# COLUMN COUNT VALIDATION MACRO (FIX-NCOLS-VALIDATION)
# =============================================================================
def _validate_extraction_params(n_cols, sql_cols, func_name=""):
    """
    Validate extraction function parameters before processing.
    FIX BUG #15: Strict parameter validation with range checks.
    """
    # Strict n_cols validation
    if n_cols is None:
        LOG.error(f"[{func_name}] n_cols is None (must be positive integer)")
        return False
    if not isinstance(n_cols, int):
        LOG.error(f"[{func_name}] n_cols is {type(n_cols).__name__}, not int: {n_cols!r}")
        return False
    if n_cols <= 0:
        LOG.error(f"[{func_name}] n_cols is {n_cols} (must be > 0)")
        return False
    if n_cols > 1000:
        LOG.error(f"[{func_name}] n_cols is {n_cols} (exceeds max 1000)")
        return False
        
    # Validate sql_cols
    if not isinstance(sql_cols, (list, tuple)):
        LOG.error(f"[{func_name}] Invalid sql_cols: {sql_cols!r} (must be list/tuple)")
        return False
    if len(sql_cols) != n_cols:
        LOG.error(f"[{func_name}] Column count mismatch: n_cols={n_cols}, len(sql_cols)={len(sql_cols)}")
        return False
    return True

def _validate_response(fp, func_name="", allow_empty=False):
    """
    Comprehensive response object validation.
    Checks:
    1. fp object exists and is not None
    2. fp.body attribute exists
    3. fp.body is not None
    4. fp.body is bytes type (not string, int, or other)
    5. fp.body is not empty (unless allow_empty=True)
    
    FIX BUG #13: Enhanced logging to ensure all validation failures are visible
    """
    if fp is None:
        LOG.debug(f"[{func_name}] VALIDATION FAILED: Response object is None")
        return False
    if not hasattr(fp, 'body'):
        LOG.debug(f"[{func_name}] VALIDATION FAILED: Response object has no 'body' attribute")
        return False
    if fp.body is None:
        LOG.debug(f"[{func_name}] VALIDATION FAILED: Response body is None")
        return False
    if not isinstance(fp.body, bytes):
        LOG.debug(f"[{func_name}] VALIDATION FAILED: Response body is not bytes (got {type(fp.body).__name__})")
        return False
    if not allow_empty and len(_extract_body_safe(fp)) == 0:
        LOG.debug(f"[{func_name}] VALIDATION FAILED: Response body is empty")
        return False
    return True

def _validate_response_attributes(fp, func_name="", attributes=None):
    """
    FIX BUG #174: Validate response object has required attributes before access.
    This prevents AttributeError when accessing .status_code, .body_hash, etc.
    
    Args:
        fp: Response object to validate
        func_name: Function name for logging
        attributes: List of attributes to check (default: ['body', 'status_code', 'body_hash'])
    
    Returns:
        True if all attributes exist and are accessible, False otherwise
    """
    if fp is None:
        LOG.debug(f"[{func_name}] Response validation failed: fp is None")
        return False
    
    if attributes is None:
        attributes = ['body', 'status_code', 'body_hash']
    
    for attr in attributes:
        if not hasattr(fp, attr):
            LOG.debug(f"[{func_name}] Response missing attribute: {attr}")
            return False
    
    return True

def _safe_decode_body(fp, encoding='utf-8', errors='replace', func_name=""):
    """
    Safely decode response body with error handling.
    Returns decoded string or empty string on error.
    Comprehensive validation: fp existence, body attribute, type (bytes), and non-empty.
    """
    try:
        # Comprehensive null and type checks
        if fp is None:
            LOG.debug(f"[{func_name}] Cannot decode: fp is None")
            return ""
        if not hasattr(fp, 'body'):
            LOG.debug(f"[{func_name}] Cannot decode: fp has no 'body' attribute")
            return ""
        if fp.body is None:
            LOG.debug(f"[{func_name}] Cannot decode: body is None")
            return ""
        if not isinstance(fp.body, bytes):
            # If already a string, return as-is
            if isinstance(fp.body, str):
                LOG.debug(f"[{func_name}] Body is string (not bytes), returning as-is")
                return fp.body
            # Try to convert other types to string
            LOG.debug(f"[{func_name}] Body is {type(fp.body).__name__}, converting to string")
            return str(fp.body)
        # fp.body is bytes — decode it (FIX BUG #11: was calling _safe_decode_body recursively)
        # BUG-FIX-3: Safe decode operation
        try:
            return _extract_body_safe(fp).decode(encoding, errors=errors)
        except (UnicodeDecodeError, AttributeError, TypeError):
            return "" # Fallback — must return, not just evaluate
    except UnicodeDecodeError as e:
        LOG.warning(f"[{func_name}] Unicode decode error ({encoding}): {e}, using replacement chars")
        try:
            # FIX BUG #12: Use _extract_body_safe instead of recursive call
            _body_bytes = _extract_body_safe(fp, func_name=func_name, encoding=encoding, errors='replace')
            # BUG-FIX-3: Safe decode operation
            try:
                return _body_bytes.decode(encoding, errors='replace') if _body_bytes else ""
            except (UnicodeDecodeError, AttributeError, TypeError):
                return "" # Fallback — must return, not just evaluate
        except Exception:
            return ""
    except Exception as e:
        LOG.error(f"[{func_name}] Decode error: {e}")
        return ""


# BUG-FIX-V42-BASELINE: Safely access baseline samples
def _safe_baseline_sample(baseline, index=0, default=None):
    """Safely access baseline sample without IndexError."""
    if not isinstance(baseline, dict):
        return default
    samples = baseline.get("samples", [])
    if not isinstance(samples, (list, tuple)) or len(samples) <= index:
        return default
    return samples[index]


# BUG-FIX-V42-ARRAY: Safely access arrays without IndexError
def _safe_array_access(arr, index, default=None):
    """Safely access array element without IndexError."""
    if not isinstance(arr, (list, tuple)):
        return default
    if len(arr) <= index or index < 0:
        return default
    return arr[index]



def _extract_body_safe(fp, func_name="", encoding='utf-8', errors='replace') -> bytes:
    """
    Safely extract response body as bytes.
    Returns bytes or empty bytes on error.
    BUG #1 FIX: Every response must be validated before use.
    """
    try:
        if fp is None:
            LOG.debug(f"[{func_name}] Cannot extract body: fp is None")
            return b""
        if not hasattr(fp, 'body'):
            LOG.debug(f"[{func_name}] Cannot extract body: fp has no 'body' attribute")
            return b""
        if fp.body is None:
            LOG.debug(f"[{func_name}] Cannot extract body: body is None")
            return b""
        if isinstance(fp.body, bytes):
            return fp.body
        elif isinstance(fp.body, str):
            return fp.body.encode(encoding, errors=errors)
        else:
            return str(fp.body).encode(encoding, errors=errors)
    except Exception as e:
        LOG.debug(f"[{func_name}] Error extracting body: {e}")
        return b""


def _validate_fp_has_body_safe(fp, func_name="", allow_empty=False):
    """
    COMPREHENSIVE fp.body VALIDATION - FIX-R2
    Validates fp object is safe for .body access before any extraction.
    Returns (is_valid, body_bytes) tuple.
    Root cause of BUG-1: Many extraction functions accessed fp.body without these checks.
    """
    if fp is None:
        LOG.debug(f"[{func_name}] fp is None")
        return False, b""
    if not hasattr(fp, 'body'):
        LOG.debug(f"[{func_name}] fp has no body attribute")
        return False, b""
    if fp.body is None:
        LOG.debug(f"[{func_name}] fp.body is None")
        return False, b""
    if not isinstance(fp.body, bytes):
        LOG.debug(f"[{func_name}] fp.body is not bytes, got {type(fp.body).__name__}")
        return False, b""
    if not allow_empty and len(_extract_body_safe(fp)) == 0:
        LOG.debug(f"[{func_name}] fp.body is empty")
        return False, b""
    return True, fp.body

def _normalise_response_safe(fp, func_name="", default=None):
    """
    Safely normalize response body using ResponseNormaliser.
    Performs comprehensive validation before normalization.
    
    FIX-BUG-SAFE-NORMALISE: Wrapper to prevent AttributeError on unvalidated responses.
    All ResponseNormaliser.normalise(_extract_body_safe(fp)) if _validate_response(fp, allow_empty=True) else b"" calls should use this instead.
    """
    try:
        # Comprehensive validation
        if fp is None:
            LOG.debug(f"[{func_name}] Cannot normalize: fp is None")
            return default if default is not None else b""
        if not hasattr(fp, 'body'):
            LOG.debug(f"[{func_name}] Cannot normalize: fp has no 'body' attribute")
            return default if default is not None else b""
        if fp.body is None:
            LOG.debug(f"[{func_name}] Cannot normalize: body is None")
            return default if default is not None else b""
        if not isinstance(fp.body, bytes):
            LOG.debug(f"[{func_name}] Cannot normalize: body is {type(fp.body).__name__}, not bytes")
            return default if default is not None else b""
        
        # Body is valid — normalize it
        return ResponseNormaliser.normalise(_extract_body_safe(fp)) if _validate_response(fp, allow_empty=True) else b""
    except Exception as e:
        LOG.debug(f"[{func_name}] Error normalizing response: {e}")
        return default if default is not None else b""

def _safe_get_response_text(fp, func_name="", default=""):
    """
    FIX BUG #14: Safely get response text with comprehensive validation and error handling.
    All .text accesses on response objects should use this wrapper.
    """
    try:
        if fp is None:
            return default
        if not hasattr(fp, 'text'):
            # Try to decode body instead
            return _safe_decode_body(fp, func_name=func_name)
        if fp.text is None:
            return default
        if isinstance(fp.text, str):
            return fp.text
        if isinstance(fp.text, bytes):
            try:
                return fp.text.decode('utf-8', errors='replace')
            except (UnicodeDecodeError, AttributeError, TypeError):
                return default
        return str(fp.text)
    except Exception as e:
        LOG.debug(f"[{func_name}] Error getting response text: {e}")
        return default

