# ─────────────────────────────────────────────────────────────────────────────
# SAFE JSON PARSING (BUG FIX #3)
# ─────────────────────────────────────────────────────────────────────────────
def _safe_json_loads(data, default=None):
    """
    Safely parse JSON from bytes/string.
    Handles None, invalid UTF-8, malformed JSON gracefully.
    Returns default (empty dict by default) on any error.
    """
    try:
        if data is None:
            return default if default is not None else {}
        if isinstance(data, bytes):
            # BUG-FIX-3: Safe decode operation
            try:
                data = data.decode('utf-8', errors='replace')
            except (UnicodeDecodeError, AttributeError, TypeError):
                data = "" # Fallback — assign empty str so isinstance(data, str) check passes safely
        if not isinstance(data, str):
            return default if default is not None else {}
        return json.loads(data)
    except (json.JSONDecodeError, TypeError, ValueError, AttributeError):
        return default if default is not None else {}




# ─────────────────────────────────────────────────────────────────────────────
# EXTRACTION CONTEXT NORMALIZATION (BUG FIX #4)
# ─────────────────────────────────────────────────────────────────────────────
def _safe_normalize_extraction_context(value, default_if_none=None, context_type="prefix"):
    """
    FIX-R5: COMPREHENSIVE EXTRACTION CONTEXT NORMALIZATION
    Root cause: BUG-3 - inconsistent handling of None vs '' vs string
    
    Normalizes extraction prefix/suffix values:
    - None: not detected, use default (return default_if_none)
    - '': numeric context confirmed, preserve empty string
    - non-empty str: detected value, use as-is
    
    Returns normalized string suitable for SQL context building.
    """
    if value is None:
        return default_if_none if default_if_none is not None else ''
    if isinstance(value, str):
        return value
    if isinstance(value, bytes):
        try:
            return value.decode('utf-8', errors='replace')
        except Exception:
            return default_if_none if default_if_none is not None else ''
    return default_if_none if default_if_none is not None else ''


def _normalize_extraction_context(val, default_val, context_type="prefix"):
    """
    Normalize extraction context prefix/suffix with proper 3-case handling.
    
    Cases:
    1. None = "not detected" → return default
    2. '' (empty string) = "legitimately detected" → preserve exactly
    3. Non-empty string = "detected value" → use as-is
    
    CRITICAL: Empty string is DIFFERENT from None in SQL context:
      - prefix=None: unknown context, try all
      - prefix='': numeric context confirmed (no quotes)
      - prefix="'": string context confirmed
      
      - suffix=None: default suffix (-- -) not set
      - suffix='': no suffix needed (legitimately detected)
      - suffix='-- -': SQL comment suffix
    """
    if val is None:
        return default_val  # Case 1: not detected, use default
    
    if not isinstance(val, str):
        LOG.debug(f"[context-normalize] Invalid {context_type} type: {type(val).__name__}, using default")
        return default_val  # Invalid type, use default
    
    if val == '':
        # Case 2: empty string - PRESERVE EXACTLY (represents numeric context)
        # Do NOT convert to default or None
        return ''
    
    # Case 3: non-empty string - use detected value as-is
    return val

