# 
# PERFORMANCE OPTIMIZATION: ASYNC FILE I/O
# 

try:
    import aiofiles
    AIOFILES_AVAILABLE = True
except ImportError:
    AIOFILES_AVAILABLE = False
    import warnings
    warnings.warn("aiofiles not installed - using synchronous I/O (slower)")


async def async_read_file(filepath: str, mode: str = 'r', encoding: str = 'utf-8'):
    """
    Read file asynchronously for better performance.
    
    Falls back to sync I/O if aiofiles not installed.
    
    Args:
        filepath: Path to file
        mode: Read mode ('r', 'rb')
        encoding: Text encoding (default: utf-8)
    
    Returns:
        File contents
    """
    if AIOFILES_AVAILABLE:
        try:
            if 'b' in mode:
                async with aiofiles.open(filepath, mode) as f:
                    return await f.read()
            else:
                async with aiofiles.open(filepath, mode, encoding=encoding) as f:
                    return await f.read()
        except Exception as e:
            LOG.warning(f"Async file read failed, falling back to sync: {e}")
    
    # Fallback to sync I/O
    with open(filepath, mode, encoding=encoding if 'b' not in mode else None) as f:
        return f.read()


async def async_write_file(filepath: str, content: str, mode: str = 'w', encoding: str = 'utf-8'):
    """
    Write file asynchronously for better performance.
    
    Falls back to sync I/O if aiofiles not installed.
    
    Args:
        filepath: Path to file
        content: Content to write
        mode: Write mode ('w', 'wb', 'a')
        encoding: Text encoding (default: utf-8)
    """
    if AIOFILES_AVAILABLE:
        try:
            if 'b' in mode:
                async with aiofiles.open(filepath, mode) as f:
                    await f.write(content)
            else:
                async with aiofiles.open(filepath, mode, encoding=encoding) as f:
                    await f.write(content)
            return
        except Exception:
            pass
    # Fallback to sync I/O
    with open(filepath, mode, encoding=encoding if 'b' not in mode else None) as f:
        f.write(content)


