async def _apply_request_delay(config, rate_limiter=None, use_rate_limiting=False):
    """
    Apply mandatory delay before ALL requests to prevent CPU spike.
    
    CRITICAL: This ensures delays are ALWAYS applied, not just when rate 
    limiting is enabled. Without this, requests fire as fast as possible
    causing 100% CPU usage.
    
    Args:
        config: Configuration object with delay attribute
        rate_limiter: Optional rate limiter for adaptive delays
        use_rate_limiting: Whether to use adaptive rate limiting
    """
    # ALWAYS apply base delay from config (minimum 0.1s to prevent CPU spike)
    # BUG-REQ9-NONE-CONFIG FIX: config may be None when called from standalone helpers;
    # handle gracefully with a safe default of 0.1s.
    try:
        _cfg_delay = float(getattr(config, 'delay', 0.1)) if config is not None else 0.1
    except (TypeError, ValueError):
        _cfg_delay = 0.1
    # BUG-FIX-A5 (updated): Respect explicit delay=0 from user in targeted mode.
    # BUG-CPU-FAST-MODE-FIX (Req 9): fast_mode previously set floor to 0.0ms, allowing
    # event-loop starvation at sub-millisecond RTTs (loopback/LAN targets).  With 0ms
    # floor and RTT <1ms, the scan fires thousands of probes/second pinning CPU at 100%.
    # Fix: fast_mode floor raised from 0ms → 10ms.  At 10ms: 100 req/s maximum on
    # loopback, CPU remains <50%.  asyncio.sleep(0.01) still yields to other coroutines.
    # Users who truly need unrestricted throughput can set delay=0 AND fast_mode=False
    # and accept the CPU cost (documented trade-off).
    _fast_mode = bool(getattr(config, 'fast_mode', False)) if config else False
    base_delay = max(_cfg_delay, 0.01 if _fast_mode else 0.05)
    if base_delay > 0:
        await asyncio.sleep(base_delay)
    else:
        await asyncio.sleep(0)  # always yield even with delay=0
    
    # Additional adaptive delay if rate limiting enabled
    if use_rate_limiting and rate_limiter:
        try:
            adaptive_delay = rate_limiter.get_delay()
            # Only sleep additional time if adaptive delay is higher
            if adaptive_delay > base_delay:
                await asyncio.sleep(adaptive_delay - base_delay)
        except Exception:
            pass  # Ignore rate limiter errors, base delay already applied

