# Global adaptive extraction engine instance
_ADAPTIVE_ENGINE = None
_ADAPTIVE_MODE_ENABLED = False  # Set via --adaptive flag

def init_adaptive_extraction(mutation_engine=None, max_bypasses=5, waf_threshold=0.30):
    """
    Initialize the adaptive extraction system.
    
    Call this after imports and before detection.
    
    Args:
        mutation_engine: PayloadMutationEngine instance (optional)
        max_bypasses: Maximum number of bypasses to detect (default: 5)
        waf_threshold: WAF blocking detection threshold (default: 0.30)
    
    Returns:
        AdaptiveExtractionEngine instance
    """
    global _ADAPTIVE_ENGINE
    
    if _ADAPTIVE_ENGINE is None:
        _ADAPTIVE_ENGINE = AdaptiveExtractionEngine(
            mutation_engine=mutation_engine,
            max_bypasses=max_bypasses,
            waf_threshold=waf_threshold
        )
        LOG.info(f"[V21] Adaptive extraction initialized (max_bypasses={max_bypasses}, threshold={waf_threshold})")
    
    return _ADAPTIVE_ENGINE


def get_adaptive_engine():
    """Get the global adaptive extraction engine instance."""
    return _ADAPTIVE_ENGINE


def is_adaptive_mode_enabled():
    """Check if adaptive extraction mode is enabled."""
    return _ADAPTIVE_MODE_ENABLED and _ADAPTIVE_ENGINE is not None


