async def standard_detect_injection(target: str, config: "Config",
                                     method: str = "GET") -> Optional["DetectionResult"]:
    """
    Standard injection detection entry-point.
    Wraps TechniqueCascadeEngine.try_all() for a single target URL.
    Used by detect_with_bypass_pool() as the base detector.
    """
    from urllib.parse import urlparse, parse_qs
    try:
        parsed = urlparse(target)
        params = parse_qs(parsed.query)
        if not params:
            LOG.debug("[standard_detect_injection] No query params in target URL")
            return None

        # Use first parameter found
        param_name = next(iter(params))
        original_val = params[param_name][0]

        # Build a minimal HTTP engine
        _eng = HTTPEngine(config)
        _baseline = await build_baseline(_eng, config, method, target, None,
                                          "form", param_name, original_val, [])
        _cascade = TechniqueCascadeEngine(config, known_dbms=None, tamper_chain=[])
        result = await _cascade.try_all(
            _eng, target, method, None, "form",
            param_name, original_val, _baseline)
        if result:
            return result.detection
        return None
    except Exception as _sdi_e:
        LOG.debug("[standard_detect_injection] Error: %s", _sdi_e)
        return None


async def detect_with_bypass_pool(target, config):
    """
    Enhanced detection that finds MULTIPLE bypasses for the pool.
    
    This is a wrapper around the standard detection that:
    1. Finds the first working bypass (standard detection)
    2. Continues searching for additional bypasses
    3. Adds all bypasses to the adaptive engine pool
    
    Returns:
        Standard detection result + bypass pool populated

    BUG-A6-FIX [Req 2/4]: Added _SCAN_STOPPED guard before each probe attempt
    so this wrapper stops issuing bypass variants as soon as injection is confirmed.
    Cross-category dispatch (Req 2) is handled inside standard_detect_injection which
    calls the full detect_boolean/detect_error/detect_time/detect_stacked pipeline,
    each of which calls _run_cross_category_probes for all 10 CPDB categories.
    """
    # BUG-A6-FIX [Req 4]: Guard — another surface may have confirmed injection already
    if _SCAN_STOPPED[0]:
        return None
    engine = get_adaptive_engine()
    
    if not engine or not is_adaptive_mode_enabled():
        # Fall back to standard detection
        return await standard_detect_injection(target, config)
    
    LOG.info("[V21] Running enhanced detection with bypass pool...")
    
    # BUG-A6-FIX [Req 4]: Check again right before the main detect call
    if _SCAN_STOPPED[0]:
        return None
    # First, run standard detection to get first bypass
    result = await standard_detect_injection(target, config)
    
    if result and result.payload:
        # Add first bypass to pool
        engine.add_bypass(
            payload=result.payload,
            seed=0,
            confidence=result.confidence
        )
        LOG.info(f"[V21] Added bypass #1 to pool: {result.payload[:50]}...")
        
        # Try to find additional bypasses (simplified version)
        max_bypasses = engine.bypass_pool.max_size
        attempts = 0
        max_attempts = 50
        
        while len(engine.bypass_pool.bypasses) < max_bypasses and attempts < max_attempts:
            # BUG-A6-FIX [Req 4]: Stop issuing bypass variants once injection confirmed
            if _SCAN_STOPPED[0]:
                break
            # Generate variant with different seed
            variant = generate_bypass_variant(result.payload, seed=attempts)
            
            # Test variant (simplified - would need real testing)
            # if await test_bypass(variant, target):
            #     engine.add_bypass(variant, attempts, 0.8)
            
            attempts += 1
        
        LOG.info(f"[V21] Detection complete: {len(engine.bypass_pool.bypasses)} bypasses in pool")
    
    return result


