async def extract_with_adaptive_mode(standard_extract_func, *args, **kwargs):
    """
    Wrapper for extraction functions that adds adaptive capabilities.
    
    Usage:
        # Instead of:
        result = await extract_database_name(...)
        
        # Use:
        result = await extract_with_adaptive_mode(extract_database_name, ...)
    
    Args:
        standard_extract_func: The standard extraction function
        *args, **kwargs: Arguments to pass to extraction function
    
    Returns:
        Extraction result with adaptive recovery
    """
    engine = get_adaptive_engine()
    
    if not engine or not is_adaptive_mode_enabled():
        # No adaptive mode, use standard extraction
        return await standard_extract_func(*args, **kwargs)
    
    # Define wrapper that extracts and monitors
    async def monitored_extract(**extract_kwargs):
        try:
            # Call standard extraction
            result = await standard_extract_func(**extract_kwargs)
            
            # Monitor response (would need actual response object)
            # pattern = engine.waf_detector.monitor_response(
            #     status_code=response.status_code,
            #     response_text=response.text
            # )
            
            return {
                'result': result,
                'status_code': 200,  # Placeholder
                'response_text': ''   # Placeholder
            }
        except Exception as e:
            LOG.warning(f"[V21] Extraction error: {e}")
            return {
                'result': None,
                'status_code': 500,
                'response_text': str(e)
            }
    
    # Use adaptive extraction
    try:
        wrapped_result = await engine.extract_with_adaptation(
            monitored_extract,
            **kwargs
        )
        return wrapped_result.get('result') if wrapped_result else None
    except Exception as e:
        LOG.error(f"[V21] Adaptive extraction failed: {e}")
        # Fall back to standard
        return await standard_extract_func(*args, **kwargs)


