# TECHNIQUE-3 (Randomized Binary Search Pivots) — helper function.
# Replaces the deterministic midpoint calculation `(lo + hi) // 2` used in
# ALL character-extraction binary search loops.  The deterministic pivot produces
# a perfectly predictable sequence of SQL comparison values (e.g. ASCII range
# [32,126] always probes 79→55/103→43/67/91/115→...) that L3/L4 WAF ML models
# recognise as a canonical binary-search SQLi oracle fingerprint after 3-5 probes.
#
# This helper adds bounded random jitter to the pivot:
#   jitter_range = max(1, (hi - lo) // 8)   ← at most 12.5% of current span
#   mid = clamp((lo + hi) // 2 + randint(-jitter_range, jitter_range), lo, hi-1)
#
# The bound guarantees O(log N) convergence:
#   - worst-case extra bit = log2(1 + 0.25) ≈ 0.32 bits per level
#   - for 7-bit ASCII (128 values): at most 7.32 probes vs. 7 (4.5% overhead)
#   - no infinite loop possible because mid ∈ [lo, hi-1] always
#
# All extraction binary search loops that call this helper instead of
# `(lo + hi) // 2` directly gain Technique-3 coverage automatically.
def _randomized_mid(lo: int, hi: int) -> int:
    """Return a jittered binary-search pivot in [lo, hi-1] (TECHNIQUE-3).

    Args:
        lo: current lower bound (inclusive)
        hi: current upper bound (exclusive, i.e. standard Python range convention)

    Returns:
        Pivot value guaranteed in [lo, hi-1].  Equivalent to (lo+hi)//2 when
        hi - lo <= 4 (very narrow ranges where jitter is pointless and costly).
    """
    _span = hi - lo
    if _span <= 4:
        return (lo + hi) // 2  # no jitter on near-converged ranges
    _max_jitter = max(1, _span // 8)
    _jitter = random.randint(-_max_jitter, _max_jitter)
    return max(lo, min(hi - 1, (lo + hi) // 2 + _jitter))


def _randomized_mid_upper(lo: int, hi: int) -> int:
    """Ceiling-form jittered pivot for upper-bound binary search (length extraction).

    Standard upper-bound binary search uses (lo+hi+1)//2 to avoid infinite loop
    when lo+1==hi.  This variant adds the same bounded jitter.

    Args:
        lo: current lower bound (inclusive)
        hi: current upper bound (inclusive — note difference from _randomized_mid)

    Returns:
        Pivot value guaranteed in [lo+1, hi].
    """
    _span = hi - lo
    if _span <= 4:
        return (lo + hi + 1) // 2
    _max_jitter = max(1, _span // 8)
    _jitter = random.randint(-_max_jitter, _max_jitter)
    return max(lo + 1, min(hi, (lo + hi + 1) // 2 + _jitter))


@lru_cache(maxsize=500)
def get_compiled_regex(pattern: str, flags: int = 0):
    """
    Cache compiled regex patterns for performance.
    
    Performance gain: ~20% faster regex operations
    Memory cost: ~50KB for 500 cached patterns
    
    Args:
        pattern: Regex pattern string
        flags: re.IGNORECASE, re.MULTILINE, etc.
    
    Returns:
        Compiled regex pattern
    """
    return _re.compile(pattern, flags)


