@lru_cache(maxsize=2000)
def get_cached_payload(dbms: str, technique: str, level: int, risk: int = 1) -> str:
    """
    Return the first certified payload for a given DBMS/technique/level combination.

    BUG-STUB-FIX (Req 1): The previous implementation was a broken stub that returned
    the lookup key string f"{dbms}:{technique}:{level}:{risk}" instead of an actual
    SQL injection payload.  Any caller receiving that string would send a completely
    useless probe (the literal text "mysql:boolean:1:1" injected into a parameter) and
    never detect a vulnerability.

    Fix: delegate to get_dbms_payloads() — the authoritative CERTIFIED_PAYLOAD_DATABASE
    dispatch — and return the first payload at the requested level.  Falls back to a
    safe empty string (not a fake key) when no certified payload exists for the
    combination, so callers that check truthiness correctly skip the probe.

    The risk parameter (1-3) is honoured as a level multiplier: risk=1 → level as-is,
    risk=2 → level+1 (capped at 5), risk=3 → level 5 (all payloads).
    """
    # BUG-STUB-FIX: risk multiplier mapped to level adjustment
    _effective_level = min(5, level + (risk - 1))
    try:
        _payloads = get_dbms_payloads(dbms, technique, _effective_level)
        if _payloads:
            return _payloads[0]
    except Exception:
        pass
    # CERTIFIED-only: return empty string (not a fake key) so callers skip
    return ""


# Clear payload cache (call when switching targets)
def clear_payload_cache():
    """Clear cached payloads (useful when switching targets)"""
    get_cached_payload.cache_clear()


class _ColorFmt(logging.Formatter):
    C = {logging.DEBUG:"\033[90m", logging.INFO:"\033[32m",
         logging.WARNING:"\033[33m", logging.ERROR:"\033[31m",
         logging.CRITICAL:"\033[1;31m"}
    P = {logging.DEBUG:"[*]", logging.INFO:"[+]",
         logging.WARNING:"[!]", logging.ERROR:"[-]", logging.CRITICAL:"[!!]"}
    R = "\033[0m"
    def __init__(self, color=True): super().__init__(); self.color=color
    def format(self, r):
        p = self.P.get(r.levelno,"[?]"); m = r.getMessage()
        return f"{self.C.get(r.levelno,'') if self.color else ''}{p}{self.R if self.color else ''} {m}"

def _setup_logger(v=0, no_color=False):
    log = logging.getLogger("sqr")
    log.setLevel(logging.DEBUG)
    h = logging.StreamHandler(sys.stdout)
    h.setFormatter(_ColorFmt(not no_color))
    h.setLevel(logging.DEBUG if v >= 2 else logging.INFO)
    log.handlers.clear(); log.addHandler(h)
    return log

LOG = logging.getLogger("sqr")


# ===== SAFE STRING METHOD WRAPPERS =====
# These wrappers prevent crashes from calling string methods on None/non-string types

def _safe_upper(s, default=""):
    """Safely call .upper() on potentially None string."""
    if s is None:
        return default
    if isinstance(s, bytes):
        try:
            return s.decode('utf-8', errors='replace').upper()
        except Exception:
            return default
    if isinstance(s, str):
        return s.upper()
    return str(s).upper() if s else default

def _safe_lower(s, default=""):
    """Safely call .lower() on potentially None string."""
    if s is None:
        return default
    if isinstance(s, bytes):
        try:
            return s.decode('utf-8', errors='replace').lower()
        except Exception:
            return default
    if isinstance(s, str):
        return s.lower()
    return str(s).lower() if s else default

def _safe_strip(s, default=""):
    """Safely call .strip() on potentially None string."""
    if s is None:
        return default
    if isinstance(s, bytes):
        try:
            return s.decode('utf-8', errors='replace').strip()
        except Exception:
            return default
    if isinstance(s, str):
        return s.strip()
    return str(s).strip() if s else default

def _safe_index(container, index, default=None):
    """Safely access container[index] without IndexError."""
    if container is None:
        return default
    try:
        if isinstance(container, (list, tuple)):
            if 0 <= index < len(container):
                return container[index]
        elif isinstance(container, dict):
            return container.get(index, default)
        else:
            return container[index] if index < len(container) else default
    except (IndexError, KeyError, TypeError):
        return default
    return default

# ===== END SAFE WRAPPERS =====

# EXTRACTION FIX: Add response validation helper for detect functions
def _validate_detection_response(fp, func_name="detect", min_body_len=0):
    """
    Validate detection response object.
    Returns (is_valid: bool, body_str: str, body_bytes: bytes)
    """
    if fp is None:
        LOG.debug(f"[{func_name}] Response is None")
        return False, "", b""
    
    if not hasattr(fp, 'body') and not hasattr(fp, 'text'):
        LOG.debug(f"[{func_name}] Response has no body/text attribute")
        return False, "", b""
    
    try:
        # Get body as bytes
        if hasattr(fp, 'body') and isinstance(fp.body, bytes):
            body_bytes = fp.body
        elif hasattr(fp, 'text'):
            body_bytes = fp.text.encode('utf-8', errors='replace') if isinstance(fp.text, str) else fp.text
        else:
            return False, "", b""
        
        # Decode to string
        body_str = body_bytes.decode('utf-8', errors='replace') if isinstance(body_bytes, bytes) else str(body_bytes)
        
        # Check minimum length
        if len(body_bytes) < min_body_len:
            LOG.debug(f"[{func_name}] Response body too small: {len(body_bytes)} < {min_body_len}")
            return False, body_str, body_bytes
        
        return True, body_str, body_bytes
    
    except Exception as e:
        LOG.debug(f"[{func_name}] Response validation failed: {e}")
        return False, "", b""


def _validate_extraction_result(result, result_type="string", func_name="extract"):
    """
    Validate extraction result data quality.
    Ensures result is not garbage or corrupted.
    """
    if result is None:
        return None  # None is acceptable - means extraction failed cleanly
    
    # Type validation
    if result_type == "string":
        if not isinstance(result, str):
            LOG.warning(f"[{func_name}] Extraction returned non-string: {type(result)}")
            try:
                result = str(result)
            except Exception:
                return None
        
        # Content sanity check
        if len(result) > 0 and all(ord(c) < 32 for c in result[:10]):
            LOG.warning(f"[{func_name}] Extraction contains mostly control characters")
            return None
        
        # SQL injection detection - result should not contain raw payloads
        if any(payload in (result or "").lower() for payload in ['union', 'select', 'from', 'where']):
            # Might be legitimate SQL data extraction, so just log it
            LOG.debug(f"[{func_name}] Extraction contains SQL keywords (expected for data extraction)")
        
        return result
    
    elif result_type == "int":
        if not isinstance(result, int):
            try:
                return int(result)
            except (ValueError, TypeError):
                return None
        return result
    
    elif result_type == "bytes":
        if not isinstance(result, bytes):
            try:
                result = result.encode('utf-8', errors='replace') if isinstance(result, str) else bytes(result)
            except Exception:
                return None
        return result
    
    return result









