# 429 RATE LIMITING UTILITIES
# 

def smart_backoff(retry_count: int, base_delay: float = 30.0, max_delay: float = 900.0) -> float:
    """
    Exponential backoff with jitter and cap for 429 rate limiting.
    
    Returns delay in seconds based on retry count:
    - Retry 1: ~30s
    - Retry 2: ~60s  
    - Retry 3: ~120s
    - Retry 4: ~240s
    - Retry 5: ~480s
    - Retry 6+: ~900s (15 min) - capped
    
    Args:
        retry_count: Current retry attempt number (1-indexed)
        base_delay: Base delay in seconds (default 30s)
        max_delay: Maximum delay cap in seconds (default 900s = 15min)
    
    Returns:
        Delay in seconds with jitter applied
    """
    # Exponential: base * (2 ^ (retry_count - 1))
    # For retry_count=1: 30 * (2^0) = 30
    # For retry_count=2: 30 * (2^1) = 60
    # For retry_count=3: 30 * (2^2) = 120
    # Cap exponent at 5 to prevent extreme growth
    delay = base_delay * (2 ** min(retry_count - 1, 5))
    
    # Cap at max_delay
    delay = min(delay, max_delay)
    
    # Add jitter (20%) to prevent thundering herd
    jitter = delay * random.uniform(-0.2, 0.2)
    
    return delay + jitter


def parse_retry_after(response) -> Optional[int]:
    """
    Parse Retry-After header from HTTP 429 response.
    
    Supports two formats:
    1. Delay-seconds: "120" (wait 120 seconds)
    2. HTTP-date: "Wed, 21 Oct 2015 07:28:00 GMT" (rare)
    
    Args:
        response: HTTP response object with headers attribute
    
    Returns:
        Number of seconds to wait, or None if header missing/invalid
    """
    if not hasattr(response, 'headers'):
        return None
    
    retry_after = response.headers.get('Retry-After') or response.headers.get('retry-after')
    if not retry_after:
        return None
    
    # Format 1: Seconds (most common)
    if retry_after.isdigit():
        return int(retry_after)
    
    # Format 2: HTTP-date (rare but valid)
    try:
        from email.utils import parsedate_to_datetime
        retry_date = parsedate_to_datetime(retry_after)
        from datetime import timezone as _tz
        wait_seconds = (retry_date - retry_date.__class__.now(_tz.utc)).total_seconds()
        return max(0, int(wait_seconds))
    except:
        return None


async def retry_on_429(func, *args, phase: str = "unknown", max_hours: int = 24, **kwargs):
    """
    Universal 429 retry wrapper for any async function.
    
    Retries the given function with smart exponential backoff on 429 errors.
    Never gives up (within max_hours limit).
    
    Args:
        func: Async function to retry
        *args: Positional arguments for func
        phase: Name of scan phase (for logging)
        max_hours: Maximum hours to retry (default 24)
        **kwargs: Keyword arguments for func
    
    Returns:
        Result of func when successful
    
    Raises:
        Exception if max_hours exceeded or non-429 error
    """
    retry_count = 0
    start_time = time.time()
    
    while True:
        retry_count += 1
        
        # Safety: don't retry forever
        if (time.time() - start_time) > (max_hours * 3600):
            raise TimeoutError(
                f"{phase} exceeded {max_hours} hour timeout (429 retries: {retry_count})")
        
        try:
            result = await func(*args, **kwargs)
            # Success!
            if retry_count > 1 and _RATE_429_MONITOR:
                # Record successful recovery
                recovery_time = time.time() - start_time
                _RATE_429_MONITOR.record_recovery(recovery_time)
            return result
        
        except Exception as e:
            # Check if this is a 429-related error
            # Look for 429 in the exception or check response status
            is_429 = False
            
            # Check if exception message contains 429
            if '429' in str(e):
                is_429 = True
            
            # Check if exception has a response attribute with status_code
            if hasattr(e, 'response') and hasattr(e.response, 'status_code'):
                if e.response.status_code == 429:
                    is_429 = True
            
            # If not 429, re-raise immediately
            if not is_429:
                raise
            
            # It's a 429 - record and retry
            if _RATE_429_MONITOR:
                _RATE_429_MONITOR.record_429(phase=phase)
            
            backoff = smart_backoff(retry_count)
            print(f"[!] [{phase}] 429 detected, retrying after {backoff:.0f}s "
                  f"(retry {retry_count})", flush=True)
            
            # Log progress every 10 retries
            if retry_count % 10 == 0:
                elapsed = time.time() - start_time
                print(f"    [429 Stats] Phase: {phase}, Retries: {retry_count}, "
                      f"Elapsed: {elapsed/60:.1f}min", flush=True)
            
            await asyncio.sleep(backoff)
            continue  # Retry


class Rate429Monitor:
    """
    Monitor and track 429 rate limiting statistics across all scan phases.
    Provides insights into rate limiting patterns for optimization.
    """
    def __init__(self):
        self.total_429s = 0
        self.total_requests = 0
        # MEMORY LEAK FIX: Use bounded deque instead of unbounded list
        self.rate_429_times = collections.deque(maxlen=100)  # Last 100 timestamps only
        self.recovery_times = collections.deque(maxlen=100)  # Last 100 recovery times only
        self.start_time = time.time()
        self.phase_429s = {}  # 429s per phase (baseline, detection, injection, extraction)
    
    def record_429(self, phase: str = "unknown"):
        """Record a 429 error occurrence"""
        self.total_429s += 1
        self.total_requests += 1
        self.rate_429_times.append(time.time())
        self.phase_429s[phase] = self.phase_429s.get(phase, 0) + 1
    
    def record_request(self, is_429: bool = False, phase: str = "unknown"):
        """Record a request attempt"""
        self.total_requests += 1
        if is_429:
            self.record_429(phase)
    
    def record_recovery(self, duration: float):
        """Record successful recovery from 429 after 'duration' seconds"""
        self.recovery_times.append(duration)
    
    def get_stats(self) -> dict:
        """Get current 429 statistics"""
        elapsed = time.time() - self.start_time
        return {
            'total_429s': self.total_429s,
            'total_requests': self.total_requests,
            '429_rate': self.total_429s / max(1, self.total_requests),
            'avg_recovery_time': sum(self.recovery_times) / max(1, len(self.recovery_times)),
            'elapsed_time': elapsed,
            '429s_per_hour': self.total_429s / max(0.001, elapsed / 3600),
            'phase_breakdown': dict(self.phase_429s)
        }
    
    def print_summary(self):
        """Print 429 statistics summary"""
        stats = self.get_stats()
        print(f"\n{'='*80}")
        print("[429 STATISTICS SUMMARY]")
        print(f"{'='*80}")
        print(f"  Total 429 errors: {stats['total_429s']}")
        print(f"  Total requests: {stats['total_requests']}")
        print(f"  429 rate: {stats['429_rate']:.2%}")
        print(f"  Avg recovery time: {stats['avg_recovery_time']:.1f}s")
        print(f"  429s per hour: {stats['429s_per_hour']:.1f}")
        if stats['phase_breakdown']:
            print("\n  Breakdown by phase:")
            for phase, count in stats['phase_breakdown'].items():
                print(f"    {phase}: {count} 429s")
        print(f"{'='*80}\n")


class ProgressTracker:
    """
    Save scan progress to disk for resumption after 429 interruption.
    Enables recovery from persistent rate limiting without losing work.
    """
    def __init__(self, target_url: str, enabled: bool = True):
        self.enabled = enabled
        if not enabled:
            self.progress = self._empty_progress()
            return
        
        # Create progress file name from URL hash
        url_hash = hashlib.md5(target_url.encode()).hexdigest()[:16]
        self.progress_file = f".sqlreaper_progress_{url_hash}.json"
        self.progress = self.load_progress()
    
    def _empty_progress(self) -> dict:
        """Return empty progress structure"""
        return {
            'completed_params': [],
            'current_param': None,
            'extraction_position': 0,
            'extraction_data': '',
            '429_count': 0,
            'last_update': time.time(),
            'scan_phase': 'init'
        }
    
    def load_progress(self) -> dict:
        """Load progress from disk or create new"""
        if os.path.exists(self.progress_file):
            try:
                # TODO: Replace with aiofiles for async I/O
                with open(self.progress_file, 'r') as f:
                    saved = json.load(f)
                    print(f"[+] [Progress] Resuming from saved progress: {len(saved.get('completed_params', []))} params done, "
                          f"{saved.get('429_count', 0)} 429s encountered")
                    return saved
            except:
                pass  # TODO: Add logging for debugging

        return self._empty_progress()
    
    def save_progress(self):
        """Save current progress to disk"""
        if not self.enabled:
            return
        try:
            self.progress['last_update'] = time.time()
            # TODO: Replace with aiofiles for async I/O
            with open(self.progress_file, 'w') as f:
                json.dump(self.progress, f, indent=2)
        except:
            pass  # Fail silently on save errors
    
    def mark_param_complete(self, param: str):
        """Mark parameter as fully scanned"""
        if param not in self.progress['completed_params']:
            self.progress['completed_params'].append(param)
        self.save_progress()
    
    def update_extraction(self, position: int, data: str):
        """Update extraction progress"""
        self.progress['extraction_position'] = position
        self.progress['extraction_data'] = data
        self.save_progress()
    
    def record_429(self):
        """Record 429 occurrence"""
        self.progress['429_count'] += 1
        self.save_progress()
    
    def should_skip_param(self, param: str) -> bool:
        """Check if parameter was already completed"""
        return param in self.progress['completed_params']
    
    def get_extraction_resume_point(self) -> tuple:
        """Get extraction resume position and partial data"""
        return (
            self.progress['extraction_position'],
            self.progress['extraction_data']
        )
    
    def set_phase(self, phase: str):
        """Update current scan phase"""
        self.progress['scan_phase'] = phase
        self.save_progress()
    
    def clear(self):
        """Clear progress file after successful completion"""
        if self.enabled and os.path.exists(self.progress_file):
            try:
                os.remove(self.progress_file)
            except:
                pass  # TODO: Add logging for debugging



# Global 429 monitor instance (initialized in main)
_RATE_429_MONITOR: Optional[Rate429Monitor] = None

