_GLOBAL_WASSERSTEIN: Optional[Any] = None

# 
# ADVANCED OPTIMIZATION CLASSES
# 

def is_garbage_data(extracted_string: str) -> bool:
    """
    Detect if extracted data is garbage/invalid.
    
    8-Layer comprehensive validation (FIX BUG #5):
    1. Empty string check
    2. All-same-character check (e.g., "aaaaaaa")
    3. Non-printable character ratio (>20%)
    4. Binary data detection (null bytes >10%)
    5. Repeated pattern detection (e.g., "ababab")
    6. Common error/debug strings (NULL, 0x00, error messages)
    7. Extremely short for bulk extraction (suspicious <1 char)
    8. Extremely long random-looking data (>10K chars of gibberish)
    
    Args:
        extracted_string: String to validate
    
    Returns:
        True if data appears to be garbage
    """
    # BUG-5 FIX: empty string "" is a valid extraction result (empty column value).
    # Only None is truly missing/garbage.
    if extracted_string is None:
        return True
    if not extracted_string:
        return False  # "" is valid — empty column, not garbage
    if not extracted_string.strip():
        return True  # Whitespace-only is garbage

    # Layer 1: All same character (e.g., "aaaaaaa")
    if len(set(extracted_string)) == 1 and len(extracted_string) > 3:
        return True

    # Layer 2: Too many non-printable characters (>20%)
    # BUG-4 FIX: only count true C0 control chars (0-31 excl. tab/CR/LF) and DEL (127)
    # as non-printable.  Extended ASCII (128-255) can appear in real data (accented
    # characters, Latin-1 encoded values) and matches validate_char's acceptance range.
    non_printable = sum(
        1 for c in extracted_string
        if (ord(c) < 32 and c not in '\t\n\r') or ord(c) == 127
    )
    if len(extracted_string) > 0 and non_printable / len(extracted_string) > 0.2:
        return True
    
    # Layer 3: Binary data (too many null bytes >10%)
    null_bytes = extracted_string.count('\x00')
    if len(extracted_string) > 0 and null_bytes > len(extracted_string) * 0.1:
        return True
    
    # Layer 4: Repeated pattern detection (e.g., "ababababab")
    # BUG-6 FIX: require >= 3 complete repetitions AND the string must fully equal
    # the repeated pattern (not just start with it).  The old "startswith" check
    # flagged "abcabc" (only 2 reps) and legitimate data like "go go go" as garbage.
    if len(extracted_string) > 10:
        for pattern_len in [2, 3, 4, 5]:
            if pattern_len >= len(extracted_string):
                break
            pattern = extracted_string[:pattern_len]
            reps = len(extracted_string) // pattern_len
            if reps >= 3 and extracted_string == pattern * reps:
                return True
    
    # Layer 5: Common error/debug/NULL strings (garbage from failed extraction)
    garbage_strings = [
        'null', 'NULL', 'none', 'NONE', 'undefined', 'UNDEFINED',
        '0x00', '\\x00', '\\0', b'\x00'.decode('utf-8', errors='ignore'),
        'error', 'Error', 'ERROR', 'exception', 'Exception',
        'failed', 'Failed', 'FAILED', 'crash', 'Crash', 'CRASH',
        'timeout', 'Timeout', 'TIMEOUT',
        '<?php', '<script', 'function', 'var ', 'if ', 'for ',  # Code snippets
    ]
    s_lower = extracted_string.lower()
    if any(g.lower() in s_lower for g in garbage_strings):
        # Only flag as garbage if that's the ENTIRE string (not substring)
        if extracted_string in garbage_strings or s_lower in [g.lower() for g in garbage_strings]:
            return True
    
    # Layer 6: Suspicious entropy for bulk extractions
    # If we have very long random-looking data (>5000 chars) with high entropy,
    # it might be binary or corrupted
    if len(extracted_string) > 5000:
        unique_chars = len(set(extracted_string))
        entropy = unique_chars / len(extracted_string)
        if entropy > 0.9:  # Nearly every character is unique (very high entropy = garbage)
            return True
    
    # Layer 7: Check for control characters density (excluding common whitespace)
    control_chars = sum(1 for c in extracted_string if ord(c) < 32 and c not in '\n\r\t')
    if len(extracted_string) > 0 and control_chars / len(extracted_string) > 0.1:
        return True
    
    return False


def validate_char(char: str) -> bool:
    """
    Validate that a character is printable and valid.
    
    Args:
        char: Single character to validate
    
    Returns:
        True if character is valid
    """
    if not char or len(char) != 1:
        return False
    
    ascii_val = ord(char)
    
    # Valid ASCII range (printable + common special chars)
    # 32-126: Standard printable ASCII
    # 9, 10, 13: Tab, newline, carriage return
    if ascii_val in (9, 10, 13) or (32 <= ascii_val <= 126):
        return True
    
    # Extended ASCII (128-255) - allow but flag as unusual
    if 128 <= ascii_val <= 255:
        return True
    
    return False


class AdaptiveRPMLearner:
    """
    Learn server's actual RPM limit through binary search.
    
    Automatically finds optimal speed without manual tuning.
    Adapts to server changes in real-time.
    """
    def __init__(self, initial_rpm: int = 120):
        self.min_safe_rpm = 10      # Known safe lower bound
        self.max_safe_rpm = 500     # Upper bound to explore
        self.current_rpm = initial_rpm
        self.consecutive_429s = 0
        self.consecutive_oks = 0
        self.learning_mode = True
        self.confidence = 0.0
        self.total_requests = 0
    
    def on_429(self):
        """Server rate limited us - RPM too high"""
        self.consecutive_429s += 1
        self.consecutive_oks = 0
        
        # BUG-9 FIX: react to the FIRST 429, not just the second.
        # A single isolated 429 is already a signal that the current RPM is too high;
        # waiting for a second one means we've already sent too many blocked requests.
        if self.consecutive_429s >= 1:
            # Too fast - reduce max bound
            self.max_safe_rpm = self.current_rpm
            self.current_rpm = (self.min_safe_rpm + self.max_safe_rpm) // 2

            print(f"[RPM Learner] Too fast! Reducing: {self.max_safe_rpm}  {self.current_rpm} RPM",
                  flush=True)

            # Reset confidence
            self.confidence = max(0.0, self.confidence - 0.2)
    
    def on_success(self):
        """Request succeeded - can try faster?"""
        self.consecutive_oks += 1
        self.consecutive_429s = 0
        self.total_requests += 1
        
        if self.consecutive_oks >= 100 and self.learning_mode:
            # Very stable - try going faster
            old_rpm = self.current_rpm
            self.min_safe_rpm = self.current_rpm
            new_rpm = (self.min_safe_rpm + self.max_safe_rpm) // 2
            
            if new_rpm - self.current_rpm < 5:
                # Converged - stop learning
                self.learning_mode = False
                self.confidence = 1.0
                print(f"[RPM Learner]  Optimal RPM found: {self.current_rpm}", flush=True)
            else:
                self.current_rpm = new_rpm
                self.consecutive_oks = 0  # Reset counter
                print(f"[RPM Learner] Stable! Trying faster: {old_rpm}  {self.current_rpm} RPM", 
                      flush=True)
                self.confidence = min(1.0, self.confidence + 0.1)
    
    def get_current_rpm(self) -> int:
        return self.current_rpm
    
    def get_confidence(self) -> float:
        """How confident we are in current RPM (0.0 to 1.0)"""
        return self.confidence


class Predictive429Detector:
    """
    Detect warning signs that 429 is imminent.
    
    Monitors:
    - Response time increases (server stressed)
    - 5xx errors (server overloaded)
    - Response time variance (server unstable)
    
    Slows down BEFORE getting 429.
    """
    def __init__(self):
        self.response_times = collections.deque(maxlen=20)
        self.status_codes = collections.deque(maxlen=50)
        self.baseline_response_time = None
        self.warning_triggered = False
    
    def record_request(self, status_code: int, response_time_ms: float):
        """Record request for analysis"""
        self.response_times.append(response_time_ms)
        self.status_codes.append(status_code)
        
        # Establish baseline (first 10 requests)
        if len(self.response_times) == 10 and self.baseline_response_time is None:
            self.baseline_response_time = statistics.mean(self.response_times)
    
    def is_429_imminent(self) -> bool:
        """
        Detect if 429 is about to happen.
        
        Returns:
            True if warning signs detected
        """
        if len(self.response_times) < 10:
            return False
        
        # Warning 1: Response time increased >50% from baseline
        if self.baseline_response_time and self.baseline_response_time > 0:
            current_avg = statistics.mean(list(self.response_times)[-10:])
            if current_avg > self.baseline_response_time * 1.5:
                if not self.warning_triggered:
                    print("[Predictive]   Response time increasing "
                          f"({self.baseline_response_time:.0f}ms  {current_avg:.0f}ms)", 
                          flush=True)
                    self.warning_triggered = True
                return True
        
        # Warning 2: Recent 5xx errors (last 10 requests)
        recent_5xx = sum(1 for sc in list(self.status_codes)[-10:] if 500 <= sc < 600)
        if recent_5xx >= 2:
            if not self.warning_triggered:
                print(f"[Predictive]   Server errors detected ({recent_5xx} 5xx in last 10)", 
                      flush=True)
                self.warning_triggered = True
            return True
        
        # Warning 3: High variance in response times (server unstable)
        if len(self.response_times) >= 20:
            try:
                variance = statistics.variance(self.response_times)
                if variance > 1000:  # >1 second variance
                    if not self.warning_triggered:
                        print("[Predictive]   High response time variance detected", flush=True)
                        self.warning_triggered = True
                    return True
            except:
                pass  # TODO: Add logging for debugging

        
        # Reset warning flag if conditions clear
        if self.warning_triggered:
            self.warning_triggered = False
        
        return False


class PerSurfaceRateTracker:
    """
    Track rate limiting separately for each surface.
    
    Allows some surfaces (e.g., headers) to scan faster
    while others (e.g., params) slow down.
    """
    def __init__(self, global_rpm: int = 120):
        self.global_rpm = global_rpm
        self.surface_multipliers = {}  # Surface  speed multiplier
        self.surface_429_counts = {}   # Surface  429 count
        self.surface_request_counts = {}  # Surface  total requests
    
    def record_429(self, surface: str):
        """Record 429 for specific surface"""
        self.surface_429_counts[surface] = self.surface_429_counts.get(surface, 0) + 1
        
        # Reduce multiplier for this surface
        current_mult = self.surface_multipliers.get(surface, 1.0)
        self.surface_multipliers[surface] = max(0.3, current_mult * 0.7)
        
        print(f"[Surface Tracker] {surface} rate limited, "
              f"reducing to {self.surface_multipliers[surface]:.0%} speed", flush=True)
    
    def record_success(self, surface: str):
        """Record successful request for surface"""
        self.surface_request_counts[surface] = self.surface_request_counts.get(surface, 0) + 1
        
        # Gradually increase multiplier
        current_mult = self.surface_multipliers.get(surface, 1.0)
        self.surface_multipliers[surface] = min(1.0, current_mult + 0.02)
    
    def get_rpm_for_surface(self, surface: str) -> int:
        """Get RPM limit for specific surface"""
        multiplier = self.surface_multipliers.get(surface, 1.0)
        return max(10, int(self.global_rpm * multiplier))
    
    def update_global_rpm(self, new_rpm: int):
        """Update global RPM (called when adaptive learner adjusts)"""
        self.global_rpm = new_rpm


class SmartBackoffCalculator:
    """
    Calculate backoff based on 429 pattern and frequency.
    
    Adapts backoff duration based on:
    - Retry count
    - 429 frequency
    - 429 acceleration (getting worse?)
    """
    def __init__(self):
        self.recent_429s = collections.deque(maxlen=10)
        self.total_429s = 0
    
    def record_429(self, timestamp: float):
        """Record a 429 occurrence"""
        self.recent_429s.append(timestamp)
        self.total_429s += 1
    
    def calculate_backoff(self, retry_count: int) -> float:
        """
        Calculate backoff duration based on pattern.
        
        Args:
            retry_count: Current retry attempt number
        
        Returns:
            Backoff duration in seconds
        """
        # Base exponential backoff
        base = 30 * (2 ** min(retry_count - 1, 5))
        
        # Frequency multiplier
        if len(self.recent_429s) >= 5:
            # Calculate 429 rate (429s per minute)
            time_span = self.recent_429s[-1] - self.recent_429s[0]
            if time_span > 0:
                rate_per_min = len(self.recent_429s) / (time_span / 60)
                
                if rate_per_min > 10:  # Very frequent 429s
                    base *= 3
                elif rate_per_min > 5:
                    base *= 2
                elif rate_per_min > 2:
                    base *= 1.5
        
        # Acceleration detection
        if len(self.recent_429s) >= 3:
            recent_interval = self.recent_429s[-1] - self.recent_429s[-2]
            older_interval = self.recent_429s[-2] - self.recent_429s[-3]
            
            if recent_interval < older_interval * 0.5:
                # 429s accelerating
                base *= 2
        
        # Cap at 15 minutes
        return min(base, 900)


class MultiWindowRateAnalyzer:
    """
    Analyze rate limiting across multiple time windows.
    
    Windows: 10s (short-term), 60s (standard), 300s (long-term)
    Detects burst patterns and sustained high rates.
    """
    def __init__(self):
        self.windows = {
            '10s': collections.deque(maxlen=1000),
            '60s': collections.deque(maxlen=5000),
            '300s': collections.deque(maxlen=20000),
        }
    
    def record_request(self, timestamp: float):
        """Record request in all windows"""
        for window in self.windows.values():
            window.append(timestamp)
    
    def get_rate_in_window(self, window_name: str, now: float) -> float:
        """Get requests per second in given window"""
        window_seconds = int(window_name.rstrip('s'))
        window = self.windows[window_name]
        
        if not window:
            return 0.0
        
        # Count requests in window
        cutoff = now - window_seconds
        recent_requests = sum(1 for t in window if t >= cutoff)
        
        return recent_requests / window_seconds if window_seconds > 0 else 0.0
    
    def should_throttle(self, now: float) -> bool:
        """Decide if we should throttle based on multi-window analysis"""
        # Short-term spike detection
        short_rate = self.get_rate_in_window('10s', now)
        if short_rate > 5:  # >5 req/s = 300 RPM
            return True
        
        # Medium-term check
        medium_rate = self.get_rate_in_window('60s', now) * 60
        if medium_rate > 120:
            return True
        
        # Long-term sustainability
        long_rate = self.get_rate_in_window('300s', now) * 60
        if long_rate > 100:
            return True
        
        return False


# 
# ADVANCED OPTIMIZATION: WAF RATE LIMIT PREDICTOR
# 

class RateLimitPredictor:
    """
    ENHANCED WAF Rate Limit Predictor with multi-signal detection.
    
    Features:
    - Exponential + binary search calibration
    - Multi-signal detection (status codes, response times, headers, body patterns)
    - Adaptive rate adjustment with PID controller
    - Per-technique rate limits
    - Predictive modeling
    - Graceful degradation
    
    Prevents IP bans by discovering and staying below rate limits.
    """
    
    def __init__(self, technique='B'):
        self.technique = technique
        self.calibrated = False
        
        # Rate limiting state
        self.discovered_limit = None  # Actual rate limit (req/sec)
        self.safe_rate = 1.0  # Current safe operating rate
        self.target_rate = 1.0  # Target rate to reach
        
        # Baseline measurements
        self.baseline_response_time = None
        self.response_times = collections.deque(maxlen=50)
        
        # Request tracking
        self.request_timestamps = collections.deque(maxlen=1000)
        self.blocked_requests = collections.deque(maxlen=100)
        
        # Adaptive control (PID controller)
        self.kp = 0.15  # Proportional gain (increased for faster response)
        self.ki = 0.02  # Integral gain
        self.kd = 0.08  # Derivative gain
        self.integral_error = 0
        self.last_error = 0
        
        # Success/failure streaks
        self.success_streak = 0
        self.block_streak = 0
        
        # Statistics
        self.total_requests = 0
        self.total_blocks = 0
        self.total_rate_limits = 0
        
        # Re-calibration timing
        self.last_calibration = time.time()
        self.calibration_interval = 300  # Re-calibrate every 5 minutes
        
        # Rate limit detection patterns
        self.RATE_LIMIT_STATUS_CODES = {429, 503, 509, 403}
        self.RATE_LIMIT_PATTERNS = [
            r'rate limit exceeded',
            r'too many requests',
            r'quota exceeded',
            r'throttled',
            r'please slow down',
            r'retry after \d+',
        ]
        
        LOG.info(f"[RateLimitPredictor] Initialized for technique {technique}")
    
    async def calibrate(self, send_func):
        """
        Discover rate limit through exponential + binary search.
        
        Args:
            send_func: Async function that sends a test request
        """
        LOG.info(f"[RateLimitPredictor] Starting calibration for technique {self.technique}...")
        
        # Establish baseline response time
        await self._establish_baseline(send_func)
        
        # Phase 1: Exponential search to find approximate limit
        rate = 0.5  # Start very conservative
        max_safe_rate = 0.5
        
        while rate < 100:  # Safety cap
            is_safe, avg_rt = await self._test_rate(send_func, rate, num_tests=8)
            
            if not is_safe:
                LOG.info(f"[RateLimitPredictor] Rate {rate:.1f} req/s triggers limit")
                break
            
            # Check for response time degradation
            if self.baseline_response_time and avg_rt > self.baseline_response_time * 2.5:
                LOG.info(f"[RateLimitPredictor] Response time degradation at {rate:.1f} req/s "
                        f"(baseline: {self.baseline_response_time:.3f}s, current: {avg_rt:.3f}s)")
                break
            
            LOG.info(f"[RateLimitPredictor] Rate {rate:.1f} req/s is safe "
                    f"(avg response: {avg_rt:.3f}s)")
            max_safe_rate = rate
            rate *= 1.8  # Exponential increase
        
        # Phase 2: Binary search refinement
        lower_bound = max_safe_rate
        upper_bound = rate if rate < 100 else max_safe_rate * 1.5
        
        LOG.info(f"[RateLimitPredictor] Binary search between {lower_bound:.1f} and {upper_bound:.1f} req/s")
        
        iterations = 0
        while upper_bound - lower_bound > 0.3 and iterations < 8:
            test_rate = (lower_bound + upper_bound) / 2
            
            is_safe, avg_rt = await self._test_rate(send_func, test_rate, num_tests=6)
            
            degraded = (self.baseline_response_time and 
                       avg_rt > self.baseline_response_time * 2.0)
            
            if is_safe and not degraded:
                lower_bound = test_rate
                LOG.info(f"[RateLimitPredictor] Rate {test_rate:.1f} req/s is safe")
            else:
                upper_bound = test_rate
                LOG.info(f"[RateLimitPredictor] Rate {test_rate:.1f} req/s is too high")
            
            iterations += 1
        
        # Set discovered limits
        self.discovered_limit = upper_bound
        self.safe_rate = lower_bound * 0.88  # Operate at 88% for safety margin
        self.target_rate = self.safe_rate
        
        self.calibrated = True
        self.last_calibration = time.time()
        
        LOG.info("[RateLimitPredictor] ✓ Calibration complete:")
        LOG.info(f"  Discovered limit: ~{self.discovered_limit:.2f} req/s")
        LOG.info(f"  Safe operating rate: {self.safe_rate:.2f} req/s")
        LOG.info(f"  Delay between requests: {1.0/self.safe_rate:.3f}s")
    
    async def _establish_baseline(self, send_func):
        """Establish baseline response time with clean requests"""
        LOG.info("[RateLimitPredictor] Establishing baseline response time...")
        
        times = []
        for _ in range(5):
            start = time.time()
            try:
                await send_func()
                elapsed = time.time() - start
                times.append(elapsed)
            except:
                pass
            await asyncio.sleep(0.3)
        
        if times:
            self.baseline_response_time = sum(times) / len(times)
            LOG.info(f"[RateLimitPredictor] Baseline response time: {self.baseline_response_time:.3f}s")
        else:
            self.baseline_response_time = 0.15  # Default
    
    async def _test_rate(self, send_func, rate, num_tests=10):
        """
        Test if a specific rate triggers rate limiting.
        
        Returns:
            (is_safe, avg_response_time)
        """
        delay = 1.0 / rate
        response_times = []
        errors = 0
        rate_limit_hits = 0
        
        for i in range(num_tests):
            start = time.time()
            
            try:
                response = await send_func()
                elapsed = time.time() - start
                response_times.append(elapsed)
                
                # Check for rate limit signals
                if self._is_rate_limited(response):
                    rate_limit_hits += 1
                    errors += 1
                
            except Exception as e:
                errors += 1
                response_times.append(5.0)  # Penalize failures
            
            # Wait before next request
            if i < num_tests - 1:
                await asyncio.sleep(max(0.01, delay))
        
        avg_rt = sum(response_times) / len(response_times) if response_times else 5.0
        error_rate = errors / num_tests
        
        # Safe if: low error rate AND low rate limit hits
        is_safe = error_rate < 0.15 and rate_limit_hits < 2
        
        return is_safe, avg_rt
    
    def _is_rate_limited(self, response):
        """
        Multi-signal detection of rate limiting.
        
        Checks:
        - HTTP status codes (429, 503, 509, 403)
        - Response headers (X-RateLimit-*, Retry-After)
        - Response body patterns
        """
        # Signal 1: Status code
        if hasattr(response, 'status_code'):
            if _get_safe_status_code(response) in self.RATE_LIMIT_STATUS_CODES:
                return True
        
        # Signal 2: Headers
        if hasattr(response, 'headers'):
            headers_lower = {k.lower(): v for k, v in response.headers.items()}
            
            # Check for rate limit headers
            if 'x-ratelimit-remaining' in headers_lower:
                try:
                    remaining = int(headers_lower['x-ratelimit-remaining'])
                    if remaining == 0:
                        return True
                except:
                    pass
            
            # Check for retry-after header
            if 'retry-after' in headers_lower:
                return True
        
        # Signal 3: Body patterns
        if hasattr(response, 'body'):
            try:
                body = _safe_decode_body(response).lower()  # _safe_decode_body already returns str
                for pattern in self.RATE_LIMIT_PATTERNS:
                    if re.search(pattern, body, re.IGNORECASE):
                        return True
            except:
                pass
        
        return False
    
    def record_request(self, response, response_time):
        """
        Record request and adapt rate based on feedback.
        
        Args:
            response: HTTP response object
            response_time: Time taken for request in seconds
        """
        now = time.time()
        self.request_timestamps.append(now)
        self.response_times.append(response_time)
        self.total_requests += 1
        
        # Check if rate limited
        is_blocked = self._is_rate_limited(response)
        
        if is_blocked:
            self.blocked_requests.append(now)
            self.block_streak += 1
            self.success_streak = 0
            self.total_blocks += 1
            self.total_rate_limits += 1
            
            LOG.warning("[RateLimitPredictor] Rate limit detected! "
                       f"(streak: {self.block_streak}, total: {self.total_rate_limits})")
            
            # Immediate aggressive reduction
            if self.block_streak >= 3:
                reduction_factor = 0.4  # 60% reduction
                old_rate = self.safe_rate
                self.safe_rate *= reduction_factor
                self.target_rate = self.safe_rate
                
                LOG.warning("[RateLimitPredictor] Emergency rate reduction: "
                           f"{old_rate:.2f} → {self.safe_rate:.2f} req/s")
        else:
            self.success_streak += 1
            self.block_streak = 0
            
            # Check for response time degradation
            if self.baseline_response_time:
                if response_time > self.baseline_response_time * 2.5:
                    # Slow responses = approaching limit
                    old_rate = self.target_rate
                    self.target_rate *= 0.85
                    
                    LOG.info("[RateLimitPredictor] Response time degradation detected, "
                            f"reducing target: {old_rate:.2f} → {self.target_rate:.2f} req/s")
            
            # Cautious rate increase after sustained success
            if self.success_streak >= 25 and self.safe_rate < 50:
                old_rate = self.target_rate
                self.target_rate *= 1.08  # 8% increase
                
                LOG.info("[RateLimitPredictor] Sustained success, "
                        f"increasing target: {old_rate:.2f} → {self.target_rate:.2f} req/s")
                self.success_streak = 0
        
        # PID controller for smooth rate adjustment
        error = self.target_rate - self.safe_rate
        self.integral_error += error
        derivative = error - self.last_error
        
        adjustment = (self.kp * error + 
                     self.ki * self.integral_error + 
                     self.kd * derivative)
        
        self.safe_rate += adjustment
        self.last_error = error
        
        # Bounds: 0.1 to 100 req/s
        self.safe_rate = max(0.1, min(100, self.safe_rate))
        
        # Periodic re-calibration check
        if now - self.last_calibration > self.calibration_interval:
            if self.total_rate_limits > 5:
                LOG.info("[RateLimitPredictor] Frequent rate limits detected, "
                        "re-calibration recommended")
    
    def get_delay(self):
        """Get current delay between requests in seconds"""
        if not self.calibrated or self.safe_rate <= 0:
            return 1.0  # Conservative default
        
        calculated_delay = 1.0 / self.safe_rate
        # CAP: Prevent excessive delays that cause confirmation timeout
        # Max 5s to ensure confirmation (2 requests) completes within 45s timeout
        return min(calculated_delay, 5.0)
    
    def get_stats(self):
        """Get current statistics"""
        return {
            'calibrated': self.calibrated,
            'discovered_limit': self.discovered_limit,
            'safe_rate': self.safe_rate,
            'target_rate': self.target_rate,
            'total_requests': self.total_requests,
            'total_blocks': self.total_blocks,
            'total_rate_limits': self.total_rate_limits,
            'success_rate': ((self.total_requests - self.total_blocks) / self.total_requests * 100) 
                           if self.total_requests > 0 else 0,
            'current_delay': self.get_delay(),
        }


# 
# ADVANCED OPTIMIZATION: PAYLOAD DNA SHUFFLING
# 

class PayloadDNAShuffle:
    """
    ENHANCED Payload DNA Shuffling - Complete semantic restructuring.
    
    Features:
    - Boolean (B): 20+ semantic templates per DBMS
    - Error (E): 10+ error-triggering variants per DBMS
    - Time (T): 10+ timing mechanism variants per DBMS
    - Union (U): NULL representation variants
    - Adaptive template selection (tracks blocked structures)
    - Nested boolean expressions (up to 2 levels deep)
    - DBMS-specific optimization
    
    Defeats ML WAFs by constantly changing payload structure.
    """
    
    def __init__(self, dbms='Generic', technique='B'):
        self.dbms = dbms
        self.technique = technique  # B, E, T, or U
        
        # Template usage tracking
        self.template_usage = {}
        self.blocked_templates = set()
        self.successful_templates = set()
        
        # Statistics
        self.total_generated = 0
        self.total_blocked = 0
        self.total_successful = 0
        
        # Build templates based on technique
        if technique == 'B':
            self.TRUE_TEMPLATES = self._build_true_templates()
            self.FALSE_TEMPLATES = self._build_false_templates()
        elif technique == 'E':
            self.ERROR_TEMPLATES = self._build_error_templates()
        elif technique == 'T':
            self.TIMING_TEMPLATES = self._build_timing_templates()
        elif technique == 'U':
            self.UNION_TEMPLATES = self._build_union_templates()
        
        LOG.info(f"[PayloadDNAShuffle] Initialized for {dbms}, technique {technique}")
        if technique == 'B':
            LOG.info(f"  TRUE templates: {len(self.TRUE_TEMPLATES.get(dbms, self.TRUE_TEMPLATES.get('Generic', [])))}")
        elif technique == 'E':
            LOG.info(f"  ERROR templates: {len(self.ERROR_TEMPLATES.get(dbms, self.ERROR_TEMPLATES.get('Generic', [])))}")
        elif technique == 'T':
            LOG.info(f"  TIMING templates: {len(self.TIMING_TEMPLATES.get(dbms, self.TIMING_TEMPLATES.get('Generic', [])))}")
        elif technique == 'U':
            LOG.info(f"  UNION templates: {len(self.UNION_TEMPLATES.get(dbms, self.UNION_TEMPLATES.get('Generic', [])))}")
    
