class ScanSession:
    VERSION = "19.0"
    def __init__(self, config: Config):
        self.config = config
        self.created_at = time.time()
        self.session_id = hashlib.sha256(
            ((config.url or "")+(config.data or "")+config.method+str(time.time())).encode()
        ).hexdigest()[:16]  # 16-char hex from SHA-256 (not MD5)
        self.vulnerabilities: Dict[str,Dict] = {}
        self.data: Dict[str,Any] = {
            "banner":None,"current_db":None,"current_user":None,
            "hostname":None,"dbs":[],"tables":{},"columns":{},
            "dump":{},"users":[],"privileges":{}
        }
        self.waf_info: Dict[str, Any] = {}
        self.dbms: Optional[str] = None
        self.dbms_version: Optional[str] = None
        self.requests_sent: int = 0
        self.requests_failed: int = 0
        self.start_time: float = time.time()
        self.active_tampers: List[str] = []
        self.baselines: Dict[str,Dict] = {}
        self.session_file = Path(config.output_dir)/f"{self.session_id}.session"

    def save(self):
        self.session_file.parent.mkdir(parents=True,exist_ok=True)
        # Sanitise config dict  convert any non-serialisable values to str
        def _safe_dict(d):
            out = {}
            for k, v in d.items():
                try:
                    json.dumps(v)
                    out[k] = v
                except (TypeError, ValueError):
                    out[k] = str(v)
            return out
        state = {
            "version":self.VERSION,"session_id":self.session_id,
            "created_at":self.created_at,"config":_safe_dict(self.config.__dict__),
            "vulnerabilities":self.vulnerabilities,"data":self.data,
            "waf_info":self.waf_info,"dbms":self.dbms,
            "dbms_version":self.dbms_version,
            "requests_sent":self.requests_sent,
            "active_tampers":self.active_tampers,
        }
        tmp = str(self.session_file)+".tmp"
        # TODO: Replace with aiofiles for async I/O
        with open(tmp,"w") as f: json.dump(state,f,indent=2,default=str)
        os.replace(tmp,self.session_file)
        LOG.debug(f"Session saved  {self.session_file}")

    def load(self, path: str):
        # TODO: Replace with aiofiles for async I/O
        with open(path) as f: state=json.load(f)
        # FIX v16: validate session version to prevent silent data corruption
        # when a session from an older scanner version is resumed.
        # BUG-3 FIX: state.get("version", "0.0") returns None when JSON has
        # "version": null — dict.get() only uses the default when key is absent.
        # Use `or "0.0"` to coerce None → "0.0" so int(split()[0]) never raises.
        saved_ver = state.get("version") or "0.0"
        cur_major = int(self.VERSION.split(".")[0])
        saved_major = int(str(saved_ver).split(".")[0])
        if saved_major < cur_major - 1:
            LOG.warning(
                f"Session version {saved_ver!r} may be incompatible with "
                f"current {self.VERSION}  some fields may be missing. "
                "Use --flush to start fresh if detection is unreliable.")
        self.session_id=state["session_id"]; self.created_at=state.get("created_at", self.created_at)
        self.vulnerabilities=state.get("vulnerabilities",{})
        self.data=state.get("data",self.data)
        # FIX-A: state.get("waf_info", {}) returns None when JSON has "waf_info": null
        # because dict.get() only falls back to default when the key is absent, not null.
        # Use `or {}` to coerce None  empty dict so all downstream .get() calls are safe.
        self.waf_info = state.get("waf_info") or {}
        self.dbms=state.get("dbms"); self.dbms_version=state.get("dbms_version")
        self.requests_sent=state.get("requests_sent",0)
        self.active_tampers=state.get("active_tampers",[])
        cfg_dict = state.get("config", {})
        if cfg_dict:
            self.config=Config.from_dict(cfg_dict)

    def record_vuln(self, param,technique,payload,dbms="",notes=""):
        param = param.replace("__path_seg__","path-injection").replace("__path__","path-injection")
        self.vulnerabilities[param]={
            "technique":technique,"payload":payload,"dbms":dbms,
            "notes":notes,"found_at":time.time()
        }
        # PATCH-ISSUE5: Block second parallel extraction
        if _EXTRACTION_ACTIVE[0] or _EXTRACTION_DONE[0]:
            LOG.info(f"[PATCH-5] Second injection point param={param!r} technique={technique} "
                     f"dbms={dbms} — logging only, extraction already active/done (Req 5).")
            return
        LOG.info(f"Vulnerability confirmed  param={param.replace('__path__', 'path-injection')!r} technique={technique} dbms={dbms}")

    def already_confirmed(self, param): return param in self.vulnerabilities
    def elapsed(self): return time.time()-self.start_time
    def summary(self):
        return {"session_id":self.session_id,"elapsed_sec":round(self.elapsed(),2),
                "requests_sent":self.requests_sent,"requests_failed":self.requests_failed,
                "dbms":self.dbms,
                # FIX-B: waf_info can be None when loaded from a session file that stored
                # null.  Use (... or {}) so .get() never throws AttributeError.
                "waf":(self.waf_info or {}).get("name","unknown"),
                "vulnerabilities":len(self.vulnerabilities),
                "params":list(self.vulnerabilities.keys())}


