class JsonBodyFlattener:
    @staticmethod
    def flatten_endpoint(url, method, json_body, source="api"):
        try:
            obj = json.loads(json_body)
        except (json.JSONDecodeError, TypeError):
            return []
        flat = ParameterParser.flatten_json(obj)
        return [{"param": jp, "original": str(v), "data_fmt": "json",
                 "data": json_body, "url": url, "method": method,
                 "source": source} for jp, v in flat.items()]

    @staticmethod
    def detect_json_body(data):
        if not data:
            return False
        s = data.strip()
        return (s.startswith("{") and s.endswith("}")) or (s.startswith("[") and s.endswith("]"))

# BUG-GRAPHQL-DUPE-FIX: Second GraphQLInjector definition removed — merged into
# the single definition above (~line 7570). All methods (get_targeted_probes,
# build_graphql_payloads, detect_graphql, extract_inline_args, build_injection_points,
