class APIEndpointDiscovery:
    SWAGGER_PATHS = ["/swagger.json", "/api-docs", "/openapi.json", "/api/swagger.json", "/v1/api-docs", "/v2/api-docs", "/docs/openapi.json", "/swagger/v1/swagger.json"]
    _JS_PATS = [
        re.compile(r'fetch\s*\(\s*[\'"]([^\'"]+)[\'"]'),
        re.compile(r'axios\.(?:get|post|put|delete|patch)\s*\(\s*[\'"]([^\'"]+)[\'"]'),
        re.compile(r'[\'"](/api/[a-zA-Z0-9/_\-]+)[\'"]'),
        re.compile(r'[\'"](/v[0-9]+/[a-zA-Z0-9/_\-]+)[\'"]'),
    ]

    @staticmethod
    async def discover_swagger(engine, base_url):
        parsed = urlparse(base_url)
        base = f"{parsed.scheme}://{parsed.netloc}"
        for path in APIEndpointDiscovery.SWAGGER_PATHS:
            try:
                fp = await asyncio.wait_for(engine.send("GET", base + path), timeout=8)
                if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) != 200: continue
                body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction") if isinstance(fp.body, bytes) else str(fp.body)
                if '"paths"' not in body and '"openapi"' not in body: continue
                spec = json.loads(body)
                eps = APIEndpointDiscovery._parse_openapi(spec, base)
                if eps:
                    print(f"[+] [API] Swagger found at {path}: {len(eps)} endpoints", flush=True)
                    return eps
            except Exception: continue
        return []

    @staticmethod
    def _parse_openapi(spec, base_url):
        endpoints = []
        for path, methods in spec.get("paths", {}).items():
            for method, details in methods.items():
                if method.upper() not in ("GET","POST","PUT","DELETE","PATCH"): continue
                full_url = base_url.rstrip("/") + path
                for p in details.get("parameters", []):
                    pn, pi = p.get("name",""), p.get("in","query")
                    pe = p.get("example", p.get("default", "test"))
                    if pi in ("query","header"):
                        endpoints.append({"param": pn, "original": str(pe), "data_fmt": "header" if pi=="header" else "form", "data": None, "url": full_url, "method": method.upper(), "source": f"openapi_{pi}"})
                rb = details.get("requestBody", {}).get("content", {}).get("application/json", {}).get("schema", {})
                if rb:
                    ex = APIEndpointDiscovery._schema_to_example(rb, spec)
                    if ex and isinstance(ex, dict):
                        js = json.dumps(ex)
                        for jp, v in ParameterParser.flatten_json(ex).items():
                            endpoints.append({"param": jp, "original": str(v), "data_fmt": "json", "data": js, "url": full_url, "method": method.upper(), "source": "openapi_body"})
        return endpoints

    @staticmethod
    def _schema_to_example(schema, root, _depth=0):
        if _depth > 10:  # Prevent infinite recursion on circular $ref
            return "test"
        if "$ref" in schema:
            parts = schema["$ref"].lstrip("#/").split("/")
            r = root
            for p in parts: r = r.get(p, {})
            return APIEndpointDiscovery._schema_to_example(r, root, _depth + 1)
        t = schema.get("type", "object")
        if t == "object": return {k: APIEndpointDiscovery._schema_to_example(v, root, _depth + 1) for k, v in schema.get("properties", {}).items()}
        elif t == "array": return [APIEndpointDiscovery._schema_to_example(schema.get("items", {}), root, _depth + 1)]
        elif t == "string": return schema.get("example", "test")
        elif t == "integer": return schema.get("example", 1)
        elif t == "number": return schema.get("example", 1.0)
        elif t == "boolean": return schema.get("example", True)
        return "test"

    @staticmethod
    def extract_js_endpoints(js_content, base_url):
        parsed = urlparse(base_url)
        base = f"{parsed.scheme}://{parsed.netloc}"
        eps, seen = [], set()
        for pat in APIEndpointDiscovery._JS_PATS:
            for m in pat.finditer(js_content):
                ap = m.group(1)
                if ap in seen: continue
                seen.add(ap)
                full = ap if ap.startswith("http") else base + ap if ap.startswith("/") else None
                if not full or any(full.endswith(e) for e in [".js",".css",".png",".jpg",".svg",".woff"]): continue
                ctx = js_content[max(0,m.start()-50):m.start()].lower()
                meth = "POST" if "post" in ctx else "PUT" if "put" in ctx else "GET"
                eps.append({"param": "__api_probe__", "original": "", "data_fmt": "form", "data": None, "url": full, "method": meth, "source": "js_bundle"})
        return eps

    @staticmethod
    async def discover_all(engine, base_url):
        all_eps = []
        try: all_eps.extend(await APIEndpointDiscovery.discover_swagger(engine, base_url))
        except Exception: pass
        try:
            gql_url = await GraphQLInjector.detect_graphql(engine, base_url)
            if gql_url: print(f"[+] [API] GraphQL endpoint: {gql_url}", flush=True)
        except Exception: pass
        try:
            fp = await asyncio.wait_for(engine.send("GET", base_url), timeout=10)
            body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction") if isinstance(fp.body, bytes) else str(fp.body)
            js_urls = re.findall(r'src=["\']([^"\']+\.js[^"\']*)["\']', body)
            parsed = urlparse(base_url)
            base = f"{parsed.scheme}://{parsed.netloc}"
            jc = 0
            for ju in js_urls[:15]:
                jf = base + ju if ju.startswith("/") else ju if ju.startswith("http") else base + "/" + ju
                try:
                    jfp = await asyncio.wait_for(engine.send("GET", jf), timeout=10)
                    # BUG-H1 FIX: was _safe_decode_body(fp, ...) — fp is the HTML base page,
                    # not the fetched JS bundle.  Use jfp (the JS response) instead.
                    jb = _safe_decode_body(jfp, encoding="utf-8", errors="replace", func_name="extraction") if isinstance(jfp.body, bytes) else str(jfp.body)
                    jeps = APIEndpointDiscovery.extract_js_endpoints(jb, base_url)
                    all_eps.extend(jeps); jc += len(jeps)
                except Exception: continue
            if jc: print(f"[+] [API] JS analysis: {jc} endpoints from {len(js_urls)} bundles", flush=True)
        except Exception: pass
        seen, deduped = set(), []
        for ep in all_eps:
            key = (ep["url"], ep["method"], ep["param"])
            if key not in seen: seen.add(key); deduped.append(ep)
        if deduped: print(f"[+] [API] Total: {len(deduped)} injection points", flush=True)
        return deduped


