                # Numeric safety: mid+1 operands, char_hi bounds, and BETWEEN range limits
                # are plain integer literals never touched by either obfuscation function.
                _bsearch_full = _original_clean_bsearch + payload
                _bsearch_full = apply_heavy_variation(_bsearch_full, req_num, data_fmt=data_fmt)
                _bsearch_full = _obfuscate_extraction_cond(_bsearch_full, req_num)
