def _populate_certified_db():
    """Populate CERTIFIED_PAYLOAD_DATABASE from the per-DBMS payload lists."""
    _mapping: Dict[str, Dict[str, Dict[str, list]]] = {
        # BUG-1 FIX: all 10 payload categories registered as top-level keys
        # so CERTIFIED_PAYLOAD_DATABASE.get(dbms).get(category) works for every
        # combination and get_dbms_payloads() globals() lookup is the primary path.
        "MySQL":      {
            "Boolean":   {"Standard": MYSQL_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": MYSQL_ERROR_PAYLOADS},
            "Timebased": {"Standard": MYSQL_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": MYSQL_STACKED_PAYLOADS},
            "Union":     {"Standard": MYSQL_UNION_PAYLOADS},
            "Standard":  {"Standard": MYSQL_STANDARD_PAYLOADS},
            "WAFBypass": {"Standard": MYSQL_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": MYSQL_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": MYSQL_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": MYSQL_HYBRID_PAYLOADS},
        },
        "PostgreSQL": {
            "Boolean":   {"Standard": POSTGRESQL_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": POSTGRESQL_ERROR_PAYLOADS},
            "Timebased": {"Standard": POSTGRESQL_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": POSTGRESQL_STACKED_PAYLOADS},
            "Union":     {"Standard": POSTGRESQL_UNION_PAYLOADS},
            "Standard":  {"Standard": POSTGRESQL_STANDARD_PAYLOADS},
            # FIX BUG-5: was `if globals().get("POSTGRESQL_WAFBYPASS_PAYLOADS") else {}` —
            # if the variable existed but was empty [], globals().get() returned [] (falsy)
            # → {} was used, silently dropping the WAFBypass key entirely.
            # Use globals().get(..., []) consistently so the key is always present.
            "WAFBypass": {"Standard": POSTGRESQL_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": POSTGRESQL_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": POSTGRESQL_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": POSTGRESQL_HYBRID_PAYLOADS},
        },
        "Oracle":     {
            "Boolean":   {"Standard": ORACLE_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": ORACLE_ERROR_PAYLOADS},
            "Timebased": {"Standard": ORACLE_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": ORACLE_STACKED_PAYLOADS},
            "Union":     {"Standard": ORACLE_UNION_PAYLOADS},
            "Standard":  {"Standard": ORACLE_STANDARD_PAYLOADS},
            "WAFBypass": {"Standard": ORACLE_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": ORACLE_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": ORACLE_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": ORACLE_HYBRID_PAYLOADS},
        },
        "MSSQL":      {
            "Boolean":   {"Standard": MSSQL_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": MSSQL_ERROR_PAYLOADS},
            "Timebased": {"Standard": MSSQL_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": MSSQL_STACKED_PAYLOADS},
            "Union":     {"Standard": MSSQL_UNION_PAYLOADS},
            "Standard":  {"Standard": MSSQL_STANDARD_PAYLOADS},
            "WAFBypass": {"Standard": MSSQL_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": MSSQL_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": MSSQL_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": MSSQL_HYBRID_PAYLOADS},
        },
        "SQLite":     {
            "Boolean":   {"Standard": SQLITE_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": SQLITE_ERROR_PAYLOADS},
            "Timebased": {"Standard": SQLITE_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": SQLITE_STACKED_PAYLOADS},
            "Union":     {"Standard": SQLITE_UNION_PAYLOADS},
            "Standard":  {"Standard": SQLITE_STANDARD_PAYLOADS},
            "WAFBypass": {"Standard": SQLITE_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": SQLITE_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": SQLITE_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": SQLITE_HYBRID_PAYLOADS},
        },
        # REQ-1 FIX (BUG-MARIADB-CPDB): MariaDB was missing from CERTIFIED_PAYLOAD_DATABASE.
        # DBMS_PROBE_ORDER and _build_technique_map both include "MariaDB". Without this entry,
        # CERTIFIED_PAYLOAD_DATABASE.get("MariaDB") returns {} silently, making _run_cross_category_probes
        # try MariaDB AND MySQL as separate DBMS probes — resulting in identical MySQL payloads being
        # tested twice per target (100% duplicate probing). Fix: register MariaDB using the MySQL arrays
        # directly (MariaDB is MySQL-compatible; get_dbms_payloads already normalises mariadb→MYSQL for
        # the globals() path, so referencing the same list objects is consistent and correct).
        "MariaDB":    {
            "Boolean":   {"Standard": MYSQL_BOOLEAN_PAYLOADS},
            "Error":     {"Standard": MYSQL_ERROR_PAYLOADS},
            "Timebased": {"Standard": MYSQL_TIMEBASED_PAYLOADS},
            "Stacked":   {"Standard": MYSQL_STACKED_PAYLOADS},
            "Union":     {"Standard": MYSQL_UNION_PAYLOADS},
            "Standard":  {"Standard": MYSQL_STANDARD_PAYLOADS},
            "WAFBypass": {"Standard": MYSQL_WAFBYPASS_PAYLOADS},
            "Novel":     {"Standard": MYSQL_NOVEL_PAYLOADS},
            "Exotic":    {"Standard": MYSQL_EXOTIC_PAYLOADS},
            "Hybrid":    {"Standard": MYSQL_HYBRID_PAYLOADS},
        },
    }
    CERTIFIED_PAYLOAD_DATABASE.update(_mapping)
    # BUG-NEW-2 FIX (Req 1/2): Deduplicate ORACLE_UNION_PAYLOADS in CPDB.
    # ORACLE_UNION_PAYLOADS was built with every unique payload duplicated (e.g.
    # 'UNION SELECT 1 FROM DUAL' at indices 0 AND 1, 'UNION SELECT 2 FROM DUAL'
    # at indices 2 AND 3, …).  The ~300-entry list contains only ~150 unique
    # payloads.  This halves effective level-based coverage (level=1 → cutoff=60
    # but only 30 unique probes), and causes direct callers of get_dbms_payloads()
    # (e.g. detect_union's inner loop) to send duplicate probes with zero benefit.
    # Fix: replace the Union Standard list with a deduplicated copy using
    # dict.fromkeys() which preserves insertion order while eliminating dupes.
    try:
        _ora_union_entry = CERTIFIED_PAYLOAD_DATABASE.get('Oracle', {}).get('Union', {})
        if _ora_union_entry and 'Standard' in _ora_union_entry:
            _ora_union_raw = _ora_union_entry['Standard']
            _ora_union_deduped = list(dict.fromkeys(_ora_union_raw))
            _ora_union_removed = len(_ora_union_raw) - len(_ora_union_deduped)
            if _ora_union_removed > 0:
                _ora_union_entry['Standard'] = _ora_union_deduped
                LOG.debug(
                    f"[CPDB-ORA-UNION-DEDUP] Removed {_ora_union_removed} duplicate Oracle Union "
                    f"payloads ({len(_ora_union_deduped)} unique remain of {len(_ora_union_raw)} original entries)"
                )
    except Exception as _ora_dup_err:
        LOG.debug(f"[CPDB-ORA-UNION-DEDUP] Dedup error (non-fatal): {_ora_dup_err}")
    # BUG-NEW-4 FIX (Req 1/3): Filter invalid MSSQL CASE-WHEN-WAITFOR payloads.
    # MSSQL_TIMEBASED_PAYLOADS contains ~30 payloads of the form:
    #   AND CASE WHEN 1=1 THEN WAITFOR DELAY '00:00:1' ELSE WAITFOR DELAY '00:00:0' END
    # WAITFOR DELAY is a T-SQL batch statement (like PRINT/EXEC), NOT a scalar
    # expression.  SQL Server rejects these with Msg 156 "Incorrect syntax near
    # '00:00:1'" when injected in a WHERE-clause context.  The correct MSSQL inline
    # timing form is a stacked query ('; WAITFOR DELAY ...') or a heavy-query CASE
    # expression (as _derive_timing_payloads() already uses for PCV Check B).
    # These invalid payloads waste HTTP probes, produce SQL errors that confuse
    # Check C error-fingerprint logic, and can trigger WAF/IDS alerts.
    # Filter: CASE WHEN ... THEN WAITFOR patterns (case-insensitive).
    try:
        # BUG-INLINE-IMPORT-RE-N4 FIX (LOW): removed `import re as _re_n4`.
        # _re is already imported at module level (line 10871: `import re as _re`).
        # Inline import adds unnecessary dict lookup + local binding on every call.
        # Fix: use module-level _re directly.
        # Match all invalid MSSQL WAITFOR-as-expression patterns:
        # 1. CASE WHEN ... THEN WAITFOR  — WAITFOR is a statement, not an expression value
        # 2. IF(cond, WAITFOR ..., x)    — MySQL IF() syntax; also invalid as WAITFOR is void
        # 3. IIF(... WAITFOR ...)        — IIF expects scalar values, WAITFOR returns nothing
        # 4. WHERE WAITFOR DELAY         — WAITFOR is not a boolean predicate
        # 5. SELECT WAITFOR DELAY        — WAITFOR produces no result set
        # 6. SELECT col=WAITFOR DELAY    — T-SQL column assignment of void type
        _MSSQL_CASE_WAITFOR_RE = _re.compile(
            r'(\bCASE\b.{0,200}\bTHEN\b.{0,100}\bWAITFOR\b'
            r'|\bIF\s*\([^)]*,\s*WAITFOR\s+DELAY'
            r'|\bIIF\s*\([^)]*WAITFOR\s+DELAY'
            r'|\bWHERE\s+WAITFOR\s+DELAY'
            r'|\bSELECT\s+WAITFOR\s+DELAY'
            r'|\bSELECT\s+\w+\s*=\s*WAITFOR\s+DELAY)',
            _re.IGNORECASE | _re.DOTALL
        )
        _mssql_cpdb_entry = CERTIFIED_PAYLOAD_DATABASE.get('MSSQL', {})
        for _mssql_cat_key in ('Timebased', 'Boolean', 'Standard', 'Novel', 'Hybrid',
                               'Exotic', 'WAFBypass', 'Stacked', 'Union', 'Error'):
            _mssql_cat = _mssql_cpdb_entry.get(_mssql_cat_key, {})
            if 'Standard' in _mssql_cat:
                _mssql_raw = _mssql_cat['Standard']
                _mssql_filtered = [
                    _p for _p in _mssql_raw
                    if not _MSSQL_CASE_WAITFOR_RE.search(_p)
                ]
                _mssql_removed = len(_mssql_raw) - len(_mssql_filtered)
                if _mssql_removed > 0:
                    _mssql_cat['Standard'] = _mssql_filtered
                    LOG.debug(
                        f"[CPDB-MSSQL-CASE-WAITFOR] Category '{_mssql_cat_key}': removed "
                        f"{_mssql_removed} invalid CASE-WHEN-WAITFOR payloads "
                        f"({len(_mssql_filtered)} safe payloads remain)"
                    )
    except Exception as _mssql_case_err:
        LOG.debug(f"[CPDB-MSSQL-CASE-WAITFOR] Filter error (non-fatal): {_mssql_case_err}")
    # BUG-CPU-ORA-NOVEL FIX: Filter MySQL-only functions from Oracle Novel payloads.
    # LOAD_FILE() does not exist in Oracle — these payloads always fail with
    # ORA-00904 "LOAD_FILE: invalid identifier", wasting HTTP round-trips.
    # Filter them out of CERTIFIED_PAYLOAD_DATABASE at population time.
    try:
        _ora_novel = CERTIFIED_PAYLOAD_DATABASE.get('Oracle', {}).get('Novel', {})
        if _ora_novel and 'Standard' in _ora_novel:
            _ora_novel_orig_count = len(_ora_novel['Standard'])  # BUG-3-FIX: capture BEFORE filtering
            _filtered_novel = [p for p in _ora_novel['Standard']
                               if 'LOAD_FILE' not in p.upper()]
            _ora_novel_removed = _ora_novel_orig_count - len(_filtered_novel)
            _ora_novel['Standard'] = _filtered_novel
            LOG.debug(f"[CPDB-ORA-NOVEL] Filtered {len(_filtered_novel)} Oracle Novel payloads kept "
                      f"(removed {_ora_novel_removed} LOAD_FILE entries from {_ora_novel_orig_count} total)")
    except Exception as _orn_err:
        LOG.debug(f"[CPDB-ORA-NOVEL] Filter error (non-fatal): {_orn_err}")
    # BUG-CPU-1 / BUG-PCV-2 SECOND-LAYER FIX: Filter oversized SQLite timing payloads
    # in CERTIFIED_PAYLOAD_DATABASE at population time.
    # _get_cascade_payloads() already filters via _is_sqlite_resource_bomb(), but callers
    # that read CERTIFIED_PAYLOAD_DATABASE directly (unit tests, third-party integrations,
    # or any code path that bypasses _get_cascade_payloads) would still receive the
    # unfiltered list containing RANDOMBLOB(500000000) — risking OOM on the target and
    # false positives. This second-layer filter removes them once at population time.
    try:
        _RE_BLOB_POP = _re.compile(r'RANDOMBLOB\s*\(\s*(\d+)\s*\)',
                                                _re.IGNORECASE)
        # BUG-ZEROBLOB-CPDB-FILTER FIX: Also filter ZEROBLOB. SQLITE_EXOTIC_PAYLOADS
        # contains ZEROBLOB() entries that bypass the RANDOMBLOB-only check above.
        _RE_ZBLOB_POP = _re.compile(r'ZEROBLOB\s*\(\s*(\d+)\s*\)',
                                                 _re.IGNORECASE)
        _RE_ITER_POP = _re.compile(
            r'(?:WHERE\s+\w+\s*<\s*|LIMIT\s+)(\d{7,})', _re.IGNORECASE)
        # BUG-CPU-BLOB-CAP FIX: Reduced from 50_000_000 (50MB) to 5_000_000 (5MB).
        # The original 50MB cap still allowed payloads like RANDOMBLOB(49000000) through,
        # which on local/same-machine SQLite targets allocates 49MB RAM per probe,
        # with 8 concurrent probes = 392MB per probe-cycle.  At 5MB the timing signal
        # is still clearly measurable (≥2s on typical hardware) while capping memory
        # pressure at 40MB for 8 concurrent probes.
        _MAX_BLOB_CPDB = 5_000_000
        # BUG-CPU-ITER-THRESHOLD FIX: Was > 10_000_000 (off-by-one — 10M iterations
        # exactly passed through unfiltered because the condition was STRICTLY greater).
        # Changed to >= 5_000_000 so payloads iterating exactly 5M or more are removed.
        # 5M recursive iterations take ~0.5-1s on modern hardware — a usable timing
        # signal without pinning the CPU for 20-60 seconds like 200M-iteration payloads.
        _MAX_ITER_CPDB = 5_000_000

        def _is_bomb_cpdb(payload_str):
            try:
                # BUG-CPU-ORA-CART-CPDB FIX: Also filter Oracle Cartesian join timing bombs
                # at CPDB population time (second layer, after _get_cascade_payloads).
                # This ensures even direct CPDB access paths (unit tests, diagnostics)
                # never receive Oracle Cartesian bomb payloads.
                try:
                    if _is_oracle_cartesian_bomb(payload_str):
                        return True
                except Exception:
                    pass
                # BUG-MSSQL-WAITFOR-TIME FIX: Remove WAITFOR TIME payloads entirely.
                # WAITFOR TIME 'hh:mm:ss' waits until the specified wall-clock time,
                # not for a duration.  WAITFOR TIME '23:59:59' on a server at 00:01 AM
                # would block the connection for ~24 hours.  _targeted_sleep_replace()
                # only handles WAITFOR DELAY format, so these payloads:
                #   (a) cannot be proportionally scaled for PCV Check B
                #   (b) cause multi-hour connection hangs on targets running at the wrong TOD
                # Remove them at population time so they never reach the detection loops.
                if 'WAITFOR TIME' in payload_str.upper():
                    return True
                # BUG-DDL-CPDB-FILTER FIX (Req 3/9): Also filter SQLite DDL/DML statements
                # at CPDB population time. SQLITE_EXOTIC_PAYLOADS and SQLITE_HYBRID_PAYLOADS
                # contain ALTER TABLE, CREATE TRIGGER, DROP TRIGGER, ATTACH DATABASE, etc.
                # These can permanently modify the target database (responsible disclosure
                # violation) and they cannot be used for detection (they change schema,
                # not response bodies). Filter them here so they never reach any probe loop.
                # Only apply to SQLite DBMS key (non-SQLite DBMSes are unaffected by DDL filter).
                # Use a lightweight keyword check instead of the full regex for speed.
                _psu = payload_str.upper()
                _ddl_kws = (
                    'ALTER TABLE', 'CREATE TRIGGER', 'DROP TRIGGER', 'CREATE INDEX',
                    'CREATE UNIQUE INDEX', 'CREATE TABLE', 'DROP TABLE', 'DROP INDEX',
                    'CREATE VIEW', 'DROP VIEW', 'ATTACH DATABASE', 'BEGIN EXCLUSIVE',
                    'BEGIN IMMEDIATE', 'ANALYZE;', 'ANALYZE--', 'ANALYZE ',
                    # BUG-DDL-SAVEPOINT-FIX (Req 3/9): SAVEPOINT/ROLLBACK can leave an
                    # open transaction on the target server if the injection aborts mid-probe.
                    # An uncommitted transaction can lock rows, inflate WAL, and prevent
                    # other sessions from writing — a responsible-disclosure violation for
                    # bug-bounty work.  Filter at CPDB population time so they never reach
                    # the probe loop.
                    'SAVEPOINT ', ';SAVEPOINT', 'ROLLBACK TO ', 'RELEASE SAVEPOINT',
                    # BUG-PRAGMA-LOAD-EXTENSION-FIX (Req 3/9): PRAGMA load_extension() can
                    # load arbitrary shared libraries from the server filesystem.  On SQLite
                    # builds that permit this (compile flag SQLITE_ENABLE_LOAD_EXTENSION and
                    # a call to sqlite3_enable_load_extension()), a successful injection would
                    # give unauthenticated RCE — far beyond the scope of SQL-injection testing.
                    # Remove all load_extension payloads unconditionally.
                    'PRAGMA LOAD_EXTENSION',
                    # BUG-PRAGMA-WAL-FIX (Req 3/9): WAL checkpoint/autocheckpoint/mmap_size/
                    # journal_mode/temp_store_directory PRAGMAs mutate persistent database state
                    # (checkpoint the WAL log, change fsync mode, set temp directory paths).
                    # These can corrupt data on a live server or expose server filesystem paths.
                    'PRAGMA WAL_CHECKPOINT', 'PRAGMA WAL_AUTOCHECKPOINT',
                    'PRAGMA JOURNAL_MODE', 'PRAGMA TEMP_STORE_DIRECTORY',
                    'PRAGMA MMAP_SIZE', 'PRAGMA STMT_JOURNAL_SIZE',
                    'PRAGMA STMT_CACHE_SIZE', 'PRAGMA BATCH_SIZE',
                    # BUG-PRAGMA-SCHEMA-FIX (Req 3/9): writable_schema=ON enables direct
                    # writes to the sqlite_master schema table — equivalent to a schema
                    # backdoor.  writable_schema=OFF is safe but indistinguishable from
                    # writable_schema=ON in the raw payload text before the value is checked,
                    # so filter the entire writable_schema PRAGMA.
                    'PRAGMA WRITABLE_SCHEMA',
                    # BUG-PRAGMA-RECURSIVE-TRIGGERS-FIX (Req 3/9): recursive_triggers=ON
                    # can cause cascading trigger loops that permanently modify data.
                    'PRAGMA RECURSIVE_TRIGGERS',
                    # BUG-SQLITE-ATTACH-MEMORY-FIX (Req 3/9): ATTACH ':memory:' / ATTACH
                    # 'file:...' creates new database handles that persist across the
                    # connection and can interfere with the target application's own SQLite
                    # handles.  ATTACH DATABASE is already filtered; also filter bare ATTACH
                    # followed by a string literal (handles the ':memory:' shorthand form).
                    "ATTACH ':MEMORY:'", "ATTACH \":MEMORY:\"", "ATTACH 'FILE:",
                    # DDL transaction control that bypasses the BEGIN EXCLUSIVE/IMMEDIATE filter
                    'BEGIN;SELECT', 'BEGIN DEFERRED',
                    # BUG-V47-STACKED-DML FIX (Req 3): Add destructive DML write operations.
                    # SQLITE_STACKED_PAYLOADS contains REPLACE INTO, INSERT OR REPLACE,
                    # DELETE FROM, UPDATE ... SET, and VACUUM that permanently modify target DB.
                    # These are out-of-scope for bug-bounty SQL injection detection — only
                    # read-only stacked queries (SELECT, EXPLAIN) are appropriate for
                    # responsible scanning. Root cause: _ddl_kws filtered DDL (schema changes)
                    # but not DML write operations that corrupt user data.
                    'REPLACE INTO', 'INSERT OR REPLACE', 'INSERT OR ROLLBACK INTO',
                    'INSERT OR FAIL INTO', 'INSERT OR ABORT INTO',
                    # Vacuum/Reindex are write-heavy but not DDL — add them here
                    'VACUUM;', 'VACUUM ', 'REINDEX ',
                    # BUG-V47-STACKED-DELETE FIX: DELETE and UPDATE in stacked context
                    # permanently remove/modify production data on bug-bounty targets.
                    # Benign stacked probes use SELECT only; filter write DML entirely.
                    # Note: DELETE FROM / UPDATE ... SET can appear mid-payload after ';' —
                    # catch the explicit start-of-payload and post-separator forms.
                    'DELETE FROM ', 'DELETE  FROM ',  # cover double-space obfuscation
                    # UPDATE ... SET targeting real tables (covered by the bomb regex too)
                    # Use the full pattern here for CPDB fast-path string matching.
                    # BUG-V47-STACKED-UPDATE FIX: UPDATE at payload start (STACKED category)
                    # permanently modifies data — filter at CPDB population time.
                    # PG and MySQL already filter by other means; this is SQLite-only guard.
                    'UPDATE ',  # UPDATE ... SET modifies table rows (destructive DML)
                    # BPG-PG-COPY-FS-FIX (Req 3): PostgreSQL COPY ... TO '/tmp/...' writes
                    # files to the server filesystem — a direct OOB data exfiltration that is
                    # out of scope for standard SQL-injection testing on bug-bounty targets.
                    # Even COPY ... TO PROGRAM allows arbitrary OS command execution.
                    # Filter ALL COPY ... TO variants. COPY (SELECT ...) FROM is also filtered
                    # since it reads server-local files (path disclosure / SSRF via file:///).
                    # Use COPY TO '/dev/null' or COPY TO STDOUT in tests that need COPY stubs.
                    "COPY (SELECT", "COPY pg_", " TO '/tmp/", " TO '/dev/",
                    " TO PROGRAM ", " TO '/::",
                )
                if any(k in _psu for k in _ddl_kws):
                    return True
                for _bm in _RE_BLOB_POP.finditer(payload_str):
                    if int(_bm.group(1)) >= _MAX_BLOB_CPDB:  # BUG-CPU-ITER-THRESHOLD FIX: >= not >
                        return True
                # BUG-ZEROBLOB-CPDB-FILTER FIX: check ZEROBLOB too
                for _zbm in _RE_ZBLOB_POP.finditer(payload_str):
                    if int(_zbm.group(1)) >= _MAX_BLOB_CPDB:  # BUG-CPU-ITER-THRESHOLD FIX: >= not >
                        return True
                for _im in _RE_ITER_POP.finditer(payload_str):
                    if int(_im.group(1)) >= _MAX_ITER_CPDB:  # BUG-CPU-ITER-THRESHOLD FIX: >= not >
                        return True
            except Exception:
                pass
            return False

        for _dk, _tm in CERTIFIED_PAYLOAD_DATABASE.items():
            for _ck, _cm in _tm.items():
                for _sk in list(_cm.keys()):
                    _orig_list = _cm[_sk]
                    if isinstance(_orig_list, list):
                        _safe = [_p for _p in _orig_list if not _is_bomb_cpdb(_p)]
                        if len(_safe) < len(_orig_list):
                            _cm[_sk] = _safe
    except Exception:
        pass  # non-fatal: _get_cascade_payloads still filters as secondary fallback

    # ── BUG-ORA-CARTESIAN CPDB FIX (Req 3/9): Filter Oracle ALL_OBJECTS cross-join bombs ──
    # ORACLE_TIMEBASED_PAYLOADS contains payloads like:
    #   (SELECT COUNT(*) FROM all_objects A, all_objects B WHERE ROWNUM<50000)
    # On production Oracle systems, all_objects can hold 50,000+ rows. Even with
    # ROWNUM<50000, Oracle's CBO may perform a full nested-loop scan before applying the
    # filter — up to 2.5 billion row comparisons → 30-120s CPU per probe → 100% server CPU.
    # _is_oracle_cartesian_bomb() was defined at module scope but was NEVER called during
    # CPDB population, leaving these payloads active in every scan that probes Oracle.
    # Fix: filter them at population time so all access paths (globals() + CPDB fallback)
    # return only safe Oracle timing payloads (DBMS_PIPE.RECEIVE_MESSAGE and DBMS_LOCK.SLEEP).
    try:
        _ora_cpdb_entry = CERTIFIED_PAYLOAD_DATABASE.get('Oracle', {})
        _ora_cpdb_removed_total = 0
        for _ora_cat_k, _ora_cat_m in _ora_cpdb_entry.items():
            for _ora_sub_k in list(_ora_cat_m.keys()):
                _ora_sub_list = _ora_cat_m[_ora_sub_k]
                if isinstance(_ora_sub_list, list):
                    _ora_safe_list = [_p for _p in _ora_sub_list
                                      if not _is_oracle_cartesian_bomb(_p)]
                    _ora_removed = len(_ora_sub_list) - len(_ora_safe_list)
                    if _ora_removed > 0:
                        _ora_cpdb_removed_total += _ora_removed
                        _ora_cat_m[_ora_sub_k] = _ora_safe_list
        if _ora_cpdb_removed_total > 0:
            print(f'[*] _populate_certified_db: removed {_ora_cpdb_removed_total} Oracle '
                  'cartesian-bomb payloads (ALL_OBJECTS cross-join) to prevent '
                  'target CPU saturation', flush=True)
    except Exception as _ora_cpdb_err:
        LOG.debug(f'[CPDB-ORA-CARTESIAN] Filter error (non-fatal): {_ora_cpdb_err}')

    # ── BUG-ORACLE-DDL-EXOTIC-NOT-FILTERED FIX (Req 3/9) ──────────────────────────────
    # ORACLE_EXOTIC_PAYLOADS and ORACLE_HYBRID_PAYLOADS contain DDL/DML/PL-SQL statements
    # that PERMANENTLY MODIFY the target database:
    #   - CREATE PROCEDURE exotic_proc / CREATE FUNCTION exotic_func / CREATE TYPE exotic_type
    #   - DECLARE ... BEGIN EXECUTE IMMEDIATE ... END  (arbitrary PL/SQL execution)
    #   - AUDIT ALL BY ... / NOAUDIT ALL BY ...        (modifies audit configuration)
    #   - DELETE FROM aud$ WHERE ...                   (deletes audit records)
    #   - BEGIN DBMS_LOGMNR.ADD_LOGFILE(...) END       (registers log files for mining)
    #   - BEGIN DBMS_LBAC.CREATE_LABEL(...) END        (creates VPD policy labels)
    #   - BEGIN DBMS_RLS.ADD_POLICY(...) END           (creates row-level-security policies)
    # These are:
    #   (a) Out of scope for SQL injection DETECTION (they test schema mutation, not data leak)
    #   (b) Responsible-disclosure violations — they permanently alter the tested database
    #   (c) Cannot be used as boolean oracle probes (they don't cause a boolean diff)
    # ORACLE_STACKED_PAYLOADS also contain DDL; they're included here.
    # The SQLite DDL filter above filters _is_bomb_cpdb() only for all-DBMS keys; Oracle-specific
    # DDL patterns (CREATE PROCEDURE, EXECUTE IMMEDIATE, AUDIT, DELETE FROM aud$, DBMS_*) were
    # never filtered, leaving them active in every Oracle scan.
    # Fix: filter Oracle EXOTIC, HYBRID, and STACKED categories at population time.
    try:
        _ORA_DDL_PREFIXES = (
            'CREATE PROCEDURE', 'CREATE FUNCTION', 'CREATE TYPE', 'CREATE TABLE',
            'CREATE INDEX', 'CREATE SEQUENCE', 'CREATE TRIGGER', 'CREATE VIEW',
            'CREATE SYNONYM', 'DROP PROCEDURE', 'DROP FUNCTION', 'DROP TYPE',
            'DROP TABLE', 'DROP INDEX', 'DROP SEQUENCE', 'DROP TRIGGER',
            'DROP VIEW', 'DROP SYNONYM', 'ALTER TABLE', 'ALTER INDEX',
            # PL/SQL blocks that execute arbitrary statements
            'DECLARE ', 'BEGIN ', 'BEGIN\n', 'BEGIN\t',
            # Audit/un-audit statements (modify audit configuration)
            'AUDIT ', 'NOAUDIT ',
            # Direct DML on audit/data-dictionary tables (deletes records)
            'DELETE FROM AUD$', 'DELETE FROM FGA_LOG$', 'DELETE FROM SYS.AUD$',
            # DBMS packages that create/modify database objects or audit state
            'BEGIN DBMS_LOGMNR.', 'BEGIN DBMS_LBAC.', 'BEGIN DBMS_RLS.',
            'BEGIN DBMS_DDL.', 'BEGIN DBMS_OBFUSCATION_TOOLKIT.',
            'SELECT CAST(DBMS_RLS.', 'SELECT CAST(DBMS_LOGMNR.',
            'SELECT CAST(DBMS_DDL.', 'SELECT CAST(DBMS_GOLDENGATE',
            'SELECT CAST(SYS_SESSION_ROLES',
            # EXECUTE IMMEDIATE is PL/SQL that executes arbitrary SQL
            'EXECUTE IMMEDIATE', 'DBMS_SQL.OPEN_CURSOR', 'DBMS_SQL.PARSE(',
        )
        _ora_ddl_cats = ('Exotic', 'Hybrid', 'Stacked')
        _ora_cpdb_ddl_entry = CERTIFIED_PAYLOAD_DATABASE.get('Oracle', {})
        _ora_ddl_removed = 0
        for _ddl_cat in _ora_ddl_cats:
            _ddl_cat_entry = _ora_cpdb_ddl_entry.get(_ddl_cat, {})
            for _ddl_sub_k in list(_ddl_cat_entry.keys()):
                _ddl_list = _ddl_cat_entry[_ddl_sub_k]
                if isinstance(_ddl_list, list):
                    _ddl_safe = [
                        _p for _p in _ddl_list
                        if not any(_p.upper().lstrip().startswith(_pfx.upper())
                                   or _pfx.upper() in _p.upper()
                                   for _pfx in _ORA_DDL_PREFIXES)
                    ]
                    _ddl_removed_n = len(_ddl_list) - len(_ddl_safe)
                    if _ddl_removed_n > 0:
                        _ddl_cat_entry[_ddl_sub_k] = _ddl_safe
                        _ora_ddl_removed += _ddl_removed_n
        if _ora_ddl_removed > 0:
            LOG.debug(f'[CPDB-ORA-DDL] Filtered {_ora_ddl_removed} Oracle DDL/DML/PL-SQL '
                      f'payloads from Exotic/Hybrid/Stacked (responsible disclosure filter)')
    except Exception as _ora_ddl_err:
        LOG.debug(f'[CPDB-ORA-DDL] Filter error (non-fatal): {_ora_ddl_err}')

    # ── BUG-V43-2 FIX (Req 1/3): Filter MSSQL xp_cmdshell/CREATE ASSEMBLY/sp_add_job
    # from CERTIFIED_PAYLOAD_DATABASE at population time. MSSQL_EXOTIC_PAYLOADS contains
    # EXEC xp_cmdshell (OS command execution), CREATE ASSEMBLY exploit (CLR injection),
    # EXEC msdb.dbo.sp_add_job (persistent SQL Agent job creation), ALTER DATABASE SET
    # PARTNER (failover trigger), EXEC sp_OACreate (OLE Automation), BEGIN DISTRIBUTED
    # TRANSACTION OPENQUERY (remote execution), and other RCE/DDL payloads that have no
    # place in SQL injection detection testing. _is_bomb_cpdb() does NOT filter these.
    # BUG-MSSQL-FILTER-GAP FIX: Extended _MSSQL_CPDB_DANGEROUS to cover MSSQL_NOVEL_PAYLOADS
    # entries (sp_addlinkedserver, sp_adddistributor, sp_addpublication, sp_addsubscription,
    # OPENROWSET, CREATE FULLTEXT, CREATE MESSAGE TYPE, CREATE CONTRACT, CREATE QUEUE,
    # CREATE SERVICE, CHANGETABLE, FREETEXTTABLE, CONTAINSTABLE, CHANGE_TRACKING) that
    # were previously escaping ALL three filter layers. Also extended _mssql_dangerous_cats
    # to include 'Novel' so these payloads are filtered at CPDB population time.
    try:
        _MSSQL_CPDB_DANGEROUS = (
            'EXEC XP_CMDSHELL', 'EXEC MASTER..XP_',
            'CREATE ASSEMBLY', 'ALTER ASSEMBLY', 'DROP ASSEMBLY',
            'EXEC MSDB.DBO.SP_ADD_JOB', 'EXEC MSDB.DBO.SP_ADD_JOBSTEP',
            'EXEC MSDB.DBO.SP_START_JOB', 'EXEC MSDB.DBO.SP_DELETE_JOB',
            'ALTER DATABASE ', 'DROP DATABASE ',
            'BEGIN DISTRIBUTED TRANSACTION',
            'EXEC SP_SERVEROPTION', 'EXEC SP_OACREATE', 'EXEC SP_OAMETHOD',
            'EXEC SP_OASETPROPERTY', 'EXEC SP_OADESTROY',
            'EXEC SP_MSSET_OLEDB_PROP',
            'SELECT * FROM OPENQUERY(', 'SELECT * FROM OPENDATASOURCE(',
            'EXEC SP_VALIDATELOGINS',
            'EXEC REPORTSERVER', 'EXEC REPLICATIONSERVER',
            'CREATE TRIGGER ', 'CREATE VIEW ', 'CREATE PROCEDURE ',
            'CREATE PROC ', 'CREATE FUNCTION ', 'CREATE TABLE ',
            'DROP TABLE ', 'DROP VIEW ',
            'EXEC SP_EXECUTESQL',
            # BUG-MSSQL-FILTER-GAP FIX: Previously missing entries now added to all 3 filter layers.
            # Linked server operations (persistent infrastructure modification)
            'EXEC SP_ADDLINKEDSERVER', 'EXEC SP_ADDLINKEDSRVLOGIN',
            'EXEC SP_DROPLINKEDSRVLOGIN', 'EXEC SP_DROPSERVER',
            # OLE DB / remote data access (potential SSRF / credential leak vector)
            'SELECT * FROM OPENROWSET(',
            # Replication infrastructure (creates persistent DB replication objects)
            'EXEC SP_ADDDISTRIBUTOR', 'EXEC SP_ADDPUBLICATION',
            'EXEC SP_ADDPUBLICATION_SNAPSHOT', 'EXEC SP_ADDSUBSCRIPTION',
            'EXEC SP_ADDSUBSCRIBER',
            # Service Broker DDL (creates persistent messaging objects)
            'CREATE FULLTEXT ', 'ALTER FULLTEXT ',
            'CREATE MESSAGE TYPE', 'CREATE CONTRACT',
            'CREATE QUEUE', 'CREATE SERVICE',
            # Change tracking (reads CDC logs; also alters tracking configuration)
            'SELECT * FROM CHANGETABLE(', 'ENABLE CHANGE_TRACKING',
            # Full-text search table-valued functions (reads full-text indexes)
            'SELECT * FROM FREETEXTTABLE(', 'SELECT * FROM CONTAINSTABLE(',
        )
        # BUG-MSSQL-FILTER-GAP FIX: Added 'Novel' to _mssql_dangerous_cats.
        # MSSQL_NOVEL_PAYLOADS contains sp_addlinkedserver, sp_adddistributor,
        # sp_addpublication, OPENROWSET, CREATE FULLTEXT, CREATE MESSAGE TYPE,
        # CREATE CONTRACT, CREATE QUEUE, CREATE SERVICE, CHANGETABLE, FREETEXTTABLE,
        # and CONTAINSTABLE payloads. These were in 'Novel' but _mssql_dangerous_cats
        # only covered 'Exotic', 'Hybrid', 'Stacked' — so Novel payloads escaped all
        # three filter layers (get_dbms_payloads/_CPI_MSSQL_DANGEROUS/_MSSQL_CPDB_DANGEROUS)
        # entirely and were sent against bug-bounty targets.
        _mssql_dangerous_cats = ('Exotic', 'Hybrid', 'Stacked', 'Novel')
        _mssql_cpdb_entry = CERTIFIED_PAYLOAD_DATABASE.get('MSSQL', {})
        _mssql_dangerous_removed = 0
        for _ms_cat in _mssql_dangerous_cats:
            _ms_cat_entry = _mssql_cpdb_entry.get(_ms_cat, {})
            for _ms_sub_k in list(_ms_cat_entry.keys()):
                _ms_list = _ms_cat_entry[_ms_sub_k]
                if isinstance(_ms_list, list):
                    _ms_safe = [
                        _p for _p in _ms_list
                        if not any(_pfx in _p.upper().lstrip()
                                   for _pfx in _MSSQL_CPDB_DANGEROUS)
                    ]
                    _ms_removed_n = len(_ms_list) - len(_ms_safe)
                    if _ms_removed_n > 0:
                        _ms_cat_entry[_ms_sub_k] = _ms_safe
                        _mssql_dangerous_removed += _ms_removed_n
        if _mssql_dangerous_removed > 0:
            LOG.debug(f'[CPDB-MSSQL-RCE] Filtered {_mssql_dangerous_removed} MSSQL RCE/DDL '
                      f'payloads from Exotic/Hybrid/Stacked (responsible disclosure filter)')
    except Exception as _mssql_danger_err:
        LOG.debug(f'[CPDB-MSSQL-RCE] Filter error (non-fatal): {_mssql_danger_err}')

    # ── BUG-V43-3 FIX (Req 1/3): Filter PostgreSQL COPY TO file payloads from CPDB.
    # _is_bomb_cpdb() already catches these via "COPY (SELECT" / " TO '/tmp/" but as a
    # second-layer defense (for future payload additions that might have different forms),
    # also filter them explicitly from PostgreSQL Novel/Exotic/Hybrid categories at CPDB
    # population time. COPY TO '/tmp/...' writes server-side files — out of scope.
    try:
        _PG_COPY_CPDB_PREFIXES = ('COPY (SELECT', 'COPY PG_', 'COPY (WITH')
        _PG_COPY_TO_CPDB_PATTERNS = (
            " TO '/TMP/", " TO '/DEV/", " TO '/VAR/",
            " TO '/ETC/", " TO PROGRAM ", " TO STDOUT",
        )
        _pg_copy_cats = ('Novel', 'Exotic', 'Hybrid')
        _pg_cpdb_entry = CERTIFIED_PAYLOAD_DATABASE.get('PostgreSQL', {})
        _pg_copy_removed = 0
        for _pg_cat in _pg_copy_cats:
            _pg_cat_entry = _pg_cpdb_entry.get(_pg_cat, {})
            for _pg_sub_k in list(_pg_cat_entry.keys()):
                _pg_list = _pg_cat_entry[_pg_sub_k]
                if isinstance(_pg_list, list):
                    _pg_safe = [
                        _p for _p in _pg_list
                        if not (any(pfx in _p.upper() for pfx in _PG_COPY_CPDB_PREFIXES) and
                                any(pat in _p.upper() for pat in _PG_COPY_TO_CPDB_PATTERNS))
                    ]
                    _pg_removed_n = len(_pg_list) - len(_pg_safe)
                    if _pg_removed_n > 0:
                        _pg_cat_entry[_pg_sub_k] = _pg_safe
                        _pg_copy_removed += _pg_removed_n
        if _pg_copy_removed > 0:
            LOG.debug(f'[CPDB-PG-COPY] Filtered {_pg_copy_removed} PostgreSQL COPY TO '
                      f'file payloads from Novel/Exotic/Hybrid (responsible disclosure filter)')
    except Exception as _pg_copy_err:
        LOG.debug(f'[CPDB-PG-COPY] Filter error (non-fatal): {_pg_copy_err}')


    # These payloads produce syntax errors or always-FALSE conditions on every probe,
    # causing both true and false conditions to return identical responses (zero differential).
    # Having them in the list wastes probe slots and can confuse the differential oracle.
    try:
        _DEAD_PAYLOAD_PATTERNS = [
            # BUG-MYSQL-STD-SYNTAX-A: 'AND (SLEEP(0)IN"test")' — MySQL IN requires a
            # parenthesized list or subquery; IN followed by a bare string literal is a
            # syntax error with default sql_mode (NO_ANSI_QUOTES) where "test" is an
            # identifier, not a string. Both true and false probes fail with the same error.
            'SLEEP(0)IN"test"',
            # BUG-MYSQL-STD-SEMANTIC-A: COALESCE(ASCII('0'),SLEEP(0))=SLEEP(0) evaluates
            # to COALESCE(48,0)=0 → 48=0 → always FALSE. Using as a "true" condition
            # inverts the oracle: the "true" probe produces the false/negative response.
            # This can cause detected-but-not-injected false positives on some targets.
            "COALESCE(ASCII('0'),SLEEP(0))=SLEEP(0)",
        ]
        for _dk2, _tm2 in CERTIFIED_PAYLOAD_DATABASE.items():
            for _ck2, _cm2 in _tm2.items():
                for _sk2 in list(_cm2.keys()):
                    _list2 = _cm2[_sk2]
                    if isinstance(_list2, list):
                        _filtered2 = [
                            _p for _p in _list2
                            if not any(_pat in _p for _pat in _DEAD_PAYLOAD_PATTERNS)
                        ]
                        if len(_filtered2) < len(_list2):
                            _cm2[_sk2] = _filtered2
    except Exception:
        pass  # non-fatal

    # ── BUG-PAYLOAD-PREFIX-FIX (ALL-DBMS): normalise missing SQL operator prefixes ──
    # Root cause: every DBMS payload list except Oracle Boolean was generated without
    # the leading SQL separator needed when the payload is concatenated onto the existing
    # parameter value as  (original + payload).  Without it:
    #   id=1CAST(SUSER_NAME() AS BIT)=1      ← always SQL syntax error
    # With normalised prefix:
    #   id=1 AND CAST(SUSER_NAME() AS BIT)=1  ← proper conditional injection
    #
    # Both the "true" and "false" probes raised the same syntax error, so the boolean
    # oracle measured zero delta and never confirmed injection.  This bug made detection
    # completely non-functional for: MSSQL (all categories), PostgreSQL (Boolean, Error,
    # Timebased, Standard, Novel), SQLite (all categories), MySQL (Error, Timebased,
    # Standard; Boolean was 280/300 broken).  Oracle Boolean was already correct.
    #
    # Normalisation rules (applied once at population time, idempotent):
    #   1. Payload already starts with space / quote / comment / semicolon → skip
    #   2. Payload starts with digit+quote  (e.g. "1' UNION …")  → replacement-style, skip
    #   3. Stacked category + no prefix  → prepend '; '
    #   4. Starts with AND/OR/XOR/HAVING + whitespace  → prepend ' '  (just needs spacing)
    #   5. Starts with || or &&  → prepend ' '
    #   6. Starts with UNION + whitespace  → prepend ' '
    #   7. Everything else (CAST, EXTRACTVALUE, SUBSTRING, CHARINDEX, …)  → prepend ' AND '
    try:
        # Pattern 4 — keywords that already ARE the boolean connector; just need space
        _pfx_kw  = _re.compile(r'^(?:AND|OR|XOR|HAVING)\s', _re.IGNORECASE)
        # Pattern 5 — PostgreSQL/MySQL bitwise / logical operators
        _pfx_op  = _re.compile(r'^\|\||^&&')
        # Pattern 6 — UNION-style replacement payloads
        _pfx_un  = _re.compile(r'^UNION\s', _re.IGNORECASE)
        # Patterns 1-2 — already-correct or replacement-style  (skip normalisation)
        # Covers: leading space, single/double quote, semicolon, comment (-- / /*),
        # and the numeric-quote replacement pattern  1' / 0' / 2' etc.
        _pfx_skip = _re.compile(r"^(?:\s|'|\"|;|--|/\*|\d+')")

        for _pnk_d, _pnk_tm in CERTIFIED_PAYLOAD_DATABASE.items():
            for _pnk_c, _pnk_cm in _pnk_tm.items():
                _is_stacked_cat = (_pnk_c == 'Stacked')
                for _pnk_s in list(_pnk_cm.keys()):
                    _pnk_list = _pnk_cm[_pnk_s]
                    if not isinstance(_pnk_list, list):
                        continue
                    _pnk_out = []
                    for _pnk_p in _pnk_list:
                        if not isinstance(_pnk_p, str) or not _pnk_p:
                            _pnk_out.append(_pnk_p)
                            continue
                        # Rules 1-2: already correct or replacement-style — leave untouched
                        if _pfx_skip.match(_pnk_p):
                            _pnk_out.append(_pnk_p)
                            continue
                        # Rule 6: UNION payload needs a space before it
                        if _pfx_un.match(_pnk_p):
                            _pnk_out.append(' ' + _pnk_p)
                            continue
                        # Rule 3: stacked-query payload needs semicolon separator
                        if _is_stacked_cat:
                            _pnk_out.append('; ' + _pnk_p)
                            continue
                        # Rule 4: payload already begins with a boolean connector keyword
                        if _pfx_kw.match(_pnk_p) or _pfx_op.match(_pnk_p):
                            _pnk_out.append(' ' + _pnk_p)
                            continue
                        # BUG-PREFIX-EXEC-FIX (Req 1/6): Payloads starting with EXEC, CALL,
                        # BEGIN, DECLARE, or WAITFOR are stored in non-stacked categories
                        # (e.g. Exotic, Hybrid, Novel) but are stacked-query SQL statements —
                        # they must be preceded by '; ' not ' AND '.  Prepending ' AND EXEC ...'
                        # produces a SQL syntax error on ALL DBMSes, making both true and false
                        # probes fail identically → differential oracle measures zero delta →
                        # genuine injection silently missed.  Rule 5b guards these keywords
                        # BEFORE Rule 7 (catch-all ' AND ') fires.
                        _pnk_p_upper_check = _pnk_p.upper().lstrip()
                        if (_pnk_p_upper_check.startswith('EXEC ') or
                                _pnk_p_upper_check.startswith('EXEC(') or
                                _pnk_p_upper_check.startswith('CALL ') or
                                _pnk_p_upper_check.startswith('BEGIN ') or
                                _pnk_p_upper_check.startswith('BEGIN;') or
                                _pnk_p_upper_check.startswith('DECLARE ') or
                                _pnk_p_upper_check.startswith('WAITFOR ')):
                            _pnk_out.append('; ' + _pnk_p)
                            continue
                        # Rule 7: expression-style payload — needs AND to attach to WHERE
                        _pnk_out.append(' AND ' + _pnk_p)
                    _pnk_cm[_pnk_s] = _pnk_out
        print('[*] _populate_certified_db: payload prefix normalisation complete',
              flush=True)
    except Exception as _pfx_err:
        print(f'[!] _populate_certified_db: prefix normalisation error (non-fatal): {_pfx_err}',
              flush=True)
    # ── end BUG-PAYLOAD-PREFIX-FIX ──────────────────────────────────────────────────
    # BUG-CPU-A cache invalidation: clear the lru_cache on _get_cascade_payloads_cached
    # whenever CERTIFIED_PAYLOAD_DATABASE is re-populated (e.g. scan restart without
    # process restart) so stale cached results don't persist into the new scan session.
    try:
        _get_cascade_payloads_cached.cache_clear()
    except Exception:
        pass  # function may not be defined yet on first populate call

DBMS_TECHNIQUE_MAP  = _NormalizingDBMSDict()

# FIX FUN-1 (Issue 1 & 2): _build_technique_map() was only called lazily inside the v25
# scanner's run() method, leaving DBMS_TECHNIQUE_MAP empty for every other scanner
# tier (V4–V18), standalone callers, and any access before run() fires.
# We populate it here at module load time — safe because CERTIFIED_PAYLOAD_DATABASE is
# populated by _populate_certified_db() at the very bottom of this file and the
# function object exists from the def at line 48392.  The actual *call* is deferred to
# after _populate_certified_db() runs (see bottom of file) via the module-level hook.
# A guard inside run() still updates it in case new payloads are dynamically added.
def _ensure_technique_map_populated():
    """Populate DBMS_TECHNIQUE_MAP from per-DBMS payload lists (idempotent)."""
    global DBMS_TECHNIQUE_MAP
    if not len(DBMS_TECHNIQUE_MAP):
        try:
            DBMS_TECHNIQUE_MAP.update(_build_technique_map())
        except Exception as _tm_err:
            import traceback as _tm_tb
            print(f"[!] DBMS_TECHNIQUE_MAP population failed: {_tm_err}", flush=True)
            _tm_tb.print_exc()

