                    p = _re.sub(
                        r'((?:DBMS_LOCK|DBMS_SESSION)\.SLEEP\s*\(\s*)[\d.]+(\s*\))',
                        lambda m: f"{m.group(1)}{new_val:.1f}{m.group(2)}", p,
                        count=1, flags=_re.I)
