                _s_thresh_floor = _S_DBMS_THRESH_FLOORS.get(_thresh_dbms_key, _DBMS_TIMING_FLOORS.get(_thresh_dbms_key, 200.0))
                _s_payload_thresh = _s_val * 0.65 * 1000  # 65% of payload sleep value in ms
