                # allocated once.  Reference here still works because it is defined in enclosing scope.
                if len(_passing_pairs) >= 2:
                    _fam0 = _norm_chka_family(_passing_pairs[-2][1])
                    _fam1 = _norm_chka_family(_passing_pairs[-1][1])
                    if _fam0 != _fam1:
                        _best = max(_passing_pairs, key=lambda x: x[0])
                        _any_strong = any(s for _, _, s in _passing_pairs)
