                                                        _ch_iso = hashlib.md5(_pay.encode('utf-8', errors='replace')).hexdigest()[:10]
                                                        _cb_u_iso = (_u + ("&" if "?" in _u else "?")
                                                                     + _get_cache_bust_params(_cb_iso, _ch_iso))
