# PROXY POOL MANAGER
# 

import statistics as _statistics

class ProxyAnonymity:
    ELITE       = "elite"
    ANONYMOUS   = "anonymous"
    TRANSPARENT = "transparent"
    UNKNOWN     = "unknown"

class ProxyEntry:
    __slots__ = ("url","protocol","host","port","username","password",
                 "anonymity","latency_ms","alive","fail_count",
                 "success_count","last_checked","last_used","country")
    def __init__(self, url, protocol, host, port,
                 username=None, password=None):
        self.url           = url
        self.protocol      = protocol
        self.host          = host
        self.port          = port
        self.username      = username
        self.password      = password
        self.anonymity     = ProxyAnonymity.UNKNOWN
        self.latency_ms    = 9999.0
        self.alive         = False
        self.fail_count    = 0
        self.success_count = 0
        self.last_checked  = 0.0
        self.last_used     = 0.0
        self.country       = ""

    @property
    def score(self) -> float:
        anon_s = {ProxyAnonymity.ELITE:1.0, ProxyAnonymity.ANONYMOUS:0.7,
                  ProxyAnonymity.TRANSPARENT:0.0, ProxyAnonymity.UNKNOWN:0.3
                  }.get(self.anonymity, 0.3)
        lat_s  = max(0.0, 1.0 - self.latency_ms / 10000.0)
        total  = self.success_count + self.fail_count
        sr     = self.success_count / max(total, 1)
        return anon_s * 0.5 + lat_s * 0.3 + sr * 0.2

    def __str__(self):
        return (f"{self.url} [{self.anonymity}] "
                f"{self.latency_ms:.0f}ms score={self.score:.2f}")


class ProxyPoolManager:
    """User-supplied proxy pool with health checking, anonymity detection,
    smart rotation. Supports http/socks5 proxies from a file you control."""

    CHECK_SERVICES = ["http://httpbin.org/anything",
                      "http://api.ipify.org/?format=json"]
    MAX_FAIL_COUNT = 3
    RECHECK_AFTER  = 300

    def __init__(self, proxy_file=None, proxy_list=None,
                 rotate_every=1,
                 min_anonymity=ProxyAnonymity.ANONYMOUS,
                 timeout=10.0, max_concurrent_checks=30,
                 check_anonymity=True, real_ip=None):
        self._raw:       List[str]        = []
        self._pool:      List[ProxyEntry] = []
        self._live:      List[ProxyEntry] = []
        self._blacklist: Set[str]         = set()
        self._idx        = 0
        self._req_count  = 0
        self._rotate_every    = max(1, rotate_every)
        self._min_anon        = min_anonymity
        self._timeout         = timeout
        self._max_checks      = max_concurrent_checks
        self._check_anon      = check_anonymity
        self._real_ip         = real_ip
        self._lock            = asyncio.Lock()
        self._stats           = {"rotations":0,"blacklisted":0,"requests":0}
        if proxy_file:  self._load_file(proxy_file)
        if proxy_list:  self._raw.extend(proxy_list)

    def _load_file(self, path):
        try:
            # TODO: Replace with aiofiles for async I/O
            with open(path, encoding="utf-8", errors="ignore") as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith("#"):
                        self._raw.append(line)
            LOG.info(f"Proxy file: {len(self._raw)} entries from {path}")
        except FileNotFoundError:
            raise ConfigError(f"Proxy file not found: {path}")

    def _parse(self, raw):
        raw = raw.strip()
        if not raw: return None
        if raw.startswith(("http://","https://","socks5://","socks4://")):
            try:
                from urllib.parse import urlparse as _u
                p = _u(raw)
                return ProxyEntry(url=raw,
                    protocol=p.scheme.lower().replace("https","http"),
                    host=p.hostname or "", port=p.port or 8080,
                    username=p.username, password=p.password)
            except Exception: return None
        parts = raw.split(":")
        if len(parts) >= 2:
            host = parts[0]
            try: port = int(parts[1])
            except Exception: return None
            user = parts[2] if len(parts)>2 else None
            pw   = parts[3] if len(parts)>3 else None
            url  = (f"http://{user}:{pw}@{host}:{port}" if user
                    else f"http://{host}:{port}")
            return ProxyEntry(url=url, protocol="http",
                              host=host, port=port, username=user, password=pw)
        return None

    async def check_all(self, target_url=None):
        entries = [self._parse(r) for r in self._raw]
        entries = [e for e in entries if e]
        if not entries: return 0
        LOG.info(f"Proxy check: {len(entries)} proxies (concurrency={self._max_checks})")
        sem = asyncio.Semaphore(self._max_checks)
        await asyncio.gather(*[self._check_one(e, sem, target_url)
                                for e in entries], return_exceptions=True)
        self._pool = entries
        self._refresh_live()
        LOG.info(f"Proxy result: {len(self._live)} live "
                 f"({sum(1 for p in self._live if p.anonymity==ProxyAnonymity.ELITE)} elite, "
                 f"{sum(1 for p in self._live if p.anonymity==ProxyAnonymity.ANONYMOUS)} anonymous)")
        return len(self._live)

    async def _check_one(self, entry, sem, target_url):
        async with sem:
            try:
                import httpx as _httpx
                url = target_url or self.CHECK_SERVICES[0]
                proxy_map = {"http://": entry.url, "https://": entry.url}
                t0 = time.monotonic()
                async with _httpx.AsyncClient(proxies=proxy_map,
                        timeout=self._timeout, verify=False) as c:
                    r = await c.get(url)
                    elapsed = (time.monotonic()-t0)*1000
                entry.alive      = True
                entry.latency_ms = elapsed
                entry.last_checked = time.time()
                if self._check_anon:
                    entry.anonymity = self._detect_anon(dict(r.headers))
                LOG.debug(f"   {entry.host}:{entry.port} "
                          f"{entry.latency_ms:.0f}ms {entry.anonymity}")
            except Exception as e:
                entry.alive = False
                LOG.debug(f"   {entry.host}:{entry.port}: {type(e).__name__}")

    def _detect_anon(self, headers):
        hl   = {k.lower(): v.lower() for k,v in headers.items()}
        xff  = hl.get("x-forwarded-for","")
        via  = hl.get("via","")
        if self._real_ip and self._real_ip in xff:
            return ProxyAnonymity.TRANSPARENT
        if xff and self._real_ip and any(
                self._real_ip in p for p in xff.split(",")):
            return ProxyAnonymity.TRANSPARENT
        if via or "proxy-connection" in hl:
            return ProxyAnonymity.ANONYMOUS
        if not xff and not via:
            return ProxyAnonymity.ELITE
        return ProxyAnonymity.ANONYMOUS

    def _refresh_live(self):
        rank = {ProxyAnonymity.ELITE:3, ProxyAnonymity.ANONYMOUS:2,
                ProxyAnonymity.TRANSPARENT:1, ProxyAnonymity.UNKNOWN:0}
        min_r = rank.get(self._min_anon, 2)
        self._live = sorted(
            [p for p in self._pool
             if p.alive and rank.get(p.anonymity,0) >= min_r
             and p.url not in self._blacklist],
            key=lambda p: p.score, reverse=True)

    def get_next(self):
        if not self._live: return None
        self._req_count  += 1
        self._stats["requests"] += 1
        if self._req_count % self._rotate_every == 0:
            self._idx = (self._idx+1) % len(self._live)
            self._stats["rotations"] += 1
        p = self._live[self._idx % len(self._live)]
        p.last_used = time.time()
        return p

    def get_random(self):
        return random.choice(self._live) if self._live else None

    async def record_result(self, proxy, success):
        async with self._lock:
            if success:
                proxy.success_count += 1
                proxy.fail_count = max(0, proxy.fail_count-1)
            else:
                proxy.fail_count += 1
                if proxy.fail_count >= self.MAX_FAIL_COUNT:
                    self._blacklist.add(proxy.url)
                    self._stats["blacklisted"] += 1
                    LOG.warning(f"Proxy blacklisted: {proxy.host}:{proxy.port}")
                    self._refresh_live()

    async def recheck_blacklisted(self):
        now = time.time()
        to_recheck = [p for p in self._pool
                      if p.url in self._blacklist
                      and now-p.last_checked > self.RECHECK_AFTER]
        if not to_recheck: return
        sem = asyncio.Semaphore(10)
        await asyncio.gather(*[self._check_one(p, sem, None) for p in to_recheck], return_exceptions=True)
        for p in to_recheck:
            if p.alive:
                p.fail_count = 0
                self._blacklist.discard(p.url)
        self._refresh_live()

    @property
    def live_count(self): return len(self._live)
    @property
    def elite_count(self):
        return sum(1 for p in self._live if p.anonymity==ProxyAnonymity.ELITE)
    @property
    def stats(self):
        return {**self._stats, "live":self.live_count, "elite":self.elite_count,
                "blacklisted":len(self._blacklist), "pool":len(self._pool)}

    def summary(self):
        lines = [f"Proxy pool: {self.live_count} live ({self.elite_count} elite)"]
        for p in self._live[:5]: lines.append(f"  {p}")
        if len(self._live)>5: lines.append(f"  ... +{len(self._live)-5} more")
        return "\n".join(lines)



# Alias for backward compatibility
ProxyManager = ProxyPoolManager

class ProxyRotatingEngine(HTTPEngineV5):
    """HTTPEngineV5 that transparently rotates proxies per request."""
    def __init__(self, *args, proxy_pool=None, **kwargs):
        super().__init__(*args, **kwargs)
        self._proxy_pool = proxy_pool

    async def send(self, method, url, **kwargs):
        if not self._proxy_pool or self._proxy_pool.live_count == 0:
            return await super().send(method, url, **kwargs)
        proxy = self._proxy_pool.get_next()
        if not proxy:
            return await super().send(method, url, **kwargs)
        # httpx.AsyncClient bakes the proxy at construction time, so we must
        # create a per-request client to honour proxy rotation.
        limits = httpx.Limits(max_connections=4, max_keepalive_connections=2)
        try:
            async with httpx.AsyncClient(
                http2=self.config.http2,
                verify=self.config.verify_ssl,
                proxy=proxy.url,
                limits=limits,
                timeout=self.config.timeout,
                follow_redirects=True,
            ) as tmp_client:
                orig_client = self._client
                self._client = tmp_client
                try:
                    fp = await super().send(method, url, **kwargs)
                    await self._proxy_pool.record_result(proxy, _get_safe_status_code(fp) < 500)
                    return fp
                except Exception as e:
                    await self._proxy_pool.record_result(proxy, False)
                    raise
                finally:
                    self._client = orig_client
        except Exception:
            # Proxy connection failed  fall back to direct
            return await super().send(method, url, **kwargs)


