                            "X-Tenant-IP",
                            "X-Original-Forwarded-For",
                            "X-Proxy-Client-IP",
                            "WL-Proxy-Client-IP",
                            "X-True-Client-IP",
                            "X-Nokia-Client-IP",
                            "X-Siemens-Client-IP",
                            "X-Huawei-Client-IP",
                            "X-Bunny-Client-IP",
                            "X-Reblaze-Client-IP",
                            "EC-Identifier",
                            #  Metadata headers (logged/stored, don't affect routing) 
                            "Referer",
                            "User-Agent",
