                            "X-Trace-ID",
                            "X-Span-ID",
                            "X-Parent-Span-ID",
                            "X-B3-TraceId",
                            "X-B3-SpanId",
                            "X-B3-ParentSpanId",
                            "X-Datadog-Trace-ID",
                            "X-Cloud-Trace-Context",
                            "Traceparent",
                            "X-Request-Start",
                            "X-Queue-Start",
                            #  Auth/token headers (stored in backend) 
                            "X-Auth-Token",
                            "X-API-Key",
                            "X-CSRF-Token",
                            "X-Access-Token",
                            "X-Refresh-Token",
                            "X-Tenant-ID",
                            "X-Org-ID",
                            "X-Workspace-ID",
                            "X-Team-ID",
                            "X-Project-ID",
                            "X-Authorization",
                            "X-Token",
                            "X-Auth-Email",
                            "X-Email",
