                    if not _bl_fp or not _bl_fp.body:
                        _hi = _mid  # treat failed probe as "length not exceeded"
                        continue
                    _bl_norm = ResponseNormaliser.normalise(_extract_body_safe(_bl_fp)) if _validate_response(_bl_fp, allow_empty=True) else b""
                    _bl_samples = self.baseline.get("samples", [])
                    # BUG-M6H-EMPTY-BASELINE FIX: With stub baseline (samples=[]),
