class AdaptiveExtractionDecisionEngine:
    """
    Scores each extraction technique based on environmental factors and
    automatically selects the one with highest success probability.

    Factors considered:
      - Detection technique (B/E/U/T/S/O)
      - WAF presence and type
      - DBMS identified
      - Response stability (baseline variance)
      - Available channels (timing, boolean, error, OOB)
      - Past extraction success/failure history
      - Network conditions (latency, jitter)
      - Rate limiting detection
      - Cache behavior observed

    Returns a ranked list of extraction methods to try in order.
    """

    # Technique compatibility matrix: which extraction methods work with which
    # detection techniques. Higher score = better compatibility.
    COMPATIBILITY = {
        #                     Fast  GrpConcat Chameleon Adaptive Bitwise Parallel TimeBased ZK  Cache  Compress
        "E":  {"fast": 0.95, "gc": 0.10, "cham": 0.20, "adapt": 0.15, "bit": 0.30, "par": 0.25, "time": 0.05, "zk": 0.10, "cache": 0.15, "compress": 0.15},
        "U":  {"fast": 0.90, "gc": 0.95, "cham": 0.20, "adapt": 0.15, "bit": 0.30, "par": 0.25, "time": 0.05, "zk": 0.10, "cache": 0.15, "compress": 0.15},
        "B":  {"fast": 0.10, "gc": 0.05, "cham": 0.85, "adapt": 0.80, "bit": 0.75, "par": 0.70, "time": 0.15, "zk": 0.65, "cache": 0.50, "compress": 0.45},
        "T":  {"fast": 0.05, "gc": 0.05, "cham": 0.10, "adapt": 0.10, "bit": 0.10, "par": 0.10, "time": 0.90, "zk": 0.80, "cache": 0.20, "compress": 0.15},
        "S":  {"fast": 0.30, "gc": 0.10, "cham": 0.15, "adapt": 0.10, "bit": 0.15, "par": 0.10, "time": 0.80, "zk": 0.70, "cache": 0.15, "compress": 0.10},
        "O":  {"fast": 0.05, "gc": 0.05, "cham": 0.05, "adapt": 0.05, "bit": 0.05, "par": 0.05, "time": 0.10, "zk": 0.05, "cache": 0.05, "compress": 0.05},
        "HQ": {"fast": 0.05, "gc": 0.05, "cham": 0.10, "adapt": 0.10, "bit": 0.10, "par": 0.10, "time": 0.85, "zk": 0.75, "cache": 0.20, "compress": 0.15},
        "BH": {"fast": 0.05, "gc": 0.05, "cham": 0.70, "adapt": 0.65, "bit": 0.60, "par": 0.55, "time": 0.10, "zk": 0.50, "cache": 0.40, "compress": 0.35},
        "EH": {"fast": 0.70, "gc": 0.10, "cham": 0.20, "adapt": 0.15, "bit": 0.25, "par": 0.20, "time": 0.05, "zk": 0.10, "cache": 0.10, "compress": 0.10},
        "TH": {"fast": 0.05, "gc": 0.05, "cham": 0.10, "adapt": 0.10, "bit": 0.10, "par": 0.10, "time": 0.85, "zk": 0.75, "cache": 0.15, "compress": 0.10},
        "IN": {"fast": 0.50, "gc": 0.10, "cham": 0.75, "adapt": 0.70, "bit": 0.65, "par": 0.60, "time": 0.10, "zk": 0.55, "cache": 0.40, "compress": 0.35},
    }

    # WAF penalty factors  some methods are more likely to be blocked by specific WAFs
    WAF_PENALTY = {
        "Cloudflare":  {"fast": 0.3, "gc": 0.4, "time": 0.5, "cache": 0.1, "compress": 0.1},
        "AWS WAF":     {"fast": 0.4, "gc": 0.5, "time": 0.4, "cache": 0.1, "compress": 0.1},
        "Imperva":     {"fast": 0.5, "gc": 0.6, "time": 0.6, "cache": 0.1, "compress": 0.2},
        "ModSecurity": {"fast": 0.3, "gc": 0.3, "time": 0.3, "cache": 0.0, "compress": 0.0},
        "Akamai":      {"fast": 0.4, "gc": 0.5, "time": 0.5, "cache": 0.2, "compress": 0.1},
    }

    @classmethod
    def rank_methods(cls, technique: str, waf_name: str = "",
                      baseline_variance: float = 0.0,
                      has_timing: bool = False) -> List[Tuple[str, float]]:
        """
        Return ranked list of (method_name, score) tuples, highest score first.

        The decision engine considers:
          1. Base compatibility between detection technique and extraction method
          2. WAF-specific penalty (some methods get blocked more by certain WAFs)
          3. Baseline variance bonus (noisy pages benefit from cache/compression)
          4. Timing availability bonus (if timing works, time-based gets boost)
        """
        compat = cls.COMPATIBILITY.get(technique, cls.COMPATIBILITY["B"])
        scores = {}

        for method, base_score in compat.items():
            score = base_score

            # Apply WAF penalty
            if waf_name:
                for waf_key, penalties in cls.WAF_PENALTY.items():
                    if waf_key.lower() in waf_name.lower():
                        penalty = penalties.get(method, 0.0)
                        score *= (1.0 - penalty)
                        break

            # Noisy baseline bonus for cache/compression oracles
            if baseline_variance > 0.15 and method in ("cache", "compress"):
                score *= 1.3  # Noisy pages make body-based extraction unreliable

            # Timing availability bonus
            if has_timing and method in ("time", "zk"):
                score *= 1.2

            scores[method] = min(1.0, score)

        # Sort by score descending
        ranked = sorted(scores.items(), key=lambda x: -x[1])
        return ranked

    @classmethod
    def get_best_method(cls, technique: str, waf_name: str = "",
                         baseline_variance: float = 0.0,
                         has_timing: bool = False) -> str:
        """Return the name of the best extraction method."""
        ranked = cls.rank_methods(technique, waf_name, baseline_variance, has_timing)
        return ranked[0][0] if ranked else "adapt"



