        for priv_name, priv_query in cls.PRIV_CHECKS.get(dbms, []):
            chain.append({
                "step": "privilege_check",
                "name": priv_name,
                "query": priv_query,
            })
        # Step 2: Attempt OS command execution
        for cmd_tmpl in cls.OS_CMD_TEMPLATES.get(dbms, []):
            chain.append({
                "step": "os_command",
                "template": cmd_tmpl,
                "test_cmd": "id" if dbms != "MSSQL" else "whoami",
            })
