#  v23-14: API Version Exploitation 

class APIVersionExploiter:
    """Tests same endpoint across API versions. Older versions often
    lack security patches and WAF rules.
    """

    VERSION_PREFIXES = [
        "/v1", "/v2", "/v3", "/api/v1", "/api/v2", "/api/v3",
        "/api", "/rest", "/graphql", "/v1.0", "/v2.0",
        "/api/1.0", "/api/2.0", "/internal", "/legacy",
    ]

    @classmethod
    def generate_versioned_urls(cls, url: str) -> List[str]:
        """Generate URL variants with different API version prefixes."""
        from urllib.parse import urlparse, urlunparse
        parsed = urlparse(url)
        # Strip existing version prefix
        path = parsed.path
        clean_path = re.sub(r'^/(?:api/)?v\d+(?:\.\d+)?', '', path)
        if not clean_path:
            clean_path = "/"
        variants = []
        for prefix in cls.VERSION_PREFIXES:
            new_path = prefix + clean_path
            new_url = urlunparse(parsed._replace(path=new_path))
            if new_url != url:
                variants.append(new_url)
        return variants


