def _apply_config_file(config: "Config", args) -> "Config":
    """
    Load a YAML / TOML / JSON config file and merge its values into config.
    Config file keys mirror long-form CLI flag names (hyphens  underscores).
    CLI flags always take precedence over config file values.

    Example config.yaml:
      level: 5
      technique: BEUTS
      delay: 1.0
      batch: true
      dbs: true
    """
    config_path = getattr(args, "config", None)
    if not config_path:
        for _dp in ConfigFileLoader.DEFAULT_PATHS:
            if _dp.exists():
                config_path = str(_dp)
                LOG.info(f"Auto-loaded config: {_dp}")
                break
    if not config_path:
        return config

    cfg_path = Path(config_path)
    if not cfg_path.exists():
        LOG.warning(f"Config file not found: {config_path}")
        return config

    try:
        raw_text = cfg_path.read_text(encoding="utf-8")

        # Parse format based on extension
        ext = cfg_path.suffix.lower()
        data: Dict = {}

        if ext in (".yaml", ".yml"):
            # Simple YAML parser (no pyyaml dependency required)
            for line in raw_text.splitlines():
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if ": " in line:
                    k, v = line.split(": ", 1)
                    k = k.strip().replace("-", "_")
                    v = v.strip().strip('"').strip("'")
                    # Type coercion
                    if v.lower() == "true":   v = True
                    elif v.lower() == "false":v = False
                    else:
                        try:    v = int(v)
                        except ValueError:
                            try:    v = float(v)
                            except ValueError: pass
                    data[k] = v

        elif ext == ".toml":
            try:
                import tomllib  # Python 3.11+
                data = tomllib.loads(raw_text)
            except ImportError:
                try:
                    import tomli as tomllib  # pip install tomli
                    data = tomllib.loads(raw_text)
                except ImportError:
                    LOG.warning("TOML support requires Python 3.11+ or: pip install tomli")
                    return config

        elif ext == ".json":
            data = json.loads(raw_text)

        else:
            # Try JSON first, then YAML-style
            try:
                data = json.loads(raw_text)
            except json.JSONDecodeError:
                for line in raw_text.splitlines():
                    line = line.strip()
                    if ": " in line and not line.startswith("#"):
                        k, v = line.split(": ", 1)
                        data[k.strip().replace("-","_")] = v.strip()

        # Merge: CLI args always win over config file values.
        # We detect explicit CLI args by scanning sys.argv for the flag.
        # This is necessary because argparse cannot distinguish "user set this"
        # from "this is the argparse default" without a custom Action class.
        import sys as _sys
        _argv_str = " ".join(_sys.argv[1:])
        # Short-flag map for common options
        _short_map = {
            "url": "-u", "output": "-o", "verbose": "-v",
            "db": "-D", "table": "-T", "cols": "-C",
            "request": "-r", "multiple": "-m",
        }
        for key, val in data.items():
            key = key.replace("-", "_")
            # Build the long-form flag for this key
            _long_flag  = "--" + key.replace("_", "-")
            _short_flag = _short_map.get(key, "")
            # Skip if the user passed this flag on the command line
            # Use word-boundary check to avoid --db matching --dbs
            _cli_set = (bool(_re.search(rf'(?:^|\s){_re.escape(_long_flag)}(?:\s|=|$)', _argv_str)) or
                        bool(_short_flag and _re.search(rf'(?:^|\s){_re.escape(_short_flag)}(?:\s|$)', _argv_str)))
            if _cli_set:
                LOG.debug(f"Config file: {key!r} skipped  CLI flag takes precedence")
                continue
            try:
                setattr(config, key, val)
                LOG.debug(f"Config file: {key} = {val!r}")
            except Exception as _cfg_e:
                LOG.debug(f"Config file: failed to set {key!r} = {val!r}: {_cfg_e}")

        LOG.info(f"Loaded config file: {config_path} ({len(data)} keys)")

    except Exception as e:
        LOG.warning(f"Config file parse error ({config_path}): {e}")

    return config


# 
#   S Q L R E A P E R  v 1 6  N E W  F E A T U R E S  
# 
#
#  1. TokenBucketRateLimiter    proper burst-aware rate limiting
#  2. SessionIntegritySigner    HMAC-SHA256 session file signing
#  3. SensitiveDataClassifier   PII / credential / API-key detection
#  4. SARIF21Reporter            full SARIF v2.1 with physical locations + rules
#  5. HTMLReportV2              Bootstrap 5 report with charts and CVSS badges
#  6. NucleiTemplateGenerator   generate Nuclei YAML from a confirmed finding
#  7. BurpRepeaterExporter      export HTTP request in Burp Suite XML format
#  8. RateLimitDetector         detect 429 / WAF backoff and auto-adjust delay
#  9. AdaptiveBaselineManager   per-endpoint adaptive baseline with drift guard
# 10. SecureCompressedSession   CompressedSession with HMAC integrity
# 


# 
# 1.  TOKEN BUCKET RATE LIMITER
#     Replaces the nave asyncio.sleep(delay) with a proper token-bucket
#     algorithm that absorbs small bursts while enforcing a long-term rate cap.
#     The scanner uses this to stay below a target requests-per-second rate
#     without introducing unnecessary latency on slow pages.
# 

class TokenBucketRateLimiter:
    """
    Token-bucket rate limiter for asyncio.

    Parameters
    ----------
    rate : float
        Tokens ( requests) added per second.
    burst : int
        Maximum number of tokens that can accumulate (burst capacity).
    min_delay : float
        Hard minimum seconds between any two requests (floor for jitter).

    Algorithm
    ---------
    Each request consumes one token. Tokens are added at `rate` tokens/sec up
    to `burst` maximum. When the bucket is empty the caller awaits until a
    token is available.  Because it uses time-based replenishment rather than
    a fixed sleep, a caller that makes requests slowly will accumulate tokens
    up to `burst`, allowing occasional fast bursts without violating the
    long-term rate.

    Usage
    -----
        limiter = TokenBucketRateLimiter(rate=5.0, burst=10)
        async with limiter:
            response = await http_get(url)
    """

    def __init__(self, rate: float = 10.0, burst: int = 20,
                 min_delay: float = 0.0):
        self._rate      = max(rate, 0.01)
        self._burst     = max(burst, 1)
        self._tokens    = float(burst)     # start full
        self._last_refill = time.monotonic()
        self._min_delay = min_delay
        self._last_req  = 0.0
        self._lock      = asyncio.Lock()
        self._total_waits = 0
        self._total_wait_sec = 0.0

    def _refill(self):
        now     = time.monotonic()
        elapsed = now - self._last_refill
        self._tokens = min(self._burst,
                           self._tokens + elapsed * self._rate)
        self._last_refill = now

    async def acquire(self):
        """Block until a token is available."""
        # BUG-TOKEN-BUCKET-LOCK FIX: The original code held the asyncio Lock while
        # sleeping for min_delay. Since asyncio.sleep() yields to the event loop
        # but does NOT release the Lock, all concurrent acquire() callers were
        # blocked during min_delay sleep even if tokens were available, serializing
        # parallel requests and reducing throughput to 1/min_delay req/s.
        # Fix: perform the token consumption inside the lock, then release the lock
        # BEFORE sleeping for min_delay. Record last_req before sleep to prevent
        # drift from sleep inaccuracy.
        _gap_to_sleep = 0.0
        async with self._lock:
            while True:
                self._refill()
                if self._tokens >= 1.0:
                    self._tokens -= 1.0
                    now = time.monotonic()
                    _gap_to_sleep = max(0.0, self._min_delay - (now - self._last_req))
                    self._last_req = now + _gap_to_sleep
                    break  # release lock before sleeping
                wait = (1.0 - self._tokens) / self._rate
                self._total_waits += 1
                self._total_wait_sec += wait
                await asyncio.sleep(wait)
        # Sleep OUTSIDE the lock so other coroutines can acquire tokens concurrently
        if _gap_to_sleep > 0:
            await asyncio.sleep(_gap_to_sleep)

    async def __aenter__(self):
        await self.acquire()
        return self

    async def __aexit__(self, *_):
        pass

    def update_rate(self, new_rate: float):
        """Dynamically adjust rate (e.g. after detecting 429 responses)."""
        self._rate = max(new_rate, 0.01)
        LOG.debug(f"TokenBucket: rate updated to {self._rate:.2f} req/s")

    @property
    def stats(self) -> Dict[str, Any]:
        return {
            "rate_rps":       round(self._rate, 3),
            "burst":          self._burst,
            "tokens_now":     round(self._tokens, 2),
            "total_waits":    self._total_waits,
            "total_wait_sec": round(self._total_wait_sec, 2),
        }


# 
# 2.  SESSION INTEGRITY SIGNER
#     Signs session JSON with HMAC-SHA256 so a tampered or corrupt session
#     file is detected at load time rather than silently producing wrong data.
# 

class SessionIntegritySigner:
    """
    HMAC-SHA256 signer/verifier for ScanSession JSON files.

    The signature is appended as a standalone JSON file:
        <session_id>.session.sig

    The HMAC key defaults to the SHA-256 hash of the session_id, making it
    machine-specific without requiring a user-supplied secret.  A caller that
    wants a proper secret can pass one via ``key``.

    Usage
    -----
        signer = SessionIntegritySigner()
        signer.sign(path_to_session_json)
        ok, reason = signer.verify(path_to_session_json)
    """

    SIG_SUFFIX = ".sig"

    def __init__(self, key: Optional[bytes] = None):
        self._key = key  # None  derived from session_id at sign time

    def _derive_key(self, session_id: str) -> bytes:
        return hashlib.sha256(f"sqr-session-{session_id}".encode()).digest()

    def _compute(self, data: bytes, key: bytes) -> str:
        return hmac.new(key, data, hashlib.sha256).hexdigest()

    def sign(self, session_path: str) -> str:
        """Write a .sig file alongside the session file. Returns sig hex."""
        path = Path(session_path)
        raw  = path.read_bytes()
        try:
            sid = json.loads(raw).get("session_id", "")
        except Exception:
            sid = ""
        key = self._key or self._derive_key(sid)
        sig = self._compute(raw, key)
        sig_path = Path(str(path) + self.SIG_SUFFIX)
        sig_path.write_text(
            json.dumps({"algorithm": "hmac-sha256", "sig": sig,
                        "signed_at": datetime.now(timezone.utc).isoformat()}),
            encoding="utf-8")
        LOG.debug(f"Session signed  {sig_path}")
        return sig

    def verify(self, session_path: str) -> Tuple[bool, str]:
        """
        Verify the HMAC signature of a session file.
        Returns (ok, reason) where reason is empty on success.
        """
        path     = Path(session_path)
        sig_path = Path(str(path) + self.SIG_SUFFIX)

        if not sig_path.exists():
            return True, ""   # No sig file  legacy session, accept without check

        raw = path.read_bytes()
        try:
            sig_doc = json.loads(sig_path.read_text(encoding="utf-8"))
            stored  = sig_doc.get("sig", "")
        except Exception as e:
            return False, f"Corrupt .sig file: {e}"

        try:
            sid = json.loads(raw).get("session_id", "")
        except Exception:
            sid = ""

        key      = self._key or self._derive_key(sid)
        expected = self._compute(raw, key)

        if not hmac.compare_digest(expected, stored):
            return False, ("HMAC mismatch  session file may have been "
                           "tampered with or corrupted. "
                           "Use --flush to start fresh.")
        return True, ""


class SecureCompressedSession(CompressedSession):
    """
    CompressedSession that signs every save with HMAC-SHA256 and verifies
    integrity on load.  Raises SessionError on tamper/corruption detection.
    """

    def __init__(self, config: Config, signer: Optional[SessionIntegritySigner] = None):
        super().__init__(config)
        self._signer = signer or SessionIntegritySigner()

    def save(self):
        super().save()
        # Sign the plain .session file if it exists (fallback path)
        plain = Path(str(self.session_file))
        gz    = Path(str(self.session_file) + ".gz")
        target = gz if gz.exists() else plain
        if target.exists():
            try:
                self._signer.sign(str(target))
            except Exception as e:
                LOG.debug(f"Session sign error: {e}")

    def load(self, path: str):
        ok, reason = self._signer.verify(path)
        if not ok:
            raise SessionError(f"Session integrity check failed: {reason}")
        super().load(path)


# 
# 3.  SENSITIVE DATA CLASSIFIER
#     Scans extracted strings (column values, error messages, response bodies)
#     for PII, credentials, API keys, and other sensitive data classes.
#     Called by the Enumerator and the Reporter to flag high-value findings.
# 

@dataclass
class SensitiveMatch:
    category:    str          # e.g. "password_hash", "api_key", "email"
    pattern_id:  str          # internal rule id
    value:       str          # matched/redacted value snippet
    risk:        str          # "CRITICAL" / "HIGH" / "MEDIUM" / "LOW"
    confidence:  float        # 0.0  1.0


class SensitiveDataClassifier:
    """
    Classifies strings for sensitive data using regex patterns derived from
    common formats and known credential/PII shapes.

    Categories (with risk levels):
      CRITICAL: bcrypt/argon2 hashes, private keys, JWT secrets, AWS credentials
      HIGH:     MD5/SHA1 hashes, API keys, OAuth tokens, DB connection strings
      MEDIUM:   Email addresses, phone numbers, SSN-like patterns
      LOW:      Generic high-entropy strings, UUIDs, internal paths

    Usage
    -----
        clf = SensitiveDataClassifier()
        matches = clf.classify_row({"password": "$2b$12$abc...", "email": "u@ex.com"})
        for m in matches:
            print(m.category, m.risk, m.value[:20])
    """

    # (pattern_id, category, risk, regex, min_confidence)
    RULES: List[Tuple[str, str, str, str, float]] = [
        #  CRITICAL 
        ("bcrypt",        "password_hash",   "CRITICAL",
         r"^\$2[aby]\$\d{2}\$.{53}$",         0.99),
        ("argon2",        "password_hash",   "CRITICAL",
         r"^\$argon2(id?|d)\$v=\d+\$",        0.99),
        ("pbkdf2",        "password_hash",   "CRITICAL",
         r"^pbkdf2_sha(256|512)\$\d+\$",      0.97),
        ("scrypt_hash",   "password_hash",   "CRITICAL",
         r"^\$s0\$[0-9a-f]+\$",               0.97),
        ("rsa_key",       "private_key",     "CRITICAL",
         r"-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----",  0.99),
        ("aws_secret",    "cloud_credential","CRITICAL",
         r"(?i)aws_secret_access_key\s*[=:]\s*[A-Za-z0-9/+]{40}",  0.96),
        ("aws_access",    "cloud_credential","CRITICAL",
         r"\bAKIA[0-9A-Z]{16}\b",             0.96),
        ("gcp_key",       "cloud_credential","CRITICAL",
         r'"type":\s*"service_account"',       0.95),
        ("db_connstr",    "db_credential",   "CRITICAL",
         r"(?i)(mysql|postgres|mssql|mongodb|redis)://[^@\s]+:[^@\s]+@",  0.95),

        #  HIGH 
        ("md5_hash",      "password_hash",   "HIGH",
         r"^[0-9a-f]{32}$",                   0.70),
        ("sha1_hash",     "password_hash",   "HIGH",
         r"^[0-9a-f]{40}$",                   0.70),
        ("sha256_hash",   "password_hash",   "HIGH",
         r"^[0-9a-f]{64}$",                   0.75),
        ("jwt_token",     "auth_token",      "HIGH",
         r"^eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*$",  0.97),
        ("github_pat",    "api_key",         "HIGH",
         r"ghp_[A-Za-z0-9]{36}",              0.98),
        ("github_oauth",  "api_key",         "HIGH",
         r"gho_[A-Za-z0-9]{36}",              0.98),
        ("stripe_key",    "api_key",         "HIGH",
         r"sk_(live|test)_[A-Za-z0-9]{24,}",  0.98),
        ("slack_token",   "api_key",         "HIGH",
         r"xox[bpoas]-[A-Za-z0-9\-]{10,}",    0.96),
        ("google_api",    "api_key",         "HIGH",
         r"AIza[0-9A-Za-z\-_]{35}",           0.97),
        ("twilio_sid",    "api_key",         "HIGH",
         r"\bAC[0-9a-f]{32}\b",               0.90),
        ("sendgrid",      "api_key",         "HIGH",
         r"SG\.[A-Za-z0-9\-_]{22}\.[A-Za-z0-9\-_]{43}",  0.98),
        ("cleartext_pw",  "plaintext_password","HIGH",
         r"(?i)(password|passwd|pwd|secret)\s*[=:]\s*\S{6,}",  0.80),

        #  MEDIUM 
        ("email",         "pii_email",       "MEDIUM",
         r"\b[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Z|a-z]{2,}\b",  0.92),
        ("us_ssn",        "pii_ssn",         "MEDIUM",
         r"\b\d{3}-\d{2}-\d{4}\b",            0.85),
        ("us_phone",      "pii_phone",       "MEDIUM",
         r"\b(\+1[\s.\-]?)?\(?\d{3}\)?[\s.\-]?\d{3}[\s.\-]?\d{4}\b",  0.75),
        ("credit_card",   "pii_pci",         "MEDIUM",
         r"\b(?:4[0-9]{12}(?:[0-9]{3})?|5[1-5][0-9]{14}|3[47][0-9]{13})\b",  0.88),
        ("ipv4_private",  "internal_ip",     "MEDIUM",
         r"\b(10\.\d+\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+|192\.168\.\d+\.\d+)\b",  0.80),
        ("unix_path",     "filesystem_path", "LOW",
         r"(?<!\w)(/etc/passwd|/etc/shadow|/root/|/home/\w+/)",  0.92),
        ("win_path",      "filesystem_path", "LOW",
         r"(?i)C:\\(Windows|Users|Program Files|inetpub)",  0.88),
    ]

    def __init__(self):
        self._compiled: List[Tuple[str, str, str, re.Pattern, float]] = []
        for pid, cat, risk, pattern, conf in self.RULES:
            try:
                self._compiled.append((pid, cat, risk, re.compile(pattern), conf))
            except re.error as e:
                LOG.debug(f"SensitiveDataClassifier: bad regex {pid!r}: {e}")

    def classify_string(self, value: str) -> List[SensitiveMatch]:
        """Check a single string value against all rules."""
        matches: List[SensitiveMatch] = []
        v = value.strip()
        if not v:
            return matches
        for pid, cat, risk, pat, conf in self._compiled:
            if pat.search(v):
                # Redact the matched value for safe logging
                redacted = v[:6] + "[REDACTED]" if len(v) > 6 else "[REDACTED]"
                matches.append(SensitiveMatch(
                    category=cat, pattern_id=pid,
                    value=redacted, risk=risk, confidence=conf))
        return matches

    def classify_row(self, row: Dict[str, str]) -> List[SensitiveMatch]:
        """Classify all values in a database row dict."""
        all_matches: List[SensitiveMatch] = []
        for col, val in row.items():
            for m in self.classify_string(str(val)):
                all_matches.append(m)
        return all_matches

    def classify_data_dict(self, data: Dict) -> Dict[str, List[SensitiveMatch]]:
        """
        Walk an extracted data dict (session.data) and classify every string value.
        Returns {path: [matches]} where path is e.g. 'dump.users[0].password'.
        """
        results: Dict[str, List[SensitiveMatch]] = {}
        self._walk(data, "", results)
        return results

    def _walk(self, obj: Any, prefix: str, out: Dict[str, List[SensitiveMatch]]):
        if isinstance(obj, dict):
            for k, v in obj.items():
                self._walk(v, f"{prefix}.{k}" if prefix else str(k), out)
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                self._walk(v, f"{prefix}[{i}]", out)
        elif isinstance(obj, str):
            ms = self.classify_string(obj)
            if ms:
                out[prefix] = ms

    def summary_report(self, data: Dict) -> str:
        """Return a concise text summary of sensitive findings."""
        classified = self.classify_data_dict(data)
        if not classified:
            return "No sensitive data patterns detected in extracted data."
        lines = ["Sensitive Data Classification:"]
        critical = [(p, ms) for p, ms in classified.items()
                    if any(m.risk == "CRITICAL" for m in ms)]
        high     = [(p, ms) for p, ms in classified.items()
                    if any(m.risk == "HIGH" for m in ms) and
                    not any(m.risk == "CRITICAL" for m in ms)]
        other    = [(p, ms) for p, ms in classified.items()
                    if p not in dict(critical) and p not in dict(high)]
        for label, items in [(" CRITICAL", critical),
                              (" HIGH",     high),
                              (" OTHER",    other)]:
            if items:
                lines.append(f"\n  {label} ({len(items)} fields):")
                for path, ms in items[:10]:
                    cats = ", ".join({m.category for m in ms})
                    lines.append(f"     {path}: {cats}")
        return "\n".join(lines)


# 
# 4.  SARIF v2.1 REPORTER
#     Full SARIF 2.1.0 output with per-finding physicalLocation, rule metadata,
#     CVSS properties, and suppression support.  Suitable for direct import into
#     GitHub Code Scanning, Azure DevOps Security, and SonarQube.
# 

class SARIF21Reporter:
    """
    Generates SARIF 2.1.0 output from confirmed injection findings.

    Conforms to: https://docs.oasis-open.org/sarif/sarif/v2.1.0/sarif-v2.1.0.html

    Each finding becomes one SARIF Result with:
      - ruleId mapped to the injection technique (SQLI-B, SQLI-E, SQLI-U, )
      - level: error for CRITICAL/HIGH CVSS, warning for MEDIUM, note for LOW
      - physicalLocation: URI derived from the target URL
      - properties: CVSS score, vector, DBMS, confidence, payload hash
      - fingerprints: deterministic SHA-256 of (url+param+technique)
    """

    SCHEMA = "https://schemastore.azurewebsites.net/schemas/json/sarif-2.1.0.json"
    VERSION = "2.1.0"
    TOOL_NAME = "SQLReaper"
    TOOL_VERSION = "19.0"
    TOOL_URI = "https://github.com/sqlreaper/sqlreaper"

    # SARIF level per CVSS severity
    _LEVEL_MAP = {"CRITICAL": "error", "HIGH": "error",
                  "MEDIUM": "warning", "LOW": "note", "NONE": "note"}

    # One rule definition per technique code
    _RULES = {
        "B":  ("SQLI-B",  "Boolean-Based Blind SQL Injection",
               "The parameter is injectable via boolean conditions that produce "
               "different application responses for true vs false predicates."),
        "E":  ("SQLI-E",  "Error-Based SQL Injection",
               "The parameter causes the database to emit diagnostic errors "
               "containing query results, leaking data in the HTTP response."),
        "U":  ("SQLI-U",  "UNION-Based SQL Injection",
               "The parameter allows UNION SELECT to append rows to the "
               "original result set, enabling direct data extraction."),
        "T":  ("SQLI-T",  "Time-Based Blind SQL Injection",
               "The parameter controls database sleep/delay functions, "
               "creating a timing oracle for data extraction without visible output."),
        "S":  ("SQLI-S",  "Stacked-Query SQL Injection",
               "The parameter allows execution of additional SQL statements via "
               "statement terminators (;), enabling full DML/DDL control."),
        "N":  ("SQLI-N",  "NoSQL Injection",
               "The endpoint is vulnerable to NoSQL operator injection "
               "(MongoDB $where, $ne, $gt, etc.)."),
        "O":  ("SQLI-O",  "Out-of-Band SQL Injection",
               "The parameter triggers DNS/HTTP callbacks to an external server, "
               "enabling data exfiltration without in-band response."),
        "X":  ("XXE-001", "XML External Entity Injection",
               "The application parses attacker-controlled XML and resolves "
               "external entity references, enabling file read and SSRF."),
        "L":  ("LDAP-I",  "LDAP Injection",
               "User-supplied data is interpolated into LDAP filter expressions "
               "without sanitisation, allowing filter manipulation."),
        "I":  ("SSTI-001","Server-Side Template Injection",
               "User input is rendered inside a template engine context "
               "without sandboxing, enabling arbitrary code execution."),
        "P":  ("PROTO-P", "Prototype Pollution",
               "User-controlled JSON keys pollute Object.prototype, "
               "enabling property injection and potential authentication bypass."),
    }

    def __init__(self, output_dir: str = "./output"):
        self.output_dir = Path(output_dir)

    def _uri_from_url(self, url: str) -> str:
        """Normalise URL to a URI suitable for physicalLocation.artifactLocation."""
        try:
            p = urlparse(url)
            return f"{p.scheme}://{p.netloc}{p.path}"
        except Exception:
            return url

    def _fingerprint(self, url: str, param: str, technique: str) -> str:
        raw = f"{self._uri_from_url(url)}|{param}|{technique}"
        return hashlib.sha256(raw.encode()).hexdigest()

    def _payload_hash(self, payload: str) -> str:
        return hashlib.sha256(payload.encode()).hexdigest()[:16]

    def generate(self, vulns: List[Dict], session: "ScanSession") -> Dict:
        """Build and return the full SARIF document as a Python dict."""
        # Collect unique rule IDs used
        used_rule_ids: Set[str] = set()
        results: List[Dict] = []

        for v in vulns:
            technique = v.get("technique", "B")
            rule_info = self._RULES.get(technique, self._RULES["B"])
            rule_id, _, _ = rule_info
            used_rule_ids.add(technique)

            url     = v.get("url", session.config.url or "")
            param   = v.get("parameter", "")
            payload = v.get("payload", "")
            sev     = v.get("cvss_severity", "HIGH")
            score   = v.get("cvss_score", 7.0)
            vec     = v.get("cvss_vector", "")
            conf    = v.get("confidence", 0.0)
            dbms    = v.get("dbms", "")
            ts      = v.get("timestamp", datetime.now(timezone.utc).isoformat())

            results.append({
                "ruleId":  rule_id,
                "level":   self._LEVEL_MAP.get(sev, "error"),
                "message": {
                    "text": (
                        f"SQL Injection in parameter '{param}' via {technique} technique. "
                        f"DBMS: {dbms or 'unknown'}. "
                        f"CVSS: {score} ({sev}). "
                        f"Payload hash: {self._payload_hash(payload)}."
                    )
                },
                "locations": [{
                    "physicalLocation": {
                        "artifactLocation": {
                            "uri": self._uri_from_url(url),
                            "uriBaseId": "%SRCROOT%",
                        },
                        "region": {
                            "startLine": 1,   # No source line available
                            "snippet": {"text": f"param={param}"},
                        }
                    },
                    "logicalLocations": [{
                        "name": param,
                        "kind": "parameter",
                        "fullyQualifiedName": f"{self._uri_from_url(url)}#{param}",
                    }]
                }],
                "fingerprints": {
                    "primaryLocationLineHash/v1":
                        self._fingerprint(url, param, technique),
                },
                "properties": {
                    "confidence":    round(conf, 3),
                    "cvss_score":    score,
                    "cvss_severity": sev,
                    "cvss_vector":   vec,
                    "dbms":          dbms,
                    "technique":     technique,
                    "payload_hash":  self._payload_hash(payload),
                    "timestamp":     ts,
                },
            })

        # Build rule descriptors for every technique used
        rules = []
        for technique in sorted(used_rule_ids):
            if technique not in self._RULES:
                continue
            rule_id, name, desc = self._RULES[technique]
            rules.append({
                "id":   rule_id,
                "name": name.replace(" ", ""),
                "shortDescription": {"text": name},
                "fullDescription":  {"text": desc},
                "helpUri": "https://owasp.org/www-community/attacks/SQL_Injection",
                "properties": {
                    "tags": ["security", "sql-injection", "injection",
                             technique.lower()],
                    "problem.severity": "error",
                    "security-severity": "9.8",
                },
                "defaultConfiguration": {"level": "error"},
            })

        sarif: Dict = {
            "$schema": self.SCHEMA,
            "version": self.VERSION,
            "runs": [{
                "tool": {
                    "driver": {
                        "name":            self.TOOL_NAME,
                        "version":         self.TOOL_VERSION,
                        "informationUri":  self.TOOL_URI,
                        "semanticVersion": self.TOOL_VERSION,
                        "rules":           rules,
                        "properties": {
                            "scanDate": datetime.now(timezone.utc).isoformat(),
                            "target":   session.config.url or "",
                            "dbms":     session.dbms or "unknown",
                            "waf":      (session.waf_info or {}).get("name", "none"),
                            "requests": session.requests_sent,
                        },
                    }
                },
                "results":    results,
                "artifacts":  [{
                    "location": {"uri": self._uri_from_url(session.config.url or "")},
                    "roles": ["analysisTarget"],
                }],
                "invocations": [{
                    "executionSuccessful": True,
                    "commandLine": f"sqlreaper -u {session.config.url or ''}",
                    "startTimeUtc": datetime.fromtimestamp(
                        session.created_at, tz=timezone.utc).isoformat(),
                    "endTimeUtc": datetime.now(timezone.utc).isoformat(),
                }],
            }],
        }
        return sarif

    def write(self, vulns: List[Dict], session: "ScanSession",
              path: Optional[str] = None) -> Path:
        """Write the SARIF document to disk. Returns the output path."""
        self.output_dir.mkdir(parents=True, exist_ok=True)
        out = Path(path) if path else (
            self.output_dir / f"sqlreaper_{session.session_id}.sarif")
        doc = self.generate(vulns, session)
        tmp = str(out) + ".tmp"
        # TODO: Replace with aiofiles for async I/O
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(doc, f, indent=2, default=str)
        os.replace(tmp, out)
        LOG.info(f"SARIF v2.1 report  {out} "
                 f"({len(vulns)} finding(s), {len(doc['runs'][0]['rules'])} rules)")
        return out


# 
# 5.  HTML REPORT v2
#     Bootstrap 5-based report with Chart.js visualisations, CVSS severity
#     heat-map, technique distribution chart, and extracted data tables.
#     Self-contained single HTML file  no external assets required at view time
#     because Bootstrap and Chart.js are loaded from CDNs inside the file with
#     integrity hashes, and all extracted data is embedded as inline JSON.
# 

class HTMLReportV2:
    """
    Generates a standalone Bootstrap 5 HTML report.

    Sections
    --------
    1. Header bar  target, scan date, DBMS/WAF badge
    2. Executive metrics row  vulnerability count, highest CVSS, tech spread
    3. Technique distribution doughnut chart (Chart.js)
    4. CVSS severity heat-map bar chart
    5. Findings table  sortable, colour-coded by severity
    6. Database schema tree
    7. Extracted data tables (dump)
    8. Sensitive data findings (if SensitiveDataClassifier ran)
    9. Remediation guidance per DBMS
    10. Raw JSON evidence (collapsible)
    """

    _SEVERITY_COLORS = {
        "CRITICAL": "#7c3aed", "HIGH": "#ef4444",
        "MEDIUM": "#f59e0b",   "LOW": "#3b82f6", "NONE": "#6b7280"
    }
    _TECHNIQUE_COLORS = {
        "B": "#3b82f6", "E": "#ef4444", "U": "#8b5cf6",
        "T": "#f59e0b", "S": "#10b981", "N": "#ec4899",
        "O": "#0ea5e9", "X": "#84cc16", "L": "#a78bfa",
        "I": "#fb923c", "P": "#14b8a6",
    }
    _TECHNIQUE_NAMES = {
        "B": "Boolean Blind", "E": "Error-Based", "U": "UNION",
        "T": "Time-Based",    "S": "Stacked",     "N": "NoSQL",
        "O": "Out-of-Band",   "X": "XXE",         "L": "LDAP",
        "I": "SSTI",          "P": "Prototype Pollution",
    }

    def generate(self, vulns: List[Dict], session: "ScanSession",
                 sensitive_summary: str = "") -> str:
        """Return the complete HTML document as a string."""
        import html as _html_mod
        _he = _html_mod.escape
        now_str = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        # BUG-HTML-XSS-HEADER FIX: target/dbms/waf go into the HTML hero section
        # without escaping. A URL with < or a DB returning a DBMS name with <script>
        # would execute JS in the report. Apply html.escape() to all three.
        target  = _he(session.config.url or "")
        dbms    = _he(session.dbms or "Unknown")
        waf     = _he((session.waf_info or {}).get("name", "None"))
        reqs    = session.requests_sent

        #  metrics 
        n_vulns = len(vulns)
        max_cvss = max((v.get("cvss_score", 0.0) for v in vulns), default=0.0)
        max_sev  = max(
            (v.get("cvss_severity", "LOW") for v in vulns),
            key=lambda s: {"CRITICAL":4,"HIGH":3,"MEDIUM":2,"LOW":1,"NONE":0}.get(s,0),
            default="NONE")
        techniques_used = sorted(set(v.get("technique","") for v in vulns))

        #  Chart.js data 
        tech_counts: Dict[str, int] = {}
        for v in vulns:
            t = v.get("technique","?")
            tech_counts[t] = tech_counts.get(t, 0) + 1
        chart_labels = json.dumps([self._TECHNIQUE_NAMES.get(t, t)
                                    for t in tech_counts])
        chart_data   = json.dumps(list(tech_counts.values()))
        chart_colors = json.dumps([self._TECHNIQUE_COLORS.get(t, "#6b7280")
                                    for t in tech_counts])

        sev_counts: Dict[str, int] = {}
        for v in vulns:
            s = v.get("cvss_severity", "HIGH")
            sev_counts[s] = sev_counts.get(s, 0) + 1
        sev_order  = ["CRITICAL","HIGH","MEDIUM","LOW","NONE"]
        sev_labels = json.dumps([s for s in sev_order if s in sev_counts])
        sev_data   = json.dumps([sev_counts.get(s, 0) for s in sev_order
                                  if s in sev_counts])
        sev_colors_js = json.dumps([self._SEVERITY_COLORS[s] for s in sev_order
                                      if s in sev_counts])

        #  Finding rows 
        sev_order_idx = {"CRITICAL":0,"HIGH":1,"MEDIUM":2,"LOW":3,"NONE":4}
        sorted_vulns  = sorted(vulns,
            key=lambda v: sev_order_idx.get(v.get("cvss_severity","HIGH"), 5))
        rows_html = ""
        for v in sorted_vulns:
            t     = v.get("technique","")
            sev   = v.get("cvss_severity","HIGH")
            score = v.get("cvss_score", 7.0)
            sc    = self._SEVERITY_COLORS.get(sev, "#6b7280")
            tc    = self._TECHNIQUE_COLORS.get(t, "#6b7280")
            conf  = int(v.get("confidence",0)*100)
            param = v.get("parameter","")
            dbms_ = v.get("dbms","")
            pl    = v.get("payload","")[:80]
            vec   = v.get("cvss_vector","")
            ts    = v.get("timestamp","")[:19]
            # BUG-HTML-XSS FIX: param, payload (pl), dbms, sev are user-controlled strings
            # from the scanned target. Without HTML escaping, a payload like
            # "</code><script>alert(1)</script>" executes JS when the report is opened.
            # Wrap all user-controlled fields with _he() = html.escape().
            _he_param = _he(str(param))
            _he_t     = _he(str(t))
            _he_sev   = _he(str(sev))
            _he_dbms  = _he(str(dbms_))
            _he_pl    = _he(str(pl))
            _he_vec   = _he(str(vec))
            rows_html += f"""
            <tr>
              <td><code class="param">{_he_param}</code></td>
              <td><span class="badge" style="background:{tc}">{_he_t}</span>
                  <small class="text-muted ms-1">{_he(self._TECHNIQUE_NAMES.get(t,''))}</small></td>
              <td><span style="color:{sc};font-weight:700">{score}</span>
                  <span class="badge ms-1" style="background:{sc};font-size:.65rem">{_he_sev}</span></td>
              <td>{_he_dbms}</td>
              <td>
                <div class="progress" style="height:6px">
                  <div class="progress-bar" style="width:{conf}%;background:{sc}"></div>
                </div>
                <small>{conf}%</small>
              </td>
              <td><code class="payload" title="{_he_pl}">{_he_pl[:55]}{"" if len(_he_pl)>55 else ""}</code></td>
              <td title="{_he_vec}"><small class="text-muted">{_he_vec[:40]}{"" if len(_he_vec)>40 else ""}</small></td>
              <td><small class="text-muted">{ts}</small></td>
            </tr>"""

        #  Schema tree 
        data    = session.data
        schema_html = ""
        if data.get("dbs") or data.get("tables"):
            schema_html = '<ul class="schema-tree">'
            for db in (data.get("dbs") or "").split(",") if data.get("dbs") else []:
                db = db.strip()
                if not db: continue
                tbls = data.get("tables",{}).get(db,[])
                if isinstance(tbls, str): tbls = [t.strip() for t in tbls.split(",") if t.strip()]
                schema_html += f'<li class="db-node"> <strong>{_he(str(db))}</strong>'
                if tbls:
                    schema_html += "<ul>"
                    for tbl in tbls:
                        cols = data.get("columns",{}).get(f"{db}.{tbl}",[])
                        if isinstance(cols, str): cols = [c for c in cols.split(",") if c.strip()]
                        cols_html = " ".join(f'<span class="col-chip">{_he(str(c))}</span>' for c in cols)
                        schema_html += f'<li class="tbl-node"> {_he(str(tbl))} {cols_html}</li>'
                    schema_html += "</ul>"
                schema_html += "</li>"
            schema_html += "</ul>"
        else:
            schema_html = '<p class="text-muted">No schema extracted.</p>'

        #  Dump tables 
        dump_html = ""
        for tk, rows in (data.get("dump") or {}).items():
            if not rows: continue
            if isinstance(rows, list) and rows and isinstance(rows[0], dict):
                cols = list(rows[0].keys())
                hdrs = "".join(f"<th>{_he(str(c))}</th>" for c in cols)
                body = "".join(
                    "<tr>" + "".join(f"<td>{_he(str(row.get(c,'')))}</td>" for c in cols) + "</tr>"
                    for row in rows)
                dump_html += f"""
                <div class="mb-4">
                  <h6 class="fw-bold text-success"> {_he(str(tk))} ({len(rows)} rows)</h6>
                  <div class="table-responsive">
                    <table class="table table-sm table-hover table-dark dump-table">
                      <thead><tr>{hdrs}</tr></thead>
                      <tbody>{body}</tbody>
                    </table>
                  </div>
                </div>"""
        if not dump_html:
            dump_html = '<p class="text-muted">No data extracted.</p>'

        #  Sensitive data section 
        sens_html = ""
        if sensitive_summary and "No sensitive" not in sensitive_summary:
            sens_html = f"""
            <div class="alert alert-danger border-danger mt-3" role="alert">
              <h6 class="alert-heading"> Sensitive Data Detected</h6>
              <pre class="mb-0" style="font-size:.8rem">{sensitive_summary}</pre>
            </div>"""

        #  Remediation 
        rem_html = ""
        if dbms in ("MySQL","MariaDB"):
            rem_html = """<pre class="lang-php">// VULNERABLE:
$q = "SELECT * FROM users WHERE id = " . $_GET['id'];

// FIXED (PDO prepared statement):
$stmt = $pdo->prepare("SELECT * FROM users WHERE id = ?");
$stmt->execute([$_GET['id']]);
$rows = $stmt->fetchAll();</pre>"""
        elif dbms == "PostgreSQL":
            rem_html = """<pre class="lang-python"># VULNERABLE:
cur.execute(f"SELECT * FROM users WHERE id = {request.args['id']}")

# FIXED (parameterised):
cur.execute("SELECT * FROM users WHERE id = %s", (request.args['id'],))</pre>"""
        elif dbms == "MSSQL":
            rem_html = """<pre class="lang-csharp">// VULNERABLE:
string q = "SELECT * FROM Users WHERE Id = " + id;

// FIXED (SqlParameter):
var cmd = new SqlCommand("SELECT * FROM Users WHERE Id = @id", conn);
cmd.Parameters.AddWithValue("@id", id);</pre>"""
        if not rem_html:
            rem_html = """<pre>Use parameterised queries / prepared statements in your DB driver.
Never concatenate user input directly into SQL strings.</pre>"""

        #  JSON evidence (embedded) 
        evidence_json = json.dumps(
            {"vulnerabilities": vulns, "extracted_data": data},
            indent=2, default=str)

        # Pre-compute nested f-strings (Python <3.12 can't nest same-delimiter f-strings)
        if vulns:
            _findings_table_html = (
                "\n      <div class=\"table-responsive\">\n"
                "        <table class=\"table table-hover table-dark table-sm align-middle\" id=\"findingsTable\">\n"
                "          <thead><tr>\n"
                "            <th>Parameter</th><th>Technique</th><th>CVSS</th>\n"
                "            <th>DBMS</th><th>Confidence</th><th>Payload</th>\n"
                "            <th>CVSS Vector</th><th>Timestamp</th>\n"
                "          </tr></thead>\n"
                f"          <tbody>{rows_html}</tbody>\n"
                "        </table>\n"
                "      </div>"
            )
            _chart_js = (
                f"const tCtx = document.getElementById('techChart').getContext('2d');\n"
                f"  new Chart(tCtx, {{\n"
                f"    type: 'doughnut',\n"
                f"    data: {{ labels: {chart_labels}, datasets: [{{\n"
                f"      data: {chart_data}, backgroundColor: {chart_colors}, borderWidth: 2,\n"
                f"      borderColor: '#0f172a'\n"
                f"    }}] }},\n"
                f"    options: {{ responsive:true, plugins: {{ legend: {{\n"
                f"      position:'right', labels: {{ color:'#94a3b8', font:{{size:12}} }}\n"
                f"    }} }} }}\n"
                f"  }});\n"
                f"  const sCtx = document.getElementById('sevChart').getContext('2d');\n"
                f"  new Chart(sCtx, {{\n"
                f"    type: 'bar',\n"
                f"    data: {{ labels: {sev_labels}, datasets: [{{\n"
                f"      data: {sev_data}, backgroundColor: {sev_colors_js}, borderRadius:6\n"
                f"    }}] }},\n"
                f"    options: {{ responsive:true, plugins: {{ legend: {{ display:false }} }},\n"
                f"      scales: {{ y: {{ ticks: {{ color:'#64748b' }}, grid:{{ color:'#1e293b' }} }},\n"
                f"                 x: {{ ticks: {{ color:'#94a3b8' }}, grid:{{ display:false }} }} }} }}\n"
                f"  }});"
            )
        else:
            _findings_table_html = '<p class="text-muted">No vulnerabilities found.</p>'
            _chart_js = ''

        return f"""<!DOCTYPE html>
<html lang="en" data-bs-theme="dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>SQLReaper v19  Security Report</title>
  <link rel="stylesheet"
        href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"
        integrity="sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH"
        crossorigin="anonymous">
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.2/dist/chart.umd.min.js"
          crossorigin="anonymous"></script>
  <style>
    body   {{ background:#0f172a; font-family:'Segoe UI',system-ui,sans-serif }}
    .hero  {{ background:linear-gradient(135deg,#0f172a 0%,#1e3a5f 50%,#0f172a 100%);
              border-bottom:1px solid #334155; padding:1.5rem 2rem }}
    .hero h1 {{ font-size:1.8rem; font-weight:800; color:#38bdf8 }}
    .hero .sub {{ color:#64748b; font-size:.85rem }}
    .metric-card {{ background:#1e293b; border:1px solid #334155; border-radius:10px;
                    padding:1.2rem; text-align:center }}
    .metric-val  {{ font-size:2.4rem; font-weight:800; color:#38bdf8 }}
    .metric-lbl  {{ font-size:.68rem; text-transform:uppercase; color:#64748b;
                    letter-spacing:.08em }}
    .param  {{ color:#38bdf8; font-size:.85rem }}
    .payload{{ color:#f472b6; font-size:.78rem; font-family:monospace }}
    .badge  {{ font-weight:700; font-size:.68rem }}
    .schema-tree, .schema-tree ul {{ list-style:none; padding-left:1.2rem }}
    .db-node {{ padding:.3rem .2rem; color:#60a5fa; font-weight:700 }}
    .tbl-node{{ padding:.15rem .2rem; color:#94a3b8 }}
    .col-chip{{ display:inline-block; background:#1e3a5f; border-radius:3px;
                font-size:.65rem; padding:.1rem .3rem; margin:.1rem;
                color:#94a3b8; font-family:monospace }}
    .dump-table td, .dump-table th {{ font-size:.75rem; padding:.3rem .5rem }}
    pre {{ background:#0d1929; border:1px solid #334155; border-radius:6px;
           padding:1rem; font-size:.75rem; overflow:auto; max-height:350px;
           color:#94a3b8 }}
    .lang-php, .lang-python, .lang-csharp {{ color:#86efac }}
    th {{ background:#0d1929 !important }}
    .chart-box {{ background:#1e293b; border:1px solid #334155; border-radius:10px;
                  padding:1rem }}
  </style>
</head>
<body>
  <!-- HERO ----------------------------------------------------------------->
  <div class="hero">
    <h1> SQLReaper v19  Security Report</h1>
    <div class="sub">
      {now_str} &nbsp;&nbsp; <strong>Target:</strong> {target}
      &nbsp;&nbsp; <strong>DBMS:</strong> {dbms}
      &nbsp;&nbsp; <strong>WAF:</strong> {waf}
      &nbsp;&nbsp; <strong>Requests:</strong> {reqs:,}
    </div>
  </div>

  <div class="container-fluid px-4 py-4">

    <!-- METRICS ------------------------------------------------------------->
    <div class="row g-3 mb-4">
      <div class="col-6 col-md-3">
        <div class="metric-card">
          <div class="metric-val" style="color:{'#ef4444' if n_vulns>0 else '#10b981'}">{n_vulns}</div>
          <div class="metric-lbl">Vulnerabilities</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="metric-card">
          <div class="metric-val" style="color:{self._SEVERITY_COLORS.get(max_sev,'#6b7280')}">{max_cvss}</div>
          <div class="metric-lbl">Highest CVSS  {max_sev}</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="metric-card">
          <div class="metric-val">{len(techniques_used)}</div>
          <div class="metric-lbl">Techniques Used</div>
        </div>
      </div>
      <div class="col-6 col-md-3">
        <div class="metric-card">
          <div class="metric-val">{reqs:,}</div>
          <div class="metric-lbl">HTTP Requests</div>
        </div>
      </div>
    </div>

    <!-- CHARTS -------------------------------------------------------------->
    {'<div class="row g-3 mb-4">' if vulns else ''}
      {'<div class="col-md-5"><div class="chart-box"><h6 class="text-muted mb-3">Technique Distribution</h6><canvas id="techChart" height="200"></canvas></div></div>' if vulns else ''}
      {'<div class="col-md-7"><div class="chart-box"><h6 class="text-muted mb-3">CVSS Severity Breakdown</h6><canvas id="sevChart" height="200"></canvas></div></div>' if vulns else ''}
    {'</div>' if vulns else ''}

    <!-- FINDINGS TABLE ----------------------------------------------------->
    <div class="mb-5">
      <h5 class="text-secondary fw-bold mb-3"> Findings ({n_vulns})</h5>
      {_findings_table_html}
    </div>

    <!-- SCHEMA ------------------------------------------------------------->
    <div class="mb-5">
      <h5 class="text-secondary fw-bold mb-3"> Database Schema</h5>
      {schema_html}
    </div>

    <!-- EXTRACTED DATA ---------------------------------------------------->
    <div class="mb-5">
      <h5 class="text-secondary fw-bold mb-3"> Extracted Data</h5>
      {dump_html}
      {sens_html}
    </div>

    <!-- REMEDIATION -------------------------------------------------------->
    <div class="mb-5">
      <h5 class="text-secondary fw-bold mb-3"> Remediation ({dbms})</h5>
      <p class="text-muted small">Use parameterised queries. Never concatenate user input into SQL.</p>
      {rem_html}
    </div>

    <!-- RAW JSON ------------------------------------------------------------>
    <div class="mb-5">
      <h5 class="text-secondary fw-bold mb-2"> Raw Evidence</h5>
      <button class="btn btn-sm btn-outline-secondary mb-2"
              onclick="document.getElementById('rawJson').classList.toggle('d-none')">
        Toggle JSON
      </button>
      <pre id="rawJson" class="d-none">{evidence_json}</pre>
    </div>

  </div><!-- /container -->

  <script>
  {'// Technique chart' if vulns else ''}
  {_chart_js}
  </script>
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"
          crossorigin="anonymous"></script>
</body>
</html>"""

    def write(self, vulns: List[Dict], session: "ScanSession",
              sensitive_summary: str = "",
              path: Optional[str] = None) -> Path:
        self.output_dir.mkdir(parents=True, exist_ok=True)
        out = Path(path) if path else (
            self.output_dir / f"sqlreaper_{session.session_id}.html")
        html = self.generate(vulns, session, sensitive_summary)
        tmp  = str(out) + ".tmp"
        # TODO: Replace with aiofiles for async I/O
        with open(tmp, "w", encoding="utf-8") as f:
            f.write(html)
        os.replace(tmp, out)
        LOG.info(f"HTML v2 report  {out}")
        return out


# 
# 6.  NUCLEI TEMPLATE GENERATOR
#     Generates a Nuclei YAML template from a confirmed injection finding so
#     the vulnerability can be re-verified in CI pipelines with a single command.
# 

class NucleiTemplateGenerator:
    """
    Generates a Nuclei YAML template for a confirmed SQL injection.

    The generated template:
      - Sends the exact confirmed request (method, URL, headers, body)
      - Injects the confirmed payload into the vulnerable parameter
      - Matches on the confirmed indicator (error string / timing / UNION sentinel)
      - Tagged: sqli, injection, <technique>, <dbms>, sqlreaper

    Usage
    -----
        gen = NucleiTemplateGenerator()
        yaml_str = gen.generate(method="GET", url="http://t.com/page?id=1",
                                param="id", payload="' AND 1=1-- -",
                                technique="E", dbms="MySQL",
                                error_pattern="mysql_fetch")
        Path("sqli_id.yaml").write_text(yaml_str)
        # nuclei -t sqli_id.yaml -u http://t.com
    """

    def generate(
        self,
        method:  str,
        url:     str,
        param:   str,
        payload: str,
        technique: str,
        dbms:    str,
        error_pattern:  str = "",
        time_sec: float = 5.0,
        union_sentinel: str = "SQRPR7731UNIQ",
        data: Optional[str] = None,
        headers: Optional[Dict[str, str]] = None,
        data_fmt: str = "form",
    ) -> str:
        """Return a Nuclei YAML template string."""
        parsed  = urlparse(url)
        base_url = f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
        # FIX: Preserve all values for multi-valued parameters
        qs_orig  = parse_qs(parsed.query)
        ts       = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        tid      = re.sub(r"[^\w]", "-", f"sqli-{param}-{technique}").lower()
        severity = "critical" if technique in ("S","O") else (
                   "high"     if technique in ("E","U","B") else
                   "medium"   if technique == "T" else "info")

        # Build injected query string / body
        if method.upper() in ("GET","HEAD","DELETE") or not data:
            inj_qs = dict(qs_orig)
            inj_qs[param] = ["{{sqli_payload}}"]
            path_and_qs = parsed.path + "?" + urlencode(inj_qs, doseq=True)
            raw_path = path_and_qs
            raw_body = ""
        elif data_fmt == "json":
            try:
                body_d = json.loads(data)
                body_d[param] = "{{sqli_payload}}"
                raw_body = json.dumps(body_d)
            except Exception:
                raw_body = data or ""
            raw_path = parsed.path
        else:
            parts = [p for p in (data or "").split("&") if not p.startswith(param+"=")]
            parts.append(f"{quote(param)}={{{{sqli_payload}}}}")
            raw_body = "&".join(parts)
            raw_path = parsed.path

        # Matcher section
        if technique == "E" and error_pattern:
            matcher = f"""\
  matchers:
    - type: regex
      regex:
        - '{error_pattern}'
      condition: and"""
        elif technique == "T":
            matcher = f"""\
  matchers:
    - type: dsl
      dsl:
        - 'duration >= {int(time_sec * 0.8)}'"""
        elif technique == "U":
            matcher = f"""\
  matchers:
    - type: word
      words:
        - '{union_sentinel}'"""
        else:
            matcher = """\
  matchers:
    - type: status
      status:
        - 200
    - type: regex
      regex:
        - 'SQL|syntax|mysql|postgres|oracle|sqlite|microsoft'
      negative: true
      condition: and"""

        # Extra headers section
        header_lines = ""
        for k, v in (headers or {}).items():
            if k.lower() not in ("host","content-length"):
                header_lines += f"\n      {k}: '{v}'"

        body_section = (f"\n      body: |\n        {raw_body}" if raw_body else "")
        content_type = ""
        if raw_body:
            ct = ("application/json" if data_fmt == "json"
                  else "application/x-www-form-urlencoded")
            content_type = f"\n      Content-Type: '{ct}'"

        _nuclei_payload_escaped = payload.replace('"', '\\"')
        return f"""\
id: {tid}

info:
  name: "SQL Injection  {param} ({technique}/{dbms})"
  author: SQLReaper-v19
  severity: {severity}
  description: |
    SQL injection confirmed in parameter '{param}' via {technique} technique
    against {dbms}. Payload: {payload[:60]}
  tags: sqli,injection,{technique.lower()},{dbms.lower()},sqlreaper,auto-generated
  metadata:
    dbms: {dbms}
    technique: {technique}
    confirmed-date: {ts}
  reference:
    - https://owasp.org/www-community/attacks/SQL_Injection

variables:
  sqli_payload: "{_nuclei_payload_escaped}"

http:
  - method: {method.upper()}
    path:
      - "{{{{BaseURL}}}}{raw_path}"
    headers:{header_lines}{content_type}
{body_section}
{matcher}
"""

    def save(self, output_dir: str, finding_id: str, **kwargs) -> Path:
        """Save YAML template and return path."""
        d = Path(output_dir) / "nuclei"
        d.mkdir(parents=True, exist_ok=True)
        path = d / f"{finding_id}.yaml"
        path.write_text(self.generate(**kwargs), encoding="utf-8")
        LOG.info(f"Nuclei template  {path}")
        return path


# 
# 7.  BURP SUITE REPEATER EXPORTER
#     Exports the exact confirmed HTTP request in Burp Suite XML format.
#     Paste into Burp Repeater (Repeater  Import XML) to instantly reproduce.
# 

class BurpRepeaterExporter:
    """
    Generates a Burp Suite XML item importable into Burp Repeater/Intruder.

    Format: Burp Suite's items.xml (Base64-encoded request/response).
    """

    def generate(
        self,
        method:  str,
        url:     str,
        param:   str,
        payload: str,
        headers: Optional[Dict[str, str]] = None,
        data:    Optional[str] = None,
        data_fmt: str = "form",
    ) -> str:
        """Return Burp XML as a string."""
        parsed = urlparse(url)
        port   = parsed.port or (443 if parsed.scheme == "https" else 80)
        https  = (parsed.scheme == "https")

        # Build injected request
        # FIX: Preserve all values for multi-valued parameters
        qs = parse_qs(parsed.query)
        if method.upper() in ("GET","HEAD","DELETE") or not data:
            qs[param] = payload
            path  = parsed.path + "?" + urlencode(qs)
            body  = ""
            ctype = ""
        elif data_fmt == "json":
            try:
                body_d = json.loads(data)
                body_d[param] = payload
                body  = json.dumps(body_d)
            except Exception:
                body  = data or ""
            path  = parsed.path
            ctype = "application/json"
        else:
            parts = [p for p in (data or "").split("&") if not p.startswith(param+"=")]
            parts.append(f"{quote(param)}={quote(payload)}")
            body  = "&".join(parts)
            path  = parsed.path
            ctype = "application/x-www-form-urlencoded"

        # Build raw HTTP request bytes
        hdrs = dict(headers or {})
        hdrs.setdefault("Host", parsed.netloc)
        hdrs.setdefault("User-Agent", USER_AGENTS[0])
        hdrs.setdefault("Accept", "*/*")
        hdrs.setdefault("Connection", "close")
        if ctype:
            hdrs["Content-Type"]   = ctype
        if body:
            hdrs["Content-Length"] = str(len(body.encode("utf-8")))

        req_lines = [f"{method.upper()} {path} HTTP/1.1"]
        for k, v in hdrs.items():
            req_lines.append(f"{k}: {v}")
        req_lines.append("")
        if body:
            req_lines.append(body)

        raw_req    = "\r\n".join(req_lines).encode("utf-8", errors="replace")
        # BUG-FIX-3: Safe decode operation
        req_b64 = ""
        try:
            req_b64 = base64.b64encode(raw_req).decode()
        except (UnicodeDecodeError, AttributeError, TypeError):
            req_b64 = "" # Fallback

        return (
            '<?xml version="1.0"?>\n'
            '<!DOCTYPE items [\n'
            '<!ELEMENT items (item*)>\n'
            '<!ELEMENT item (time,url,host,port,protocol,method,path,extension,'
            'request,status,responselength,mimetype,response,comment)>\n'
            '<!ELEMENT time (#PCDATA)>\n'
            '<!ELEMENT url (#PCDATA)>\n'
            '<!ELEMENT host (#PCDATA)>\n'
            '<!ELEMENT port (#PCDATA)>\n'
            '<!ELEMENT protocol (#PCDATA)>\n'
            '<!ELEMENT method (#PCDATA)>\n'
            '<!ELEMENT path (#PCDATA)>\n'
            '<!ELEMENT extension (#PCDATA)>\n'
            '<!ELEMENT request (#PCDATA)>\n'
            '<!ELEMENT status (#PCDATA)>\n'
            '<!ELEMENT responselength (#PCDATA)>\n'
            '<!ELEMENT mimetype (#PCDATA)>\n'
            '<!ELEMENT response (#PCDATA)>\n'
            '<!ELEMENT comment (#PCDATA)>\n'
            ']>\n'
            '<items burpVersion="2024.1" exportTime="'
            f'{datetime.now(timezone.utc).strftime("%a %b %d %H:%M:%S UTC %Y")}'
            '">\n'
            '  <item>\n'
            f'    <time>{datetime.now(timezone.utc).isoformat()}</time>\n'
            f'    <url>{url}</url>\n'
            f'    <host ip="">{parsed.netloc}</host>\n'
            f'    <port>{port}</port>\n'
            f'    <protocol>{"HTTPS" if https else "HTTP"}</protocol>\n'
            f'    <method>{method.upper()}</method>\n'
            f'    <path>{path}</path>\n'
            '    <extension></extension>\n'
            f'    <request base64="true">{req_b64}</request>\n'
            '    <status>0</status>\n'
            '    <responselength>0</responselength>\n'
            '    <mimetype></mimetype>\n'
            '    <response base64="true"></response>\n'
            f'    <comment>SQLReaper v19  param={param} technique confirmed</comment>\n'
            '  </item>\n'
            '</items>\n'
        )

    def save(self, output_dir: str, finding_id: str, **kwargs) -> Path:
        d = Path(output_dir) / "burp"
        d.mkdir(parents=True, exist_ok=True)
        path = d / f"{finding_id}_burp.xml"
        path.write_text(self.generate(**kwargs), encoding="utf-8")
        LOG.info(f"Burp Repeater XML  {path}")
        return path


# 
# 8.  RATE LIMIT DETECTOR
#     Detects when the server starts rate-limiting (429, Retry-After, WAF
#     block cascades) and automatically reduces the scan rate via the
#     TokenBucketRateLimiter.  Integrates with HTTPEngine via a callback.
# 

class RateLimitDetector:
    """
    Observes response codes and headers to detect rate-limiting, then
    signals the TokenBucketRateLimiter to back off.

    Triggers
    --------
    - HTTP 429 (Too Many Requests)  hard rate limit
    - HTTP 503 with Retry-After header  service overload
    - Cloudflare 1015/1020 error codes in body  WAF challenge
    - Consecutive 403s after normal 200s  WAF starting to block

    Actions
    -------
    - Immediately halves the token-bucket rate
    - Optionally sleeps for the Retry-After duration
    - Logs a prominent warning
    - After N consecutive clean responses, restores original rate
    """

    RECOVERY_AFTER   = 20   # clean responses needed before rate recovery
    BACKOFF_FACTOR   = 0.5  # multiply rate by this on each trigger
    MIN_RATE_RPS     = 0.2  # never go below 0.2 req/s

    def __init__(self, limiter: Optional[TokenBucketRateLimiter] = None):
        self._limiter        = limiter
        self._original_rate  = limiter._rate if limiter else 5.0
        self._clean_streak   = 0
        self._total_triggers = 0
        self._current_rate   = self._original_rate

    async def observe(self, fp: "ResponseFingerprint", method: str, url: str):
        """Called after each HTTP response. Adjusts rate if needed."""
        status = getattr(fp, "status_code", 500)
        hdrs   = {k.lower(): v for k, v in fp.headers.items()}
        body   = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")[:500]

        triggered = False
        retry_after = 0

        if status == 429:
            triggered = True
            try:
                retry_after = int(hdrs.get("retry-after", "0"))
            except ValueError:
                retry_after = 10

        elif status == 503 and "retry-after" in hdrs:
            triggered = True
            try:
                retry_after = int(hdrs["retry-after"])
            except ValueError:
                retry_after = 5

        elif (re.search(r"1015|1020|cf-ray|cloudflare", body, re.I) and
              status == 403):
            triggered = True
            retry_after = 15

        if triggered:
            self._total_triggers += 1
            self._clean_streak    = 0
            new_rate = max(self.MIN_RATE_RPS,
                           self._current_rate * self.BACKOFF_FACTOR)
            LOG.warning(
                f" Rate limit detected (HTTP {status})  "
                f"reducing rate {self._current_rate:.2f}  {new_rate:.2f} req/s")
            self._current_rate = new_rate
            if self._limiter:
                self._limiter.update_rate(new_rate)
            if retry_after > 0:
                LOG.warning(f"  Waiting {retry_after}s (Retry-After)")
                await asyncio.sleep(retry_after)
        else:
            # Count clean responses toward rate recovery
            if status < 400:
                self._clean_streak += 1
                if (self._clean_streak >= self.RECOVERY_AFTER and
                        self._current_rate < self._original_rate):
                    recovered = min(self._original_rate,
                                    self._current_rate / self.BACKOFF_FACTOR)
                    LOG.info(f"Rate recovery: {self._current_rate:.2f}  {recovered:.2f} req/s")
                    self._current_rate = recovered
                    if self._limiter:
                        self._limiter.update_rate(recovered)
                    self._clean_streak = 0

    @property
    def stats(self) -> Dict[str, Any]:
        return {
            "total_triggers":  self._total_triggers,
            "current_rate":    round(self._current_rate, 3),
            "original_rate":   round(self._original_rate, 3),
            "clean_streak":    self._clean_streak,
        }


# 
# 9.  ADAPTIVE BASELINE MANAGER
#     Maintains a per-endpoint adaptive baseline that detects and compensates
#     for session drift (e.g. countdown timers, changing CSRF tokens, server
#     rotation) without false-positiving on legitimate content variation.
# 

class AdaptiveBaselineManager:
    """
    Manages a rolling adaptive baseline per (method, url, param) key.

    Unlike the static `build_baseline()` which snapshots N responses once,
    this class continuously updates the baseline using EWMA so it tracks
    natural drift in the application's response characteristics.

    Key features:
      - EWMA update on every clean (non-injected) request
      - Drift guard: alerts when baseline shifts faster than expected
        (which may indicate the scanner is inadvertently changing server state)
      - Per-parameter history for post-scan variance analysis
      - Thread-safe for concurrent param scanning

    Usage
    -----
        mgr = AdaptiveBaselineManager()
        baseline = await mgr.get_or_build(engine, config, method, url,
                                           data, fmt, param, original, chain)
        #  scan 
        await mgr.update(method, url, param, fresh_fp)
    """

    ALPHA = 0.15   # EWMA smoothing  higher = faster adaptation
    MAX_DRIFT_RATIO = 0.30   # alert if length drifts > 30% in one step

    def __init__(self):
        self._baselines: Dict[str, Dict] = {}
        self._drift_alerts: List[str]    = []

    def _key(self, method: str, url: str, param: str) -> str:
        raw = f"{method}:{url}:{param}"
        return hashlib.md5(raw.encode()).hexdigest()[:16]

    async def get_or_build(
        self,
        engine: "HTTPEngine",
        config: "Config",
        method: str, url: str,
        data: Optional[str], data_fmt: str,
        param: str, original: str,
        tamper_chain: List[str],
        n_samples: int = 3,
    ) -> Dict:
        """Return cached baseline or build a new one."""
        key = self._key(method, url, param)
        if key not in self._baselines:
            bl = await asyncio.wait_for(build_baseline(engine, config, method, url, data,
                                       data_fmt, param, original,
                                       tamper_chain, n_samples=n_samples), timeout=300)
            self._baselines[key] = bl
        return self._baselines[key]

    def update(self, method: str, url: str, param: str,
               fp: "ResponseFingerprint"):
        """Feed a fresh clean response into the EWMA baseline."""
        key = self._key(method, url, param)
        if key not in self._baselines:
            return  # Not yet initialised
        bl    = self._baselines[key]
        alpha = self.ALPHA

        old_len = bl["mean_length"]
        new_len = float(fp.content_length)

        # Drift guard
        if old_len > 0:
            ratio = abs(new_len - old_len) / old_len
            if ratio > self.MAX_DRIFT_RATIO:
                msg = (f"Baseline drift detected for {param!r}: "
                       f"length {old_len:.0f}{new_len:.0f} ({ratio:.0%})")
                LOG.debug(msg)
                self._drift_alerts.append(msg)

        # EWMA update
        bl["mean_length"] = (1-alpha)*bl["mean_length"] + alpha*new_len
        bl["mean_words"] = (1-alpha)*bl["mean_words"] + alpha*getattr(fp, "body_words", 0)
        bl["mean_timing"] = (1-alpha)*bl["mean_timing"] + alpha*fp.elapsed_ms

    @property
    def drift_alerts(self) -> List[str]:
        return list(self._drift_alerts)

    @property
    def tracked_params(self) -> int:
        return len(self._baselines)


# 
# 10.  COMPREHENSIVE PoC GENERATOR v2
#      Extends the existing PoCGenerator to also emit Nuclei YAML and
#      Burp Suite XML alongside the curl/Python scripts.
# 

class ComprehensivePoCGeneratorV2:
    """
    All-in-one PoC generator:
      - curl one-liner  (.sh)
      - Python requests (.py)
      - Nuclei template (.yaml)
      - Burp Suite XML  (_burp.xml)

    Wraps the existing PoCGenerator, NucleiTemplateGenerator,
    and BurpRepeaterExporter into a single call.
    """

    def __init__(self):
        self._poc    = PoCGenerator()
        self._nuclei = NucleiTemplateGenerator()
        self._burp   = BurpRepeaterExporter()

    def generate_all(
        self,
        method:    str,
        url:       str,
        param:     str,
        payload:   str,
        technique: str,
        dbms:      str,
        data:      Optional[str]       = None,
        headers:   Optional[Dict[str,str]] = None,
        data_fmt:  str                 = "form",
        error_pattern: str             = "",
        time_sec:  float               = 5.0,
    ) -> Dict[str, str]:
        """
        Return dict of {format_name: content_string}.
        Keys: "curl", "python", "nuclei", "burp"
        """
        return {
            "curl": self._poc.generate_curl(
                method, url, param, payload, data, headers, data_fmt),
            "python": self._poc.generate_python(
                method, url, param, payload, data, headers, data_fmt),
            "nuclei": self._nuclei.generate(
                method=method, url=url, param=param, payload=payload,
                technique=technique, dbms=dbms, data=data,
                headers=headers, data_fmt=data_fmt,
                error_pattern=error_pattern, time_sec=time_sec),
            "burp": self._burp.generate(
                method=method, url=url, param=param, payload=payload,
                headers=headers, data=data, data_fmt=data_fmt),
        }

    def save_all(
        self,
        output_dir: str,
        finding_id: str,
        **kwargs,
    ) -> Dict[str, Path]:
        """Save all PoC formats and return {format: path}."""
        content = self.generate_all(**kwargs)
        d = Path(output_dir) / "poc"
        d.mkdir(parents=True, exist_ok=True)
        saved: Dict[str, Path] = {}

        for ext, key in [(".sh", "curl"), (".py", "python"),
                         (".yaml", "nuclei"), ("_burp.xml", "burp")]:
            p = d / f"{finding_id}{ext}"
            p.write_text(content[key], encoding="utf-8")
            if ext == ".sh":
                try: os.chmod(p, 0o755)
                except Exception: pass
            saved[key] = p
            LOG.debug(f"PoC saved: {p}")

        LOG.info(f"All PoC formats saved  {d}/")
        return saved


