    # Generic: IS NULL / IS NOT NULL
    (" AND NULL IS NULL", " AND NULL IS NOT NULL", "null_is_null"),
    # Integer overflow normalization
    (" AND 2147483647+1=-2147483648", " AND 2147483647+1=0", "int_overflow"),
    # Float comparison
