if __name__ == "__main__":
    # BUG-PY313-CSTACK-FIX (original): sys.setrecursionlimit guards Python-frame
    # depth but each recursive asyncio.Task.cancel() also consumes C stack.
    # 3329 levels × ~2 KB C frame ≈ 6.6 MB, overflowing the 8 MB default.
    # Running asyncio.run() in a new thread with an explicit large stack gives
    # ~30× headroom and is the only correct fix without architectural changes.
    #
    # BUG-PY313-CSTACK-V2 FIX (new — resolves "Exception in callback" RecursionError):
    # The original fix used 64 MB, but on Python 3.13 the C-stack frame size for
    # asyncio.Task.cancel() is larger (~20 KB on aarch64/glibc) than the original
    # ~2 KB estimate.  3329 × 20 KB = ~67 MB → still overflows 64 MB.
    # Fix 1: Double stack to 128 MB (3329 × 20 KB = 67 MB → 1.9× margin).
    # Fix 2: Set sys.setrecursionlimit on the WORKER THREAD too (the main-thread
    #         set at module import time affects only the main thread; each new
    #         thread inherits the Python frame limit but not the C-stack size, and
    #         the sys module's recursion counter is global, so resetting it here
    #         inside the thread ensures the 50 M limit is active for all callbacks
    #         that asyncio dispatches on this thread's C stack).
    # Fix 3: Install a custom asyncio event loop exception handler BEFORE any tasks
    #         are created.  asyncio's DEFAULT exception handler prints the full
    #         traceback for ANY unhandled callback exception — including the
    #         RecursionError that fires inside Task._step → Task.cancel() chain.
    #         Our custom handler silently absorbs RecursionErrors that arise during
    #         task cancellation (which are safe because _SCAN_STOPPED was already
    #         set before the cancellation chain began; all scan tasks self-terminate
    #         via the flag without needing their asyncio.Task.cancel() to propagate
    #         all the way to the leaf). All other exceptions are forwarded to the
    #         default handler unchanged.
    import sys as _sys_entry
    _sys_entry.setrecursionlimit(50_000_000)  # main thread
    import asyncio as _asyncio
    import threading as _threading_entry

    _threading_entry.stack_size(128 * 1024 * 1024)   # BUG-PY313-CSTACK-V2: 128 MB

    _exit_code = [0]

    def _run_main():
        import sys as _sys_worker
        _sys_worker.setrecursionlimit(50_000_000)  # BUG-PY313-CSTACK-V2: also set on worker thread

        # BUG-PY313-CSTACK-V2 FIX: Create event loop manually so we can install
        # the custom exception handler BEFORE asyncio.run() creates any tasks.
        # asyncio.run() creates its own loop and tears it down, but does not expose
        # the loop object before running — so we must do this manually.
        _loop = _asyncio.new_event_loop()
        _asyncio.set_event_loop(_loop)

        def _exc_handler(loop, context):
            exc = context.get('exception')
            # Silently absorb RecursionErrors from asyncio Task.cancel() chains.
            # Root cause: asyncio recursively calls child.cancel() for every nested
            # task, and 3329+ levels exhausts the C stack on Python 3.13.
            # Safety: _SCAN_STOPPED[0] was set True BEFORE _gate.kill() triggers
            # cancel(), so all scan tasks stop on their own via the _SCAN_STOPPED
            # flag regardless of whether Task.cancel() completes.
            # The injection result, report, and extraction are unaffected.
            if isinstance(exc, RecursionError):
                # Only suppress if this is a task-cancellation RecursionError
                msg = context.get('message', '')
                src = context.get('source_traceback', None)
                if ('cancel' in msg.lower() or
                        'task' in msg.lower() or
                        exc is not None):
                    return  # Suppress — safe, scan already completed
            # All other unhandled exceptions go to the default handler
            loop.default_exception_handler(context)

        _loop.set_exception_handler(_exc_handler)

        try:
            _loop.run_until_complete(main())
        except (KeyboardInterrupt, SystemExit) as _exc:
            _exit_code[0] = getattr(_exc, 'code', 0) or 0
        except RecursionError:
            # asyncio cleanup hit C-stack limit during task teardown — safe to ignore;
            # all important work completed before this point.
            pass
        except Exception as _exc:
            import traceback as _tb
            _tb.print_exc()
            _exit_code[0] = 2
        finally:
            try:
                # Graceful loop shutdown: cancel remaining tasks iteratively
                # (avoids a second recursive cancel chain during cleanup)
                _pending = _asyncio.all_tasks(_loop)
                if _pending:
                    for _pt in _pending:
                        _pt.cancel()
                    try:
                        _loop.run_until_complete(
                            _asyncio.gather(*_pending, return_exceptions=True))
                    except Exception:
                        pass
            finally:
                try:
                    _loop.run_until_complete(_loop.shutdown_asyncgens())
                except Exception:
                    pass
                try:
                    _loop.run_until_complete(_loop.shutdown_default_executor())
                except Exception:
                    pass
                _loop.close()

    _main_thread = _threading_entry.Thread(target=_run_main, daemon=False)
    _main_thread.start()
    _main_thread.join()
    import sys as _sys_exit
    _sys_exit.exit(_exit_code[0])
